// Réessaie d'envoyer tout ce qui est resté en attente — appelée dès que le
// navigateur signale un retour de connexion, et par sécurité toutes les
// 20 secondes (le signal "en ligne" n'est pas toujours fiable sur mobile).
// Refus que renvoyer ne changera pas (sauf après une nouvelle clé) : on
// arrête d'insister toutes les 20 s, mais l'entrée reste visible dans le
// rapport de test avec sa raison, et le bouton « Renvoyer maintenant ».
var PERMANENT_QUEUE_ERRORS = ["not_your_order", "not_linked_to_order", "missing_fields", "forbidden", "invalid_doc", "invalid_id", "admin_only", "price_changed", "product_missing", "own_product", "out_of_stock", "payment_not_supported", "not_paid", "insufficient_balance", "bad_code", "not_allowed", "empty_order", "no_wallet_phone"];
var _queueFlushing = false;
function flushPendingSyncQueue(manual) {
  if (!FIREBASE_ENABLED || !state.pendingSyncQueue || state.pendingSyncQueue.length === 0) return;
  if (_queueFlushing) return;
  if (sessionHealth() !== "ok" && sessionHealth() !== "expiring" && state.profile && !manual) { ensureFreshSession(); return; }
  _queueFlushing = true;
  var flushDone = 0, flushTotal = 0, sessionRejected = false, ordersSent = false;
  function oneDone() { flushDone++; if (flushDone >= flushTotal) { _queueFlushing = false; save(); if (sessionRejected) noteSessionRejected(); if (ordersSent) setTimeout(function() { try { fetchMyOrderContacts(); } catch (e) {} }, 1500); } }
  // Volontairement PAS de vérification navigator.onLine ici non plus —
  // déjà peu fiable sur mobile (voir plus haut) ; chaque requête gère de
  // toute façon son propre échec sans rien casser si vraiment hors ligne.
  var queue = state.pendingSyncQueue.filter(function(e) { return manual || !e.blocked; });
  flushTotal = queue.length;
  if (!flushTotal) { _queueFlushing = false; return; }
  queue.forEach(function(entry) {
    var request;
    if (entry.collection === "orders" && entry.type !== "delete") {
      // "orders" ne peut plus être écrit directement depuis le
      // navigateur (voir le verrouillage de la base) — une commande
      // restée en attente doit repasser par order-write comme
      // n'importe quelle autre, sinon elle échouerait à coup sûr et
      // resterait bloquée dans cette file indéfiniment.
      request = fetch(supabaseConfig.url + "/functions/v1/order-write", {
        method: "POST",
        headers: authHeaders(),
        body: JSON.stringify({ docId: entry.id, data: entry.data, referralCode: currentReferralCode() })
      })
        .then(readServerJson)
        .then(function(res) { if (res.success) ordersSent = true; return { error: res.success ? null : (res.error || "order_write_failed"), detail: res.detail }; })
        .catch(function(err) { return { error: "network_error", detail: String((err && err.message) || err) }; });
    } else if (entry.collection === "notifications" && entry.type !== "delete") {
      // La base refuse l'écriture directe des notifications (verrouillage de
      // sécurité) : elles passent par la fonction serveur social-write.
      // Avant, elles restaient bloquées ici pour toujours — le vendeur ne
      // recevait jamais « nouvelle commande ».
      var nd = entry.data || {};
      request = secureSocialWrite({ operation: "create_notification", notification: nd }, null).then(function(res) {
        if (res && res.success && nd.read && state.profile && nd.userId === state.profile.id) secureSocialWrite({ operation: "mark_notifications_read", ids: [nd.id] }, null);
        if (res && res.success) return { error: null };
        if (res && res.fallback) return { error: res.error ? "network_error" : "session_required" };
        var e = (res && res.error) || "social_write_failed";
        // Refus définitif (destinataire supprimé, message vide...) : inutile d'insister.
        if (["unknown_user", "invalid_id", "invalid_message", "invalid_user", "broadcast_admin_only"].indexOf(e) !== -1) { pushDebugLog("info", "Notification abandonnée", nd.id + " — " + e); return { error: null }; }
        return { error: e, detail: res && res.detail };
      });
    } else if (["wallets", "earningsLedgers", "savedAddresses", "orderContacts"].indexOf(entry.collection) !== -1) {
      // Ces collections ne devraient plus jamais atterrir ici du tout
      // (tous leurs points d'entrée passent déjà par une fonction
      // dédiée) — mais si une entrée obsolète traînait encore d'avant
      // cette mise à jour, mieux vaut l'abandonner proprement que de
      // la retenter indéfiniment pour rien : elle échouerait de toute
      // façon contre la base désormais verrouillée.
      pushDebugLog("info", "Entrée en attente abandonnée (collection protégée)", entry.collection + " / " + entry.id);
      state.pendingSyncQueue = (state.pendingSyncQueue || []).filter(function(e) { return !(e.collection === entry.collection && e.id === entry.id); });
      save();
      return;
    } else if (SECURE_WRITE_COLLECTIONS.indexOf(entry.collection) !== -1) {
      request = secureWrite(entry.collection, entry.type === "delete" ? { operation: "delete", id: entry.id } : { operation: "save", doc: entry.data })
        .then(function(res) {
          if (res.notDeployed) {
            return entry.type === "delete"
              ? sb.from("app_data").delete().eq("collection", entry.collection).eq("id", entry.id)
              : sb.from("app_data").upsert({ collection: entry.collection, id: entry.id, data: entry.data, updated_at: new Date().toISOString() }, { onConflict: "collection,id" });
          }
          if (res.success && res.doc) applyServerDoc(entry.collection, res.doc);
          if (res.error === "session_required") return { error: "session_required" };
          // Un refus définitif (droits) retire aussi l'entrée de la file.
          return { error: (res.success || res.httpStatus === 403 || res.httpStatus === 401) ? null : (res.error || "secure_write_failed"), detail: res.detail };
        })
        .catch(function(err) { return { error: "network_error", detail: String((err && err.message) || err) }; });
    } else {
      request = entry.type === "delete"
        ? sb.from("app_data").delete().eq("collection", entry.collection).eq("id", entry.id)
        : sb.from("app_data").upsert({ collection: entry.collection, id: entry.id, data: entry.data, updated_at: new Date().toISOString() }, { onConflict: "collection,id" });
    }
    request.then(function(res) {
      if (!res.error) {
        state.pendingSyncQueue = (state.pendingSyncQueue || []).filter(function(e) { return !(e.collection === entry.collection && e.id === entry.id); });
        renderOrDefer();
      } else {
        var errTxt = typeof res.error === "string" ? res.error : (res.error && res.error.message) || "erreur";
        entry.attempts = (entry.attempts || 0) + 1;
        entry.lastError = errTxt + (res.detail ? " — " + String(res.detail).slice(0, 100) : "");
        entry.lastTriedAt = Date.now();
        if (errTxt === "session_required") sessionRejected = true;
        if (PERMANENT_QUEUE_ERRORS.indexOf(errTxt) !== -1) entry.blocked = true;
      }
    })
    .catch(function() {})
    .finally(oneDone);
  });
}
window.addEventListener("online", flushPendingSyncQueue);
setInterval(flushPendingSyncQueue, 20000);
// Remplace le "temps réel" pour les messages (qui ne peut plus lire la
// collection désormais protégée) — revérifie la conversation OUVERTE
// toutes les 8 secondes, jamais les autres.
setInterval(function() {
  if (state.chatOpen && state.currentConversationId) {
    fetchConversationMessages(state.currentConversationId);
  }
}, 8000);

function deleteRemoteDoc(collectionName, docId) {
  if (!FIREBASE_ENABLED) return; // mode local : localStorage s'en charge déjà via save()
  if (SECURE_WRITE_COLLECTIONS.indexOf(collectionName) !== -1) {
    secureWrite(collectionName, { operation: "delete", id: docId }).then(function(res) {
      if (res.notDeployed) return deleteRemoteDocDirect(collectionName, docId);
      if (!res.success && (res.error === "session_required" || (res.httpStatus !== 403 && res.httpStatus !== 401))) queuePendingSync(collectionName, { id: docId }, "delete");
    }).catch(function() { queuePendingSync(collectionName, { id: docId }, "delete"); });
    return;
  }
  deleteRemoteDocDirect(collectionName, docId);
}
function deleteRemoteDocDirect(collectionName, docId) {
  if (!FIREBASE_ENABLED) return;
  // Même filet de sécurité que saveDoc : hors connexion, ou en cas
  // d'échec, la suppression rejoint la file d'attente et sera refaite
  // dès que la connexion revient — sans ça, une fiche produit pouvait
  // rester dans la base alors que ses photos avaient déjà disparu.
  // On tente toujours d'abord (voir saveDoc pour pourquoi on ne se fie
  // plus à navigator.onLine).
  sb.from("app_data").delete().eq("collection", collectionName).eq("id", docId)
    .then(function(res) {
      if (res.error) {
        console.error("Erreur de suppression Supabase (" + collectionName + ") :", res.error);
        queuePendingSync(collectionName, { id: docId }, "delete");
      }
    })
    .catch(function(err) {
      console.error("Erreur réseau lors de la suppression (" + collectionName + ") :", err);
      queuePendingSync(collectionName, { id: docId }, "delete");
    });
}

// Envoie un fichier (photo/vidéo). En mode local (Firebase non configuré),
// le fichier est simplement encodé en base64 et gardé sur cet appareil —
// exactement comme avant, pratique pour tester sans rien configurer.
// Une fois Firebase configuré, bascule automatiquement vers Storage.
// Supprime pour de vrai le(s) fichier(s) correspondant à une ou plusieurs
// URL publiques Supabase Storage — sans ça, supprimer un produit ne
// retirait que sa fiche, jamais les photos/vidéo réellement stockées.
// Supprime des photos ET leurs vignettes.
function deleteStorageFilesWithThumbs(urls) {
  var all = [];
  (urls || []).forEach(function(u) { all.push(u); var tU = snsThumb(u); if (tU !== u) all.push(tU); });
  deleteStorageFiles(all);
}
function deleteStorageFiles(urls) {
  if (!FIREBASE_ENABLED || !urls || urls.length === 0) return;
  var marker = "/storage/v1/object/public/photo/";
  var paths = urls.filter(function(u) { return typeof u === "string" && u.indexOf(marker) !== -1; })
    .map(function(u) { return decodeURIComponent(u.split(marker)[1].split("?")[0]); });
  if (paths.length === 0) {
    console.warn("deleteStorageFiles : aucune URL Supabase reconnue parmi", urls);
    return;
  }
  console.log("Suppression Supabase Storage demandée pour :", JSON.stringify(paths));
  sb.storage.from("photo").remove(paths).then(function(res) {
    if (res.error) {
      console.error("Erreur de suppression Supabase Storage :", res.error);
    } else if (!res.data || res.data.length === 0) {
      console.warn("⚠️ La suppression a répondu sans erreur mais AUCUN fichier n'a réellement été supprimé — le chemin ne correspond probablement à aucun objet existant :", JSON.stringify(paths));
    } else {
      console.log("Suppression Supabase Storage réussie, fichiers réellement supprimés :", JSON.stringify(res.data.map(function(d) { return d.name; })));
    }
  });
}

// Redimensionne et recompresse une image côté navigateur avant envoi,
// en réduisant progressivement la qualité (puis la taille si besoin)
// jusqu'à atteindre la cible visée — pas un simple réglage fixe qui
// pourrait encore dépasser sur une photo complexe.
var IMAGE_TARGET_BYTES = 100 * 1024; // 100 Ko visé
function compressImage(file, callback) {
  if (!file.type || file.type.indexOf("image/") !== 0) { callback(file); return; }
  try {
    var reader = new FileReader();
    reader.onload = function(e) {
      var img = new Image();
      img.onload = function() {
        var attempts = [
          { dim: 1000, q: 0.75 },
          { dim: 1000, q: 0.6 },
          { dim: 1000, q: 0.45 },
          { dim: 800, q: 0.55 },
          { dim: 800, q: 0.4 },
          { dim: 600, q: 0.5 },
          { dim: 600, q: 0.35 }
        ];
        var bestSoFar = null;

        function tryAttempt(idx) {
          if (idx >= attempts.length) {
            finish(bestSoFar || file);
            return;
          }
          var a = attempts[idx];
          var w = img.width, h = img.height;
          if (w > a.dim || h > a.dim) {
            if (w > h) { h = Math.round(h * a.dim / w); w = a.dim; }
            else { w = Math.round(w * a.dim / h); h = a.dim; }
          }
          var canvas = document.createElement("canvas");
          canvas.width = w;
          canvas.height = h;
          var ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0, w, h);
          canvas.toBlob(function(blob) {
            if (!blob) { tryAttempt(idx + 1); return; }
            if (!bestSoFar || blob.size < bestSoFar.size) bestSoFar = blob;
            if (blob.size <= IMAGE_TARGET_BYTES) { finish(blob); return; }
            tryAttempt(idx + 1);
          }, "image/jpeg", a.q);
        }

        function finish(blob) {
          if (blob === file || blob.size >= file.size) { callback(file); return; } // garde l'original s'il était déjà plus léger
          var newName = file.name.replace(/\.[^.]+$/, "") + ".jpg";
          var compressed;
          try { compressed = new File([blob], newName, { type: "image/jpeg" }); }
          catch (e2) { blob.name = newName; compressed = blob; } // secours pour navigateurs sans support de File()
          callback(compressed);
        }

        tryAttempt(0);
      };
      img.onerror = function() { callback(file); }; // en cas d'échec, on envoie l'original plutôt que de bloquer
      img.src = e.target.result;
    };
    reader.onerror = function() { callback(file); };
    reader.readAsDataURL(file);
  } catch (e3) {
    callback(file);
  }
}

// ---------- Loader d'upload (mascotte Sounsouni) ----------
// Compteur plutôt qu'un simple booléen : si plusieurs photos/vidéos
// s'envoient en même temps (ex: plusieurs images d'un produit), le
// loader doit rester visible jusqu'à ce que LA DERNIÈRE se termine,
// pas disparaître dès que la première a fini.
var _activeUploadsCount = 0;
function showUploadLoader() {
  _activeUploadsCount++;
  var el = document.getElementById("su-upload-loader");
  if (el) el.classList.add("su-visible");
}
function hideUploadLoader() {
  _activeUploadsCount = Math.max(0, _activeUploadsCount - 1);
  if (_activeUploadsCount === 0) {
    var el = document.getElementById("su-upload-loader");
    if (el) el.classList.remove("su-visible");
  }
}

// ---------- Resynchronisation silencieuse au retour au premier plan ----------
// Remplace l'ancien window.location.reload() : recharge les données à jour
// (commandes, comptes, messages...) SANS recharger toute la page — donc
// sans repasser par l'écran de démarrage et sans perdre la position de la
// personne dans l'app. Affiche le petit loader mascotte pendant l'opération,
// comme prévu à l'origine pour ce cas d'usage.
var _backgroundResyncRunning = false;
function runBackgroundResync() {
  if (!FIREBASE_ENABLED || typeof sb === "undefined" || !sb) return;
  if (_backgroundResyncRunning) return; // évite deux resyncs en même temps
  _backgroundResyncRunning = true;
  showUploadLoader();
  var resyncStartedAt = Date.now();
  // Durée minimale d'affichage de la mascotte, même si la resync réelle va
  // plus vite — un aller-retour de 300ms suivi d'une disparition instantanée
  // du loader donnait une impression de clignotement plutôt que de vrai
  // chargement. 4,5 secondes minimum, quel que soit le temps réel du réseau.
  var MIN_LOADER_DISPLAY_MS = 4500;

  var LAST_SYNC_KEY = "gems_last_sync_v2";
  var lastSyncAt = localStorage.getItem(LAST_SYNC_KEY);
  var hasCachedData = state.products.length > 0 && state.accounts.length > 0;
  var ONE_DAY_MS = 24 * 60 * 60 * 1000;
  var needsFullSync = !lastSyncAt || !hasCachedData || (Date.now() - new Date(lastSyncAt).getTime()) > ONE_DAY_MS;
  var PAGE_SIZE = 900;

  function fetchAllResyncPages(offset, accumulated) {
    var pageQuery = sb.from("app_data").select("*").not("collection", "in", "(products,orders,notifications,conversations,visitIds,visitStats)").range(offset, offset + PAGE_SIZE - 1);
    if (!needsFullSync) pageQuery = pageQuery.gt("updated_at", lastSyncAt);
    return pageQuery.then(function(res) {
      if (res.error) return res;
      var combined = accumulated.concat(res.data || []);
      if (res.data && res.data.length === PAGE_SIZE) {
        return fetchAllResyncPages(offset + PAGE_SIZE, combined);
      }
      return { error: null, data: combined };
    });
  }

  fetchAllResyncPages(0, []).then(function(res) {
    if (!res.error) {
      if (needsFullSync) {
        var byCollection = {};
        SHARED_KEYS.forEach(function(name) { byCollection[name] = []; });
        var publicProfileRows = [];
        res.data.forEach(function(row) {
          if (row.collection === "publicProfiles") { publicProfileRows.push(row.data); return; }
          if (byCollection[row.collection]) byCollection[row.collection].push(row.data);
        });
        var accountsFromPublic = byCollection.accounts.length === 0 && publicProfileRows.length > 0;
        // Même règle qu'au démarrage : les articles ne sont pas dans cette
        // requête, on ne remplace donc jamais leur liste par du vide.
        SHARED_KEYS.forEach(function(name) { if (name === "products" || PERSONAL_KEYS.indexOf(name) !== -1 || PRIVATE_KEYS.indexOf(name) !== -1 || (name === "accounts" && accountsFromPublic)) return; state[name] = byCollection[name]; });
          if (accountsFromPublic) applyPublicProfiles(publicProfileRows, true);
      } else {
        res.data.forEach(function(row) {
          if (row.collection === "publicProfiles") { applyPublicProfiles([row.data], false); return; }
          if (SHARED_KEYS.indexOf(row.collection) === -1) return;
          var list = state[row.collection];
          var idx = list.findIndex(function(item) { return item.id === row.data.id; });
          if (idx === -1) list.push(row.data); else list[idx] = row.data;
        });
      }
      localStorage.setItem(LAST_SYNC_KEY, computeNextSyncWatermark(res.data, lastSyncAt));
        syncPersonalCollections();
      refreshProfileFromAccounts();
      for (var oi = 0; oi < state.orders.length; oi++) {
        if (!Array.isArray(state.orders[oi].items)) state.orders[oi].items = [];
        if (typeof state.orders[oi].subtotal !== "number") state.orders[oi].subtotal = 0;
        if (typeof state.orders[oi].total !== "number") state.orders[oi].total = 0;
      }
      save();
      pushDebugLog("info", "Resynchronisation silencieuse (retour au premier plan)", "lignes reçues=" + res.data.length);
      if (state.profile) { fetchMyOrderContacts(); fetchMyOrderDetails(); }
      render();
    } else {
      console.error("Erreur resynchronisation silencieuse :", res.error);
    }
    _backgroundResyncRunning = false;
    var elapsedResyncMs = Date.now() - resyncStartedAt;
    var remainingDisplayMs = Math.max(0, MIN_LOADER_DISPLAY_MS - elapsedResyncMs);
    setTimeout(hideUploadLoader, remainingDisplayMs);
  });
}

// ---------- VIGNETTES LÉGÈRES (économie du trafic Supabase) ----------
// Chaque photo du stockage « photo » a une petite copie WebP d'environ 10 Ko
// (400 px de large) rangée à « thumbs/<chemin d'origine>.webp ». Les listes
// et cartes affichent cette vignette ; la grande photo n'est chargée qu'à
// l'ouverture de l'article. Si la vignette manque, l'image d'origine prend
// le relais automatiquement (voir l'écouteur « error » plus bas).
var SNS_PHOTO_RE = /^(https:\/\/[^\/]+\/storage\/v1\/object\/public\/photo\/)([^?#]+)$/;
function snsThumb(u) {
  var m = SNS_PHOTO_RE.exec(u || "");
  if (!m || m[2].indexOf("thumbs/") === 0 || m[2].indexOf("verification/") === 0 || !/\.(jpe?g|png|webp)$/i.test(m[2])) return u;
  return m[1] + "thumbs/" + m[2] + ".webp";
}
function snsThumbSrc(u) {
  var t = snsThumb(u);
  return t === u ? 'src="' + u + '"' : 'src="' + t + '" data-full="' + u + '"';
}
document.addEventListener("error", function(e) {
  var el = e.target;
  if (!el || el.tagName !== "IMG" || !el.getAttribute) return;
  var full = el.getAttribute("data-full");
  if (full && el.getAttribute("src") !== full) { el.removeAttribute("data-full"); el.setAttribute("src", full); }
}, true);
// Fabrique et envoie la vignette d'une photo qu'on vient de téléverser.
// Sans effet bloquant : en cas d'échec, l'image d'origine reste affichée.
function snsMakeThumb(file, path) {
  try {
    // Jamais de copie pour les pièces d'identité / selfies de vérification.
    if (!file || /^verification\//.test(path) || !/^image\/(jpe?g|png|webp)$/i.test(file.type || "") || !/\.(jpe?g|png|webp)$/i.test(path)) return;
    var url = URL.createObjectURL(file), img = new Image();
    img.onload = function() {
      try {
        var w = Math.min(400, img.naturalWidth || 400), h = Math.round((img.naturalHeight || w) * w / (img.naturalWidth || w));
        var c = document.createElement("canvas"); c.width = w; c.height = h;
        c.getContext("2d").drawImage(img, 0, 0, w, h);
        URL.revokeObjectURL(url);
        var tryQ = function(q) {
          c.toBlob(function(b) {
            if (!b) return;
            if (b.size > 12000 && q > 0.3) return tryQ(Math.round((q - 0.1) * 10) / 10);
            sb.storage.from("photo").upload("thumbs/" + path + ".webp", b, { cacheControl: "31536000", contentType: "image/webp", upsert: false });
          }, "image/webp", q);
        };
        tryQ(0.7);
      } catch (e2) {}
    };
    img.onerror = function() { URL.revokeObjectURL(url); };
    img.src = url;
  } catch (e) {}
}

function uploadToStorage(file, folder, onDone) {
  showUploadLoader();
  compressImage(file, function(processedFile) {
    uploadToStorageRaw(processedFile, folder, function(err, url) {
      hideUploadLoader();
      onDone(err, url);
    });
  });
}

// Pièces d'identité et selfies (audit 28/10/2026) : jamais dans le stockage
// public. Envoyés à la fonction serveur verif-upload, qui les range dans le
// coffre privé « verif » et renvoie une référence « verif:<chemin> ».
// Pour l'aperçu sur le téléphone, on garde une copie locale (objectURL).
window._snsVerifPreview = window._snsVerifPreview || {};
function verifSrc(u) {
  if (typeof u === "string" && u.indexOf("verif:") === 0) return window._snsVerifPreview[u] || "data:image/gif;base64,R0lGODlhAQABAAAAACw=";
  return u;
}
function uploadVerificationFile(file, folder, onDone) {
  var kind = folder.indexOf("selfies") !== -1 ? "selfies" : "docs";
  var reader = new FileReader();
  reader.onerror = function() { onDone(reader.error || new Error("Lecture du fichier impossible")); };
  reader.onload = function(e) {
    fetch(supabaseConfig.url + "/functions/v1/verif-upload", { method: "POST", headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey }, body: JSON.stringify({ kind: kind, data: e.target.result }) })
      .then(function(r) { return r.json(); })
      .then(function(res) {
        if (!res || !res.success || !res.ref) { onDone(new Error((res && res.error) || "envoi_refuse")); return; }
        try { window._snsVerifPreview[res.ref] = URL.createObjectURL(file); } catch (e2) { window._snsVerifPreview[res.ref] = e.target.result; }
        onDone(null, res.ref);
      })
      .catch(function(err) { onDone(err); });
  };
  reader.readAsDataURL(file);
}
function uploadToStorageRaw(file, folder, onDone) {
  if (FIREBASE_ENABLED && /^verification\//.test(folder)) { uploadVerificationFile(file, folder, onDone); return; }
  if (!FIREBASE_ENABLED) {
    try {
      var reader = new FileReader();
      reader.onload = function(e) { onDone(null, e.target.result); };
      reader.onerror = function() {
        console.error("Erreur de lecture du fichier :", file.name, reader.error);
        onDone(reader.error || new Error("Lecture du fichier impossible"));
      };
      reader.readAsDataURL(file);
    } catch (err) {
      console.error("Exception lecture locale du fichier :", err);
      onDone(err);
    }
    return;
  }
  try {
    var path = folder + "/" + Date.now() + "_" + uid() + "_" + file.name.replace(/[^a-zA-Z0-9.\-_]/g, "_");
    // Conservation 1 an dans le téléphone : chaque nom de fichier est unique
    // (date + identifiant), une photo ne change donc jamais à la même
    // adresse — inutile de la retélécharger toutes les heures.
    sb.storage.from("photo").upload(path, file, { cacheControl: "31536000" }).then(function(res) {
      if (res.error) {
        console.error("Erreur d'envoi vers Supabase Storage :", res.error);
        onDone(res.error);
        return;
      }
      var publicUrl = sb.storage.from("photo").getPublicUrl(path).data.publicUrl;
      snsMakeThumb(file, path);
      onDone(null, publicUrl);
    });
  } catch (err) {
    console.error("Exception uploadToStorage :", err);
    onDone(err);
  }
}

