const CITIES = ["Bamako", "Ségou", "Sikasso", "Mopti", "Kayes", "Koutiala"];

// Villes hors Mali — ajoutées par l'administration au fur et à mesure de
// l'expansion (voir renderAdminInternationalCities). Chacune porte son
// propre pays, sa propre liste de quartiers, et un tarif de livraison
// simple et unique en attendant d'avoir assez de recul pour un calcul
// précis comme celui du Mali (voir DELIVERY_FEES).
function getInternationalCities() {
  return state.internationalCities || [];
}

// Le pays d'une ville de livraison choisie — Mali pour toute ville de la
// liste CITIES ci-dessus (le système historique), sinon on cherche dans
// les villes internationales ajoutées par l'admin. Sert au point 6 :
// bloquer un achat si le pays de la ville de livraison ne correspond pas
// à celui du vendeur.
function countryForCity(cityName) {
  if (CITIES.indexOf(cityName) !== -1) return "Mali";
  var intl = getInternationalCities();
  for (var i = 0; i < intl.length; i++) {
    if (intl[i].city === cityName) return intl[i].country;
  }
  return "Mali";
}

const DELIVERY_FEES = {
  "Bamako": { "Commune I": 1000, "Commune II": 1500, "Commune III": 2000, "Commune IV": 2200, "Commune V": 2500, "Commune VI": 3000, "Autre": 3000 },
  "Ségou": { "Centre-ville": 2500, "Périphérie": 3200, "Autre": 3200 },
  "Sikasso": { "Centre-ville": 2500, "Périphérie": 3200, "Autre": 3200 },
  "Mopti": { "Centre-ville": 3000, "Périphérie": 3800, "Autre": 3800 },
  "Kayes": { "Centre-ville": 3000, "Périphérie": 3800, "Autre": 3800 },
  "Koutiala": { "Centre-ville": 2500, "Périphérie": 3200, "Autre": 3200 },
};

const DEFAULT_DELIVERY_FEE = 2000;

// ---------- LIVRAISON INTER-VILLES (envoi par car, hors Bamako) ----------
// Pour les autres grandes villes du Mali, pas de calcul GPS/rive — le
// vendeur (basé à Bamako) envoie le colis par car, l'acheteur le récupère
// lui-même à la gare routière de sa ville. Un tarif de base par ville
// (jamais deviné : reste "non configuré" tant que l'admin n'a pas
// renseigné le vrai prix du car), plus une majoration par article
// supplémentaire dans la même commande (colis plus gros/plus lourd à
// envoyer), elle aussi propre à chaque ville puisque les distances et les
// tarifs de car ne sont pas les mêmes.
function intercityDeliveryCities() {
  return CITIES.filter(function(c) { return c !== "Bamako"; });
}

function defaultIntercityDeliveryConfig() {
  var cfg = {};
  intercityDeliveryCities().forEach(function(city) {
    cfg[city] = { basePrice: null, extraItemFee: null };
  });
  return cfg;
}

function getIntercityDeliveryConfig() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "intercity_delivery_config") {
        // Fusionne avec les valeurs par défaut au cas où une ville aurait
        // été ajoutée à CITIES après l'enregistrement de cette config.
        var saved = state.settings[i].data || {};
        var merged = defaultIntercityDeliveryConfig();
        Object.keys(saved).forEach(function(city) { merged[city] = saved[city]; });
        return merged;
      }
    }
  }
  return defaultIntercityDeliveryConfig();
}

function saveIntercityDeliveryConfig(cfg) {
  var doc = { id: "intercity_delivery_config", data: cfg };
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "intercity_delivery_config") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(doc); else state.settings[idx] = doc;
  save();
  saveDoc("settings", doc);
}

// totalItemCount : nombre total d'articles dans la commande (quantités
// additionnées, pas seulement le nombre de lignes différentes) — un colis
// avec plus d'articles est plus gros/plus lourd à envoyer par car.
// Renvoie null si le prix de cette ville n'a pas encore été configuré —
// à afficher comme "tarif pas encore disponible", jamais comme 0 FCFA.
function computeIntercityDeliveryFee(city, totalItemCount) {
  var cfg = getIntercityDeliveryConfig();
  var cityCfg = cfg[city];
  if (!cityCfg || cityCfg.basePrice == null) return null;
  var extra = Math.max(0, (totalItemCount || 1) - 1);
  var extraFee = cityCfg.extraItemFee != null ? cityCfg.extraItemFee : 0;
  return cityCfg.basePrice + extra * extraFee;
}
// Nombre d'articles affichés à la fois dans le marché — le reste se charge
// automatiquement au défilement, voir setupMarketInfiniteScroll().
const MARKET_PAGE_SIZE = 20;

// Construit la config par défaut { ville: { zone: { express, relais } } } à
// partir du tarif Express existant. Le tarif Point de Retrait démarre à 70% de
// l'Express (arrondi à 50F), mais tout est modifiable ensuite depuis
// Admin > Tarifs livraison (voir saveDeliveryFeesConfig).
function defaultDeliveryFeesConfig() {
  var cfg = {};
  var cities = Object.keys(DELIVERY_FEES);
  for (var i = 0; i < cities.length; i++) {
    var city = cities[i];
    cfg[city] = {};
    var zones = Object.keys(DELIVERY_FEES[city]);
    for (var j = 0; j < zones.length; j++) {
      var z = zones[j];
      var expressPrice = DELIVERY_FEES[city][z];
      var relaisPrice = Math.round((expressPrice * 0.7) / 50) * 50;
      cfg[city][z] = { express: expressPrice, relais: relaisPrice };
    }
  }
  return cfg;
}

// Renvoie la config de tarifs actuellement active : celle enregistrée par
// l'admin si elle existe (state.settings, synchronisée via Firestore/local),
// sinon la config par défaut calculée ci-dessus.
function getDeliveryFeesConfig() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "delivery_fees") return state.settings[i].zones;
    }
  }
  return defaultDeliveryFeesConfig();
}

function saveDeliveryFeesConfig(zones) {
  var doc = { id: "delivery_fees", zones: zones };
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "delivery_fees") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(doc); else state.settings[idx] = doc;
  save();
  saveDoc("settings", doc);
  showToast(t("toast_delivery_rates_updated"));
  render();
}

// --- Tarifs de transport international (vendeur "international", groupage) ---
// Prix au kg, en Roupies (INR) — cohérent avec les prix produit du vendeur,
// eux-mêmes en INR. Converti en FCFA au moment de l'affichage/paiement via
// getInrToXofRate(), jamais stocké en dur en FCFA (le taux de change bouge).
function defaultInternationalShippingConfig() {
  // Deux planchers séparés (pas un seul commun) : sans ça, un article
  // léger ou sans poids/volume renseigné tombait sur le MÊME minimum
  // quel que soit le mode choisi — Maritime et Aérien affichaient alors
  // exactement le même total, ce qui rendait le choix incompréhensible.
  // Le plancher Aérien est volontairement plus élevé, comme dans le vrai
  // fret (un envoi minimal par avion coûte plus cher qu'un envoi minimal
  // par bateau).
  return {
    maritimePerKg: 150, aerienPerKg: 450, minCostInrMaritime: 500, minCostInrAerien: 1200,
    // Avion — tableau du partenaire indien (roupies, hors taxe), par tranche
    // de 0,5 kg jusqu'à 20 kg, puis un prix au kilo de 21 à 44 kg.
    airTable: [[0.5,2653],[1,3094],[1.5,3546],[2,4000],[2.5,4452],[3,4906],[3.5,5359],[4,5811],[4.5,6262],[5,6715],[5.5,7026],[6,7449],[6.5,7884],[7,8253],[7.5,8684],[8,9092],[8.5,9488],[9,9816],[9.5,10199],[10,10581],[10.5,10942],[11,11303],[11.5,11662],[12,12023],[12.5,12383],[13,12743],[13.5,13103],[14,13463],[14.5,13823],[15,14185],[15.5,14544],[16,14904],[16.5,15266],[17,15625],[17.5,15984],[18,16328],[18.5,16673],[19,17055],[19.5,17439],[20,17789]],
    airPerKgAbove20: 830,   // de 21 à 44 kg
    airMaxKg: 44,           // poids maximum d'un colis ; au-delà, plusieurs colis
    gstPct: 18,             // taxe indienne (GST) sur le transport
    marginPct: 10,          // frais Sounsouni : % du transport (taxe comprise)
    customsDutyPct: 32,     // droits de douane à Bamako : % de la valeur des articles
    vatPct: 18,             // TVA au Mali : % de la valeur des articles
    delayText: "6 à 12 jours",
    // Bateau — prix TOUT COMPRIS par m³, en FCFA : bateau Inde → Dakar avec
    // taxes indiennes, frais des ports, camion Dakar → Bamako, transit et
    // formalités. Estimation prudente (octobre 2026), à ajuster dans Admin.
    seaPricePerM3Xof: 300000,
    seaMinM3: 1,            // volume minimum facturé par commande
    seaKgPerM3: 1000,       // marchandise lourde : 1 m³ = 1 000 kg
    seaDelayText: "6 à 10 semaines",
    // Dernier trajet jusqu'au domicile du client à Bamako : tarif normal
    // de livraison du quartier, + un supplément pour les gros colis
    // (tricycle au lieu d'une moto).
    homeHeavyKg: 30,
    homeHeavyExtraXof: 5000
  };
}

// Calcul du transport par avion, colis par colis (partenaire indien) :
// poids facturé = le plus élevé entre le poids réel et le poids de place
// (L × l × H en cm ÷ 5 000), minimum 0,5 kg, arrondi à la demi-tranche
// au-dessus ; prix du tableau + 18 % de taxe ; + frais Sounsouni (10 % du
// transport) ; + douane estimée (en FCFA). Livraison : aéroport de Bamako.
function intlParcelsText(parcels) {
  var groups = [];
  parcels.forEach(function(p) { var g = groups.find(function(x) { return x.kg === p.kg; }); if (g) g.n++; else groups.push({ kg: p.kg, n: 1 }); });
  return groups.map(function(g) { return g.n + ' × ' + String(g.kg).replace('.', ',') + ' kg'; }).join(' + ');
}

// Bateau : volume facturé = le plus élevé entre le volume réel, le poids
// ramené en m³ (1 000 kg = 1 m³) et le minimum ; prix tout compris au m³ ;
// + frais Sounsouni ; + douane et TVA sur la valeur des articles.
function intlHomeDeliveryFee(heavy) {
  var cfg = getInternationalShippingConfig();
  var f = state.checkoutForm || {};
  var fee = DEFAULT_DELIVERY_FEE;
  if (f.expressCommune && f.expressQuartier) {
    try { var r = computeRealDeliveryFees(f.buyerLat, f.buyerLng, "Bamako", f.expressCommune, f.expressQuartier, f.zone); if (r && Number(r.expressFee) > 0) fee = Number(r.expressFee); } catch (e) {}
  }
  return Math.round(fee + (heavy ? (Number(cfg.homeHeavyExtraXof) || 0) : 0));
}

function computeSeaShippingBreakdown() {
  var air = computeAirShippingBreakdown();
  var cfg = air.cfg;
  var wv = checkoutInternationalWeightVolume();
  var kgPerM3 = Number(cfg.seaKgPerM3) || 1000;
  var raw = Math.max(Number(cfg.seaMinM3) || 0, wv.volumeM3, wv.weightKg / kgPerM3, 0.01);
  var m3 = Math.ceil(raw * 100 - 1e-9) / 100;
  var transportXof = Math.round(m3 * (Number(cfg.seaPricePerM3Xof) || 0));
  var marginXof = Math.round(transportXof * (Number(cfg.marginPct) || 0) / 100);
  return { mode: "maritime", billableM3: m3, realM3: wv.volumeM3, realKg: wv.weightKg, transportXof: transportXof, marginXof: marginXof,
    goodsXof: air.goodsXof, dutyXof: air.dutyXof, vatXof: air.vatXof, customsXof: air.customsXof, dutyPct: air.dutyPct, vatPct: air.vatPct,
    homeXof: intlHomeDeliveryFee(true),
    totalXof: air.goodsXof + transportXof + marginXof + air.customsXof + intlHomeDeliveryFee(true), cfg: cfg, rate: air.rate };
}

function computeAirShippingBreakdown() {
  var cfg = getInternationalShippingConfig();
  var wv = checkoutInternationalWeightVolume();
  var realKg = wv.weightKg, volKg = wv.volumeM3 * 200; // m³ × 200 = cm³ ÷ 5 000
  var billable = Math.max(0.5, realKg, volKg);
  var kg = Math.ceil(billable * 2 - 1e-9) / 2;
  var table = Array.isArray(cfg.airTable) && cfg.airTable.length ? cfg.airTable : defaultInternationalShippingConfig().airTable;
  var last = table[table.length - 1];
  var priceFor = function(k) {
    if (k <= last[0]) { var row = table.find(function(r) { return r[0] >= k - 1e-9; }) || last; return row[1]; }
    return Math.max(last[1], Math.ceil(k) * (Number(cfg.airPerKgAbove20) || 830));
  };
  // Au-delà du poids maximum d'un colis (44 kg) : plusieurs colis, chacun
  // calculé avec le tableau. On partage le poids à parts égales (ex. 50 kg =
  // 2 colis de 25 kg) pour ne jamais avoir un petit colis qui coûte cher.
  var maxKg = Math.max(1, Number(cfg.airMaxKg) || 44);
  var nParcels = Math.ceil(kg / maxKg - 1e-9);
  var halves = Math.round(kg * 2), per = Math.floor(halves / nParcels), extra = halves % nParcels;
  var parcels = [];
  for (var pi = 0; pi < nParcels; pi++) { var pk = (per + (pi < extra ? 1 : 0)) / 2; parcels.push({ kg: pk, baseInr: priceFor(pk) }); }
  var baseInr = parcels.reduce(function(s, x) { return s + x.baseInr; }, 0);
  var gstInr = Math.round(baseInr * (Number(cfg.gstPct) || 0) / 100);
  var transportInr = baseInr + gstInr;
  var marginInr = Math.round(transportInr * (Number(cfg.marginPct) || 0) / 100);
  var rate = getInrToXofRate();
  var goodsXof = Math.round(checkoutSubtotal() * rate);
  var transportXof = Math.round(transportInr * rate), marginXof = Math.round(marginInr * rate);
  // Douane : droits + TVA, calculés sur la valeur des articles seulement (sans le transport). Les anciens
  // réglages avec un seul pourcentage (customsPct) restent compris.
  var dutyPct = cfg.customsDutyPct != null ? Number(cfg.customsDutyPct) || 0 : Number(cfg.customsPct) || 0;
  var vatPct = cfg.vatPct != null ? Number(cfg.vatPct) || 0 : 0;
  var dutyXof = Math.round(goodsXof * dutyPct / 100);
  var vatXof = Math.round(goodsXof * vatPct / 100);
  var customsXof = dutyXof + vatXof;
  return { realKg: realKg, volKg: volKg, billableKg: kg, baseInr: baseInr, gstInr: gstInr, transportInr: transportInr, marginInr: marginInr,
    goodsXof: goodsXof, transportXof: transportXof, marginXof: marginXof, customsXof: customsXof, dutyXof: dutyXof, vatXof: vatXof, dutyPct: dutyPct, vatPct: vatPct, homeXof: intlHomeDeliveryFee(kg > (Number(cfg.homeHeavyKg) || 30)), totalXof: goodsXof + transportXof + marginXof + customsXof + intlHomeDeliveryFee(kg > (Number(cfg.homeHeavyKg) || 30)),
    parcels: parcels, overLimit: false, cfg: cfg, rate: rate };
}

function getInternationalShippingConfig() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "international_shipping") return { ...defaultInternationalShippingConfig(), ...state.settings[i].config };
    }
  }
  return defaultInternationalShippingConfig();
}

function saveInternationalShippingConfig(config) {
  var doc = { id: "international_shipping", config: config };
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "international_shipping") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(doc); else state.settings[idx] = doc;
  save();
  saveDoc("settings", doc);
  showToast(t("toast_shipping_rates_updated"));
  render();
}

// Poids/volume total du panier international (l'un OU l'autre compte selon
// le transporteur — pratique standard du fret : on facture le "poids
// volumétrique" si le volume pèse plus lourd que le poids réel).
function checkoutInternationalWeightVolume() {
  var items = checkoutItems();
  var totalWeightKg = 0, totalVolumeM3 = 0;
  for (var i = 0; i < items.length; i++) {
    totalWeightKg += (Number(items[i].poidsKg) || 0) * items[i].qty;
    totalVolumeM3 += (Number(items[i].volumeM3) || 0) * items[i].qty;
  }
  return { weightKg: totalWeightKg, volumeM3: totalVolumeM3 };
}

// Poids volumétrique standard fret maritime/aérien : 1 m³ ≈ 167 kg
// (convention IATA simplifiée) — on facture le plus lourd des deux.
function checkoutInternationalBillableWeight() {
  var wv = checkoutInternationalWeightVolume();
  var volumetricKg = wv.volumeM3 * 200; // L × l × H (cm) ÷ 5 000, règle du partenaire
  return Math.max(wv.weightKg, volumetricKg);
}

function computeInternationalShippingCostInr(mode) {
  var cfg = getInternationalShippingConfig();
  var billableKg = checkoutInternationalBillableWeight();
  if (mode === "aerien") { var bd = computeAirShippingBreakdown(); return bd.transportInr + bd.marginInr; }
  var perKg = cfg.maritimePerKg;
  var minCost = cfg.minCostInrMaritime;
  return Math.max(minCost, Math.round(billableKg * perKg));
}

// true seulement si TOUT le panier est international — le mélange est déjà
// bloqué à l'ajout au panier (voir addToCart), donc en pratique c'est
// "tout ou rien", jamais un mélange partiel.
function checkoutIsInternational() {
  var items = checkoutItems();
  return items.length > 0 && items.every(function(it) { return it.sellerType === "international"; });
}

// Renvoie les modes de transport réellement disponibles pour CE panier —
// l'intersection de ce que chaque vendeur autorise (en pratique un seul
// vendeur par commande internationale, mais on reste robuste si ça change).
function checkoutAvailableShippingModes() {
  var items = checkoutItems();
  var allowsMaritime = items.every(function(it) { return !it.transportModes || it.transportModes === "both" || it.transportModes === "maritime"; });
  var allowsAerien = items.every(function(it) { return !it.transportModes || it.transportModes === "both" || it.transportModes === "aerien"; });
  // Le client choisit lui-même entre l'avion et le bateau (selon ce que le
  // vendeur accepte) ; les deux prix lui sont montrés côte à côte.
  var modes = [];
  if (allowsAerien) modes.push("aerien");
  if (allowsMaritime) modes.push("maritime");
  return modes;
}

// --- Taux de change international (roupie indienne → Franc CFA) ---
// Deux modes, au choix dans Admin :
// - Automatique (par défaut) : récupéré une fois par jour depuis un
//   service gratuit, sans clé ni limite d'appels — personne n'a besoin d'y
//   penser, le taux se met à jour tout seul.
// - Manuel : un chiffre fixe, choisi et gardé tant que l'Admin ne le
//   change pas — l'automatique ne le remplace jamais tant que ce mode est actif.
const EXCHANGE_RATE_FALLBACK_INR_TO_XOF = 7.2; // au cas où le tout premier chargement échoue (pas de réseau) — remplacé dès que possible par le vrai taux
const EXCHANGE_RATE_MAX_AGE_MS = 24 * 60 * 60 * 1000; // 1 jour — inutile de re-demander plus souvent, le service ne se met à jour qu'une fois par jour

function getExchangeRateConfig() {
  var defaults = { mode: "auto", manualRate: EXCHANGE_RATE_FALLBACK_INR_TO_XOF, autoRate: null, autoRateFetchedAt: 0 };
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "exchange_rate_inr_xof") {
        return Object.assign({ id: "exchange_rate_inr_xof" }, defaults, state.settings[i]);
      }
    }
  }
  return Object.assign({ id: "exchange_rate_inr_xof" }, defaults);
}

function saveExchangeRateConfig(cfg) {
  cfg.id = "exchange_rate_inr_xof";
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "exchange_rate_inr_xof") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(cfg); else state.settings[idx] = cfg;
  save();
  saveDoc("settings", cfg);
}

// Le taux réellement à utiliser partout dans l'app (panier, fiches
// produits des vendeurs internationaux...) — jamais un appel réseau ici,
// juste une lecture immédiate de ce qui est déjà en mémoire.
function getInrToXofRate() {
  var cfg = getExchangeRateConfig();
  if (cfg.mode === "manual") return cfg.manualRate;
  return cfg.autoRate || EXCHANGE_RATE_FALLBACK_INR_TO_XOF;
}

// Va chercher le vrai taux du jour si besoin (une fois par jour maximum,
// et seulement si le mode automatique est actif) — appelée sans risque à
// chaque démarrage de l'app, elle ne fait rien la plupart du temps.
function refreshAutoExchangeRateIfNeeded() {
  var cfg = getExchangeRateConfig();
  if (cfg.mode !== "auto") return; // le mode manuel ne doit jamais être écrasé
  var isStale = !cfg.autoRateFetchedAt || (Date.now() - cfg.autoRateFetchedAt) > EXCHANGE_RATE_MAX_AGE_MS;
  if (!isStale) return;
  fetch("https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/inr.json")
    .then(function(r) { return r.json(); })
    .then(function(data) {
      var rate = data && data.inr && data.inr.xof;
      if (typeof rate === "number" && rate > 0) {
        cfg.autoRate = rate;
        cfg.autoRateFetchedAt = Date.now();
        saveExchangeRateConfig(cfg);
      }
    })
    .catch(function() {
      // Pas grave si ça échoue une fois (pas de réseau, service
      // indisponible) — l'ancien taux (ou celui de secours) reste utilisé
      // en attendant, et on retentera automatiquement au prochain
      // démarrage de l'app.
    });
}

// ---------- TRADUCTION AUTOMATIQUE DES ARTICLES (nom + description) ----------
// Le nom et la description d'un article sont tapés librement par chaque
// vendeur — jamais dans le dictionnaire de traduction de l'app (contrairement
// aux menus/boutons, eux préparés à l'avance dans les 3 langues). On les
// fait traduire une seule fois, à la publication, via un service gratuit
// (même principe que le taux de change ci-dessus : un simple fetch, sans
// clé ni compte) — puis on garde le résultat sur la fiche produit, jamais
// retraduit à chaque fois qu'un acheteur la consulte.
// Réponse de MyMemory qui n'est PAS une traduction : quand la limite du
// jour est atteinte (ou texte trop long), le service renvoie un message
// d'avertissement À LA PLACE de la traduction — il ne faut jamais
// l'enregistrer comme traduction.
function isTranslationGarbage(txt) {
  if (!txt || typeof txt !== "string") return true;
  var u = txt.toUpperCase();
  return u.indexOf("MYMEMORY WARNING") !== -1 || u.indexOf("QUERY LENGTH LIMIT") !== -1 || u.indexOf("INVALID LANGUAGE PAIR") !== -1 || u.indexOf("YOU USED ALL AVAILABLE FREE TRANSLATIONS") !== -1;
}
// Découpe un texte en morceaux de moins de 450 octets (limite MyMemory :
// 500 octets par envoi), de préférence entre deux phrases.
function splitForTranslation(text) {
  var bytes = function(x) { try { return new TextEncoder().encode(x).length; } catch (e) { return x.length * 2; } };
  if (bytes(text) <= 450) return [text];
  // Sans « lookbehind » (regard en arrière) : les iPhone avant iOS 16.4 ne le comprennent pas
  // et TOUT le programme refusait alors de démarrer (écran noir).
  var parts = text.replace(/([.!?\n])\s+/g, "$1\u0000").split("\u0000"), chunks = [], cur = "";
  parts.forEach(function(part) {
    if (bytes(cur + " " + part) > 450 && cur) { chunks.push(cur); cur = part; }
    else cur = cur ? cur + " " + part : part;
    while (bytes(cur) > 450) { var cut = Math.floor(cur.length / 2); chunks.push(cur.slice(0, cut)); cur = cur.slice(cut); }
  });
  if (cur) chunks.push(cur);
  return chunks;
}
// opts.useEmail : adresse de contact transmise à MyMemory (50 000
// caractères/jour au lieu de 5 000) — réservé à la traduction en masse.
function translateText(text, targetLang, opts) {
  if (!text || !text.trim()) return Promise.resolve("");
  if (opts && opts.from && opts.from === targetLang) return Promise.resolve(text);
  var chunks = splitForTranslation(text.trim());
  var emailParam = (opts && opts.useEmail) ? "&de=" + encodeURIComponent("direction@sounsouni.pro") : "";
  return Promise.all(chunks.map(function(chunk) {
    var fromLang = (opts && opts.from) || "fr";
    var url = "https://api.mymemory.translated.net/get?q=" + encodeURIComponent(chunk) + "&langpair=" + fromLang + "|" + targetLang + emailParam;
    return fetch(url)
      .then(function(r) { return r.json(); })
      .then(function(data) {
        var translated = data && data.responseData && data.responseData.translatedText;
        var status = data && Number(data.responseStatus);
        if (status && status !== 200) { if (status === 429 || status === 403) window._translateQuotaReached = true; return null; }
        if (isTranslationGarbage(translated)) { window._translateQuotaReached = true; return null; }
        return translated;
      })
      .catch(function() { return null; });
  })).then(function(parts) {
    if (parts.some(function(x) { return x === null; })) return ""; // échec : l'article reste en français
    return parts.join(" ");
  });
}

// Traduit le nom et la description d'UN produit fraîchement publié/modifié,
// en anglais et en hindi — sans jamais bloquer la publication elle-même
// (déjà faite avant cet appel, voir finalizeProductSave). Le résultat
// n'arrive qu'une fois le réseau disponible ; si le service est en panne,
// l'article reste simplement affiché dans sa langue d'origine, sans
// jamais empêcher qui que ce soit de le voir ou de l'acheter.
function translateProductAsync(productId) {
  var product = null;
  for (var i = 0; i < state.products.length; i++) { if (state.products[i].id === productId) { product = state.products[i]; break; } }
  if (!product) return;
  translateProductNeeds(product, {}).then(function(changed) {
    if (!changed) return;
    save();
    saveDoc("products", product);
    if (state.detailProductId === productId) render(); // pour voir le résultat tout de suite si on est encore sur la fiche
  });
}

// Langue dans laquelle le vendeur a écrit l'article : retenue à la
// publication ; pour les anciens articles, français — sauf vendeur
// international (anglais).
var APP_LANGS = ["fr", "en", "hi"];
function productSourceLang(p) {
  if (p && p.sourceLang && APP_LANGS.indexOf(p.sourceLang) !== -1) return p.sourceLang;
  return p && p.sellerType === "international" ? "en" : "fr";
}
// Caractéristiques écrites par le vendeur à traduire (texte avec des
// lettres ; pas les nombres, ni les réglages techniques).
var NON_TRANSLATABLE_FIELDS = ["transportModes", "moq", "poidsKg", "volumeM3", "dimL", "dimW", "dimH"];
function productTextFields(p) {
  var fields = [];
  var relevant = (typeof getRelevantSectorFields === "function") ? getRelevantSectorFields(p.sellerType, p.sellerSector, p.category) : [];
  relevant.forEach(function(f) {
    if (NON_TRANSLATABLE_FIELDS.indexOf(f) !== -1) return;
    var v = p[f];
    if (typeof v === "string" && /[A-Za-zÀ-ÿ\u0900-\u097F]/.test(v) && v.length <= 300) fields.push(f);
  });
  return fields;
}
function pickTranslation(p, byLangKey, field, original) {
  var lang = state.language || "fr";
  if (lang === productSourceLang(p)) return original;
  var store = p[byLangKey];
  var v = store ? (field ? (store[lang] && store[lang][field]) : store[lang]) : null;
  return (v && !isTranslationGarbage(v)) ? v : original;
}
function productDisplayName(p) {
  return pickTranslation(p, "nameByLang", null, p.name);
}
function productDisplayDescription(p) {
  return pickTranslation(p, "descriptionByLang", null, p.description || "");
}
function productDisplayField(p, f) {
  return pickTranslation(p, "fieldsByLang", f, p[f]);
}

// ---------- Traduction des articles ----------
// Pour chaque langue autre que celle du vendeur : nom, description et
// caractéristiques écrites. Liste de ce qui manque encore (ou est invalide).
function productTranslationNeeds(p) {
  var src = productSourceLang(p), needs = [];
  APP_LANGS.forEach(function(lang) {
    if (lang === src) return;
    var n = p.nameByLang && p.nameByLang[lang];
    if (p.name && (!n || isTranslationGarbage(n))) needs.push({ kind: "name", lang: lang });
    var d = p.descriptionByLang && p.descriptionByLang[lang];
    if (p.description && p.description.trim() && (!d || isTranslationGarbage(d))) needs.push({ kind: "description", lang: lang });
    productTextFields(p).forEach(function(f) {
      var fv = p.fieldsByLang && p.fieldsByLang[lang] && p.fieldsByLang[lang][f];
      if (!fv || isTranslationGarbage(fv)) needs.push({ kind: "field", field: f, lang: lang });
    });
  });
  return needs;
}
// Traduit tout ce qui manque pour un article. opts.useEmail : quota élargi
// (traduction en masse). Renvoie true si quelque chose a été traduit.
function translateProductNeeds(p, opts) {
  var src = productSourceLang(p);
  var needs = productTranslationNeeds(p);
  var changed = false;
  var chain = Promise.resolve();
  needs.forEach(function(nd) {
    chain = chain.then(function() {
      if (window._translateQuotaReached && opts.useEmail) return;
      var text = nd.kind === "name" ? p.name : (nd.kind === "description" ? p.description : String(p[nd.field]));
      return translateText(text, nd.lang, { from: src, useEmail: !!opts.useEmail }).then(function(res) {
        if (!res) return;
        changed = true;
        if (nd.kind === "name") { p.nameByLang = p.nameByLang || {}; p.nameByLang[nd.lang] = res; }
        else if (nd.kind === "description") { p.descriptionByLang = p.descriptionByLang || {}; p.descriptionByLang[nd.lang] = res; }
        else { p.fieldsByLang = p.fieldsByLang || {}; p.fieldsByLang[nd.lang] = p.fieldsByLang[nd.lang] || {}; p.fieldsByLang[nd.lang][nd.field] = res; }
      });
    });
  });
  return chain.then(function() { return changed; });
}
function runProductTranslationBatch() {
  if (state.trBatch && state.trBatch.running) return;
  var todo = state.products.filter(function(p) { return productTranslationNeeds(p).length > 0; });
  state.trBatch = { running: true, done: 0, total: todo.length, msg: "" };
  window._translateQuotaReached = false;
  render();
  var i = 0;
  function next() {
    if (i >= todo.length) {
      state.trBatch.running = false;
      state.trBatch.msg = "✅ Terminé : " + state.trBatch.done + " article(s) traduit(s).";
      render(); return;
    }
    var p = todo[i++];
    translateProductNeeds(p, { useEmail: true }).then(function(changed) {
      if (changed) saveDoc("products", p);
      if (productTranslationNeeds(p).length === 0) state.trBatch.done++;
      save();
      if (window._translateQuotaReached) {
        state.trBatch.running = false;
        state.trBatch.msg = "⏸️ Limite de traduction du jour atteinte : " + state.trBatch.done + " article(s) traduit(s) aujourd'hui. Relancez demain pour continuer là où ça s'est arrêté.";
        render(); return;
      }
      render();
      setTimeout(next, 250); // on ménage le service gratuit
    });
  }
  next();
}

function getRelaisCommissionRate() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "relais_commission" && typeof state.settings[i].rate === "number") {
        return state.settings[i].rate;
      }
    }
  }
  return RELAIS_COMMISSION_RATE_DEFAULT;
}

function saveRelaisCommissionRate(rate) {
  var doc = { id: "relais_commission", rate: rate };
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "relais_commission") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(doc); else state.settings[idx] = doc;
  save();
  saveDoc("settings", doc);
  showToast(t("toast_pickup_commission_updated"));
  render();
}

// ---------- EFFETS ANIMÉS DU MARCHÉ (interrupteur Admin, coupé par défaut) ----------
// Réglage partagé (collection "settings", id "market_fx") : quand il est
// coupé — c'est le cas tant que l'admin ne l'a pas allumé — les animations
// qui tournent en boucle sur le marché s'arrêtent pour tout le monde
// (balayages de l'en-tête et du menu, cercles "Recommandé", reflets,
// effets des images de marque et de la pub VIP, changement automatique
// des cases "À la une"). La classe "sns-fx-off" est posée dès le départ
// sur <html> (voir index.html), donc rien ne bouge avant le chargement.
function isMarketFxEnabled() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i] && state.settings[i].id === "market_fx") return state.settings[i].enabled === true;
    }
  }
  return false;
}
function applyMarketFxClass() {
  try { document.documentElement.classList.toggle("sns-fx-off", !isMarketFxEnabled()); } catch (e) {}
}
function toggleMarketFx() {
  var doc = { id: "market_fx", enabled: !isMarketFxEnabled() };
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i] && state.settings[i].id === "market_fx") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(doc); else state.settings[idx] = doc;
  save();
  saveDoc("settings", doc);
  applyMarketFxClass();
  showToast(doc.enabled ? "Effets animés du marché : activés" : "Effets animés du marché : désactivés");
  render();
}

// ---------- TOUCHER « DOIGT DANS L'EAU » + OUVERTURE DOUCE ----------
// Une onde part de l'endroit touché, sur tout ce qui se touche. Elle est
// dessinée dans une couche à part (position fixe, au-dessus de tout, sans
// capter les touchers) : on ne modifie jamais les boutons eux-mêmes.
var snsLastTap = null;
(function() {
  var layer = null;
  var SEL = 'button, a, [data-action], .product-card, .nav-item, .reco-circle-item, .chip, label.toggle, .toggle-switch';
  function reduced() { try { return window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches; } catch (e) { return false; } }
  document.addEventListener("pointerdown", function(e) {
    snsLastTap = { x: e.clientX, y: e.clientY, at: Date.now() };
    if (e.button && e.button !== 0) return;
    var el = e.target && e.target.closest ? e.target.closest(SEL) : null;
    if (!el || el.classList.contains("modal-overlay") || el.disabled || reduced()) return;
    var r = el.getBoundingClientRect();
    if (r.width < 8 || r.height < 8 || r.width * r.height > window.innerWidth * window.innerHeight * 0.45) return;
    if (!layer) { layer = document.createElement("div"); layer.className = "sns-ripple-layer"; document.body.appendChild(layer); }
    var cs = getComputedStyle(el);
    var box = document.createElement("div"); box.className = "sns-ripple-box";
    box.style.cssText = "left:" + r.left + "px;top:" + r.top + "px;width:" + r.width + "px;height:" + r.height + "px;border-radius:" + cs.borderRadius + ";";
    var size = Math.max(r.width, r.height) * 2.1;
    var dot = document.createElement("span"); dot.className = "sns-ripple";
    dot.style.cssText = "width:" + size + "px;height:" + size + "px;left:" + (e.clientX - r.left - size / 2) + "px;top:" + (e.clientY - r.top - size / 2) + "px;";
    var ring = document.createElement("span"); ring.className = "sns-ripple-ring";
    ring.style.cssText = "width:" + size * 0.6 + "px;height:" + size * 0.6 + "px;left:" + (e.clientX - r.left - size * 0.3) + "px;top:" + (e.clientY - r.top - size * 0.3) + "px;";
    box.appendChild(dot); box.appendChild(ring); layer.appendChild(box);
    setTimeout(function() { if (box.parentNode) box.parentNode.removeChild(box); }, 700);
  }, { passive: true, capture: true });
})();
// La fiche article s'ouvre en grandissant depuis l'endroit touché.
function snsZoomFromTap(sheet) {
  if (!sheet || !snsLastTap || Date.now() - snsLastTap.at > 1500) return;
  try {
    var r = sheet.getBoundingClientRect();
    sheet.style.transformOrigin = Math.round(snsLastTap.x - r.left) + "px " + Math.round(Math.max(0, snsLastTap.y - r.top)) + "px";
    sheet.classList.add("sns-zoom-open");
    setTimeout(function() { sheet.classList.remove("sns-zoom-open"); }, 600);
  } catch (e) {}
}

// ---------- BOOST (mise en avant payante) ----------
// Config par défaut : forfaits de départ + mode "auto" (activation immédiate,
// sans vérification de paiement — voir discussion avec l'utilisateur : tant
// qu'aucune API Mobile Money n'est branchée, l'admin choisit son mode dans
// Admin > Boosts, avec "auto" par défaut le temps des tests).
function defaultBoostConfig() {
  return {
    id: "boost_config",
    mode: "auto", // "auto" | "manual" | "api"
    itemTiers: [
      { days: 1, price: 500 },
      { days: 3, price: 1200 },
      { days: 7, price: 2500 },
      { days: 30, price: 8000 }
    ],
    shopTiers: [
      { days: 7, price: 5000 },
      { days: 30, price: 15000 }
    ]
  };
}

function getBoostConfig() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "boost_config") return state.settings[i];
    }
  }
  return defaultBoostConfig();
}

function saveBoostConfig(cfg) {
  cfg.id = "boost_config";
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "boost_config") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(cfg); else state.settings[idx] = cfg;
  save();
  saveDoc("settings", cfg);
  showToast(t("toast_boost_config_updated"));
  render();
}

// ---------- CONFIG AFFICHAGE MARCHÉ (réglable en Admin) ----------
function defaultMarketConfig() {
  return {
    id: "market_config",
    newArrivalsValue: 2,
    newArrivalsUnit: "days", // seconds | minutes | hours | days
    showRecoCircles: true,
    showCategoryStars: true,
    showSectorIcons: true,
    showNewArrivals: true,
    showNewTag: true,
    verifiedBadgeShowAll: false,
    ratingBadgeShowAll: false
  };
}

var NEW_ARRIVALS_UNIT_MS = { seconds: 1000, minutes: 60000, hours: 3600000, days: 86400000 };
function newArrivalsDurationMs(cfg) {
  var unit = cfg.newArrivalsUnit || "days";
  var value = cfg.newArrivalsValue != null ? cfg.newArrivalsValue : (cfg.newArrivalsDays || 2);
  return value * (NEW_ARRIVALS_UNIT_MS[unit] || NEW_ARRIVALS_UNIT_MS.days);
}

function getMarketConfig() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "market_config") return Object.assign(defaultMarketConfig(), state.settings[i]);
    }
  }
  return defaultMarketConfig();
}

function saveMarketConfig(cfg) {
  cfg.id = "market_config";
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "market_config") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(cfg); else state.settings[idx] = cfg;
  save();
  saveDoc("settings", cfg);
  showToast(t("toast_market_display_updated"));
  render();
}

// ---------- MOTIF DE FOND : config + génération (canvas, côté navigateur) ----------
function defaultBgPatternConfig() {
  var icons = DEFAULT_BG_ICONS.slice(0, 10);
  while (icons.length < 10) icons.push(null);
  return {
    id: "bg_pattern_config",
    enabled: false, // le motif écailles Sounsouni (CSS) sert désormais de filigrane par défaut
    icons: icons,
    color: "#0a5c36",
    opacity: 0.8,
    iconSize: 22,
    tileSize: 420,
    density: 16,
    generatedPatternUri: null // rempli après génération par l'admin
  };
}

function getBgPatternConfig() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "bg_pattern_config") {
        var cfg = Object.assign({}, defaultBgPatternConfig(), state.settings[i]);
        if (!cfg.icons || cfg.icons.length < 10) {
          var ic = (cfg.icons || []).slice(0, 10);
          while (ic.length < 10) ic.push(null);
          cfg.icons = ic;
        }
        return cfg;
      }
    }
  }
  return defaultBgPatternConfig();
}

function saveBgPatternConfig(cfg) {
  cfg.id = "bg_pattern_config";
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "bg_pattern_config") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(cfg); else state.settings[idx] = cfg;
  save();
  saveDoc("settings", cfg);
  applyBgPattern();
  render();
}

// Applique (ou retire) le motif déjà généré comme fond de toute l'app.
// Appelé à chaque démarrage / mise à jour de la config — ne régénère rien,
// se contente d'appliquer l'image déjà calculée et stockée.
function applyBgPattern() {
  var cfg = getBgPatternConfig();
  if (cfg.enabled && cfg.generatedPatternUri) {
    document.documentElement.style.setProperty('--bg-pattern-image', 'url(' + cfg.generatedPatternUri + ')');
    document.documentElement.style.setProperty('--bg-pattern-size', cfg.tileSize + 'px');
    document.documentElement.classList.add('has-bg-pattern');
  } else {
    document.documentElement.classList.remove('has-bg-pattern');
  }
}

// Motif écailles Sounsouni : généré en JS avec la couleur du thème courante
// directement dans le SVG (au lieu de compter sur mask-image, dont le
// support est trop inégal sur les navigateurs mobiles réels) — un simple
// background-image, garanti de s'afficher partout.
// Opacité du motif écailles, réglable dans l'Admin (à côté du motif
// décoratif à icônes). Modeste par défaut — un vrai filigrane, pas un
// motif qui attire l'œil.
function getScaleMotifOpacity() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "scale_motif_opacity") return state.settings[i].data.value;
    }
  }
  return 0.08;
}

function saveScaleMotifOpacity(value) {
  var doc = { id: "scale_motif_opacity", data: { value: value } };
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "scale_motif_opacity") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(doc); else state.settings[idx] = doc;
  save();
  saveDoc("settings", doc);
}

function applyScaleMotif() {
  try {
    var primaryColor = getComputedStyle(document.documentElement).getPropertyValue('--primary').trim() || '#2e7d32';
    var op = getScaleMotifOpacity();
    var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="60" height="52" viewBox="0 0 60 52">' +
      '<path d="M0 20 Q15 0 30 20 Q15 40 0 20 Z" fill="none" stroke="' + primaryColor + '" stroke-width="1.2" stroke-opacity="' + op + '"/>' +
      '<path d="M30 20 Q45 0 60 20 Q45 40 30 20 Z" fill="none" stroke="' + primaryColor + '" stroke-width="1.2" stroke-opacity="' + op + '"/>' +
      '<path d="M15 46 Q30 26 45 46 Q30 66 15 46 Z" fill="none" stroke="' + primaryColor + '" stroke-width="1.2" stroke-opacity="' + op + '"/>' +
      '<path d="M-15 46 Q0 26 15 46 Q0 66 -15 46 Z" fill="none" stroke="' + primaryColor + '" stroke-width="1.2" stroke-opacity="' + op + '"/>' +
      '<path d="M45 46 Q60 26 75 46 Q60 66 45 46 Z" fill="none" stroke="' + primaryColor + '" stroke-width="1.2" stroke-opacity="' + op + '"/>' +
      '</svg>';
    var uri = 'url("data:image/svg+xml,' + encodeURIComponent(svg) + '")';
    document.documentElement.style.setProperty('--scale-motif', uri);
  } catch (e) {
    // Si quoi que ce soit échoue, on laisse simplement le motif absent
    // plutôt que de bloquer l'affichage du reste de l'app.
  }
}

function loadImageAsync(src) {
  return new Promise(function(resolve, reject) {
    var img = new Image();
    img.onload = function() { resolve(img); };
    img.onerror = reject;
    img.src = src;
  });
}

// Dessine une icône recolorée (silhouette noire -> couleur choisie) avec
// duplication sur les bords opposés si elle déborde, pour un motif qui se
// répète sans coupure visible une fois utilisé en background-repeat.
function drawIconWrapped(ctx, img, cx, cy, w, h, angle, tile, opacity) {
  function drawAt(x, y) {
    ctx.save();
    ctx.globalAlpha = opacity;
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.drawImage(img, -w / 2, -h / 2, w, h);
    ctx.restore();
  }
  var half = Math.max(w, h);
  var positions = [[cx, cy]];
  if (cx - half < 0) positions.push([cx + tile, cy]);
  if (cx + half > tile) positions.push([cx - tile, cy]);
  if (cy - half < 0) positions.push([cx, cy + tile]);
  if (cy + half > tile) positions.push([cx, cy - tile]);
  for (var i = 0; i < positions.length; i++) drawAt(positions[i][0], positions[i][1]);
}

// Génère le motif (grille + décalage aléatoire + rotation -15/+15) et
// renvoie une Promise résolue avec le data URI PNG obtenu. Appelé uniquement
// depuis l'écran Admin quand on sauvegarde la config — le résultat est
// ensuite stocké et partagé tel quel avec tous les comptes.
function generateBgPattern(cfg) {
  var activeIcons = cfg.icons.filter(function(u) { return !!u; });
  if (activeIcons.length === 0) return Promise.resolve(null);

  return Promise.all(activeIcons.map(loadImageAsync)).then(function(imgs) {
    // Recolore chaque icône une fois (silhouette noire -> couleur choisie)
    // via un canvas intermédiaire, pour ne pas re-teinter à chaque coup de pinceau.
    var tinted = imgs.map(function(img) {
      var c = document.createElement('canvas');
      c.width = img.width; c.height = img.height;
      var cx2 = c.getContext('2d');
      cx2.drawImage(img, 0, 0);
      cx2.globalCompositeOperation = 'source-in';
      cx2.fillStyle = cfg.color;
      cx2.fillRect(0, 0, c.width, c.height);
      return c;
    });

    var scale = 2; // rendu net (équivalent x2)
    var tile = cfg.tileSize;
    var canvas = document.createElement('canvas');
    canvas.width = tile * scale;
    canvas.height = tile * scale;
    var ctx = canvas.getContext('2d');
    ctx.scale(scale, scale);

    var N = cfg.density;
    var cell = tile / N;
    for (var gy = 0; gy < N; gy++) {
      for (var gx = 0; gx < N; gx++) {
        var icon = tinted[Math.floor(Math.random() * tinted.length)];
        var baseCx = (gx + 0.5) * cell;
        var baseCy = (gy + 0.5) * cell;
        var cx = baseCx + (Math.random() - 0.5) * cell * 0.55;
        var cy = baseCy + (Math.random() - 0.5) * cell * 0.55;
        var h = cfg.iconSize * (0.85 + Math.random() * 0.3);
        var w = h * (icon.width / icon.height);
        var angle = (Math.random() * 30 - 15) * Math.PI / 180;
        drawIconWrapped(ctx, icon, cx, cy, w, h, angle, tile, cfg.opacity);
      }
    }
    return canvas.toDataURL('image/png');
  });
}

// ---------- ESPACE PUBLICITAIRE VIP (bandeau du header) ----------
// Distinct du système de Boost : ici, c'est l'admin qui crée/gère chaque
// publicité pour le compte d'une entreprise (accord passé hors-app), pas
// un achat en libre-service par le vendeur.
function isVipAdActive(ad) {
  if (!ad.active) return false;
  var now = Date.now();
  if (ad.startDate && now < new Date(ad.startDate).getTime()) return false;
  if (ad.endDate && now > new Date(ad.endDate).getTime() + 86400000) return false;
  return true;
}

// ---------- CONFIG IMAGES DE MARQUE (filigrane inscription + bandeau marché) ----------
// Les deux images sont totalement indépendantes : chacune a sa propre
// photo, opacité, effet, et style de texte — réglables séparément en Admin.
// ---------- CONFIG STYLE DE SECTION (générique, réutilisable) ----------
// Système commun aux 6 zones personnalisables du marché : logo+marque,
// recommandations, étoiles catégories, autres vendeurs, à la une, bandeau
// Sougouba (déjà fait séparément). Chaque zone a son propre id de config.
// ---------- PERMISSIONS EMPLOYÉS (Groupe 2) ----------
// Deux réglages activables/désactivables par le Groupe 1 (le propriétaire)
// uniquement : approuver les demandes Livreur/Relais, et répondre aux
// messages. Tout le reste (modifier/supprimer/bannir) leur est fermé,
// sans exception, quel que soit ce réglage.
// ---------- INTÉGRATION PLATEFORME EXTERNE (colis internationaux) ----------
// Réglage réservé au Groupe 1 : quand activé, chaque changement de statut
// d'un colis externe est envoyé (webhook) à l'URL configurée par le
// partenaire — pour qu'ils reçoivent nos mises à jour sans qu'on ait à
// leur envoyer quoi que ce soit manuellement. Désactivé par défaut, et
// n'a aucun effet tant qu'aucune URL réelle n'est configurée.
// ---------- OPTION 4 : TABLEAU DE BORD PARTAGÉ (accès partenaire) ----------
// Un accès en lecture seule, avec ses propres identifiants (indépendants
// de l'Admin), donnant à un partenaire externe une vue de ses colis sans
// aucune connexion technique entre nos deux systèmes — la solution la
// plus simple à mettre en place, au prix de zéro automatisation.
// ---------- OPTION 4 (multi-partenaires) : TABLEAU DE BORD PARTAGÉ ----------
// Une liste, pas un réglage unique — chaque partenaire (Alibaba, Amazon...)
// a ses propres identifiants et ne voit jamais que ses propres colis
// (filtrés par plateforme), sans que rien ne se mélange entre eux.
function addDashboardPartner(platform) {
  var partner = { id: uid(), platform: platform, enabled: true, username: "", hasPassword: false };
  state.dashboardPartners.push(partner);
  save();
  saveDoc("dashboardPartners", partner);
  return partner;
}

function updateDashboardPartner(partner) {
  for (var i = 0; i < state.dashboardPartners.length; i++) {
    if (state.dashboardPartners[i].id === partner.id) { state.dashboardPartners[i] = partner; break; }
  }
  save();
  saveDoc("dashboardPartners", partner);
}

function removeDashboardPartner(id) {
  state.dashboardPartners = state.dashboardPartners.filter(function(p) { return p.id !== id; });
  save();
  deleteRemoteDoc("dashboardPartners", id);
}

