// Suggestion de quartiers via OpenStreetMap (Nominatim, gratuit, sans
// clé) — UNE SEULE FOIS par ville, ici côté admin, jamais en direct par
// les utilisateurs (limite de 1 requête/seconde du service gratuit).
// L'admin peut ensuite corriger la liste proposée avant de l'enregistrer.
// Suggestion de quartiers — via Mapbox si un jeton est configuré
// (MAPBOX_TOKEN, plus précis), sinon via OpenStreetMap (gratuit). Dans
// les deux cas : UNE SEULE FOIS par ville, côté admin, jamais en direct
// par les utilisateurs. L'admin peut ensuite corriger la liste proposée
// avant de l'enregistrer.
function fetchQuartierSuggestions(city, country, onDone) {
  var geoCfg = getGeocodingConfig();
  if (geoCfg.provider === "mapbox" && geoCfg.token) {
    fetchQuartierSuggestionsMapbox(city, country, geoCfg.token, onDone);
  } else {
    // Aucun service payant configuré, ou service inconnu — repli gratuit.
    // Pour ajouter un nouveau service plus tard : un nouveau
    // "else if (geoCfg.provider === '...')" ici, avec sa propre fonction
    // dédiée (même principe que fetchQuartierSuggestionsMapbox).
    fetchQuartierSuggestionsOSM(city, country, onDone);
  }
}

// Méthode Mapbox : géocode d'abord la ville pour trouver son contour,
// puis interroge la couche "neighborhood" de Mapbox à l'intérieur de ce
// contour — données curées, généralement plus complètes et plus fiables
// que la recherche brute par mot-clé sur OpenStreetMap.
function fetchQuartierSuggestionsMapbox(city, country, token, onDone) {
  var cityQuery = encodeURIComponent(city + ", " + country);
  fetch("https://api.mapbox.com/geocoding/v5/mapbox.places/" + cityQuery + ".json?types=place&limit=1&access_token=" + token)
    .then(function(res) { return res.json(); })
    .then(function(data) {
      var feature = data.features && data.features[0];
      if (!feature || !feature.bbox) { fetchQuartierSuggestionsOSM(city, country, onDone); return; }
      var bbox = feature.bbox.join(",");
      // Une recherche générique "quartier/neighborhood" limitée à la boîte
      // englobante de la ville trouvée — Mapbox n'a pas d'endpoint direct
      // "liste tous les quartiers de X", donc on procède comme pour OSM
      // mais avec des données Mapbox, nettement plus riches.
      fetch("https://api.mapbox.com/geocoding/v5/mapbox.places/quartier.json?types=neighborhood&bbox=" + bbox + "&limit=10&access_token=" + token)
        .then(function(res2) { return res2.json(); })
        .then(function(data2) {
          var names = [];
          var features2 = data2.features || [];
          for (var i = 0; i < features2.length; i++) {
            var name = features2[i].text;
            if (name && names.indexOf(name) === -1) names.push(name);
          }
          if (names.length === 0) { fetchQuartierSuggestionsOSM(city, country, onDone); return; }
          onDone(names);
        })
        .catch(function() { fetchQuartierSuggestionsOSM(city, country, onDone); });
    })
    .catch(function() { fetchQuartierSuggestionsOSM(city, country, onDone); });
}

// Méthode OpenStreetMap (gratuite) — en deux temps : d'abord Nominatim
// pour retrouver le contour administratif exact de la ville, puis
// Overpass pour lister TOUS les quartiers (place=suburb/neighbourhood/
// quarter) réellement recensés dans ce contour.
function fetchQuartierSuggestionsOSM(city, country, onDone) {
  var query = encodeURIComponent(city + ", " + country);
  fetch("https://nominatim.openstreetmap.org/search?q=" + query + "&format=json&limit=1")
    .then(function(res) { return res.json(); })
    .then(function(results) {
      if (!results || results.length === 0) { onDone([]); return; }
      var lat = results[0].lat, lon = results[0].lon;
      if (results[0].osm_type !== "relation") {
        fetchQuartierSuggestionsFallback(lat, lon, onDone);
        return;
      }
      var areaId = 3600000000 + parseInt(results[0].osm_id, 10);
      var overpassQuery = "[out:json][timeout:25];area(" + areaId + ")->.a;(node[\"place\"~\"suburb|neighbourhood|quarter|city_block\"](area.a);way[\"place\"~\"suburb|neighbourhood|quarter|city_block\"](area.a););out tags center;";
      fetch("https://overpass-api.de/api/interpreter", { method: "POST", body: "data=" + encodeURIComponent(overpassQuery) })
        .then(function(res2) { return res2.json(); })
        .then(function(data) {
          var names = [];
          var elements = data.elements || [];
          for (var i = 0; i < elements.length; i++) {
            var name = elements[i].tags && elements[i].tags.name;
            if (name && names.indexOf(name) === -1) names.push(name);
          }
          names.sort();
          if (names.length === 0) { fetchQuartierSuggestionsFallback(lat, lon, onDone); return; }
          onDone(names);
        })
        .catch(function() { fetchQuartierSuggestionsFallback(lat, lon, onDone); });
    })
    .catch(function() { onDone([]); showToast(t("toast_cannot_contact_osm")); });
}

// Solution de secours (ville sans contour administratif précis dans OSM)
// — moins complète, cherche simplement autour du centre-ville trouvé.
function fetchQuartierSuggestionsFallback(lat, lon, onDone) {
  fetch("https://nominatim.openstreetmap.org/search?q=quartier&format=json&limit=30&viewbox=" +
    (parseFloat(lon) - 0.15) + "," + (parseFloat(lat) + 0.15) + "," + (parseFloat(lon) + 0.15) + "," + (parseFloat(lat) - 0.15) +
    "&bounded=1&addressdetails=1")
    .then(function(res) { return res.json(); })
    .then(function(results) {
      var names = [];
      for (var i = 0; i < (results || []).length; i++) {
        var addr = results[i].address || {};
        var name = addr.suburb || addr.neighbourhood || addr.quarter || addr.residential;
        if (name && names.indexOf(name) === -1) names.push(name);
      }
      onDone(names);
    })
    .catch(function() { onDone([]); });
}

// ---------- COMMISSION POINT DE RETRAIT PAR PLATEFORME ----------
// Un montant fixe par colis, réglable indépendamment pour chaque
// plateforme — aucune valeur imposée tant qu'aucun accord réel n'est
// signé ; le réglage reste prêt pour le jour où ce sera le cas.
// ---------- IDENTIFIANTS ADMIN (modifiables) ----------
// Les identifiants des deux groupes restent stockés comme réglage,
// modifiable depuis l'Admin Groupe 1 — avec les valeurs d'origine comme
// valeurs par défaut tant que rien n'a été changé.
// Vrai si l'admin CONNECTÉ EN CE MOMENT a le droit de voir cet élément —
// c'est-à-dire soit c'est le Groupe 1 global (voit tout, tous pays), soit
// l'élément appartient au même pays que celui de l'admin national/employé
// national actuellement connecté. Un élément sans pays renseigné (ancien
// compte/commande d'avant l'ajout de ce champ) est toujours visible — on
// ne cache jamais une donnée par erreur de migration.
function inAdminScope(item) {
  if (!state.adminCountryScope) return true;
  if (!item || !item.country) return true;
  return item.country === state.adminCountryScope;
}

// --- Groupe 2 (accès limité) : liste blanche de numéros, sans mot de
// passe. Le Groupe 1 (global ou national) ajoute directement le numéro
// d'un compte Sounsouni existant — dès que cette personne est connectée
// avec CE numéro, elle peut basculer vers l'Admin sans rien saisir de
// plus. Retirer le numéro coupe l'accès à la prochaine tentative de
// bascule (une session déjà ouverte n'est pas interrompue en cours).
function isPhoneOnGroup2GlobalWhitelist(phone) {
  var norm = normalizeWalletPhone(phone);
  return (state.group2GlobalWhitelist || []).some(function(w) { return normalizeWalletPhone(w.phone) === norm; });
}
// --- Agent Sourcing (accès délégué) : même principe que le Groupe 2 —
// liste blanche de numéros, sans mot de passe — mais dans sa PROPRE liste,
// séparée du Groupe 2. Un numéro qui y figure bascule directement vers
// l'espace Agent Sourcing (jamais vers l'Admin), en tapant sur le même
// bouton "Administration" du menu Changer de rôle.
function isPhoneOnSourcingAgentWhitelist(phone) {
  var norm = normalizeWalletPhone(phone);
  return (state.sourcingAgentWhitelist || []).some(function(w) { return normalizeWalletPhone(w.phone) === norm; });
}
function findNationalAdminByEmployeePhone(phone) {
  var norm = normalizeWalletPhone(phone);
  for (var i = 0; i < (state.nationalAdmins || []).length; i++) {
    var na = state.nationalAdmins[i];
    if ((na.employeeWhitelist || []).some(function(w) { return normalizeWalletPhone(w.phone) === norm; })) return na;
  }
  return null;
}

function getAdminCredentials(group) {
  // Seul "owner" (Groupe 1) utilise encore un mot de passe — le Groupe 2
  // fonctionne uniquement par liste blanche de numéros (voir switchRole).
  // Aucun mot de passe ici : il est gardé et vérifié uniquement par le serveur.
  var defaults = { username: ADMIN_USERNAME };
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "admin_credentials_" + group) {
        return Object.assign({ id: "admin_credentials_" + group }, defaults, state.settings[i]);
      }
    }
  }
  return Object.assign({ id: "admin_credentials_" + group }, defaults);
}

function saveAdminCredentials(group, cfg) {
  cfg.id = "admin_credentials_" + group;
  delete cfg.password; // jamais de mot de passe en clair dans les réglages (lisibles par tous)
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "admin_credentials_" + group) { idx = i; break; }
  }
  if (idx === -1) state.settings.push(cfg); else state.settings[idx] = cfg;
  save();
  saveDoc("settings", cfg);
}

