// Envoie une mise à jour de statut au partenaire externe, si le webhook
// est activé et configuré. N'échoue jamais bruyamment — un partenaire
// injoignable ne doit jamais bloquer le travail du Point de Retrait.
function notifyExternalWebhook(parcel, eventType) {
  var matching = state.webhookPartners.filter(function(p) { return p.enabled && p.url && p.platform === parcel.platform; });
  if (matching.length === 0) return;
  var payload = {
    event: eventType,
    trackingNumber: parcel.trackingNumber,
    platform: parcel.platform,
    status: parcel.status,
    recipientName: parcel.recipientName,
    recipientPhone: parcel.recipientPhone,
    relaisShopName: parcel.relaisShopName,
    timestamp: new Date().toISOString()
  };
  matching.forEach(function(cfg) {
    fetch(supabaseConfig.url + "/functions/v1/call-webhook", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey },
      body: JSON.stringify({ partnerId: cfg.id, payload: payload })
    }).catch(function(err) {
      console.error("Webhook partenaire injoignable :", err);
    });
  });
}

function getEmployeePermissions() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "employee_permissions") return Object.assign({ id: "employee_permissions", canApprove: false, canReply: false }, state.settings[i]);
    }
  }
  return { id: "employee_permissions", canApprove: false, canReply: false };
}

function saveEmployeePermissions(perms) {
  perms.id = "employee_permissions";
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "employee_permissions") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(perms); else state.settings[idx] = perms;
  save();
  saveDoc("settings", perms);
}

