// Convertit une couleur hexadécimale (sortie d'un sélecteur <input type="color">)
// en triplet "R, G, B", pour l'utiliser dans un rgba(...) CSS.
function hexToRgbTriplet(hex) {
  if (!hex || hex.indexOf('#') !== 0) return hex; // déjà au format "R, G, B"
  var h = hex.replace('#', '');
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  var r = parseInt(h.substring(0, 2), 16);
  var g = parseInt(h.substring(2, 4), 16);
  var b = parseInt(h.substring(4, 6), 16);
  return r + ', ' + g + ', ' + b;
}

