// S'il y a plusieurs publicités actives, on les fait tourner (rotation
// configurable en Admin) plutôt que d'en figer une seule indéfiniment.
function getActiveVipAd() {
  var actives = state.vipAds.filter(isVipAdActive);
  if (actives.length === 0) return null;
  var cfg = getVipConfig();
  var ms = Math.max(2, cfg.rotationSeconds || 8) * 1000;
  var slot = Math.floor(Date.now() / ms) % actives.length;
  return actives[slot];
}

function getActiveVipAds() {
  return state.vipAds.filter(isVipAdActive);
}

// Approuve une demande Point de Retrait : transforme le compte Acheteur en
// vrai Point de Retrait actif, avec toutes les infos soumises, et prévient
// l'utilisateur avec un lien direct vers son nouvel espace.
// ---------- DEMANDE POUR DEVENIR LIVREUR ----------
// Contrairement à Point de Retrait, pas de champ supplémentaire à l'inscription
// : n'importe quel compte existant peut postuler depuis le menu de rôle.
// ---------- SOUMISSION : DEVENIR POINT DE RETRAIT (compte déjà existant) ----------
function submitBecomeRelais() {
  var d = state.relaisApplyDraft;
  // Empêche une double soumission (double-tap, ou nouvelle tentative
  // pendant qu'une demande est déjà en attente) — sans ça, deux fiches
  // quasi identiques se retrouvaient dans la liste "En attente", et
  // approuver l'une laissait l'autre trainer indéfiniment.
  if (state.profile.relaisApplicationStatus === "pending") {
    showToast(t("relais_apply_already_pending") || "Vous avez déjà une candidature Point de Retrait en attente d'examen.");
    return;
  }
  var alreadyPendingApp = state.relaisApplications.some(function(a) { return a.accountId === state.profile.id && a.status === "pending"; });
  if (alreadyPendingApp) {
    showToast(t("relais_apply_already_pending") || "Vous avez déjà une candidature Point de Retrait en attente d'examen.");
    return;
  }
  if (!state.profile.email && (!d.email || !d.email.trim())) {
    showToast(t("toast_email_required_pickup"));
    return;
  }
  if (!d.shopName || !d.shopName.trim()) {
    showToast(t("toast_shopname_required2"));
    return;
  }
  if (d.useAutreQuartier) {
    if (!d.autreQuartierNom || !d.autreQuartierNom.trim()) { showToast(t("toast_neighborhood_name_required")); return; }
    if (d.autreQuartierLat == null || d.autreQuartierLng == null) { showToast(t("toast_neighborhood_gps_required")); return; }
  } else {
    if (!d.commune) { showToast(t("toast_commune_required")); return; }
    if (!d.quartier) { showToast(t("toast_neighborhood_required")); return; }
  }
  if (d.shopLat == null || d.shopLng == null) {
    showToast("❌ Position GPS obligatoire — appuyez sur \"Localiser ma boutique\".");
    return;
  }
  if (!d.selfiePhotoUri) { showToast(t("toast_photo_required")); return; }
  if (!d.verificationDocs || d.verificationDocs.length === 0) { showToast(t("toast_doc_required")); return; }

  // Complète l'email sur le compte si celui-ci n'en avait pas encore.
  refreshProfileFromAccounts();
  if (!state.profile.email && d.email) {
    state.profile.email = d.email.trim();
  }
  state.profile.relaisApplicationStatus = "pending";
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === state.profile.id) { state.accounts[i] = { ...state.profile }; break; }
  }

  state.relaisApplications.push(application);

  if (d.useAutreQuartier) {
    var quartierApp = {
      id: uid(),
      accountId: state.profile.id,
      accountName: state.profile.name,
      country: state.profile.country || "Mali",
      quartierNom: d.autreQuartierNom.trim(),
      lat: d.autreQuartierLat,
      lng: d.autreQuartierLng,
      suggestedCommune: null,
      status: "pending",
      createdAt: Date.now()
    };
    state.autreQuartierApplications.push(quartierApp);
    saveDoc("autreQuartierApplications", quartierApp);
  }

  save();
  saveDoc("accounts", state.profile);
  // IMPORTANT : on attend que la fiche de candidature existe bien côté
  // serveur AVANT de tenter d'y attacher les coordonnées GPS — sinon
  // save_relais_application_location la refuse (elle vérifie que la
  // candidature existe déjà), et le GPS n'est alors jamais enregistré
  // du tout, sans qu'aucune erreur ne soit visible ensuite pour l'Admin
  // (juste "aucune localisation enregistrée" au moment de la révéler).
  var relaisSavePromise = saveDoc("relaisApplications", application);
  (relaisSavePromise || Promise.resolve()).then(function() {
    // Coordonnées GPS exactes et adresse détaillée — envoyées à part,
    // vers la collection protégée dédiée. Jamais dans
    // "relaisApplications" lui-même, qui reste largement synchronisé
    // pour les badges/listes.
    callAdminAccessOperation({
      operation: "save_relais_application_location",
      applicationId: application.id,
      shopLat: d.shopLat,
      shopLng: d.shopLng,
      autreQuartierLat: d.useAutreQuartier ? d.autreQuartierLat : null,
      autreQuartierLng: d.useAutreQuartier ? d.autreQuartierLng : null,
      addressDetail: d.addressDetail || ""
    });
  });
  // La vraie photo (selfie + pièce d'identité) ne transite jamais par
  // app_data — elle part directement vers la table protégée, jamais
  // visible que par un Admin qui confirme son mot de passe pour la voir.
  // Après l'enregistrement de la candidature : le serveur vérifie qu'elle est bien à nous.
  (relaisSavePromise || Promise.resolve()).then(function() { return submitVerificationDocuments("relais_app_" + application.id, d.selfiePhotoUri, d.verificationDocs); }).then(function(ok) {
    if (!ok) {
      application.hasVerificationDocs = false;
      saveDoc("relaisApplications", application);
      console.error("Échec de l'envoi sécurisé de la photo pour la candidature", application.id);
    }
  });
  state.view = "market";
  state.relaisApplyDraft = null;
  showToast(t("toast_request_sent_will_notify"));
  render();
}

// ---------- DEMANDE DE VÉRIFICATION DE BOUTIQUE (badge "compte vérifié") ----------
function applyForVerification() {
  if (state.profile.verified) { showToast(t("toast_shop_already_verified")); return; }
  if (state.profile.verificationStatus === "pending") { showToast(t("toast_request_pending")); return; }
  refreshProfileFromAccounts();
  state.profile.verificationStatus = "pending";
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === state.profile.id) { state.accounts[i] = { ...state.profile }; break; }
  }
  var request = {
    id: uid(),
    accountId: state.profile.id,
    accountName: state.profile.name,
    shopName: state.profile.shopName || state.profile.name,
    accountPhone: state.profile.phone,
    country: state.profile.country || "Mali",
    status: "pending",
    createdAt: Date.now()
  };
  state.verificationRequests.push(request);
  save();
  saveDoc("accounts", state.profile);
  saveDoc("verificationRequests", request);
  showToast(t("toast_verification_request_sent"));
  render();
}

function approveVerificationRequest(reqId) {
  var req = state.verificationRequests.find(function(r) { return r.id === reqId; });
  if (!req) return;
  if (!confirm('Approuver la vérification de "' + req.shopName + '" ?')) return;
  var account = null;
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === req.accountId) { account = state.accounts[i]; break; }
  }
  if (!account) { showToast(t("toast_account_not_found")); return; }
  account.verified = true;
  account.verificationStatus = "approved";
  if (state.profile && state.profile.id === account.id) state.profile = { ...account };
  req.status = "approved";
  req.resolvedAt = Date.now();
  save();
  saveDoc("accounts", account);
  saveDoc("verificationRequests", req);
  addNotification("whatsapp", "🛡️ Votre boutique \"" + (account.shopName || account.name) + "\" est maintenant vérifiée !", account.id, "verification");
  showToast(t("toast_shop_verified"));
  render();
}

function rejectVerificationRequest(reqId) {
  var req = state.verificationRequests.find(function(r) { return r.id === reqId; });
  if (!req) return;
  if (!confirm('Refuser cette demande de vérification ?')) return;
  var account = null;
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === req.accountId) { account = state.accounts[i]; break; }
  }
  if (account) {
    account.verificationStatus = "rejected";
    if (state.profile && state.profile.id === account.id) state.profile = { ...account };
    saveDoc("accounts", account);
  }
  req.status = "rejected";
  req.resolvedAt = Date.now();
  save();
  saveDoc("verificationRequests", req);
  addNotification("whatsapp", "Votre demande de vérification n'a pas été approuvée pour le moment. Vous pouvez réessayer plus tard.", req.accountId, "verification");
  showToast(t("toast_request_refused"));
  render();
}

