function approveRelaisApplication(appId) {
  var app = null;
  for (var i = 0; i < state.relaisApplications.length; i++) {
    if (state.relaisApplications[i].id === appId) { app = state.relaisApplications[i]; break; }
  }
  if (!app) return;
  if (!confirm("Approuver cette demande et activer le Point de Retrait \"" + app.shopName + "\" ?")) return;

  var account = null;
  for (var j = 0; j < state.accounts.length; j++) {
    if (state.accounts[j].id === app.accountId) { account = state.accounts[j]; break; }
  }
  if (!account) { showToast(t("toast_account_not_found")); return; }

  // Les coordonnées GPS exactes et l'adresse détaillée vivent à part
  // (voir save_relais_application_location) — on les récupère ici pour
  // les copier sur le compte, qui DEVIENT public une fois approuvé :
  // les clients doivent pouvoir trouver ce point de retrait.
  callAdminAccessOperation({ operation: "get_relais_application_location", applicationId: appId }).then(function(res) {
    var loc = res.success ? res.location : null;

    account.role = "point_vente";
    account.relaisApplicationStatus = "approved";
    account.shopName = app.shopName;
    account.commune = app.commune;
    account.quartier = app.quartier;
    account.addressDetail = loc ? loc.addressDetail : "";
    account.shopLat = loc ? loc.shopLat : null;
    account.shopLng = loc ? loc.shopLng : null;

    if (state.profile && state.profile.id === account.id) state.profile = { ...account };

    app.status = "approved";
    app.resolvedAt = Date.now();

    save();
    saveDoc("accounts", account);
    saveDoc("relaisApplications", app);
    addNotification("whatsapp", "🎉 Votre Point de Retrait \"" + app.shopName + "\" a été approuvé ! Ouvrez le menu de rôle pour y accéder.", account.id, "pointvente");
    showToast(t("toast_pickup_approved"));
    render();
  });
}

