// Crée une demande de boost pour un produit/service précis ou toute la
// boutique. Selon le mode configuré par l'admin : activation immédiate
// ("auto"), ou mise en attente de confirmation ("manual"/"api" pour l'instant,
// "api" se comportera comme "manual" tant que le paiement réel n'est pas branché).
function activateBoost(targetType, targetId, tierIndex) {
  if (!state.profile) return;
  var cfg = getBoostConfig();
  var tiers = targetType === "shop" ? cfg.shopTiers : cfg.itemTiers;
  var tier = tiers[tierIndex];
  if (!tier) { showToast(t("toast_invalid_plan")); return; }

  var boost = {
    id: uid(),
    targetType: targetType, // "product" | "shop"
    targetId: targetId,
    sellerId: state.profile.id,
    sellerName: state.profile.shopName || state.profile.name,
    country: state.profile.country || "Mali",
    days: tier.days,
    price: tier.price,
    mode: cfg.mode,
    status: cfg.mode === "auto" ? "actif" : "en_attente",
    createdAt: Date.now(),
    activatedAt: cfg.mode === "auto" ? Date.now() : null,
    expiresAt: cfg.mode === "auto" ? (Date.now() + tier.days * 86400000) : null
  };

  state.boosts.push(boost);
  save();
  saveDoc("boosts", boost);
  state.showBoostModal = false;

  if (cfg.mode === "auto") {
    showToast(t("dt_boost_activated") + tier.days + t("dt_days_suffix"));
  } else if (cfg.mode === "api" && ligdicashEnabled(state.profile.country || "Mali")) {
    startLigdicashPayment({ kind: "boost", boostId: boost.id });
  } else {
    showToast(t("toast_request_sent_awaiting_payment"));
  }
  render();
}

function isBoostActive(b) {
  return b.status === "actif" && b.expiresAt && b.expiresAt > Date.now();
}

// Un produit est "boosté" si lui-même a un boost actif, ou si toute sa
// boutique (son vendeur) a un boost actif de type "shop".
function isProductBoosted(product) {
  for (var i = 0; i < state.boosts.length; i++) {
    var b = state.boosts[i];
    if (!isBoostActive(b)) continue;
    if (b.targetType === "product" && b.targetId === product.id) return true;
    if (b.targetType === "shop" && b.sellerId === product.sellerId) return true;
  }
  return false;
}

// Mélange légèrement l'ordre des éléments boostés à chaque appel (rotation
// équitable) sans changer la position des éléments non boostés — ils restent
// triés par pertinence normale, seuls les boostés remontent en tête.
function applyBoostOrdering(products) {
  var boosted = [];
  var rest = [];
  for (var i = 0; i < products.length; i++) {
    if (isProductBoosted(products[i])) boosted.push(products[i]); else rest.push(products[i]);
  }
  for (var j = boosted.length - 1; j > 0; j--) {
    var k = Math.floor(Math.random() * (j + 1));
    var tmp = boosted[j]; boosted[j] = boosted[k]; boosted[k] = tmp;
  }
  return boosted.concat(rest);
}

// Construit le marché entier selon la formule décidée : trié par
// pertinence personnelle avec une marge de découverte mélangée dedans, et
// le boost injecté par-dessus à un rythme contrôlé, avec un équilibre
// ciblé/public large — tout réglable en Admin (getAlgorithmConfig).
function sortMarketWithAlgorithm(products) {
  var cfg = getAlgorithmConfig();
  var seed = window._marketVisitSeed || 0;
  // Petit nombre pseudo-aléatoire stable pour CETTE visite (même ordre tant
  // qu'on ne quitte pas le marché, nouvel ordre à la visite suivante).
  function visitJitter(id) {
    // Mélange solide (FNV-1a + brassage) : deux identifiants proches
    // (P070 / P080) donnent des ordres vraiment différents à chaque visite.
    var str = id + "|" + seed, h = 2166136261;
    for (var vi = 0; vi < str.length; vi++) { h ^= str.charCodeAt(vi); h = Math.imul(h, 16777619); }
    h ^= h >>> 13; h = Math.imul(h, 0x5bd1e995); h ^= h >>> 15;
    return h >>> 0;
  }
  // Un boost d'ARTICLE = 1 place sponsorisée. Un boost de BOUTIQUE = 1 place
  // aussi, avec un article différent de la boutique à chaque visite. Avant,
  // une boutique boostée de 60 articles prenait la moitié du haut du marché
  // (toujours les mêmes 10 articles), et écrasait les articles boostés seuls.
  var productBoostIds = {}, shopBoostSellers = {};
  (state.boosts || []).forEach(function(b) {
    if (!isBoostActive(b)) return;
    if (b.targetType === "product") productBoostIds[b.targetId] = true;
    else if (b.targetType === "shop") shopBoostSellers[b.sellerId] = true;
  });
  var inStock = [], outOfStock = [];
  for (var i = 0; i < products.length; i++) {
    if (products[i].stock != null && Number(products[i].stock) <= 0) outOfStock.push(products[i]); else inStock.push(products[i]);
  }
  var slots = [], usedInSlot = {};
  inStock.forEach(function(p) { if (productBoostIds[p.id]) { slots.push(p); usedInSlot[p.id] = true; } });
  Object.keys(shopBoostSellers).forEach(function(sid) {
    var pool = inStock.filter(function(p) { return p.sellerId === sid && !usedInSlot[p.id]; });
    if (!pool.length) return;
    pool.sort(function(x, y) { return visitJitter(x.id) - visitJitter(y.id); });
    slots.push(pool[0]); usedInSlot[pool[0].id] = true;
  });
  slots.sort(function(x, y) { return visitJitter(x.id) - visitJitter(y.id); });
  var scores = computeRelevanceScores(state.profile);
  var normal = inStock.filter(function(p) { return !usedInSlot[p.id]; });
  // Un peu de hasard ajouté à chaque visite (0 à 4 points) : un article un
  // peu moins bien noté passe parfois devant — chaque article a sa chance,
  // sans que l'ordre change pendant qu'on fait défiler.
  var eff = {};
  normal.forEach(function(p) { eff[p.id] = (scores[p.id] || 0) + (visitJitter(p.id) % 1000) / 250; });
  normal.sort(function(x, y) { return eff[y.id] - eff[x.id]; });
  var normalIds = interleaveDiscovery(normal.map(function(p) { return p.id; }), normal.map(function(p) { return p.id; }), cfg.marketDiscoveryRatio);
  var byId = {};
  normal.forEach(function(p) { byId[p.id] = p; });
  var ordered = normalIds.map(function(id) { return byId[id]; }).filter(Boolean);
  // Diversité : jamais plus de 2 articles de la même boutique d'affilée —
  // une boutique qui a beaucoup d'articles ne peut plus remplir tout l'écran.
  var spread = [], waiting = ordered.slice();
  while (waiting.length) {
    var pick = 0;
    for (var w = 0; w < waiting.length; w++) {
      var n1 = spread[spread.length - 1], n2 = spread[spread.length - 2];
      if (!(n1 && n2 && n1.sellerId === waiting[w].sellerId && n2.sellerId === waiting[w].sellerId)) { pick = w; break; }
    }
    spread.push(waiting.splice(pick, 1)[0]);
  }
  // Places sponsorisées réparties régulièrement (toutes présentes à chaque visite).
  var result = spread;
  if (slots.length) {
    var spacing = Math.max(1, Math.min(cfg.boostInjectionRate, Math.floor(result.length / (slots.length + 1)) || 1));
    var pos = Math.min(2, result.length);
    for (var bi = 0; bi < slots.length; bi++) {
      var at = Math.min(pos, result.length);
      // évite de coller 3 articles de la même boutique
      var sameAt = function(k) { return result[k] && result[k].sellerId === slots[bi].sellerId; };
      while (at < result.length && ((sameAt(at - 1) && sameAt(at - 2)) || (sameAt(at - 1) && sameAt(at)) || (sameAt(at) && sameAt(at + 1)))) at++;
      result.splice(at, 0, slots[bi]);
      pos = at + spacing + 1;
    }
  }
  // Les articles en rupture de stock restent visibles, mais en bas.
  return result.concat(outOfStock);
}

// Identifiant partagé pour les notifications/messages livreur — l'accès
