// Position d'un statut dans le parcours complet d'une commande, qu'elle soit
// Express (pas de "En boutique") ou Point de Retrait (avec "En boutique" entre
// "En route" et "Livrée"). Sert à comparer/trier sans se soucier du flux
// exact utilisé par la commande.
function statusProgressIndex(status) {
  var idxIntl = INTERNATIONAL_STATUS_FLOW.indexOf(status);
  if (idxIntl !== -1) return idxIntl;
  var idx = RELAIS_STATUS_FLOW.indexOf(status);
  return idx === -1 ? 0 : idx;
}

