  EMBEDDED_IMG_ORIGINALS.STAR_FRAME_IMG = STAR_FRAME_IMG; STAR_FRAME_IMG = toBlobUrl(STAR_FRAME_IMG);
  EMBEDDED_IMG_ORIGINALS.SOUNSOUNI_SPLASH_IMG = SOUNSOUNI_SPLASH_IMG; SOUNSOUNI_SPLASH_IMG = toBlobUrl(SOUNSOUNI_SPLASH_IMG);
  EMBEDDED_IMG_ORIGINALS.SOUNSOUNI_HEADER_ICON = SOUNSOUNI_HEADER_ICON; SOUNSOUNI_HEADER_ICON = toBlobUrl(SOUNSOUNI_HEADER_ICON);
  EMBEDDED_IMG_ORIGINALS.SOUNSOUNI_BASKET_LOGO = SOUNSOUNI_BASKET_LOGO; SOUNSOUNI_BASKET_LOGO = toBlobUrl(SOUNSOUNI_BASKET_LOGO);
