  EMBEDDED_IMG_ORIGINALS.SOUNSOUNI_ONBOARD_COLLAGE = SOUNSOUNI_ONBOARD_COLLAGE; SOUNSOUNI_ONBOARD_COLLAGE = toBlobUrl(SOUNSOUNI_ONBOARD_COLLAGE);
  EMBEDDED_IMG_ORIGINALS.SOUNSOUNI_CART_LOGO = SOUNSOUNI_CART_LOGO; SOUNSOUNI_CART_LOGO = toBlobUrl(SOUNSOUNI_CART_LOGO);
  EMBEDDED_IMG_ORIGINALS.SOUNSOUNI_INTRO_IMG_1 = SOUNSOUNI_INTRO_IMG_1; SOUNSOUNI_INTRO_IMG_1 = toBlobUrl(SOUNSOUNI_INTRO_IMG_1);
  EMBEDDED_IMG_ORIGINALS.SOUNSOUNI_INTRO_IMG_2 = SOUNSOUNI_INTRO_IMG_2; SOUNSOUNI_INTRO_IMG_2 = toBlobUrl(SOUNSOUNI_INTRO_IMG_2);
  EMBEDDED_IMG_ORIGINALS.SOUNSOUNI_INTRO_IMG_3 = SOUNSOUNI_INTRO_IMG_3; SOUNSOUNI_INTRO_IMG_3 = toBlobUrl(SOUNSOUNI_INTRO_IMG_3);
  EMBEDDED_IMG_ORIGINALS.SOUNSOUNI_REG_TOP_BANNER = SOUNSOUNI_REG_TOP_BANNER; SOUNSOUNI_REG_TOP_BANNER = toBlobUrl(SOUNSOUNI_REG_TOP_BANNER);
