    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "quartiers_proches_overrides") {
        return state.settings[i].data || JSON.parse(JSON.stringify(BAMAKO_QUARTIERS_PROCHES));
      }
    }
