// Pays qui utilisent le Franc CFA (XOF) — aucune conversion nécessaire
// entre eux, contrairement aux autres pays de la liste ci-dessus.
const CFA_COUNTRIES = ['Mali', 'Sénégal', 'Côte d\'Ivoire', 'Burkina Faso', 'Niger'];

// Indicatifs africains de la liste ci-dessus — sert à distinguer un
// vendeur "local" (Afrique de l'Ouest, où l'app opère déjà normalement)
// d'un vendeur véritablement à l'étranger (ex : Inde), pour qui seul le
// parcours "Vendeur International" a du sens (voir renderOnboardStepVendorType).
// "+XXX" (Autre) est volontairement exclu : ce code couvre n'importe quel
// pays non listé, donc potentiellement hors Afrique.
const AFRICAN_COUNTRY_CODES = ['+223', '+221', '+225', '+226', '+224', '+227', '+220', '+234', '+232'];

// Les gens à l'étranger tapent souvent leur numéro avec le 0 du pays
// (ex : France 06 12 34 56 78) : on retire ce 0 devant l'indicatif.
// Jamais pour les pays d'Afrique de l'Ouest déjà en place (inchangés).
function stripTrunkZero(code, digits) {
  digits = String(digits || "").replace(/\D/g, "");
  if (isAfricanCountryCode(code) || code === "+XXX" || code === "+39" || code === "+229") return digits; // Italie, Bénin : le 0 fait partie du numéro
  return digits.length > 6 && digits.charAt(0) === "0" ? digits.slice(1) : digits;
}

function isAfricanCountryCode(code) {
  return AFRICAN_COUNTRY_CODES.indexOf(code || '+223') !== -1;
}

function countryForCode(code) {
  for (var i = 0; i < COUNTRY_CODES.length; i++) {
    if (COUNTRY_CODES[i].code === code) return COUNTRY_CODES[i].country;
  }
  return 'Mali';
}

function currencyForCountry(country) {
  for (var i = 0; i < COUNTRY_CODES.length; i++) {
    if (COUNTRY_CODES[i].country === country) return COUNTRY_CODES[i].currency;
  }
  return 'XOF';
}

// Libellé du champ prix à la publication, avec la VRAIE devise du vendeur
// (ex : "Prix (INR)" pour un compte indien) au lieu de "FCFA" toujours
// affiché en dur, alors que le prix qu'il tape est bien dans sa devise —
// la conversion d'affichage sur le marché existe déjà (voir money()),
// mais le formulaire de publication, lui, n'avait jamais suivi.
function publishPriceLabel() {
  var currency = currencyForCountry(state.profile ? state.profile.country : null);
  return t("publish_price_word") + " (" + currency + ")";
}

