const SEED_PRODUCTS = [];

// ---------- STATE ----------
const STORAGE_KEY = "gems_demo_state_v7";

// ---------- STOCKAGE LOCAL — IndexedDB, plus vraiment localStorage ----------
// localStorage a une limite fixe et minuscule sur certains téléphones
// (quelques Mo, parfois moins), sans rapport avec l'espace réel
// disponible sur l'appareil — c'est ce qui causait les erreurs "stockage
// plein" même avec moins d'1 Mo de données. IndexedDB suit les vraies
// limites de l'appareil (souvent plusieurs Go), exactement comme
// Firebase/Supabase le font déjà pour leur propre cache. Supabase reste
// dans tous les cas la vraie source des données — ceci n'est qu'une copie
// locale pour un rechargement plus rapide.
const IDB_NAME = "sounsouni_local";
const IDB_STORE = "kv";
var _idbInstance = null;

function idbOpen() {
  if (_idbInstance) return Promise.resolve(_idbInstance);
  return new Promise(function(resolve, reject) {
    if (!window.indexedDB) { reject(new Error("IndexedDB indisponible")); return; }
    var req = indexedDB.open(IDB_NAME, 1);
    req.onupgradeneeded = function() {
      if (!req.result.objectStoreNames.contains(IDB_STORE)) req.result.createObjectStore(IDB_STORE);
    };
    req.onsuccess = function() { _idbInstance = req.result; resolve(_idbInstance); };
    req.onerror = function() { reject(req.error); };
  });
}

function idbGet(key) {
  return idbOpen().then(function(db) {
    return new Promise(function(resolve, reject) {
      var tx = db.transaction(IDB_STORE, "readonly");
      var req = tx.objectStore(IDB_STORE).get(key);
      req.onsuccess = function() { resolve(req.result); };
      req.onerror = function() { reject(req.error); };
    });
  });
}

function idbSet(key, value) {
  return idbOpen().then(function(db) {
    return new Promise(function(resolve, reject) {
      var tx = db.transaction(IDB_STORE, "readwrite");
      tx.objectStore(IDB_STORE).put(value, key);
      tx.oncomplete = function() { resolve(); };
      tx.onerror = function() { reject(tx.error); };
    });
  });
}

