let state = defaultState();

// ---------- CAPTURE D'ERREURS POUR L'ÉCRAN ADMIN > TEST ----------
// Sans accès à un ordinateur, impossible d'ouvrir la Console du
// navigateur pour voir ce qui plante — donc l'app capte elle-même tout
// ce qui se passe (erreurs JS, promesses rejetées, console.error) et le
// garde en mémoire, consultable et copiable depuis Admin > Test.
// Une clé de session ne doit JAMAIS apparaître dans le journal ni dans un
// rapport copié (il circule par WhatsApp) : on la remplace par « [clé masquée] ».
function maskSecrets(txt) {
  return String(txt || "").replace(/eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g, "[clé masquée]");
}
function pushDebugLog(type, message, detail) {
  if (!state.debugLoggingEnabled) return;
  try {
    state.debugLog = state.debugLog || [];
    state.debugLog.unshift({ type: type, message: maskSecrets(message), detail: detail ? maskSecrets(detail) : "", at: Date.now() });
    // Jamais plus de 200 entrées — sinon ça grossirait indéfiniment dans
    // le stockage local d'un téléphone qui reste connecté des jours.
    if (state.debugLog.length > 200) state.debugLog.length = 200;
    save();
    // Jamais pendant la gestion d'une erreur d'affichage : sinon boucle
    // (l'affichage plante -> on note l'erreur -> on redessine -> il replante...).
    if (state.view === "admin" && state.adminTab === "test" && !window._handlingRenderError) render();
    // Envoi au serveur (best-effort, jamais bloquant) pour que l'Admin
    // puisse voir les erreurs de N'IMPORTE QUEL compte à distance — voir
    // Admin > Test > "Erreurs récentes". Seulement les vraies erreurs
    // (pas les traces "info" routinières, pour ne pas saturer), et
    // jamais de console.error ici pour éviter une boucle si cet envoi
    // lui-même échoue.
    if ((type === "error" || type === "promise" || type === "console.error") && typeof FIREBASE_ENABLED !== "undefined" && FIREBASE_ENABLED && typeof sb !== "undefined" && sb) {
      sb.from("app_data").upsert({
        collection: "clientErrorLogs",
        id: "log-" + Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
        data: {
          accountId: (state.profile && state.profile.id) || null,
          accountName: (state.profile && (state.profile.shopName || state.profile.name)) || null,
          type: type,
          message: String(message || ""),
          detail: detail ? String(detail) : "",
          at: Date.now()
        },
        updated_at: new Date().toISOString()
      }, { onConflict: "collection,id" }).catch(function() { /* best-effort, silencieux */ });
    }
  } catch (e) { /* la capture elle-même ne doit jamais faire planter l'app */ }
}
window.addEventListener("error", function(e) {
  pushDebugLog("error", e.message, (e.error && e.error.stack) || (e.filename + ":" + e.lineno + ":" + e.colno));
});
window.addEventListener("unhandledrejection", function(e) {
  var reason = e.reason;
  pushDebugLog("promise", (reason && reason.message) || String(reason), reason && reason.stack);
});
(function() {
  var origConsoleError = console.error;
  console.error = function() {
    origConsoleError.apply(console, arguments);
    try {
      var parts = Array.prototype.slice.call(arguments).map(function(a) {
        if (typeof a === "string") return a;
        try { return JSON.stringify(a); } catch (e2) { return String(a); }
      });
      pushDebugLog("console.error", parts.join(" "));
    } catch (e3) { /* ignore */ }
  };
})();

// Le "profil" affiché à l'écran est une COPIE séparée du compte, prise au
// moment de la connexion — elle ne se met pas à jour toute seule quand un
// changement arrive d'ailleurs sur ce même compte pendant que la session
// reste ouverte (ex: une approbation Admin pendant qu'on est déjà connecté
// en tant que Point de Retrait). Sans ce rafraîchissement, la prochaine action
// qui resauvegarde le profil (changer de rôle, ajouter un favori…) écrase
// le changement distant avec l'ancienne copie encore en mémoire ici — et
// c'est exactement ce qui annulait silencieusement les approbations de
// Point de Retrait. On rappelle donc cette fonction chaque fois que des
// données fraîches arrivent du serveur.
function refreshProfileFromAccounts() {
  if (!state.profile) return;
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === state.profile.id) {
      state.profile = { ...state.accounts[i] };
      break;
    }
  }
}

// Charge l'état local — IndexedDB en priorité ; si rien n'y est encore
// trouvé (première fois avec cette nouvelle version), reprend l'ancienne
// sauvegarde localStorage si elle existe, pour ne perdre aucune donnée
// lors de la transition, puis la migre vers IndexedDB.
function loadStateAsync() {
  return idbGet(STORAGE_KEY).then(function(saved) {
    if (saved) return mergeWithDefaults(saved);
    var raw = null;
    try { raw = localStorage.getItem(STORAGE_KEY); } catch (e) {}
    if (raw) {
      try {
        var parsed = JSON.parse(raw);
        idbSet(STORAGE_KEY, parsed).catch(function() {}); // migration best-effort, silencieuse
        return mergeWithDefaults(parsed);
      } catch (e) {}
    }
    return null;
  }).catch(function() {
    // IndexedDB totalement indisponible (rare) — repli sur l'ancien
    // comportement localStorage plutôt que de bloquer le démarrage.
    try {
      var raw2 = localStorage.getItem(STORAGE_KEY);
      if (raw2) return mergeWithDefaults(JSON.parse(raw2));
    } catch (e) {}
    return null;
  });
}

function mergeWithDefaults(saved) {
  var d = defaultState();
  var merged = { ...d, ...saved };
  // Un message-éclair resté coincé d'une session précédente (avant ce
  // correctif) ne doit jamais resurgir au chargement.
  merged.toastMsg = null;
  // Aucune fenêtre ("show...") ne doit rester ouverte au démarrage, même
  // si c'était le cas au moment où la page a été quittée la dernière
  // fois — sinon le tout premier écran affiché EST cette fenêtre, sans
  // qu'aucune étape ne soit ajoutée à l'historique du navigateur pour
  // elle (voir syncHistoryForNav : le tout premier rendu ne fait que
  // "remplacer" l'étape actuelle, jamais en ajouter une). La fermer
  // déclenchait alors un vrai retour en arrière du navigateur — donc on
  // quittait carrément l'app au lieu de simplement fermer la fenêtre.
  for (var _showKey in merged) {
    if (_showKey.indexOf("show") === 0 && typeof merged[_showKey] === "boolean") {
      merged[_showKey] = d[_showKey];
    }
  }
  // Même chose pour la visionneuse de photo (lightbox) et la demande de
  // mot de passe Admin pour les documents sensibles — leurs noms ne
  // commencent pas par "show", donc elles échappaient au filet ci-dessus
  // et pouvaient rester "ouvertes" au tout premier écran après un
  // rechargement, avec exactement le même souci de retour en arrière.
  merged.lightboxOpen = false;
  merged.lightboxImages = [];
  merged.showDocPasswordModal = false;
  merged.pendingDocKeyForPassword = null;
  merged.pendingPartnerSecretRequest = null;
  merged.pendingFilatureLogRequest = null;
  merged.docPasswordDraft = "";
  merged.docPasswordError = null;
  // Même chose pour le suivi des articles déjà montrés dans le carrousel
  // intercalé du marché — sans ce repli, cette liste ne faisait que
  // grandir, session après session, jusqu'à finir par couvrir tout le
  // catalogue et empêcher le carrousel de jamais réapparaître.
  merged._inlineRecoShownIds = [];
  merged._lastMarketSignature = null;
  merged.checkoutForm = { ...d.checkoutForm, ...(saved.checkoutForm || {}) };
  merged.marketFilters = { ...d.marketFilters, ...(saved.marketFilters || {}) };
  merged.onboardDraft = { ...d.onboardDraft, ...(saved.onboardDraft || {}) };
  merged.productDraft = { ...d.productDraft, ...(saved.productDraft || {}) };
  merged.adminStats = { ...d.adminStats, ...(saved.adminStats || {}) };
  merged.seasonalEffects = { ...d.seasonalEffects, ...(saved.seasonalEffects || {}) };
  if (!Array.isArray(merged.productDraft.images)) merged.productDraft.images = [];
  if (!Array.isArray(merged.products) || merged.products.length === 0) merged.products = d.products;
  if (!Array.isArray(merged.cart)) merged.cart = [];
  if (Array.isArray(merged.orders)) merged.orders = merged.orders.filter(function(o) { return o && typeof o === "object"; }).map(normalizeOrderDoc);
  // Une demande de connexion "visiteur" ne doit jamais survivre à un
  // rechargement : on revient toujours aux articles.
  merged.guestAuthRequested = false;
  merged.showGuestAuthPrompt = false;
  if (!Array.isArray(merged.orders)) merged.orders = [];
  if (!Array.isArray(merged.notifications)) merged.notifications = [];
  if (!Array.isArray(merged.accounts)) merged.accounts = [];
  // Migration : tout compte créé avant l'ajout du champ pays devient
  // "Mali" par défaut (c'était le seul pays disponible jusque-là).
  for (var _mi = 0; _mi < merged.accounts.length; _mi++) {
    if (!merged.accounts[_mi].country) merged.accounts[_mi].country = "Mali";
  }
  if (!Array.isArray(merged.conversations)) merged.conversations = [];
  if (!Array.isArray(merged.reviews)) merged.reviews = [];
  if (!Array.isArray(merged.settings)) merged.settings = [];
  if (!Array.isArray(merged.bookings)) merged.bookings = [];
  if (!Array.isArray(merged.boosts)) merged.boosts = [];
  if (!Array.isArray(merged.disputes)) merged.disputes = [];
  if (!Array.isArray(merged.adminConversations)) merged.adminConversations = [];
  if (!Array.isArray(merged.relaisApplications)) merged.relaisApplications = [];
  if (!Array.isArray(merged.livreurApplications)) merged.livreurApplications = [];
  if (!Array.isArray(merged.autreQuartierApplications)) merged.autreQuartierApplications = [];
  if (!Array.isArray(merged.relaisEditRequests)) merged.relaisEditRequests = [];
  if (!Array.isArray(merged.verificationRequests)) merged.verificationRequests = [];
  if (!Array.isArray(merged.vipAds)) merged.vipAds = [];
  if (typeof merged.activeImageIndex !== "number") merged.activeImageIndex = 0;
  if (!["green-yellow", "orange-white", "red-white"].includes(merged.theme)) merged.theme = "green-yellow";
  if (!["dashboard", "sellers", "products", "effects", "affiliate", "reviews", "pointsvente", "tarifs", "boosts", "accounts", "disputes", "marketdisplay", "textes", "vipads", "bgpattern", "relaisapplications", "quartiers", "livreurapplications", "messagerie"].includes(merged.adminTab)) merged.adminTab = "dashboard";
  return merged;
}

var _localSaveQuotaWarned = false; // n'affiche un message qu'une seule fois par session, si jamais même IndexedDB échoue (très rare — voir plus bas)

function save() {
  var localCopy = {};
  for (var k in state) {
    // toastMsg est un message éclair (2,6s) — jamais persisté, sinon il
    // resurgit au prochain chargement si save() tombe juste avant qu'il
    // ne s'efface tout seul.
    if (k === "toastMsg") continue;
    // Même chose pour les fenêtres/visionneuses ouvertes à l'instant T :
    // une photo ou une demande de mot de passe restée ouverte ne doit
    // jamais "revenir" toute seule à la prochaine ouverture de l'app —
    // sans ça, fermer cette fenêtre fantôme n'a plus rien à faire en
    // interne, et le téléphone retombe sur un retour en arrière classique
    // du navigateur (vers la dernière vraie page visitée avant l'app).
    if (k === "lightboxOpen" || k === "lightboxImages" || k === "lightboxIndex" ||
        k === "showDocPasswordModal" || k === "pendingDocKeyForPassword" || k === "pendingPartnerSecretRequest" || k === "pendingFilatureLogRequest" ||
        k === "docPasswordDraft" || k === "docPasswordError") continue;
    localCopy[k] = state[k];
  }
  // IndexedDB stocke l'objet directement (pas besoin de JSON.stringify) et
  // suit les vraies limites d'espace de l'appareil, pas une limite fixe et
  // minuscule comme l'ancien localStorage.
  idbSet(STORAGE_KEY, localCopy).catch(function(e) {
    console.error("Échec de sauvegarde locale :", e);
    // IMPORTANT : ne jamais réécrire une version tronquée ici en cas
    // d'échec — une écriture ratée laisse la DERNIÈRE sauvegarde réussie
    // intacte. Écrire un objet partiel "de secours" écraserait cette bonne
    // version avec une quasi-vide, ce qui a déjà causé une vraie perte de
    // données (retour à l'inscription, photos disparues) — sans danger de
    // continuer sans nouvelle copie locale : Supabase reste la vraie
    // source des données, cette sauvegarde n'est qu'un raccourci pour un
    // rechargement plus rapide.
    if (!_localSaveQuotaWarned) {
      _localSaveQuotaWarned = true;
      showToast(t("toast_local_backup_unavailable"));
    }
  });
}

// ---------- UTILS ----------
function uid() {
  return "id-" + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function money(n) {
  return Number(n).toLocaleString("fr-FR") + " FCFA";
}

// ---------- CONVERSION DE MONNAIE (expansion internationale) ----------
// Taux récupérés en direct (gratuit, sans clé) — XOF comme base commune,
// puisque c'est déjà la monnaie de la majorité des pays couverts. Mis en
// cache 24h pour ne pas re-télécharger à chaque écran.
function getExchangeRates() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "exchange_rates") return state.settings[i];
    }
  }
  return { id: "exchange_rates", base: "XOF", rates: {}, updatedAt: null };
}

function refreshExchangeRatesIfStale() {
  var cached = getExchangeRates();
  var oneDayMs = 24 * 60 * 60 * 1000;
  if (cached.updatedAt && (Date.now() - cached.updatedAt) < oneDayMs) return;
  fetch("https://open.er-api.com/v6/latest/XOF")
    .then(function(res) { return res.json(); })
    .then(function(data) {
      if (!data || data.result !== "success" || !data.rates) return;
      var cfg = { id: "exchange_rates", base: "XOF", rates: data.rates, updatedAt: Date.now() };
      var idx = -1;
      for (var i = 0; i < state.settings.length; i++) { if (state.settings[i].id === "exchange_rates") { idx = i; break; } }
      if (idx === -1) state.settings.push(cfg); else state.settings[idx] = cfg;
      save();
      saveDoc("settings", cfg);
    })
    .catch(function() { /* échec silencieux — les prix restent affichés dans leur monnaie d'origine */ });
}

// Devise à utiliser pour un montant donné, selon le pays auquel il
// appartient (produit, commande...) — XOF pour tous les pays CFA, sinon
// la devise propre à ce pays (voir currencyForCountry / CFA_COUNTRIES).
function currencySymbol(code) {
  var symbols = { XOF: "FCFA", XAF: "FCFA", NGN: "₦", GMD: "D", SLL: "Le", GNF: "FG", INR: "₹", EUR: "€", USD: "$", GBP: "£", CAD: "$ CA", CNY: "¥", MAD: "DH", GHS: "GH₵" };
  return symbols[code] || code;
}

// Convertit un montant stocké dans SA devise d'origine (celle du pays
// vendeur) vers la devise du VIEWER (celle de qui regarde l'écran), pour
// affichage seulement — jamais utilisé pour les calculs internes
// (commissions, totaux de commande...), qui restent toujours dans la
// devise d'origine pour rester exacts.
function convertForDisplay(amount, fromCountry, toCountry) {
  var fromCur = currencyForCountry(fromCountry || "Mali");
  var toCur = currencyForCountry(toCountry || "Mali");
  if (fromCur === toCur) return amount;
  var rates = getExchangeRates().rates;
  if (!rates || !rates[fromCur] || !rates[toCur]) return null; // taux pas encore chargés
  // Les taux sont exprimés depuis XOF (base) : on repasse par XOF au milieu.
  var amountInXof = amount / rates[fromCur];
  return amountInXof * rates[toCur];
}

// Affiche un montant dans SA propre devise (comportement par défaut,
// inchangé partout où "money(prix)" est déjà appelé), ou — si un pays
// d'origine ET un pays visiteur différents sont précisés — ajoute une
// estimation convertie entre parenthèses à titre indicatif.
// Montant à afficher pour CE visiteur précis — converti dans SA devise si
// son pays diffère de celui de l'article, sinon inchangé. Ne renvoie
// jamais les deux valeurs à la fois (l'originale ET la convertie) :
// seule celle qui est utile à cette personne, dans sa propre devise.
function displayAmount(n, itemCountry, viewerCountry) {
  n = Number(n); if (!isFinite(n)) n = 0; // un montant absent ne s'affiche jamais « NaN »
  itemCountry = itemCountry || "Mali"; // voir money() ci-dessous pour le pourquoi de ce repli
  var itemCur = currencyForCountry(itemCountry);
  if (!viewerCountry || itemCountry === viewerCountry) {
    return { amount: Number(n), currency: itemCur };
  }
  var converted = convertForDisplay(n, itemCountry, viewerCountry);
  if (converted == null) return { amount: Number(n), currency: itemCur }; // taux pas encore disponibles
  return { amount: Math.round(converted), currency: currencyForCountry(viewerCountry) };
}

// Montants d'une commande : une commande internationale est toujours
// enregistrée en FCFA (articles convertis au paiement), jamais en roupies.
function orderMoney(n, o) {
  return (o && o.isInternational) ? money(n) : money(n, o ? o.country : null);
}

function money(n, itemCountry, viewerCountry) {
  var d = displayAmount(n, itemCountry, viewerCountry);
  return d.amount.toLocaleString("fr-FR") + " " + currencySymbol(d.currency);
}

// Petit bip généré directement (pas de fichier audio externe à charger) —
// deux notes brèves façon "notification". Peut échouer silencieusement sur
// certains navigateurs tant qu'aucune interaction utilisateur n'a eu lieu
// dans la page (règle anti-autoplay) ; ce n'est pas gênant ici puisqu'un
// premier tap a toujours eu lieu avant qu'une notification puisse arriver.
function playNotificationSound() {
  try {
    var Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    var ctx = new Ctx();
    var o = ctx.createOscillator();
    var g = ctx.createGain();
    o.type = "sine";
    o.frequency.setValueAtTime(880, ctx.currentTime);
    o.frequency.setValueAtTime(1174.7, ctx.currentTime + 0.11);
    g.gain.setValueAtTime(0.0001, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.22, ctx.currentTime + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.38);
    o.connect(g);
    g.connect(ctx.destination);
    o.start();
    o.stop(ctx.currentTime + 0.4);
    setTimeout(function() { ctx.close(); }, 500);
  } catch (e) {
    console.error("Son de notification indisponible :", e);
  }
}

// Notification système (visible même onglet en arrière-plan, tant que le
