// ---------- SERVICE DE PAIEMENT MOBILE MONEY — RÉGLABLE PAR PAYS ----------
// Chaque pays peut utiliser un agrégateur (CinetPay, PayDunya, Flutterwave
// — une seule clé pour tous les opérateurs de ce pays), ou chaque
// opérateur séparément (sa propre clé chacun), ou aucun (paiement à la
// livraison uniquement). Structuré pour qu'ajouter un nouvel agrégateur
// plus tard n'exige qu'un nouveau bloc de champs, sans rien reconstruire.
function getPaymentConfig(country) {
  var id = "payment_config_" + country;
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === id) return state.settings[i];
    }
  }
  return { id: id, country: country, mode: "none", aggregator: "cinetpay" };
}

// Nom de secret Supabase lisible à partir d'un nom de pays (ex : "Côte
// d'Ivoire" → "COTE_D_IVOIRE") — jamais les clés elles-mêmes, seulement
// leur nom, affiché à l'admin pour qu'il sache quoi créer dans Supabase.
function countrySecretSlug(country) {
  return country
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // retire les accents
    .toUpperCase()
    .replace(/[^A-Z]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function savePaymentConfig(country, cfg) {
  cfg.id = "payment_config_" + country;
  cfg.country = country;
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === cfg.id) { idx = i; break; }
  }
  if (idx === -1) state.settings.push(cfg); else state.settings[idx] = cfg;
  save();
  saveDoc("settings", cfg);
}

function urlBase64ToUint8Array(base64String) {
  var padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  var base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  var rawData = atob(base64);
  var outputArray = new Uint8Array(rawData.length);
  for (var i = 0; i < rawData.length; i++) outputArray[i] = rawData.charCodeAt(i);
  return outputArray;
}

// Abonne cet appareil aux vraies notifications (même app fermée) pour le
// compte actuellement connecté, et enregistre l'abonnement côté Supabase
// — c'est cet enregistrement que send-push utilisera pour savoir OÙ
// envoyer. Un même compte peut être abonné depuis plusieurs appareils à
// la fois (chacun reçoit alors sa propre notification).
// Enregistre le jeton Firebase natif (FCM) — UNIQUEMENT quand l'app
// tourne dans la vraie application Capacitor (pas dans un navigateur
// classique, qui utilise subscribeToPush() / Web Push générique juste
// en dessous). window.Capacitor n'existe QUE dans cette app native,
// injecté automatiquement par elle au démarrage.
function subscribeToFcmIfCapacitor(silent) {
  if (!window.Capacitor) { console.log("[FCM] window.Capacitor absent — pas dans l'app Capacitor."); return false; }
  if (!state.profile) { console.log("[FCM] Pas de profil connecté."); return false; }
  var PushNotifications = window.Capacitor.Plugins && window.Capacitor.Plugins.PushNotifications;
  if (!PushNotifications) {
    if (!silent) showToast(t("toast_push_plugin_not_found"));
    else console.log("[FCM] Plugin PushNotifications introuvable (appel silencieux).");
    return false;
  }
  // "silent" = appel automatique au démarrage de l'app (juste pour tenir
  // l'abonnement à jour en arrière-plan) — dans ce cas on ne montre AUCUN
  // toast, ni pour la progression ni pour le succès, afin de ne pas
  // afficher un message à chaque ouverture de l'app une fois que tout
  // fonctionne déjà. Quand l'utilisateur déclenche l'action lui-même
  // (bouton "Activer les notifications" dans Profil), silent est faux et
  // le retour visuel reste complet comme avant.
  window._fcmSilentCall = !!silent;
  if (!silent) showToast(t("toast_firebase_permission_pending"));

  // Cette fonction peut être appelée plusieurs fois dans la même session
  // (au démarrage ET manuellement depuis Profil) — sans ce garde-fou,
  // chaque appel ajouterait un NOUVEL écouteur en plus des précédents,
  // et un seul jeton reçu (ou une seule notification) déclencherait
  // alors plusieurs toasts/enregistrements en double.
  if (!window._fcmListenersRegistered) {
    window._fcmListenersRegistered = true;

    PushNotifications.addListener("registration", function(tokenResult) {
      var token = tokenResult.value;
      // Jeton ACTUEL de ce téléphone (sert à vérifier qu'il est bien celui
      // enregistré sur le serveur — voir le Profil).
      window._fcmCurrentToken = token;
      window._fcmRegisteredFor = state.profile ? state.profile.id : null;
      window._fcmLastError = null;
      var quiet = window._fcmSilentCall;
      if (!quiet && diagnosticsEnabled()) showToast("✅ Jeton reçu (" + token.length + " caractères) — enregistrement dans Supabase...");
      // Le téléphone est inscrit pour TOUS les comptes liés au même numéro
      // (ex. compte acheteur + boutique) : sinon, un message reçu par la
      // boutique ne déclenchait aucune notification si l'app était ouverte
      // sur le compte acheteur (le serveur ne trouvait aucun téléphone
      // inscrit pour la boutique).
      if (!state.fcmTokens) state.fcmTokens = [];
      var fcmAccountIds = (typeof getLinkedAccountIds === "function" ? getLinkedAccountIds() : [state.profile.id]).slice();
      if (fcmAccountIds.indexOf(state.profile.id) === -1) fcmAccountIds.push(state.profile.id);
      fcmAccountIds.forEach(function(fcmAccId) {
        var existingEntry = state.fcmTokens.find(function(t) { return t.token === token && t.accountId === fcmAccId; });
        var entry = {
          id: existingEntry ? existingEntry.id : uid(),
          accountId: fcmAccId,
          token: token,
          createdAt: existingEntry ? existingEntry.createdAt : Date.now()
        };
        if (existingEntry) {
          for (var i = 0; i < state.fcmTokens.length; i++) {
            if (state.fcmTokens[i].id === existingEntry.id) { state.fcmTokens[i] = entry; break; }
          }
        } else {
          state.fcmTokens.push(entry);
        }
        saveDoc("fcmTokens", entry);
      });
      save();
      if (!quiet) showToast(t("toast_notif_enabled"));
      render();
    });

    PushNotifications.addListener("registrationError", function(err) {
      window._fcmLastError = "Enregistrement Firebase échoué : " + JSON.stringify(err);
      try { render(); } catch (e) {}
      if (!window._fcmSilentCall) showToast(diagnosticsEnabled() ? "❌ Enregistrement Firebase échoué : " + JSON.stringify(err) : "❌ Impossible d'activer les notifications pour le moment.");
      else console.log("[FCM] Enregistrement échoué (appel silencieux) :", err);
    });

    // Reçu alors que l'app est ouverte au premier plan — sinon Android
    // l'affiche déjà tout seul nativement, pas besoin de code ici pour ça.
    // Toujours affiché : ce n'est jamais lié au démarrage silencieux, c'est
    // une vraie notification qui vient d'arriver.
    PushNotifications.addListener("pushNotificationReceived", function(notification) {
      showToast("🔔 " + (notification.title || "Sounsouni") + " — " + (notification.body || ""));
    });
  }

  PushNotifications.requestPermissions().then(function(result) {
    if (!silent && diagnosticsEnabled()) showToast("ℹ️ Permission : " + JSON.stringify(result));
    if (result.receive !== "granted") {
      window._fcmLastError = "Autorisation des notifications refusée par le téléphone (" + result.receive + ")";
      if (!silent) showToast(t("toast_notif_refused_settings"));
      return;
    }
    if (!silent) showToast(t("toast_firebase_registering"));
    // Retour à la configuration qui fonctionnait : on N'utilise PLUS de canal
    // personnalisé. Le canal "sounsouni_messages" ajouté le 27/09 est
    // supprimé du téléphone : Android se rabat alors sur le canal par
    // défaut (celui qui affichait bien les notifications en arrière-plan).
    if (typeof PushNotifications.deleteChannel === "function") {
      PushNotifications.deleteChannel({ id: "sounsouni_messages" }).catch(function() {});
    }
    PushNotifications.register();
  }).catch(function(err) {
    if (!silent) showToast(diagnosticsEnabled() ? "❌ requestPermissions() a échoué : " + (err && err.message ? err.message : String(err)) : "❌ Impossible d'activer les notifications pour le moment.");
    else console.log("[FCM] requestPermissions a échoué (appel silencieux) :", err);
  });

  return true;
}

function subscribeToPush() {
  if (!state.profile) return;
  if (window._swRegistrationError) {
    showToast("❌ Le service worker n'a pas pu s'enregistrer : " + window._swRegistrationError);
    return;
  }
  if (!("serviceWorker" in navigator) || !("PushManager" in window)) {
    showToast(t("toast_browser_no_push"));
    return;
  }
  var currentKeyBytes = urlBase64ToUint8Array(VAPID_PUBLIC_KEY);
  // Filet de sécurité : si "ready" ne répond jamais (bloqué en silence),
  // on le signale clairement après 8 secondes au lieu de rester bloqué
  // sans aucun message, indéfiniment.
  var readyTimedOut = false;
  var readyTimeout = setTimeout(function() {
    readyTimedOut = true;
    showToast(t("toast_service_worker_not_responding"));
  }, 8000);
  navigator.serviceWorker.ready.then(function(registration) {
    clearTimeout(readyTimeout);
    if (readyTimedOut) return null; // le message de délai a déjà été montré, on n'en rajoute pas un deuxième
    return registration.pushManager.getSubscription().then(function(existing) {
      if (existing) {
        // Vérifie que l'abonnement existant utilise bien la clé ACTUELLE —
        // si la clé a changé (ex: régénération VAPID), un vieil abonnement
        // ne fonctionne plus et doit être remplacé, jamais réutilisé tel
        // quel.
        var existingKey = existing.options && existing.options.applicationServerKey ? new Uint8Array(existing.options.applicationServerKey) : null;
        var keysMatch = existingKey && existingKey.length === currentKeyBytes.length && existingKey.every(function(b, i) { return b === currentKeyBytes[i]; });
        if (keysMatch) return existing;
        return existing.unsubscribe().then(function() {
          return registration.pushManager.subscribe({
            userVisibleOnly: true,
            applicationServerKey: currentKeyBytes
          });
        });
      }
      return registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: currentKeyBytes
      });
    });
  }).then(function(subscription) {
    if (!subscription) return;
    var json = subscription.toJSON();
    // Identifié par appareil ET compte ensemble — pas seulement l'appareil
    // — pour qu'un même téléphone puisse garder un abonnement actif pour
    // CHAQUE compte qui s'y est connecté (utile pour tester plusieurs
    // comptes sur un seul appareil), au lieu que le dernier compte connecté
    // n'écrase l'abonnement du précédent.
    var existingEntry = (state.pushSubscriptions || []).find(function(s) { return s.endpoint === json.endpoint && s.accountId === state.profile.id; });
    var entry = {
      id: existingEntry ? existingEntry.id : uid(),
      accountId: state.profile.id,
      endpoint: json.endpoint,
      keys: json.keys,
      createdAt: existingEntry ? existingEntry.createdAt : Date.now()
    };
    if (!state.pushSubscriptions) state.pushSubscriptions = [];
    if (existingEntry) {
      for (var i = 0; i < state.pushSubscriptions.length; i++) {
        if (state.pushSubscriptions[i].id === existingEntry.id) { state.pushSubscriptions[i] = entry; break; }
      }
    } else {
      state.pushSubscriptions.push(entry);
    }
    save();
    saveDoc("pushSubscriptions", entry);
  }).catch(function(err) {
    clearTimeout(readyTimeout);
    if (readyTimedOut) return; // le message de délai a déjà été montré
    console.log("Abonnement notifications push impossible :", err);
    showToast("❌ Abonnement échoué (" + (err && err.name ? err.name : "erreur") + ") : " + (err && err.message ? err.message.slice(0, 100) : String(err)));
  });
}

// Demande la permission puis abonne l'appareil dans la foulée si accordée
// — utilisé à la fois automatiquement (premier lancement) et par le
// bouton manuel dans Profil.
function requestPushPermissionAndSubscribe() {
  if (!("Notification" in window)) { showToast(t("toast_notif_not_supported_device")); return; }
  Notification.requestPermission().then(function(permission) {
    if (permission === "granted") {
      subscribeToPush();
      showToast(t("toast_notif_enabled_device"));
    } else {
      showToast(t("toast_notif_refused_settings"));
    }
    render();
  });
}

// Étape 3b : écritures des notifications et des conversations via la
// fonction serveur sécurisée "social-write". Repli sur l'ancienne écriture
// directe UNIQUEMENT si la fonction n'est pas (encore) déployée ou si le
// réseau échoue — jamais quand le serveur refuse explicitement.
function secureSocialWrite(payload, fallbackFn, useAdminToken) {
  var token = useAdminToken ? state.adminSessionToken : state.sessionToken;
  if (!FIREBASE_ENABLED || !token) { if (fallbackFn) fallbackFn(); return Promise.resolve({ success: false, fallback: true }); }
  return fetch(supabaseConfig.url + "/functions/v1/social-write", { method: "POST", headers: authHeaders({}, !!useAdminToken), body: JSON.stringify(payload) })
    .then(function(r) {
      if (r.status === 404) { if (fallbackFn) fallbackFn(); return { success: false, fallback: true }; }
      return readServerJson(r).then(function(res) {
        if (!res.success) { try { pushDebugLog("error", "social-write refusé : " + payload.operation, JSON.stringify(res)); } catch (e) {} }
        return res;
      });
    })
    .catch(function(err) { if (fallbackFn) fallbackFn(); return { success: false, fallback: true, error: String(err) }; });
}

function addNotification(channel, message, userId, target) {
  var notif = { id: uid(), channel: channel, message: message, userId: userId || null, time: Date.now(), read: false, target: target || null };
  state.notifications.unshift(notif);
  save();
  secureSocialWrite({ operation: "create_notification", notification: notif }, function() { queuePendingSync("notifications", notif); })
    .then(function(res) { if (res && res.success) triggerPushNotification(userId, message, notif.id); });
}

// Déclenche une VRAIE notification (même app fermée) pour ce compte, en
// appelant la fonction Supabase dédiée — best-effort, jamais bloquant :
// si ça échoue (pas de connexion, fonction pas encore déployée...), la
// notification simulée dans l'app reste quand même créée normalement.
// Audit 30/10/2026 (ADM-2) : le serveur n'envoie plus une notification
// anonyme ; on lui donne l'identifiant de la notification déjà enregistrée,
// et il envoie SON texte à elle.
function triggerPushNotification(userId, message, notificationId) {
  if (!userId || !FIREBASE_ENABLED) return;
  // Envoie sur les deux systèmes à la fois — chaque compte peut avoir des
  // appareils des deux types (navigateur classique + app Capacitor), best-
  // effort sur chacun, jamais bloquant l'un pour l'autre.
  fetch(supabaseConfig.url + "/functions/v1/send-push", {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({ userId: userId, title: "Sounsouni", body: message, notificationId: notificationId || null })
  }).catch(function() { /* échec silencieux, best-effort */ });
  fetch(supabaseConfig.url + "/functions/v1/send-push-fcm", {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({ userId: userId, title: "Sounsouni", body: message, notificationId: notificationId || null })
  }).catch(function() { /* échec silencieux, best-effort */ });
}

function unreadCount() {
  if (!state.profile) return 0;
  return state.notifications.filter(function(n) { return !n.read && n.userId === state.profile.id; }).length;
}

function categoryByName(name) {
  for (var i = 0; i < CATEGORIES.length; i++) {
    if (CATEGORIES[i].name === name) return CATEGORIES[i];
  }
  return CATEGORIES[CATEGORIES.length - 1];
}

function isDigitalCategory(name) {
  for (var i = 0; i < CATEGORIES.length; i++) if (CATEGORIES[i].name === name) return !!CATEGORIES[i].digital;
  return false;
}
function isDigitalProduct(p) { return !!(p && (p.isDigital || isDigitalCategory(p.category))); }
var DIGITAL_FIELDS_BY_CAT = {
  "E-books & Livres numériques": ["digitalAuthor", "digitalLanguage", "digitalLength", "digitalFormat"],
  "Formations & Cours en ligne": ["digitalAuthor", "digitalLanguage", "digitalLength", "digitalLevel"],
  "Logiciels & Applications": ["digitalAuthor", "digitalPlatform", "digitalVersion", "digitalLicense"],
  "Musique, Vidéos & Créations": ["digitalAuthor", "digitalLength", "digitalFormat"],
  "Documents & Modèles": ["digitalAuthor", "digitalLanguage", "digitalFormat", "digitalLength"]
};
function sizeTypeForCategory(name) {
  var cat = categoryByName(name);
  return cat.sizeType || "none";
}

function colorHex(name) {
  var map = {
    rouge: "#e53935", blanc: "#ffffff", noir: "#1a1a1a", bleu: "#1e88e5", "bleu ciel": "#64b5f6",
    vert: "#43a047", jaune: "#fdd835", orange: "#fb8c00", marron: "#6d4c41", brun: "#6d4c41",
    rose: "#ec407a", violet: "#8e24aa", mauve: "#8e24aa", gris: "#9e9e9e", beige: "#d7ccc8",
    or: "#d4af37", doré: "#d4af37", argenté: "#c0c0c0", turquoise: "#1abc9c", kaki: "#78866b", bordeaux: "#800020",
  };
  var key = (name || "").trim().toLowerCase();
  return map[key] || null;
}

function deliveryZonesForCity(city) {
  var cfg = getDeliveryFeesConfig();
  var cityCfg = cfg[city];
  return cityCfg ? Object.keys(cityCfg) : ["Autre"];
}

function getDeliveryFee(city, zone, mode) {
  mode = mode === "relais" ? "relais" : "express";
  var cfg = getDeliveryFeesConfig();
  var cityCfg = cfg[city];
  var zoneCfg = cityCfg && cityCfg[zone];
  if (!zoneCfg) {
    return mode === "relais" ? Math.round((DEFAULT_DELIVERY_FEE * 0.7) / 50) * 50 : DEFAULT_DELIVERY_FEE;
  }
  return zoneCfg[mode];
}

function cartLineId(productId, color, size) {
  return productId + "::" + (color || "") + "::" + (size || "");
}

function discountPercent(p) {
  if (!p.oldPrice || p.oldPrice <= p.price) return null;
  return Math.round(((p.oldPrice - p.price) / p.oldPrice) * 100);
}

function isFavorite(productId) {
  if (!state.profile) return false;
  if (!Array.isArray(state.profile.favorites)) return false;
  return state.profile.favorites.indexOf(productId) !== -1;
}

// =====================================================================
// SYSTÈME DE TRADUCTION (Français / English / हिंदी)
// =====================================================================
// Principe : chaque texte traduisible passe par t("cle") au lieu d'être
// écrit en dur dans le HTML. Le dictionnaire ci-dessous ne contient pour
// l'instant que les tout premiers écrans convertis — le reste de l'app
// continue de s'afficher en français en attendant sa conversion, écran
// par écran (chantier volontairement progressif, pas un "tout ou rien").
// Le français fait office de langue de secours : si une clé n'existe pas
// encore pour la langue choisie (ou pas du tout), le français s'affiche
// à la place plutôt qu'un texte cassé ou vide.
const SUPPORTED_LANGUAGES = ["fr", "en", "hi"];
const LANGUAGE_LABELS = { fr: "Français", en: "English", hi: "हिंदी" };

function detectInitialLanguage() {
  try {
    var saved = localStorage.getItem("sounsouni_language");
    if (saved && SUPPORTED_LANGUAGES.indexOf(saved) !== -1) return saved;
  } catch (e) {}
  var nav = (navigator.language || navigator.userLanguage || "fr").toLowerCase();
  if (nav.indexOf("hi") === 0) return "hi";
  if (nav.indexOf("en") === 0) return "en";
  return "fr";
}

function setLanguage(lang) {
  if (SUPPORTED_LANGUAGES.indexOf(lang) === -1) return;
  state.language = lang;
  snsEnsureLang(lang);
  try { localStorage.setItem("sounsouni_language", lang); } catch (e) {}
  // Pour un compte déjà connecté, la préférence suit la personne sur ses
  // prochains appareils — pas seulement celui-ci.
  if (state.profile) {
    state.profile.language = lang;
    persistProfileToAccounts();
  }
}

// Textes : un fichier par langue (js/lang-fr.js, lang-en.js, lang-hi.js) — voir snsEnsureLang().
const TRANSLATIONS = window.SNS_LANG || (window.SNS_LANG = {});
if (!TRANSLATIONS.fr) TRANSLATIONS.fr = {};


// Charge le fichier de textes d'une langue s'il n'est pas encore là, puis
// réaffiche l'écran (le français reste affiché en attendant).
function snsEnsureLang(lang) {
  if (!lang || lang === "fr" || TRANSLATIONS[lang] || SUPPORTED_LANGUAGES.indexOf(lang) === -1) return;
  var busy = window._snsLangLoading || (window._snsLangLoading = {});
  if (busy[lang]) return;
  busy[lang] = 1;
  var sc = document.createElement("script");
  sc.src = "js/lang-" + lang + ".js?v=" + encodeURIComponent(window.SOUNSOUNI_VERSION || "");
  sc.onload = function() { busy[lang] = 0; if (TRANSLATIONS[lang]) { try { render(); } catch (e) {} } };
  sc.onerror = function() { busy[lang] = 0; };
  document.head.appendChild(sc);
}
function t(key) {
  var lang = state.language || "fr";
  if (lang !== "fr" && !TRANSLATIONS[lang]) snsEnsureLang(lang);
  if (TRANSLATIONS[lang] && TRANSLATIONS[lang][key] !== undefined) return TRANSLATIONS[lang][key];
  if (TRANSLATIONS.fr[key] !== undefined) return TRANSLATIONS.fr[key];
  return key; // dernier recours — au moins visible, jamais un vide
}

function esc(s) {
  return String(s).replace(/[&<>"']/g, function(c) {
    var map = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
    return map[c];
  });
}

// Nom d'un article dans une commande : dans la langue du lecteur si
// l'article existe encore (sinon le nom enregistré au moment de l'achat).
function orderItemName(it) {
  for (var i = 0; i < state.products.length; i++) {
    if (state.products[i].id === it.productId) return productDisplayName(state.products[i]);
  }
  return it.name;
}
function itemVariant(it) {
  var parts = [];
  if (it.color) parts.push(translateColorName(it.color));
  if (it.size) parts.push(it.size);
  return parts.length ? " (" + parts.map(esc).join(", ") + ")" : "";
}

// ---------- PRIX PAR COULEUR ----------
// Le vendeur peut donner un prix différent à certaines couleurs
// (product.colorPrices = { "Rouge": 9000 }). Une couleur absente de la
// liste garde le prix normal de l'article.
function colorBasePrice(product, color) {
  var cp = product && product.colorPrices;
  if (color && cp && typeof cp === "object") {
    var v = Number(cp[color]);
    if (isFinite(v) && v > 0) return v;
  }
  return product.price;
}
function hasColorPrices(product) {
  var cp = product && product.colorPrices;
  if (!cp || typeof cp !== "object" || !Array.isArray(product.colors)) return false;
  return product.colors.some(function(c) { var v = Number(cp[c]); return isFinite(v) && v > 0 && v !== product.price; });
}

// ---------- PRIX DÉGRESSIF ----------
// color : couleur choisie (sinon celle de la ligne de panier, product.color).
// Un écart de prix dû à la couleur s'applique aussi aux paliers dégressifs.
function getTieredPrice(product, qty, color) {
  var col = color !== undefined ? color : product.color;
  var base = colorBasePrice(product, col);
  if (!product.tieredPricing || product.tieredPricing.length === 0) {
    return base;
  }
  var delta = base - product.price;
  var sorted = product.tieredPricing.slice().sort(function(a, b) { return a.minQty - b.minQty; });
  var price = base;
  for (var i = 0; i < sorted.length; i++) {
    if (qty >= sorted[i].minQty) {
      price = Math.max(1, sorted[i].price + delta);
    }
  }
  return price;
}
