// GEMS — Logique complète — PARTIE 2/6
// ============================================================

// ---------- ONBOARDING ----------
// Validation des champs obligatoires propres à un type de vendeur (hors
// Particulier) — sortie de registerAccount() pour pouvoir être appelée
// PLUS TÔT, avant même d'afficher la politique d'utilisation. Sans ça,
// on découvrait un champ manquant seulement après avoir lu tout le
// document et cliqué "J'accepte", obligeant à repartir en arrière.
function validateVendorDetailsFields(d) {
  if (d.role === "vendeur" && d.sellerType !== "particulier" && d.sellerType !== "international") {
    if (!d.commune) {
      showToast(t("toast_commune_required_seller_type"));
      return false;
    }
    if (!d.quartier) {
      showToast(t("toast_neighborhood_required_seller_type"));
      return false;
    }
    if (d.shopLat == null || d.shopLng == null) {
      showToast("❌ Position GPS obligatoire — appuyez sur \"Localiser mon activité\" avant de créer le compte.");
      return false;
    }
  }
  if (d.role === "vendeur" && d.sellerType === "international") {
    if (!d.shopAddress || !d.shopAddress.trim()) {
      showToast(t("toast_shop_address_required"));
      return false;
    }
    var agentsAtRegister2 = state.accounts.filter(function(a) { return a.isSourcingAgent; });
    if (agentsAtRegister2.length > 0 && !d.sourcingAgentId) {
      showToast(t("toast_choose_agent_required"));
      return false;
    }
  }
  return true;
}

function registerAccount() {
  console.log("=== DEBUT registerAccount ===");
  
  var d = state.onboardDraft;
  if (isLikelyBot("inscription", d)) { showToast("❌ Une erreur est survenue, veuillez réessayer."); return; }
  // Engagement obligatoire de tout vendeur à ne vendre aucun produit
  // interdit — exigé par notre partenaire de paiement, et protège
  // juridiquement Sounsouni en engageant clairement la responsabilité du
  // vendeur. Demandé juste avant la création du compte, quel que soit le
  // type de vendeur.
  if (d.role === "vendeur" && !d.prohibitedGoodsConsent) {
    d.prohibitedConsentReturnStep = state.onboardStep;
    state.onboardStep = "prohibitedGoodsConsent";
    render();
    return;
  }
  console.log("d =", d);
  
  // 1. Nom
  if (!d.name || !d.name.trim()) {
    showToast(t("toast_fullname_required"));
    return;
  }
  console.log("Nom OK");
  
  // 2. Téléphone
  var phoneRaw = d.phone || "";
  var phoneDigits = stripTrunkZero(d.countryCode || "+223", phoneRaw);
  if (!phoneDigits) {
    showToast(t("toast_phone_required1"));
    return;
  }
  console.log("Téléphone OK");
  
  // 3. Indicatif
  var countryCode = d.countryCode || "+223";
  var countryInfo = null;
  for (var i = 0; i < COUNTRY_CODES.length; i++) {
    if (COUNTRY_CODES[i].code === countryCode) {
      countryInfo = COUNTRY_CODES[i];
      break;
    }
  }
  if (!countryInfo) countryInfo = COUNTRY_CODES[COUNTRY_CODES.length - 1];
  console.log("countryInfo =", countryInfo);
  
  // Vérification de la longueur du numéro
  if (phoneDigits.length < countryInfo.minDigits || phoneDigits.length > countryInfo.maxDigits) {
    showToast("❌ Le numéro doit comporter " + countryInfo.minDigits + " à " + countryInfo.maxDigits + " chiffres pour l'indicatif " + countryCode + ".");
    return;
  }
  // Vérification supplémentaire pour le Mali (les numéros commencent par 6,7,8,9)
  if (countryCode === "+223" && !/^[6-9]/.test(phoneDigits)) {
    showToast(t("toast_mali_phone_format"));
    return;
  }
  console.log("Téléphone valide");
  
  // 4. Email
  var email = d.email ? d.email.trim() : "";
  if (!email) {
    showToast(t("toast_email_required_generic"));
    return;
  }
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    showToast(t("toast_email_invalid_example"));
    return;
  }
  console.log("Email OK");
  
  // 4bis. Point de Retrait : nom de boutique + commune/quartier + position GPS obligatoires
  if (d.role === "point_vente") {
    if (!d.shopName || !d.shopName.trim()) {
      showToast(t("toast_shopname_required2"));
      return;
    }
    if (d.useAutreQuartier) {
      if (!d.autreQuartierNom || !d.autreQuartierNom.trim()) {
        showToast(t("toast_neighborhood_name_required"));
        return;
      }
      if (d.autreQuartierLat == null || d.autreQuartierLng == null) {
        showToast(t("toast_neighborhood_gps_required"));
        return;
      }
    } else {
      if (!d.commune) {
        showToast(t("toast_commune_required"));
        return;
      }
      if (!d.quartier) {
        showToast(t("toast_neighborhood_required"));
        return;
      }
    }
    if (d.shopLat == null || d.shopLng == null) {
      showToast("❌ Position GPS obligatoire — appuyez sur \"Localiser ma boutique\" avant de créer le compte.");
      return;
    }
    if (!d.selfiePhotoUri) {
      showToast(t("toast_photo_required_pickup"));
      return;
    }
    if (!d.verificationDocs || d.verificationDocs.length === 0) {
      showToast(t("toast_doc_required_pickup"));
      return;
    }
  }

  // 4ter/4quater. Vendeur autre que Particulier : mêmes règles que celles
  // déjà vérifiées plus tôt, avant la politique d'utilisation (voir
  // "complete-onboarding") — revérifiées ici aussi par sécurité, au cas
  // où ce point serait atteint par un autre chemin.
  if (!validateVendorDetailsFields(d)) return;
  
  // 5. Numéro complet
  var fullPhone = countryCode + phoneDigits;
  console.log("fullPhone =", fullPhone);
  
  // 6. Vérifier compte(s) existant(s) pour ce numéro — un seul compte
  // vendeur est désormais autorisé par numéro de téléphone (plus de
  // plusieurs boutiques/types différents sur un même numéro).
  var linkedAccounts = state.accounts.filter(function(a) { return a.phone === fullPhone; });
  if (linkedAccounts.length > 0) {
    if (d.role === "acheteur") {
      showToast("❌ Ce numéro a déjà un compte. Utilisez \"J'ai déjà un compte (créé sur un autre appareil)\" pour vous y reconnecter.");
      return;
    }
    if (d.role === "vendeur") {
      var vendorAccounts = linkedAccounts.filter(function(a) { return a.role === "vendeur"; });
      if (vendorAccounts.length >= 1) {
        showToast(t("toast_number_already_seller"));
        return;
      }
    }
  }
  
  // 7. Créer compte
  var effectiveRole = d.role === "point_vente" ? "acheteur" : d.role;
  var account = {
    id: uid(),
    authUid: authUid, // identifiant de cet appareil — sert aux règles de sécurité
    name: d.name.trim(),
    phone: fullPhone,
    email: email || null,
    // Pays déduit automatiquement de l'indicatif choisi à l'inscription —
    // jamais demandé séparément. Sert à filtrer comptes/commandes/produits
    // par pays et à savoir quelle monnaie afficher (voir CFA_COUNTRIES).
    country: countryForCode(countryCode),
    // Date de naissance, mot de passe et code secret ne sont PAS demandés
    // à l'inscription (pour ne pas décourager les nouveaux) — ils sont
    // créés ensemble au moment du premier achat, voir requirePasswordSetup().
    birthDate: null,
    password: null,
    recoveryCode: null,
    role: effectiveRole,
    sellerType: d.role === "vendeur" ? (d.sellerType || "particulier") : null,
    sellerSector: d.role === "vendeur" ? (d.sellerSector || null) : null,
    shopName: d.role === "vendeur" ? ((d.shopName && d.shopName.trim()) ? d.shopName.trim() : "Boutique de " + d.name.trim()) : (d.role === "point_vente" ? d.shopName.trim() : null),
    shopPhone: d.role === "vendeur" ? fullPhone : "",
    shopAddress: d.role === "vendeur" ? (d.sellerType === "international" ? (d.shopAddress || "").trim() : ((d.commune && d.quartier) ? (d.quartier + ", " + d.commune + (d.addressDetail && d.addressDetail.trim() ? " — " + d.addressDetail.trim() : "")) : "")) : "",
    shopLat: (d.role === "point_vente" || (d.role === "vendeur" && d.sellerType !== "particulier")) ? d.shopLat : null,
    commune: d.role === "point_vente" ? d.commune : null,
    quartier: d.role === "point_vente" ? d.quartier : null,
    addressDetail: d.role === "point_vente" ? (d.addressDetail || "") : "",
    shopLng: (d.role === "point_vente" || (d.role === "vendeur" && d.sellerType !== "particulier")) ? d.shopLng : null,
    cuisineType: d.role === "vendeur" ? (d.cuisineType || "") : "",
    openingHours: d.role === "vendeur" ? (d.openingHours || "") : "",
    deliveryZone: d.role === "vendeur" ? (d.deliveryZone || "") : "",
    productionType: d.role === "vendeur" ? (d.productionType || "") : "",
    domaineEnseigne: d.role === "vendeur" ? (d.domaineEnseigne || "") : "",
    specialiteSante: d.role === "vendeur" ? (d.specialiteSante || "") : "",
    servicesBeaute: d.role === "vendeur" ? (d.servicesBeaute || "") : "",
    servicesAuto: d.role === "vendeur" ? (d.servicesAuto || "") : "",
    servicesDecoration: d.role === "vendeur" ? (d.servicesDecoration || "") : "",
    servicesEvenementiel: d.role === "vendeur" ? (d.servicesEvenementiel || "") : "",
    typeEtablissement: d.role === "vendeur" ? (d.typeEtablissement || "") : "",
    nombreChambres: d.role === "vendeur" ? (d.nombreChambres || "") : "",
    // Lien vers l'agent sourcing choisi par CE vendeur — c'est ce qui
    // permet à renderAgentSourcing() de ne montrer à chaque agent que les
    // commandes des vendeurs dont il a vraiment la charge.
    sourcingAgentId: (d.role === "vendeur" && d.sellerType === "international") ? (d.sourcingAgentId || null) : null,
    relaisApplicationStatus: d.role === "point_vente" ? "pending" : null,
    // Un vendeur "international" ne passe jamais par l'écran de
    // consentement à la commission (voir "complete-onboarding" plus bas,
    // qui ne s'applique pas à lui) — sans ce cas particulier ici, il se
    // serait retrouvé bloqué une seconde fois, plus tard, par l'autre
    // porte qui vérifie ce même accord avant d'entrer dans l'espace vendeur.
    vendorCommissionAccepted: d.role === "vendeur" ? (d.sellerType === "international" || !!d.commissionConsent) : false,
    verified: false,
    favorites: [],
    createdAt: Date.now(),
    loginHistory: [Date.now()],
    behavior: { views: [], purchases: [], searches: [] }
  };

  var mergingIntoExisting = d.isFirstShopEver && d.role === "vendeur" && state.profile && state.profile.id;
  if (mergingIntoExisting) {
    // Ajoute la casquette "vendeur" sur la fiche déjà existante, au lieu
    // de fabriquer un compte séparé — une personne = une seule fiche,
    // même en cumulant plusieurs rôles. Seuls les champs propres au
    // vendeur sont copiés ; tout le reste (historique, favoris, adresses
    // personnelles déjà enregistrées) reste intact sur la fiche d'origine.
    var vendorFieldsOnly = ["sellerType", "sellerSector", "shopName", "shopPhone", "shopAddress", "shopLat", "shopLng", "cuisineType", "openingHours", "deliveryZone", "productionType", "domaineEnseigne", "specialiteSante", "servicesBeaute", "servicesAuto", "servicesDecoration", "servicesEvenementiel", "typeEtablissement", "nombreChambres", "vendorCommissionAccepted", "sourcingAgentId"];
    for (var vfi = 0; vfi < vendorFieldsOnly.length; vfi++) {
      state.profile[vendorFieldsOnly[vfi]] = account[vendorFieldsOnly[vfi]];
    }
    if (!Array.isArray(state.profile.roles)) state.profile.roles = [state.profile.role];
    if (state.profile.roles.indexOf("vendeur") === -1) state.profile.roles.push("vendeur");
    state.profile.role = "vendeur";
    for (var mai = 0; mai < state.accounts.length; mai++) {
      if (state.accounts[mai].id === state.profile.id) { state.accounts[mai] = { ...state.profile }; break; }
    }
    saveDoc("accounts", state.profile);
  } else {
    state.accounts.push(account);
    state.profile = { ...account };
    markDeviceAccount(account.id);
  }

  // 7bis. Demande Point de Retrait : soumise à validation admin avant activation
  if (d.role === "point_vente") {
    var application = {
      id: uid(),
      accountId: account.id,
      accountName: account.name,
      accountPhone: account.phone,
      country: account.country || "Mali",
      shopName: d.shopName.trim(),
      commune: d.useAutreQuartier ? null : d.commune,
      quartier: d.useAutreQuartier ? d.autreQuartierNom.trim() : d.quartier,
      isAutreQuartier: !!d.useAutreQuartier,
      autreQuartierLat: d.useAutreQuartier ? d.autreQuartierLat : null,
      autreQuartierLng: d.useAutreQuartier ? d.autreQuartierLng : null,
      addressDetail: d.addressDetail || "",
      shopLat: d.shopLat,
      shopLng: d.shopLng,
      hasVerificationDocs: true, // la vraie photo part séparément, voir plus bas
      status: "pending",
      createdAt: Date.now()
    };
    state.relaisApplications.push(application);
    var relaisSavePromise2 = saveDoc("relaisApplications", application);
    // La vraie photo ne transite jamais par app_data — voir
    // submitVerificationDocuments et get-verification-docs.
    (relaisSavePromise2 || Promise.resolve()).then(function() { return submitVerificationDocuments("relais_app_" + application.id, d.selfiePhotoUri, d.verificationDocs); }).then(function(ok) {
      if (!ok) {
        application.hasVerificationDocs = false;
        saveDoc("relaisApplications", application);
        console.error("Échec de l'envoi sécurisé de la photo pour la candidature", application.id);
      }
    });

    // Si le quartier saisi n'existe pas dans la liste, une demande séparée
    // part aussi pour que l'admin l'ajoute officiellement à la base.
    if (d.useAutreQuartier) {
      var quartierApp = {
        id: uid(),
        accountId: account.id,
        accountName: account.name,
        country: account.country || "Mali",
        quartierNom: d.autreQuartierNom.trim(),
        lat: d.autreQuartierLat,
        lng: d.autreQuartierLng,
        suggestedCommune: null,
        status: "pending",
        createdAt: Date.now()
      };
      state.autreQuartierApplications.push(quartierApp);
      saveDoc("autreQuartierApplications", quartierApp);
    }
    showToast(t("toast_account_created_relais_pending"));
  }
  
  // 8. Parrainage
  var ref = detectReferral();
  if (ref) {
    state.profile.referredBy = ref;
    account.referredBy = ref;
    showToast(t("toast_welcome_referred"));
  }
  
  // 9. Code d'affiliation
  state.affiliateCode = generateReferralCode(state.profile.id);
  
  // 10. Changer de vue
  state.view = ROLE_HOME_VIEW[effectiveRole] || "market";
  state.onboardDraft = emptyOnboardDraft();
  state.onboardStep = "identity";
  if (d.isSecondAccountFlow && effectiveRole === "vendeur") {
    // Un compte déjà existant qui devient vendeur connaît déjà l'app en
    // général — inutile de lui remontrer "Découvrir l'application".
    // Ce qui l'intéresse ici, c'est comment publier, donc c'est ce
    // guide-là qui doit s'ouvrir, pas l'introduction générale.
    account.seenDiscoverTour = true;
    state.profile.seenDiscoverTour = true;
    if (!account.seenPublierGuide) {
      account.seenPublierGuide = true;
      state.profile.seenPublierGuide = true;
      state.activeTour = { tourKey: "publier", index: 0, single: false };
    }
  } else if (!account.seenDiscoverTour) {
    account.seenDiscoverTour = true;
    state.profile.seenDiscoverTour = true;
    state.activeTour = { tourKey: "decouvrir", index: 0, single: false };
  }
  
  // 11. Notifications — déclenchement automatique juste après la création
  // du compte, pour un NOUVEAU compte uniquement (mergingIntoExisting
  // false : quelqu'un qui ajoute juste une casquette à un compte déjà
  // existant a déjà eu (ou refusé) cette demande avant). L'ancienne
  // version ne faisait QUE demander la permission sans jamais compléter
  // l'abonnement réel derrière — la personne acceptait, mais ne recevait
  // quand même jamais rien. On utilise maintenant le même mécanisme
  // complet que le bouton manuel du Profil (abonnement FCM natif sur
  // l'app Android, sinon Web Push classique).
  if (!mergingIntoExisting && 'Notification' in window && Notification.permission === 'default') {
    if (!subscribeToFcmIfCapacitor()) {
      requestPushPermissionAndSubscribe();
    }
  }
  
  // 12. Sauvegarder et afficher
  console.log("Avant save()");
  if (mergingIntoExisting) {
    // Toutes les mutations tardives (parrainage, guides vus...) doivent
    // être reportées sur la fiche persistée avant l'enregistrement final —
    // sinon la première synchronisation, faite plus tôt, serait déjà
    // dépassée à ce stade.
    for (var maiFinal = 0; maiFinal < state.accounts.length; maiFinal++) {
      if (state.accounts[maiFinal].id === state.profile.id) { state.accounts[maiFinal] = { ...state.profile }; break; }
    }
    save();
    saveDoc("accounts", state.profile);
  } else {
    save();
    createAccountSecurely(account).then(function(res) {
      if (!res.success) {
        // Le serveur a refusé (numéro déjà utilisé, détecté avec les
        // VRAIES données — pas le cache local) : on retire le compte
        // optimiste créé en local pour ne pas laisser l'app dans un état
        // où la personne SEMBLE connectée alors que rien n'a été retenu.
        state.accounts = state.accounts.filter(function(a) { return a.id !== account.id; });
        if (state.profile && state.profile.id === account.id) state.profile = null;
        var reasonMsg = res.error === "phone_already_used" ? "Ce numéro a déjà un compte."
          : res.error === "phone_already_seller" ? "Ce numéro a déjà un compte vendeur."
          : res.error === "login_required_for_phone" ? "Ce numéro a déjà un compte. Connectez-vous d'abord avec ce numéro, puis ajoutez votre boutique."
          : res.error === "invalid_phone" ? "Numéro de téléphone invalide."
          : res.error === "too_many_attempts" ? "Trop de comptes créés depuis cette connexion. Réessayez dans une heure."
          : "Impossible de créer le compte, réessayez.";
        showToast("❌ " + reasonMsg);
        save();
        render();
        return;
      }
      state.sessionToken = res.sessionToken;
      save();
      render();
      setTimeout(trackVisit, 1500);
    });
  }
  console.log("Après save()");
  render();
  console.log("=== FIN registerAccount ===");
}

// ---------- COMPTES LIÉS (même téléphone + nom + email) ----------
// Les différents comptes d'une même personne sur ce numéro (acheteur et
// son unique compte vendeur, par exemple) sont considérés comme la même
// personne — un Point de Retrait approuvé sur l'un d'eux doit être
// accessible depuis les autres, sans nouvelle demande.
function findLinkedAccounts(profile) {
  if (!profile) return [];
  return state.accounts.filter(function(a) {
    return a.id !== profile.id &&
      a.phone === profile.phone &&
      a.name.trim().toLowerCase() === profile.name.trim().toLowerCase() &&
      (a.email || "").trim().toLowerCase() === (profile.email || "").trim().toLowerCase();
  });
}

function findLinkedApprovedRelais(profile) {
  var linked = findLinkedAccounts(profile);
  for (var i = 0; i < linked.length; i++) {
    if (linked[i].relaisApplicationStatus === "approved") return linked[i];
  }
  return null;
}

// Un compte lié (même téléphone/nom/email) a-t-il une notification non lue,
// une nouvelle commande, ou un nouveau statut à voir ? Sert à signaler
// discrètement "il se passe quelque chose sur un de tes autres comptes".
function findLinkedAccountWithActivity(profile) {
  var linked = findLinkedAccounts(profile);
  for (var i = 0; i < linked.length; i++) {
    var a = linked[i];
    if (a.hasNewSellerOrderAlert || a.hasNewBuyerStatusAlert) return a;
    var hasUnread = state.notifications.some(function(n) { return n.userId === a.id && !n.read; });
    if (hasUnread) return a;
  }
  return null;
}

// Bascule vers un compte lié en préservant d'abord la session en cours
// (contrairement à loginAccount() seul, utilisé depuis la liste des
// comptes où aucune session n'est encore active).
function switchToLinkedAccount(accountId) {
  if (state.profile) {
    refreshProfileFromAccounts();
    for (var i = 0; i < state.accounts.length; i++) {
      if (state.accounts[i].id === state.profile.id) { state.accounts[i] = { ...state.profile }; break; }
    }
    save();
  }
  // Avant de basculer, on obtient un VRAI jeton de session pour ce
  // compte précis — sans ça, l'app affichait le bon compte mais
  // gardait le jeton de l'ancien, ce qui faisait échouer silencieusement
  // toute action ensuite (passer commande, envoyer un message...) avec
  // "session_required". Pas besoin de redemander le mot de passe : le
  // serveur vérifie juste que les deux comptes partagent le même numéro.
  callAddressesOperation({ operation: "get_linked_account_token", targetAccountId: accountId }).then(function(res) {
    if (res.success && res.sessionToken) {
      state.sessionToken = res.sessionToken;
      save();
    } else {
      pushDebugLog("error", "Échec changement de compte lié", JSON.stringify(res));
    }
    loginAccount(accountId);
  });
}

// Marque un compte comme "réellement utilisé sur cet appareil" — c'est
// cette liste (purement locale, jamais synchronisée) qui décide quels
// comptes apparaissent dans le sélecteur "Comptes existants".
// Animation signature : le produit "tombe" dans le panier avec un petit
// rebond quand on clique "Ajouter". Vit entièrement HORS de #root (donc
// jamais effacée par le prochain rendu complet de l'app) — un élément
// flottant temporaire, retiré tout seul une fois l'animation terminée.
function flyToCart(startEl) {
  try {
    var cartNavItem = document.querySelector('.nav-item[data-value="cart"]');
    if (!startEl || !cartNavItem) return;
    var startRect = startEl.getBoundingClientRect();
    var endRect = cartNavItem.getBoundingClientRect();
    var flyer = document.createElement('div');
    flyer.className = 'fly-to-cart-ball';
    flyer.style.left = (startRect.left + startRect.width / 2 - 11) + 'px';
    flyer.style.top = (startRect.top + startRect.height / 2 - 11) + 'px';
    document.body.appendChild(flyer);
    var dx = (endRect.left + endRect.width / 2) - (startRect.left + startRect.width / 2);
    var dy = (endRect.top + endRect.height / 2) - (startRect.top + startRect.height / 2);
    requestAnimationFrame(function() {
      flyer.style.transform = 'translate(' + dx + 'px, ' + dy + 'px) scale(0.3)';
      flyer.style.opacity = '0.15';
    });
    setTimeout(function() {
      if (flyer.parentNode) flyer.parentNode.removeChild(flyer);
      cartNavItem.classList.add('cart-bump');
      setTimeout(function() { cartNavItem.classList.remove('cart-bump'); }, 400);
    }, 550);
  } catch (e) {
    // Purement décoratif — si quoi que ce soit échoue (élément absent au
    // moment du clic, etc.), on n'empêche jamais l'ajout au panier lui-même.
  }
}

function markDeviceAccount(accountId) {
  if (!state.deviceAccountIds) state.deviceAccountIds = [];
  if (state.deviceAccountIds.indexOf(accountId) === -1) state.deviceAccountIds.push(accountId);
  save();
}

function getAccountDataCounts(accountId) {
  var products = state.products.filter(function(p) { return p.sellerId === accountId; }).length;
  var orders = state.orders.filter(function(o) { return o.buyerId === accountId; }).length;
  var conversations = state.conversations.filter(function(c) { return c.buyerId === accountId || c.sellerId === accountId; }).length;
  return { products: products, orders: orders, conversations: conversations };
}

function mergeAccountsByPhone(primaryId) {
  var primary = null;
  for (var pi = 0; pi < state.accounts.length; pi++) { if (state.accounts[pi].id === primaryId) { primary = state.accounts[pi]; break; } }
  if (!primary) return { merged: 0 };

  var duplicates = state.accounts.filter(function(a) { return a.phone === primary.phone && a.id !== primaryId; });
  if (duplicates.length === 0) return { merged: 0 };
  var dupIds = duplicates.map(function(d) { return d.id; });

  function isDup(id) { return dupIds.indexOf(id) !== -1; }

  state.products.forEach(function(p) {
    if (isDup(p.sellerId)) {
      p.sellerId = primaryId;
      p.sellerName = primary.name;
      p.sellerPhone = primary.phone;
      if (primary.shopName) p.shopName = primary.shopName;
      saveDoc("products", p);
    }
  });

  state.orders.forEach(function(o) {
    var changed = false;
    if (isDup(o.buyerId)) { o.buyerId = primaryId; o.buyerName = primary.name; o.buyerPhone = primary.phone; changed = true; }
    if (Array.isArray(o.items)) {
      o.items.forEach(function(it) {
        if (isDup(it.sellerId)) { it.sellerId = primaryId; it.sellerName = primary.name; it.sellerPhone = primary.phone; changed = true; }
      });
    }
    if (changed) secureOrderSaveDoc(o);
  });

  state.bookings.forEach(function(b) {
    var changed = false;
    if (isDup(b.buyerId)) { b.buyerId = primaryId; b.buyerName = primary.name; b.buyerPhone = primary.phone; changed = true; }
    if (isDup(b.sellerId)) { b.sellerId = primaryId; b.sellerName = primary.name; b.sellerPhone = primary.phone; changed = true; }
    if (changed) saveDoc("bookings", b);
  });

  // Conversations et notifications : réattribuées côté serveur (jeton
  // Admin), l'app se contentant de mettre à jour sa copie locale.
  var mergeDupIds = dupIds.slice();
  var mergeLocalConvs = [];
  state.conversations.forEach(function(c) {
    var changed = false;
    if (isDup(c.buyerId)) { c.buyerId = primaryId; changed = true; }
    if (isDup(c.sellerId)) { c.sellerId = primaryId; changed = true; }
    if (changed) mergeLocalConvs.push(c);
  });

  state.reviews.forEach(function(r) {
    if (isDup(r.userId)) {
      r.userId = primaryId;
      r.userName = primary.name;
      saveDoc("reviews", r);
    }
  });

  var mergeLocalNotifs = [];
  state.notifications.forEach(function(n) {
    if (isDup(n.userId)) { n.userId = primaryId; mergeLocalNotifs.push(n); }
  });
  secureSocialWrite({ operation: "admin_merge_accounts", primaryId: primaryId, duplicateIds: mergeDupIds }, function() {
    mergeLocalConvs.forEach(function(c) { saveDoc("conversations", c); });
    mergeLocalNotifs.forEach(function(n) { queuePendingSync("notifications", n); });
  }, true);

  state.boosts.forEach(function(bo) {
    if (isDup(bo.sellerId)) {
      bo.sellerId = primaryId;
      bo.sellerName = primary.shopName || primary.name;
      saveDoc("boosts", bo);
    }
  });

  state.verificationRequests.forEach(function(vr) {
    if (isDup(vr.accountId)) {
      vr.accountId = primaryId;
      vr.accountName = primary.name;
      vr.accountPhone = primary.phone;
      saveDoc("verificationRequests", vr);
    }
  });

  // ---- Récupération intelligente des informations avant suppression ----
  // Avant, cet outil ne servait qu'à nettoyer de vrais doublons fantômes
  // (sans aucune donnée propre). Il sert maintenant aussi à fusionner une
  // même personne qui a, par le passé, fini avec plusieurs fiches (une
  // par rôle) — dans ce cas, la fiche supprimée peut contenir des
  // informations bien réelles (boutique, position GPS, adresses...) qui
  // ne doivent jamais disparaître : elles sont recopiées sur la fiche
  // conservée avant toute suppression.
  var vendorFieldsToRecover = ["sellerType", "sellerSector", "shopName", "shopPhone", "shopAddress", "shopLat", "shopLng", "cuisineType", "openingHours", "deliveryZone", "productionType", "domaineEnseigne", "specialiteSante", "servicesBeaute", "servicesAuto", "servicesDecoration", "servicesEvenementiel", "typeEtablissement", "nombreChambres", "vendorCommissionAccepted", "relaisApplicationStatus", "verified"];
  if (!Array.isArray(primary.roles)) primary.roles = [primary.role];

  duplicates.forEach(function(dup) {
    if (dup.role && primary.roles.indexOf(dup.role) === -1) primary.roles.push(dup.role);
    vendorFieldsToRecover.forEach(function(vf) {
      var primaryEmpty = primary[vf] === null || primary[vf] === undefined || primary[vf] === "" || primary[vf] === false;
      var dupHasValue = dup[vf] !== null && dup[vf] !== undefined && dup[vf] !== "" && dup[vf] !== false;
      if (primaryEmpty && dupHasValue) primary[vf] = dup[vf];
    });
    if (Array.isArray(dup.favorites) && dup.favorites.length) {
      if (!Array.isArray(primary.favorites)) primary.favorites = [];
      dup.favorites.forEach(function(fid) {
        if (primary.favorites.indexOf(fid) === -1) primary.favorites.push(fid);
      });
    }
    // Les adresses enregistrées ne vivent plus sur le compte (voir
    // addresses-write) — ce bloc n'a donc plus d'effet ici. En cas de
    // fusion de deux comptes en double, les adresses de chacun restent
    // séparées ; limite mineure acceptée, pas un souci de sécurité.
    if (Array.isArray(dup.savedAddresses) && dup.savedAddresses.length) {
      if (!Array.isArray(primary.savedAddresses)) primary.savedAddresses = [];
      dup.savedAddresses.forEach(function(sa) {
        var alreadyThere = primary.savedAddresses.some(function(pa) { return pa.commune === sa.commune && pa.quartier === sa.quartier && pa.repere === sa.repere; });
        if (!alreadyThere) primary.savedAddresses.push(sa);
      });
    }
    // loginHistory ne vit plus sur le compte (voir admin-access,
    // opération "record_login") — rien à fusionner ici pour ce champ.
    // Si le vendeur avait déjà accepté la commission sur la fiche
    // supprimée, on ne doit pas lui redemander sur la fiche conservée.
    if (dup.vendorCommissionAccepted) primary.vendorCommissionAccepted = true;
  });
  // Le rôle actif après fusion privilégie "vendeur" s'il existe parmi les
  // rôles récupérés — c'est l'information la plus riche à ne pas perdre
  // de vue, la personne pourra toujours rebasculer sur "Acheteur" ensuite.
  if (primary.roles.indexOf("vendeur") !== -1) primary.role = "vendeur";

  state.accounts = state.accounts.filter(function(a) { return !isDup(a.id); });
  dupIds.forEach(function(did) { deleteRemoteDoc("accounts", did); });
  saveDoc("accounts", primary);
  save();

  return { merged: dupIds.length };
}

// ---------- RETROUVER UN COMPTE DÉJÀ CRÉÉ SUR UN AUTRE APPAREIL ----------
// Version rapide pour la phase de test : nom complet + téléphone uniquement
// (l'email étant optionnel à l'inscription, on ne peut pas s'appuyer dessus).
// ⚠️ Pas de vérification réelle (pas de code SMS) — n'importe qui connaissant
// ces deux informations peut accéder au compte. À remplacer par un vrai code
// de vérification par SMS avant une mise en production réelle.
// ---------- Pièges à robots dans les formulaires ----------
// Un champ invisible (hors de l'écran, jamais atteint au clavier) : un humain
// ne le voit pas et ne le remplit jamais ; un robot remplit tout ce qu'il
// trouve. Et un chronomètre : un humain met plusieurs secondes à remplir un
// formulaire, un robot une fraction de seconde. Détecté → on n'envoie rien,
// on affiche un message banal (sans révéler le piège) et on enregistre un
// signal pour l'Admin.
function honeypotFieldHtml(draftName) {
  return '<div aria-hidden="true" style="position:absolute;left:-10000px;top:auto;width:1px;height:1px;overflow:hidden;">' +
    '<label>Ne pas remplir ce champ<input type="text" name="hp_fax_contact_2" tabindex="-1" autocomplete="off" value="' + esc((state[draftName] || {}).hpFax || '') + '" data-bind="' + draftName + '.hpFax" /></label></div>';
}
function markFormShown(key) {
  window._snsFormShownAt = window._snsFormShownAt || {};
  if (!window._snsFormShownAt[key]) window._snsFormShownAt[key] = Date.now();
}
function isLikelyBot(key, draft) {
  var filled = !!(draft && draft.hpFax && String(draft.hpFax).trim());
  var shownAt = (window._snsFormShownAt || {})[key] || 0;
  var tooFast = shownAt && (Date.now() - shownAt < 1500);
  if (!filled && !tooFast) return false;
  try {
    // Enregistré par le serveur (le téléphone n'a pas le droit d'écrire
    // dans le journal de sécurité — c'est ce qui bloquait ces alertes).
    fetch(supabaseConfig.url + "/functions/v1/create-account", { method: "POST", headers: authHeaders(),
      body: JSON.stringify({ botSignal: { detail: (filled ? "Champ invisible rempli" : "Formulaire envoyé en moins de 1,5 s") + " — " + key } }) }).catch(function() {});
  } catch (e) {}
  // On relance le chronomètre : un humain très rapide peut simplement réessayer.
  if (window._snsFormShownAt) window._snsFormShownAt[key] = Date.now();
  return true;
}

function attemptFindAccount() {
  var d = state.findAccountDraft;
  if (isLikelyBot("connexion", d)) { showToast("❌ Une erreur est survenue, veuillez réessayer."); return; }
  if (!d.name || !d.name.trim()) { showToast(t("toast_enter_fullname")); return; }
  if (!d.phone || !d.phone.trim()) { showToast(t("toast_enter_phone1")); return; }
  var digits = stripTrunkZero(d.countryCode, d.phone);
  var fullPhone = d.countryCode + digits;
  var nameNorm = d.name.trim().toLowerCase();
  // On cherche d'abord par nom + téléphone SEULS — le mot de passe, s'il y
  // en a un, est vérifié ensuite séparément. Avant, "a.password &&
  // a.password === d.password" exigeait un mot de passe même pour un
  // compte qui n'en a jamais créé (ex : quelqu'un qui n'a fait que
  // regarder le marché, jamais acheté ni envoyé d'argent) — ce compte
  // devenait alors impossible à retrouver sur un nouvel appareil ou après
  // réinstallation, aucun mot de passe ne pouvant jamais correspondre.
  var candidate = state.accounts.find(function(a) {
    var aPhoneDigits = (a.phone || "").replace(/\D/g, "");
    var phoneMatches = aPhoneDigits === (d.countryCode + digits).replace(/\D/g, "") || aPhoneDigits.endsWith(digits);
    return phoneMatches && (a.name || "").trim().toLowerCase() === nameNorm;
  });
  if (!candidate) {
    // Les numéros ne sont plus dans la liste publique des comptes : on
    // demande au serveur de retrouver le compte (il ne renvoie que son
    // identifiant et s'il a un mot de passe).
    secureWrite("accounts", { operation: "find_account", name: d.name.trim(), phone: digits, fullPhone: fullPhone }).then(function(res) {
      if (!res || res.notDeployed || !res.found) { showToast(t("toast_no_account_name_number")); return; }
      var found = null;
      for (var fi = 0; fi < state.accounts.length; fi++) { if (state.accounts[fi].id === res.accountId) { found = state.accounts[fi]; break; } }
      if (!found) { found = { id: res.accountId, name: d.name.trim() }; state.accounts.push(found); }
      found.hasPassword = !!res.hasPassword;
      finishFindAccount(found, d);
    }).catch(function() { showToast(t("toast_no_account_name_number")); });
    return;
  }
  finishFindAccount(candidate, d);
}
function finishFindAccount(candidate, d) {
  if (candidate.hasPassword) {
    if (!d.password) { showToast(t("toast_account_has_password_enter")); return; }
    verifyAccountPassword(candidate.id, d.password).then(function(match) {
      if (!match) { showToast(t("toast_incorrect_password")); return; }
      state.showFindAccountModal = false;
      loginAccount(candidate.id);
      showToast(t("dt_welcome_back") + candidate.name + t("dt_exclaim"));
    });
    return;
  }
  // Sans mot de passe : avant, aucune clé n'était donnée — le téléphone
  // semblait connecté mais le serveur refusait toutes ses commandes.
  var fdDigits = stripTrunkZero(d.countryCode, d.phone);
  secureWrite("accounts", { operation: "find_account", name: String(d.name || "").trim(), phone: fdDigits, fullPhone: d.countryCode + fdDigits }).then(function(res) {
    if (res && res.found && res.hasPassword) { candidate.hasPassword = true; showToast(t("toast_account_has_password_enter")); render(); return; }
    if (res && res.found && res.accountId === candidate.id && res.sessionToken) state.sessionToken = res.sessionToken;
    state.showFindAccountModal = false;
    loginAccount(candidate.id);
    showToast(t("dt_welcome_back") + candidate.name + t("dt_exclaim"));
    if (res && res.sessionToken) setTimeout(function() { requirePasswordSetup("afterReconnect"); }, 1500);
    else if (res && res.needsHelp) { state.reconnectNeedsHelp = true; state.showReconnectSheet = true; render(); }
  }).catch(function() {
    state.showFindAccountModal = false;
    loginAccount(candidate.id);
  });
}

function loginAccount(accountId) {
  var account = null;
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === accountId) {
      account = state.accounts[i];
      break;
    }
  }
  if (!account) return;
  if (account.banned) {
    showToast(t("toast_account_banned"));
    return;
  }
  markDeviceAccount(account.id);
  state.profile = { ...account };
  if (account.language && SUPPORTED_LANGUAGES.indexOf(account.language) !== -1) {
    state.language = account.language;
    try { localStorage.setItem("sounsouni_language", account.language); } catch (e) {}
  }
  state.view = ROLE_HOME_VIEW[account.role] || "market";
  state.showVendorHub = false;
  state.showRoleMenu = false;
  save();
  saveDoc("accounts", account);
  fetchMyWalletState();
  fetchMyAddresses();
  fetchMyOrderContacts();
  fetchMyOrderDetails();
  callAdminAccessOperation({ operation: "record_login" });
  setTimeout(trackVisit, 1500);
  render();
}

// Suppression complète d'un compte — utilisée à la fois depuis l'Admin et
// depuis "Supprimer mon compte" (Profil). Retire aussi tout ce qui
// appartient EXCLUSIVEMENT à ce compte (produits en vente, portefeuille,
// gains, jetons de notification). Les commandes déjà passées restent
// intactes : elles appartiennent aussi à l'autre partie (acheteur ou
// vendeur) et les supprimer casserait son propre historique.
function deleteAccountCompletely(accountId) {
  var acc = state.accounts.find(function(a) { return a.id === accountId; });
  if (!acc) return;
  state.products = state.products.filter(function(p) {
    if (p.sellerId === accountId) { deleteRemoteDoc("products", p.id); return false; }
    return true;
  });
  if (acc.phone) {
    // ⚠️ Le portefeuille et les gains ne peuvent plus être supprimés
    // directement depuis ici : ces deux collections n'acceptent plus
    // aucune écriture directe du navigateur (voir le verrouillage de la
    // base), et ne sont plus téléchargées en bloc non plus (voir
    // SHARED_KEYS) — donc rien à filtrer localement ici. Le solde du
    // compte supprimé reste tel quel côté serveur pour l'instant ; une
    // vraie suppression demanderait une opération dédiée dans
    // wallet-write, réservée à un Admin authentifié (pas encore en place).
  }
  state.fcmTokens = (state.fcmTokens || []).filter(function(t) {
    if (t.accountId === accountId) { deleteRemoteDoc("fcmTokens", t.id); return false; }
    return true;
  });
  state.pushSubscriptions = (state.pushSubscriptions || []).filter(function(s) {
    if (s.accountId === accountId) { deleteRemoteDoc("pushSubscriptions", s.id); return false; }
    return true;
  });
  state.accounts = state.accounts.filter(function(a) { return a.id !== accountId; });
  deleteRemoteDoc("accounts", accountId);
  if (state.deviceAccountIds) state.deviceAccountIds = state.deviceAccountIds.filter(function(id) { return id !== accountId; });
  save();
}

function logout() {
  if (state.profile) {
    refreshProfileFromAccounts();
    for (var i = 0; i < state.accounts.length; i++) {
      if (state.accounts[i].id === state.profile.id) {
        state.accounts[i] = { ...state.profile };
        break;
      }
    }
  }
  state.profile = null;
  state.adminUnlocked = false;
  state.adminCountryScope = null;
  state.onboardMode = state.accounts.length > 0 ? "list" : "form";
  state.showRoleMenu = false;
  state.seasonalEffects.enabled = false;
  state.chatOpen = false;
  stopSeasonalEffects();
  save();
  render();
}

function switchRole(role) {
  // Vérifiée tout en haut, INCONDITIONNELLEMENT, avant même de regarder si
  // l'admin est déjà déverrouillé — sinon, un compte ayant déjà déverrouillé
  // l'accès admin au moins une fois auparavant (drapeau qui reste vrai
  // indéfiniment, jamais remis à zéro) sautait complètement cette
  // vérification et atterrissait dans l'admin général au lieu de son
  // espace Agent Sourcing dédié.
  if (role === "admin") {
    var myPhoneForSourcing = state.profile ? state.profile.phone : null;
    // Deux façons différentes de devenir Agent Sourcing existent dans
    // l'app (liste blanche par numéro, OU bouton "Nommer Agent Sourcing"
    // direct côté Admin sur la fiche d'un compte) — il faut vérifier les
    // deux ici, sinon un compte devenu agent par la seconde méthode ne
    // passait jamais par ce raccourci et atterrissait dans l'admin général.
    var isSourcingAgentNow = (state.profile && state.profile.isSourcingAgent) ||
      (myPhoneForSourcing && isPhoneOnSourcingAgentWhitelist(myPhoneForSourcing));
    if (isSourcingAgentNow) {
      applyRoleSwitch("agent_sourcing");
      return;
    }
  }
  var staleAdminSession = state.adminUnlocked && typeof state.adminIsOwner !== "boolean";
  if (RESTRICTED_ROLES.indexOf(role) !== -1 && (!state.adminUnlocked || staleAdminSession)) {
    // Groupe 2 (accès limité) n'a plus de mot de passe — juste une liste
    // blanche de numéros gérée par le Groupe 1 (voir Admin > Sécurité).
    // Si le compte actuellement connecté est sur l'une des deux listes
    // (globale ou celle d'un pays), l'accès s'ouvre directement, sans
    // jamais passer par la fenêtre de mot de passe ci-dessous.
    var myPhoneForG2 = state.profile ? state.profile.phone : null;
    if (myPhoneForG2 && isPhoneOnGroup2GlobalWhitelist(myPhoneForG2)) {
      state.adminUnlocked = true;
      state.adminIsOwner = false;
      state.adminCountryScope = null;
      applyRoleSwitch(role);
      return;
    }
    if (myPhoneForG2) {
      var naForG2 = findNationalAdminByEmployeePhone(myPhoneForG2);
      if (naForG2) {
        state.adminUnlocked = true;
        state.adminIsOwner = false;
        state.adminCountryScope = naForG2.country;
        applyRoleSwitch(role);
        return;
      }
    }
    state.adminUnlocked = false;
    state.pendingRole = role;
    state.adminPreviousRole = state.profile.role !== "admin" ? state.profile.role : (state.adminPreviousRole || "acheteur");
    state.showRoleMenu = false;
    state.showAdminGate = true;
    state.adminGateChosenGroup = null;
    state.adminGateUser = "";
    state.adminGatePass = "";
    state.adminGateError = "";
    save();
    render();
    return;
  }
  if (role === "point_vente" && state.profile.relaisApplicationStatus !== "approved") {
    var linkedRelais = findLinkedApprovedRelais(state.profile);
    if (linkedRelais) {
      state.showRoleMenu = false;
      switchToLinkedAccount(linkedRelais.id);
      applyRoleSwitch("point_vente");
      showToast("✅ Accès à votre Point de Retrait partagé (" + esc(linkedRelais.shopName) + ").");
      return;
    }
    state.showRoleMenu = false;
    showToast(t("toast_not_approved_pickup_yet"));
    render();
    return;
  }
  if (role === "livreur" && state.profile.livreurApplicationStatus !== "approved") {
    state.showRoleMenu = false;
    showToast(t("toast_not_approved_livreur_yet"));
    render();
    return;
  }
  applyRoleSwitch(role);
}

function applyRoleSwitch(role) {
  // Le déverrouillage du panneau Admin passe aussi par ici (via
  // applyRoleSwitch("admin")) — mais "admin" n'est PAS un vrai rôle de
  // navigation comme acheteur/vendeur/livreur : c'est un panneau à part,
  // qui ne doit jamais toucher au compte réel. Avant ce correctif, ça
  // écrasait — et ENREGISTRAIT EN BASE — le rôle du compte normal en
  // "admin", à chaque déverrouillage. On se contente ici de changer
  // l'écran affiché, sans rien modifier ni sauvegarder sur le compte.
  if (role === "admin") {
    state.view = "admin";
    state.showRoleMenu = false;
    render();
    return;
  }
  refreshProfileFromAccounts();
  state.profile.role = role;
  // "isSourcingAgent" est un statut PERMANENT du compte, séparé du rôle
  // actuel de navigation — sans cette distinction, un agent qui bascule
  // ensuite en "Acheteur" pour parcourir le marché "perdait" son statut
  // d'agent partout ailleurs (liste déroulante du vendeur international,
  // vérification admin...), puisque ces endroits ne regardaient que le
  // rôle courant, qui change à chaque navigation. Une fois activé, ce
  // statut reste vrai indéfiniment (sauf retrait explicite par l'Admin
  // de la liste blanche — voir "remove-sourcing-agent-whitelist").
  if (role === "agent_sourcing") state.profile.isSourcingAgent = true;
  if (role === "vendeur" && !state.profile.shopName) {
    state.profile.shopName = "Boutique de " + state.profile.name;
    state.profile.sellerType = state.profile.sellerType || "particulier";
  }
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === state.profile.id) {
      state.accounts[i] = { ...state.profile };
      break;
    }
  }
  if (role === "vendeur" && !sellerProfileComplete(state.profile)) {
    state.view = "sellerProfileSetup";
    state.showVendorHub = false;
  } else {
    state.view = ROLE_HOME_VIEW[role] || "market";
    state.showVendorHub = (role === "vendeur");
  }
  state.showRoleMenu = false;
  save();
  saveDoc("accounts", state.profile);
  render();
}

// Groupe 2 n'a plus de mot de passe (voir switchRole, liste blanche par
// numéro) — cette fenêtre ne sert donc plus qu'au Groupe 1 (accès complet,
// global ou national), avec vérification hachée du mot de passe.
function submitAdminGate() {
  var creds = getAdminCredentials("owner");
  var enteredUser = state.adminGateUser.trim();
  var enteredPass = state.adminGatePass;

  function tryNationalOwnerMatch() {
    var candidates = (state.nationalAdmins || []).filter(function(na) { return na.ownerUsername === enteredUser; });
    var checkNext = function(idx) {
      if (idx >= candidates.length) {
        state.adminGateError = "Identifiants incorrects pour cet espace.";
        render();
        return;
      }
      var na = candidates[idx];
      verifyAccountPassword("national_admin_" + na.id, enteredPass).then(function(match) {
        if (match) {
          state.adminUnlocked = true;
          state.adminIsOwner = true;
          state.adminCountryScope = na.country;
          state.adminActiveAccountId = "national_admin_" + na.id;
          state.showAdminGate = false;
          state.adminGateChosenGroup = null;
          applyRoleSwitch(state.pendingRole);
        } else {
          checkNext(idx + 1);
        }
      });
    };
    checkNext(0);
  }

  if (enteredUser === creds.username) {
    // Seule porte d'entrée : le serveur vérifie le mot de passe (la porte
    // de secours qui comparait avec un mot de passe écrit dans l'app a été
    // supprimée — ce mot de passe était lisible dans le code public du site).
    verifyAccountPassword("admin_owner", enteredPass).then(function(match) {
      if (match) {
        state.adminUnlocked = true;
        state.adminIsOwner = true;
        state.adminCountryScope = null; // Groupe 1 global : voit tout, tous pays
        state.adminActiveAccountId = "admin_owner";
        state.showAdminGate = false;
        state.adminGateChosenGroup = null;
        // Affiché dans Admin > Test > journal de debug, pour pouvoir copier
        // le jeton depuis le téléphone (utile pour tester une fonction
        // serveur avec X-Session-Token sans avoir besoin d'un ordinateur).
        pushDebugLog("info", "Jeton Admin", state.adminSessionToken ? "obtenu" : "(aucun jeton obtenu)");
        applyRoleSwitch(state.pendingRole);
        return;
      }
      tryNationalOwnerMatch();
    });
  } else {
    tryNationalOwnerMatch();
  }
}

function toggleFavorite(productId) {
  if (!state.profile) return;
  var wasFavorite = Array.isArray(state.profile.favorites) && state.profile.favorites.indexOf(productId) !== -1;
  refreshProfileFromAccounts();
  if (!Array.isArray(state.profile.favorites)) state.profile.favorites = [];
  var idx = state.profile.favorites.indexOf(productId);
  if (wasFavorite) {
    if (idx !== -1) state.profile.favorites.splice(idx, 1);
  } else {
    if (idx === -1) state.profile.favorites.push(productId);
  }
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === state.profile.id) {
      state.accounts[i] = { ...state.profile };
      break;
    }
  }
  save();
  saveDoc("accounts", state.profile);
  render();
}

// ---------- VOTES "J'AIME / J'AIME PAS" SUR UN ARTICLE ----------
// Un simple pouce haut/bas, distinct des avis écrits — un acheteur ne peut
// avoir qu'un seul vote actif par article à la fois (revoter change
// l'avis précédent, revoter pareil l'annule).
function toggleProductVote(productId, voteType) {
  if (!state.profile) return;
  var product = state.products.find(function(pr) { return pr.id === productId; });
  if (!product) return;
  if (!Array.isArray(product.likedBy)) product.likedBy = [];
  if (!Array.isArray(product.dislikedBy)) product.dislikedBy = [];
  var uidAcc = state.profile.id;
  var likedIdx = product.likedBy.indexOf(uidAcc);
  var dislikedIdx = product.dislikedBy.indexOf(uidAcc);
  if (voteType === "like") {
    if (likedIdx !== -1) { product.likedBy.splice(likedIdx, 1); }
    else { product.likedBy.push(uidAcc); if (dislikedIdx !== -1) product.dislikedBy.splice(dislikedIdx, 1); }
  } else {
    if (dislikedIdx !== -1) { product.dislikedBy.splice(dislikedIdx, 1); }
    else { product.dislikedBy.push(uidAcc); if (likedIdx !== -1) product.likedBy.splice(likedIdx, 1); }
  }
  save();
  saveDoc("products", product);
  render();
}

// Adresse publique du site : TOUS les liens partagés l'utilisent. Avant,
// ils utilisaient l'adresse actuelle de la page — qui, dans l'application
// installée, est une adresse interne au téléphone (liens morts pour les
// autres, et parrainages jamais transmis).
var PUBLIC_SITE_URL = "https://sounsouni.pro";

// Lien d'un article : ouvre directement la fiche, et porte le code de
// parrainage de la personne qui partage (chaque partage est aussi un lien
// d'affiliation).
function productShareUrl(p) {
  // Lien court vers la page de partage de l'article (p/<id>) : WhatsApp,
  // Facebook… y lisent la photo, le prix et la description pour l'aperçu,
  // puis la page renvoie aussitôt vers l'article dans l'app.
  var url = PUBLIC_SITE_URL + "/p/" + encodeURIComponent(p.id);
  var code = null;
  try { code = state.profile ? getReferralCode() : null; } catch (e) {}
  if (code) url += "?ref=" + encodeURIComponent(code);
  return url;
}
function shareProduct(productId) {
  var p = null;
  for (var i = 0; i < state.products.length; i++) {
    if (state.products[i].id === productId) {
      p = state.products[i];
      break;
    }
  }
  if (!p) return;
  var url = productShareUrl(p);
  var text = productDisplayName(p) + " — " + money(p.price) + " — Sounsouni (" + (p.shopName || "") + ")";
  var copyFallback = function() {
    var full = text + "\n" + url;
    var done = function() { showToast(t("toast_product_details_copied")); };
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(full).then(done, function() { showToast(full); });
    else showToast(full);
  };
  // Application installée : fenêtre de partage native d'Android
  var capShare = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Share;
  if (capShare && capShare.share) {
    capShare.share({ title: productDisplayName(p), text: text, url: url, dialogTitle: productDisplayName(p) }).catch(function(err) {
      if (!(err && /cancel/i.test(String(err.message || err)))) copyFallback();
    });
    return;
  }
  if (navigator.share) {
    navigator.share({ title: productDisplayName(p), text: text, url: url }).catch(function(err) {
      if (!(err && err.name === "AbortError")) copyFallback();
    });
    return;
  }
  copyFallback();
}

function getTieredTotal(product, qty) {
  var unitPrice = getTieredPrice(product, qty);
  return unitPrice * qty;
}
// ============================================================
// GEMS — Logique complète — PARTIE 3/6
// ============================================================

// ---------- CART ----------
// Crée une demande de réservation pour un service (pas de panier, pas de
// livraison — juste une demande envoyée au vendeur, qui organise le
// paiement et le rendez-vous directement avec le client).
function createBooking(productId, note) {
  if (!state.profile) return;
  var product = null;
  for (var i = 0; i < state.products.length; i++) {
    if (state.products[i].id === productId) { product = state.products[i]; break; }
  }
  if (!product) { showToast(t("toast_service_no_longer_exists")); return; }
  if (product.stock <= 0) { showToast(t("toast_service_unavailable")); return; }

  var booking = {
    id: uid(),
    productId: product.id,
    productName: product.name,
    price: product.price,
    sellerId: product.sellerId,
    sellerName: product.sellerName,
    sellerPhone: product.sellerPhone,
    buyerId: state.profile.id,
    buyerName: state.profile.name,
    buyerPhone: state.profile.phone,
    note: (note || '').trim(),
    status: "Nouvelle",
    createdAt: Date.now()
  };
  state.bookings.push(booking);
  addNotification("whatsapp", "📅 Nouvelle demande de réservation pour \"" + product.name + "\" — " + state.profile.name + " (" + state.profile.phone + ")", product.sellerId);
  save();
  saveDoc("bookings", booking);
  state.detailProductId = null;
  render();
  showToast(t("toast_request_sent_seller_recontact"));
}

// La livraison Express/Point de Retrait n'existe physiquement qu'au Mali
// (communes/quartiers réels, livreurs sur place) — aucune vraie logistique
// n'existe pour livrer un article local jusqu'à l'étranger. Un compte
// enregistré depuis un autre pays (ex : Inde) ne peut donc acheter QUE
// des articles "Vendeur International" (qui ont leur propre circuit —
// agent de sourcing, groupage), jamais un article local malien classique.
function blockedByMissingInternationalLogistics(product) {
  if (!state.profile || !state.profile.country || state.profile.country === "Mali") return false;
  if (product.sellerType === "international") return false;
  return product.country !== state.profile.country;
}

function addToCart(productId, qty, color, size) {
  if (isDigitalProduct(findProductById(productId))) { openDigitalBuy(productId); return; }
  var product = null;
  for (var i = 0; i < state.products.length; i++) {
    if (state.products[i].id === productId) {
      product = state.products[i];
      break;
    }
  }
  if (!product || product.stock <= 0) {
    showToast(t("toast_out_of_stock"));
    return;
  }
  if (isProductHiddenFromPublic(product)) {
    showToast("Cet article n'est pas disponible pour le moment.");
    return;
  }
  if (blockedByMissingInternationalLogistics(product)) {
    showToast(t("dt_no_intl_delivery_yet"));
    return;
  }
  // Un article international (prix en Roupies, groupage, transport séparé)
  // ne peut jamais se mélanger avec des articles locaux (FCFA, livraison
  // Express/Point de Retrait) dans le même panier — les deux systèmes de
  // calcul et de livraison sont incompatibles. On bloque avant l'ajout,
  // plutôt que de laisser un panier dans un état incohérent.
  var existingCartItemsForMix = cartDetails();
  if (existingCartItemsForMix.length > 0) {
    var cartHasInternational = existingCartItemsForMix.some(function(it) { return it.sellerType === "international"; });
    var thisIsInternational = product.sellerType === "international";
    if (cartHasInternational !== thisIsInternational) {
      showToast(thisIsInternational ? t("dt_cannot_mix_intl_into_local") : t("dt_cannot_mix_local_into_intl"));
      return;
    }
  }
  if (product.colors && product.colors.length > 0 && !color) {
    showToast(t("toast_choose_color"));
    return;
  }
  if (product.sizes && product.sizes.length > 0 && !size) {
    showToast(t("toast_choose_size"));
    return;
  }
  // Vendeur international : impossible d'acheter moins que la quantité
  // minimum fixée par le vendeur — le groupage ne fonctionne qu'à partir
  // de ce seuil (transitaire, coûts de transport partagés...).
  if (product.sellerType === "international" && product.moq && (qty || 1) < Number(product.moq)) {
    showToast(t("dt_moq_not_reached_a") + product.moq + t("dt_moq_not_reached_b"));
    return;
  }
  var quantity = Math.max(1, qty || 1);
  var lineId = cartLineId(productId, color, size);
  var existing = null;
  for (var j = 0; j < state.cart.length; j++) {
    if (state.cart[j].lineId === lineId && state.cart[j].buyerId === cartOwnerId()) {
      existing = state.cart[j];
      break;
    }
  }
  if (existing) {
    existing.qty = Math.min(existing.qty + quantity, product.stock);
  } else {
    state.cart.push({ lineId: lineId, buyerId: cartOwnerId(), productId: productId, qty: Math.min(quantity, product.stock), color: color || null, size: size || null });
  }
  save();
  showToast(t("dt_added_to_cart") + product.name);
  state.selectedQty = 1;
  state.selectedColor = null;
  state.selectedSize = null;
  render();
}

function setCartQty(lineId, qty) {
  var item = null;
  for (var i = 0; i < state.cart.length; i++) {
    if (state.cart[i].lineId === lineId && state.cart[i].buyerId === cartOwnerId()) {
      item = state.cart[i];
      break;
    }
  }
  if (!item) return;
  var product = null;
  for (var j = 0; j < state.products.length; j++) {
    if (state.products[j].id === item.productId) {
      product = state.products[j];
      break;
    }
  }
  if (qty <= 0) {
    state.cart = state.cart.filter(function(it) { return it.lineId !== lineId || it.buyerId !== cartOwnerId(); });
  } else if (product && product.sellerType === "international" && product.moq && qty < Number(product.moq)) {
    // On ne bloque pas silencieusement : on remonte directement au seuil
    // minimum plutôt que de laisser une quantité invalide dans le panier.
    item.qty = Math.min(Number(product.moq), product.stock);
    showToast(t("dt_moq_not_reached_a") + product.moq + t("dt_moq_not_reached_b"));
  } else {
    item.qty = Math.min(qty, product ? product.stock : qty);
  }
  save();
  render();
}

function cartDetails() {
  var result = [];
  for (var i = 0; i < state.cart.length; i++) {
    var item = state.cart[i];
    if (item.buyerId !== cartOwnerId()) continue;
    var product = null;
    for (var j = 0; j < state.products.length; j++) {
      if (state.products[j].id === item.productId) {
        product = state.products[j];
        break;
      }
    }
    if (product) {
      result.push({ ...product, qty: item.qty, color: item.color, size: item.size, lineId: item.lineId });
    }
  }
  return result;
}

function cartTotal() {
  var items = cartDetails();
  var total = 0;
  for (var i = 0; i < items.length; i++) {
    total += getTieredTotal(items[i], items[i].qty);
  }
  return total;
}

function cartCount() {
  var count = 0;
  for (var i = 0; i < state.cart.length; i++) {
    if (state.cart[i].buyerId !== cartOwnerId()) continue;
    var exists = false;
    for (var j = 0; j < state.products.length; j++) {
      if (state.products[j].id === state.cart[i].productId) { exists = true; break; }
    }
    if (exists) count += state.cart[i].qty;
  }
  return count;
}

// ---------- PRODUITS NUMÉRIQUES : ACHAT ET ACCÈS ----------
function findProductById(id) { for (var i = 0; i < state.products.length; i++) if (state.products[i].id === id) return state.products[i]; return null; }
// Commande payée dont l'accès peut être demandé (le serveur revérifie tout).
function digitalPaidOrderFor(productId) {
  if (!state.profile) return null;
  var list = (state.orders || []).filter(function(o) {
    return o && o.buyerId === state.profile.id && o.status !== "Annulée" && (o.items || []).some(function(it) { return it.productId === productId; }) &&
      ((o.payment === "ligdicash" && o.paymentStatus === "paid") || (o.payment === "portefeuille" && o.paymentStatus === "paid"));
  });
  list.sort(function(a, b) { return (b.createdAt || 0) - (a.createdAt || 0); });
  return list[0] || null;
}
function openDigitalBuy(productId) {
  var p = findProductById(productId);
  if (!p) { showToast(t("toast_product_no_longer_exists")); return; }
  if (state.profile && p.sellerId === state.profile.id) { showToast(t("dig_own_product")); return; }
  var already = digitalPaidOrderFor(productId);
  if (already) { digitalOpen(already.id, productId); return; }
  state.detailProductId = null;
  state.digitalBuy = { productId: productId };
  try { fetchMyWalletState(); } catch (e) {}
  render();
}
function createDigitalOrder(p, payment, paid) {
  var price = getTieredPrice(p, 1);
  var now = Date.now();
  var vs = {}; vs[p.sellerId] = "Nouvelle";
  return {
    id: uid(), buyerId: state.profile.id, buyerName: state.profile.name, buyerPhone: state.profile.phone,
    items: [{ productId: p.id, name: p.name, price: price, qty: 1, color: null, size: null, sellerId: p.sellerId, sellerPhone: p.sellerPhone, sellerName: p.shopName || p.sellerName, refused: false }],
    subtotal: price, deliveryFee: 0, total: price, payment: payment, paymentStatus: paid ? "paid" : "pending_payment",
    status: "Nouvelle", statusHistory: [{ status: "Nouvelle", at: now }], vendorStatuses: vs, sellerIds: [p.sellerId],
    createdAt: now, isDigital: true, deliveryMode: "numerique", city: "", zone: "", country: p.country || "Mali"
  };
}
function digitalBuyWith(method) {
  var db0 = state.digitalBuy; if (!db0) return;
  var p = findProductById(db0.productId); if (!p) { state.digitalBuy = null; render(); return; }
  var price = getTieredPrice(p, 1);
  state.digitalBuy = null;
  state.quickBuyItem = true; // ne pas vider le panier
  if (method === "ligdicash") {
    if (!ligdiAmountOk(price)) { state.quickBuyItem = null; render(); return; }
    finalizeOrder(createDigitalOrder(p, "ligdicash", false), { awaitingPayment: true });
    return;
  }
  // Portefeuille : débit réel vérifié par le serveur, puis accès immédiat.
  var order = createDigitalOrder(p, "portefeuille", true);
  state.digitalBuying = true; render();
  createOrderOnServerFirst(order).then(function(res) {
    state.digitalBuying = false;
    if (!res || !res.success) { state.quickBuyItem = null; render(); showOrderCreateError(res); return; }
    fetchMyWalletState();
    finalizeOrder(order, { simulated: false, alreadyOnServer: true });
    Promise.resolve(window.__lastOrderSaved).then(function() { setTimeout(function() { digitalOpen(order.id, p.id); }, 1200); });
  });
}
// Demande au serveur l'accès (lien de téléchargement privé valable 1 h, ou
// lien de la formation) puis l'ouvre.
function digitalOpen(orderId, productId, attempt) {
  attempt = attempt || 0;
  if (!FIREBASE_ENABLED) { showToast(t("toast_payment_unavailable_offline")); return; }
  if (attempt === 0) { state.digitalOpening = true; render(); }
  callLigdiFunction("digital-access", { operation: "get_access", orderId: orderId, productId: productId }).then(function(res) {
    if (res && !res.success && (res.error === "forbidden" || res.error === "not_paid") && attempt < 3) { setTimeout(function() { digitalOpen(orderId, productId, attempt + 1); }, [1500, 3000, 6000][attempt]); return; }
    state.digitalOpening = false;
    if (!res || !res.success) {
      render();
      var em = { not_paid: "dig_err_not_paid", no_content: "dig_err_no_content", order_cancelled: "dig_err_cancelled", forbidden: "dig_err_not_paid", not_in_order: "dig_err_not_paid" };
      showToast("❌ " + t(em[res && res.error] || "dig_err_access"));
      return;
    }
    var o = (state.orders || []).find(function(x) { return x.id === orderId; });
    if (o && o.isDigital && o.status !== "Livrée") {
      o.status = "Livrée"; o.deliveredAt = o.deliveredAt || Date.now();
      o.statusHistory = (o.statusHistory || []).concat([{ status: "Livrée", at: o.deliveredAt }]);
      save();
    }
    if (o && o.isDigital) { try { settleOrderPayouts(o); } catch (e) {} }
    state.digitalReady = { url: res.url, kind: res.kind, fileName: res.fileName || "" };
    render();
    var isNative = false; try { isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()); } catch (e) {}
    var w = null;
    if (!isNative) { try { w = window.open(res.url, "_blank", "noopener"); } catch (e) {} }
    else { setTimeout(function() { window.location.href = res.url; }, 60); w = true; }
    state.digitalReady.opened = !!w;
    render();
  });
}
function renderDigitalBuyModal() {
  var b = state.digitalBuy; if (!b) return "";
  var p = findProductById(b.productId); if (!p) return "";
  var price = getTieredPrice(p, 1);
  var wal = state.profile ? getWallet(state.profile.phone) : { balance: 0 };
  var html = '<div class="modal-overlay" style="z-index:9995;"><div class="modal-sheet" style="padding:20px 16px;">';
  html += '<div style="font-size:36px;text-align:center;">' + ((categoryByName(p.category) || {}).icon || "📥") + '</div>';
  html += '<div style="font-weight:800;font-size:16px;text-align:center;margin:4px 0;word-break:break-word;">' + esc(productDisplayName(p)) + '</div>';
  html += '<div style="font-weight:800;font-size:20px;text-align:center;color:var(--accent);margin-bottom:10px;">' + money(price, p.country) + '</div>';
  html += '<div style="font-size:12px;color:var(--text-dim);background:var(--bg-body);border-radius:10px;padding:9px 11px;margin-bottom:14px;line-height:1.5;"><i class="fa-solid fa-cloud-arrow-down"></i> ' + t(p.digitalKind === "link" ? "dig_buy_info_link" : "dig_buy_info_file") + '</div>';
  if (ligdicashEnabled(p.country || "Mali")) html += '<button class="btn-primary" style="width:100%;margin-bottom:8px;background:#ff7900;border-color:#ff7900;" data-action="digital-buy-with" data-value="ligdicash"><i class="fa-solid fa-mobile-screen"></i> ' + t("ligdi_option") + '</button>';
  var enough = Number(wal.balance || 0) >= price;
  html += '<button class="btn-secondary" style="width:100%;margin-bottom:8px;" data-action="digital-buy-with" data-value="portefeuille" ' + (enough ? '' : 'disabled') + '><i class="fa-solid fa-wallet"></i> ' + t("dig_buy_wallet") + ' (' + money(wal.balance || 0) + ')</button>';
  if (!enough) html += '<div style="font-size:11px;color:var(--text-dim);text-align:center;margin:-2px 0 8px;">' + t("dig_buy_wallet_low") + '</div>';
  html += '<button class="link-btn" style="width:100%;" data-action="digital-buy-close">' + t("cancel_generic") + '</button>';
  html += ligdiBrandLine();
  html += '</div></div>';
  return html;
}
function renderDigitalReadyModal() {
  var r = state.digitalReady;
  if (state.digitalOpening || state.digitalBuying) return '<div class="modal-overlay" style="z-index:9997;"><div class="modal-sheet" style="text-align:center;padding:30px 20px;"><div style="font-size:30px;color:var(--accent);margin-bottom:10px;"><i class="fa-solid fa-spinner fa-spin"></i></div><div style="font-weight:800;font-size:15px;">' + t("dig_preparing") + '</div></div></div>';
  if (!r) return "";
  var html = '<div class="modal-overlay" style="z-index:9997;"><div class="modal-sheet" style="text-align:center;padding:24px 18px;">';
  html += '<div style="font-size:44px;color:var(--success);margin-bottom:8px;"><i class="fa-solid ' + (r.kind === "link" ? 'fa-circle-play' : 'fa-file-arrow-down') + '"></i></div>';
  html += '<div style="font-weight:800;font-size:16px;margin-bottom:6px;">' + t(r.kind === "link" ? "dig_ready_link_title" : "dig_ready_file_title") + '</div>';
  if (r.fileName) html += '<div style="font-size:12px;color:var(--text-dim);margin-bottom:10px;word-break:break-all;">' + esc(r.fileName) + '</div>';
  html += '<a href="' + esc(r.url) + '" target="_blank" rel="noopener" class="btn-primary" style="display:flex;align-items:center;justify-content:center;gap:8px;text-decoration:none;margin-bottom:8px;"><i class="fa-solid ' + (r.kind === "link" ? 'fa-arrow-up-right-from-square' : 'fa-download') + '"></i> ' + t(r.kind === "link" ? "dig_open_link" : "dig_download") + '</a>';
  html += '<div style="font-size:10.5px;color:var(--text-dim);margin-bottom:10px;">' + t(r.kind === "link" ? "dig_ready_link_hint" : "dig_ready_file_hint") + '</div>';
  html += '<button class="link-btn" style="width:100%;" data-action="digital-ready-close">' + t("ligdi_btn_ok") + '</button>';
  html += '</div></div>';
  return html;
}
function buyNow(productId, qty, color, size) {
  if (isDigitalProduct(findProductById(productId))) { openDigitalBuy(productId); return; }
  var product = null;
  for (var i = 0; i < state.products.length; i++) {
    if (state.products[i].id === productId) {
      product = state.products[i];
      break;
    }
  }
  if (!product || product.stock <= 0) {
    showToast(t("toast_out_of_stock"));
    return;
  }
  if (blockedByMissingInternationalLogistics(product)) {
    showToast(t("dt_no_intl_delivery_yet"));
    return;
  }
  if (product.colors && product.colors.length > 0 && !color) {
    showToast(t("toast_choose_color"));
    return;
  }
  if (product.sizes && product.sizes.length > 0 && !size) {
    showToast(t("toast_choose_size"));
    return;
  }
  if (state.view !== "checkout") state.checkoutReturnView = state.view;
  state.quickBuyItem = { productId: productId, qty: Math.max(1, qty || 1), color: color || null, size: size || null };
  state.detailProductId = null;
  modalWasOpenFor = null;
  state.checkoutAddressExpanded = null;
  state.view = "checkout";
  save();
  render();
}

function checkoutItems() {
  if (state.quickBuyItem) {
    var p = null;
    for (var i = 0; i < state.products.length; i++) {
      if (state.products[i].id === state.quickBuyItem.productId) {
        p = state.products[i];
        break;
      }
    }
    return p ? [{ ...p, qty: state.quickBuyItem.qty, color: state.quickBuyItem.color, size: state.quickBuyItem.size }] : [];
  }
  return cartDetails();
}

function checkoutSubtotal() {
  var items = checkoutItems();
  var total = 0;
  for (var i = 0; i < items.length; i++) {
    total += getTieredTotal(items[i], items[i].qty);
  }
  return total;
}

// ---------- PANIER MULTI-BOUTIQUES ----------
function getCartByVendor() {
  var items = cartDetails();
  var groups = {};
  for (var i = 0; i < items.length; i++) {
    var item = items[i];
    var key = item.sellerId || 'unknown';
    if (!groups[key]) {
      groups[key] = {
        sellerId: key,
        sellerName: item.shopName || 'Boutique',
        items: [],
        subtotal: 0
      };
    }
    groups[key].items.push(item);
    groups[key].subtotal += getTieredTotal(item, item.qty);
  }
  return Object.values(groups);
}

// ---------- LIVRAISON MULTI-VENDEURS (Express vs Point de retrait) ----------
// Principe validé avec l'utilisateur : on part de la "somme brute" — ce que
// coûterait une livraison séparée chez chaque vendeur du panier — puis on
// applique un % dégressif selon le nombre de vendeurs, différent pour
// l'Express (tournée dédiée, pas de mutualisation) et le Relais (collecte
// groupée, de plus en plus rentable à mesure que le nombre de vendeurs
// grandit).
//
// Limite honnête à garder en tête : seuls les comptes vendeur "Entreprise/
// Établissement" ont une position GPS enregistrée (shopLat/shopLng) — les
// particuliers n'en ont pas. Faute de pouvoir calculer une vraie distance
// par vendeur pour tout le monde, le "frais individuel par vendeur" est
// approximé par le frais de la zone de l'ACHETEUR (baseFee) — c'est-à-dire
// qu'on suppose que chaque vendeur ajouté coûterait, seul, à peu près
// autant que le trajet de référence vers l'acheteur. Le jour où tous les
// vendeurs auront une position GPS, cette approximation pourra être
// remplacée par une vraie distance par vendeur, sans changer la structure
// des pourcentages ci-dessous.
var MULTI_VENDOR_EXPRESS_PCT = { 1: 1.00, 2: 0.60, 3: 0.60, 4: 0.60 }; // 5+ : 0.60 (plancher)
var MULTI_VENDOR_RELAIS_PCT_OF_EXPRESS = { 1: 0.70, 2: 0.65, 3: 0.62, 4: 0.60 }; // 5+ : 0.55 (plancher)

function computeMultiVendorDeliveryFee(baseFee, vendorCount, mode) {
  var n = Math.max(1, vendorCount || 1);
  var sumBrut = baseFee * n;
  var expressPct = MULTI_VENDOR_EXPRESS_PCT[n] || 0.60;
  var expressFee = Math.round((n === 1 ? baseFee : sumBrut * expressPct) / 5) * 5;
  if (mode === "relais") {
    var relaisPct = MULTI_VENDOR_RELAIS_PCT_OF_EXPRESS[n] || 0.55;
    return Math.round((expressFee * relaisPct) / 5) * 5;
  }
  return expressFee;
}

// Nombre de vendeurs distincts dans les articles à livrer (panier complet
// ou achat rapide) — sert de base au calcul ci-dessus.
function checkoutVendorCount() {
  var items = checkoutItems();
  var sellerIds = {};
  for (var i = 0; i < items.length; i++) {
    sellerIds[items[i].sellerId || 'unknown'] = true;
  }
  return Object.keys(sellerIds).length || 1;
}

// ---------- CHECKOUT ----------
// ---------- FINALISER UNE COMMANDE GROUPÉE INTERNATIONALE ----------
// Paiement manuel pour l'instant (pas de mobile money/portefeuille pour
// l'international) : l'acheteur paie l'équipe Sounsouni hors app, qui
// coordonne ensuite avec l'agent sourcing sur place — voir le statut
// "Paiement reçu" comme point de départ de la frise de suivi dédiée.
function placeInternationalOrder() {
  var items = checkoutItems();
  if (items.length === 0) {
    showToast(t("toast_cart_not_found"));
    return;
  }
  if (!state.profile.email || !state.profile.email.trim()) {
    state.showEmailRequiredModal = true;
    render();
    return;
  }
  var fH = state.checkoutForm;
  if (!fH.expressCommune || !fH.expressQuartier || !(fH.repere || "").trim()) { showToast(t("intlco_home_required")); return; }
  var modesOk = checkoutAvailableShippingModes();
  if (!modesOk.length) { showToast(t("intlco_no_mode")); return; }
  var mode = modesOk.indexOf(state.checkoutForm.internationalShippingMode) !== -1 ? state.checkoutForm.internationalShippingMode : modesOk[0];
  var isSea = mode === "maritime";
  var airBd = isSea ? computeSeaShippingBreakdown() : computeAirShippingBreakdown();
  var subtotalInr = checkoutSubtotal();
  var shippingCostInr = isSea ? Math.round((airBd.transportXof + airBd.marginXof) / (airBd.rate || 1)) : airBd.transportInr + airBd.marginInr;
  var totalInr = subtotalInr + shippingCostInr;
  var rate = airBd.rate;
  var totalXof = airBd.totalXof;
  var billableKg = airBd.billableKg;
  var orderId = uid();

  var orderDraft = {
    id: orderId,
    buyerId: state.profile.id,
    buyerName: state.profile.name,
    buyerPhone: state.profile.phone,
    contactPhone: (state.checkoutForm.contactPhone || "").trim() || state.profile.phone,
    country: items[0].country || "Inde",
    isInternational: true,
    items: [],
    subtotalInr: subtotalInr,
    shippingCostInr: shippingCostInr,
    totalInr: totalInr,
    exchangeRate: rate,
    total: totalXof,
    subtotal: airBd.goodsXof,
    deliveryFee: airBd.transportXof + airBd.marginXof + airBd.customsXof + airBd.homeXof,
    homeDeliveryXof: airBd.homeXof,
    city: "Bamako",
    zone: fH.expressCommune,
    commune: fH.expressCommune,
    quartier: fH.expressQuartier,
    repere: (fH.repere || "").trim(),
    buyerLat: fH.buyerLat != null ? fH.buyerLat : null,
    buyerLng: fH.buyerLng != null ? fH.buyerLng : null,
    airTransportInr: isSea ? null : airBd.transportInr,
    sounsouniFeeInr: isSea ? null : airBd.marginInr,
    seaTransportXof: isSea ? airBd.transportXof : null,
    sounsouniFeeXof: isSea ? airBd.marginXof : null,
    billableM3: isSea ? airBd.billableM3 : null,
    customsXof: airBd.customsXof,
    deliveryPoint: "Domicile",
    shippingMode: mode,
    billableWeightKg: isSea ? Math.round(airBd.realKg * 100) / 100 : billableKg,
    parcelsKg: isSea ? [] : airBd.parcels.map(function(x) { return x.kg; }),
    status: "Paiement reçu",
    statusHistory: [{ status: "Paiement reçu", at: Date.now(), note: null }],
    createdAt: Date.now(),
    deliveredAt: null,
    payment: ligdicashEnabled("Mali") ? "ligdicash" : "manuel_international",
    paymentStatus: "pending_verification",
    specialInstructions: state.checkoutForm.specialInstructions || "",
  };

  for (var i = 0; i < items.length; i++) {
    var it = items[i];
    orderDraft.items.push({
      productId: it.id,
      name: it.name,
      price: getTieredPrice(it, it.qty),
      qty: it.qty,
      color: it.color || null,
      size: it.size || null,
      sellerId: it.sellerId,
      sellerPhone: it.sellerPhone,
      sellerName: it.sellerName,
      poidsKg: it.poidsKg || null,
      volumeM3: it.volumeM3 || null,
      refused: false
    });
  }

  if (orderDraft.payment === "ligdicash") {
    if (!ligdiAmountOk(orderDraft.total)) return;
    orderDraft.paymentStatus = "pending_payment";
    finalizeOrder(orderDraft, { awaitingPayment: true });
    return;
  }
  finalizeOrder(orderDraft, { simulated: false });
}

function placeOrder() {
  pushDebugLog("info", "placeOrder() appelé", "payment=" + (state.checkoutForm && state.checkoutForm.payment));
  var items = checkoutItems();
  if (items.length === 0) {
    showToast(t("toast_cart_not_found"));
    return;
  }
  if (!state.profile.email || !state.profile.email.trim()) {
    state.showEmailRequiredModal = true;
    render();
    return;
  }
  var form = state.checkoutForm;
  // Point 6 : filet de sécurité final — le pays de la ville de livraison
  // choisie doit correspondre au pays de CHAQUE vendeur du panier. La
  // liste de villes proposée empêche déjà normalement ce cas, mais on
  // revérifie ici avant de finaliser, au cas où.
  var deliveryCountry = countryForCity(form.city);
  var mismatchedItem = items.find(function(it) { return it.country && it.country !== deliveryCountry; });
  if (mismatchedItem) {
    showToast(t("dt_delivery_impossible") + mismatchedItem.name + t("dt_sold_other_country"));
    return;
  }
  var isRelais = form.deliveryMode === "relais";

  if (isRelais) {
    if (!form.relaisShopId) {
      showToast(t("toast_choose_pickup_to_collect"));
      state.showAddressRequiredPopup = true;
      state.highlightAddressSection = true;
      render();
      scrollToAddressSection();
      return;
    }
  } else {
    if (!form.expressCommune || !form.expressQuartier) {
      showToast(t("toast_choose_commune_neighborhood"));
      state.showAddressRequiredPopup = true;
      state.highlightAddressSection = true;
      state.checkoutAddressExpanded = true;
      render();
      scrollToAddressSection();
      return;
    }
    // L'obligation du point de repère est désormais entièrement gérée en
    // amont (la fenêtre de rappel, avant même d'arriver ici) — avec sa
    // propre règle : obligatoire seulement si aucune position GPS n'est
    // enregistrée. La revérifier ici, à l'ancienne, bloquait la commande
    // même quand on avait le droit de continuer sans le remplir.
  }

  var relaisShop = null;
  if (isRelais) {
    for (var s = 0; s < state.accounts.length; s++) {
      if (state.accounts[s].id === form.relaisShopId) { relaisShop = state.accounts[s]; break; }
    }
    if (!relaisShop) {
      showToast(t("toast_pickup_unavailable"));
      return;
    }
  }

  var realFees = computeRealDeliveryFees(form.buyerLat, form.buyerLng, form.city, form.expressCommune, form.expressQuartier, form.zone);
  var deliveryFee = isRelais ? realFees.relaisFee : realFees.expressFee;
  var subtotal = checkoutSubtotal();
  var orderId = uid();

  var orderDraft = {
    id: orderId,
    buyerId: state.profile.id,
    buyerName: state.profile.name,
    buyerPhone: state.profile.phone,
    // Pays de la transaction — désormais celui de la VILLE DE LIVRAISON
    // choisie (voir countryForCity), comme demandé au point 6, plutôt que
    // celui du compte acheteur (utile pour la diaspora : un compte basé
    // ailleurs mais qui livre au Mali reste bien classé "Mali").    country: deliveryCountry,
    contactPhone: (form.contactPhone && form.contactPhone.trim()) ? form.contactPhone.trim() : state.profile.phone,
    items: [],
    subtotal: subtotal,
    deliveryFee: deliveryFee,
    total: subtotal + deliveryFee,
    city: form.city,
    zone: isRelais
      ? (form.relaisQuartier ? (form.relaisQuartier + (form.relaisCommune ? ', ' + form.relaisCommune : '')) : (form.relaisCommune || form.zone))
      : (form.expressQuartier ? (form.expressQuartier + (form.expressCommune ? ', ' + form.expressCommune : '')) : (form.expressCommune || form.zone)),
    repere: isRelais ? ("Retrait en point de retrait : " + relaisShop.shopName) : form.repere,
    payment: form.payment,
    status: "Nouvelle",
    statusHistory: [{ status: "Nouvelle", at: Date.now(), note: null }],
    createdAt: Date.now(),
    deliveredAt: null,
    livreurId: null,
    livreurName: null,
    livreurPhone: null,
    deliveryMode: isRelais ? "relais" : "express",
    relaisShopId: isRelais ? relaisShop.id : null,
    relaisShopName: isRelais ? relaisShop.shopName : null,
    specialInstructions: form.specialInstructions || "",
    // Conservés sur la commande — avant, calculés seulement pour le prix de
    // livraison puis jetés, donc invisibles au livreur une fois la commande
    // passée. Nécessaires pour la carte et le quartier affichés au livreur.
    quartier: isRelais ? (form.relaisQuartier || "") : (form.expressQuartier || ""),
    buyerLat: form.buyerLat || null,
    buyerLng: form.buyerLng || null,
  };

  if (isRelais) {
    // Deux codes distincts : un pour le dépôt du colis par le livreur en
    // boutique, un autre pour la remise au client (voir confirmRelaisDepot /
    // confirmRelaisRetrait). Volontairement différents l'un de l'autre.
    orderDraft.codeDepot = generateOTP();
    orderDraft.codeRetrait = generateOTP();
    orderDraft.commissionAmount = Math.round(deliveryFee * getRelaisCommissionRate());
    orderDraft.commissionSettled = false;
  } else {
    var otp = generateOTP();
    state.otpCodes[orderId] = otp;
    orderDraft.otp = otp;
  }

  for (var i = 0; i < items.length; i++) {
    var it = items[i];
    orderDraft.items.push({
      productId: it.id,
      name: it.name,
      price: getTieredPrice(it, it.qty),
      qty: it.qty,
      color: it.color || null,
      size: it.size || null,
      sellerId: it.sellerId,
      sellerPhone: it.sellerPhone,
      sellerName: it.sellerName,
      refused: false
    });
  }

  // Suivi par vendeur — chaque boutique concernée confirme (ou refuse) sa
  // propre part indépendamment des autres. La commande globale (order.status,
  // celle que voit le livreur) ne passe "Prête" qu'une fois que toutes les
  // boutiques encore actives ont confirmé la leur — voir sellerConfirmReady
  // et sellerRefuseItems.
  orderDraft.vendorStatuses = {};
  var seenSellerIdsInit = {};
  for (var vsi = 0; vsi < orderDraft.items.length; vsi++) {
    var sidInit = orderDraft.items[vsi].sellerId;
    if (!seenSellerIdsInit[sidInit]) { seenSellerIdsInit[sidInit] = true; orderDraft.vendorStatuses[sidInit] = "Nouvelle"; }
  }
  
  if (form.payment === "paiement_livraison") {
    pushDebugLog("info", "Branche paiement_livraison atteinte", "items=" + orderDraft.items.length + " orderId=" + orderDraft.id);
    orderDraft.paymentStatus = "paid"; // rien à attendre pour un paiement à la livraison
    finalizeOrder(orderDraft, { simulated: false });
    return;
  }

  if (form.payment === "portefeuille") {
    // Audit 29/10/2026 : c'est le serveur qui crée la commande ET débite le
    // portefeuille du vrai montant, en une seule fois (order-write, walletPay).
    // On ne finalise ici que si le serveur a vraiment accepté.
    orderDraft.paymentStatus = "paid";
    createOrderOnServerFirst(orderDraft).then(function(res) {
      if (!res || !res.success) { showOrderCreateError(res); return; }
      fetchMyWalletState();
      finalizeOrder(orderDraft, { simulated: false, alreadyOnServer: true });
    });
    return;
  }

  if (form.payment === "ligdicash") {
    if (!ligdicashEnabled(deliveryCountry)) { showToast(t("toast_mobile_money_not_active_country")); return; }
    if (!ligdiAmountOk(orderDraft.total)) return;
    orderDraft.paymentStatus = "pending_payment"; // passe à "paid" seulement après confirmation LigdiCash, côté serveur
    finalizeOrder(orderDraft, { awaitingPayment: true });
    return;
  }
  // Paiement mobile money — vérifie d'abord si un vrai service est réglé
  // pour ce pays (voir Admin → Sécurité → Paiement mobile money) avant de
  // créer la commande, pour ne jamais en créer une qu'on ne pourrait pas
  // faire payer.
  var payCfg = getPaymentConfig(deliveryCountry);
  if (payCfg.mode === "aggregator" && ["cinetpay", "paydunya", "flutterwave"].indexOf(payCfg.aggregator) !== -1) {
    orderDraft.paymentStatus = "pending_payment"; // passe à "paid" seulement une fois confirmé par le service de paiement (voir <service>-webhook)
    finalizeOrder(orderDraft, { simulated: false });
    initiatePayment(orderDraft);
    return;
  }

  showToast("❌ Le paiement mobile money n'est pas encore activé pour ce pays — choisissez \"Paiement à la livraison\" pour l'instant.");
  return;
  
  // Code de simulation Mobile Money (désactivé mais conservé)
  /*
  state.paymentPending = { order: orderDraft, attempts: 0, status: "pending" };
  state.view = "payment";
  save();
  render();
  showToast("Paiement " + (form.payment === "orange_money" ? "Orange Money" : "Moov Money") + " (simulation)…");
  window._paymentInterval = setInterval(function() {
    if (!state.paymentPending) { clearInterval(window._paymentInterval); return; }
    state.paymentPending.attempts += 1;
    if (state.paymentPending.attempts >= 2) {
      clearInterval(window._paymentInterval);
      state.paymentPending.status = "success";
      render();
      setTimeout(function() { finalizeOrder(state.paymentPending.order, { simulated: true }); }, 1400);
    } else { render(); }
  }, 4000);
  */
}

function cancelPayment() {
  clearInterval(window._paymentInterval);
  state.paymentPending = null;
  state.view = state.quickBuyItem ? "market" : "cart";
  state.quickBuyItem = null;
  save();
  render();
}

// Appelle la fonction Supabase dédiée au service réglé pour ce pays
// (voir Admin → Sécurité → Paiement mobile money), puis redirige
// l'acheteur vers le guichet de paiement. La commande existe déjà (créée
// juste avant, en "pending_payment") — c'est la confirmation reçue plus
// tard par la fonction "-webhook" correspondante qui la fera vraiment
// passer à "paid", jamais une simple redirection de retour.
function initiatePayment(order) {
  if (!FIREBASE_ENABLED) { showToast(t("toast_payment_unavailable_offline")); return; }
  var payCfg = getPaymentConfig(order.country);
  var functionsByAggregator = { cinetpay: "cinetpay-init", paydunya: "paydunya-init", flutterwave: "flutterwave-init" };
  var functionName = functionsByAggregator[payCfg.aggregator];
  if (payCfg.mode !== "aggregator" || !functionName) {
    showToast(t("toast_mobile_money_not_active_country"));
    return;
  }
  showToast(t("toast_redirecting_payment"));
  fetch(supabaseConfig.url + "/functions/v1/" + functionName, {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey },
    body: JSON.stringify({
      orderId: order.id,
      country: order.country,
      amount: order.total,
      currency: currencyForCountry(order.country),
      buyerName: order.buyerName,
      buyerPhone: order.buyerPhone
    })
  })
    .then(function(res) { return res.json(); })
    .then(function(data) {
      if (data.ok && data.paymentUrl) {
        window.location.href = data.paymentUrl;
      } else {
        showToast(t("toast_cannot_start_payment"));
      }
    })
    .catch(function() {
      showToast(t("toast_connection_failed_order_pending"));
    });
}

function finalizeOrder(order, opts) {
  pushDebugLog("info", "finalizeOrder() démarré", "orderId=" + order.id + " items=" + order.items.length + " view avant=" + state.view);
  var affectedProducts = [];
  for (var i = 0; i < order.items.length; i++) {
    var it = order.items[i];
    for (var j = 0; j < state.products.length; j++) {
      if (state.products[j].id === it.productId) {
        state.products[j].stock = Math.max(0, state.products[j].stock - it.qty);
        affectedProducts.push(state.products[j]);
        break;
      }
    }
  }
  state.orders.unshift(order);
  if (!state.quickBuyItem) state.cart = state.cart.filter(function(it) { return it.buyerId !== state.profile.id; });
  state.quickBuyItem = null;
  state.paymentPending = null;
  state.view = "orders";
  
  var awaitingPayment = !!(opts && opts.awaitingPayment);
  var paymentLabel = awaitingPayment ? "mobile money (en attente)" : (opts && opts.simulated) ? (order.payment === "orange_money" ? "Orange Money" : "Moov Money") + " (simulation)" : "à la livraison";
  addNotification("whatsapp", "Confirmation : commande #" + order.id.slice(-5).toUpperCase() + " (" + orderMoney(order.total, order) + ") enregistrée. Paiement : " + paymentLabel, order.buyerId, "orders");
  if (order.isDigital) {
    addNotification("sms", "📥 " + t("dig_notif_after_pay"), order.buyerId, "orders");
  } else if (order.isInternational) {
    addNotification("sms", "🌍 Votre commande groupée internationale est enregistrée — en attente de vérification du paiement par notre agent sourcing.", order.buyerId, "orders");
  } else if (order.deliveryMode === "relais") {
    addNotification("sms", "📦 Votre commande sera déposée chez " + order.relaisShopName + ".", order.buyerId, "orders");
    addNotification("sms", "🔑 Code de retrait (à donner en boutique quand vous récupérez votre colis) : " + order.codeRetrait + " — Ne le partagez pas avant d'être sur place !", order.buyerId, "orders");
  } else {
    addNotification("sms", "🔑 Code OTP : " + order.otp + " — Ne le partagez pas !", order.buyerId, "orders");
  }
  
  // Les champs financiers (taux, montants, parrain identifié) ne sont
  // plus calculés ici : order-write les calcule et les vérifie lui-même,
  // à partir du code de parrainage brut transmis ci-dessous — jamais
  // depuis un montant que ce téléphone aurait calculé.
  order.commissionRate = null;
  order.commissionMode = null;
  order.commissionTotal = null;
  order.affiliateId = null;
  order.affiliateAmount = null;
  order.affiliateCommissionCredited = false;
  order.platformCommissionAmount = null;
  
  var sellers = {};
  for (var k = 0; k < order.items.length; k++) {
    var sellerKey = order.items[k].sellerId || order.items[k].sellerName;
    if (!sellers[sellerKey]) sellers[sellerKey] = { name: order.items[k].sellerName, items: [] };
    sellers[sellerKey].items.push(order.items[k]);
  }
  // Paiement en ligne : les boutiques sont prévenues par le serveur, seulement une fois payé.
  var sellerKeys = awaitingPayment ? [] : Object.keys(sellers);
  for (var s = 0; s < sellerKeys.length; s++) {
    var sellerKey2 = sellerKeys[s];
    var itemsList = sellers[sellerKey2].items;
    var msg = "";
    for (var m = 0; m < itemsList.length; m++) {
      if (m > 0) msg += ", ";
      msg += itemsList[m].qty + "x " + itemsList[m].name;
    }
    addNotification("sms", "Nouvelle commande reçue par " + sellers[sellerKey2].name + " : " + msg, sellerKey2, "seller-orders");
    for (var sai = 0; sai < state.accounts.length; sai++) {
      if (state.accounts[sai].id === sellerKey2) {
        state.accounts[sai].hasNewSellerOrderAlert = true;
        if (state.profile && state.profile.id === sellerKey2) state.profile.hasNewSellerOrderAlert = true;
        saveDoc("accounts", state.accounts[sai]);
        break;
      }
    }
  }
  
  save();
  // Coordonnées GPS/repère/téléphones — envoyées à part, vers la collection
  // protégée dédiée, une fois la commande ENREGISTRÉE sur le serveur.
  var contactPayload = (order.buyerLat != null || order.buyerLng != null || order.repere || order.buyerPhone || order.contactPhone) ? {
    operation: "save_order_contact",
    orderId: order.id,
    buyerPhone: order.buyerPhone || null,
    contactPhone: order.contactPhone || null,
    repere: order.repere || null,
    buyerLat: order.buyerLat != null ? order.buyerLat : null,
    buyerLng: order.buyerLng != null ? order.buyerLng : null
  } : null;
  var orderSaved = (opts && opts.alreadyOnServer) ? Promise.resolve(true) : secureOrderSaveDoc(order, false, { isNew: true });
  window.__lastOrderSaved = orderSaved;
  if (awaitingPayment) {
    Promise.resolve(orderSaved).then(function(okSaved) {
      if (okSaved === "rejected") return;
      if (okSaved === false) { showToast(t("ligdi_saved_offline")); return; }
      startLigdicashPayment({ kind: "order", orderId: order.id });
    });
  }
  if (contactPayload) {
    Promise.resolve(orderSaved).then(function(okSaved) { if (okSaved === "rejected") return; saveOrderContactReliably(contactPayload, 0); });
  }
  // Le stock est désormais retiré par le serveur (order-write) : rien à envoyer ici.
  render();
  pushDebugLog("info", "finalizeOrder() terminé", "view après=" + state.view + " taille panier après=" + state.cart.length);
  // Une commande internationale n'a ni code de retrait ni code OTP (ces
  // deux-là supposent une livraison locale au Mali) — sans ce cas à part,
  // le message affichait "undefined" à la place d'un vrai code.
  if (order.isInternational) {
    showToast(t("dt_order_saved_international"));
  } else if (order.deliveryMode === "relais") {
    showToast(t("dt_order_saved_pickup_code") + order.codeRetrait);
  } else {
    showToast(t("dt_order_saved_otp") + order.otp);
  }
}

// Crédite le portefeuille de CHAQUE vendeur concerné par une commande
// livrée (elle peut mélanger plusieurs boutiques), selon sa part réelle
// après la commission — appelée depuis les trois chemins qui peuvent
// marquer une commande "Livrée" (statut manuel, code OTP, retrait en
// point de retrait), pour ne jamais en oublier un.
// Règle le paiement des vendeurs ET du parrain éventuel sur une commande
// livrée — désormais calculé et vérifié ENTIÈREMENT côté serveur (voir
// wallet-write, opération "settle_order_payouts") : ce téléphone ne fait
// que déclencher la vérification, il ne calcule et n'envoie plus aucun
// montant lui-même.
// Versements d'une commande livrée (vendeurs + parrain), faits par le
// serveur. Le serveur refuse tant qu'il ne voit pas la commande "Livrée" —
// or le statut est enregistré juste APRÈS cette demande : on attend donc un
// peu, et on réessaie plusieurs fois au lieu d'abandonner au premier refus
// (avant : versements jamais faits, vendeurs et parrains non crédités).
// Sans risque de double paiement : le serveur ne verse jamais deux fois.
var SETTLE_RETRY_DELAYS = [2000, 5000, 12000, 30000];
function settleOrderPayouts(order, attempt) {
  attempt = attempt || 0;
  var orderId = order && order.id;
  if (!orderId) return Promise.resolve(false);
  return new Promise(function(resolve) {
    setTimeout(function() {
      callWalletOperation({ operation: "settle_order_payouts", orderId: orderId }).then(function(res) {
        if (res && res.success) {
          fetchMyWalletState();
          // Recharge les commandes : leur état "réglée" vient du serveur.
          clearTimeout(window._settleResyncTimer);
          window._settleResyncTimer = setTimeout(function() { try { syncPersonalCollections(); } catch (e) {} }, 800);
          resolve(true); return;
        }
        var err = res && res.error;
        if (attempt + 1 < SETTLE_RETRY_DELAYS.length && (!err || err === "order_not_delivered" || /network|fetch|timeout/i.test(String(err)))) {
          settleOrderPayouts(order, attempt + 1).then(resolve);
          return;
        }
        try { pushDebugLog("error", "Versement de la commande non effectué", orderId + " — " + err); } catch (e) {}
        resolve(false);
      });
    }, SETTLE_RETRY_DELAYS[attempt]);
  });
}

// Commandes livrées dont un versement (vendeur ou parrain) n'a jamais été
// fait — pour le rattrapage depuis l'Admin.
function unsettledDeliveredOrders() {
  return (state.orders || []).filter(function(o) {
    if (!o || o.status !== "Livrée") return false;
    var paid = o.sellerPayoutSettled || {};
    // Un compte supprimé (vieilles commandes de test) : personne à payer.
    var exists = function(id) { return (state.accounts || []).some(function(a) { return a && a.id === id; }); };
    var sellerIds = Array.isArray(o.sellerIds) && o.sellerIds.length ? o.sellerIds : (o.items || []).map(function(it) { return it.sellerId; }).filter(Boolean);
    var sellerMissing = sellerIds.some(function(id) { return !paid[id] && exists(id); });
    var affiliateMissing = !!o.affiliateId && !o.affiliateCommissionCredited && !o.isInternational && o.affiliateId !== o.buyerId && exists(o.affiliateId);
    return sellerMissing || affiliateMissing;
  }).sort(function(a, b) { return (b.deliveredAt || b.createdAt || 0) - (a.deliveredAt || a.createdAt || 0); });
}
function runPayoutCatchUp() {
  if (state.payoutCatchUp && state.payoutCatchUp.running) return;
  var todo = unsettledDeliveredOrders();
  state.payoutCatchUp = { running: true, done: 0, ok: 0, total: todo.length, msg: "" };
  render();
  var i = 0;
  (function next() {
    if (i >= todo.length) {
      state.payoutCatchUp.running = false;
      state.payoutCatchUp.msg = "Terminé : " + state.payoutCatchUp.ok + " commande(s) avec versement effectué sur " + todo.length + ". Le détail s'affiche à côté de chaque commande.";
      syncPersonalCollections();
      render(); return;
    }
    var o = todo[i++];
    // Pas d'attente ici : ces commandes sont livrées depuis longtemps.
    callWalletOperation({ operation: "settle_order_payouts", orderId: o.id }).then(function(res) {
      state.payoutCatchUp.done++;
      state.payoutResults = state.payoutResults || {};
      var paidParts = res && res.settled ? Object.keys(res.settled).length : 0;
      var reasons = res && res.skipped ? Object.keys(res.skipped).map(function(k) { return res.skipped[k]; }) : [];
      if (res && res.success && paidParts) state.payoutCatchUp.ok++;
      state.payoutResults[o.id] = !res || !res.success ? ("refusé : " + ((res && res.error) || "erreur")) : (paidParts ? "✅ versé" : (reasons.length ? reasons.join(", ") : "rien à verser"));
      render();
      setTimeout(next, 400);
    });
  })();
}

function setOrderStatus(orderId, status) {
  var order = null;
  for (var i = 0; i < state.orders.length; i++) {
    if (state.orders[i].id === orderId) {
      order = state.orders[i];
      break;
    }
  }
  if (!order) return;
  if (order.deliveryMode === "relais" && (status === "Livrée" || status === "En boutique")) {
    showToast(t("toast_needs_shop_code"));
    return;
  }
  // Livraison express avec code OTP : "Livrée" ne peut jamais être cliqué
  // directement — seule la saisie du bon code (verifyDeliveryOTP) peut
  // faire passer la commande à ce statut. Avant, ce bouton contournait
  // complètement la vérification.
  if (status === "Livrée" && order.otp) {
    showToast(t("toast_needs_otp"));
    return;
  }
  logOrderStatusChange(order, status);
  if (status === "Livrée") {
    order.deliveredAt = Date.now();
    addNotification("whatsapp", "✅ Commande #" + orderId.slice(-5).toUpperCase() + " livrée !", order.buyerId, "orders");
    settleOrderPayouts(order);
  }
  if (state.profile.role === "livreur" && !order.livreurId) {
    order.livreurId = state.profile.id;
    order.livreurName = state.profile.name;
    order.livreurPhone = state.profile.phone;
    // Coordonnées du client (numéro, GPS, repère) récupérées tout de suite —
    // en réessayant le temps que le serveur enregistre l'attribution.
    [2500, 6000, 12000].forEach(function(delay) {
      setTimeout(function() {
        var o = (state.orders || []).find(function(x) { return x.id === orderId; });
        if (o && !(o.buyerPhone || o.contactPhone)) { try { fetchMyOrderContacts().then(function() { renderOrDefer(); }); fetchMyOrderDetails([orderId]); } catch (e) {} }
      }, delay);
    });
  }
  if (status === "Prête") {
    var readyMsg = "📦 Commande #" + orderId.slice(-5).toUpperCase() + " prête à être récupérée chez " + (order.items[0] ? order.items[0].sellerName : "le vendeur") + ".";
    for (var lvi = 0; lvi < state.accounts.length; lvi++) {
      if (state.accounts[lvi].livreurApplicationStatus === "approved") {
        addNotification("whatsapp", readyMsg, state.accounts[lvi].id, "livreur");
      }
    }
    // Le rond rouge "nouvelle commande" doit disparaître dès que le vendeur
    // agit sur sa commande (la marque prête), pas seulement s'il rouvre
    // l'onglet — sinon il peut rester coincé indéfiniment.
    if (state.profile && state.profile.hasNewSellerOrderAlert) {
      state.profile.hasNewSellerOrderAlert = false;
      for (var ssoi = 0; ssoi < state.accounts.length; ssoi++) {
        if (state.accounts[ssoi].id === state.profile.id) { state.accounts[ssoi].hasNewSellerOrderAlert = false; saveDoc("accounts", state.accounts[ssoi]); break; }
      }
    }
  }
  var labels = { Prête: "est prête", Récupérée: "a été récupérée", "En route": "est en route", Livrée: "a été livrée" };
  addNotification("whatsapp", "Commande #" + orderId.slice(-5).toUpperCase() + " " + (labels[status] || "a changé de statut : " + status), order.buyerId, "orders");
  for (var bai = 0; bai < state.accounts.length; bai++) {
    if (state.accounts[bai].id === order.buyerId) {
      state.accounts[bai].hasNewBuyerStatusAlert = true;
      if (state.profile && state.profile.id === order.buyerId) state.profile.hasNewBuyerStatusAlert = true;
      saveDoc("accounts", state.accounts[bai]);
      break;
    }
  }
  save();
  secureOrderSaveDoc(order);
  render();
}

// ---------- CONFIRMATION / REFUS PAR VENDEUR (commande multi-boutiques) ----------
// Une commande avec plusieurs vendeurs reste UNE seule fiche, mais chaque
// boutique concernée avance indépendamment via order.vendorStatuses —
// jamais le statut global (order.status, celui que voit le livreur) tant
// que toutes les boutiques encore actives n'ont pas confirmé la leur.

// Vrai si toutes les boutiques encore actives (ni déjà refusées) d'une
// commande ont confirmé leur part — c'est ce moment précis qui doit faire
// basculer la commande globale sur "Prête" pour le livreur.
function allActiveVendorsReady(order) {
  var sellerIds = Object.keys(order.vendorStatuses || {});
  for (var i = 0; i < sellerIds.length; i++) {
    var st = order.vendorStatuses[sellerIds[i]];
    if (st === "Refusée") continue;
    if (st !== "Prête") return false;
  }
  return true;
}

function sellerConfirmReady(orderId) {
  var order = null;
  for (var i = 0; i < state.orders.length; i++) { if (state.orders[i].id === orderId) { order = state.orders[i]; break; } }
  if (!order || !state.profile) return;
  // Même protection que sellerRefuseItems : une commande déjà annulée,
  // livrée, non livrable ou refusée au retrait ne doit plus jamais
  // pouvoir être "confirmée" après coup — sinon le statut se remet à
  // bouger sur une commande déjà terminée, et le message envoyé à
  // l'acheteur ("en attente des autres boutiques") n'a plus de sens,
  // même pour une commande à une seule boutique.
  var terminalStatusesReady = ["Livrée", "Annulée", "Non livrable", "Refusée au retrait"];
  if (terminalStatusesReady.indexOf(order.status) !== -1) {
    showToast(t("toast_order_cannot_be_modified"));
    return;
  }
  var myId = state.profile.id;
  if (!order.vendorStatuses) order.vendorStatuses = {};
  order.vendorStatuses[myId] = "Prête";

  // Le rond rouge "nouvelle commande" doit disparaître dès que CE vendeur
  // agit sur sa part, pas seulement s'il rouvre l'onglet.
  if (state.profile.hasNewSellerOrderAlert) {
    state.profile.hasNewSellerOrderAlert = false;
    for (var ssoi = 0; ssoi < state.accounts.length; ssoi++) {
      if (state.accounts[ssoi].id === myId) { state.accounts[ssoi].hasNewSellerOrderAlert = false; saveDoc("accounts", state.accounts[ssoi]); break; }
    }
  }

  if (allActiveVendorsReady(order) && order.status === "Nouvelle") {
    // Toutes les boutiques encore actives ont confirmé — la commande
    // devient enfin visible pour un livreur, exactement comme avant pour
    // une commande à un seul vendeur.
    logOrderStatusChange(order, "Prête");
    var readyMsg = "📦 Commande #" + orderId.slice(-5).toUpperCase() + " prête à être récupérée.";
    for (var lvi = 0; lvi < state.accounts.length; lvi++) {
      if (state.accounts[lvi].livreurApplicationStatus === "approved") {
        addNotification("whatsapp", readyMsg, state.accounts[lvi].id, "livreur");
      }
    }
    addNotification("whatsapp", "Commande #" + orderId.slice(-5).toUpperCase() + " est prête", order.buyerId, "orders");
    for (var bai = 0; bai < state.accounts.length; bai++) {
      if (state.accounts[bai].id === order.buyerId) {
        state.accounts[bai].hasNewBuyerStatusAlert = true;
        if (state.profile.id === order.buyerId) state.profile.hasNewBuyerStatusAlert = true;
        saveDoc("accounts", state.accounts[bai]);
        break;
      }
    }
  } else {
    // Encore d'autres boutiques à attendre — on informe juste l'acheteur
    // que CETTE boutique-là a confirmé sa part, sans faire croire que
    // toute la commande est prête.
    var myShopName = null;
    for (var mi = 0; mi < order.items.length; mi++) { if (order.items[mi].sellerId === myId) { myShopName = order.items[mi].sellerName; break; } }
    addNotification("whatsapp", "✅ " + esc(myShopName || "Une boutique") + " a préparé sa part de la commande #" + orderId.slice(-5).toUpperCase() + " — en attente des autres boutiques.", order.buyerId, "orders");
  }
  save();
  secureOrderSaveDoc(order);
  render();
}

// sellerIdForAdmin : l'administration retire la part d'UNE boutique précise
// (boutique injoignable ou qui ne peut pas fournir), sans annuler les autres.
function sellerRefuseItems(orderId, reason, sellerIdForAdmin) {
  var order = null;
  for (var i = 0; i < state.orders.length; i++) { if (state.orders[i].id === orderId) { order = state.orders[i]; break; } }
  if (!order || (!state.profile && !sellerIdForAdmin)) return;
  var myId = sellerIdForAdmin || state.profile.id;
  var byAdmin = !!sellerIdForAdmin;
  var terminalStatuses = ["Livrée", "Annulée", "Non livrable", "Refusée au retrait"];
  if (terminalStatuses.indexOf(order.status) !== -1) {
    showToast(t("toast_order_cannot_be_modified"));
    return;
  }
  if (!reason || !reason.trim()) {
    showToast(t("toast_explain_why_not_deliverable"));
    return;
  }
  reason = reason.trim();
  if (!order.vendorStatuses) order.vendorStatuses = {};
  order.vendorStatuses[myId] = "Refusée";

  var myShopName = null;
  var myItemNames = [];
  for (var j = 0; j < order.items.length; j++) {
    if (order.items[j].sellerId === myId) {
      order.items[j].refused = true;
      myShopName = order.items[j].sellerName;
      myItemNames.push(order.items[j].name);
      // Stock restauré, comme pour une annulation — mais seulement pour
      // les articles de CE vendeur, jamais ceux des autres boutiques.
      for (var k = 0; k < state.products.length; k++) {
        if (state.products[k].id === order.items[j].productId) {
          state.products[k].stock += order.items[j].qty;
          if (!order.stockReserved) saveDoc("products", state.products[k]); // sinon le serveur remet le stock lui-même
          break;
        }
      }
    }
  }

  var sellerIds = Object.keys(order.vendorStatuses);
  var allRefused = sellerIds.every(function(sid) { return order.vendorStatuses[sid] === "Refusée"; });

  if (allRefused) {
    // Plus aucune boutique active — la commande entière est annulée, pas
    // seulement "non livrable" (rien à livrer du tout).
    logOrderStatusChange(order, "Annulée", "Toutes les boutiques ont refusé leur part.");
    order.deliveryFee = 0;
    order.subtotal = 0;
    order.total = 0;
    addNotification("whatsapp", "❌ Commande #" + orderId.slice(-5).toUpperCase() + " annulée — aucune boutique n'a pu fournir les articles commandés.", order.buyerId, "orders");
  } else {
    // Recalcule le sous-total et les frais de livraison uniquement à
    // partir de ce qui reste réellement à livrer — l'acheteur ne doit
    // jamais payer pour un article qu'il ne recevra pas.
    var remainingItems = order.items.filter(function(it) { return !it.refused; });
    var newSubtotal = 0;
    for (var ri = 0; ri < remainingItems.length; ri++) { newSubtotal += remainingItems[ri].price * remainingItems[ri].qty; }
    var newFees = computeDeliveryFeesFromItems(remainingItems, order.buyerLat, order.buyerLng, order.city, order.expressCommune || null, order.expressQuartier || null, order.zone);
    var newDeliveryFee = order.deliveryMode === "relais" ? newFees.relaisFee : newFees.expressFee;
    order.subtotal = newSubtotal;
    order.deliveryFee = newDeliveryFee;
    order.total = newSubtotal + newDeliveryFee;

    addNotification("whatsapp", "⚠️ " + esc(myShopName || "Une boutique") + " ne peut pas fournir : " + esc(myItemNames.join(", ")) + ". Motif : \"" + esc(reason) + "\". Nouveau total de votre commande #" + orderId.slice(-5).toUpperCase() + " : " + orderMoney(order.total, order) + ".", order.buyerId, "orders");

    // Trace dans l'historique de la commande, sans changer order.status
    // (logOrderStatusChange l'écraserait) — sinon ce refus partiel restait
    // invisible dans "Historique complet", comme s'il ne s'était rien passé.
    if (!Array.isArray(order.statusHistory)) order.statusHistory = [];
    order.statusHistory.push({ status: order.status, at: Date.now(), note: (myShopName || "Une boutique") + " a refusé sa part : " + reason });

    // Si ce refus était le dernier blocage — toutes les boutiques encore
    // actives avaient déjà confirmé — la commande peut passer "Prête"
    // tout de suite, sans attendre une action supplémentaire de personne.
    if (allActiveVendorsReady(order) && order.status === "Nouvelle") {
      logOrderStatusChange(order, "Prête");
      var readyMsg2 = "📦 Commande #" + orderId.slice(-5).toUpperCase() + " prête à être récupérée.";
      for (var lvi2 = 0; lvi2 < state.accounts.length; lvi2++) {
        if (state.accounts[lvi2].livreurApplicationStatus === "approved") {
          addNotification("whatsapp", readyMsg2, state.accounts[lvi2].id, "livreur");
        }
      }
    }
  }

  for (var bai2 = 0; bai2 < state.accounts.length; bai2++) {
    if (state.accounts[bai2].id === order.buyerId) {
      state.accounts[bai2].hasNewBuyerStatusAlert = true;
      if (state.profile && state.profile.id === order.buyerId) state.profile.hasNewBuyerStatusAlert = true;
      saveDoc("accounts", state.accounts[bai2]);
      break;
    }
  }
  save();
  secureOrderSaveDoc(order, byAdmin);
  if (!byAdmin) createDispute(orderId, "produit_endommage", "Le vendeur " + (myShopName || "") + " a signalé que sa part de la commande ne peut pas être livrée : " + reason, true);
  state.showNonLivrableModal = false;
  state.nonLivrableOrderId = null;
  state.nonLivrableReason = "";
  render();
  showToast(allRefused ? "Commande annulée — le client a été prévenu." : "Votre part a été retirée de la commande — le client a été prévenu.");
}

// Audit 29/10/2026 (faille CMD-2) : les codes (OTP, code de dépôt, code de
// retrait) ne sont plus vérifiés sur ce téléphone — seul le serveur les
// connaît encore (les autres ne voient que « •••• »). On envoie le code saisi
// avec le nouveau statut ; le serveur accepte ou refuse.
function findOrderById(orderId) {
  for (var i = 0; i < state.orders.length; i++) { if (state.orders[i].id === orderId) return state.orders[i]; }
  return null;
}
function submitOrderCode(order, newStatus, code) {
  var draft = JSON.parse(JSON.stringify(order));
  logOrderStatusChange(draft, newStatus);
  if (newStatus === "Livrée") draft.deliveredAt = Date.now();
  if (newStatus === "En boutique") draft.depotConfirmedAt = Date.now();
  return orderWriteRequest(draft, { deliveryCode: String(code || "").trim() }).then(function(res) {
    if (res && res.success && res.status === newStatus) {
      order.status = draft.status;
      order.statusHistory = draft.statusHistory;
      if (draft.deliveredAt && newStatus === "Livrée") order.deliveredAt = draft.deliveredAt;
      if (newStatus === "En boutique") order.depotConfirmedAt = draft.depotConfirmedAt;
      if (newStatus === "Livrée") order.deliveryVerified = true;
      save();
      render();
      return "ok";
    }
    if (res && res.error === "too_many_attempts") return "locked";
    if (res && (res.error === "bad_code" || res.error === "not_allowed")) return "bad";
    if (res && res.success) return "bad";
    return "network";
  });
}
function codeErrorToast(result, badKey) {
  if (result === "locked") showToast("⛔ Trop de codes faux. Réessayez dans 1 heure.");
  else if (result === "network") showToast("❌ Pas de connexion au serveur. Réessayez.");
  else showToast(t(badKey));
}
function verifyDeliveryOTP(orderId, inputOTP) {
  var order = findOrderById(orderId);
  if (!order) return false;
  submitOrderCode(order, "Livrée", inputOTP).then(function(r) {
    if (r !== "ok") { codeErrorToast(r, "toast_incorrect_otp"); return; }
    settleOrderPayouts(order);
    showToast(t("toast_delivery_confirmed"));
  });
  return true;
}

// Le livreur vient de déposer le colis en boutique : la boutique saisit le
// Code Dépôt (montré par le livreur) pour confirmer la bonne réception du colis.
function confirmRelaisDepot(orderId, inputCode) {
  var order = findOrderById(orderId);
  if (!order) return false;
  if (order.status !== "En route") {
    showToast(t("toast_parcel_not_awaiting_depot1"));
    return false;
  }
  submitOrderCode(order, "En boutique", inputCode).then(function(r) {
    if (r !== "ok") { codeErrorToast(r, "toast_incorrect_deposit_code"); return; }
    addNotification("whatsapp", "📦 Votre commande #" + orderId.slice(-5).toUpperCase() + " est arrivée chez " + order.relaisShopName + " — vous pouvez venir la récupérer.", order.buyerId, "orders");
    showToast(t("toast_deposit_confirmed_awaiting"));
  });
  return true;
}

// Le client vient récupérer son colis : la boutique saisit le Code Retrait,
// ce qui confirme à la fois la remise du colis ET l'encaissement du paiement.
function confirmRelaisRetrait(orderId, inputCode) {
  var order = findOrderById(orderId);
  if (!order) return false;
  if (order.status !== "En boutique") {
    showToast(t("toast_parcel_not_ready_pickup"));
    return false;
  }
  submitOrderCode(order, "Livrée", inputCode).then(function(r) {
    if (r !== "ok") { codeErrorToast(r, "toast_incorrect_pickup_code"); return; }
    settleOrderPayouts(order);
    showToast(t("dt_parcel_delivered_paid") + orderMoney(order.total, order) + t("dt_close_paren_excl"));
  });
  return true;
}

// ---------- COLIS EXTERNES (plateformes internationales) ----------
// Un colis externe est enregistré par un Point de Retrait quand il reçoit un
// colis venant d'un partenaire (Alibaba, Amazon, etc.) — indépendant du
// système de commandes Sounsouni puisqu'il n'y a ni vendeur ni panier ici.
// Construit le lien public (sans compte) vers la fiche du Point de Retrait —
// utilisable dans un SMS pour que le destinataire sache où aller, même
// sans avoir de compte Sounsouni.
function buildRelaisPublicLink(relaisShopId) {
  return PUBLIC_SITE_URL + "/#relais=" + relaisShopId;
}

function registerExternalParcel(draft) {
  if (!draft.trackingNumber || !draft.trackingNumber.trim()) { showToast(t("toast_tracking_required")); return null; }
  if (!draft.recipientName || !draft.recipientName.trim()) { showToast(t("toast_recipient_name_required")); return null; }
  var phoneDigits = (draft.recipientPhone || "").replace(/\D/g, "");
  if (!phoneDigits) { showToast(t("toast_recipient_phone_required")); return null; }
  if (!draft.relaisShopId) { showToast(t("toast_choose_destination_pickup")); return null; }
  var relaisAcc = null;
  for (var ri = 0; ri < state.accounts.length; ri++) {
    if (state.accounts[ri].id === draft.relaisShopId) { relaisAcc = state.accounts[ri]; break; }
  }
  if (!relaisAcc) { showToast(t("toast_pickup_not_found")); return null; }
  var parcel = {
    id: uid(),
    trackingNumber: draft.trackingNumber.trim(),
    platform: draft.platform || "Autre",
    recipientName: draft.recipientName.trim(),
    recipientPhone: phoneDigits,
    weight: draft.weight || null,
    description: draft.description || "",
    relaisShopId: relaisAcc.id,
    relaisShopName: relaisAcc.shopName || relaisAcc.name,
    livreurId: null,
    livreurName: null,
    status: "Créé",
    statusHistory: [{ status: "Créé", at: Date.now(), note: null }],
    codeDepot: generateOTP(),
    codeRetrait: generateOTP(),
    createdAt: Date.now(),
    createdByAccountId: state.profile ? state.profile.id : null,
    createdByName: state.profile ? state.profile.name : null,
    retrievedAt: null,
    lastRecipientMessage: null
  };
  state.externalParcels.push(parcel);
  save();
  saveDoc("externalParcels", parcel);
  notifyExternalWebhook(parcel, "parcel_received");
  return parcel;
}

// Change le statut d'un colis externe en gardant l'historique horodaté —
// même principe que logOrderStatusChange, et déclenche le webhook
// partenaire s'il est activé.
function setExternalParcelStatus(parcelId, newStatus, note) {
  var parcel = null;
  for (var i = 0; i < state.externalParcels.length; i++) {
    if (state.externalParcels[i].id === parcelId) { parcel = state.externalParcels[i]; break; }
  }
  if (!parcel) return;
  parcel.status = newStatus;
  if (!Array.isArray(parcel.statusHistory)) parcel.statusHistory = [];
  parcel.statusHistory.push({ status: newStatus, at: Date.now(), note: note || null });
  if (newStatus === "Retiré") parcel.retrievedAt = Date.now();
  if (newStatus === "Disponible pour retrait") {
    parcel.lastRecipientMessage = "Bonjour " + parcel.recipientName + ", votre colis (" + parcel.trackingNumber + ") est disponible pour retrait chez " + parcel.relaisShopName + ". Localisation : " + buildRelaisPublicLink(parcel.relaisShopId) + " — Code de retrait : " + parcel.codeRetrait;
  }
  save();
  saveDoc("externalParcels", parcel);
  notifyExternalWebhook(parcel, "status_changed");
}

// Un livreur (n'importe lequel, approuvé) prend en charge un colis externe
// "Créé" pour l'apporter physiquement au Point de Retrait visé — même
// principe d'auto-attribution que pour les commandes classiques.
function acceptExternalParcelDelivery(parcelId) {
  var parcel = null;
  for (var i = 0; i < state.externalParcels.length; i++) {
    if (state.externalParcels[i].id === parcelId) { parcel = state.externalParcels[i]; break; }
  }
  if (!parcel || parcel.status !== "Créé") { showToast(t("toast_parcel_unavailable")); return false; }
  parcel.livreurId = state.profile.id;
  parcel.livreurName = state.profile.name;
  setExternalParcelStatus(parcelId, "Pris en charge par le livreur");
  showToast(t("dt_parcel_taken_code") + parcel.codeDepot);
  render();
  return true;
}

// Le Point de Retrait confirme le code donné par le livreur — c'est SEULEMENT
// à cette étape que le colis est vraiment chez lui, et que le
// destinataire est prévenu pour la première fois (message + lien public).
function confirmExternalParcelDepot(parcelId, inputCode) {
  var parcel = null;
  for (var i = 0; i < state.externalParcels.length; i++) {
    if (state.externalParcels[i].id === parcelId) { parcel = state.externalParcels[i]; break; }
  }
  if (!parcel) return false;
  if (parcel.status !== "Pris en charge par le livreur") { showToast(t("toast_parcel_not_awaiting_depot2")); return false; }
  if (parcel.codeDepot === inputCode) {
    setExternalParcelStatus(parcelId, "Reçu au point de retrait");
    parcel.lastRecipientMessage = "Bonjour " + parcel.recipientName + ", votre colis (" + parcel.trackingNumber + ") est arrivé chez " + parcel.relaisShopName + ". Localisation : " + buildRelaisPublicLink(parcel.relaisShopId) + " — Code de retrait (à présenter sur place) : " + parcel.codeRetrait;
    save();
    saveDoc("externalParcels", parcel);
    showToast(t("toast_deposit_confirmed"));
    render();
    return true;
  }
  showToast(t("toast_incorrect_deposit_code"));
  return false;
}

function confirmExternalParcelRetrieval(parcelId, inputCode) {
  var parcel = null;
  for (var i = 0; i < state.externalParcels.length; i++) {
    if (state.externalParcels[i].id === parcelId) { parcel = state.externalParcels[i]; break; }
  }
  if (!parcel) return false;
  if (parcel.codeRetrait === inputCode) {
    setExternalParcelStatus(parcelId, "Retiré");
    showToast(t("toast_parcel_delivered"));
    render();
    return true;
  }
  showToast(t("toast_incorrect_pickup_code"));
  return false;
}

// ---------- DEMANDES DE MODIFICATION/SUPPRESSION (Groupe 2) ----------
// Un employé peut créer un colis externe directement, mais toute
// modification ou suppression d'un colis existant doit d'abord être
// approuvée par le Groupe 1 — même principe que les demandes de
// modification Point de Retrait déjà en place.
function requestExternalParcelChange(parcelId, type, changes) {
  var req = {
    id: uid(),
    parcelId: parcelId,
    type: type, // "edit" | "delete"
    changes: changes || null,
    requestedByAccountId: state.profile.id,
    requestedByName: state.profile.name,
    status: "pending",
    createdAt: Date.now()
  };
  state.externalParcelChangeRequests.push(req);
  save();
  saveDoc("externalParcelChangeRequests", req);
  showToast(t("toast_request_sent_main_admin"));
  return req;
}

function approveExternalParcelChangeRequest(reqId) {
  var req = null;
  for (var i = 0; i < state.externalParcelChangeRequests.length; i++) {
    if (state.externalParcelChangeRequests[i].id === reqId) { req = state.externalParcelChangeRequests[i]; break; }
  }
  if (!req) return;
  var parcel = null;
  for (var j = 0; j < state.externalParcels.length; j++) {
    if (state.externalParcels[j].id === req.parcelId) { parcel = state.externalParcels[j]; break; }
  }
  if (parcel) {
    if (req.type === "delete") {
      state.externalParcels = state.externalParcels.filter(function(p) { return p.id !== req.parcelId; });
      deleteRemoteDoc("externalParcels", req.parcelId);
    } else if (req.type === "edit" && req.changes) {
      Object.assign(parcel, req.changes);
      saveDoc("externalParcels", parcel);
    }
  }
  req.status = "approved";
  save();
  saveDoc("externalParcelChangeRequests", req);
  showToast(t("toast_request_approved"));
  render();
}

function rejectExternalParcelChangeRequest(reqId) {
  var req = null;
  for (var i = 0; i < state.externalParcelChangeRequests.length; i++) {
    if (state.externalParcelChangeRequests[i].id === reqId) { req = state.externalParcelChangeRequests[i]; break; }
  }
  if (!req) return;
  req.status = "rejected";
  save();
  saveDoc("externalParcelChangeRequests", req);
  showToast(t("toast_request_rejected"));
  render();
}

// Le client, sur place, refuse le produit après vérification : il repart
// avec le prochain passage du livreur vers le vendeur. Aucune commission
// (ni boutique, ni GEMS) puisque la vente n'a pas abouti. Un litige est
// ouvert automatiquement — ce refus EST quasiment un signalement.
// Le livreur refuse de récupérer le produit chez le vendeur (ne correspond
// pas à l'annonce). Commande annulée directement — rien n'a encore été
// payé (paiement à la réception), donc pas de complication financière.
// Suit aussi le nombre de refus par vendeur pour alerter l'admin en cas
// de récidive (2 refus ou plus).
// Le livreur refuse de récupérer le produit chez UN vendeur précis (ne
// correspond pas à l'annonce) — seule la part de CE vendeur est retirée de
// la commande, jamais celle des autres boutiques qui peuvent être
// parfaitement conformes. Même logique que sellerRefuseItems côté
// vendeur : stock restauré, sous-total et livraison recalculés sur ce qui
// reste réellement à livrer, commande entière annulée seulement si plus
// aucune boutique active ne reste. Suit aussi le nombre de refus par
// vendeur pour alerter l'admin en cas de récidive (2 refus ou plus).
function livreurRefuseVendorItems(orderId, sellerId, reason) {
  var order = null;
  for (var i = 0; i < state.orders.length; i++) {
    if (state.orders[i].id === orderId) { order = state.orders[i]; break; }
  }
  if (!order) return false;
  reason = (reason || "").trim() || "Le produit récupéré ne correspondait pas à l'annonce.";
  if (!order.vendorStatuses) order.vendorStatuses = {};
  order.vendorStatuses[sellerId] = "Refusée";

  var shopName = null;
  var refusedNames = [];
  for (var j = 0; j < order.items.length; j++) {
    var it = order.items[j];
    if (it.sellerId !== sellerId) continue;
    it.refused = true;
    shopName = it.sellerName;
    refusedNames.push(it.name);
    for (var k = 0; k < state.products.length; k++) {
      if (state.products[k].id === it.productId) {
        state.products[k].stock += it.qty;
        if (!order.stockReserved) saveDoc("products", state.products[k]); // sinon le serveur remet le stock lui-même
        break;
      }
    }
  }

  var sellerIdsInOrder = Object.keys(order.vendorStatuses);
  var allRefused = sellerIdsInOrder.every(function(sid) { return order.vendorStatuses[sid] === "Refusée"; });

  if (allRefused) {
    logOrderStatusChange(order, "Annulée", "refus_livreur : " + reason);
    order.cancelReason = "refus_livreur";
    order.cancelledAt = Date.now();
    order.refusalReason = reason;
    order.deliveryFee = 0;
    order.subtotal = 0;
    order.total = 0;
    addNotification("whatsapp", "❌ Commande #" + orderId.slice(-5).toUpperCase() + " annulée par notre livreur. Motif : " + reason, order.buyerId, "orders");
    showToast(t("toast_order_cancelled_livreur_refusal"));
  } else {
    var remainingItems = order.items.filter(function(it2) { return !it2.refused; });
    var newSubtotal = 0;
    for (var ri = 0; ri < remainingItems.length; ri++) { newSubtotal += remainingItems[ri].price * remainingItems[ri].qty; }
    var newFees = computeDeliveryFeesFromItems(remainingItems, order.buyerLat, order.buyerLng, order.city, order.expressCommune || null, order.expressQuartier || null, order.zone);
    var newDeliveryFee = order.deliveryMode === "relais" ? newFees.relaisFee : newFees.expressFee;
    order.subtotal = newSubtotal;
    order.deliveryFee = newDeliveryFee;
    order.total = newSubtotal + newDeliveryFee;
    addNotification("whatsapp", "⚠️ Notre livreur a refusé l'article de " + (shopName || "une boutique") + " (" + refusedNames.join(", ") + ") : " + reason + ". Nouveau total de votre commande #" + orderId.slice(-5).toUpperCase() + " : " + orderMoney(order.total, order) + ". Le reste de votre commande continue normalement.", order.buyerId, "orders");
    showToast(t("toast_item_refused"));

    // Trace dans l'historique de la commande, sans changer order.status —
    // même souci que côté vendeur : sans ça, ce refus restait invisible
    // dans "Historique complet".
    if (!Array.isArray(order.statusHistory)) order.statusHistory = [];
    order.statusHistory.push({ status: order.status, at: Date.now(), note: "Livreur : refusé chez " + (shopName || "une boutique") + " — " + reason });
  }

  for (var rbai = 0; rbai < state.accounts.length; rbai++) {
    if (state.accounts[rbai].id === order.buyerId) {
      state.accounts[rbai].hasNewBuyerStatusAlert = true;
      if (state.profile && state.profile.id === order.buyerId) state.profile.hasNewBuyerStatusAlert = true;
      saveDoc("accounts", state.accounts[rbai]);
      break;
    }
  }

  addNotification("whatsapp", "⚠️ Commande #" + orderId.slice(-5).toUpperCase() + " — votre article a été refusé par notre livreur. Motif : " + reason, sellerId, "seller-orders");
  trackSellerRefusal(sellerId);
  createDispute(orderId, "refus_livreur", "Le livreur a refusé de récupérer le produit chez " + (shopName || "un vendeur") + ". Motif donné par le livreur : " + reason, true);

  save();
  secureOrderSaveDoc(order);
  render();
  return true;
}

// Comptabilise les refus de récupération par vendeur. À partir de 2, un
// signal reste affiché sur le compte jusqu'à ce que l'admin l'examine.
function trackSellerRefusal(sellerId) {
  var account = null;
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === sellerId) { account = state.accounts[i]; break; }
  }
  if (!account) return;
  account.livreurRefusalCount = (account.livreurRefusalCount || 0) + 1;
  if (account.livreurRefusalCount >= 2) {
    account.hasRefusalAlert = true;
  }
  save();
  saveDoc("accounts", account);
}


// Regroupe ce qui est commun entre un refus explicite du client au retrait
// (voir refuseRelaisProduct juste en dessous) et un colis jamais venu
// chercher après le délai automatique (voir checkStalePickupOrders) :
// dans les deux cas, retour au vendeur, aucune commission pour personne.
function markOrderReturnedUnclaimed(order, disputeReason, disputeNote, sellerMessage) {
  logOrderStatusChange(order, "Refusée au retrait");
  order.returnStatus = "en_attente_retour";
  // Code de reprise : le livreur le donne au point de retrait pour prouver
  // que le colis a bien quitté la boutique (retour vers le vendeur).
  if (!order.returnPickupCode) order.returnPickupCode = generateOTP();
  order.refusedAt = Date.now();
  order.commissionAmount = 0; // aucune commission, ni boutique ni Sounsouni
  save();
  secureOrderSaveDoc(order);
  createDispute(order.id, disputeReason, disputeNote, true);
  var notifiedSellers = {};
  for (var si = 0; si < order.items.length; si++) {
    var sid = order.items[si].sellerId;
    if (sid && !notifiedSellers[sid]) {
      notifiedSellers[sid] = true;
      addNotification("whatsapp", sellerMessage, sid, "seller-orders");
    }
  }
}

// Le point de retrait déclare que le client n'est pas venu : retour
// immédiat chez le vendeur (sans attendre les 5 jours).
function relaisNotCollected(orderId) {
  var order = (state.orders || []).find(function(o) { return o.id === orderId; });
  if (!order) return;
  if (order.status !== "En boutique") { showToast(t("toast_parcel_not_awaiting_pickup")); return; }
  if (!confirm(t("relais_not_collected_confirm"))) return;
  markOrderReturnedUnclaimed(order, "colis_non_retire", "Colis non récupéré : déclaré par le point de retrait.",
    "⚠️ Commande #" + orderId.slice(-5).toUpperCase() + " : le client n'est pas venu chercher son colis — retour prévu chez vous.");
  render();
  showToast(t("relais_not_collected_done"));
}
// Le point de retrait confirme, avec le code de reprise du livreur, que le
// colis retourné a quitté sa boutique.
function confirmReturnPickup(orderId) {
  var order = (state.orders || []).find(function(o) { return o.id === orderId; });
  if (!order) return;
  var input = document.getElementById("reprise-input-" + orderId);
  var code = input ? String(input.value || "").trim() : "";
  if (!code || code !== String(order.returnPickupCode || "")) { showToast(t("relais_reprise_wrong_code")); return; }
  order.returnStatus = "repris_par_livreur";
  order.returnPickedUpAt = Date.now();
  save();
  secureOrderSaveDoc(order);
  var notified = {};
  (order.items || []).forEach(function(it) {
    if (it.sellerId && !notified[it.sellerId]) { notified[it.sellerId] = true; addNotification("whatsapp", "🔁 Commande #" + orderId.slice(-5).toUpperCase() + " : le colis retourné est en route vers vous avec le livreur. Confirmez sa réception dans vos commandes.", it.sellerId, "seller-orders"); }
  });
  render();
  showToast(t("relais_reprise_done"));
}

function refuseRelaisProduct(orderId) {
  var order = null;
  for (var i = 0; i < state.orders.length; i++) {
    if (state.orders[i].id === orderId) { order = state.orders[i]; break; }
  }
  if (!order) return false;
  if (order.status !== "En boutique") {
    showToast(t("toast_parcel_not_awaiting_pickup"));
    return false;
  }
  if (!confirm("Confirmer le refus du produit par le client ? Le colis repartira avec le prochain passage du livreur, sans commission.")) return false;

  markOrderReturnedUnclaimed(order, "produit_refuse", "Produit refusé par le client au point de retrait lors de la vérification.",
    "⚠️ Commande #" + orderId.slice(-5).toUpperCase() + " refusée par le client au point de retrait — retour prévu chez vous.");
  render();
  showToast(t("toast_product_refused_return"));
  return true;
}

// Un jour complet = 24h, pour calculer depuis combien de temps un colis
// attend au point de retrait.
const PICKUP_DAY_MS = 24 * 60 * 60 * 1000;

// Vérifie TOUS les colis "En boutique" de TOUTE l'app (pas seulement ceux
// de la personne qui a ouvert l'app) et envoie les rappels ou déclenche le
// retour automatique selon le calendrier convenu :
// Jour 1 et 2 : rappel ("venez avant le [date = jour 4]").
// Jour 3 : rappel plus insistant.
// Jour 4 : dernier rappel, très insistant.
// Jour 5 : plus personne n'attend — retour automatique chez le vendeur,
// et on note ce refus sur le compte de l'acheteur pour repérer les
// comportements répétés (voir "unclaimedParcelCount").
// Se déclenche à CHAQUE ouverture de l'app, par N'IMPORTE QUEL compte —
// c'est justement ce qui le rend fiable : avec beaucoup d'utilisateurs,
// il y a presque toujours quelqu'un en train d'ouvrir l'app à un moment
// donné, donc cette vérification tourne très régulièrement sans jamais
// dépendre d'une seule personne précise.
function checkStalePickupOrders() {
  if (!state.orders || !state.orders.length) return;
  var now = Date.now();
  var anyChange = false;
  state.orders.forEach(function(order) {
    if (order.status !== "En boutique" || !order.depotConfirmedAt) return;
    var elapsedDays = Math.floor((now - order.depotConfirmedAt) / PICKUP_DAY_MS);
    var orderCode = "#" + order.id.slice(-5).toUpperCase();
    var shopName = order.relaisShopName || "votre point de retrait";

    if (elapsedDays >= 5) {
      // Au bout de 5 jours (contrat Point de retrait) : retour automatique.
      markOrderReturnedUnclaimed(order, "colis_non_retire",
        "Colis non récupéré par le client dans les 5 jours suivant son arrivée au point de retrait — retour automatique.",
        "⚠️ Commande " + orderCode + " n'a pas été récupérée par le client dans les délais — retour prévu chez vous.");
      var buyerAcc = null;
      for (var bi = 0; bi < state.accounts.length; bi++) { if (state.accounts[bi].id === order.buyerId) { buyerAcc = state.accounts[bi]; break; } }
      if (buyerAcc) {
        // Une fois, ça peut arriver à tout le monde — mais un compteur
        // permet à l'administration de repérer un comportement répété.
        buyerAcc.unclaimedParcelCount = (buyerAcc.unclaimedParcelCount || 0) + 1;
        saveDoc("accounts", buyerAcc);
      }
      anyChange = true;
      return;
    }

    // Rappels au 2e jour et au 4e jour seulement (contrat Point de retrait).
    var targetStage = elapsedDays >= 4 ? 4 : (elapsedDays >= 2 ? 2 : 0);
    if (!targetStage || targetStage <= (order.pickupReminderStage || 0)) return; // rien à envoyer, ou déjà envoyé
    var deadlineLabel = new Date(order.depotConfirmedAt + 5 * PICKUP_DAY_MS).toLocaleDateString("fr-FR", { day: "numeric", month: "long" });
    var message;
    if (targetStage === 2) {
      message = "📦 Votre colis " + orderCode + " vous attend chez " + shopName + ". Venez le chercher avant le " + deadlineLabel + ".";
    } else if (targetStage === 3) { // (palier conservé pour compatibilité, plus utilisé)
      message = "⚠️ Attention : votre colis " + orderCode + " vous attend toujours chez " + shopName + ". Il ne vous reste que jusqu'au " + deadlineLabel + " pour venir le chercher.";
    } else {
      message = "🚨 DERNIER JOUR ! Allez chercher votre colis " + orderCode + " AUJOURD'HUI chez " + shopName + ". Si vous ne venez pas, il repart chez le vendeur et vous ne pourrez plus l'avoir.";
    }
    addNotification("whatsapp", message, order.buyerId, "orders");
    order.pickupReminderStage = targetStage;
    secureOrderSaveDoc(order);
    anyChange = true;
  });
  if (anyChange) save();
}



// Le livreur confirme avoir récupéré le produit refusé pour le ramener au vendeur.
function confirmProductReturn(orderId) {
  var order = null;
  for (var i = 0; i < state.orders.length; i++) {
    if (state.orders[i].id === orderId) { order = state.orders[i]; break; }
  }
  if (!order) return;
  order.returnStatus = "retourne";
  order.returnedAt = Date.now();
  save();
  secureOrderSaveDoc(order);
  render();
  showToast(t("toast_seller_return_confirmed"));
}

// ---------- LITIGES ----------
var DISPUTE_REASONS = {
  produit_endommage: "Produit endommagé ou différent",
  non_recu: "Commande non reçue",
  produit_refuse: "Produit refusé au retrait",
  colis_non_retire: "Colis non récupéré par le client",
  refus_livreur: "Produit refusé par le livreur à la récupération",
  autre: "Autre problème"
};
var DISPUTE_STATUS_FLOW = ["En litige", "Résolu", "Remboursé"];

function createDispute(orderId, reason, description, autoGenerated) {
  var order = null;
  for (var i = 0; i < state.orders.length; i++) {
    if (state.orders[i].id === orderId) { order = state.orders[i]; break; }
  }
  if (!order) { showToast(t("toast_order_not_found")); return null; }

  var sellerIds = [];
  for (var j = 0; j < order.items.length; j++) {
    if (sellerIds.indexOf(order.items[j].sellerId) === -1) sellerIds.push(order.items[j].sellerId);
  }

  var dispute = {
    id: uid(),
    orderId: orderId,
    buyerId: order.buyerId,
    buyerName: order.buyerName,
    sellerIds: sellerIds,
    country: order.country || "Mali",
    reason: reason,
    status: "En litige",
    autoGenerated: !!autoGenerated,
    createdAt: Date.now()
  };
  state.disputes.push(dispute);
  save();
  saveDoc("disputes", dispute);
  // La description détaillée (texte libre, potentiellement sensible)
  // part à part, vers la collection protégée — jamais dans "disputes"
  // lui-même, qui reste largement synchronisé.
  callDisputeDetailsOperation({ operation: "save_dispute_detail", disputeId: dispute.id, orderId: orderId, description: (description || "").trim() });
  dispute.description = (description || "").trim(); // garder en mémoire locale pour cette session
  if (!autoGenerated) {
    for (var sdi = 0; sdi < sellerIds.length; sdi++) {
      if (sellerIds[sdi]) addNotification("whatsapp", "⚠️ Litige ouvert pour la commande #" + orderId.slice(-5).toUpperCase() + " : " + (DISPUTE_REASONS[reason] || reason), sellerIds[sdi]);
    }
  }
  render();
  return dispute;
}

function setDisputeStatus(disputeId, status) {
  var d = null;
  for (var i = 0; i < state.disputes.length; i++) {
    if (state.disputes[i].id === disputeId) { d = state.disputes[i]; break; }
  }
  if (!d) return;
  d.status = status;
  d.resolvedAt = status !== "En litige" ? Date.now() : null;
  save();
  saveDoc("disputes", d);
  addNotification("whatsapp", "Votre litige sur la commande #" + d.orderId.slice(-5).toUpperCase() + " est maintenant : " + status, d.buyerId, "orders");
  render();
  showToast(t("toast_dispute_status_updated"));
}

// ---------- ANNULATION DE COMMANDE ----------
// Seulement possible tant que le vendeur n'a pas commencé à préparer la
// commande (statut "Nouvelle") — au-delà, il est trop tard.
function cancelOrder(orderId) {
  var order = null;
  for (var i = 0; i < state.orders.length; i++) {
    if (state.orders[i].id === orderId) { order = state.orders[i]; break; }
  }
  if (!order) return;
  if (order.status !== "Nouvelle") {
    showToast(t("toast_order_already_preparing"));
    return;
  }
  if (!confirm("Annuler cette commande ?")) return;

  // Restaurer le stock
  for (var j = 0; j < order.items.length; j++) {
    var it = order.items[j];
    for (var k = 0; k < state.products.length; k++) {
      if (state.products[k].id === it.productId) {
        state.products[k].stock += it.qty;
        if (!order.stockReserved) saveDoc("products", state.products[k]); // sinon le serveur remet le stock lui-même
        break;
      }
    }
  }
  logOrderStatusChange(order, "Annulée");
  order.cancelledAt = Date.now();
  // Le statut général ne suffit pas — chaque vendeur regarde en priorité
  // SON propre statut (order.vendorStatuses), qui restait sinon bloqué
  // sur son ancienne valeur (ex: "Nouvelle") même après l'annulation.
  if (!order.vendorStatuses) order.vendorStatuses = {};
  var notifiedSellersOnCancel = {};
  for (var jj = 0; jj < order.items.length; jj++) {
    var sellerIdCancel = order.items[jj].sellerId;
    if (sellerIdCancel && !notifiedSellersOnCancel[sellerIdCancel]) {
      notifiedSellersOnCancel[sellerIdCancel] = true;
      order.vendorStatuses[sellerIdCancel] = "Annulée";
      addNotification("sms", "❌ Commande #" + order.id.slice(-5).toUpperCase() + " annulée par l'acheteur.", sellerIdCancel, "seller-orders");
    }
  }
  save();
  secureOrderSaveDoc(order);
  render();
  showToast(t("toast_order_cancelled"));
}

