// ---------- AFFILIATION ----------
// Code de parrainage STABLE : toujours le même pour un même compte (tiré de
// son identifiant, plus de l'heure). Avant, un nouveau code était fabriqué à
// chaque affichage tant que le serveur ne l'avait pas enregistré — d'où un
// code qui "tournait" et une page qui remontait sans cesse.
function generateReferralCode(userId) {
  var clean = String(userId || "").replace(/[^A-Za-z0-9]/g, "").toUpperCase();
  return "REF" + (clean.slice(-12) || Math.random().toString(36).slice(2, 10).toUpperCase());
}

// Réglages de commission — partagés entre TOUS les appareils (comme les
// réglages d'affichage du marché), pas seulement enregistrés sur celui-ci.
// Réglages de l'algorithme du marché — partagés entre tous les appareils,
// réglables uniquement en Admin (comme la commission).
// ---------- FILATURE (suivi détaillé, réservé aux comptes surveillés) ----------
// Liste des numéros surveillés — réglage partagé, modifiable uniquement en
// Admin, synchronisé entre tous les appareils comme la commission. Aucun
// suivi détaillé n'est jamais activé pour qui que ce soit d'autre.
function getFilatureWatchlist() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "filature_watchlist") return state.settings[i].phones || [];
    }
  }
  return [];
}

function saveFilatureWatchlist(phones) {
  var cfg = { id: "filature_watchlist", phones: phones };
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "filature_watchlist") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(cfg); else state.settings[idx] = cfg;
  save();
  saveDoc("settings", cfg);
}

function isPhoneWatched(phone) {
  var watchlist = getFilatureWatchlist();
  var wid = normalizeWalletPhone(phone);
  return watchlist.some(function(p) { return normalizeWalletPhone(p) === wid; });
}

function getFilatureLog(phone) {
  var wid = normalizeWalletPhone(phone);
  for (var i = 0; i < state.filatureLogs.length; i++) {
    if (state.filatureLogs[i].id === wid) return state.filatureLogs[i];
  }
  return { id: wid, phone: phone, events: [] };
}

// N'enregistre RIEN pour qui que ce soit, sauf si son numéro figure
// explicitement dans la liste de surveillance de l'Admin — vérifié à
