// cinetpay-webhook après vérification réelle auprès de CinetPay.
function checkPaymentReturn() {
  var urlParams = new URLSearchParams(window.location.search);
  var returnOrderId = urlParams.get('paymentReturn');
  if (!returnOrderId) return;
  window.history.replaceState({}, "", window.location.pathname);
  var order = null;
  for (var i = 0; i < state.orders.length; i++) {
    if (state.orders[i].id === returnOrderId) { order = state.orders[i]; break; }
  }
  if (!order) return;
  if (order.paymentStatus === "paid") {
    showToast(t("dt_payment_confirmed_order") + returnOrderId.slice(-5).toUpperCase() + t("dt_validated_excl"));
  } else if (order.paymentStatus === "failed") {
    showToast(t("toast_payment_failed_cancelled"));
  } else {
    showToast(t("toast_payment_confirming"));
  }
}

// Le calcul de la commission et le crédit du parrain sont désormais
// entièrement gérés côté serveur — voir order-write (calcul et
// vérification à la création) et wallet-write / settle_order_payouts
// (crédit réel à la livraison confirmée).

function getAffiliateStats() {
  if (!state.profile) return null;
  return {
    code: getReferralCode(),
    balance: state.profile.affiliateBalance || 0,
    referrals: state.profile.affiliateReferrals || 0,
    earnings: state.profile.affiliateEarnings || [],
    commissionRate: getCommissionConfig().affiliateCommission
  };
}

// ---------- OTP ----------
function generateOTP() {
  return String(Math.floor(1000 + Math.random() * 9000));
}

// ---------- AVIS ----------
function addReview(productId, rating, comment) {
  if (!state.profile) return false;
  
  var hasPurchased = false;
  for (var i = 0; i < state.orders.length; i++) {
    var o = state.orders[i];
    if (o.buyerId !== state.profile.id) continue;
    if (o.status !== "Livrée") continue;
    for (var j = 0; j < o.items.length; j++) {
      if (o.items[j].productId === productId) {
        hasPurchased = true;
        break;
      }
    }
    if (hasPurchased) break;
  }
  
  if (!hasPurchased) {
    showToast(t("toast_must_have_purchased"));
    return false;
  }
  
  var review = {
    id: uid(),
    authUid: authUid,
    productId: productId,
    userId: state.profile.id,
    userName: state.profile.name,
    rating: rating,
    comment: comment,
    verified: true,
    createdAt: Date.now()
  };
  
  state.reviews.push(review);
  save();
  saveDoc("reviews", review);
  showToast(t("toast_thanks_for_review"));
  return true;
}

// Même principe que getAccountsIndex ci-dessus, pour les avis cette
// fois — sans ça, chaque produit affiché reparcourait la totalité des
// avis de toute l'app, deux fois de suite (note moyenne + nombre
// d'avis), à chaque fois qu'un produit s'affichait.
var _reviewsIndexCache = null;
var _reviewsIndexCacheLen = -1;
function getReviewsIndex() {
  if (_reviewsIndexCache && _reviewsIndexCacheLen === state.reviews.length) return _reviewsIndexCache;
  var idx = {};
  for (var i = 0; i < state.reviews.length; i++) {
    var pid = state.reviews[i].productId;
    if (!idx[pid]) idx[pid] = [];
    idx[pid].push(state.reviews[i]);
  }
  _reviewsIndexCache = idx;
  _reviewsIndexCacheLen = state.reviews.length;
  return idx;
}

function getProductReviews(productId) {
  return getReviewsIndex()[productId] || [];
}

function getProductAverageRating(productId) {
  var reviews = getProductReviews(productId);
  if (reviews.length === 0) return 0;
  var sum = 0;
  for (var i = 0; i < reviews.length; i++) {
    sum += reviews[i].rating;
  }
  return Math.round((sum / reviews.length) * 10) / 10;
}

// ---------- RÉPUTATION VENDEUR ----------
// Score de fiabilité (0-5) au-delà de la simple note produit : combine la
// note moyenne des avis, le taux de commandes menées à bien (sans
// annulation ni litige), et un petit bonus de volume pour les boutiques
// actives. Affiché aux acheteurs et suivi en Admin.
function computeSellerReputation(sellerId) {
  var myProductIds = [];
  for (var i = 0; i < state.products.length; i++) {
    if (state.products[i].sellerId === sellerId) myProductIds.push(state.products[i].id);
  }
  // Note moyenne (sur tous les produits du vendeur)
  var ratingSum = 0, ratingCount = 0;
  for (var r = 0; r < state.reviews.length; r++) {
    if (myProductIds.indexOf(state.reviews[r].productId) !== -1) { ratingSum += state.reviews[r].rating; ratingCount++; }
  }
  var avgRating = ratingCount > 0 ? ratingSum / ratingCount : null;

  // Commandes concernant ce vendeur
  var delivered = 0, problematic = 0, total = 0;
  var disputedOrderIds = {};
  for (var d = 0; d < state.disputes.length; d++) {
    if (state.disputes[d].status !== "Résolu") disputedOrderIds[state.disputes[d].orderId] = true;
  }
  // Liste des commandes de ce vendeur, avec leur statut : depuis les
  // statistiques du serveur si elles existent, sinon depuis les commandes
  // présentes sur ce téléphone (ancien calcul).
  var sellerOrderStatuses = [];
  if (orderStatsActive()) {
    var sRow = statsIndex("sellerStats")[sellerId];
    if (sRow && sRow.orders) {
      for (var sOid in sRow.orders) sellerOrderStatuses.push({ id: sOid, status: sRow.orders[sOid] });
    }
  } else {
    for (var o = 0; o < state.orders.length; o++) {
      var ord = state.orders[o];
      var involved = false;
      for (var it = 0; it < ord.items.length; it++) { if (ord.items[it].sellerId === sellerId) { involved = true; break; } }
      if (involved) sellerOrderStatuses.push({ id: ord.id, status: ord.status });
    }
  }
  for (var so = 0; so < sellerOrderStatuses.length; so++) {
    var sOrd = sellerOrderStatuses[so];
    total++;
    if (sOrd.status === "Livrée" && !disputedOrderIds[sOrd.id]) delivered++;
    else if (sOrd.status === "Annulée" || sOrd.status === "Refusée au retrait" || disputedOrderIds[sOrd.id]) problematic++;
  }
  var completionRate = total > 0 ? delivered / total : null;

  var pointsRating = avgRating != null ? (avgRating / 5) * 50 : 30; // neutre si pas encore d'avis
  var pointsCompletion = completionRate != null ? completionRate * 40 : 30; // neutre si pas encore de commandes
  var pointsVolume = Math.min(delivered, 20) / 20 * 10;
  var score100 = Math.round(pointsRating + pointsCompletion + pointsVolume);
  var stars = Math.round((score100 / 100) * 5 * 10) / 10;

  var label = "Nouveau vendeur";
  if (total >= 3) {
    if (score100 >= 85) label = "Excellent";
    else if (score100 >= 65) label = "Fiable";
    else if (score100 >= 40) label = "Correct";
    else label = "À surveiller";
  }

  // Historique bancaire informel — l'argent réellement encaissé et vérifié,
  // pas juste un décompte de commandes. C'est cette donnée-là qui fait de
  // la réputation une vraie "carte de confiance", vérifiable, pas juste
  // déclarative. Ces deux nombres sont désormais calculés et maintenus
  // par le serveur (wallet-write, à chaque vente réglée) — jamais en
  // scannant l'historique complet du portefeuille de quelqu'un d'autre,
  // qui n'a plus à être téléchargé sur chaque téléphone pour ça.
  var sellerAccForWallet = null;
  for (var wai = 0; wai < state.accounts.length; wai++) {
    if (state.accounts[wai].id === sellerId) { sellerAccForWallet = state.accounts[wai]; break; }
  }
  var walletVerifiedTotal = (sellerAccForWallet && sellerAccForWallet.verifiedSalesTotal) || 0;
  var walletVerifiedCount = (sellerAccForWallet && sellerAccForWallet.verifiedSalesCount) || 0;

  return {
    score100: score100,
    stars: stars,
    label: label,
    avgRating: avgRating,
    completionRate: completionRate,
    totalOrders: total,
    deliveredOrders: delivered,
    problematicOrders: problematic,
    walletVerifiedTotal: walletVerifiedTotal,
    walletVerifiedCount: walletVerifiedCount
  };
}

// ---------- GÉOLOCALISATION ----------
var _lastGeoErrorCode = null; // 1=permission refusée, 2=position indisponible (ex: localisation désactivée), 3=délai dépassé

// Message adapté à la vraie cause de l'échec — plutôt qu'un message générique
// à chaque fois. On ne peut pas activer la localisation du téléphone depuis
// le site (aucune page web n'a ce pouvoir, pour des raisons de sécurité,
// quel que soit le navigateur) — mais on peut au moins dire précisément quoi
// faire selon le cas.
function geoErrorMessage() {
  if (_lastGeoErrorCode === 1) {
    return "🚫 Localisation refusée pour ce site. Ouvrez les réglages de votre téléphone (Position/Localisation) et autorisez ce site, puis réessayez — ou placez votre position sur la carte.";
  }
  if (_lastGeoErrorCode === 2) {
    return "📍 Position indisponible — vérifiez que la localisation est ACTIVÉE dans les réglages de votre téléphone, puis réessayez. En attendant, placez votre position sur la carte.";
  }
  return "La localisation automatique n'a pas répondu — placez votre position sur la carte.";
}

function getUserLocation() {
  return new Promise(function(resolve) {
    if (!navigator.geolocation) {
      _lastGeoErrorCode = null;
      console.error("Géolocalisation : navigator.geolocation indisponible dans ce navigateur/contexte.");
      resolve(null);
      return;
    }
    var settled = false;
    // Filet de sécurité : dans certains aperçus intégrés (iframe sandboxée,
    // comme on l'a déjà vu pour l'upload de photos), l'API de géolocalisation
    // peut ne JAMAIS appeler ni le succès ni l'échec — elle reste bloquée
    // silencieusement. On force donc une résolution après un délai raisonnable
    // plutôt que de laisser l'utilisateur face à un bouton qui ne répond plus.
    var safetyTimer = setTimeout(function() {
      if (settled) return;
      settled = true;
      _lastGeoErrorCode = 3;
      console.error("Géolocalisation : délai dépassé sans réponse du navigateur (probable blocage du contexte d'aperçu).");
      resolve(null);
    }, 14000);

    navigator.geolocation.getCurrentPosition(
      function(position) {
        if (settled) return;
        settled = true;
        clearTimeout(safetyTimer);
        _lastGeoErrorCode = null;
        var loc = {
          lat: position.coords.latitude,
          lng: position.coords.longitude,
          accuracy: position.coords.accuracy
        };
        state.userLocation = loc;
        save();
        resolve(loc);
      },
      function(err) {
        if (settled) return;
        settled = true;
        clearTimeout(safetyTimer);
        _lastGeoErrorCode = err ? err.code : null;
        console.error("Géolocalisation refusée/échouée :", err && err.code, err && err.message);
        resolve(null);
      },
      // enableHighAccuracy:true = puce GPS directe. Le réseau/WiFi
      // (false) subit un ralentissement documenté de Chrome (jusqu'à
      // plusieurs minutes de délai s'il ne détecte pas de changement
      // récent), ce qui fait systématiquement échouer un délai court —
      // sur un vrai téléphone, le GPS matériel est le choix fiable.
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 60000 }
    );
  });
}

// Modale "voir la boutique sur la carte" depuis une commande Point de
// Retrait déjà passée — permet à l'acheteur de se repérer pour aller
// récupérer son colis, sans devoir redemander l'adresse par message.
function renderOrderRelaisMapModal() {
  var orderId = state.showOrderRelaisMap;
  var o = null;
  for (var i = 0; i < state.orders.length; i++) { if (state.orders[i].id === orderId) { o = state.orders[i]; break; } }
  if (!o) return '';
  var shop = null;
  for (var s = 0; s < state.accounts.length; s++) { if (state.accounts[s].id === o.relaisShopId) { shop = state.accounts[s]; break; } }
  var html = '<div class="modal-overlay" id="order-relais-map-overlay" data-action="close-order-relais-map">';
  html += '<div class="modal-sheet">';
  html += '<button class="modal-close" data-action="close-order-relais-map"><i class="fa-solid fa-xmark"></i></button>';
  html += '<div class="section-title" style="margin-bottom:6px;"><i class="fa-solid fa-shop"></i> ' + esc(shop ? (shop.shopName || shop.name) : 'Point de Retrait') + '</div>';
  if (shop && shop.shopAddress) html += '<div style="font-size:12px;color:var(--text-dim);margin-bottom:12px;"><i class="fa-solid fa-location-dot"></i> ' + esc(shop.shopAddress) + '</div>';
  if (shop && shop.shopLat != null && shop.shopLng != null) {
    html += '<div id="order-relais-map" class="map-container" style="height:260px;border-radius:14px;overflow:hidden;"></div>';
    window._pendingOrderRelaisMap = { lat: shop.shopLat, lng: shop.shopLng, label: shop.shopName || shop.name };
  } else {
    html += '<div class="empty-state"><i class="fa-solid fa-map-slash"></i><div class="title">' + t("shop_position_unavailable") + '</div>' + t("shop_position_unavailable_hint") + '</div>';
  }
  html += '</div></div>';
  return html;
}

// ---------- Bibliothèques chargées à la demande ----------
// Avant, cartes (Leaflet), graphiques (Chart.js), scanner (jsQR), PDF (jsPDF)
// et QR codes étaient téléchargés au démarrage pour tout le monde. Maintenant
// on ne les télécharge qu'au premier écran qui en a vraiment besoin.
var SNS_LIBS = {
  leaflet: { test: function() { return typeof L !== "undefined"; }, css: ["https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"], js: ["https://unpkg.com/leaflet@1.9.4/dist/leaflet.js", "https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js"] },
  chart: { test: function() { return typeof Chart !== "undefined"; }, js: ["https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js", "https://unpkg.com/chart.js@4.4.1/dist/chart.umd.min.js"] },
  jsqr: { test: function() { return typeof jsQR !== "undefined"; }, js: ["https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js", "https://unpkg.com/jsqr@1.4.0/dist/jsQR.js"] },
  jspdf: { test: function() { return typeof window.jspdf !== "undefined"; }, js: ["https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js", "https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js"] },
  qrcode: { test: function() { return typeof QRCode !== "undefined"; }, js: ["https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js", "https://unpkg.com/qrcode@1.5.3/build/qrcode.min.js", "https://cdn.jsdelivr.net/npm/qrcode@1.5.1/build/qrcode.min.js"] },
  three: { test: function() { return typeof THREE !== "undefined"; }, js: ["https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.min.js", "https://unpkg.com/three@0.160.0/build/three.min.js"] }
};
var _snsLibPromises = {};
function snsLoadLib(name) {
  var lib = SNS_LIBS[name];
  if (!lib) return Promise.reject(new Error("unknown_lib"));
  if (lib.test()) return Promise.resolve();
  if (_snsLibPromises[name]) return _snsLibPromises[name];
  (lib.css || []).forEach(function(href) {
    if (document.querySelector('link[href="' + href + '"]')) return;
    var l = document.createElement("link"); l.rel = "stylesheet"; l.href = href; document.head.appendChild(l);
  });
  _snsLibPromises[name] = new Promise(function(resolve, reject) {
    var tryAt = function(i) {
      if (i >= lib.js.length) { delete _snsLibPromises[name]; reject(new Error("lib_load_failed")); return; }
      var sc = document.createElement("script");
      sc.src = lib.js[i]; sc.async = true;
      sc.onload = function() { if (lib.test()) resolve(); else tryAt(i + 1); };
      sc.onerror = function() { tryAt(i + 1); };
      document.head.appendChild(sc);
    };
    tryAt(0);
  });
  return _snsLibPromises[name];
}
window.snsLoadLib = snsLoadLib;

function renderMap(containerId, lat, lng, markerText, extraMarkers) {
  markerText = markerText || 'Vous êtes ici';
  if (typeof L === 'undefined') {
    var rmArgs = arguments;
    snsLoadLib("leaflet").then(function() { renderMap.apply(null, rmArgs); }).catch(function() {});
    return;
  }
  var container = document.getElementById(containerId);
  if (!container) return;
  // Filet de sécurité : si ce conteneur porte déjà une carte Leaflet — par
  // exemple deux mises à jour rapprochées qui se chevauchent (changer
  // d'adresse puis de point de retrait très vite l'un après l'autre) —
  // Leaflet refuse silencieusement de réinitialiser une carte déjà
  // attachée à cet élément. Résultat : la position affichée reste bloquée
  // sur une ancienne valeur pour toujours, même quand tout le reste (la
  // liste triée par distance, etc.) s'est bien mis à jour. On retire donc
  // proprement toute trace d'une carte précédente avant d'en recréer une.
  if (container._leaflet_id) {
    container._leaflet_id = null;
    container.innerHTML = '';
  }
  // closePopupOnClick désactivé globalement : par défaut, Leaflet ferme
  // TOUTE bulle ouverte dès qu'on touche la carte ailleurs. On veut que ça
  // reste vrai pour la bulle de la boutique (comportement inchangé), mais
  // que la bulle "Vous êtes ici" du client, elle, reste affichée — le
  // client doit toujours pouvoir se repérer — sauf s'il la ferme lui-même
  // avec sa petite croix.
  var map = L.map(containerId, { closePopupOnClick: false }).setView([lat || 12.6392, lng || -8.0029], 13);
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; OpenStreetMap'
  }).addTo(map);
  if (lat != null && lng != null) {
    L.marker([lat, lng]).addTo(map).bindPopup(markerText, { autoClose: false, closeOnClick: false }).openPopup();
  }
  if (Array.isArray(extraMarkers)) {
    for (var i = 0; i < extraMarkers.length; i++) {
      var m = extraMarkers[i];
      var shopMarker = L.marker([m.lat, m.lng], { icon: L.divIcon({ html: '🏪', className: 'shop-map-icon', iconSize: [26, 26] }) })
        .addTo(map).bindPopup(m.label || 'Point de Retrait', { maxWidth: 200 }).openPopup();
      (function(marker) {
        map.on('click', function() { marker.closePopup(); });
      })(shopMarker);
    }
  }
  return map;
}

