function renderPublicDiagnosticPage() {
  var st = window._productsLoadStatus || {};
  var visible = 0;
  try { visible = filteredProducts(true).length; } catch (e) { visible = "erreur : " + e.message; }
  var modCounts = {};
  (state.products || []).forEach(function(p) { var k = p.moderationStatus || "normal"; modCounts[k] = (modCounts[k] || 0) + 1; });
  var lines = [
    "Date : " + new Date().toLocaleString(),
    "Version : " + (window.SOUNSOUNI_VERSION || "?"),
    "Serveur configuré : " + (FIREBASE_ENABLED ? "oui" : "NON"),
    "Connecté : " + (state.profile ? "oui (" + (state.profile.role || "?") + ")" : "non (visiteur)"),
    "Application installée : " + (isNativeAppForGuest() ? "oui" : "non (site web)"),
    "",
    "--- Chargement des articles ---",
    "Étape : " + (st.step || "?"),
    "Durée : " + (st.ms != null ? st.ms + " ms" : "?"),
    "Articles reçus du serveur : " + (st.rows != null ? st.rows : "?"),
    "Erreur : " + (st.error || "aucune"),
    "Code : " + (st.code || "—"),
    "Repli (chargement complet) : " + (st.fallback ? ("reçus=" + st.fallback.rows + ", erreur=" + (st.fallback.error || "aucune") + ", " + st.fallback.ms + " ms") : "non utilisé"),
    "",
    "--- En mémoire sur cet appareil ---",
    "Articles en mémoire : " + (state.products || []).length,
    "Articles visibles au marché : " + visible,
    "Statuts : " + JSON.stringify(modCounts),
    "Comptes en mémoire : " + (state.accounts || []).length,
    "Erreurs au démarrage : " + ((window._bootStepErrors && window._bootStepErrors.length) ? window._bootStepErrors.join(" | ") : "aucune"),
    "Chargement ciblé : " + (window._personalSyncStatus ? ("commandes=" + window._personalSyncStatus.orders + ", notifications=" + window._personalSyncStatus.notifications + ", conversations=" + window._personalSyncStatus.conversations + (window._personalSyncStatus.full ? " (accès complet)" : " (personnel)") + " — via " + (window._personalSyncStatus.via || "?") + (window._personalSyncStatus.fallback ? " [repli : " + window._personalSyncStatus.fallback + "]" : "")) : "pas encore effectué"),
    "Signaux en direct : " + (Object.keys(_signalChannels).length ? (signalsWorking() ? "actifs (" + Object.keys(_signalChannels).join(", ") + ")" : "en connexion ou indisponibles — vérification toutes les 90 s") : "aucun (non connecté)"),
    "Catégorie : " + state.category + " · Recherche : \"" + (state.search || "") + "\"",
    "Filtre boutique : " + (state.shopFilterSellerId || "aucun") + " · Filtre secteur : " + (state.sectorFilter || "aucun")
  ];
  window._diagText = lines.join("\n");
  var html = '<div style="padding:18px;max-width:640px;margin:0 auto;">';
  html += '<div class="section-title" style="margin-bottom:10px;"><i class="fa-solid fa-stethoscope"></i> Diagnostic Sounsouni</div>';
  html += '<div style="display:flex;gap:8px;margin-bottom:12px;">';
  html += '<button class="btn-primary" style="flex:1;" data-action="diag-copy"><i class="fa-solid fa-copy"></i> Copier</button>';
  html += '<button class="btn-secondary" style="flex:1;" data-action="diag-retry"><i class="fa-solid fa-rotate"></i> Réessayer</button>';
  html += '</div>';
  html += '<div class="glass-card" style="padding:12px;font-family:monospace;font-size:11.5px;white-space:pre-wrap;word-break:break-word;">' + esc(window._diagText) + '</div>';
  html += '<button class="link-btn" style="margin-top:14px;" data-action="diag-close"><i class="fa-solid fa-arrow-left"></i> Retour au site</button>';
  html += '</div>';
  return html;
}

// ---------- MODÉRATION DES ARTICLES ----------
// Un article "en attente" (signalé plusieurs fois, ou plus tard repéré par
// le filtre automatique) ou "refusé" par l'Admin n'apparaît plus nulle part
// pour le public — seuls son propre vendeur (pour savoir où il en est) et
// l'Admin (pour décider) peuvent encore le voir.
var PRODUCT_REPORT_THRESHOLD = 3;
function isProductHiddenFromPublic(p) {
  if (!p) return true;
  if (p.moderationStatus !== "pending" && p.moderationStatus !== "rejected") return false;
  if (state.profile && p.sellerId === state.profile.id) return false;
  if (state.view === "admin" && state.adminUnlocked) return false;
  return true;
}

function filteredProducts(skipValueFilters) {
  var f = state.marketFilters;
  var result = [];
  for (var i = 0; i < state.products.length; i++) {
    var p = state.products[i];
    if (isProductHiddenFromPublic(p)) continue;
    var matchCat = state.category === "Tout" || p.category === state.category;
    var search = state.search.trim();
    var matchSearch = !search || p.name.toLowerCase().indexOf(search.toLowerCase()) !== -1 || p.shopName.toLowerCase().indexOf(search.toLowerCase()) !== -1 || (p.barcode || "") === search;
    if (!matchCat || !matchSearch) continue;
    if (state.shopFilterSellerId && p.sellerId !== state.shopFilterSellerId) continue;
    if (state.sectorFilter) {
      if (state.sectorFilter.indexOf("entreprise:") === 0) {
        var wantedSector = state.sectorFilter.split(":")[1];
        if (p.sellerType !== "entreprise" || p.sellerSector !== wantedSector) continue;
      } else if (p.sellerType !== state.sectorFilter) {
        continue;
      }
    }
    if (!skipValueFilters) {
      if (f.inStockOnly && p.stock <= 0) continue;
      if (f.onSaleOnly && !(p.oldPrice && p.oldPrice > p.price)) continue;
      if (f.priceMin !== "" && f.priceMin != null && p.price < Number(f.priceMin)) continue;
      if (f.priceMax !== "" && f.priceMax != null && p.price > Number(f.priceMax)) continue;
    }
    result.push(p);
  }

  // Tri (le tri par défaut "boost" garde le mélange des articles sponsorisés
  // déjà géré par applyBoostOrdering, appliqué juste après)
  if (f.sortBy === "price_asc") {
    result.sort(function(a, b) { return a.price - b.price; });
  } else if (f.sortBy === "price_desc") {
    result.sort(function(a, b) { return b.price - a.price; });
  } else if (f.sortBy === "rating") {
    // Note moyenne : UN seul passage sur TOUS les avis (au lieu d'un
    // passage par produit, qui rescannait encore tout l'historique des
    // avis pour chacun) — à grand volume d'avis, l'ancienne version
    // (même "en cache") pouvait encore prendre plusieurs secondes.
    var ratingSums = {}, ratingCounts = {};
    for (var revi = 0; revi < state.reviews.length; revi++) {
      var rev = state.reviews[revi];
      ratingSums[rev.productId] = (ratingSums[rev.productId] || 0) + rev.rating;
      ratingCounts[rev.productId] = (ratingCounts[rev.productId] || 0) + 1;
    }
    var ratingCache = {};
    for (var rci = 0; rci < result.length; rci++) {
      var rpid = result[rci].id;
      ratingCache[rpid] = ratingCounts[rpid] ? ratingSums[rpid] / ratingCounts[rpid] : 0;
    }
    result.sort(function(a, b) { return ratingCache[b.id] - ratingCache[a.id]; });
  } else if (f.sortBy === "popularity") {
    // Même principe : un seul passage sur TOUTES les commandes (au lieu
    // d'un passage par produit) pour construire le compteur de ventes.
    var salesCache = {};
    for (var sci = 0; sci < result.length; sci++) salesCache[result[sci].id] = getProductSalesCount(result[sci].id);
    result.sort(function(a, b) { return salesCache[b.id] - salesCache[a.id]; });
  } else if (f.sortBy === "newest") {
    result.sort(function(a, b) { return (b.createdAt || 0) - (a.createdAt || 0); });
  } else if (f.sortBy === "nearby" && state.userLocation) {
    var sellerCoords = {};
    for (var sc = 0; sc < state.accounts.length; sc++) {
      var acc = state.accounts[sc];
      if (acc.shopLat != null) sellerCoords[acc.id] = { lat: acc.shopLat, lng: acc.shopLng };
    }
    result.sort(function(a, b) {
      var ca = sellerCoords[a.sellerId], cb = sellerCoords[b.sellerId];
      var da = ca ? distanceKm(state.userLocation.lat, state.userLocation.lng, ca.lat, ca.lng) : 99999;
      var db = cb ? distanceKm(state.userLocation.lat, state.userLocation.lng, cb.lat, cb.lng) : 99999;
      return da - db;
    });
  }

  return f.sortBy === "boost" ? sortMarketWithAlgorithm(result) : result;
}

// ---------- ALGORITHME RECOMMANDATION ----------
// Score de pertinence pur (SANS le boost — le boost est géré séparément
// maintenant, avec son propre équilibre ciblé/large) — réutilisé à la fois
// par "Recommandé pour vous" et par le tri du marché entier.
// Bonus de fraîcheur qui décroît avec l'âge de l'annonce — inspiré de ce
// que font Etsy/Vinted (boost temporaire de 24 à 72h à la publication,
// qui s'estompe ensuite) pour qu'un article neuf ne reste jamais invisible
// juste parce que personne n'a encore d'historique avec lui.
function getRecencyBoost(p) {
  var ageMs = Date.now() - (p.createdAt || 0);
  var DAY = 24 * 60 * 60 * 1000;
  if (ageMs < DAY) return 8;
  if (ageMs < 3 * DAY) return 5;
  if (ageMs < 7 * DAY) return 2;
  return 0;
}

function computeRelevanceScores(profile) {
  var scores = {};
  if (!profile) {
    for (var z = 0; z < state.products.length; z++) scores[state.products[z].id] = getRecencyBoost(state.products[z]);
    return scores;
  }
  var purchased = [];
  for (var i = 0; i < state.orders.length; i++) {
    var o = state.orders[i];
    if (o.buyerId === profile.id) {
      for (var j = 0; j < o.items.length; j++) purchased.push(o.items[j].productId);
    }
  }
  var viewedRaw = profile.behavior ? profile.behavior.views || [] : [];
  var viewedIds = viewedRaw.map(function(v) { return typeof v === "string" ? v : v.productId; });
  var searches = profile.behavior ? profile.behavior.searches || [] : [];
  // Ventes par article : calculées une seule fois (pas une fois par article).
  var salesMapLocal = null;
  function salesOf(pid) {
    if (orderStatsActive()) return productSalesFromStats(pid, 0);
    if (!salesMapLocal) {
      salesMapLocal = {};
      (state.orders || []).forEach(function(o) { if (o.status === "Annulée") return; (o.items || []).forEach(function(it) { salesMapLocal[it.productId] = (salesMapLocal[it.productId] || 0) + (Number(it.qty) || 0); }); });
    }
    return salesMapLocal[pid] || 0;
  }
  var searchWords = [];
  searches.slice(-20).forEach(function(sq) { String(sq && sq.term != null ? sq.term : sq).toLowerCase().split(/\s+/).forEach(function(w) { if (w.length >= 3 && searchWords.indexOf(w) === -1) searchWords.push(w); }); });

  var catPurchases = {};
  for (var m = 0; m < state.orders.length; m++) {
    var o2 = state.orders[m];
    if (o2.buyerId === profile.id) {
      for (var n = 0; n < o2.items.length; n++) {
        var pid = o2.items[n].productId;
        var prod = null;
        for (var q = 0; q < state.products.length; q++) {
          if (state.products[q].id === pid) { prod = state.products[q]; break; }
        }
        if (prod) catPurchases[prod.category] = (catPurchases[prod.category] || 0) + 1;
      }
    }
  }
  var topCat = null, maxCount = 0;
  for (var cat in catPurchases) {
    if (catPurchases[cat] > maxCount) { maxCount = catPurchases[cat]; topCat = cat; }
  }

  var now = new Date();
  var month = now.getMonth();

  for (var k = 0; k < state.products.length; k++) {
    var p = state.products[k];
    var score = 0;
    // Déjà acheté : petit bonus seulement (avant +10 : le client revoyait en
    // tête ce qu'il avait déjà acheté, au lieu de découvrir autre chose).
    if (purchased.indexOf(p.id) !== -1) score += 2;
    if (viewedIds.indexOf(p.id) !== -1) score += 3;
    // Recherches : chaque mot cherché compte (avant, toutes les recherches
    // étaient collées en une seule phrase, qui ne correspondait jamais).
    var pName = String(p.name || "").toLowerCase(), pCat = String(p.category || "").toLowerCase();
    for (var sti = 0; sti < searchWords.length; sti++) {
      if (pName.indexOf(searchWords[sti]) !== -1 || pCat.indexOf(searchWords[sti]) !== -1) { score += 2; break; }
    }
    // Articles qui se vendent vraiment (statistiques du serveur), plafonné
    // pour ne pas enfermer le marché sur quelques articles.
    score += Math.min(4, salesOf(p.id));
    if (p.category === topCat) score += 5;

    for (var h = 0; h < HOLIDAYS.length; h++) {
      var holiday = HOLIDAYS[h];
      var hDate = new Date(now.getFullYear(), holiday.month - 1, holiday.day);
      var diffDays = Math.ceil((hDate - now) / (1000 * 60 * 60 * 24));
      if (diffDays >= -7 && diffDays <= 14) {
        for (var kw = 0; kw < holiday.keywords.length; kw++) {
          if (p.name.toLowerCase().indexOf(holiday.keywords[kw]) !== -1 || p.category.toLowerCase().indexOf(holiday.keywords[kw]) !== -1) score += 4;
        }
      }
    }
    if (month >= 5 && month <= 7 && (p.category === "Mode Femme" || p.category === "Mode Homme")) score += 2;
    if (month >= 10 && month <= 12 && p.category === "Électronique & Téléphones") score += 2;
    score += getRecencyBoost(p);
    scores[p.id] = score;
  }
  return scores;
}

// Mélange une portion "découverte" dans une liste triée par pertinence —
// pour ne jamais enfermer quelqu'un dans son seul historique. Le ratio
// (par défaut 30%) vient du réglage Admin.
function interleaveDiscovery(sortedIds, allIds, discoveryRatio) {
  if (discoveryRatio <= 0 || sortedIds.length === 0) return sortedIds;
  // .indexOf() dans une boucle coûte cher à grande échelle (il reparcourt
  // toute la liste à chaque appel) — remplacé par un vrai répertoire
  // (objet), qui vérifie une présence instantanément au lieu de
  // reparcourir. Avec 20 000 articles, ça faisait des centaines de
  // millions de comparaisons rien que pour cette fonction.
  var sortedIdsSet = {};
  for (var sdi = 0; sdi < sortedIds.length; sdi++) sortedIdsSet[sortedIds[sdi]] = true;
  var discoveryPool = allIds.filter(function(id) { return sortedIdsSet[id]; });
  // Bassin de découverte = même liste, mais mélangée — une position "hasard
  // parmi ce qui existe", pas nécessairement mal noté ou impertinent, juste
  // pas strictement trié par historique à cet endroit précis.
  // Le mélange est mis en cache pour la session : sans ça, chaque clic qui
  // redessine l'écran (y compris juste ajouter un favori) relançait un
  // nouveau tirage aléatoire, et l'article qu'on regardait se retrouvait
  // déplacé ailleurs dans la liste — donnant l'impression qu'il avait
  // disparu du marché, alors qu'il changeait juste de position à chaque
  // rendu.
  var cacheKey = discoveryPool.slice().sort().join(",") + "|" + (window._marketVisitSeed || 0);
  var shuffled;
  if (window._discoveryShuffleCache && window._discoveryShuffleCache.key === cacheKey) {
    shuffled = window._discoveryShuffleCache.order;
  } else {
    shuffled = discoveryPool.slice();
    for (var si = shuffled.length - 1; si > 0; si--) {
      var sj = Math.floor(Math.random() * (si + 1));
      var tmp = shuffled[si]; shuffled[si] = shuffled[sj]; shuffled[sj] = tmp;
    }
    window._discoveryShuffleCache = { key: cacheKey, order: shuffled };
  }
  var result = [];
  var resultSet = {};
  var discoveryIdx = 0;
  var everyNth = Math.max(2, Math.round(1 / discoveryRatio));
  for (var i = 0; i < sortedIds.length; i++) {
    // L'article normal d'abord — jamais sauté, jamais perdu.
    if (!resultSet[sortedIds[i]]) { result.push(sortedIds[i]); resultSet[sortedIds[i]] = true; }
    // Puis, de temps en temps, un article "découverte" en plus — inséré,
    // jamais à la place d'un autre.
    if ((i + 1) % everyNth === 0) {
      while (discoveryIdx < shuffled.length) {
        var pick = shuffled[discoveryIdx++];
        if (!resultSet[pick]) { result.push(pick); resultSet[pick] = true; break; }
      }
    }
  }
  return result;
}

// Titre de section personnalisable dans l'Admin : un titre personnalisé est
// saisi en français. Dans une autre langue, on affiche le titre traduit par
// défaut (sinon "Recommandé pour vous", "Catégories"... restaient en
// français en anglais ou en hindi).
function sectionTitleFor(cfg, defaultKey) {
  if (state.language && state.language !== "fr") return t(defaultKey);
  return (cfg && cfg.title) || t(defaultKey);
}

function getRecommendations(limit) {
  limit = limit || 6;
  if (!state.profile) {
    // Visiteur (mode visiteur du site) : pas d'historique personnel, donc
    // on recommande les articles les plus populaires du moment (ventes et
    // vues des 30 derniers jours), puis les plus récents.
    var sinceGuest = Date.now() - getTrendingWindowMs();
    var guestPool = state.products.filter(function(p) { return !isProductHiddenFromPublic(p) && p.stock !== 0; });
    return guestPool.map(function(p) {
      return { p: p, s: getProductRecentSalesCount(p.id, sinceGuest) * 3 + getProductRecentViewCount(p.id, sinceGuest) };
    }).sort(function(a, b) { return (b.s - a.s) || ((b.p.createdAt || 0) - (a.p.createdAt || 0)); })
      .slice(0, limit).map(function(x) { return x.p; });
  }
  var scores = computeRelevanceScores(state.profile);
  // Table de correspondance id -> produit, construite une seule fois (au
  // lieu de reparcourir tout state.products pour retrouver CHAQUE produit
  // par son id — deux fois de suite dans cette fonction) : avec un grand
  // catalogue, ça pouvait prendre plus d'une demi-seconde, à chaque
  // apparition du carrousel de recommandation pendant le défilement.
  var productById = {};
  for (var pmi = 0; pmi < state.products.length; pmi++) productById[state.products[pmi].id] = state.products[pmi];
  for (var pid in scores) {
    var pForScore = productById[pid];
    if (pForScore && isProductBoosted(pForScore)) scores[pid] += 6; // priorité aux articles boostés, sans écraser totalement la pertinence
  }

  var sorted = Object.keys(scores).sort(function(a, b) { return scores[b] - scores[a]; });

  // Les articles boostés sont toujours inclus en priorité — la rotation ne
  // doit jamais les faire disparaître de la fenêtre visible. Elle ne
  // s'applique qu'au reste, pour faire varier les autres suggestions.
  var boostedIds = [], restIds = [];
  for (var bi = 0; bi < sorted.length; bi++) {
    var pForBoost = productById[sorted[bi]];
    if (pForBoost && isProductBoosted(pForBoost)) boostedIds.push(sorted[bi]); else restIds.push(sorted[bi]);
  }

  var windowIds = boostedIds.slice(0, limit);
  var remainingSlots = limit - windowIds.length;
  if (remainingSlots > 0) {
    // Rotation dans le temps sur le reste : bassin plus large que la place
    // disponible, fenêtre qui glisse toutes les quelques minutes — les
    // suggestions non boostées changent au fil du temps sans perdre en
    // pertinence (le bassin reste trié par score).
    var poolSize = Math.min(restIds.length, Math.max(remainingSlots * 3, remainingSlots));
    var pool = restIds.slice(0, poolSize);
    var rotationSlot = Math.floor(Date.now() / (5 * 60 * 1000)); // change toutes les 5 minutes
    var startIdx = pool.length > remainingSlots ? rotationSlot % (pool.length - remainingSlots + 1) : 0;
    windowIds = windowIds.concat(pool.slice(startIdx, startIdx + remainingSlots));
  }

  var result = [];
  for (var r = 0; r < windowIds.length; r++) {
    var pFinal = productById[windowIds[r]];
    if (pFinal) result.push(pFinal);
  }
  return result;
}
// ============================================================
// GEMS — Logique complète — PARTIE 5/6
// ============================================================

// ---------- EFFETS SAISONNIERS ----------
var seasonalInterval = null;
var seasonalElements = [];

function toggleSeasonalEffects() {
  state.seasonalEffects.enabled = !state.seasonalEffects.enabled;
  if (!state.seasonalEffects.enabled) {
    stopSeasonalEffects();
  } else {
    startSeasonalEffects(state.seasonalEffects.effect);
  }
  save();
  render();
}

function setSeasonalEffect(effect) {
  state.seasonalEffects.effect = effect;
  if (state.seasonalEffects.enabled) {
    stopSeasonalEffects();
    startSeasonalEffects(effect);
  }
  save();
  render();
}

function startSeasonalEffects(effect) {
  stopSeasonalEffects();
  if (!state.seasonalEffects.enabled) return;
  switch(effect) {
    case "snow": startSnowEffect(); break;
    case "hearts": startHeartsEffect(); break;
    case "fireworks": startFireworksEffect(); break;
    case "mali": startMaliFlagEffect(); break;
    default: break;
  }
}

function stopSeasonalEffects() {
  if (seasonalInterval) { clearInterval(seasonalInterval); seasonalInterval = null; }
  for (var i = 0; i < seasonalElements.length; i++) {
    seasonalElements[i].remove();
  }
  seasonalElements = [];
  var selectors = '.snowflake, .heart-float, .firework, .mali-flag-float, .firework-particle';
  var items = document.querySelectorAll(selectors);
  for (var j = 0; j < items.length; j++) {
    items[j].remove();
  }
}

function startSnowEffect() {
  var container = document.body;
  var count = 0;
  seasonalInterval = setInterval(function() {
    if (count > 40) return;
    var flake = document.createElement('div');
    flake.className = 'snowflake';
    var chars = ['❄', '❅', '❆', '✦'];
    flake.textContent = chars[Math.floor(Math.random() * chars.length)];
    flake.style.left = Math.random() * 100 + '%';
    flake.style.fontSize = (8 + Math.random() * 12) + 'px';
    flake.style.animationDuration = (5 + Math.random() * 8) + 's';
    flake.style.opacity = 0.4 + Math.random() * 0.5;
    container.appendChild(flake);
    seasonalElements.push(flake);
    count++;
    setTimeout(function() { flake.remove(); }, 13000);
  }, 600);
}

function startHeartsEffect() {
  var container = document.body;
  var count = 0;
  seasonalInterval = setInterval(function() {
    if (count > 30) return;
    var heart = document.createElement('div');
    heart.className = 'heart-float';
    var symbols = ['❤️', '💕', '💖', '💗', '💓'];
    heart.textContent = symbols[Math.floor(Math.random() * symbols.length)];
    heart.style.left = Math.random() * 90 + 5 + '%';
    heart.style.fontSize = (16 + Math.random() * 24) + 'px';
    heart.style.animationDuration = (4 + Math.random() * 4) + 's';
    container.appendChild(heart);
    seasonalElements.push(heart);
    count++;
    setTimeout(function() { heart.remove(); }, 8000);
  }, 700);
}

function startFireworksEffect() {
  var container = document.body;
  var count = 0;
  seasonalInterval = setInterval(function() {
    if (count > 15) return;
    var x = 10 + Math.random() * 80;
    var y = 10 + Math.random() * 60;
    var colors = ['#ff6b6b', '#ffd93d', '#6bcb77', '#4d96ff', '#ff6bff', '#ff9f43'];
    var firework = document.createElement('div');
    firework.className = 'firework';
    firework.style.left = x + '%';
    firework.style.top = y + '%';
    firework.style.width = '0';
    firework.style.height = '0';
    container.appendChild(firework);
    for (var i = 0; i < 30; i++) {
      var particle = document.createElement('div');
      particle.className = 'firework-particle';
      var angle = Math.random() * 2 * Math.PI;
      var dist = 50 + Math.random() * 120;
      particle.style.setProperty('--tx', Math.cos(angle) * dist + 'px');
      particle.style.setProperty('--ty', Math.sin(angle) * dist + 'px');
      particle.style.background = colors[Math.floor(Math.random() * colors.length)];
      particle.style.width = (3 + Math.random() * 5) + 'px';
      particle.style.height = particle.style.width;
      particle.style.animationDuration = (0.8 + Math.random() * 0.6) + 's';
      firework.appendChild(particle);
    }
    seasonalElements.push(firework);
    count++;
    setTimeout(function() { firework.remove(); }, 1500);
  }, 900);
}

function startMaliFlagEffect() {
  var container = document.body;
  var flags = ['🇲🇱', '🇲🇱', '🇲🇱', '🇲🇱'];
  for (var i = 0; i < flags.length; i++) {
    var el = document.createElement('div');
    el.className = 'mali-flag-float';
    el.textContent = flags[i];
    el.style.left = (15 + i * 20) + '%';
    el.style.top = (10 + Math.random() * 30) + '%';
    el.style.fontSize = (30 + Math.random() * 20) + 'px';
    el.style.animationDelay = (i * 0.5) + 's';
    container.appendChild(el);
    seasonalElements.push(el);
  }
}

// ---------- ADMIN STATISTIQUES ----------
// Commandes marquées "Prête" depuis plus de 30 minutes sans qu'aucun
// livreur ne les ait prises — sert d'alerte visible sur l'onglet Admin.
function countLateUnassignedOrders() {
  var terminalNonActive = ["Annulée", "Non livrable", "Refusée au retrait", "Livrée", "En boutique"];
  return state.orders.filter(function(o) {
    if (terminalNonActive.indexOf(o.status) !== -1) return false;
    if (statusProgressIndex(o.status) < statusProgressIndex("Prête")) return false;
    if (o.livreurId) return false;
    var readyStep = (o.statusHistory || []).find(function(h) { return h.status === "Prête"; });
    return readyStep && (Date.now() - readyStep.at) > 30 * 60 * 1000;
  }).length;
}

function computeAdminStats() {
  var orders = state.orders.filter(inAdminScope);
  var products = state.products.filter(inAdminScope);
  var totalSales = 0;
  for (var i = 0; i < orders.length; i++) {
    totalSales += orders[i].total;
  }
  var totalOrders = orders.length;
  var cfgStats = getCommissionConfig();
  var totalCommission = 0;
  var totalCommissionWithAffiliate = 0;
  var totalCommissionWithoutAffiliate = 0;
  var totalAffiliatePaid = 0;
  for (var j = 0; j < orders.length; j++) {
    var oj = orders[j];
    // Anciennes commandes (avant ce système) : on retombe sur une
    // estimation au taux actuel, plutôt que de les ignorer complètement.
    var ojCommission = oj.commissionTotal != null ? oj.commissionTotal : oj.subtotal * cfgStats.totalCommissionRate;
    totalCommission += ojCommission;
    if (oj.affiliateId) {
      totalCommissionWithAffiliate += ojCommission;
      totalAffiliatePaid += oj.affiliateAmount || 0;
    } else {
      totalCommissionWithoutAffiliate += ojCommission;
    }
  }
  var deliveryRevenue = 0;
  for (var k = 0; k < orders.length; k++) {
    deliveryRevenue += orders[k].deliveryFee;
  }
  
  var productSales = {};
  for (var m = 0; m < orders.length; m++) {
    var o = orders[m];
    for (var n = 0; n < o.items.length; n++) {
      var it = o.items[n];
      productSales[it.productId] = (productSales[it.productId] || 0) + it.qty;
    }
  }
  var topProducts = Object.keys(productSales).sort(function(a, b) { return productSales[b] - productSales[a]; }).slice(0, 5);
  var topProductsList = [];
  for (var p = 0; p < topProducts.length; p++) {
    var pid = topProducts[p];
    for (var q = 0; q < products.length; q++) {
      if (products[q].id === pid) {
        topProductsList.push({ ...products[q], qty: productSales[pid] });
        break;
      }
    }
  }
  
  var sellerSales = {};
  for (var r = 0; r < orders.length; r++) {
    var o2 = orders[r];
    for (var s = 0; s < o2.items.length; s++) {
      var it2 = o2.items[s];
      var key = it2.sellerId || it2.sellerName;
      if (!sellerSales[key]) {
        sellerSales[key] = { name: it2.sellerName || key, sellerId: it2.sellerId || null, total: 0, orders: 0 };
      }
      sellerSales[key].total += it2.price * it2.qty;
      sellerSales[key].orders += 1;
    }
  }
  var sellerRanking = Object.keys(sellerSales).map(function(key) { return sellerSales[key]; }).sort(function(a, b) { return b.total - a.total; });
  
  var now = Date.now();
  var dayMs = 24 * 60 * 60 * 1000;
  var weekMs = 7 * dayMs;
  var monthMs = 30 * dayMs;
  var period = state.adminStats.period || "semaine";
  var periodMs = weekMs;
  if (period === "jour") periodMs = dayMs;
  else if (period === "mois") periodMs = monthMs;
  
  var filteredOrders = [];
  for (var t = 0; t < orders.length; t++) {
    var o3 = orders[t];
    if (state.adminStats.dateFrom && o3.createdAt < new Date(state.adminStats.dateFrom).getTime()) continue;
    if (state.adminStats.dateTo && o3.createdAt > new Date(state.adminStats.dateTo).getTime()) continue;
    if (state.adminStats.sellerFilter) {
      var hasSeller = false;
      for (var u = 0; u < o3.items.length; u++) {
        if (o3.items[u].sellerName === state.adminStats.sellerFilter) { hasSeller = true; break; }
      }
      if (!hasSeller) continue;
    }
    if (state.adminStats.productFilter) {
      var hasProduct = false;
      for (var v = 0; v < o3.items.length; v++) {
        if (o3.items[v].productId === state.adminStats.productFilter) { hasProduct = true; break; }
      }
      if (!hasProduct) continue;
    }
    filteredOrders.push(o3);
  }
  
  var chartData = [];
  var labels = [];
  var startDate = new Date(now - periodMs);
  var points = period === "jour" ? 24 : period === "semaine" ? 7 : 30;
  for (var w = 0; w < points; w++) {
    var date = new Date(startDate.getTime() + (periodMs / points) * w);
    var label = period === "jour" ? date.getHours() + 'h' : date.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
    labels.push(label);
    var dayTotal = 0;
    for (var x = 0; x < filteredOrders.length; x++) {
      var d = new Date(filteredOrders[x].createdAt);
      if (d >= date && d < new Date(date.getTime() + (periodMs / points))) {
        dayTotal += filteredOrders[x].total;
      }
    }
    chartData.push(dayTotal);
  }
  
  var totalReviews = state.reviews.length;
  var avgRating = 0;
  if (totalReviews > 0) {
    var sumRating = 0;
    for (var y = 0; y < state.reviews.length; y++) {
      sumRating += state.reviews[y].rating;
    }
    avgRating = sumRating / totalReviews;
  }
  var affiliateTotal = 0;
  for (var z = 0; z < state.accounts.length; z++) {
    if (Array.isArray(state.accounts[z].affiliateEarnings)) {
      for (var z2 = 0; z2 < state.accounts[z].affiliateEarnings.length; z2++) {
        affiliateTotal += state.accounts[z].affiliateEarnings[z2].amount;
      }
    }
  }
  
  var productsCount = products.length;
  var sellersSet = {};
  for (var a1 = 0; a1 < products.length; a1++) {
    sellersSet[products[a1].sellerId] = true;
  }
  var sellersCount = Object.keys(sellersSet).length;
  var totalItemsSold = 0;
  for (var b1 = 0; b1 < orders.length; b1++) {
    for (var c1 = 0; c1 < orders[b1].items.length; c1++) {
      totalItemsSold += orders[b1].items[c1].qty;
    }
  }
  
  return {
    totalSales: totalSales,
    totalOrders: totalOrders,
    totalCommission: totalCommission,
    totalCommissionWithAffiliate: totalCommissionWithAffiliate,
    totalCommissionWithoutAffiliate: totalCommissionWithoutAffiliate,
    totalAffiliatePaid: totalAffiliatePaid,
    deliveryRevenue: deliveryRevenue,
    topProducts: topProductsList,
    sellerRanking: sellerRanking,
    chartData: chartData,
    chartLabels: labels,
    totalRevenue: totalCommission + deliveryRevenue,
    avgOrderValue: totalOrders > 0 ? totalSales / totalOrders : 0,
    productsCount: productsCount,
    sellersCount: sellersCount,
    totalItemsSold: totalItemsSold,
    totalReviews: totalReviews,
    avgRating: avgRating,
    affiliateTotal: affiliateTotal,
    affiliateReferrals: state.accounts.reduce(function(sum, a) { return sum + (a.affiliateReferrals || 0); }, 0),
  };
}

function getSellerNames() {
  var set = {};
  for (var i = 0; i < state.products.length; i++) {
    if (!inAdminScope(state.products[i])) continue;
    var name = state.products[i].sellerName;
    if (name) set[name] = true;
  }
  return Object.keys(set);
}

function getProductNames() {
  var result = [];
  for (var i = 0; i < state.products.length; i++) {
    if (!inAdminScope(state.products[i])) continue;
    result.push({ id: state.products[i].id, name: state.products[i].name });
  }
  return result;
}

