var root = document.getElementById("root");

// Filet de sécurité pour toutes les petites cartes Leaflet de l'app :
// quand le clavier du téléphone s'ouvre/se ferme, ou qu'on change
// d'orientation, la taille visible du cadre change sans que Leaflet le
// sache — la carte reste alors mal calée / déborde de son cadre arrondi
// jusqu'à ce qu'on la recrée entièrement. On lui redit sa vraie taille à
// chaque fois que la fenêtre visible change.
window.addEventListener("resize", function() {
  if (window._activeLeafletMap) {
    setTimeout(function() {
      try { window._activeLeafletMap.invalidateSize(); } catch (e) {}
    }, 120);
  }
});

// ---------- OPTION 2 : POINT D'ACCÈS JSON POUR INTERROGATION (#api-parcel=...) ----------
// Simule ce que serait un vrai point d'API une fois l'application hébergée
// en ligne : le partenaire "interroge" cette adresse avec le numéro de
// suivi et sa clé, et reçoit une réponse JSON — lisible par un programme,
// pas une page visuelle. Vérifié avant tout le reste de l'application.
(function handlePollingApiRequest() {
  if (window.location.hash.indexOf("#api-parcel=") !== 0) return;
  var params = new URLSearchParams(window.location.hash.slice(1));
  var tracking = params.get("api-parcel");
  var key = params.get("key");

  // Bloque immédiatement le reste de l'app le temps que la vérification
  // (désormais faite côté serveur, plus jamais en comparant localement
  // contre la liste de toutes les clés) réponde.
  document.body.innerHTML = '';
  document.body.style.margin = '0';
  var pre = document.createElement('pre');
  pre.style.cssText = 'padding:20px;font-family:monospace;font-size:13px;white-space:pre-wrap;word-break:break-word;';
  pre.textContent = '{"status": "loading"}';
  document.body.appendChild(pre);
  document.title = "Sounsouni - API";
  window._apiModeActive = true;

  function writeResponse(response) {
    pre.textContent = JSON.stringify(response, null, 2);
  }

  if (!key) {
    writeResponse({ error: "unauthorized", message: "Clé d'accès invalide ou inconnue." });
  } else {
    fetch(supabaseConfig.url + "/functions/v1/verify-api-key", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey },
      body: JSON.stringify({ apiKey: key })
    })
      .then(function(r) { return r.json(); })
      .then(function(res) {
        var matchedPartner = res.success ? state.apiPartners.find(function(p) { return p.id === res.partnerId; }) : null;
        if (!matchedPartner) {
          writeResponse({ error: "unauthorized", message: "Clé d'accès invalide ou inconnue." });
          return;
        }
        var parcel = null;
        for (var i = 0; i < state.externalParcels.length; i++) {
          // Cloisonnement : un partenaire ne peut jamais consulter les colis
          // d'une autre plateforme, même s'il devine un numéro de suivi.
          if (state.externalParcels[i].trackingNumber === tracking && state.externalParcels[i].platform === matchedPartner.platform) {
            parcel = state.externalParcels[i];
            break;
          }
        }
        if (!parcel) {
          writeResponse({ error: "not_found", message: "Aucun colis avec ce numéro de suivi pour cette plateforme." });
        } else {
          writeResponse({
            trackingNumber: parcel.trackingNumber,
            platform: parcel.platform,
            status: parcel.status,
            statusHistory: parcel.statusHistory,
            relaisShopName: parcel.relaisShopName,
            createdAt: new Date(parcel.createdAt).toISOString(),
            retrievedAt: parcel.retrievedAt ? new Date(parcel.retrievedAt).toISOString() : null
          });
        }
      })
      .catch(function(err) {
        writeResponse({ error: "server_error", message: String(err) });
      });
  }
  throw new Error("__API_RESPONSE_SENT__");
})();

