function currentOverlayKey() {
  for (var oi = 0; oi < OVERLAY_REGISTRY.length; oi++) {
    if (OVERLAY_REGISTRY[oi].isOpen()) return OVERLAY_REGISTRY[oi].key;
  }
  return null;
}

function closeOverlayByKey(k) {
  for (var oi = 0; oi < OVERLAY_REGISTRY.length; oi++) {
    if (OVERLAY_REGISTRY[oi].key === k) { OVERLAY_REGISTRY[oi].close(); return; }
  }
}

// Ajoute/retire automatiquement une étape d'historique de navigateur à
// chaque ouverture/fermeture de fenêtre ET à chaque changement de page —
// gérés ENSEMBLE (et non plus par deux fonctions séparées) pour éviter le
// cas où une fenêtre se ferme ET la page change dans la même action (ex:
// "Acheter maintenant" ferme la fiche produit et ouvre la page paiement en
// même temps) : traiter ça comme deux étapes d'historique distinctes
// provoquait un empilement puis un retour en arrière immédiat qui
// annulait la navigation qu'on venait de faire. Ici, ce genre de double
// changement REMPLACE l'étape du dessus au lieu d'empiler puis reculer.
// Nombre d'étapes que L'APPLICATION a elle-même ajoutées à l'historique du
// navigateur : tant qu'il en reste, un "retour" reste dans l'app ; à zéro,
// un "retour" sortirait du site — les boutons Retour de l'app ramènent
// alors à l'accueil de l'app au lieu de quitter.
var _snsHistoryDepth = 0;
var _overlayHasOwnEntry = false;
function safeHistoryBack(fallbackFn) {
  if (_snsHistoryDepth > 0) { history.back(); return; }
  if (fallbackFn) fallbackFn();
}
function goToAppHome() {
  state.view = (state.profile && ROLE_HOME_VIEW[state.profile.role]) || "market";
  render();
}

function syncHistoryForNav() {
  if (!state.profile) return;
  var newView = state.view;
  var newOverlay = currentOverlayKey();
  if (suppressHistoryPush) {
    // Ce rendu vient d'un retour (physique ou logiciel) déjà traité par
    // popstate — on aligne juste notre suivi interne, sans rien repousser.
    lastHistoryView = newView;
    lastHistoryOverlayKey = newOverlay;
    suppressHistoryPush = false;
    return;
  }
  var viewChanged = newView !== lastHistoryView;
  var overlayChanged = newOverlay !== lastHistoryOverlayKey;
  if (!viewChanged && !overlayChanged) return;

  if (lastHistoryView === null) {
    // Tout premier rendu après connexion.
    history.replaceState({ view: newView, overlay: newOverlay }, "");
    _overlayHasOwnEntry = false;
  } else if (overlayChanged && !viewChanged && newOverlay !== null && lastHistoryOverlayKey === null) {
    // Une fenêtre s'ouvre seule, rien d'autre ne change → on empile une
    // étape pour qu'un retour la referme.
    window.scrollTo(0, 0);
    history.pushState({ view: newView, overlay: newOverlay }, "");
    _snsHistoryDepth++;
    _overlayHasOwnEntry = true;
  } else if (overlayChanged && !viewChanged && newOverlay === null && lastHistoryOverlayKey !== null) {
    // Une fenêtre se ferme seule, autrement qu'avec le retour (bouton
    // "X", validation...) → on retire l'étape qu'on avait ajoutée pour
    // elle, pour ne pas laisser une étape fantôme. UNIQUEMENT si une étape
    // avait vraiment été ajoutée pour elle : sinon ce "retour" reculait
    // d'une vraie page — et sortait du site (fenêtre des messages, fiche
    // compte de l'Admin...).
    var hadOwnEntry = _overlayHasOwnEntry;
    _overlayHasOwnEntry = false;
    lastHistoryView = newView;
    lastHistoryOverlayKey = newOverlay;
    if (hadOwnEntry && _snsHistoryDepth > 0) {
      suppressHistoryPush = true;
      history.back();
    }
    return;
  } else if (viewChanged && !overlayChanged) {
    // Changement de page classique, aucune fenêtre impliquée.
    window.scrollTo(0, 0);
    history.pushState({ view: newView, overlay: newOverlay }, "");
    _snsHistoryDepth++;
  } else {
    // Les deux changent en même temps (fenêtre + page), ou une fenêtre en
    // remplace une autre : on REMPLACE l'étape du dessus plutôt que
    // d'empiler puis de revenir en arrière. Une fenêtre qui en remplace
    // une autre reprend son étape ; une fenêtre ouverte avec un changement
    // de page n'a pas d'étape à elle.
    window.scrollTo(0, 0);
    history.replaceState({ view: newView, overlay: newOverlay }, "");
    if (!(lastHistoryOverlayKey !== null && newOverlay !== null)) _overlayHasOwnEntry = false;
  }
  lastHistoryView = newView;
  lastHistoryOverlayKey = newOverlay;
}

// Après chaque rendu, cache visuellement (plutôt que de simplement bloquer
// au clic) tout ce qui est réservé au Groupe 1 — pour qu'un employé ne
// voie même pas de bouton qu'il ne peut pas utiliser. Centralisé ici pour
// ne dépendre d'aucun écran individuel.
// Remplit chaque emplacement réservé (.qr-code-slot) avec un vrai QR code
// généré à partir du code qu'il porte — pour que le code de retrait/dépôt
// soit aussi scannable, pas seulement lisible en chiffres.
// Le thème est un réglage global de la plateforme (comme la commission) —
// un seul thème pour tout le monde, choisi uniquement par l'Admin, jamais
// par chaque utilisateur individuellement.
function getThemeConfig() {
  if (state.settings) {
    for (var i = 0; i < state.settings.length; i++) {
      if (state.settings[i].id === "theme_config") return state.settings[i].theme || "green-yellow";
    }
  }
  return "green-yellow";
}

function saveThemeConfig(themeValue) {
  var cfg = { id: "theme_config", theme: themeValue };
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) {
    if (state.settings[i].id === "theme_config") { idx = i; break; }
  }
  if (idx === -1) state.settings.push(cfg); else state.settings[idx] = cfg;
  save();
  saveDoc("settings", cfg);
}

// Cache en mémoire — un QR code déjà généré pour une valeur donnée n'a
// pas besoin d'être recalculé à chaque redessin de l'écran (qui reconstruit
// tout le DOM, y compris les QR codes déjà affichés juste avant).
var qrCodeCache = {};

function renderPendingQRCodes() {
  var slots = root.querySelectorAll('.qr-code-slot[data-qr-value]');
  for (var i = 0; i < slots.length; i++) {
    (function(slot) {
      var value = slot.dataset.qrValue;
      if (qrCodeCache[value]) {
        var cachedImg = document.createElement('img');
        cachedImg.src = qrCodeCache[value];
        cachedImg.style.width = '100%';
        cachedImg.style.height = '100%';
        cachedImg.style.background = '#fff';
        cachedImg.style.borderRadius = '8px';
        slot.innerHTML = '';
        slot.appendChild(cachedImg);
        return;
      }
      // Toujours forcer noir sur blanc, quel que soit le thème actif — et
      // si la bibliothèque de génération échoue ou n'a pas pu charger
      // (réseau capricieux sur certains téléphones), on affiche le code en
      // texte brut plutôt qu'un carré vide invisible.
      if (typeof QRCode === 'undefined' && !renderPendingQRCodes._failed) {
        snsLoadLib("qrcode").then(function() { renderPendingQRCodes(); }).catch(function() { renderPendingQRCodes._failed = true; renderPendingQRCodes(); });
        return;
      }
      if (typeof QRCode === 'undefined') {
        slot.innerHTML = '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:#fff;color:#000;font-weight:800;font-size:13px;text-align:center;padding:6px;border-radius:8px;">' + esc(value) + '</div>';
        return;
      }
      QRCode.toDataURL(value, { width: 220, margin: 1, color: { dark: '#000000', light: '#ffffff' } }).then(function(url) {
        qrCodeCache[value] = url;
        var img = document.createElement('img');
        img.src = url;
        img.style.width = '100%';
        img.style.height = '100%';
        img.style.background = '#fff';
        img.style.borderRadius = '8px';
        slot.innerHTML = '';
        slot.appendChild(img);
      }).catch(function() {
        slot.innerHTML = '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:#fff;color:#000;font-weight:800;font-size:13px;text-align:center;padding:6px;border-radius:8px;">' + esc(value) + '</div>';
      });
    })(slots[i]);
  }
}

function renderPendingStorageReport() {
  var slot = document.getElementById("browser-storage-report");
  if (!slot || !slot.dataset.storageReportPending) return;
  slot.dataset.storageReportPending = "";
  computeBrowserStorageReport(function(report) {
    var slot2 = document.getElementById("browser-storage-report");
    if (!slot2) return; // l'écran a changé entre-temps
    var html = '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-hard-drive"></i> Ce que le navigateur voit réellement</div>';
    if (report.estimateUsage != null) {
      var usageMo = (report.estimateUsage / 1024).toFixed(2);
      var quotaMo = report.estimateQuota != null ? (report.estimateQuota / 1024).toFixed(0) : "?";
      html += '<div class="mono" style="font-size:18px;font-weight:700;margin-bottom:4px;">' + usageMo + ' Mo <span style="font-size:12px;color:var(--text-dim);font-weight:400;">/ ' + quotaMo + ' Mo alloués</span></div>';
      html += '<div style="font-size:10.5px;color:var(--text-dim);margin-bottom:10px;">Chiffre donné par le navigateur lui-même — inclut tout ce qui est stocké pour ce site (pas seulement les données de l\'app).</div>';
    } else {
      html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Ce navigateur ne fournit pas cette information directement.</div>';
    }
    html += '<div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">Toutes les clés réellement stockées (' + report.keys.length + ')</div>';
    for (var i = 0; i < report.keys.length; i++) {
      var kr = report.keys[i];
      html += '<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;border-bottom:1px solid var(--border-color);"><span style="word-break:break-all;padding-right:8px;">' + esc(kr.key) + '</span><span style="font-weight:700;flex-shrink:0;">' + (kr.sizeKB > 1024 ? (kr.sizeKB / 1024).toFixed(2) + ' Mo' : kr.sizeKB + ' Ko') + '</span></div>';
    }
    slot2.innerHTML = html;
  });
}

function applyEmployeeRestrictions() {
  if (!(state.adminUnlocked && !state.adminIsOwner)) return;
  var perms = getEmployeePermissions();

  function hideAll(actions) {
    for (var i = 0; i < actions.length; i++) {
      var els = root.querySelectorAll('[data-action="' + actions[i] + '"]');
      for (var j = 0; j < els.length; j++) els[j].style.display = 'none';
    }
  }
  hideAll(ADMIN_RESTRICTED_ACTIONS);
  if (!perms.canApprove) hideAll(ADMIN_APPROVE_ACTIONS);
  if (!perms.canReply) hideAll(ADMIN_REPLY_ACTIONS);

  // Curseurs/sélecteurs de réglages visuels (pas de simple data-action)
  var inputPrefixes = ['brand-image-', 'section-style-', 'bgpattern-', 'webhook-partner-', 'dashboard-partner-', 'api-partner-', 'platform-commission-', 'owner-cred-', 'employee-cred-'];
  var allInputs = root.querySelectorAll('[data-action-input]');
  for (var k = 0; k < allInputs.length; k++) {
    var val = allInputs[k].dataset.actionInput || '';
    for (var p = 0; p < inputPrefixes.length; p++) {
      if (val.indexOf(inputPrefixes[p]) === 0) { allInputs[k].disabled = true; allInputs[k].style.opacity = '0.5'; break; }
    }
  }
  if (!perms.canReply) {
    var replyInputs = root.querySelectorAll('#admin-reply-input');
    for (var r = 0; r < replyInputs.length; r++) { replyInputs[r].disabled = true; replyInputs[r].placeholder = 'Réponse non autorisée pour le moment'; }
  }
}

// Fiche article : nombre d'articles dans « Vous pourriez aussi aimer » et
// taille des lots de « Produits du marché ».
var PD_RELATED_MAX = 9, PD_MARKET_PAGE = 9, PD_MARKET_MAX = 120;
function setupPdMarketScroll() {
  var sentinel = document.getElementById("pd-market-sentinel");
  if (!sentinel || !('IntersectionObserver' in window)) return;
  var obs = new IntersectionObserver(function(entries) {
    if (!entries[0].isIntersecting) return;
    var st = window._pdMarket, grid = document.getElementById("pd-market-grid");
    if (!st || !st.list || !grid) { obs.disconnect(); return; }
    var from = st.shown, to = Math.min(from + PD_MARKET_PAGE, st.list.length), add = "";
    for (var i = from; i < to; i++) add += productCard(st.list[i]);
    grid.insertAdjacentHTML("beforeend", add);
    st.shown = to;
    if (to >= st.list.length) { obs.disconnect(); if (sentinel.parentNode) sentinel.parentNode.removeChild(sentinel); }
  }, { rootMargin: "300px" });
  obs.observe(sentinel);
}

function setupMarketInfiniteScroll() {
  var sentinel = document.getElementById("market-infinite-sentinel");
  if (!sentinel) return;
  // La sentinelle est un tout nouvel élément à chaque rendu (tout l'écran
  // est reconstruit) — il faut donc réattacher l'observateur à chaque
  // fois, jamais une seule fois au démarrage.
  var observer = new IntersectionObserver(function(entries) {
    if (entries[0].isIntersecting && !window._marketLoadingMore) {
      window._marketLoadingMore = true;
      state.marketVisibleCount = (state.marketVisibleCount || MARKET_PAGE_SIZE) + MARKET_PAGE_SIZE;
      // On ne redemande une nouvelle fournée à Supabase que si ce qui est
      // déjà en mémoire commence vraiment à manquer (moins d'une page
      // d'avance) — pas à chaque fois que 20 articles de plus s'affichent,
      // sinon on redemanderait bien plus souvent que nécessaire alors que
      // les 300 déjà chargés suffisent encore largement.
      if (state.marketVisibleCount + MARKET_PAGE_SIZE >= state.products.length) {
        loadMoreProductsIfNeeded();
      }
      window._skipScrollRestore = true;
      render();
      window._marketLoadingMore = false;
    }
  }, { rootMargin: "600px" });
  observer.observe(sentinel);
}

function render() {
  window._renderTick = (window._renderTick || 0) + 1;
  // Depuis le verrouillage, une commande peut arriver sans sa liste
  // d'articles (rangée à part sur le serveur) : jamais de plantage d'écran.
  (state.orders || []).forEach(function(o) { if (o && !Array.isArray(o.items)) o.items = []; });
  if (window._pendingProductLink && typeof _splashFinished !== "undefined" && _splashFinished) { try { openPendingProductLink(); } catch (e) {} }
  try { syncDiagnosticsMirror(); } catch (e) {}
  if (window.__bootMark && window._renderTick <= 6) window.__bootMark("affichage n°" + window._renderTick + " (" + state.view + (state.profile ? ", connecté" : ", visiteur") + ")");
  // Téléphone (app) : réinscription automatique à chaque connexion ou
  // changement de compte — avant, seulement au démarrage de l'app.
  if (state.profile && window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.PushNotifications
      && typeof _splashFinished !== "undefined" && _splashFinished && window._fcmAutoRegisterFor !== state.profile.id) {
    window._fcmAutoRegisterFor = state.profile.id;
    setTimeout(function() { try { subscribeToFcmIfCapacitor(true); } catch (e) {} }, 0);
  }
  if (window._personalSyncIdentity !== undefined && typeof bootDone !== "undefined" && bootDone && window._personalSyncIdentity !== personalSyncIdentityKey()) {
    window._personalSyncIdentity = personalSyncIdentityKey();
    setTimeout(syncPersonalCollections, 0);
  }
  if (window._apiModeActive) return; // réponse JSON déjà envoyée, ne rien redessiner par-dessus
  // Nouvelle disposition à chaque fois qu'on REVIENT sur le marché (pas à
  // chaque rendu à l'intérieur — sinon un simple ajout aux favoris
  // redistribuerait tout et donnerait l'impression qu'un article a
  // disparu). On ne change la graine que sur une vraie transition vers
  // cette vue, jamais pendant qu'on y reste.
  if (state.view === "market" && window._lastRenderedView !== "market") {
    window._marketVisitSeed = Math.random();
    // Même principe que la graine ci-dessus, pour "À la une" : la liste
    // ET le nombre d'articles éligibles (ventes/vues récentes) changent
    // en permanence en arrière-plan — les regeler ici, une fois pour
    // toute la visite, évite qu'une rangée entière apparaisse ou
    // disparaisse d'un coup pendant qu'on défile (par exemple juste
    // après avoir soi-même ouvert un article, ce qui compte comme une
    // vue de plus dès le rendu suivant).
    try { window._newArrivalsSnapshot = getNewArrivals(); } catch (naErr) {
      // Jamais bloquant : sans cette protection, une erreur ici (en dehors
      // de la zone protégée de l'affichage) laissait le logo à l'écran.
      console.error("Nouveautés : calcul impossible", naErr);
      window._newArrivalsSnapshot = state.products.slice().sort(function(a, b) { return (b.createdAt || 0) - (a.createdAt || 0); }).slice(0, 12);
    }
  }
  window._lastRenderedView = state.view;
  // Garde-fou : le marché est réservé aux acheteurs — si on s'y retrouve
  // (fermeture d'une fenêtre en glissement, etc.) alors qu'un autre rôle
  // était actif, on corrige ici même, sans passer par switchRole() pour
  // éviter un second appel à render() en pleine exécution de celui-ci.
  if (state.view === "market" && state.profile && state.profile.role && state.profile.role !== "acheteur") {
    state.profile.role = "acheteur";
    for (var _rmi = 0; _rmi < state.accounts.length; _rmi++) {
      if (state.accounts[_rmi].id === state.profile.id) { state.accounts[_rmi].role = "acheteur"; break; }
    }
    save();
    saveDoc("accounts", state.profile);
  }
  document.body.dataset.theme = getThemeConfig();
  document.body.classList.toggle("dark-mode", !!state.darkMode);
  // Le centre de contrôle admin a son propre fond toujours sombre — sans
  // ça, s'il y a moins de contenu qu'un écran plein, le fond clair de
  // l'app apparaît en dessous (le conteneur ne recouvre alors pas toute
  // la hauteur réelle de la page).
  document.body.classList.toggle("mc-admin-active", state.view === "admin" && state.adminUnlocked);
  applyBgPattern();
  applyScaleMotif();
  var active = document.activeElement;
  var activeId = active ? active.id : null;
  var selStart = active && "selectionStart" in active ? active.selectionStart : null;
  var selEnd = active && "selectionEnd" in active ? active.selectionEnd : null;
  var pageScrollY = window.scrollY;
  var modalSheet = document.querySelector(".modal-sheet");
  var modalScrollTop = modalSheet ? modalSheet.scrollTop : null;
  var liveVideo = document.getElementById("product-detail-video");
  var videoState = null;
  if (liveVideo) {
    videoState = { src: liveVideo.dataset.src, time: liveVideo.currentTime, paused: liveVideo.paused };
  }

  try {
    // Idiomorph : ne change dans le DOM que ce qui a réellement changé,
    // au lieu de tout détruire et reconstruire à chaque action — un
    // vrai gain de fluidité, surtout sur les écrans chargés (marché,
    // listes admin). Repli automatique sur l'ancien comportement si la
    // bibliothèque n'a pas pu charger (réseau capricieux), pour ne
    // jamais bloquer l'app à cause de ça.
    var newHtml = buildHTML();
    if (window.Idiomorph) {
      Idiomorph.morph(root, newHtml, { morphStyle: "innerHTML", callbacks: { beforeNodeMorphed: function(oldNode) { return !(oldNode.nodeType === 1 && oldNode.getAttribute && oldNode.getAttribute("data-sns3d-state")); } } });
    } else {
      root.innerHTML = newHtml;
    }
    applyEmployeeRestrictions();
    renderPendingQRCodes();
    observeVisibilityAnimations();
    if (window.snsMount3D) { try { window.snsMount3D(); } catch (e3d) {} }
    renderPendingStorageReport();
    if (state.showScannerModal && !window._scannerActive) {
      window._scannerActive = true;
      startScanner();
    } else if (!state.showScannerModal && window._scannerActive) {
      window._scannerActive = false;
      stopScanner();
    }
    if (window.__bootDone && typeof _splashFinished !== "undefined" && _splashFinished && !window._bootDoneMarked) { window._bootDoneMarked = true; window.__bootDone(); }
  } catch (err) {
    if (window.__bootMark) window.__bootMark("❌ erreur d'affichage : " + (err && err.message));
    window._handlingRenderError = true;
    setTimeout(function() { window._handlingRenderError = false; }, 0);
    console.error("Erreur de rendu :", err);
    var detail = (err && err.message) ? err.message : String(err);
    // Où exactement ça plante : les premières lignes de la pile d'appels
    // (noms des fonctions + numéros de ligne), pour pouvoir corriger la
    // vraie cause au lieu de deviner.
    var stackLines = (err && err.stack ? String(err.stack) : "").split("\n").slice(1, 7).map(function(l) {
      return l.trim().replace(/\(?(https?|file|capacitor):\/\/[^)]*?(:\d+:\d+)\)?$/, "$2").replace(/^at /, "");
    }).join("\n");
    window._lastRenderError = "Erreur : " + detail + "\nVue : " + state.view + " · Connecté : " + (state.profile ? state.profile.role : "non") + "\n" + stackLines;
    try { pushDebugLog("error", "Erreur d'affichage : " + detail, stackLines); } catch (e2) {}
    var showDiag = false;
    try { showDiag = diagnosticsEnabled(); } catch (eD) {}
    root.innerHTML = '<div style="padding:60px 24px;text-align:center;color:#1a1a2e">' +
      '<div style="font-size:34px;margin-bottom:12px">⚠️</div>' +
      '<div style="font-weight:800;font-size:16px;margin-bottom:6px">Un problème est survenu</div>' +
      (showDiag ? '<div style="font-size:11px;color:#666;margin-bottom:12px;font-family:monospace;word-break:break-word;white-space:pre-wrap;text-align:left;background:#f4f4f4;border-radius:8px;padding:10px;">' + esc(window._lastRenderError) + '</div>' +
      '<button id="copy-render-error-btn" style="background:#1a1a2e;color:white;border:none;padding:10px 18px;border-radius:12px;font-weight:700;font-size:13px;margin:0 4px 8px;">Copier l\'erreur</button>' : '<div style="font-size:13px;color:#666;margin-bottom:16px;">Revenez au marché pour continuer. Si le problème persiste, contactez l\'administration.</div>') +
      '<button id="back-market-btn" style="background:white;color:#1a1a2e;border:1.5px solid #1a1a2e;padding:10px 18px;border-radius:12px;font-weight:700;font-size:13px;margin:0 4px 8px;">Retour au marché</button><br/>' +
      (showDiag ? '<button id="reset-app-btn" style="background:#7bcb3a;color:white;border:none;padding:12px 22px;border-radius:12px;font-weight:700;font-size:13.5px;margin-bottom:8px;">Réinitialiser les données locales</button>' : '') +
      '</div>';
    var copyErrBtn = document.getElementById("copy-render-error-btn");
    if (copyErrBtn) copyErrBtn.addEventListener("click", function() {
      copyTextToClipboard(window._lastRenderError || detail).then(function(ok) { copyErrBtn.textContent = ok ? "✅ Copié" : "Impossible de copier"; });
    });
    var backBtn = document.getElementById("back-market-btn");
    if (backBtn) backBtn.addEventListener("click", function() {
      state.view = "market"; state.detailProductId = null; state.showFilterPanel = false;
      render();
    });
    var resetBtn = document.getElementById("reset-app-btn");
    if (resetBtn) resetBtn.addEventListener("click", function() { localStorage.removeItem(STORAGE_KEY); location.reload(); });
    return;
  }
  

  if (activeId) {
    var el = document.getElementById(activeId);
    if (el) {
      el.focus();
      if (selStart !== null && el.setSelectionRange) {
        try { el.setSelectionRange(selStart, selEnd); } catch(e) {}
      }
    }
  }
  if (!window._skipScrollRestore) {
    window.scrollTo(0, pageScrollY);
  }
  var liveHeader = document.querySelector('.gems-header');
  if (liveHeader) {
    var mainEl = document.querySelector('main');
    if (mainEl) mainEl.style.paddingTop = (liveHeader.offsetHeight + 14) + 'px';
  }
  var newModalSheet = document.querySelector(".modal-sheet");
  if (newModalSheet) {
    // Ne pas restaurer l'ancienne position ne suffit pas à elle seule à
    // repartir en haut — Idiomorph réutilise le même élément, qui garde
    // sinon sa position de défilement précédente telle quelle. On la
    // remet donc explicitement à zéro dans ce cas.
    newModalSheet.scrollTop = (window._skipScrollRestore || modalScrollTop === null) ? 0 : modalScrollTop;
  }
  window._skipScrollRestore = false;
  if (videoState) {
    var newVideo = document.getElementById("product-detail-video");
    if (newVideo && newVideo.dataset.src === videoState.src) {
      newVideo.currentTime = videoState.time;
      if (!videoState.paused) { var vp = newVideo.play(); if (vp && vp.catch) vp.catch(function() {}); }
    }
  }
  syncHistoryForNav();
  document.querySelectorAll(".frame-editor-box").forEach(function(box) {
    paintFrameEditor(box.dataset.config);
  });
  setupMarketInfiniteScroll();
  setupPdMarketScroll();
  
  applyMarketFxClass();
  if (state.seasonalEffects.enabled && state.view !== "onboarding") {
    var effectsRunning = document.querySelectorAll('.snowflake, .heart-float, .firework, .mali-flag-float').length > 0;
    if (!effectsRunning) {
      startSeasonalEffects(state.seasonalEffects.effect);
    }
  }

  if (window._pendingRelaisMap) {
    var pm = window._pendingRelaisMap;
    window._pendingRelaisMap = null;
    setTimeout(function() {
      if (!document.getElementById('relais-map')) return;
      var shopMarker = [{ lat: pm.shop.shopLat, lng: pm.shop.shopLng, label: '🏪 Vous pouvez retirer votre article ici dans cette boutique "' + esc(pm.shop.shopName || pm.shop.name) + '"' }];
      var mapInstance = renderMap('relais-map', pm.lat, pm.lng, '📍 Vous êtes ici', shopMarker);
      window._activeLeafletMap = mapInstance;      // La carte est créée tout de suite (pour rester visible même si
      // d'autres rafraîchissements de l'écran s'enchaînent) ; on corrige
      // seulement sa TAILLE une fois l'animation d'ouverture de la fenêtre
      // terminée (0.3s), au cas où elle se serait mal mesurée pendant que
      // le cadre était encore en train de glisser vers le haut.
      if (mapInstance) {
        setTimeout(function() {
          try { mapInstance.invalidateSize(); } catch (e) {}
        }, 320);
      }
    }, 0);
  }

  if (window._pendingOrderRelaisMap) {
    var pom = window._pendingOrderRelaisMap;
    window._pendingOrderRelaisMap = null;
    setTimeout(function() {
      if (!document.getElementById('order-relais-map')) return;
      var mapInstance2 = renderMap('order-relais-map', pom.lat, pom.lng, '🏪 ' + esc(pom.label));
      if (mapInstance2) {
        setTimeout(function() {
          try { mapInstance2.invalidateSize(); } catch (e) {}
        }, 320);
      }
    }, 0);
  }

  if (state.showLocationPicker) {
    setTimeout(mountLocationPickerMap, 0);
  }
}

function renderBoostDebugPanel() {
  var html = '<div style="padding:16px;font-family:monospace;font-size:12px;line-height:1.6;background:#fff;min-height:100vh;">';
  html += '<div style="font-size:16px;font-weight:800;margin-bottom:14px;">🔍 Diagnostic articles boostés</div>';

  html += '<div style="background:#eee;padding:10px;border-radius:8px;margin-bottom:12px;">';
  html += '<b>État général</b><br>';
  html += 'Produits chargés (state.products) : <b>' + state.products.length + '</b><br>';
  html += 'Boosts chargés (state.boosts) : <b>' + state.boosts.length + '</b><br>';
  html += 'Catégorie active : <b>' + esc(state.category) + '</b><br>';
  html += 'Recherche active : <b>"' + esc(state.search) + '"</b><br>';
  html += 'Tri actif (marketFilters.sortBy) : <b>' + esc(state.marketFilters.sortBy) + '</b><br>';
  html += 'Filtre boutique : <b>' + (state.shopFilterSellerId || 'aucun') + '</b><br>';
  html += 'Filtre secteur : <b>' + (state.sectorFilter || 'aucun') + '</b><br>';
  html += 'En stock uniquement : <b>' + state.marketFilters.inStockOnly + '</b><br>';
  html += 'En promo uniquement : <b>' + state.marketFilters.onSaleOnly + '</b><br>';
  html += 'Prix min/max : <b>' + (state.marketFilters.priceMin || '-') + ' / ' + (state.marketFilters.priceMax || '-') + '</b>';
  html += '</div>';

  html += '<div style="background:#eee;padding:10px;border-radius:8px;margin-bottom:12px;">';
  html += '<b>Tous les boosts trouvés</b><br>';
  if (state.boosts.length === 0) {
    html += '<span style="color:#c0272d;">Aucun boost du tout dans state.boosts !</span>';
  }
  for (var i = 0; i < state.boosts.length; i++) {
    var b = state.boosts[i];
    var active = isBoostActive(b);
    html += '<div style="margin-top:8px;padding-top:8px;border-top:1px dashed #999;">';
    html += 'Cible : ' + b.targetType + ' → ' + b.targetId + '<br>';
    html += 'Statut : ' + esc(b.status) + (b.status === "actif" ? ' ✅' : ' ❌ (pas "actif")') + '<br>';
    html += 'Expire : ' + (b.expiresAt ? new Date(b.expiresAt).toLocaleString('fr-FR') + (b.expiresAt > Date.now() ? ' ✅' : ' ❌ EXPIRÉ') : '<span style="color:#c0272d;">aucune date !</span>') + '<br>';
    html += '<b>isBoostActive() : ' + (active ? '✅ true' : '❌ false') + '</b><br>';
    var prodInState = null;
    for (var j = 0; j < state.products.length; j++) { if (state.products[j].id === b.targetId) { prodInState = state.products[j]; break; } }
    html += 'Produit chargé localement (state.products) : ' + (prodInState ? '✅ oui — "' + esc(prodInState.name) + '"' : '❌ NON, absent de state.products') + '<br>';
    if (prodInState) {
      html += 'isProductBoosted() pour ce produit : ' + (isProductBoosted(prodInState) ? '✅ true' : '❌ false') + '<br>';
    }
    html += '</div>';
  }
  html += '</div>';

  html += '<div style="background:#eee;padding:10px;border-radius:8px;margin-bottom:12px;">';
  html += '<b>Résultat de filteredProducts() (ce que le Marché utilise vraiment)</b><br>';
  try {
    var filtered = filteredProducts(true);
    html += 'Nombre total après filtre : <b>' + filtered.length + '</b><br>';
    for (var k = 0; k < state.boosts.length; k++) {
      var bb = state.boosts[k];
      if (bb.targetType === "product") {
        var pos = -1;
        for (var m = 0; m < filtered.length; m++) { if (filtered[m].id === bb.targetId) { pos = m; break; } }
        html += 'Position de "' + bb.targetId + '" dans la liste finale : ' + (pos === -1 ? '<span style="color:#c0272d;">❌ ABSENT de la liste finale</span>' : '<span style="color:#1a7d1a;">✅ position ' + pos + '</span>') + '<br>';
      }
    }
  } catch (e) {
    html += '<span style="color:#c0272d;">❌ ERREUR pendant filteredProducts() : ' + esc(e.message) + '</span>';
  }
  html += '</div>';

  html += '<div style="font-size:11px;color:#666;margin-top:20px;">Fais une capture de TOUTE cette page (défile si besoin) et envoie-la.</div>';
  html += '</div>';
  return html;
}

function buildHTML() {
  // Panneau de diagnostic temporaire — accessible en ajoutant #debugboost
  // à la fin de l'adresse, pour voir EXACTEMENT ce que l'app voit sur CET
  // appareil précis (au lieu de deviner depuis un environnement de test
  // séparé qui ne peut pas reproduire les vraies données).
  if (window.location.hash === "#debugboost" && diagnosticsEnabled()) {
    return renderBoostDebugPanel();
  }
  // Fiche publique d'un Point de Retrait — consultable via un lien sans compte
  // ni connexion, envoyé par SMS au destinataire d'un colis. Vérifié en
  // tout premier, avant même d'exiger un profil.
  if (window.location.hash.indexOf("#relais=") === 0) {
    return renderPublicRelaisPage(window.location.hash.slice("#relais=".length));
  }
  // Fiche publique d'une cagnotte — consultable via un lien partagé, même
  // sans être connecté (mais il faut un compte pour cotiser).
  if (window.location.hash.indexOf("#cagnotte=") === 0 && !state.profile) {
    return renderPublicCagnottePage(window.location.hash.slice("#cagnotte=".length));
  }
  if (window.location.hash === "#diag" && (diagnosticsEnabled() || (state.adminUnlocked))) {
    return renderPublicDiagnosticPage();
  }
  if (window.location.hash === "#partner-dashboard") {
    return renderPartnerDashboard();
  }
  if (state.forcePreviewIntro) return renderOnboardingIntro();
  if (!state.profile) {
    // Site web : le visiteur voit directement les articles (mode visiteur),
    // après avoir choisi sa langue lors de son tout premier passage.
    if (guestModeAllowed() && !state.guestAuthRequested) {
      var guestLangChosen = false;
      try { guestLangChosen = !!localStorage.getItem("sounsouni_language"); } catch (e) { guestLangChosen = true; }
      if (!guestLangChosen && !state.forceSkipLanguagePicker) return renderLanguagePickerGate();
      // Puis la présentation (storyboard), au premier passage seulement.
      if (!state.introSeen) return renderOnboardingIntro();
      return renderGuestShell();
    }
    // Visiteur du site qui a demandé à se connecter : directement le
    // formulaire (sans choix de langue ni présentation), avec un bouton
    // pour revenir aux articles.
    if (guestModeAllowed() && state.guestAuthRequested) {
      return renderOnboarding() + '<button type="button" data-action="guest-back-to-browsing" style="position:fixed;top:calc(10px + env(safe-area-inset-top, 0px));left:10px;z-index:9999;background:rgba(255,255,255,0.95);border:1px solid var(--border-color);border-radius:999px;padding:7px 12px;font-size:12px;font-weight:700;color:var(--text-primary, #222);box-shadow:0 2px 8px rgba(0,0,0,0.12);"><i class="fa-solid fa-arrow-left"></i> ' + t("guest_back") + '</button>';
    }
    // Choix explicite de la langue, une seule fois par appareil — avant
    // même la détection automatique basée sur la langue du téléphone.
    // localStorage("sounsouni_language") n'est écrit QUE par setLanguage(),
    // donc son absence signifie "jamais choisi sur cet appareil", peu
    // importe depuis quand l'app y est installée.
    var languageAlreadyChosen = false;
    try { languageAlreadyChosen = !!localStorage.getItem("sounsouni_language"); } catch (e) { languageAlreadyChosen = true; }
    if (!languageAlreadyChosen && !state.forceSkipLanguagePicker) return renderLanguagePickerGate();
    if (!state.introSeen) return renderOnboardingIntro();
    return renderOnboarding();
  }
  // Juste après une connexion depuis le mode visiteur : le panier rempli
  // sans compte est rattaché au compte, et si la personne voulait payer,
  // elle arrive directement à l'étape de paiement.
  if (state.guestAuthRequested || state.guestPendingCheckout || state.cart.some(function(it) { return it.buyerId === "guest"; })) {
    for (var gci = 0; gci < state.cart.length; gci++) {
      if (state.cart[gci].buyerId === "guest") state.cart[gci].buyerId = state.profile.id;
    }
    // Tout compte peut acheter (acheteur, mais aussi un vendeur qui se
    // connecte avec son compte) : on reprend là où le visiteur s'était
    // arrêté — la commande de son article, sinon la fiche de l'article.
    var guestGoCheckout = state.guestPendingCheckout && state.profile.role !== "admin" && cartCount() > 0;
    var guestBackProduct = !guestGoCheckout && state.guestReturnProductId && findProductById(state.guestReturnProductId) ? state.guestReturnProductId : null;
    state.guestAuthRequested = false;
    state.guestPendingCheckout = false;
    state.showGuestAuthPrompt = false;
    state.guestReturnProductId = null;
    if (guestGoCheckout || guestBackProduct) {
      state.showVendorHub = false; state.showRoleMenu = false; state.showProfileScreen = false;
      // Le guide de découverte attendra : la personne est en train d'acheter.
      if (state.activeTour && state.activeTour.tourKey === "decouvrir") state.activeTour = null;
    }
    if (guestGoCheckout) { state.view = "checkout"; state.detailProductId = null; }
    else if (guestBackProduct) { state.view = "market"; state.detailProductId = guestBackProduct; }
    save();
  }
  if (state.view === "onboarding") return renderOnboarding();
  // Le centre de contrôle admin a sa propre barre supérieure dédiée
  // (SOUNSOUNI · CENTRE DE CONTRÔLE) — l'en-tête classique de l'app
  // (bannière, menu, notifications...) ne doit jamais s'afficher par-dessus.
  var html = state.view === "admin" ? '' : renderHeader();
  if (state.pendingSyncQueue && state.pendingSyncQueue.length > 0 && state.view !== "admin") {
    html += '<div style="background:#fff3cd;color:#856404;font-size:11.5px;font-weight:700;text-align:center;padding:6px 12px;"><i class="fa-solid fa-cloud-arrow-up"></i> ' + state.pendingSyncQueue.length + ' modification(s) en attente de connexion — seront envoyées automatiquement.</div>';
  }
  html += '<main>';
  // Quand une fenêtre couvre tout l'écran par-dessus (profil, menu,
  // fiche produit, notifications...), l'écran du dessous ne se voit plus
  // du tout — inutile de payer le coût de le reconstruire en entier
  // (potentiellement des dizaines de cartes produit) juste pour qu'il
  // reste caché derrière. On ne le refait que si aucune de ces fenêtres
  // n'est ouverte.
  var heavyModalOpen = !!(state.detailProductId || state.showProfileScreen || state.showRoleMenu ||
    state.showVendorHub || state.showNotifPanel || state.showAdminGate || state.showScannerModal ||
    state.adminOrderDetailId || state.adminParcelDetailId || state.showSellerTypeModal);
  if (heavyModalOpen && state._lastMainHTML) {
    html += state._lastMainHTML;
  } else {
    var mainHtml = '';
    if (state.view === "market") mainHtml += renderMarket();
    else if (state.view === "categoryPage") mainHtml += renderCategoryPage();
    else if (state.view === "searchPage") mainHtml += renderSearchPage();
    else if (state.view === "shop") mainHtml += renderShopPage();
    else if (state.view === "favorites") mainHtml += renderFavorites();
    else if (state.view === "cart") mainHtml += renderCart();
    else if (state.view === "checkout") mainHtml += renderCheckout();
    else if (state.view === "payment") mainHtml += renderPayment();
    else if (state.view === "orders") mainHtml += renderOrders();
    else if (state.view === "sellerProfileSetup") mainHtml += renderSellerProfileSetup();
    else if (state.view === "seller") mainHtml += renderSeller();
    else if (state.view === "livreur") mainHtml += renderLivreur();
    else if (state.view === "agentsourcing") mainHtml += renderAgentSourcing();
    else if (state.view === "pointvente") mainHtml += renderPointVente();
    else if (state.view === "externalParcels") mainHtml += renderExternalParcelsScreen();
    else if (state.view === "relaisEditInfo") mainHtml += renderRelaisEditInfo();
    else if (state.view === "shopCustomize") mainHtml += renderShopCustomize();
    else if (state.view === "relaisPolicy") mainHtml += renderRelaisPolicy();
    else if (state.view === "relaisPolicyView") mainHtml += renderRelaisPolicyStandalone();
    else if (state.view === "sellerPolicyView") mainHtml += renderSellerPolicyStandalone();
    else if (state.view === "becomeRelais") mainHtml += renderBecomeRelais();
    else if (state.view === "admin") mainHtml += renderAdmin();
    state._lastMainHTML = mainHtml;
    html += mainHtml;
  }
  html += '</main>';
  if (state.profile.role === "acheteur" && state.view !== "searchPage" && state.view !== "admin") html += renderBottomNav();
  if (state.detailProductId) html += renderProductModal();
  if (state.adminOrderDetailId) html += renderAdminOrderModal();
  if (state.showAdminGate) html += renderAdminGateModal();
  if (state.showScannerModal) html += renderScannerModal();
  if (state.adminParcelDetailId) html += renderAdminParcelDetailModal();
  if (state.showNotifPanel) html += renderNotifPanel();
  if (state.showRoleMenu) html += renderRoleMenuModal();
  if (state.showVendorHub) html += renderVendorHubModal();
  if (state.showProfileScreen) html += renderProfileModal();
  html += renderContractGate();
  html += renderReconnectSheet();
  if (state.showSellerTypeModal) html += renderSellerTypeModal();
  if (state.showSellerSectorModal) html += renderSellerSectorModal();
  if (state.showBoostModal) html += renderBoostModal();
  if (state.showAdminProductEdit) html += renderAdminProductEditModal();
  if (state.colorPriceEdit) html += renderColorPricesModal();
  if (state.showAdminOrdersList) html += renderAdminOrdersListModal();
  if (state.showAdminProductsList) html += renderAdminProductsListModal();
  if (state.showLivreurRefuseModal) html += renderLivreurRefuseModal();
  if (state.adminViewingConversationId) html += renderAdminConversationViewModal();
  if (state.showProfileInfoModal) html += renderProfileInfoModal();
  if (state.showUserTestPanel) html += renderUserTestPanel();
  if (state.reportProductId) html += renderReportProductModal();
  if (state.showHistoryModal) html += renderHistoryModal();
  if (state.showShopPicker) html += renderShopPickerModal();
  if (state.showAffiliateProgram) html += renderAffiliateProgramModal();
  if (state.showForgotPassword) html += renderForgotPasswordModal(); else forgotPasswordWasOpen = false;
  if (state.showUnlockAccount) html += renderUnlockAccountModal(); else unlockAccountWasOpen = false;
  if (state.showCommissionConfirm) html += renderCommissionConfirmModal();
  if (state.detailAgentOrderId) html += renderAgentOrderDetailModal();
  if (state.showRepereGate) html += renderRepereGateModal();
  if (state.showUserGuide) html += renderUserGuideModal();
  if (state.showWallet) html += renderWalletModal();
  if (state.showWalletTransfer) html += renderWalletTransferModal();
  if (state.walletTopup) html += renderWalletTopupModal();
  if (state.digitalBuy) html += renderDigitalBuyModal();
  if (state.digitalOpening || state.digitalBuying || state.digitalReady) html += renderDigitalReadyModal();
  if (state.showCagnottesList) html += renderCagnottesListModal();
  if (state.showCreateCagnotte) html += renderCreateCagnotteModal();
  if (state.cagnotteDetailId) html += renderCagnotteDetailModal();
  if (state.cagnotteContributeId) html += renderCagnotteContributeModal();
  if (state.showGiftCard) html += renderGiftCardModal();
  if (state.showCarte) html += renderSounsouniCarteModal();
  if (state.showChargePayment) html += renderChargePaymentModal();
  if (state.showPaymentCode) html += renderPaymentCodeModal();
  if (state.revealPasswordContext) html += renderRevealPasswordModal();
  if (state.showDiaspora) html += renderDiasporaModal();
  if (state.showLeavePublishConfirm) html += renderLeavePublishConfirmModal();
  if (state.showVendorConsentGate) html += renderVendorConsentGateModal();
  if (state.showAddressModal && state.addressDraft) html += renderAddressModal();
  if (state.showLocationPicker) html += renderLocationPickerModal();
  if (state.imagePositionEditorIndex !== null) html += renderImagePositionEditorModal();
  if (state.showEarnings) html += renderEarningsModal();
  if (state.showDeleteAccountConfirm) html += renderDeleteAccountConfirmModal();
  if (state.forgotPasswordResetAccountId !== null) html += renderForgotPasswordResetModal();
  if (state.showEmailRequiredModal) html += renderEmailRequiredModal();
  if (state.showDisputeModal) html += renderDisputeModal();
  if (state.showNonLivrableModal) html += renderNonLivrableModal();
  if (state.showPrivacyModal) html += renderPrivacyModal();
  if (state.showFilterPanel) html += renderFilterPanel();
  if (state.showNewArrivalsModal) html += renderNewArrivalsModal();
  if (state.showOrderRelaisMap) html += renderOrderRelaisMapModal();
  // Rendues en tout dernier, comme sensitiveConfirm plus bas : elles
  // peuvent être déclenchées depuis n'importe quelle fenêtre finance
  // (Portefeuille, Envoi d'argent, Bon cadeau, Cagnotte, achat...) et
  // doivent systématiquement s'afficher AU-DESSUS de celle-ci, jamais
  // cachées derrière (même bug que sensitiveConfirm, corrigé pareil).
  if (state.showCreatePasswordGate) html += renderCreatePasswordGateModal(); else createPasswordGateWasOpen = false;
  if (state.showRecoveryCodeReveal) html += renderRecoveryCodeRevealModal(); else recoveryCodeRevealWasOpen = false;
  // Toujours rendue en tout dernier parmi les fenêtres : elle peut être
  // déclenchée depuis plusieurs écrans finance différents (Portefeuille,
  // Envoi d'argent, Bon cadeau, Cagnotte...) et doit systématiquement
  // s'afficher AU-DESSUS de celui qui l'a ouverte, jamais caché derrière.
  if (state.showSensitiveConfirm) html += renderSensitiveConfirmModal(); else sensitiveConfirmWasOpen = false;
  if (state.showMascotHint && state.view === "market" && !state.activeTour) html += renderMascotHint();
  if (state.activeTour) html += renderTourOverlay();
  if (state.guideVideoKey) html += renderGuideVideoModal();
  if (state.ligdiChoose) html += renderLigdiChoose();
  if (state.ligdiWaiting && !state.ligdiResult) html += renderLigdiWaiting();
  if (state.ligdiOpening) html += renderLigdiOpening();
  if (state.ligdiChecking && !state.ligdiResult) html += renderLigdiChecking();
  if (state.ligdiResult) html += renderLigdiResultModal();
  if (state.toastMsg) html += '<div class="toast">' + esc(state.toastMsg) + '</div>';
  if (state.showDownloadNudge) html += renderDownloadNudge();
  if (state.lightboxOpen) html += renderLightbox();
  if (state.showDocPasswordModal) html += renderDocPasswordModal();
  if (state.showAppDownloadContact) html += renderAppDownloadContactModal();
  if (state.chatOpen) html += renderChatWidget();
  html += renderChatToggle();
  return html;
}

// ---------- SYNC HISTORY ----------
// (fusionnée dans syncHistoryForNav ci-dessus)
// ============================================================
// GEMS — Logique complète — PARTIE 6/6
// ============================================================

// ---------- RENDER ONBOARDING ----------
// ---------- FICHE PUBLIQUE POINT DE RETRAIT (sans compte, sans connexion) ----------
// Accessible via #relais=<id> — pour le destinataire d'un colis externe,
// qui n'a pas forcément de compte Sounsouni. Volontairement minimaliste :
// juste de quoi trouver le point de retrait, rien qui exige d'être connecté.
// ---------- TABLEAU DE BORD PARTENAIRE (Option 4 — accès partagé) ----------
// Connexion indépendante de tout le reste (ni compte Sounsouni, ni Admin)
// — juste les identifiants configurés en Admin Groupe 1. Lecture seule.
function renderPartnerDashboard() {
  var html = '<div style="min-height:100vh;background:var(--bg-body);padding:20px 16px;">';
  html += '<div style="text-align:center;margin-bottom:18px;font-weight:800;font-size:16px;">GE<span style="font-style:italic;font-weight:500;">market</span>S <span style="font-size:12px;font-weight:500;color:var(--text-dim);">— Espace partenaire</span></div>';

  var hasAnyEnabled = state.dashboardPartners.some(function(p) { return p.enabled; });
  if (!hasAnyEnabled) {
    html += '<div class="empty-state"><i class="fa-solid fa-lock"></i><div class="title">Cet accès n\'est pas activé pour le moment.</div></div></div>';
    return html;
  }

  if (!state.partnerDashboardUnlocked) {
    html += '<div class="glass-card" style="padding:18px;max-width:360px;margin:40px auto 0;">';
    html += '<label class="field-label" style="margin-top:0;">Nom d\'utilisateur</label>';
    html += '<input class="input" value="' + esc(state.partnerGateUser || '') + '" data-bind="partnerGateUser" placeholder="Nom d\'utilisateur" />';
    html += '<label class="field-label">Mot de passe</label>';
    html += '<div style="position:relative;"><input class="input" type="password" style="padding-right:44px;" value="' + esc(state.partnerGatePass || '') + '" data-bind="partnerGatePass" placeholder="Mot de passe" /><button type="button" class="pw-eye-btn" data-action="toggle-pw-visibility" style="position:absolute;right:6px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--text-dim);padding:8px;"><i class="fa-solid fa-eye"></i></button></div>';
    if (state.partnerGateError) html += '<div style="color:var(--danger);font-size:12px;font-weight:700;margin-top:8px;">' + esc(state.partnerGateError) + '</div>';
    html += '<button class="btn-primary" style="margin-top:16px;" data-action="submit-partner-gate"><i class="fa-solid fa-unlock"></i> Se connecter</button>';
    html += '</div></div>';
    return html;
  }

  var matchedPartner = state.dashboardPartners.find(function(p) { return p.id === state.partnerDashboardMatchedId; });
  var parcels = matchedPartner ? state.externalParcels.filter(function(p) { return p.platform === matchedPartner.platform; }) : [];
  html += '<div style="max-width:480px;margin:0 auto;">';
  if (matchedPartner) html += '<div style="font-size:12px;color:var(--text-dim);margin-bottom:4px;">Connecté en tant que ' + esc(matchedPartner.platform) + '</div>';
  html += '<div style="font-weight:800;font-size:15px;margin-bottom:12px;">Vos colis (' + parcels.length + ')</div>';
  if (parcels.length === 0) {
    html += '<div class="empty-state"><i class="fa-solid fa-box-open"></i><div class="title">Aucun colis enregistré pour l\'instant</div></div>';
  } else {
    for (var i = 0; i < parcels.length; i++) {
      var p = parcels[i];
      html += '<div class="glass-card" style="padding:12px;margin-bottom:10px;">';
      html += '<div style="display:flex;justify-content:space-between;font-weight:800;font-size:12.5px;"><span>' + esc(p.trackingNumber) + '</span><span class="status-pill">' + translateStatus(p.status) + '</span></div>';
      html += '<div style="font-size:11.5px;color:var(--text-dim);margin-top:2px;">' + esc(p.relaisShopName) + ' · ' + fmtDateTime(p.createdAt) + '</div>';
      html += '</div>';
    }
  }
  html += '<button class="link-btn" style="margin-top:10px;" data-action="logout-partner-dashboard">Se déconnecter</button>';
  html += '</div></div>';
  return html;
}

// Fiche publique d'une cagnotte, consultable sans compte — la cotisation,
// elle, exige de se connecter (l'argent doit toujours venir d'un vrai
// portefeuille identifié).
function renderPublicCagnottePage(cagnotteId) {
  var c = getCagnotte(cagnotteId);
  if (!c) {
    return '<div style="padding:60px 24px;text-align:center;"><div style="font-size:34px;margin-bottom:12px">🔍</div><div style="font-weight:800;font-size:16px;">Cagnotte introuvable</div></div>';
  }
  var pct = c.targetAmount ? Math.min(100, Math.round((c.balance / c.targetAmount) * 100)) : null;
  var html = '<div style="padding:24px 20px;max-width:480px;margin:0 auto;">';
  html += '<div style="text-align:center;margin-bottom:20px;"><img loading="lazy" src="' + SOUNSOUNI_BASKET_LOGO + '" style="width:56px;height:56px;border-radius:50%;" /></div>';
  html += '<div style="font-weight:800;font-size:20px;text-align:center;margin-bottom:4px;">' + esc(c.title) + '</div>';
  html += '<div style="font-size:12px;color:var(--text-dim);text-align:center;margin-bottom:16px;">Par ' + esc(c.creatorName) + '</div>';
  if (c.description) html += '<div style="font-size:13.5px;color:var(--text-secondary);margin-bottom:16px;line-height:1.5;text-align:center;">' + esc(c.description) + '</div>';
  html += '<div class="glass-card" style="padding:18px;text-align:center;margin-bottom:20px;background:linear-gradient(135deg,var(--primary),var(--accent));">';
  html += '<div style="font-size:26px;font-weight:800;color:white;">' + money(c.balance) + (c.targetAmount ? '<span style="font-size:14px;font-weight:600;"> / ' + money(c.targetAmount) + '</span>' : '') + '</div>';
  if (pct != null) {
    html += '<div style="height:8px;background:rgba(255,255,255,0.3);border-radius:99px;margin-top:10px;overflow:hidden;"><div style="height:100%;width:' + pct + '%;background:white;border-radius:99px;"></div></div>';
    html += '<div style="font-size:11px;color:rgba(255,255,255,0.85);margin-top:6px;">' + pct + '% atteint</div>';
  }
  html += '</div>';
  html += '<div style="font-size:13px;color:var(--text-dim);text-align:center;margin-bottom:16px;">Connectez-vous sur Sounsouni pour cotiser à cette cagnotte.</div>';
  html += '<button class="btn-primary" style="width:100%;" data-action="go-to-login-for-cagnotte">' + t("open_sounsouni") + '</button>';
  html += '</div>';
  return html;
}

function renderPublicRelaisPage(relaisId) {
  var account = null;
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === relaisId) { account = state.accounts[i]; break; }
  }
  var html = '<div style="min-height:100vh;background:var(--bg-body);padding:20px 16px;font-family:inherit;">';
  html += '<div style="text-align:center;margin-bottom:18px;">';
  html += '<div style="display:inline-flex;align-items:center;gap:6px;font-weight:800;font-size:16px;color:var(--text-primary);">Sounsouni</div>';
  html += '</div>';

  if (!account || account.relaisApplicationStatus !== "approved") {
    html += '<div class="empty-state"><i class="fa-solid fa-shop-slash"></i><div class="title">Ce Point de Retrait est introuvable</div></div>';
    html += '</div>';
    return html;
  }

  html += '<div class="glass-card" style="padding:18px;max-width:420px;margin:0 auto;">';
  if (account.shopCoverPhoto) {
    html += '<div style="width:100%;height:100px;border-radius:12px;overflow:hidden;margin-bottom:-32px;"><img loading="lazy" src="' + account.shopCoverPhoto + '" style="width:100%;height:100%;object-fit:cover;" /></div>';
  }
  if (account.shopProfilePhoto) {
    html += '<img loading="lazy" src="' + account.shopProfilePhoto + '" style="width:60px;height:60px;border-radius:50%;object-fit:cover;display:block;margin:0 auto 10px;border:3px solid var(--bg-card);position:relative;" />';
  } else {
    html += '<div class="emoji-thumb" style="width:60px;height:60px;font-size:24px;margin:0 auto 10px;position:relative;border:3px solid var(--bg-card);"><i class="fa-solid fa-shop"></i></div>';
  }
  html += '<div style="font-weight:800;font-size:17px;text-align:center;">' + esc(account.shopName || account.name) + '</div>';
  html += '<div style="font-size:12px;color:var(--text-dim);text-align:center;margin-top:2px;">Point de Retrait Sounsouni</div>';

  html += '<div style="background:var(--bg-body);border-radius:10px;padding:12px;margin-top:16px;">';
  html += '<div style="font-size:11px;font-weight:800;color:var(--text-dim);margin-bottom:4px;"><i class="fa-solid fa-location-dot"></i> Adresse</div>';
  html += '<div style="font-size:13px;">' + esc(account.commune || '') + (account.quartier ? ' — ' + esc(account.quartier) : '') + '</div>';
  if (account.addressDetail) html += '<div style="font-size:12.5px;color:var(--text-dim);margin-top:2px;">' + esc(account.addressDetail) + '</div>';
  html += '</div>';

  if (account.shopLat != null && account.shopLng != null) {
    html += '<a href="https://www.google.com/maps/search/?api=1&query=' + account.shopLat + ',' + account.shopLng + '" target="_blank" class="btn-primary" style="display:block;text-align:center;margin-top:14px;text-decoration:none;"><i class="fa-solid fa-map-location-dot"></i> Ouvrir dans Google Maps</a>';
  }
  html += '<div style="font-size:11px;color:var(--text-dim);text-align:center;margin-top:16px;">Vous avez un colis à récupérer ici — présentez le code de retrait reçu par SMS.</div>';
  html += '</div></div>';
  return html;
}

// Introduction en 3 pages, montrée une seule fois par appareil, avant le
// formulaire d'inscription — illustrations à base d'icônes (pas d'images
// personnalisées disponibles pour l'instant).
var ONBOARD_INTRO_PAGES_BY_LANG = {
  fr: [
    { img: 'SOUNSOUNI_INTRO_IMG_1', title: 'Achetez partout au Mali', text: 'Des milliers de produits livrés directement chez vous, où que vous soyez.' },
    { img: 'SOUNSOUNI_INTRO_IMG_2', title: 'Des milliers de vendeurs locaux', text: 'Particuliers, boutiques, restaurants — tout Bamako et bien au-delà, réunis au même endroit.' },
    { img: 'SOUNSOUNI_INTRO_IMG_3', title: 'Livraison rapide et sécurisée', text: 'Suivez votre commande en temps réel, du dépôt jusqu\'à votre porte.' }
  ],
  en: [
    { img: 'SOUNSOUNI_INTRO_IMG_1', title: 'Shop anywhere in Mali', text: 'Thousands of products delivered straight to you, wherever you are.' },
    { img: 'SOUNSOUNI_INTRO_IMG_2', title: 'Thousands of local sellers', text: 'Individuals, shops, restaurants — all of Bamako and beyond, gathered in one place.' },
    { img: 'SOUNSOUNI_INTRO_IMG_3', title: 'Fast and secure delivery', text: 'Track your order in real time, from drop-off to your door.' }
  ],
  hi: [
    { img: 'SOUNSOUNI_INTRO_IMG_1', title: 'माली में कहीं भी खरीदारी करें', text: 'हज़ारों उत्पाद सीधे आपके पास पहुंचाए जाते हैं, आप जहां भी हों।' },
    { img: 'SOUNSOUNI_INTRO_IMG_2', title: 'हज़ारों स्थानीय विक्रेता', text: 'व्यक्ति, दुकानें, रेस्तरां — पूरा बमाको और उससे भी आगे, एक ही जगह पर।' },
    { img: 'SOUNSOUNI_INTRO_IMG_3', title: 'तेज़ और सुरक्षित डिलीवरी', text: 'अपने ऑर्डर को वास्तविक समय में ट्रैक करें, भेजने से लेकर आपके दरवाज़े तक।' }
  ],
};
var ONBOARD_INTRO_PAGES = ONBOARD_INTRO_PAGES_BY_LANG.fr; // valeur de repli si jamais utilisée avant le premier rendu
var ONBOARD_INTRO_IMG_MAP = { SOUNSOUNI_INTRO_IMG_1: SOUNSOUNI_INTRO_IMG_1, SOUNSOUNI_INTRO_IMG_2: SOUNSOUNI_INTRO_IMG_2, SOUNSOUNI_INTRO_IMG_3: SOUNSOUNI_INTRO_IMG_3 };

// ---------- CHOIX EXPLICITE DE LA LANGUE (une seule fois, au tout premier
// lancement de l'app sur cet appareil) ----------
// Volontairement écrit dans les 3 langues à la fois sur chaque bouton — le
// nom d'une langue s'écrit toujours dans elle-même, jamais besoin de
// traduction pour "Français"/"English"/"हिंदी".
function renderLanguagePickerGate() {
  var html = '<div class="intro-wrap" style="justify-content:center;">';
  html += '<div style="text-align:center;margin-bottom:36px;">';
  html += '<img loading="lazy" src="' + SOUNSOUNI_HEADER_ICON + '" style="width:72px;height:72px;border-radius:20px;margin-bottom:16px;" alt="" />';
  html += '<div style="font-size:20px;font-weight:800;color:var(--accent);">Choisissez votre langue</div>';
  html += '<div style="font-size:14px;color:var(--text-dim);margin-top:2px;">Choose your language · अपनी भाषा चुनें</div>';
  html += '</div>';
  html += '<div style="display:flex;flex-direction:column;gap:14px;width:100%;max-width:320px;">';
  html += '<button type="button" class="btn-primary" style="padding:16px;font-size:17px;" data-action="pick-initial-language" data-value="fr">Français</button>';
  html += '<button type="button" class="btn-primary" style="padding:16px;font-size:17px;" data-action="pick-initial-language" data-value="en">English</button>';
  html += '<button type="button" class="btn-primary" style="padding:16px;font-size:17px;" data-action="pick-initial-language" data-value="hi">हिंदी</button>';
  html += '</div>';
  html += '</div>';
  return html;
}

function renderOnboardingIntro() {
  var pages = ONBOARD_INTRO_PAGES_BY_LANG[state.language] || ONBOARD_INTRO_PAGES_BY_LANG.fr;
  var step = state.introStep || 0;
  var page = pages[step];
  var isLast = step === pages.length - 1;
  var html = '<div class="intro-wrap">';
  html += '<button class="intro-skip" data-action="intro-finish">' + t("skip") + '</button>';
  html += '<div class="intro-photo-wrap"><img loading="lazy" src="' + ONBOARD_INTRO_IMG_MAP[page.img] + '" class="intro-photo" alt="" /></div>';
  html += '<div class="intro-title">' + esc(page.title) + '</div>';
  html += '<div class="intro-text">' + esc(page.text) + '</div>';
  html += '<div class="intro-dots">';
  for (var i = 0; i < pages.length; i++) {
    html += '<span class="intro-dot ' + (i === step ? 'active' : '') + '"></span>';
  }
  html += '</div>';
  html += '<button class="btn-primary intro-next-btn" data-action="' + (isLast ? 'intro-finish' : 'intro-next') + '">' + (isLast ? t("start") : t("next")) + ' <i class="fa-solid fa-arrow-right"></i></button>';
  html += '</div>';
  return html;
}

function renderOnboarding() {
  var mode = state.onboardMode || (state.accounts.length > 0 ? "list" : "form");
  var d = state.onboardDraft;
  var obwCfg = getBrandImageConfig("onboard_watermark_config");
  var obwImg = obwCfg.imageUrl || SOUGOUBA_BANNER_IMG;
  var cardBgStyle = '';
  var cardBgClass = '';
  if (obwCfg.enabled) {
    var topAlpha = Math.max(0, 1 - obwCfg.opacity * 0.6);
    var botAlpha = Math.max(0, 1 - obwCfg.opacity * 0.3);
    var overlayCss = obwCfg.overlayEnabled ? ('linear-gradient(rgba(255,255,255,' + topAlpha + '),rgba(255,255,255,' + botAlpha + ')),') : '';
    cardBgStyle = 'background-image:' + overlayCss + 'url(\'' + obwImg + '\');background-size:' + obwCfg.frameZoom + '%;background-position:' + obwCfg.framePosX + '% ' + obwCfg.framePosY + '%;background-repeat:no-repeat;';
    cardBgClass = ' brand-fx-' + obwCfg.effect;
  }
  var topBannerCfg = getBrandImageConfig("onboard_top_banner_config");
  var topBannerFrameStyle = 'height:' + topBannerCfg.frameHeight + 'px;background-image:url(\'' + SOUNSOUNI_REG_TOP_BANNER + '\');background-size:' + topBannerCfg.frameZoom + '%;background-position:' + topBannerCfg.framePosX + '% ' + topBannerCfg.framePosY + '%;background-repeat:no-repeat;';
  var header = '';

  if (mode === "list") {
    var accountsHtml = '';
    // Filtre les doublons d'ID avant affichage — une protection existe déjà
    // à la création pour ne plus jamais en créer, mais une vieille donnée
    // restée en mémoire d'avant cette protection ne doit plus jamais
    // s'afficher deux fois pour autant.
    var deviceIds = Array.from(new Set(state.deviceAccountIds || []));
    var visibleAccounts = state.accounts.filter(function(a) { return deviceIds.indexOf(a.id) !== -1; });
    // Filet de sécurité supplémentaire : même si ce sont deux comptes avec
    // des identifiants réellement différents, deux entrées strictement
    // identiques (même numéro, même rôle, même type) n'ont aucune raison
    // de s'afficher deux fois — on ne garde alors que la première.
    var seenAccountKeys = {};
    visibleAccounts = visibleAccounts.filter(function(a) {
      var accKey = a.phone + "|" + a.role + "|" + (a.sellerType || "");
      if (seenAccountKeys[accKey]) return false;
      seenAccountKeys[accKey] = true;
      return true;
    });
    for (var i = 0; i < visibleAccounts.length; i++) {
      var a = visibleAccounts[i];
      accountsHtml += '<button class="account-item" data-action="login-account" data-value="' + a.id + '">';
      accountsHtml += '<div class="account-avatar">' + esc(a.name.slice(0, 1).toUpperCase()) + '</div>';
      accountsHtml += '<div style="flex:1;text-align:left">';
      accountsHtml += '<div style="font-weight:700;font-size:14px">' + esc(a.name) + '</div>';
      accountsHtml += '<div style="font-size:11.5px;color:var(--text-dim)">' + esc(a.phone) + ' \u00b7 ' + translateRoleLabel(a.role) + '</div>';
      accountsHtml += '</div>';
      accountsHtml += '<i class="fa-solid fa-chevron-right" style="color:var(--text-dim)"></i>';
      accountsHtml += '</button>';
    }
    return '<div class="onboarding-wrap"><div class="onboarding-fixed-banner onboarding-fixed-banner-compact" style="' + topBannerFrameStyle + '"></div><div class="onboarding-card' + cardBgClass + '" style="' + cardBgStyle + '">' + header +
      '<label class="field-label">' + t("accounts_on_device") + '</label>' +
      '<div class="account-list">' + accountsHtml + '</div>' +
      '<button class="btn-secondary" style="margin-top:16px" data-action="show-onboard-form"><i class="fa-solid fa-plus"></i> ' + t("new_account") + '</button>' +
      '<button class="link-btn link-btn-standout" style="width:100%;text-align:center;margin-top:10px;" data-action="open-find-account"><i class="fa-solid fa-user-check"></i> ' + t("already_have_account") + '</button>' +
      '<button class="link-btn link-btn-standout" style="width:100%;text-align:center;margin-top:10px;" data-action="open-forgot-password"><i class="fa-solid fa-key"></i> ' + t("forgot_password") + '</button>' +
      '</div>' + renderLoginBrandBanner() + '</div>' +
      (state.showFindAccountModal ? renderFindAccountModal() : '') +
      (state.showForgotPassword ? renderForgotPasswordModal() : '') +
      (state.showUnlockAccount ? renderUnlockAccountModal() : '') +
      (state.toastMsg ? '<div class="toast">' + esc(state.toastMsg) + '</div>' : '');
  }

  var step = state.onboardStep || "identity";
  var bodyHtml = '';
  if (step === "identity") bodyHtml = renderOnboardStepIdentity(d);
  else if (step === "vendorType") bodyHtml = renderOnboardStepVendorType(d);
  else if (step === "restaurantDetails") bodyHtml = renderOnboardStepRestaurant(d);
  else if (step === "agriculteurDetails") bodyHtml = renderOnboardStepAgriculteur(d);
  else if (step === "sectorChoice") bodyHtml = renderOnboardStepSectorChoice(d);
  else if (step === "sectorDetails") bodyHtml = renderOnboardStepSectorDetails(d);
  else if (step === "internationalDetails") bodyHtml = renderOnboardStepInternational(d);
  else if (step === "relaisDetails") bodyHtml = renderOnboardStepRelais(d);
  else if (step === "commissionConsent") bodyHtml = renderOnboardStepCommissionConsent(d);
  else if (step === "prohibitedGoodsConsent") bodyHtml = renderOnboardStepProhibitedGoods(d);
  else bodyHtml = renderOnboardStepIdentity(d);

  var showHero = step === "identity";
  var heroHtml = '';
  if (showHero) {
    heroHtml += '<div class="onboarding-trust-row">';
    heroHtml += '<div class="trust-badge"><span class="trust-icon"><i class="fa-solid fa-bag-shopping"></i></span>' + t("trust_millions_products") + '</div>';
    heroHtml += '<div class="trust-badge"><span class="trust-icon"><i class="fa-solid fa-shield-halved"></i></span>' + t("trust_secure_payment") + '</div>';
    heroHtml += '<div class="trust-badge"><span class="trust-icon"><i class="fa-solid fa-truck-fast"></i></span>' + t("trust_delivery") + '</div>';
    heroHtml += '</div>';
    heroHtml += '<img loading="lazy" class="onboarding-hero-collage" src="' + SOUNSOUNI_ONBOARD_COLLAGE + '" alt="Sounsouni" />';
  }

  return '<div class="onboarding-wrap"><div class="onboarding-fixed-banner" style="' + topBannerFrameStyle + '"></div>' + heroHtml + '<div class="onboarding-card' + (showHero ? ' onboarding-card-overlap' : '') + cardBgClass + '" style="' + cardBgStyle + '">' + header +
    (state.accounts.length > 0 && step === "identity" ? (state.onboardDraft.isSecondAccountFlow ? '<button class="link-btn" style="margin-bottom:14px" data-action="onboard-back-step" data-value="vendorType"><i class="fa-solid fa-arrow-left"></i> Retour</button>' : '<button class="link-btn" style="margin-bottom:14px" data-action="show-onboard-list"><i class="fa-solid fa-arrow-left"></i> Comptes existants</button>') : '') +
    bodyHtml +
    '</div>' + renderLoginBrandBanner() + '</div>' +
    (state.showLocationPicker ? renderLocationPickerModal() : '') +
    (state.showFindAccountModal ? renderFindAccountModal() : '') +
    (state.showForgotPassword ? renderForgotPasswordModal() : '') +
    (state.showUnlockAccount ? renderUnlockAccountModal() : '') +
    (state.toastMsg ? '<div class="toast">' + esc(state.toastMsg) + '</div>' : '');
}

// ---------- \u00c9TAPE 1 : IDENTIT\u00c9 + CHOIX DU R\u00d4LE (commun \u00e0 tous) ----------
function renderOnboardStepIdentity(d) {
  markFormShown("inscription");
  var countryOptions = '';
  for (var k = 0; k < COUNTRY_CODES.length; k++) {
    var c = COUNTRY_CODES[k];
    countryOptions += '<option value="' + c.code + '" ' + (d.countryCode === c.code ? 'selected' : '') + '>' + c.label + '</option>';
  }
  var html = honeypotFieldHtml("onboardDraft") + '<label class="field-label">' + t("full_name") + '</label>' +
    '<div class="field-icon-group"><i class="fa-regular fa-user field-icon"></i><input id="ob-name" class="input" placeholder="' + t("full_name_placeholder") + '" value="' + esc(d.name) + '" data-bind="onboardDraft.name" /></div>' +
    '<label class="field-label">' + t("phone") + '</label>' +
    '<div class="phone-group">' +
    '<div class="field-icon-group" style="width:132px;flex-shrink:0;"><i class="fa-solid fa-phone field-icon"></i><select class="input" data-bind="onboardDraft.countryCode" style="width:100%;">' + countryOptions + '</select></div>' +
    '<input id="ob-phone" class="input" placeholder="' + t("phone_placeholder") + '" value="' + esc(d.phone) + '" data-bind="onboardDraft.phone" />' +
    '</div>' +
    '<label class="field-label">' + t("email_required") + '</label>' +
    '<div class="field-icon-group"><i class="fa-regular fa-envelope field-icon"></i><input id="ob-email" class="input" type="text" inputmode="email" autocomplete="email" placeholder="exemple@email.com" value="' + esc(d.email) + '" data-bind="onboardDraft.email" /></div>' +
    '<label class="field-label">' + t("here_for") + '</label>' +
    '<div class="role-cards">' +
    '<button class="role-card ' + (d.role === "acheteur" ? 'active' : '') + (d.isSecondAccountFlow ? ' locked' : '') + '" ' + (d.isSecondAccountFlow ? 'disabled' : 'data-action="set-onboard-role" data-value="acheteur"') + '><span class="role-card-icon"><i class="fa-solid fa-bag-shopping"></i></span>' + t("role_buy") + '</button>' +
    '<button class="role-card ' + (d.role === "vendeur" ? 'active' : '') + (d.isSecondAccountFlow ? ' locked' : '') + '" ' + (d.isSecondAccountFlow ? 'disabled' : 'data-action="set-onboard-role" data-value="vendeur"') + '><span class="role-card-icon"><i class="fa-solid fa-tag"></i></span>' + t("role_sell") + '</button>' +
    '<button class="role-card ' + (d.role === "point_vente" ? 'active' : '') + (d.isSecondAccountFlow ? ' locked' : '') + '" ' + (d.isSecondAccountFlow ? 'disabled' : 'data-action="set-onboard-role" data-value="point_vente"') + '><span class="role-card-icon"><i class="fa-solid fa-location-dot"></i></span>' + t("role_pickup_point") + '</button>' +
    '</div>' +
    (d.isSecondAccountFlow ? '<div style="font-size:10.5px;color:var(--text-dim);margin-top:6px;margin-bottom:4px;">Vous êtes déjà inscrit — ce parcours ne fait qu\'ajouter la casquette Vendeur à votre compte.</div>' : '');
  var isLastStep = d.role === "acheteur";
  html += '<button class="btn-primary" style="margin-top:22px" data-action="onboard-continue-identity">' + (isLastStep ? t("create_my_account") : t("continue")) + ' <i class="fa-solid fa-arrow-right"></i></button>';
  html += '<button class="link-btn link-btn-standout" style="width:100%;text-align:center;margin-top:14px;" data-action="open-find-account"><i class="fa-solid fa-user-check"></i> ' + t("already_have_account") + '</button>';
  html += '<button class="link-btn link-btn-standout" style="width:100%;text-align:center;margin-top:10px;" data-action="open-forgot-password"><i class="fa-solid fa-key"></i> ' + t("forgot_password") + '</button>';
  return html;
}

function renderFindAccountModal() {
  markFormShown("connexion");
  var d = state.findAccountDraft;
  var countryOptions = '';
  for (var k = 0; k < COUNTRY_CODES.length; k++) {
    var c = COUNTRY_CODES[k];
    countryOptions += '<option value="' + c.code + '" ' + (d.countryCode === c.code ? 'selected' : '') + '>' + c.label + '</option>';
  }
  var html = '<div class="modal-overlay" id="find-account-overlay" data-action="close-find-account">';
  html += '<div class="modal-sheet">';
  html += '<button class="modal-close" data-action="close-find-account"><i class="fa-solid fa-xmark"></i></button>';
  html += '<div class="section-title" style="margin-bottom:6px;"><i class="fa-solid fa-user-check"></i> ' + t("fa_title") + '</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:14px;">' + t("fa_explainer") + '</div>';
  html += '<label class="field-label" style="margin-top:0;">' + t("full_name") + '</label>';
  html += '<input class="input" placeholder="' + t("name_placeholder_generic") + '" value="' + esc(d.name) + '" data-bind="findAccountDraft.name" />';
  html += '<label class="field-label">' + t("phone") + '</label>';
  html += '<div class="phone-group">';
  html += '<select class="input" data-bind="findAccountDraft.countryCode" style="width:100px;flex-shrink:0;">' + countryOptions + '</select>';
  html += '<input class="input" placeholder="' + t("phone_placeholder_generic") + '" value="' + esc(d.phone) + '" data-bind="findAccountDraft.phone" />';
  html += '</div>';
  html += '<label class="field-label">' + t("fa_password_optional") + '</label>';
  html += '<div style="position:relative;"><input class="input" id="fa-password" type="password" style="padding-right:44px;" value="' + esc(d.password || '') + '" data-bind="findAccountDraft.password" /><button type="button" class="pw-eye-btn" data-action="toggle-pw-visibility" style="position:absolute;right:6px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--text-dim);padding:8px;"><i class="fa-solid fa-eye"></i></button></div>';
  html += '<button class="btn-primary" style="margin-top:18px;" data-action="attempt-find-account">' + t("find_my_account") + '</button>';
  html += '<button class="link-btn" style="width:100%;text-align:center;margin-top:12px;" data-action="open-forgot-password"><i class="fa-solid fa-circle-question"></i> ' + t("forgot_password") + '</button>';
  html += '</div></div>';
  html = honeypotFieldHtml("findAccountDraft") + html;
  return html;
}

// ---------- \u00c9TAPE 2 (Vendeur) : TYPE DE VENDEUR ----------
function renderOnboardStepVendorType(d) {
  // Venant du menu "Changer de rôle" (compte déjà existant), revenir en
  // arrière ne doit jamais ramener au formulaire d'inscription complet
  // (il n'y a pas d'étape "identité" dans ce parcours) — mais directement
  // là où la personne se trouvait avant, dans "Changer de rôle".
  var vtBackAction = d.isSecondAccountFlow
    ? ' data-action="cancel-onboard-to-role-menu"'
    : ' data-action="onboard-back-step" data-value="identity"';
  var html = '<button class="link-btn" style="margin-bottom:14px"' + vtBackAction + '><i class="fa-solid fa-arrow-left"></i> ' + t("relais_apply_back") + '</button>';
  // Même fond blanc opaque que l'étape "Vendeur International" juste après
  // — ce texte s'affichait directement sur la photo de fond de la carte
  // d'inscription, illisible par endroits selon la photo choisie.
  html += '<div style="background:rgba(255,255,255,0.94);border-radius:14px;padding:14px 16px;margin-bottom:10px;">';
  html += '<div class="section-title" style="margin-bottom:4px;font-weight:800;">' + t("vt_question") + '</div>';
  html += '<div style="font-size:11.5px;color:var(--text-primary);">' + t("vt_hint") + '</div>';
  html += '</div>';
  html += '<div style="display:flex;flex-direction:column;gap:10px;">';
  var types = [
    ["particulier", "fa-user", t("vt_particulier"), t("vt_particulier_sub")],
    ["restaurant", "fa-utensils", t("vt_restaurant"), t("vt_restaurant_sub")],
    ["agriculteur", "fa-seedling", t("vt_agriculteur"), t("vt_agriculteur_sub")],
    ["entreprise", "fa-building", t("vt_entreprise"), t("vt_entreprise_sub")],
    ["international", "fa-earth-asia", t("vt_international"), t("vt_international_sub")]
  ];
  // Les 4 premiers types supposent tous une présence physique en Afrique
  // de l'Ouest (commune/quartier, livraison locale) — les proposer à un
  // compte enregistré depuis un autre continent (ex : Inde) n'a aucun
  // sens et ne ferait que l'embrouiller. Un numéro sénégalais, ivoirien,
  // etc. reste "local" et garde les 5 options. Seul "Vendeur
  // International" reste pertinent pour un numéro hors Afrique.
  if (!isAfricanCountryCode(d.countryCode)) {
    types = types.filter(function(vt) { return vt[0] === "international"; });
  } else {
    // Inverse : un compte africain (Mali, Sénégal, etc.) n'a aucune
    // raison de voir "Vendeur International" — ce parcours (agent de
    // sourcing, MOQ, groupage) ne concerne que les comptes hors Afrique.
    types = types.filter(function(vt) { return vt[0] !== "international"; });
  }
  for (var vi = 0; vi < types.length; vi++) {
    var vt = types[vi];
    html += '<button type="button" class="vendor-hub-card" data-action="set-onboard-vendor-type" data-value="' + vt[0] + '">';
    html += '<i class="fa-solid ' + vt[1] + '"></i><div><div class="vh-title">' + vt[2] + '</div><div class="vh-sub">' + vt[3] + '</div></div><i class="fa-solid fa-chevron-right"></i>';
    html += '</button>';
  }
  html += '</div>';
  return html;
}

// ---------- \u00c9TAPE 3 (Restaurant / Traiteur) ----------
// ---------- ÉTAPE 3 (Vendeur International) ----------
// Pas de commune/quartier/GPS malien ici — ce vendeur n'a pas de présence
// physique au Mali. Son pays est déjà connu via l'indicatif téléphonique
// (voir countryForCode dans registerAccount). Le MOQ, le poids et le
// volume se règlent article par article, au moment de la publication.
function renderOnboardStepInternational(d) {
  var detectedCountry = countryForCode(d.countryCode || "+223");
  var agents = state.accounts.filter(function(a) { return a.isSourcingAgent; });
  // Un compte hors Afrique ne voit QUE cette option à l'étape précédente
  // (voir renderOnboardStepVendorType) — y revenir en arrière n'aurait
  // aucun intérêt (une seule carte à re-choisir) et prêterait à
  // confusion. On retourne donc directement au menu "Changer de rôle".
  var isForeignAccount = !isAfricanCountryCode(d.countryCode);
  var backAction = isForeignAccount
    ? ' data-action="cancel-onboard-to-role-menu"'
    : ' data-action="onboard-back-step" data-value="vendorType"';
  var html = '<button class="link-btn" style="margin-bottom:14px"' + backAction + '><i class="fa-solid fa-arrow-left"></i> ' + t("relais_apply_back") + '</button>';
  // Fond blanc opaque autour du texte de cette étape : contrairement à
  // l'étape précédente (des cartes blanches par nature), ce texte était
  // affiché à même la photo de fond de la carte d'inscription — illisible
  // par endroits selon la photo choisie. Renforcé en gras là où c'est le
  // plus important (titre, adresse à donner à l'agent).
  html += '<div style="background:rgba(255,255,255,0.94);border-radius:14px;padding:14px 16px;">';
  html += '<div class="section-title" style="margin-bottom:4px;font-weight:800;"><i class="fa-solid fa-earth-asia"></i> ' + t("intl_title") + '</div>';
  html += '<div style="font-size:11.5px;color:var(--text-primary);margin-bottom:16px;">' + t("intl_explainer") + '</div>';
  html += '<label class="field-label">' + t("intl_company_name") + '</label>';
  // Fond blanc pur + bordure plus marquée sur les champs eux-mêmes : sans
  // ça, ils se confondaient presque avec le fond blanc cassé ajouté
  // ci-dessus (à peine 2-3 nuances d'écart), rendant les champs difficiles
  // à distinguer du texte autour.
  html += '<input class="input" style="background:#ffffff;border-color:var(--text-dim);" placeholder="' + t("intl_company_placeholder") + '" value="' + esc(d.shopName || '') + '" data-bind="onboardDraft.shopName" />';
  html += '<div style="font-size:11px;color:var(--text-primary);margin-top:8px;"><i class="fa-solid fa-circle-info"></i> ' + t("intl_country_note") + '<strong>' + esc(detectedCountry) + '</strong></div>';
  html += '<label class="field-label">' + t("intl_shop_address_label") + '</label>';
  html += '<textarea class="input" style="background:#ffffff;border-color:var(--text-dim);" rows="2" placeholder="' + t("intl_shop_address_placeholder") + '" data-bind="onboardDraft.shopAddress">' + esc(d.shopAddress || '') + '</textarea>';
  html += '<div style="font-size:10.5px;color:var(--text-primary);font-weight:700;margin-top:4px;margin-bottom:14px;">' + t("intl_shop_address_hint") + '</div>';
  // Chaque vendeur choisit lui-même son agent — c'est cette personne qui
  // vérifiera ses paiements et lui enverra l'argent. Un agent ne gère
  // jamais un vendeur qu'un autre agent gère déjà, pour éviter toute
  // confusion sur le terrain (voir renderAgentSourcing, filtré par ce lien).
  if (agents.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--danger);background:rgba(255,85,102,0.08);padding:10px 12px;border-radius:10px;margin-top:14px;font-weight:700;"><i class="fa-solid fa-triangle-exclamation"></i> ' + t("intl_no_agent_yet") + '</div>';
  } else {
    html += '<label class="field-label">' + t("intl_choose_agent") + '</label>';
    html += '<select class="input" style="background:#ffffff;border-color:var(--text-dim);" data-bind="onboardDraft.sourcingAgentId">';
    html += '<option value="">' + t("intl_choose_agent_placeholder") + '</option>';
    for (var ai = 0; ai < agents.length; ai++) {
      html += '<option value="' + agents[ai].id + '" ' + (d.sourcingAgentId === agents[ai].id ? 'selected' : '') + '>' + esc(agents[ai].name) + '</option>';
    }
    html += '</select>';
    html += '<div style="font-size:10.5px;color:var(--text-primary);margin-top:4px;">' + t("intl_choose_agent_hint") + '</div>';
  }
  html += '</div>';
  // Le bouton reste désactivé tant qu'aucun agent valide n'est choisi —
  // que ce soit parce qu'il n'en existe encore aucun (rien à choisir), ou
  // parce qu'il y en a mais que le vendeur n'a pas encore cliqué dessus.
  // Sans agent assigné, personne ne pourrait jamais vérifier ses
  // paiements ni suivre sa commande une fois publiée.
  var canCreateIntlAccount = agents.length > 0 && !!d.sourcingAgentId;
  // Toujours cliquable (jamais "disabled" au sens HTML) même quand la
  // condition n'est pas remplie — un bouton vraiment désactivé ne déclenche
  // aucun clic du tout, donc aucun message ne peut s'afficher pour
  // expliquer pourquoi. On simule juste l'apparence grisée, et le clic
  // montre un message clair au lieu de ne rien faire.
  html += '<button class="btn-primary" style="margin-top:22px;' + (canCreateIntlAccount ? '' : 'opacity:0.5;') + '" data-action="' + (canCreateIntlAccount ? 'complete-onboarding' : 'agent-required-hint') + '">' + t("vo_create_account") + ' <i class="fa-solid fa-arrow-right"></i></button>';
  return html;
}

