// Champs de contact partag\u00e9s par tous les vendeurs non-Particulier
// (t\u00e9l\u00e9phone pro, adresse, position GPS).
function renderVendorContactFields(d) {
  var vendorGpsOk = d.shopLat != null && d.shopLng != null;
  var communeOptionsVc = communeSelectOptionsHtml(d.commune, d.communeProche, t("shop_customize_choose"));
  var quartierListVc = resolveQuartierListForCommune(d.commune, d.communeProche);
  var html = '';
  if (!d.email || d.isSecondAccountFlow) {
    html += '<label class="field-label">' + t("email_required") + '</label>';
    html += '<input class="input" type="text" inputmode="email" autocomplete="email" placeholder="exemple@email.com" value="' + esc(d.email || '') + '" data-bind="onboardDraft.email" />';
    html += '<div style="font-size:10.5px;color:var(--text-dim);margin-bottom:10px;">' + t("vo_email_required_note") + (d.isSecondAccountFlow ? t("vo_email_reused_note") : '') + '.</div>';
  }
  html += '<label class="field-label">' + t("shop_customize_commune") + ' *</label>';
  html += '<select class="input" data-bind="onboardDraft.commune" data-action-change="commune-changed">' + communeOptionsVc + '</select>';
  html += '<label class="field-label">' + t("shop_customize_quartier") + ' *</label>';
  html += renderQuartierFieldWithToggle(d.commune, d.communeProche, d.quartier, "onboardDraft.quartier", "onboard", t("shop_customize_choose"));
  html += '<label class="field-label">' + t("relais_apply_precision") + '</label>';
  html += '<input class="input" placeholder="' + t("relais_apply_precision_placeholder") + '" value="' + esc(d.addressDetail || '') + '" data-bind="onboardDraft.addressDetail" />';
  html += '<label class="field-label">' + t("vo_gps_required") + '</label>';
  html += '<button type="button" class="btn-secondary" style="margin-top:4px" data-action="capture-shop-gps">';
  html += '<i class="fa-solid fa-location-crosshairs"></i> ' + (vendorGpsOk ? t("relais_apply_gps_recapture") : t("vo_locate_activity"));
  html += '</button>';
  html += vendorGpsOk ? ('<div style="font-size:11px;color:var(--success);margin-top:6px">\ud83d\udccd ' + d.shopLat.toFixed(5) + ', ' + d.shopLng.toFixed(5) + '</div>') : '<div style="font-size:11px;color:var(--text-dim);margin-top:6px">' + t("vo_gps_mandatory_note") + '</div>';
  html += renderGpsPasteField("onboardDraft.shopLat", "onboardDraft.shopLng");
  return html;
}
// ---------- \u00c9TAPE 2 (Point de Retrait) ----------
// ---------- DEVENIR POINT DE RETRAIT (depuis un compte déjà existant) ----------
// Même fiche que celle de l'inscription, mais accessible depuis le menu de
// rôle pour un compte déjà créé — avec le champ email proposé ici s'il
// manquait encore (il est optionnel à l'inscription Acheteur).
// Document de politique d'utilisation, affiché AVANT le formulaire de
// candidature — la boutique doit explicitement accepter pour pouvoir
// continuer (voir "accept-relais-policy"). Texte uniquement en français :
// ce rôle ne concerne que des boutiques locales au Mali, jamais un
// compte international.
// Le bouton "J'accepte" d'un document de politique reste visuellement
// atténué tant qu'on n'a pas fait défiler jusqu'en bas — pas un vrai
// "disabled" HTML (qui bloquerait le clic sans jamais rien expliquer),
// juste une apparence pour inviter à lire ; le clic lui-même reste actif
// et vérifie la même chose au moment où on appuie (voir les handlers
// "accept-relais-policy" / "accept-commission-consent").
function onPolicyScroll(el, btnId) {
  if (el.scrollTop + el.clientHeight >= el.scrollHeight - 20) {
    var b = document.getElementById(btnId);
    if (b) b.style.opacity = '1';
  }
}

function isPolicyBoxScrolledToBottom(boxId) {
  var el = document.getElementById(boxId);
  if (!el) return true; // par sécurité, ne jamais bloquer si l'élément est introuvable
  return el.scrollTop + el.clientHeight >= el.scrollHeight - 20;
}

// Contenu du document, extrait pour être réutilisé à 3 endroits : ici
// (avant candidature), un écran "relire" depuis le tableau de bord, et le
// fichier téléchargeable — jamais dupliqué à plusieurs endroits.
// Génère un vrai fichier PDF téléchargeable à partir du contenu HTML
// d'une politique (voir relaisPolicyBodyHtml / sellerPolicyBodyHtml) —
// converti en texte brut avant l'écriture, puisque jsPDF n'écrit que du
// texte simple, pas du HTML. Une fois sur le téléphone, la personne peut
// l'imprimer ou le partager comme n'importe quel autre PDF — ça ne
// dépend plus de l'application à partir de ce moment-là.
function downloadPolicyAsPdf(title, bodyHtml, filename) {
  if (typeof window.jspdf === "undefined") {
    var pdfArgs = arguments;
    showToast("⏳ Préparation du PDF…");
    snsLoadLib("jspdf").then(function() { downloadPolicyAsPdf.apply(null, pdfArgs); }).catch(function() {
      showToast("❌ Le générateur de PDF n'a pas pu se charger — vérifiez votre connexion et réessayez.");
    });
    return;
  }
  var tempDiv = document.createElement("div");
  tempDiv.innerHTML = bodyHtml;
  var plainText = (tempDiv.innerText || tempDiv.textContent || "").replace(/×/g, "x").replace(/−/g, "-").replace(/→/g, "->").replace(/[\u202F\u00A0]/g, " ");

  var jsPDF = window.jspdf.jsPDF;
  var doc = new jsPDF({ unit: "pt", format: "a4" });
  var margin = 42;
  var pageWidth = doc.internal.pageSize.getWidth();
  var pageHeight = doc.internal.pageSize.getHeight();
  var maxWidth = pageWidth - margin * 2;
  var y = margin;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  var titleLines = doc.splitTextToSize(title, maxWidth);
  doc.text(titleLines, margin, y);
  y += titleLines.length * 20 + 14;

  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  var paragraphs = plainText.split("\n").map(function(p) { return p.trim(); }).filter(function(p) { return p.length > 0; });
  paragraphs.forEach(function(p) {
    var lines = doc.splitTextToSize(p, maxWidth);
    lines.forEach(function(line) {
      if (y > pageHeight - margin) { doc.addPage(); y = margin; }
      doc.text(line, margin, y);
      y += 14;
    });
    y += 7; // petit espace entre paragraphes
  });

  doc.setFontSize(8.5);
  doc.setTextColor(140, 140, 140);
  var footerLine = "Document généré depuis l'application Sounsouni — le contenu peut évoluer, téléchargez une version à jour à tout moment.";
  var footerLines = doc.splitTextToSize(footerLine, maxWidth);
  if (y + footerLines.length * 12 > pageHeight - margin) { doc.addPage(); y = margin; }
  doc.text(footerLines, margin, y + 10);

  doc.save(filename);
  showToast("✅ Document téléchargé.");
}

