  html += '<div style="position:relative;width:56px;height:56px;margin-bottom:8px;display:flex;align-items:center;justify-content:center;background:var(--accent-glow);border-radius:50%;">';
  html += '<i class="fa-solid fa-chart-line" style="font-size:22px;color:var(--primary);"></i>';
  html += '</div>';
  html += '<div style="font-weight:800;font-size:12.5px;line-height:1.3;">' + t("profile_earnings") + '</div>';
  html += '<span style="margin-top:6px;font-size:12.5px;font-weight:800;color:var(--primary);">' + money(getEarnings(state.profile.phone).total) + '</span>';
  html += '</button>';
