// ---------- Panneau "Test" — diagnostic complet, visible côté utilisateur ----------
// Réservé aux comptes activés par l'Admin (voir toggle-user-test-mode).
// But : que N'IMPORTE QUEL souci futur (pas seulement "je ne vois que mes
// propres produits") puisse être diagnostiqué en un seul rapport, sans
// aller-retour de questions — la personne appuie sur "Copier tout" et
// envoie le résultat.
function buildUserTestPanelText() {
  var p = state.profile || {};
  var lines = ["=== Rapport de test Sounsouni ===", fmtDateTime(Date.now()), ""];

  lines.push("--- Identité & compte ---");
  lines.push("Nom : " + (p.name || p.shopName || "—"));
  lines.push("Téléphone : " + (p.phone || "—"));
  lines.push("Rôle : " + (p.role || "—"));
  lines.push("Identifiant compte : " + (p.id || "—"));
  var linkedAccts = state.accounts.filter(function(a) { return a.phone === p.phone && a.id !== p.id; });
  lines.push("Comptes liés au même numéro : " + (linkedAccts.length ? linkedAccts.map(function(a) { return a.name + " (" + a.role + ")"; }).join(", ") : "aucun"));
  lines.push("Comptes déjà utilisés sur cet appareil : " + ((state.deviceAccountIds || []).length));
  lines.push("");

  lines.push("--- Connexion & synchronisation ---");
  lines.push("Jeton de session présent : " + (state.sessionToken ? "oui" : "NON"));
  lines.push("En ligne actuellement : " + (navigator.onLine ? "oui" : "NON"));
  var lastSync = null;
  try { lastSync = localStorage.getItem("gems_last_sync_v2"); } catch (e) {}
  lines.push("Dernière synchronisation : " + (lastSync ? fmtDateTime(new Date(lastSync).getTime()) : "jamais / inconnue"));
  lines.push("Modifications en attente d'envoi : " + ((state.pendingSyncQueue || []).length));
  var tp = decodeSessionToken(state.sessionToken);
  var healthTxt = { ok: "valide", expiring: "bientôt périmée (renouvellement auto)", expired: "PÉRIMÉE", other_account: "appartient à un AUTRE compte", broken: "ABÎMÉE", missing: "ABSENTE", none: "pas de profil" }[sessionHealth()] || "?";
  lines.push("État de la clé : " + healthTxt + (tp && tp.expiresAt ? " (expire le " + fmtDateTime(tp.expiresAt) + ")" : ""));
  lines.push("Mot de passe sur ce compte : " + (state.profile && state.profile.hasPassword ? "oui" : "non"));
  lines.push("");
  var pq = state.pendingSyncQueue || [];
  if (pq.length) {
    lines.push("--- En attente d'envoi (" + pq.length + ") ---");
    pq.slice(0, 40).forEach(function(e) {
      lines.push("• " + e.collection + " / " + e.id + " — depuis " + fmtDateTime(e.queuedAt || 0) + " — " + (e.attempts || 0) + " essai(s)" + (e.blocked ? " — ARRÊTÉ" : "") + " — raison : " + (e.lastError || "pas encore essayé"));
    });
    lines.push("");
  }

  lines.push("--- Données en mémoire sur ce téléphone ---");
  lines.push("Comptes : " + state.accounts.length);
  lines.push("Commandes : " + state.orders.length);
  lines.push("Produits (total, tous vendeurs) : " + state.products.length);
  var myProductsCount = state.products.filter(function(pr) { return pr.sellerId === p.id; }).length;
  lines.push("Produits qui m'appartiennent : " + myProductsCount);
  lines.push("Produits des AUTRES vendeurs : " + (state.products.length - myProductsCount));
  lines.push("");

  lines.push("--- Appareil ---");
  lines.push("Navigateur/app : " + navigator.userAgent);
  lines.push("Taille d'écran : " + window.innerWidth + " x " + window.innerHeight);
  lines.push("Langue de l'app : " + (state.lang || "—"));
  lines.push("Type de connexion : " + (navigator.connection && navigator.connection.effectiveType ? navigator.connection.effectiveType : "inconnu"));
  lines.push("");

  lines.push("--- Notifications & localisation ---");
  lines.push("Permission notifications : " + (typeof Notification !== "undefined" ? Notification.permission : "non supporté sur ce navigateur"));
  lines.push("Permission position GPS : " + (state.testPanelGeoPermission || "vérification en cours…"));
  lines.push("");

  lines.push("--- Stockage local ---");
  var approxSizeKb = "?";
  try { approxSizeKb = Math.round(JSON.stringify(state).length / 1024); } catch (e) {}
  lines.push("Taille approximative des données sauvegardées : " + approxSizeKb + " Ko");
  lines.push("");

  lines.push("--- Erreurs récentes (" + (state.debugLog || []).length + ") ---");
  var logs = (state.debugLog || []).slice(0, 20);
  if (logs.length === 0) {
    lines.push("Aucune erreur capturée récemment.");
  } else {
    for (var i = 0; i < logs.length; i++) {
      lines.push(maskSecrets("[" + fmtDateTime(logs[i].at) + "] (" + logs[i].type + ") " + logs[i].message + (logs[i].detail ? " — " + logs[i].detail : "")));
    }
  }
  return lines.join("\n");
}

// Vérification de la permission GPS — asynchrone par nature (API
// Permissions du navigateur), donc lancée une fois à l'ouverture du
// panneau puis affichée dès qu'elle répond, plutôt que de bloquer
// l'affichage du reste en l'attendant.
function checkGeoPermissionForTestPanel() {
  if (!navigator.permissions || !navigator.permissions.query) {
    state.testPanelGeoPermission = "API non disponible sur ce navigateur";
    render();
    return;
  }
  navigator.permissions.query({ name: "geolocation" }).then(function(status) {
    state.testPanelGeoPermission = status.state === "granted" ? "accordée" : (status.state === "denied" ? "refusée" : "pas encore demandée");
    render();
  }).catch(function() {
    state.testPanelGeoPermission = "impossible à vérifier";
    render();
  });
}

function renderUserTestPanel() {
  if (state.testPanelGeoPermission == null) {
    state.testPanelGeoPermission = "vérification en cours…";
    setTimeout(checkGeoPermissionForTestPanel, 0);
  }
  var html = '<div class="modal-overlay" data-action="close-user-test-panel">';
  html += '<div class="modal-sheet" style="max-height:85vh;overflow-y:auto;">';
  html += '<button class="modal-close" data-action="close-user-test-panel"><i class="fa-solid fa-xmark"></i></button>';
  html += '<div class="section-title" style="margin-bottom:6px;"><i class="fa-solid fa-flask"></i> Test</div>';
  html += '<div style="font-size:12px;color:var(--text-dim);margin-bottom:14px;">Si on t\'a demandé de faire ce test, appuie sur "Copier tout" ci-dessous et envoie le résultat.</div>';

  html += '<button class="btn-primary" style="width:100%;margin-bottom:10px;" data-action="copy-user-test-panel"><i class="fa-solid fa-copy"></i> Copier tout</button>';
  if ((state.pendingSyncQueue || []).length) html += '<button class="btn-secondary" style="width:100%;margin-bottom:14px;" data-action="retry-pending-now"><i class="fa-solid fa-paper-plane"></i> Renvoyer maintenant (' + state.pendingSyncQueue.length + ')</button>';

  var reportText = buildUserTestPanelText();
  html += '<div class="glass-card" style="padding:12px;background:var(--bg-body);font-family:monospace;font-size:10.5px;white-space:pre-wrap;word-break:break-word;max-height:50vh;overflow-y:auto;">' + esc(reportText) + '</div>';

  html += '</div></div>';
  return html;
}

