function renderCagnotteDetailModal() {
  var c = getCagnotte(state.cagnotteDetailId);
  if (!c) return '';
  var pct = c.targetAmount ? Math.min(100, Math.round((c.balance / c.targetAmount) * 100)) : null;
  var isCreator = state.profile && c.creatorId === state.profile.id;
  var html = '<div class="modal-overlay" id="cagnotte-detail-overlay" data-action="close-cagnotte-detail">';
  html += '<div class="modal-sheet">';
  html += '<button class="modal-close" data-action="close-cagnotte-detail"><i class="fa-solid fa-xmark"></i></button>';
  html += '<button class="link-btn wallet-back-btn" style="margin-bottom:10px;" data-action="close-cagnotte-detail"><i class="fa-solid fa-arrow-left"></i> ' + t("wallet_back") + '</button>';
  html += '<div class="section-title" style="margin-bottom:4px;"><i class="fa-solid fa-hand-holding-heart"></i> ' + esc(c.title) + '</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:14px;">' + t("pot_by") + ' ' + esc(c.creatorName) + (c.status === "closed" ? ' · ' + t("pot_closed_label") : '') + '</div>';
  if (c.description) html += '<div style="font-size:13px;color:var(--text-secondary);margin-bottom:14px;line-height:1.5;">' + esc(c.description) + '</div>';
  html += '<div class="glass-card" style="padding:16px;text-align:center;margin-bottom:16px;background:linear-gradient(135deg,var(--primary),var(--accent));">';
  html += '<div style="font-size:26px;font-weight:800;color:white;">' + money(c.balance) + (c.targetAmount ? '<span style="font-size:14px;font-weight:600;"> / ' + money(c.targetAmount) + '</span>' : '') + '</div>';
  if (pct != null) {
    html += '<div style="height:8px;background:rgba(255,255,255,0.3);border-radius:99px;margin-top:10px;overflow:hidden;"><div style="height:100%;width:' + pct + '%;background:white;border-radius:99px;"></div></div>';
    html += '<div style="font-size:11px;color:rgba(255,255,255,0.85);margin-top:6px;">' + pct + t("pot_reached") + '</div>';
  }
  html += '</div>';
  if (c.status === "active") {
    html += '<button class="btn-primary" style="margin-bottom:10px;" data-action="open-cagnotte-contribute" data-value="' + c.id + '"><i class="fa-solid fa-hand-holding-dollar"></i> ' + t("pot_contribute") + '</button>';
    html += '<button class="btn-secondary" style="margin-bottom:16px;" data-action="share-cagnotte" data-value="' + c.id + '"><i class="fa-solid fa-share-nodes"></i> ' + t("pot_share_link") + '</button>';
    if (isCreator) {
      html += '<button class="btn-secondary" style="margin-bottom:16px;color:var(--danger);" data-action="confirm-close-cagnotte" data-value="' + c.id + '"><i class="fa-solid fa-flag-checkered"></i> ' + t("pot_close_and_collect") + '</button>';
    }
  }
  html += '<div class="section-title" style="font-size:14px;margin-bottom:10px;">' + t("pot_contributions_title") + ' (' + c.contributions.length + ')</div>';
  if (c.contributions.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim);">' + t("pot_no_contributions") + '</div>';
  } else {
    var sorted = c.contributions.slice().reverse();
    for (var i = 0; i < sorted.length; i++) {
      var ct = sorted[i];
      html += '<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border-color);font-size:12.5px;">';
      html += '<div><div style="font-weight:700;">' + esc(ct.contributorName) + '</div>' + (ct.message ? '<div style="font-size:11px;color:var(--text-dim);">"' + esc(ct.message) + '"</div>' : '') + '</div>';
      html += '<div style="font-weight:800;color:var(--accent);">' + money(ct.amount) + '</div>';
      html += '</div>';
    }
  }
  html += '</div></div>';
  return html;
}

