  html += '<input class="input" id="giftcard-message" placeholder="Ex : Joyeux anniversaire !" />';
  html += '<label class="field-label">' + t("gift_payment_mode") + '</label>';
  html += '<div style="display:flex;flex-direction:column;gap:8px;margin-top:4px;margin-bottom:6px;">';
  html += giftCardPaymentOption("paiement_livraison", "Paiement à la livraison", "fa-money-bill-wave");
  html += giftCardPaymentOption("orange_money", "Orange Money", "fa-mobile-screen");
  html += giftCardPaymentOption("moov_money", "Moov Money", "fa-mobile-screen");
  html += '</div>';
  html += '<div style="font-size:10.5px;color:var(--text-dim);margin-bottom:16px;">' + t("gift_payment_note") + '</div>';
  html += '<button class="btn-primary" data-action="confirm-giftcard"><i class="fa-solid fa-check"></i> ' + t("gift_submit") + '</button>';
  html += '</div></div>';
