  html += '<div style="font-weight:700;font-size:13.5px;flex:1;text-align:left">' + label + '</div>';
  html += '<span class="coming-soon" style="font-size:8px;background:var(--primary);color:white;padding:1px 6px;border-radius:999px;margin-left:4px;">Bientôt</span>';
