// ---------- GUIDE D'UTILISATION ----------
// Texte dynamique substitué au marqueur {{COMMISSION_INFO}} dans le guide —
// reflète toujours le taux ET le mode réellement configurés en Admin,
// contrairement à un pourcentage écrit en dur qui resterait faux si le
// taux ou le mode changent.
function commissionFaqText() {
  var cfg = getCommissionConfig();
  var pct = (cfg.totalCommissionRate * 100).toFixed(0);
  var keepPct = (100 - cfg.totalCommissionRate * 100).toFixed(0);
  var template = cfg.commissionMode === "add" ? t("commission_faq_add") : t("commission_faq_default");
  return template.replace("{pct}", pct).replace("{keepPct}", keepPct);
}

// Remplace les marqueurs dynamiques (ex: {{COMMISSION_INFO}}) par leur
// vrai texte au moment de l'affichage — pour l'instant seul le taux de
// commission en a besoin, mais la structure accepte d'autres marqueurs
// futurs sans tout réécrire.
function faqAnswerText(rawAnswer) {
  if (rawAnswer === "{{COMMISSION_INFO}}") return commissionFaqText();
  return rawAnswer;
}

