var GUIDE_VIDEO_BASE = "https://sounsouni.pro/guides/";
function renderGuideVideoModal() {
  var g = TASK_GUIDES[state.guideVideoKey];
  if (!g || !g.video) return "";
  var html = '<div class="modal-overlay" style="z-index:9999;background:rgba(0,0,0,0.88);">';
  html += '<div style="position:relative;width:100%;max-width:420px;margin:auto;padding:12px;">';
  html += '<button class="modal-close" data-action="close-guide-video" style="position:absolute;top:18px;right:18px;z-index:2;"><i class="fa-solid fa-xmark"></i></button>';
  html += '<div style="color:#fff;font-weight:800;font-size:14px;margin:4px 44px 10px 4px;">' + esc(g.label) + '</div>';
  html += '<video src="' + GUIDE_VIDEO_BASE + g.video + '.mp4" controls autoplay playsinline preload="auto" style="width:100%;max-height:78vh;border-radius:16px;background:#000;display:block;"></video>';
  html += '<div style="color:rgba(255,255,255,0.7);font-size:11px;margin-top:8px;text-align:center;">' + t("guide_video_hint") + '</div>';
  html += '</div></div>';
  return html;
}

function renderTourOverlay() {
  var tour = state.activeTour;
  var slides = TASK_GUIDES[tour.tourKey] ? TASK_GUIDES[tour.tourKey].slides : (TOUR_CONTENT[tour.tourKey] || []);
  var slide = slides[tour.index];
  if (!slide) return "";
  var isLast = tour.index >= slides.length - 1;
  var isFirst = tour.index === 0;
  var html = '<div class="modal-overlay" style="z-index:9999;">';
  html += '<div class="modal-sheet" style="max-width:340px;margin:auto;border-radius:20px;padding:24px 20px;position:relative;">';
  html += '<button class="modal-close" data-action="tour-close" style="position:absolute;top:14px;right:14px;"><i class="fa-solid fa-xmark"></i></button>';
  if (!tour.single) {
    html += '<div style="display:flex;justify-content:center;gap:6px;margin-bottom:16px;">';
    for (var d = 0; d < slides.length; d++) {
      html += '<div style="width:' + (d === tour.index ? '18px' : '6px') + ';height:6px;border-radius:3px;background:' + (d === tour.index ? 'var(--accent)' : 'var(--border-color)') + ';transition:width .2s;"></div>';
    }
    html += '</div>';
  }
  html += '<div class="tour-mockup">';
  html += '<img loading="lazy" src="' + slide.img + '" style="width:100%;max-height:52vh;object-fit:cover;object-position:top;display:block;border-radius:14px;" alt="" />';
  if (slide.tapPos) {
    html += '<div class="tour-tap-point" style="top:' + slide.tapPos.top + ';left:' + slide.tapPos.left + ';"><div class="tour-ripple"></div><div class="tour-finger"><i class="fa-solid fa-hand-pointer"></i></div></div>';
  }
  html += '</div>';
  html += '<div style="font-weight:800;font-size:15.5px;margin-bottom:6px;text-align:center;">' + esc(slide.title) + '</div>';
  html += '<div style="font-size:12.5px;color:var(--text-dim);line-height:1.5;margin-bottom:20px;text-align:center;">' + esc(slide.text) + '</div>';
  if (tour.single) {
    html += '<button class="btn-primary" style="width:100%;" data-action="tour-close">' + t("tour_got_it") + '</button>';
  } else {
    html += '<button class="btn-primary" style="width:100%;margin-bottom:10px;" data-action="tour-next">' + (isLast ? t("tour_finish") : t("tour_next")) + '</button>';
    html += '<div style="display:flex;justify-content:space-between;">';
    html += isFirst ? '<span></span>' : '<button class="link-btn" data-action="tour-prev"><i class="fa-solid fa-arrow-left"></i> ' + t("tour_prev") + '</button>';
    html += '<button class="link-btn" style="color:var(--text-dim);" data-action="tour-close">' + t("tour_close_guide") + '</button>';
    html += '</div>';
  }
  html += '</div></div>';
  return html;
}

