// Génère un code secret de récupération lisible (évite les caractères
// ambigus 0/O/1/I) — donné à l'utilisateur une seule fois, à la création
// de son mot de passe, pour lui permettre de le récupérer plus tard.
function generateRecoveryCode() {
  var chars = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
  var out = "";
  for (var i = 0; i < 8; i++) out += chars.charAt(Math.floor(Math.random() * chars.length));
  return out.slice(0, 4) + "-" + out.slice(4);
}

// --- Hachage des mots de passe / codes secrets (PBKDF2, Web Crypto) ---
// Jamais de version en clair stockée à partir d'ici. PBKDF2 est
// volontairement lent (100 000 itérations) : même avec un accès complet à
// la base, quelqu'un ne peut pas essayer des millions de mots de passe
// par seconde dessus, contrairement à un simple SHA-256.
// Format stocké : "pbkdf2$<itérations>$<sel en base64>$<empreinte en base64>"
function bufToB64(buf) {
  var bytes = new Uint8Array(buf);
  var bin = "";
  for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}
function b64ToBuf(b64) {
  var bin = atob(b64);
  var bytes = new Uint8Array(bin.length);
  for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
// Appelle une fonction serveur sécurisée (Edge Function) plutôt que de
// vérifier/chiffrer un mot de passe directement sur le téléphone — voir
// la migration de sécurité : ni le mot de passe de la personne, ni celui
// de qui que ce soit d'autre, ne doit plus jamais transiter en clair ni
// être comparé localement.
// Petit utilitaire central : construit les en-têtes d'une requête vers
// une fonction serveur, en y ajoutant le jeton de session s'il y en a
// un — pour ne jamais l'oublier sur un appel qui en a besoin.
function authHeaders(extra, useAdminToken) {
  var h = Object.assign({ "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey }, extra || {});
  var token = useAdminToken ? state.adminSessionToken : state.sessionToken;
  if (token) h["X-Session-Token"] = token;
  return h;
}

// Seul chemin autorisé pour créer un nouveau compte — le serveur
// vérifie pour de vrai l'unicité du numéro (jamais fiable si on ne
// fait confiance qu'au cache local du téléphone) et délivre aussitôt
// un jeton de session, pour que le compte tout neuf puisse déjà
// utiliser les actions sensibles (dont son tout premier mot de passe).
function createAccountSecurely(account) {
  return fetch(supabaseConfig.url + "/functions/v1/create-account", {
    method: "POST",
    // Le jeton de session (si on est déjà connecté) prouve que ce numéro
    // est bien le nôtre quand on ajoute une boutique sur le même numéro.
    headers: authHeaders(),
    body: JSON.stringify({ account: account, hp: (state.onboardDraft && state.onboardDraft.hpFax) || "", formMs: (window._snsFormShownAt && window._snsFormShownAt.inscription) ? Date.now() - window._snsFormShownAt.inscription : null })
  })
    .then(function(r) { return r.json(); })
    .catch(function() { return { success: false, error: "network_error" }; });
}

// Retrouve un compte par identité (nom+téléphone ou nom+email, plus
// date de naissance) — entièrement côté serveur désormais, pour ne
// plus jamais avoir besoin de la date de naissance de qui que ce soit
// d'autre en mémoire sur ce téléphone.
function findAccountForRecovery(payload) {
  return fetch(supabaseConfig.url + "/functions/v1/find-account-recovery", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey },
    body: JSON.stringify(payload)
  })
    .then(function(r) { return r.json(); })
    .catch(function() { return { success: false }; });
}

function verifyAccountPassword(accountId, password) {
  return fetch(supabaseConfig.url + "/functions/v1/verify-login", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey },
    body: JSON.stringify({ accountId: accountId, password: password })
  })
    .then(function(r) { return r.json(); })
    .then(function(res) {
      if (res && res.error === "too_many_attempts") {
        showToast("🔒 Trop d'essais ratés. Réessayez dans 15 minutes.");
      }
      // Un mot de passe correct délivre un vrai jeton de session — on le
      // garde, il faudra le présenter pour toute action sensible ensuite
      // (commandes, portefeuille, changement de mot de passe...).
      //
      // Si ce mot de passe vérifié est celui du compte ACTUELLEMENT
      // connecté (ou qu'aucun profil n'est encore actif — connexion
      // initiale), c'est le jeton "principal" qui sert à toutes les
      // actions courantes (commandes, portefeuille). Mais si c'est celui
      // d'une IDENTITÉ SÉPARÉE — admin_owner, national_admin_*,
      // dashboard_partner_* — déverrouillée alors qu'un profil normal
      // est déjà connecté, ce jeton ne doit JAMAIS remplacer le
      // principal : sinon la prochaine commande passée en tant
      // qu'acheteur seraît refusée par le serveur (elle porterait alors
      // l'identité Admin, pas la vraie).
      if (res.success && res.sessionToken) {
        var isOwnProfile = !state.profile || state.profile.id === accountId;
        if (isOwnProfile) state.sessionToken = res.sessionToken;
        else state.adminSessionToken = res.sessionToken;
        save();
      }
      return !!res.success;
    })
    .catch(function() { return false; }); // panne réseau = refusé, jamais accepté par défaut
}

function verifyAccountRecoveryCode(accountId, recoveryCode) {
  return fetch(supabaseConfig.url + "/functions/v1/verify-login", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey },
    body: JSON.stringify({ accountId: accountId, recoveryCode: recoveryCode })
  })
    .then(function(r) { return r.json(); })
    .then(function(res) {
      // Un code de récupération correct ne délivre PAS une vraie session
      // — juste un jeton spécial, à courte durée, qui ne permettra que de
      // définir un nouveau mot de passe (voir submit-forgot-password-reset).
      if (res.success && res.passwordResetToken) {
        state.passwordResetToken = res.passwordResetToken;
        save();
      }
      return !!res.success;
    })
    .catch(function() { return false; });
}

function setAccountPassword(accountId, newPassword, newRecoveryCode, birthDate) {
  var payload = { accountId: accountId };
  if (newPassword) payload.newPassword = newPassword;
  if (newRecoveryCode) payload.newRecoveryCode = newRecoveryCode;
  // La date de naissance ne va JAMAIS dans "accounts" (largement lu par
  // toute l'app) — seulement ici, vers "credentials", une table jamais
  // accessible directement depuis le téléphone. C'est elle qui sert à
  // retrouver un compte en cas de mot de passe oublié (voir
  // findAccountForRecovery), sans qu'aucune date de naissance n'ait
  // jamais besoin d'être visible en dehors du serveur.
  if (birthDate) payload.birthDate = birthDate;
  // Utilise le jeton de réinitialisation s'il y en a un en attente
  // (juste après un code de récupération vérifié) — sinon, le jeton
  // correspondant à CE compte précis : le principal si c'est le profil
  // actif (ou qu'aucun profil n'est encore connecté), le jeton Admin
  // séparé sinon (ex : changer le mot de passe admin_owner pendant
  // qu'un profil acheteur normal est connecté).
  var extraHeaders = {};
  if (state.passwordResetToken) {
    extraHeaders["X-Session-Token"] = state.passwordResetToken;
  } else {
    var isOwnProfile = !state.profile || state.profile.id === accountId;
    var relevantToken = isOwnProfile ? state.sessionToken : state.adminSessionToken;
    if (relevantToken) extraHeaders["X-Session-Token"] = relevantToken;
  }
  return fetch(supabaseConfig.url + "/functions/v1/set-password", {
    method: "POST",
    headers: Object.assign({ "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey }, extraHeaders),
    body: JSON.stringify(payload)
  })
    .then(function(r) { return r.json(); })
    .then(function(res) {
      // Le jeton de réinitialisation ne sert qu'une fois — on l'oublie
      // dès qu'il a servi, qu'il ait marché ou non.
      if (state.passwordResetToken) { state.passwordResetToken = null; save(); }
      return !!res.success;
    })
    .catch(function() { return false; });
}

function setPartnerSecret(partnerId, type, value) {
  return fetch(supabaseConfig.url + "/functions/v1/set-partner-secret", {
    method: "POST",
    headers: authHeaders(null, true),
    body: JSON.stringify({ partnerId: partnerId, type: type, value: value })
  })
    .then(function(r) { return r.json(); })
    .then(function(res) { return !!res.success; })
    .catch(function() { return false; });
}

function fetchPartnerSecret(partnerId, type) {
  var adminUsername = getAdminCredentials("owner").username;
  if (state.adminCountryScope) {
    var na = state.nationalAdmins.find(function(a) { return a.country === state.adminCountryScope; });
    if (na) adminUsername = na.ownerUsername;
  }
  function tryFetch(pwd) {
    return fetch(supabaseConfig.url + "/functions/v1/get-partner-secret", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey },
      body: JSON.stringify({ adminUsername: adminUsername, adminPassword: pwd, partnerId: partnerId, type: type })
    })
      .then(function(r) { return r.json(); })
      .catch(function(err) {
        console.error("Erreur réseau get-partner-secret :", err);
        return { success: false, error: "network_error" };
      });
  }
  if (_adminSessionPasswordCache) {
    return tryFetch(_adminSessionPasswordCache).then(function(res) {
      if (res.success) return res;
      _adminSessionPasswordCache = null;
      state.pendingPartnerSecretRequest = { partnerId: partnerId, type: type };
      state.pendingDocKeyForPassword = null;
      state.docPasswordDraft = "";
      state.docPasswordError = null;
      state.showDocPasswordModal = true;
      render();
      return { success: false, error: "needs_prompt" };
    });
  }
  state.pendingPartnerSecretRequest = { partnerId: partnerId, type: type };
  state.pendingDocKeyForPassword = null;
  state.docPasswordDraft = "";
  state.docPasswordError = null;
  state.showDocPasswordModal = true;
  render();
  return Promise.resolve({ success: false, error: "needs_prompt" });
}

function submitVerificationDocuments(docKey, selfiePhoto, verificationDocs) {
  return fetch(supabaseConfig.url + "/functions/v1/submit-verification-docs", {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({ docKey: docKey, selfiePhoto: selfiePhoto, verificationDocs: verificationDocs })
  })
    .then(function(r) { return r.json(); })
    .then(function(res) { return !!res.success; })
    .catch(function() { return false; });
}

// Le mot de passe Admin n'est jamais gardé en mémoire persistante — juste
// le temps de la session en cours, pour éviter de le redemander à
// chaque photo consultée. Il repart à zéro à chaque rechargement de l'app.
var _adminSessionPasswordCache = null;

// tryFetch séparée de la partie "demander le mot de passe" — cette
// dernière passe maintenant par un vrai écran de l'app (voir
// renderDocPasswordModal / "submit-doc-password"), plus fiable que la
// fenêtre native "prompt()", qui peut être bloquée ou se comporter
// bizarrement sur une app installée sur l'écran d'accueil.
function tryFetchVerificationDocument(docKey, pwd) {
  var adminUsername = getAdminCredentials("owner").username;
  if (state.adminCountryScope) {
    var na = state.nationalAdmins.find(function(a) { return a.country === state.adminCountryScope; });
    if (na) adminUsername = na.ownerUsername;
  }
  return fetch(supabaseConfig.url + "/functions/v1/get-verification-docs", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey },
    body: JSON.stringify({ adminUsername: adminUsername, adminPassword: pwd, docKey: docKey })
  })
    .then(function(r) { return r.json().then(function(j) { return { httpStatus: r.status, body: j }; }); })
    .then(function(wrapped) {
      if (!wrapped.body || wrapped.body.success !== true) {
        console.error("get-verification-docs a échoué :", wrapped.httpStatus, wrapped.body);
      }
      return wrapped.body || { success: false, error: "empty_response" };
    })
    .catch(function(networkErr) {
      console.error("Erreur réseau vers get-verification-docs :", networkErr);
      return { success: false, error: "network_error: " + (networkErr && networkErr.message ? networkErr.message : String(networkErr)) };
    });
}

// Point d'entrée : essaie d'abord avec le mot de passe déjà en mémoire
// pour cette session (s'il y en a un) ; sinon, ouvre l'écran de saisie.
function fetchAdminFilatureLog(phone) {
  var adminUsername = getAdminCredentials("owner").username;
  if (state.adminCountryScope) {
    var na = state.nationalAdmins.find(function(a) { return a.country === state.adminCountryScope; });
    if (na) adminUsername = na.ownerUsername;
  }
  function tryFetch(pwd) {
    return fetch(supabaseConfig.url + "/functions/v1/get-filature-log", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey },
      body: JSON.stringify({ adminUsername: adminUsername, adminPassword: pwd, docId: normalizeWalletPhone(phone) })
    })
      .then(function(r) { return r.json(); })
      .catch(function(err) {
        console.error("Erreur réseau get-filature-log :", err);
        return { success: false, error: "network_error" };
      });
  }
  function applyResult(res) {
    if (!res.success || !res.log) return;
    var idx = -1;
    for (var i = 0; i < state.filatureLogs.length; i++) {
      if (state.filatureLogs[i].id === res.log.id) { idx = i; break; }
    }
    if (idx === -1) state.filatureLogs.push(res.log); else state.filatureLogs[idx] = res.log;
    render();
  }
  if (_adminSessionPasswordCache) {
    tryFetch(_adminSessionPasswordCache).then(function(res) {
      if (res.success) { applyResult(res); return; }
      _adminSessionPasswordCache = null;
      state.pendingFilatureLogRequest = phone;
      state.pendingDocKeyForPassword = null;
      state.pendingPartnerSecretRequest = null;
      state.docPasswordDraft = "";
      state.docPasswordError = null;
      state.showDocPasswordModal = true;
      render();
    });
    return;
  }
  state.pendingFilatureLogRequest = phone;
  state.pendingDocKeyForPassword = null;
  state.pendingPartnerSecretRequest = null;
  state.docPasswordDraft = "";
  state.docPasswordError = null;
  state.showDocPasswordModal = true;
  render();
}

function fetchVerificationDocument(docKey) {
  if (_adminSessionPasswordCache) {
    return tryFetchVerificationDocument(docKey, _adminSessionPasswordCache).then(function(res) {
      if (res.success) return res;
      // Le mot de passe en mémoire ne marche plus (changé entre-temps) —
      // on le jette et on redemande via l'écran normal.
      _adminSessionPasswordCache = null;
      state.pendingDocKeyForPassword = docKey;
      state.docPasswordDraft = "";
      state.docPasswordError = null;
      state.showDocPasswordModal = true;
      render();
      return { success: false, error: "needs_prompt" };
    });
  }
  state.pendingDocKeyForPassword = docKey;
  state.docPasswordDraft = "";
  state.docPasswordError = null;
  state.showDocPasswordModal = true;
  render();
  return Promise.resolve({ success: false, error: "needs_prompt" });
}

