function hashSecret(plainText) {
  var iterations = 100000;
  var salt = crypto.getRandomValues(new Uint8Array(16));
  return crypto.subtle.importKey("raw", new TextEncoder().encode(plainText), { name: "PBKDF2" }, false, ["deriveBits"])
    .then(function(keyMaterial) {
      return crypto.subtle.deriveBits({ name: "PBKDF2", salt: salt, iterations: iterations, hash: "SHA-256" }, keyMaterial, 256);
    })
    .then(function(bits) {
      return "pbkdf2$" + iterations + "$" + bufToB64(salt) + "$" + bufToB64(bits);
    });
}
// Compare une valeur tapée à ce qui est stocké. Gère aussi la transition :
// si "stored" est encore une ancienne valeur en clair (comptes créés avant
// ce chiffrement), la comparaison directe fonctionne une dernière fois ET
// renvoie la nouvelle empreinte à sauvegarder à la place — sans jamais
// exiger une étape de conversion à part, ni un nouveau mot de passe.
function verifySecret(plainText, stored) {
  if (!stored) return Promise.resolve({ match: false, upgraded: null });
  if (stored.indexOf("pbkdf2$") !== 0) {
    if (stored === plainText) return hashSecret(plainText).then(function(h) { return { match: true, upgraded: h }; });
    return Promise.resolve({ match: false, upgraded: null });
  }
  var parts = stored.split("$");
  var iterations = parseInt(parts[1], 10);
  var salt = b64ToBuf(parts[2]);
  var expected = parts[3];
  return crypto.subtle.importKey("raw", new TextEncoder().encode(plainText), { name: "PBKDF2" }, false, ["deriveBits"])
    .then(function(keyMaterial) {
      return crypto.subtle.deriveBits({ name: "PBKDF2", salt: salt, iterations: iterations, hash: "SHA-256" }, keyMaterial, 256);
    })
    .then(function(bits) {
      return { match: bufToB64(bits) === expected, upgraded: null };
    });
}

function persistProfileToAccounts() {
  if (!state.profile) return;
  for (var i = 0; i < state.accounts.length; i++) {
    if (state.accounts[i].id === state.profile.id) { state.accounts[i] = { ...state.profile }; break; }
  }
  save();
  saveDoc("accounts", state.profile);
}

