  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:16px;">' + t("aff_explainer") + ' ' + (stats.commissionRate * 100).toFixed(1) + '% ' + t("aff_of_order") + '</div>';

  html += '<div class="referral-link-box" data-action="copy-referral-link" style="cursor:pointer;"><input class="input" readonly value="' + esc(link) + '" data-real-link="' + esc(link) + '" style="pointer-events:none;" /></div>';
