// ---------- MODALE : BOOST ----------
// ---------- MODALE : ÉDITION PRODUIT PAR L'ADMIN (champs essentiels) ----------
// ---------- MODALE : LECTURE D'UNE CONVERSATION PAR L'ADMIN (pouvoir étendu) ----------
function renderAdminConversationViewModal() {
  var convId = state.adminViewingConversationId;
  var conv = null;
  for (var i = 0; i < state.conversations.length; i++) {
    if (state.conversations[i].id === convId) { conv = state.conversations[i]; break; }
  }
  if (!conv) return '';

  var buyerAcc = null, sellerAcc = null, prod = null;
  for (var a = 0; a < state.accounts.length; a++) {
    if (state.accounts[a].id === conv.buyerId) buyerAcc = state.accounts[a];
    if (state.accounts[a].id === conv.sellerId) sellerAcc = state.accounts[a];
  }
  for (var p = 0; p < state.products.length; p++) { if (state.products[p].id === conv.productId) { prod = state.products[p]; break; } }

  var html = '<div class="modal-overlay" id="admin-conversation-view-overlay" data-action="close-admin-conversation-view">';
  html += '<div class="modal-sheet">';
  html += '<button class="modal-close" data-action="close-admin-conversation-view"><i class="fa-solid fa-xmark"></i></button>';
  html += '<div class="section-title" style="margin-bottom:4px;"><i class="fa-solid fa-eye"></i> Lecture (Admin)</div>';
  html += '<div style="font-size:12px;color:var(--text-dim);margin-bottom:4px;">' + esc(prod ? prod.name : 'Produit supprimé') + '</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:14px;"><i class="fa-solid fa-user"></i> ' + esc(buyerAcc ? buyerAcc.name : 'Acheteur') + ' <i class="fa-solid fa-arrow-right-arrow-left" style="margin:0 4px;"></i> ' + esc(sellerAcc ? sellerAcc.name : 'Vendeur') + '</div>';

  var msgs = conv.messages || [];
  if (msgs.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim);text-align:center;padding:20px 0;">Aucun message échangé.</div>';
  } else {
    html += '<div style="max-height:340px;overflow-y:auto;background:var(--bg-body);border-radius:12px;padding:10px;">';
    for (var m = 0; m < msgs.length; m++) {
      var msg = msgs[m];
      var fromBuyer = msg.senderId === conv.buyerId;
      html += '<div style="margin-bottom:8px;text-align:' + (fromBuyer ? 'left' : 'right') + ';">';
      html += '<div style="font-size:9.5px;color:var(--text-dim);margin-bottom:2px;">' + esc(msg.senderName) + '</div>';
      html += '<div style="display:inline-block;max-width:82%;padding:6px 10px;border-radius:10px;font-size:12px;background:' + (fromBuyer ? 'var(--bg-card)' : 'var(--accent)') + ';color:' + (fromBuyer ? 'var(--text-primary)' : '#fff') + ';">' + esc(msg.message) + (msg.hasPhoneNumber ? '<div style="font-size:10px;margin-top:2px;">🔒 Numéro masqué</div>' : '') + '</div>';
      html += '<div style="font-size:9px;color:var(--text-dim);margin-top:2px;">' + fmtDateTime(msg.createdAt) + '</div>';
      html += '</div>';
    }
    html += '</div>';
  }
  html += '<div style="font-size:10px;color:var(--text-dim);margin-top:12px;text-align:center;"><i class="fa-solid fa-lock"></i> Lecture seule — l\'administration ne peut pas envoyer de message dans cette conversation.</div>';
  html += '</div></div>';
  return html;
}

