// Administration : qui appeler pour cette commande — le client, chaque
// boutique (avec l'état de sa part), le livreur. Une boutique injoignable
// ou qui ne peut pas fournir peut être retirée : ses articles sortent du
// montant, le client est prévenu, les autres boutiques continuent.
function renderAdminOrderContacts(o) {
  var tel = function(p) { return p ? ' — <a href="tel:' + esc(p) + '" style="color:var(--accent);font-weight:700;">' + esc(p) + '</a>' : ' — <span style="color:var(--text-dim);">numéro inconnu</span>'; };
  var buyer = (state.accounts || []).find(function(a) { return a.id === o.buyerId; });
  var html = '<div style="background:var(--bg-body);border-radius:10px;padding:8px 10px;margin:8px 0;">';
  html += '<div style="font-size:11.5px;font-weight:700;color:var(--text-dim);margin-bottom:4px;"><i class="fa-solid fa-address-book"></i> ' + t("livreur_contacts") + '</div>';
  html += '<div style="font-size:12px;margin-bottom:4px;"><i class="fa-solid fa-user"></i> ' + esc(o.buyerName || "") + tel(o.contactPhone || o.buyerPhone || (buyer && buyer.phone)) + '</div>';
  var ids = [];
  (o.items || []).forEach(function(x) { if (x && x.sellerId && ids.indexOf(x.sellerId) === -1) ids.push(x.sellerId); });
  Object.keys(o.vendorStatuses || {}).forEach(function(k) { if (ids.indexOf(k) === -1) ids.push(k); });
  (o.sellerIds || []).forEach(function(k) { if (ids.indexOf(k) === -1) ids.push(k); });
  var closed = ["Livrée", "Annulée", "Non livrable", "Refusée au retrait"].indexOf(o.status) !== -1;
  ids.forEach(function(sid) {
    var acc = (state.accounts || []).find(function(a) { return a.id === sid; }) || {};
    var it = (o.items || []).find(function(x) { return x && x.sellerId === sid; }) || {};
    var st = (o.vendorStatuses || {})[sid] || (o.status === "Nouvelle" ? "Nouvelle" : "Prête");
    var badge = st === "Prête" ? '<span style="color:var(--success);font-weight:700;">✓ ' + t("livreur_shop_ready") + '</span>' : (st === "Refusée" || st === "Annulée" ? '<span style="color:var(--danger);font-weight:700;">✗ indisponible</span>' : '<span style="color:var(--text-dim);">⏳ ' + t("livreur_shop_preparing") + '</span>');
    html += '<div style="font-size:12px;margin-top:2px;"><i class="fa-solid fa-store"></i> ' + esc(acc.shopName || it.sellerName || acc.name || "?") + tel(acc.shopPhone || acc.phone) + ' ' + badge + '</div>';
    if (acc.shopAddress) html += '<div style="font-size:11px;color:var(--text-dim);margin:0 0 2px 20px;"><i class="fa-solid fa-location-dot"></i> ' + esc(acc.shopAddress) + (acc.shopLat && acc.shopLng ? ' · <a href="https://www.google.com/maps?q=' + acc.shopLat + ',' + acc.shopLng + '" target="_blank" style="color:var(--accent);font-weight:700;">' + t("livreur_map_short") + '</a>' : '') + '</div>';
    if (!closed && st !== "Refusée" && st !== "Annulée") html += '<button class="link-btn" style="color:var(--danger);font-size:11px;margin:0 0 4px 20px;" data-action="admin-shop-unavailable" data-order="' + o.id + '" data-value="' + sid + '"><i class="fa-solid fa-store-slash"></i> Boutique indisponible — retirer ses articles</button>';
  });
  if (o.livreurName) html += '<div style="font-size:12px;margin-top:4px;"><i class="fa-solid fa-truck-fast"></i> ' + esc(o.livreurName) + ' (livreur)' + tel(o.livreurPhone) + '</div>';
  html += '</div>';
  return html;
}
