// ---------- RECOMMANDATIONS EN CERCLES PULSANTS (3x3) ----------
// Recommandations liées à un contexte (catégorie ou secteur) — complète
// avec les recommandations générales si pas assez d'articles dans ce
// contexte précis, plutôt que d'afficher un bloc vide ou trop court.
// Même principe que searchProductsOnServer, pour une catégorie précise
// cette fois — sans ça, les recommandations "même catégorie" ou "même
// secteur" ne pouvaient piocher que dans le lot déjà chargé, faible ou
// vide pour une catégorie peu représentée parmi les articles récents.
var _categoriesCheckedThisSession = {};
function ensureCategoryProductsLoaded(category) {
  if (!category || category === "Tout" || _categoriesCheckedThisSession[category] || _productsFullyLoaded) return;
  _categoriesCheckedThisSession[category] = true;
  sb.from("app_data").select("*").eq("collection", "products")
    .eq("data->>category", category)
    .limit(50)
    .then(function(res) {
      if (res.error || !res.data) { console.error("Échec du chargement de la catégorie côté serveur :", res.error); return; }
      var existingIds = {};
      for (var cpi = 0; cpi < state.products.length; cpi++) existingIds[state.products[cpi].id] = true;
      var addedAny = false;
      res.data.forEach(function(row) {
        if (!existingIds[row.data.id]) { state.products.push(row.data); addedAny = true; }
      });
      if (addedAny) { save(); render(); }
    });
}

function getContextualRecommendations(limit, category, sectorKey) {
  if (category) ensureCategoryProductsLoaded(category);
  limit = limit || 9;
  function matchesContext(p) {
    if (category && category !== "Tout") return p.category === category;
    if (sectorKey) {
      if (sectorKey.indexOf("entreprise:") === 0) {
        return p.sellerType === "entreprise" && p.sellerSector === sectorKey.split(":")[1];
      }
      return p.sellerType === sectorKey;
    }
    return true;
  }
  var generalPool = getRecommendations(limit * 3);
  var inContext = generalPool.filter(matchesContext);
  var result = inContext.slice(0, limit);
  if (result.length < limit) {
    var already = result.map(function(p) { return p.id; });
    var restOfGeneral = generalPool.filter(function(p) { return already.indexOf(p.id) === -1; });
    result = result.concat(restOfGeneral.slice(0, limit - result.length));
  }
  if (result.length < limit && (category || sectorKey)) {
    var already2 = result.map(function(p) { return p.id; });
    var moreInContext = state.products.filter(function(p) { return matchesContext(p) && already2.indexOf(p.id) === -1; });
    result = result.concat(moreInContext.slice(0, limit - result.length));
  }
  return result.filter(function(p) { return !isProductHiddenFromPublic(p); }).slice(0, limit);
}

// « Recommandé pour vous » — nouvelle génération : mosaïque (bento).
// 1 grande carte « Coup de cœur » + 2 carrées + 1 large en bas ; le nom et
// le prix sont posés sur la photo (voile sombre en bas pour la lisibilité).
function renderRecommendationsCircles(items) {
  var recoCfg = getSectionStyleConfig("reco_section_config", { title: t("market_section_recommended_default"), textColor: "var(--accent)", shapeColor: "#7bcb3a" });
  var recoTitleStyle = 'font-family:' + SECTION_FONT_FAMILIES[recoCfg.fontFamily] + ';font-weight:' + (recoCfg.bold ? '700' : '400') + ';color:' + recoCfg.textColor + ';font-size:' + recoCfg.fontSize + 'px;';
  var list = items.slice(0, 9);
  var n = Math.min(list.length, 4);
  var html = '<div class="brand-fx-' + recoCfg.effect + '" style="margin-bottom:18px;">';
  html += '<div class="rb-head" style="' + recoTitleStyle + '"><span class="rb-star"><i class="fa-solid fa-star"></i></span> ' + esc(sectionTitleFor(recoCfg, "market_section_recommended_default")) + '</div>';
  html += '<div class="reco-circles-grid reco-bento rb-n' + n + '">';
  for (var i = 0; i < list.length; i++) {
    var p = list[i];
    var kind = i >= 4 ? 'rb-small' : (i === 0 ? 'rb-big' : (i === 3 ? 'rb-wide' : 'rb-small'));
    if (n === 2 && i === 1) kind = 'rb-big';
    var img = (p.images && p.images.length)
      ? '<img loading="lazy" ' + snsThumbSrc(p.images[0]) + ' alt="" style="object-position:' + imagePositionCss(p.imagePositions, 0) + ';" />'
      : '<span class="rb-emoji">' + (p.emoji || '🛍️') + '</span>';
    var price = money(p.price, p.country, state.profile ? state.profile.country : null);
    html += '<div class="reco-circle-item rb-item ' + kind + '" data-action="open-product" data-value="' + p.id + '">';
    if (kind === 'rb-wide') {
      html += '<div class="rb-thumb">' + img + '</div>';
      html += '<div class="rb-info"><div class="rb-name">' + esc(productDisplayName(p)) + '</div>';
      if (p.shopName) html += '<div class="rb-shop"><i class="fa-solid fa-store"></i> ' + esc(p.shopName) + '</div>';
      html += '<div class="rb-price-inline">' + price + '</div></div>';
      html += '<div class="rb-go"><i class="fa-solid fa-arrow-right"></i></div>';
    } else {
      html += '<div class="rb-photo">' + img + '<div class="rb-shade"></div>';
      if (i === 0) html += '<span class="rb-badge"><i class="fa-solid fa-heart"></i> ' + t("reco_top_pick") + '</span>';
      html += '<div class="rb-over"><div class="rb-name">' + esc(productDisplayName(p)) + '</div><span class="rb-price">' + price + '</span></div></div>';
    }
    html += '</div>';
  }
  html += '</div></div>';
  return html;
}

// ---------- CARROUSEL DE RECOMMANDATION INTERCALÉ DANS LE SCROLL DU MARCHÉ ----------
// Fonctions dédiées EXCLUSIVEMENT au bloc de recommandation inséré entre les
// lignes du fil principal du marché (voir renderMarket). Elles ne remplacent
// ni ne modifient renderRecommendationsCircles/getContextualRecommendations,
// utilisées ailleurs (haut du marché, pages catégorie/recherche vide, fiches
// produit) — celles-ci restent strictement inchangées.

// Pioche un lot de `count` produits jamais encore montrés dans un bloc de
// recommandation intercalé pendant cette session de défilement (excludeIds
// contient à la fois les produits déjà recommandés ET ceux déjà visibles
// tels quels dans le fil principal), pour garantir zéro doublon.
function getNextInlineRecoBatch(count, category, sectorKey, excludeIds) {
  var pool = getContextualRecommendations(count * 6, category, sectorKey);
  var result = pool.filter(function(p) { return excludeIds.indexOf(p.id) === -1; });
  if (result.length < count) {
    var already = excludeIds.concat(result.map(function(p) { return p.id; }));
    var fallback = state.products.filter(function(p) { return already.indexOf(p.id) === -1 && !isProductHiddenFromPublic(p); });
    result = result.concat(fallback.slice(0, count - result.length));
  }
  return result.filter(function(p) { return !isProductHiddenFromPublic(p); }).slice(0, count);
}

function renderInlineRecommendationCarousel(items, title) {
  if (!items || items.length === 0) return '';
  var recoCfg = getSectionStyleConfig("reco_section_config", { title: t("market_section_recommended_default"), textColor: "var(--accent)", shapeColor: "#7bcb3a" });
  var titleStyle = 'font-family:' + SECTION_FONT_FAMILIES[recoCfg.fontFamily] + ';font-weight:' + (recoCfg.bold ? '700' : '400') + ';color:' + recoCfg.textColor + ';font-size:' + recoCfg.fontSize + 'px;';
  var html = '<div class="inline-reco-block brand-fx-' + recoCfg.effect + '">';
  html += '<div style="margin-bottom:10px;' + titleStyle + '">' + esc(title) + '</div>';
  html += '<div class="inline-reco-carousel">';
  for (var i = 0; i < items.length; i++) {
    var p = items[i];
    var fav = isFavorite(p.id);
    html += '<div class="inline-reco-card">';
    html += '<div class="inline-reco-img-wrap" data-action="open-product" data-value="' + p.id + '">';
    if (p.images && p.images.length) {
      html += '<img loading="lazy" ' + snsThumbSrc(p.images[0]) + ' alt="' + esc(p.name) + '" style="object-position:' + imagePositionCss(p.imagePositions, 0) + ';" />';
    } else {
      html += '<span class="inline-reco-emoji">' + (p.emoji || '🛍️') + '</span>';
    }
    html += '</div>';
    html += '<button class="inline-reco-fav ' + (fav ? 'active' : '') + '" data-action="toggle-favorite" data-value="' + p.id + '"><i class="fa-' + (fav ? 'solid' : 'regular') + ' fa-heart"></i></button>';
    html += '<div class="inline-reco-title" data-action="open-product" data-value="' + p.id + '">' + esc(productDisplayName(p)) + '</div>';
    html += '<div class="inline-reco-bottom">';
    html += '<span class="inline-reco-price">' + money(p.price, p.country, state.profile ? state.profile.country : null) + '</span>';
    html += '<button class="inline-reco-cart-btn" data-action="quick-add-cart" data-value="' + p.id + '" title="Ajouter au panier" ' + (p.stock <= 0 ? 'disabled' : '') + '><i class="fa-solid fa-cart-plus"></i></button>';
    html += '</div></div>';
  }
  html += '</div></div>';
  return html;
}

