// Étoile "diamant" : silhouette translucide + facettes ombrées + reflet
// qui balaie la pierre à intervalles, façon pierre précieuse taillée.
function renderFacetedStar(uid, active) {
  var clipId = 'star-clip-' + uid;
  var svg = '<svg viewBox="0 0 100 100" class="star-gem-svg">';
  svg += '<defs><clipPath id="' + clipId + '"><path d="' + STAR_SHAPE_PATH + '"/></clipPath></defs>';
  svg += '<g clip-path="url(#' + clipId + ')">';
  svg += '<path class="star-gem-base" d="' + STAR_SHAPE_PATH + '"/>';
  for (var i = 0; i < STAR_FACETS.length; i++) {
    svg += '<path class="star-gem-facet" style="opacity:' + STAR_FACETS[i].o + '" d="' + STAR_FACETS[i].d + '"/>';
  }
  svg += '<rect class="star-gem-shine" x="-40" y="0" width="25" height="100" style="animation-delay:' + ((uid % 5) * 0.6) + 's" />';
  svg += '</g>';
  svg += '<path class="star-gem-outline" d="' + STAR_SHAPE_PATH + '"/>';
  svg += '</svg>';
  return svg;
}

