  relaisapplications: { icon: "fa-shop",               get name() { return t("admin_mod_relais"); },       get sub() { return t("admin_mod_relais_sub"); } },
  livreurapplications:{ icon: "fa-truck-fast",         get name() { return t("admin_mod_livreurs"); },     get sub() { return t("admin_mod_livreurs_sub"); } },
  quartiers:          { icon: "fa-map-location-dot",   get name() { return t("admin_mod_quartiers"); },    get sub() { return t("admin_mod_quartiers_sub"); } },
  messagerie:         { icon: "fa-comments",           get name() { return t("admin_mod_messagerie"); },   get sub() { return t("admin_mod_messagerie_sub"); } },
