  international:      { icon: "fa-earth-africa",        get name() { return t("admin_mod_international"); },get sub() { return t("admin_mod_international_sub"); } },
  security:           { icon: "fa-shield-halved",       get name() { return t("admin_mod_security"); },     get sub() { return t("admin_mod_security_sub"); } },
  reviews:            { icon: "fa-star",                 get name() { return t("admin_mod_reviews"); },      get sub() { return t("admin_mod_reviews_sub"); } },
