function boostTargetLabel(b) {
  if (b.targetType === "shop") return "Toute la boutique";
  for (var i = 0; i < state.products.length; i++) {
    if (state.products[i].id === b.targetId) return state.products[i].name;
  }
  return "Article supprimé";
}

// ---------- ADMIN : AFFICHAGE MARCHÉ ----------
// ---------- ADMIN : FOND D'ÉCRAN (motif décoratif) ----------
function renderAdminBgPattern() {
  var currentTheme = getThemeConfig();
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-palette"></i> Thème de la plateforme</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Un seul thème pour tout le monde — appliqué à tous les utilisateurs, personne d\'autre ne peut le changer.</div>';
  html += '<div class="theme-swatch-row">';
  html += '<button class="theme-swatch ' + (currentTheme === "green-yellow" ? 'active' : '') + '" data-action="set-theme" data-value="green-yellow" style="background:linear-gradient(135deg,#2e7d32,#7bcb3a)" title="Vert Sounsouni"></button>';
  html += '<button class="theme-swatch ' + (currentTheme === "orange-white" ? 'active' : '') + '" data-action="set-theme" data-value="orange-white" style="background:linear-gradient(135deg,#e85d04,#ffffff)" title="Orange + Blanc"></button>';
  html += '<button class="theme-swatch ' + (currentTheme === "red-white" ? 'active' : '') + '" data-action="set-theme" data-value="red-white" style="background:linear-gradient(135deg,#dc3545,#ffffff)" title="Rouge + Blanc"></button>';
  html += '</div>';
  html += '</div>';

  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-rotate-right"></i> Aperçu de l\'introduction</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Affiche immédiatement les 3 pages d\'accueil, même en étant déjà connecté — aucune donnée n\'est touchée (comptes, produits, commandes… tout reste intact, tu n\'es pas déconnecté).</div>';
  html += '<button class="btn-secondary" data-action="replay-intro">Revoir les 3 pages maintenant</button>';
  html += '</div>';

  var scaleOp = getScaleMotifOpacity();
  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-water"></i> Motif écailles Sounsouni</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Le filigrane de base, visible sur toute l\'application — suit automatiquement la couleur du thème.</div>';
  html += '<label class="field-label" style="margin-top:0;">Intensité (' + Math.round(scaleOp * 100) + '%)</label>';
  html += '<input type="range" min="0.02" max="0.4" step="0.01" value="' + scaleOp + '" data-action-input="set-scale-motif-opacity" style="width:100%;" />';
  html += '</div>';

  if (!state.bgPatternWorkingCfg) state.bgPatternWorkingCfg = JSON.parse(JSON.stringify(getBgPatternConfig()));
  var cfg = state.bgPatternWorkingCfg;
  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">';
  html += '<div style="font-weight:800;font-size:14px;">Motif de fond décoratif</div>';
  html += '<div class="toggle-switch ' + (cfg.enabled ? 'active' : '') + '" data-action="toggle-bgpattern-enabled"><div class="toggle-knob"></div></div>';
  html += '</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:14px;">Icônes discrètes en fond de toute l\'application, comme un papier peint léger.</div>';

  html += '<label class="field-label" style="margin-top:0;">Icônes (jusqu\'à 10 emplacements)</label>';
  html += '<div class="bgicon-slots-grid">';
  for (var i = 0; i < 10; i++) {
    var icon = cfg.icons[i];
    html += '<div class="bgicon-slot">';
    if (icon) {
      html += '<img loading="lazy" src="' + icon + '" />';
      html += '<button data-action="remove-bgpattern-icon" data-value="' + i + '"><i class="fa-solid fa-xmark"></i></button>';
    } else {
      html += '<div class="bgicon-slot-empty"><i class="fa-solid fa-plus"></i></div>';
      html += '<input type="file" accept="image/*" data-action-file="bgpattern-icon" data-slot="' + i + '" style="position:absolute;inset:0;opacity:0;cursor:pointer;" />';
    }
    html += '</div>';
  }
  html += '</div>';

  html += '<label class="field-label">Couleur</label>';
  html += '<input class="input" type="color" value="' + esc(cfg.color) + '" data-action-input="bgpattern-color" style="height:38px;padding:4px;max-width:100px;" />';

  html += '<label class="field-label">Opacité (' + Math.round(cfg.opacity * 100) + '%)</label>';
  html += '<input type="range" min="10" max="100" value="' + Math.round(cfg.opacity * 100) + '" data-action-input="bgpattern-opacity" style="width:100%;" />';

  html += '<label class="field-label">Taille des icônes (' + cfg.iconSize + 'px)</label>';
  html += '<input type="range" min="8" max="60" value="' + cfg.iconSize + '" data-action-input="bgpattern-iconsize" style="width:100%;" />';

  html += '<label class="field-label">Densité</label>';
  html += '<input type="range" min="6" max="24" value="' + cfg.density + '" data-action-input="bgpattern-density" style="width:100%;" />';

  html += '<button class="btn-primary" style="margin-top:16px;" data-action="regenerate-bg-pattern">' + (state.bgPatternGenerating ? '<i class="fa-solid fa-spinner fa-spin"></i> Génération…' : '<i class="fa-solid fa-wand-magic-sparkles"></i> Générer et enregistrer') + '</button>';
  if (cfg.generatedPatternUri) {
    html += '<div style="margin-top:14px;"><label class="field-label">Aperçu</label>';
    html += '<div style="height:140px;border-radius:12px;border:1px solid var(--border-color);background-image:url(' + cfg.generatedPatternUri + ');background-repeat:repeat;background-size:140px 140px;"></div></div>';
  }
  html += '</div>';
  return html;
}


function renderAdminMarketDisplay() {
  var cfg = getMarketConfig();
  var currentValue = cfg.newArrivalsValue != null ? cfg.newArrivalsValue : (cfg.newArrivalsDays || 2);
  var currentUnit = cfg.newArrivalsUnit || "days";
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px">';
  html += '<label class="field-label" style="margin-top:0;">Seuil étiquette "Nouveau"</label>';
  html += '<div style="display:flex;gap:8px;">';
  html += '<input class="input" type="number" id="market-new-arrivals-value" min="1" value="' + currentValue + '" style="flex:1;" />';
  html += '<select class="input" id="market-new-arrivals-unit" style="flex:1;">';
  var unitLabels = { seconds: "Secondes", minutes: "Minutes", hours: "Heures", days: "Jours" };
  Object.keys(unitLabels).forEach(function(u) {
    html += '<option value="' + u + '" ' + (currentUnit === u ? "selected" : "") + '>' + unitLabels[u] + '</option>';
  });
  html += '</select>';
  html += '</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-top:6px;">Un produit garde l\'étiquette "Nouveau" sur sa carte pendant cette durée après sa publication. (La section "Tendances" ci-dessous suit désormais les ventes et vues récentes, plus la date.)</div>';
  html += '</div>';

  var toggles = [
    { key: "showRecoCircles", label: "Recommandations (cercles en haut + carrousel intercalé dans le fil)" },
    { key: "showCategoryStars", label: "Catégories (étoiles flottantes)" },
    { key: "showSectorIcons", label: "Icônes secteurs vendeur" },
    { key: "showNewArrivals", label: "Section \"Tendances\"" },
    { key: "showNewTag", label: "Étiquette \"New\" sur les articles récents (Marché & Recherche)" },
    { key: "verifiedBadgeShowAll", label: "Badge \"compte vérifié\" en mode test — tous les comptes (Marché & Recherche)" },
    { key: "ratingBadgeShowAll", label: "Note moyenne en mode test — tous les articles (Marché & Recherche)" }
  ];
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;">Sections visibles sur le marché</div>';
  for (var i = 0; i < toggles.length; i++) {
    var t = toggles[i];
    html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--border-color);">';
    html += '<div style="font-weight:700;font-size:13px;">' + t.label + '</div>';
    html += '<div class="toggle-switch ' + (cfg[t.key] ? 'active' : '') + '" data-action="toggle-market-config" data-value="' + t.key + '"><div class="toggle-knob"></div></div>';
    html += '</div>';
  }
  html += '<button class="btn-primary" style="margin-top:10px;" data-action="save-market-display-config">Enregistrer</button>';

  return html;
}

// Un seul endroit centralisé pour tous les réglages de texte et d'images
// de marque de l'app — plutôt que dispersés dans plusieurs onglets.
// Chaque bloc reste indépendant (section par section), mais on les
// retrouve tous ici, au même endroit.
function renderAdminTextes() {
  var html = '<div style="font-size:12px;color:var(--text-dim);margin-bottom:16px;">Tous les réglages de texte et d\'images de marque de l\'application, réunis ici — plus besoin de les chercher dans plusieurs onglets différents.</div>';

  html += '<div class="divider-dashed" style="margin:0 0 16px;"></div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin:4px 0 8px;">Le bandeau « Livraison partout au Mali » montre maintenant la fourgonnette Sounsouni en 3D : la photo de fond ci-dessous n\'y est plus affichée.</div>';
  html += renderBrandImageAdminSection("delivery_banner_bg_config", "Photo de fond — bandeau \"Livraison partout au Mali\"", { showOverlayToggle: true });
  html += '<div class="divider-dashed" style="margin:20px 0;"></div>';
  html += renderBrandImageAdminSection("header_bg_config", "Photo de fond — en-tête", { showOverlayToggle: true });
  html += '<div class="divider-dashed" style="margin:20px 0;"></div>';
  html += renderBrandImageAdminSection("onboard_watermark_config", "Photo de fond — carte d'inscription", { showFontSizeAndBold: true, showOverlayToggle: true });
  html += renderFrameEditorCard("onboard_watermark_config", getBrandImageConfig("onboard_watermark_config").imageUrl || SOUGOUBA_BANNER_IMG, "Cadrage — carte d'inscription", 1.35);
  html += '<div class="divider-dashed" style="margin:20px 0;"></div>';
  html += renderFrameEditorCard("onboard_top_banner_config", SOUNSOUNI_REG_TOP_BANNER, "Cadrage — bandeau fixe Sounsouni", 2.6);
  html += '<div class="divider-dashed" style="margin:20px 0;"></div>';
  html += renderBrandImageAdminSection("market_banner_config", "Bandeau \"Allah ka Sougoudia\" — marché");
  html += '<div class="divider-dashed" style="margin:20px 0;"></div>';
  html += renderSectionStyleAdminSection("logo_brand_config", "Logo + marque Sounsouni", { textColor: "#f0c56a", glowColor: "212, 175, 55", logoSize: 30 }, { showLogoSize: true });
  html += '<div class="divider-dashed" style="margin:20px 0;"></div>';
  html += renderSectionStyleAdminSection("reco_section_config", "\"Recommandé pour vous\"", { title: "Recommandé pour vous", textColor: "#7bcb3a", shapeColor: "#7bcb3a" }, { showShapeColor: true, showTitleField: true });
  html += '<div class="divider-dashed" style="margin:20px 0;"></div>';
  html += renderSectionStyleAdminSection("category_stars_config", "Catégories (étoiles)", { title: "Catégories", textColor: "#12233f", shapeColor: "#0a5c36" }, { showShapeColor: true, showTitleField: true });
  html += '<div class="divider-dashed" style="margin:20px 0;"></div>';
  html += renderSectionStyleAdminSection("sector_icons_config", "\"Autres vendeurs\"", { title: "Autres vendeurs", textColor: "#12233f", shapeColor: "#7bcb3a" }, { showShapeColor: true, showTitleField: true });
  html += '<div class="divider-dashed" style="margin:20px 0;"></div>';
  html += renderSectionStyleAdminSection("new_arrivals_config", "\"Tendances\"", { title: "Tendances", textColor: "#0a0a0a", glowColor: "30, 80, 160", shapeColor: "#78d2ff" }, { showShapeColor: true, showTitleField: true });

  return html;
}

// Section réutilisable pour gérer une image de marque : photo, opacité,
// effet, style du texte, et activer/désactiver — indépendante pour
// chacune des deux images (inscription et marché).
var BRAND_FX_LABELS = { none: "Aucun", float: "Flottement", pulse: "Pulsation", glint: "Éclat balayant", sway: "Balancement", breathe: "Fondu respirant" };
// Section Admin générique pour régler le style d'une zone du marché
// (texte du titre, police, gras, couleur, halo, couleur des formes, effet,
// afficher/masquer) — réutilisée par les 6 zones personnalisables.
// options: { showLogoSize, showShapeColor, showTitleField }
function renderSectionStyleAdminSection(configId, title, extraDefaults, options) {
  options = options || {};
  var cfg = getSectionStyleConfig(configId, extraDefaults);
  var html = '<div class="glass-card" style="padding:14px;">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">';
  html += '<div style="font-weight:800;font-size:14px;">' + title + '</div>';
  html += '<div class="toggle-switch ' + (cfg.visible ? 'active' : '') + '" data-action="toggle-section-style-visible" data-value="' + configId + '"><div class="toggle-knob"></div></div>';
  html += '</div>';

  if (options.showTitleField) {
    html += '<label class="field-label" style="margin-top:0;">Texte du titre</label>';
    html += '<input type="text" id="title-' + configId + '" class="input" value="' + esc(cfg.title || "") + '" placeholder="' + esc(t(options.titleDefaultKey || "")) + '" data-action-input="section-style-title" data-config="' + configId + '" />';
    html += '<div style="font-size:11px;color:var(--text-dim);margin:4px 0 10px;">Laissez vide pour utiliser la traduction automatique selon la langue du visiteur. Un texte personnalisé restera affiché tel quel, dans toutes les langues. <span data-action="reset-section-style-title" data-value="' + configId + '" style="color:var(--accent);cursor:pointer;font-weight:700;">↺ Réinitialiser (auto)</span></div>';
  }

  if (options.showLogoSize) {
    html += '<label class="field-label" style="margin-top:0;">Taille du logo : ' + cfg.logoSize + 'px</label>';
    html += '<input type="range" min="16" max="60" value="' + cfg.logoSize + '" data-action-input="section-style-logosize" data-config="' + configId + '" style="width:100%;" />';
  }

  html += '<label class="field-label">Police</label>';
  html += '<div style="display:flex;gap:6px;">';
  [["system", "Standard"], ["serif", "Élégante"], ["rounded", "Arrondie"]].forEach(function(f) {
    html += '<button class="chip ' + (cfg.fontFamily === f[0] ? 'active' : '') + '" data-action="set-section-style-field" data-config="' + configId + '" data-field="fontFamily" data-value="' + f[0] + '">' + f[1] + '</button>';
  });
  html += '</div>';

  html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;">';
  html += '<div style="font-weight:700;font-size:13px;">Gras</div>';
  html += '<div class="toggle-switch ' + (cfg.bold ? 'active' : '') + '" data-action="toggle-section-style-bold" data-value="' + configId + '"><div class="toggle-knob"></div></div>';
  html += '</div>';

  html += '<label class="field-label">Taille du texte : ' + cfg.fontSize + 'px</label>';
  html += '<input type="range" min="11" max="26" value="' + cfg.fontSize + '" data-action-input="section-style-fontsize" data-config="' + configId + '" style="width:100%;" />';

  html += '<label class="field-label">Couleur du texte</label>';
  html += '<input type="color" value="' + cfg.textColor + '" data-action-input="section-style-textcolor" data-config="' + configId + '" style="width:100%;height:38px;border-radius:10px;border:1.5px solid var(--border-color);" />';

  if (options.showShapeColor) {
    html += '<label class="field-label">Couleur des formes</label>';
    html += '<input type="color" value="' + cfg.shapeColor + '" data-action-input="section-style-shapecolor" data-config="' + configId + '" style="width:100%;height:38px;border-radius:10px;border:1.5px solid var(--border-color);" />';
  }

  html += '<label class="field-label">Couleur du halo</label>';
  html += '<input type="text" id="glow-' + configId + '" placeholder="Ex : 212, 175, 55" value="' + cfg.glowColor + '" data-action-input="section-style-glowcolor" data-config="' + configId + '" class="input" />';

  html += '<label class="field-label">Effet</label>';
  html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
  Object.keys(BRAND_FX_LABELS).forEach(function(fx) {
    html += '<button class="chip ' + (cfg.effect === fx ? 'active' : '') + '" data-action="set-section-style-field" data-config="' + configId + '" data-field="effect" data-value="' + fx + '">' + BRAND_FX_LABELS[fx] + '</button>';
  });
  html += '</div>';

  html += '<button class="link-btn" style="color:var(--danger);margin-top:12px;" data-action="reset-section-style" data-value="' + configId + '"><i class="fa-solid fa-rotate-left"></i> Réinitialiser</button>';
  html += '</div>';
  return html;
}

// Éditeur visuel de cadrage — 4 poignées aux coins d'un rectangle que
// l'admin peut glisser directement sur un aperçu de la photo, plutôt que
// de deviner avec des curseurs numériques. "Générer" convertit le
// rectangle final en zoom + position et l'enregistre.
function renderFrameEditorCard(configId, imageUrl, title, aspectRatio) {
  var cfg = getBrandImageConfig(configId);
  var boxW = 280;
  var boxH = Math.round(boxW / aspectRatio);
  // Reconstruit un rectangle de départ cohérent avec le zoom/la position
  // actuellement enregistrés, pour que l'admin reparte de l'état réel.
  var w = 100 / (cfg.frameZoom / 100);
  var h = w; // approximation : zoom uniforme
  var x1 = Math.max(0, cfg.framePosX - w / 2);
  var y1 = Math.max(0, cfg.framePosY - h / 2);
  var x2 = Math.min(100, cfg.framePosX + w / 2);
  var y2 = Math.min(100, cfg.framePosY + h / 2);

  var html = '<div class="glass-card" style="padding:14px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:4px;">' + title + '</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:10px;">Glisse les 4 coins sur la zone que tu veux montrer, puis appuie sur "Générer".</div>';
  html += '<div class="frame-editor-box" id="frame-editor-' + configId + '" data-config="' + configId + '" style="width:' + boxW + 'px;height:' + boxH + 'px;background-image:url(\'' + imageUrl + '\');">';
  html += '<div class="frame-editor-dim" data-part="dim-top"></div>';
  html += '<div class="frame-editor-dim" data-part="dim-bottom"></div>';
  html += '<div class="frame-editor-dim" data-part="dim-left"></div>';
  html += '<div class="frame-editor-dim" data-part="dim-right"></div>';
  html += '<div class="frame-editor-rect" data-part="rect"></div>';
  ["tl", "tr", "bl", "br"].forEach(function(corner) {
    html += '<div class="frame-editor-handle" data-corner="' + corner + '" data-config="' + configId + '"></div>';
  });
  html += '</div>';
  html += '<button class="btn-primary" style="margin-top:12px;" data-action="apply-frame-editor" data-config="' + configId + '" data-aspect="' + aspectRatio + '">Générer</button>';
  html += '</div>';
  return html;
}

function renderBrandImageAdminSection(configId, title, options) {
  options = options || {};
  var cfg = getBrandImageConfig(configId);
  var imgSrc = cfg.imageUrl || SOUGOUBA_BANNER_IMG;
  var html = '<div class="glass-card" style="padding:14px;">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">';
  html += '<div style="font-weight:800;font-size:14px;">' + title + '</div>';
  html += '<div class="toggle-switch ' + (cfg.enabled ? 'active' : '') + '" data-action="toggle-brand-image-enabled" data-value="' + configId + '"><div class="toggle-knob"></div></div>';
  html += '</div>';

  html += '<div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">';
  html += '<img loading="lazy" src="' + imgSrc + '" style="width:64px;height:64px;border-radius:10px;object-fit:cover;flex-shrink:0;" />';
  html += '<div style="flex:1;position:relative;">';
  html += '<div class="file-upload-btn" style="text-align:center;border:1.5px dashed var(--border-color);background:var(--bg-body);color:var(--text-secondary);font-size:12px;font-weight:700;padding:10px;border-radius:10px;"><i class="fa-solid fa-image"></i> Changer la photo</div>';
  html += '<input type="file" accept="image/*" data-action-file="brand-image-' + configId + '" style="position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer;" />';
  html += '</div>';
  html += '</div>';

  html += '<label class="field-label" style="margin-top:0;">Opacité : ' + Math.round(cfg.opacity * 100) + '%</label>';
  html += '<input type="range" min="10" max="100" value="' + Math.round(cfg.opacity * 100) + '" data-action-input="brand-image-opacity" data-config="' + configId + '" style="width:100%;" />';

  if (options.showOverlayToggle) {
    html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;">';
    html += '<div><div style="font-weight:700;font-size:13px;">Assombrir la photo</div><div style="font-size:10.5px;color:var(--text-dim);">Pour garder le texte lisible par-dessus</div></div>';
    html += '<div class="toggle-switch ' + (cfg.overlayEnabled ? 'active' : '') + '" data-action="toggle-brand-image-overlay" data-value="' + configId + '"><div class="toggle-knob"></div></div>';
    html += '</div>';
  }

  html += '<label class="field-label">Effet</label>';
  html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
  Object.keys(BRAND_FX_LABELS).forEach(function(fx) {
    html += '<button class="chip ' + (cfg.effect === fx ? 'active' : '') + '" data-action="set-brand-image-field" data-config="' + configId + '" data-field="effect" data-value="' + fx + '">' + BRAND_FX_LABELS[fx] + '</button>';
  });
  html += '</div>';

  if (options.showFrameZoom) {
    html += '<label class="field-label">Cadrage / zoom de la photo : ' + cfg.frameZoom + '%</label>';
    html += '<input type="range" min="40" max="220" value="' + cfg.frameZoom + '" data-action-input="brand-image-framezoom" data-config="' + configId + '" style="width:100%;" />';
    html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:-6px;margin-bottom:10px;">En dessous de 100% : toute la photo est visible. Au-dessus : ça zoome et recadre.</div>';
  }
  if (options.showFrameHeight) {
    html += '<label class="field-label">Hauteur du cadre : ' + cfg.frameHeight + 'px</label>';
    html += '<input type="range" min="60" max="320" value="' + cfg.frameHeight + '" data-action-input="brand-image-frameheight" data-config="' + configId + '" style="width:100%;" />';
  }

  if (options.showFontSizeAndBold) {
    html += '<label class="field-label">Taille du texte : ' + cfg.fontSize + 'px</label>';
    html += '<input type="range" min="14" max="40" value="' + cfg.fontSize + '" data-action-input="brand-image-fontsize" data-config="' + configId + '" style="width:100%;" />';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;">';
    html += '<div style="font-weight:700;font-size:13px;">Gras</div>';
    html += '<div class="toggle-switch ' + (cfg.bold ? 'active' : '') + '" data-action="toggle-brand-image-bold" data-value="' + configId + '"><div class="toggle-knob"></div></div>';
    html += '</div>';
  }

  html += '<label class="field-label">Couleur du texte</label>';
  html += '<input type="color" value="' + cfg.textColor + '" data-action-input="brand-image-textcolor" data-config="' + configId + '" style="width:100%;height:38px;border-radius:10px;border:1.5px solid var(--border-color);" />';

  html += '<label class="field-label">Couleur du halo (contraste)</label>';
  html += '<input type="text" id="glowcolor-' + configId + '" placeholder="Ex : 212, 175, 55 (doré)" value="' + cfg.glowColor + '" data-action-input="brand-image-glowcolor" data-config="' + configId + '" class="input" />';
  html += '<div style="font-size:10px;color:var(--text-dim);margin-top:4px;">Format : Rouge, Vert, Bleu — ex : 212, 175, 55 pour un doré, 255, 122, 26 pour un orange.</div>';

  html += '<button class="link-btn" style="color:var(--danger);margin-top:12px;" data-action="reset-brand-image" data-value="' + configId + '"><i class="fa-solid fa-rotate-left"></i> Réinitialiser cette image</button>';
  html += '</div>';
  return html;
}

// ---------- ADMIN : PUB VIP ----------
function renderAdminVipAds() {
  var d = state.vipAdDraft;
  var editing = !!state.editingVipAdId;
  var vcfg = getVipConfig();

  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;">Réglages généraux de l\'espace VIP</div>';
  html += '<label class="field-label" style="margin-top:0;">Alignement</label>';
  html += '<div style="display:flex;gap:6px;">';
  ['left', 'center', 'right'].forEach(function(al) {
    var alLabel = al === 'left' ? 'Gauche' : (al === 'center' ? 'Centre' : 'Droite');
    html += '<button class="chip ' + (vcfg.alignment === al ? 'active' : '') + '" data-action="set-vip-config" data-key="alignment" data-value="' + al + '">' + alLabel + '</button>';
  });
  html += '</div>';
  html += '<label class="field-label">Comportement (s\'il y a plusieurs pubs actives)</label>';
  html += '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
  html += '<button class="chip ' + (vcfg.scrollMode === 'rotate' ? 'active' : '') + '" data-action="set-vip-config" data-key="scrollMode" data-value="rotate">Rotation (une à la fois)</button>';
  html += '<button class="chip ' + (vcfg.scrollMode === 'scroll' ? 'active' : '') + '" data-action="set-vip-config" data-key="scrollMode" data-value="scroll">Défilement continu</button>';
  html += '</div>';
  html += '<label class="field-label">Temps entre chaque pub (secondes)</label>';
  html += '<input class="input" type="number" min="2" id="vip-rotation-input" value="' + vcfg.rotationSeconds + '" style="max-width:100px;" />';
  html += '<button class="link-btn" style="margin-top:8px;" data-action="save-vip-rotation-seconds">Enregistrer ce temps</button>';
  html += '</div>';

  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;">' + (editing ? 'Modifier la publicité' : 'Nouvelle publicité VIP') + '</div>';
  html += '<label class="field-label" style="margin-top:0;">Titre *</label>';
  html += '<input class="input" placeholder="Ex : Canal+ — Offre spéciale" value="' + esc(d.title) + '" data-bind="vipAdDraft.title" />';
  html += '<label class="field-label">Description</label>';
  html += '<input class="input" placeholder="Ex : -20% ce mois-ci" value="' + esc(d.description) + '" data-bind="vipAdDraft.description" />';

  html += '<label class="field-label">Image (optionnel — remplace l\'emoji)</label>';
  if (d.imageUrl) {
    html += '<div style="position:relative;width:100%;height:90px;border-radius:10px;overflow:hidden;margin-top:4px;">';
    html += '<img loading="lazy" src="' + esc(d.imageUrl) + '" style="width:100%;height:100%;object-fit:cover;" />';
    html += '<button data-action="remove-vipad-image" style="position:absolute;top:4px;right:4px;width:22px;height:22px;border-radius:50%;background:rgba(0,0,0,0.6);color:white;border:none;font-size:10px;"><i class="fa-solid fa-xmark"></i></button>';
    html += '</div>';
  } else {
    html += '<div style="position:relative;margin-top:4px;">';
    html += '<div class="file-upload-btn" style="display:flex;align-items:center;justify-content:center;gap:8px;border:1.5px dashed var(--border-color);background:var(--bg-body);color:var(--text-secondary);font-size:13px;font-weight:700;padding:12px;border-radius:12px;">';
    html += '<i class="fa-solid fa-image"></i> Choisir une image';
    html += '</div>';
    html += '<input type="file" accept="image/*" data-action-file="vipad-image" style="position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer;" />';
    html += '</div>';
  }
  html += '<label class="field-label">Emoji / icône (utilisé si pas d\'image)</label>';
  html += '<input class="input" placeholder="⭐" value="' + esc(d.emoji) + '" data-bind="vipAdDraft.emoji" style="max-width:80px;" />';

  html += '<div style="display:flex;gap:10px;">';
  html += '<div style="flex:1;"><label class="field-label">Couleur du texte</label><input class="input" type="color" value="' + esc(d.textColor || '#ffffff') + '" data-bind="vipAdDraft.textColor" style="height:38px;padding:4px;" /></div>';
  html += '<div style="flex:1;"><label class="field-label">Couleur de fond</label><input class="input" type="color" value="' + esc(d.bgColor || '#0a5c36') + '" data-bind="vipAdDraft.bgColor" style="height:38px;padding:4px;" /></div>';
  html += '</div>';
  html += '<label class="field-label">Effet visuel</label>';
  html += '<select class="input" data-bind="vipAdDraft.effect">';
  html += '<option value="none" ' + (d.effect === 'none' ? 'selected' : '') + '>Aucun</option>';
  html += '<option value="fade" ' + (d.effect === 'fade' ? 'selected' : '') + '>Fondu</option>';
  html += '<option value="pulse" ' + (d.effect === 'pulse' ? 'selected' : '') + '>Pulsation</option>';
  html += '<option value="shine" ' + (d.effect === 'shine' ? 'selected' : '') + '>Lueur qui traverse</option>';
  html += '</select>';

  html += '<label class="field-label">Lien (optionnel)</label>';
  html += '<input class="input" placeholder="https://…" value="' + esc(d.link) + '" data-bind="vipAdDraft.link" />';
  html += '<div style="display:flex;gap:10px;">';
  html += '<div style="flex:1;min-width:0;"><label class="field-label">Début</label><input class="input" type="date" style="min-width:0;width:100%;" value="' + esc(d.startDate) + '" data-bind="vipAdDraft.startDate" /></div>';
  html += '<div style="flex:1;min-width:0;"><label class="field-label">Fin</label><input class="input" type="date" style="min-width:0;width:100%;" value="' + esc(d.endDate) + '" data-bind="vipAdDraft.endDate" /></div>';
  html += '</div>';
  html += '<label style="display:flex;align-items:center;gap:8px;margin-top:12px;font-size:12.5px;cursor:pointer;"><input type="checkbox" data-action="toggle-vipad-draft-active" ' + (d.active ? 'checked' : '') + ' /> Active</label>';
  html += '<div style="display:flex;gap:8px;margin-top:14px;">';
  html += '<button class="btn-primary" style="flex:1;" data-action="submit-vip-ad">' + (editing ? 'Enregistrer' : 'Créer la publicité') + '</button>';
  if (editing) html += '<button class="btn-secondary" style="flex:0;width:auto;padding:0 16px;" data-action="cancel-edit-vip-ad">' + t("cancel_generic") + '</button>';
  html += '</div></div>';

  var vipCollapsed = !!state.collapsedAdminSections.vipAdsList;
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;"><div style="font-weight:800;font-size:14px;">Publicités (' + state.vipAds.length + ')</div><button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="vipAdsList"><i class="fa-solid ' + (vipCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button></div>';
  if (state.vipAds.length === 0) {
    html += '<div class="empty-state"><i class="fa-solid fa-crown"></i><div class="title">Aucune publicité VIP pour l\'instant</div></div>';
  } else if (!vipCollapsed) {
    if (state.vipAds.length > 6) html += '<input class="input" style="margin-bottom:10px;" placeholder="Rechercher une publicité (titre)…" value="' + esc(state.adminVipAdsSearch || "") + '" data-action-input="admin-vipads-search" />';
    var vipSearch = (state.adminVipAdsSearch || "").toLowerCase().trim();
    var vipAdsToShow = vipSearch ? state.vipAds.filter(function(a) { return (a.title || "").toLowerCase().indexOf(vipSearch) !== -1; }) : state.vipAds;
    for (var i = 0; i < vipAdsToShow.length; i++) {
      var ad = vipAdsToShow[i];
      var isActiveNow = isVipAdActive(ad);
      html += '<div class="card-row">';
      if (ad.imageUrl) html += '<img loading="lazy" src="' + esc(ad.imageUrl) + '" style="width:40px;height:40px;border-radius:8px;object-fit:cover;" />';
      else html += '<div class="emoji-thumb">' + esc(ad.emoji || '⭐') + '</div>';
      html += '<div style="flex:1;">';
      html += '<div style="font-weight:700;font-size:13px;">' + esc(ad.title) + '</div>';
      html += '<div style="font-size:11px;color:var(--text-dim);">' + (ad.startDate || '—') + ' → ' + (ad.endDate || '—') + '</div>';
      html += '<span class="status-pill" style="' + (isActiveNow ? 'background:rgba(46,158,79,0.15);color:#2e9e4f;' : '') + 'font-size:9.5px;margin-top:4px;display:inline-block;">' + (isActiveNow ? 'En ligne' : (ad.active ? 'Programmée/expirée' : 'Désactivée')) + '</span>';
      html += '</div>';
      html += '<button class="link-btn" data-action="edit-vip-ad" data-value="' + ad.id + '"><i class="fa-solid fa-pen"></i></button>';
      html += '<button class="link-btn" style="color:var(--danger);" data-action="delete-vip-ad" data-value="' + ad.id + '"><i class="fa-solid fa-trash"></i></button>';
      html += '</div>';
    }
  }
  return html;
}

function renderAdminBoosts() {
  var cfg = getBoostConfig();
  var pending = state.boosts.filter(function(b) { return b.status === "en_attente"; });
  var active = state.boosts.filter(function(b) { return isBoostActive(b); });

  // ---- Revenu Boosts — comptabilisé séparément du Revenu GEMS, sur
  // demande explicite. Un boost compte comme "payé" dès que son statut
  // est "actif" (paiement confirmé), qu'il soit encore en cours ou déjà
  // expiré depuis — jamais les "en_attente" ou "refuse".
  var confirmedBoosts = state.boosts.filter(function(b) { return b.status === "actif" && inAdminScope(b); });
  var totalBoostRevenue = confirmedBoosts.reduce(function(sum, b) { return sum + (b.price || 0); }, 0);
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-sack-dollar"></i> Revenu Boosts</div>';
  html += '<div class="mono" style="font-size:24px;font-weight:700;color:var(--mc-green,var(--accent));">' + money(totalBoostRevenue, state.adminCountryScope) + '</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-top:2px;">' + confirmedBoosts.length + ' achat(s) confirmé(s) au total</div>';
  html += '<div class="divider-dashed" style="margin:14px 0;"></div>';
  var boostsCollapsed = !!state.collapsedAdminSections.boostsHistory;
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><div style="font-weight:700;font-size:12px;">Historique des achats</div><button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="boostsHistory"><i class="fa-solid ' + (boostsCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button></div>';
  if (confirmedBoosts.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim);">Aucun achat confirmé pour l\'instant.</div>';
  } else if (!boostsCollapsed) {
    if (confirmedBoosts.length > 8) html += '<input class="input" style="margin-bottom:10px;" placeholder="Rechercher un vendeur…" value="' + esc(state.adminBoostsSearch || "") + '" data-action-input="admin-boosts-search" />';
    var boostsSearch = (state.adminBoostsSearch || "").toLowerCase().trim();
    var sortedBoosts = confirmedBoosts.slice().sort(function(a, b) { return (b.activatedAt || b.createdAt) - (a.activatedAt || a.createdAt); });
    if (boostsSearch) sortedBoosts = sortedBoosts.filter(function(sb) { return (sb.sellerName || "").toLowerCase().indexOf(boostsSearch) !== -1; });
    for (var sbi = 0; sbi < Math.min(sortedBoosts.length, 20); sbi++) {
      var sb = sortedBoosts[sbi];
      html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:1px solid var(--border-color);font-size:12px;">';
      html += '<div><div style="font-weight:600;">' + esc(sb.sellerName || 'Vendeur') + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + boostTargetLabel(sb) + ' · ' + sb.days + ' jour(s) · ' + fmtDateTime(sb.activatedAt || sb.createdAt) + '</div></div>';
      html += '<div class="mono" style="font-weight:700;">' + money(sb.price, sb.country) + '</div>';
      html += '</div>';
    }
    if (sortedBoosts.length > 20) html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:8px;">+ ' + (sortedBoosts.length - 20) + ' autre(s) achat(s) plus ancien(s)</div>';
  }
  html += '</div>';

  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px">';
  html += '<label class="field-label">Mode de validation des paiements</label>';
  html += '<div style="display:flex;flex-direction:column;gap:8px;margin-top:6px;">';
  var modes = [
    { key: "auto", label: "Automatique (mode test)", desc: "Activation immédiate, sans vérification — le boost est gratuit tant que ce mode est actif." },
    { key: "manual", label: "Manuel", desc: "Vous confirmez vous-même chaque paiement reçu, ci-dessous." },
    { key: "api", label: "Orange Money / Moov Money (LigdiCash)", desc: "Le vendeur paie son boost par Orange Money ou Moov Money ; le boost s'active tout seul dès que le paiement est confirmé." }
  ];
  for (var m = 0; m < modes.length; m++) {
    var md = modes[m];
    html += '<button class="boost-mode-card ' + (cfg.mode === md.key ? 'active' : '') + '" data-action="set-boost-mode" data-value="' + md.key + '">';
    html += '<div style="font-weight:700;font-size:13px;">' + (cfg.mode === md.key ? '<i class="fa-solid fa-circle-check"></i> ' : '') + md.label + '</div>';
    html += '<div style="font-size:11px;color:var(--text-dim);margin-top:2px;">' + md.desc + '</div>';
    html += '</button>';
  }
  html += '</div></div>';

  if (pending.length > 0) {
    html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;">En attente de confirmation (' + pending.length + ')</div>';
    for (var p = 0; p < pending.length; p++) {
      var b = pending[p];
      html += '<div class="card-row" style="flex-direction:column;align-items:stretch">';
      html += '<div style="display:flex;justify-content:space-between;font-size:13px;"><span style="font-weight:700;">' + esc(boostTargetLabel(b)) + '</span><span>' + money(b.price) + '</span></div>';
      html += '<div style="font-size:11.5px;color:var(--text-dim);margin:4px 0;cursor:pointer;" data-action="open-admin-account-detail" data-value="' + b.sellerId + '">' + esc(b.sellerName) + ' · ' + b.days + ' jour(s) <i class="fa-solid fa-arrow-up-right-from-square" style="font-size:9px;"></i></div>';
      html += '<div style="display:flex;gap:8px;margin-top:6px;">';
      html += '<button class="btn-primary" style="flex:1;padding:8px;font-size:12.5px;" data-action="confirm-boost-payment" data-value="' + b.id + '"><i class="fa-solid fa-check"></i> Confirmer le paiement</button>';
      html += '<button class="link-btn" style="color:var(--danger)" data-action="reject-boost-payment" data-value="' + b.id + '">Refuser</button>';
      html += '</div></div>';
    }
  }

  html += '<div style="font-weight:800;font-size:14px;margin:18px 0 10px;">Boosts actifs (' + active.length + ')</div>';
  if (active.length === 0) {
    html += '<div style="font-size:12.5px;color:var(--text-dim);">Aucun boost actif pour l\'instant.</div>';
  } else {
    for (var a = 0; a < active.length; a++) {
      var ba = active[a];
      var hoursLeft = Math.max(0, Math.round((ba.expiresAt - Date.now()) / 3600000));
      html += '<div class="card-row" style="cursor:pointer;" data-action="open-admin-account-detail" data-value="' + ba.sellerId + '"><div class="emoji-thumb"><i class="fa-solid fa-rocket"></i></div><div style="flex:1;"><div style="font-weight:700;font-size:13px;">' + esc(boostTargetLabel(ba)) + '</div><div style="font-size:11px;color:var(--text-dim);">' + esc(ba.sellerName) + ' · expire dans ' + hoursLeft + 'h</div></div><div style="font-weight:700;font-size:13px;margin-right:8px;">' + money(ba.price) + '</div><button class="link-btn" style="color:var(--danger);" data-action="admin-cancel-boost" data-value="' + ba.id + '"><i class="fa-solid fa-trash"></i></button></div>';
    }
  }

  var algoCfg = getAlgorithmConfig();
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;margin:20px 0 10px;box-shadow:var(--shadow);">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:4px;"><i class="fa-solid fa-sliders"></i> Algorithme du marché</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:10px;">Équilibre entre pertinence personnelle, découverte, et boost — pour que plateforme, vendeurs et acheteurs y trouvent tous leur compte.</div>';
  html += '<label class="field-label" style="margin-top:0;">Part de découverte dans le marché (%) — produits hors historique</label>';
  html += '<input class="input" type="number" id="algo-discovery-ratio" min="0" max="100" value="' + Math.round(algoCfg.marketDiscoveryRatio * 100) + '" />';
  html += '<label class="field-label">Part large des articles boostés (%) — visible même sans historique pertinent</label>';
  html += '<input class="input" type="number" id="algo-boost-broad-ratio" min="0" max="100" value="' + Math.round(algoCfg.boostBroadRatio * 100) + '" />';
  html += '<label class="field-label">Rythme d\'injection du boost — 1 article boosté tous les :</label>';
  html += '<input class="input" type="number" id="algo-boost-rate" min="2" max="50" value="' + algoCfg.boostInjectionRate + '" />';
  html += '<button class="btn-primary" style="margin-top:12px;" data-action="save-algorithm-config"><i class="fa-solid fa-save"></i> Enregistrer</button>';
  html += '</div>';

  html += '<div style="font-weight:800;font-size:14px;margin:20px 0 10px;">Forfaits — Article/service</div>';
  for (var it = 0; it < cfg.itemTiers.length; it++) {
    html += renderBoostTierRow('itemTiers', it, cfg.itemTiers[it]);
  }
  html += '<button class="link-btn" data-action="add-boost-tier" data-value="itemTiers"><i class="fa-solid fa-plus"></i> Ajouter un forfait</button>';

  html += '<div style="font-weight:800;font-size:14px;margin:20px 0 10px;">Forfaits — Boutique entière</div>';
  for (var st = 0; st < cfg.shopTiers.length; st++) {
    html += renderBoostTierRow('shopTiers', st, cfg.shopTiers[st]);
  }
  html += '<button class="link-btn" data-action="add-boost-tier" data-value="shopTiers"><i class="fa-solid fa-plus"></i> Ajouter un forfait</button>';

  html += '<button class="btn-primary" style="margin-top:16px;" data-action="save-boost-tiers"><i class="fa-solid fa-floppy-disk"></i> Enregistrer les forfaits</button>';
  return html;
}

function renderBoostTierRow(groupKey, index, tier) {
  var html = '<div class="card-row" style="align-items:center;">';
  html += '<div style="display:flex;flex-direction:column;gap:2px;margin-right:8px;"><label style="font-size:9.5px;color:var(--text-dim);">Jours</label>';
  html += '<input class="input" style="width:80px;padding:6px 8px;" type="number" id="boost-days-' + groupKey + '-' + index + '" value="' + tier.days + '" /></div>';
  html += '<div style="display:flex;flex-direction:column;gap:2px;flex:1;"><label style="font-size:9.5px;color:var(--text-dim);">Prix (FCFA)</label>';
  html += '<input class="input" style="padding:6px 8px;" type="number" id="boost-price-' + groupKey + '-' + index + '" value="' + tier.price + '" /></div>';
  html += '<button class="link-btn" style="color:var(--danger);margin-left:8px;" data-action="remove-boost-tier" data-target-type="' + groupKey + '" data-value="' + index + '"><i class="fa-solid fa-trash"></i></button>';
  html += '</div>';
  return html;
}

// ---------- ADMIN : POINTS DE VENTE (commissions & reversements) ----------
// ---------- ADMIN : DEMANDES POINT DE RETRAIT ----------
// ---------- ADMIN : GESTION DES QUARTIERS/COMMUNES ----------
// Un champ GPS réutilisable pour un des 7 points d'un quartier — bouton
// carte cliquable (réutilise la carte déjà en local) + collage direct.
function renderQuartierPointField(qKey, pointType, label, point) {
  var pickerKey = qKey + "|" + pointType;
  var html = '<label class="field-label" style="font-size:10.5px;">' + label + '</label>';
  html += '<div style="display:flex;gap:6px;">';
  html += '<button type="button" class="btn-secondary" style="flex:1;padding:6px 10px;font-size:11.5px;" data-action="open-quartier-map-picker" data-value="' + esc(pickerKey) + '"><i class="fa-solid fa-map-location-dot"></i> ' + (point && point.lat != null ? 'Modifier sur la carte' : 'Choisir sur la carte') + '</button>';
  html += '</div>';
  html += '<input class="input" data-quartier-gps-paste-v2="' + esc(pickerKey) + '" style="margin-top:6px;padding:6px 10px;font-size:11.5px;" placeholder="' + t("quartier_paste_coords") + '" />';
  html += '<input type="hidden" id="qp-' + pointType + '-lat-' + esc(qKey) + '" value="' + (point && point.lat != null ? point.lat : '') + '" />';
  html += '<input type="hidden" id="qp-' + pointType + '-lng-' + esc(qKey) + '" value="' + (point && point.lng != null ? point.lng : '') + '" />';
  if (point && point.lat != null) {
    html += '<div style="font-size:9.5px;color:var(--success);margin-top:2px;">✓ ' + point.lat.toFixed(4) + ', ' + point.lng.toFixed(4) + '</div>';
  }
  return html;
}

function renderAdminQuartiers() {
  var data = getQuartiersData();
  var communes = Object.keys(data);
  var undoCount = (state.quartierUndoStack || []).length;
  var html = '';

  html += '<button class="btn-secondary" style="width:100%;margin-bottom:14px;" data-action="undo-quartier-change" ' + (undoCount === 0 ? 'disabled' : '') + '><i class="fa-solid fa-rotate-left"></i> ' + t("ad_undo_last_action") + (undoCount > 0 ? ' (' + undoCount + t("ad_available_word") + (undoCount > 1 ? 's' : '') + ')' : '') + '</button>';

  // ---- Réglage global de majoration (s'applique à tous les quartiers) ----
  var surchargeCfg = getQuartierSurchargeConfig();
  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">';
  html += '<div style="font-weight:800;font-size:14px;"><i class="fa-solid fa-route"></i> ' + t("ad_surcharge_title") + '</div>';
  html += '<div class="toggle-switch ' + (surchargeCfg.enabled ? 'active' : '') + '" data-action="toggle-quartier-surcharge"><div class="toggle-knob"></div></div>';
  html += '</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">' + t("ad_surcharge_hint") + '</div>';
  html += '<label class="field-label" style="margin-top:0;">' + t("ad_surcharge_threshold") + '</label>';
  html += '<input class="input" type="number" id="surcharge-threshold-input" value="' + surchargeCfg.thresholdKm + '" ' + (!surchargeCfg.enabled ? 'disabled' : '') + ' />';
  html += '<label class="field-label">' + t("ad_surcharge_perkm") + '</label>';
  html += '<input class="input" type="number" id="surcharge-perkm-input" value="' + surchargeCfg.perKmSurcharge + '" ' + (!surchargeCfg.enabled ? 'disabled' : '') + ' />';
  html += '<button class="btn-secondary" style="margin-top:10px;" data-action="save-quartier-surcharge-config">' + t("ad_save") + '</button>';
  html += '</div>';

  // ---- Propositions "Autre quartier" en attente ----
  var pendingQ = state.autreQuartierApplications.filter(function(q) { return q.status === "pending" && inAdminScope(q); });
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-inbox"></i> ' + t("ad_user_proposals") + pendingQ.length + ')</div>';
  if (pendingQ.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:16px;">' + t("ad_no_pending_proposal") + '</div>';
  } else {
    for (var i = 0; i < pendingQ.length; i++) {
      var q = pendingQ[i];
      html += '<div class="glass-card" style="padding:12px;margin-bottom:10px;">';
      html += '<div style="font-weight:700;font-size:13px;">' + esc(q.quartierNom) + '</div>';
      html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:8px;">' + t("ad_proposed_by") + esc(q.accountName) + (q.lat != null ? ' · 📍 ' + q.lat.toFixed(5) + ', ' + q.lng.toFixed(5) : '') + '</div>';
      html += '<label class="field-label" style="margin-top:0;font-size:11px;">' + t("ad_attach_to_commune") + '</label>';
      html += '<select class="input" id="quartier-app-commune-' + q.id + '" style="margin-bottom:8px;">';
      for (var ci = 0; ci < communes.length; ci++) html += '<option value="' + communes[ci] + '">' + communes[ci] + '</option>';
      html += '</select>';
      html += '<div style="display:flex;gap:8px;">';
      html += '<button class="btn-primary" style="flex:1;padding:9px;font-size:12.5px;" data-action="approve-autre-quartier" data-value="' + q.id + '"><i class="fa-solid fa-check"></i> ' + t("ad_add_to_list") + '</button>';
      html += '<button class="btn-secondary" style="flex:1;padding:9px;font-size:12.5px;color:var(--danger);border-color:var(--danger);" data-action="reject-autre-quartier" data-value="' + q.id + '"><i class="fa-solid fa-xmark"></i> ' + t("ad_refuse") + '</button>';
      html += '</div></div>';
    }
  }

  html += '<div class="divider-dashed" style="margin:16px 0;"></div>';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">';
  html += '<div style="font-weight:800;font-size:14px;"><i class="fa-solid fa-map"></i> ' + t("ad_current_list") + '</div>';
  var quartiersCollapsed = !!state.collapsedAdminSections.quartiersList;
  html += '<button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="quartiersList"><i class="fa-solid ' + (quartiersCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button>';
  html += '</div>';

  // ---- Ajouter une commune ----
  html += '<div style="display:flex;gap:8px;margin-bottom:14px;">';
  html += '<input class="input" id="new-commune-name" placeholder="' + t("ad_new_commune_placeholder") + '" style="flex:1;" />';
  html += '<button class="btn-secondary" style="width:auto;padding:0 14px;" data-action="admin-add-commune"><i class="fa-solid fa-plus"></i></button>';
  html += '</div>';

  var quartiersSearch = (state.adminQuartiersSearch || "").toLowerCase().trim();
  var communesToShow = communes;
  if (quartiersSearch) {
    communesToShow = communes.filter(function(c) {
      if (c.toLowerCase().indexOf(quartiersSearch) !== -1) return true;
      return (data[c] || []).some(function(q) { return q.toLowerCase().indexOf(quartiersSearch) !== -1; });
    });
  }
  if (communes.length > 4) html += '<input class="input" style="margin-bottom:14px;" placeholder="' + t("ad_search_commune_quartier") + '" value="' + esc(state.adminQuartiersSearch || "") + '" data-action-input="admin-quartiers-search" />';

  if (!quartiersCollapsed) {
  for (var ci2 = 0; ci2 < communesToShow.length; ci2++) {
    var commune = communesToShow[ci2];
    html += '<div class="glass-card" style="padding:12px;margin-bottom:10px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
    html += '<div style="font-weight:800;font-size:13.5px;">' + esc(commune) + '</div>';
    html += '<button class="link-btn" style="color:var(--danger);font-size:11px;" data-action="admin-remove-commune" data-value="' + esc(commune) + '"><i class="fa-solid fa-trash"></i> ' + t("ad_delete_commune") + '</button>';
    html += '</div>';
    var qs = data[commune];
    for (var qi = 0; qi < qs.length; qi++) {
      var qKey = quartierPricingKey(commune, qs[qi]);
      var qPricing = getQuartierPricing(commune, qs[qi]);
      var qExpanded = state.expandedQuartierPricing && state.expandedQuartierPricing[qKey];
      html += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;">';
      html += '<input class="input" style="flex:1;padding:6px 10px;font-size:12px;" value="' + esc(qs[qi]) + '" data-action="admin-rename-quartier" data-commune="' + esc(commune) + '" data-old-name="' + esc(qs[qi]) + '" />';
      html += '<button class="link-btn" style="font-size:11px;' + (qPricing && qPricing.basePrice != null ? 'color:var(--success);' : '') + '" data-action="toggle-quartier-pricing" data-value="' + esc(qKey) + '"><i class="fa-solid fa-tag"></i> ' + t("ad_tarif_btn") + '</button>';
      html += '<button class="link-btn" style="color:var(--danger);" data-action="admin-remove-quartier" data-commune="' + esc(commune) + '" data-value="' + esc(qs[qi]) + '"><i class="fa-solid fa-xmark"></i></button>';
      html += '</div>';
      if (qExpanded) {
        html += '<div style="background:var(--bg-body);border-radius:10px;padding:10px;margin:-2px 0 10px;">';
        html += '<label class="field-label" style="margin-top:0;font-size:10.5px;">' + t("ad_verified_price") + '</label>';
        html += '<input class="input" type="number" id="qp-price-' + esc(qKey) + '" style="padding:6px 10px;font-size:12px;" value="' + (qPricing && qPricing.basePrice != null ? qPricing.basePrice : '') + '" placeholder="Ex : 1500" />';

        html += '<div class="divider-dashed" style="margin:12px 0;"></div>';
        html += '<div style="font-weight:800;font-size:12px;margin-bottom:6px;"><i class="fa-solid fa-draw-polygon"></i> ' + t("ad_quartier_limits") + '</div>';
        html += '<div style="font-size:9.5px;color:var(--text-dim);margin-bottom:8px;">' + t("ad_quartier_limits_hint") + '</div>';
        html += renderQuartierPointField(qKey, "north", t("ad_point_north"), qPricing && qPricing.north);
        html += renderQuartierPointField(qKey, "south", t("ad_point_south"), qPricing && qPricing.south);
        html += renderQuartierPointField(qKey, "east", t("ad_point_east"), qPricing && qPricing.east);
        html += renderQuartierPointField(qKey, "west", t("ad_point_west"), qPricing && qPricing.west);

        html += '<div class="divider-dashed" style="margin:12px 0;"></div>';
        html += '<div style="font-weight:800;font-size:12px;margin-bottom:6px;"><i class="fa-solid fa-scissors"></i> ' + t("ad_split_line") + '</div>';
        html += '<div style="font-size:9.5px;color:var(--text-dim);margin-bottom:8px;">' + t("ad_split_line_hint") + '</div>';
        html += renderQuartierPointField(qKey, "line1", t("ad_line_point1"), qPricing && qPricing.linePoint1);
        html += renderQuartierPointField(qKey, "line2", t("ad_line_point2"), qPricing && qPricing.linePoint2);
        html += '<label class="field-label" style="font-size:10.5px;">' + t("ad_which_side") + '</label>';
        html += '<div style="display:flex;gap:6px;">';
        html += '<button type="button" class="chip ' + (!qPricing || qPricing.surchargeSide !== 'b' ? 'active' : '') + '" data-action="set-quartier-surcharge-side" data-value="' + esc(qKey) + '" data-side="a">' + t("ad_side_a") + '</button>';
        html += '<button type="button" class="chip ' + (qPricing && qPricing.surchargeSide === 'b' ? 'active' : '') + '" data-action="set-quartier-surcharge-side" data-value="' + esc(qKey) + '" data-side="b">' + t("ad_side_b") + '</button>';
        html += '</div>';
        html += '<input type="hidden" id="qp-surchargeside-' + esc(qKey) + '" value="' + (qPricing && qPricing.surchargeSide ? qPricing.surchargeSide : 'a') + '" />';
        html += '<div style="font-size:9.5px;color:var(--text-dim);margin-top:4px;">' + t("ad_side_tip") + '</div>';

        html += '<div class="divider-dashed" style="margin:12px 0;"></div>';
        html += '<button class="btn-primary" style="padding:8px;font-size:12px;" data-action="save-quartier-pricing" data-value="' + esc(qKey) + '">' + t("ad_save_this_quartier") + '</button>';
        html += '</div>';
      }
    }
    html += '<div style="display:flex;gap:6px;margin-top:8px;">';
    html += '<input class="input" id="new-quartier-' + esc(commune) + '" placeholder="' + t("ad_add_quartier_placeholder") + '" style="flex:1;padding:6px 10px;font-size:12px;" />';
    html += '<button class="link-btn" data-action="admin-add-quartier" data-value="' + esc(commune) + '"><i class="fa-solid fa-plus"></i></button>';
    html += '</div>';
    html += '</div>';
  }
  }

  // ---- "Quartiers proches" (hors limites officielles) + Zone Kati-ville ----
  html += '<div class="divider-dashed" style="margin:20px 0 14px;"></div>';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">';
  html += '<div style="font-weight:800;font-size:14px;"><i class="fa-solid fa-map-location-dot"></i> Quartiers proches (hors Communes officielles)</div>';
  var prochesCollapsed = !!state.collapsedAdminSections.quartiersProchesList;
  html += '<button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="quartiersProchesList"><i class="fa-solid ' + (prochesCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button>';
  html += '</div>';
  html += '<div style="font-size:10.5px;color:var(--text-dim);margin-bottom:10px;">Secteurs qui apparaissent dans le sélecteur d\'adresse sous "Quartier proche de la Commune X" — n\'importe qui peut choisir son quartier ici même s\'il n\'est pas officiellement dans une Commune de Bamako.</div>';
  var prochesUndoCount = (state.quartierProcheUndoStack || []).length;
  html += '<button class="btn-secondary" style="width:100%;margin-bottom:14px;" data-action="undo-quartier-proche-change" ' + (prochesUndoCount === 0 ? 'disabled' : '') + '><i class="fa-solid fa-rotate-left"></i> ' + t("ad_undo_last_action") + (prochesUndoCount > 0 ? ' (' + prochesUndoCount + ')' : '') + '</button>';

  if (!prochesCollapsed) {
    var prochesData = getQuartiersProchesData();
    var prochesGroupNames = Object.keys(prochesData);
    for (var pgi2 = 0; pgi2 < prochesGroupNames.length; pgi2++) {
      var prochesCommune = prochesGroupNames[pgi2];
      html += '<div class="glass-card" style="padding:12px;margin-bottom:10px;">';
      html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:8px;">' + esc(prochesCommune) + '</div>';
      var pqs = prochesData[prochesCommune];
      for (var pqi = 0; pqi < pqs.length; pqi++) {
        html += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;">';
        html += '<input class="input" style="flex:1;padding:6px 10px;font-size:12px;" value="' + esc(pqs[pqi]) + '" data-action="admin-rename-quartier-proche" data-commune="' + esc(prochesCommune) + '" data-old-name="' + esc(pqs[pqi]) + '" />';
        html += '<button class="link-btn" style="color:var(--danger);" data-action="admin-remove-quartier-proche" data-commune="' + esc(prochesCommune) + '" data-value="' + esc(pqs[pqi]) + '"><i class="fa-solid fa-xmark"></i></button>';
        html += '</div>';
      }
      html += '<div style="display:flex;gap:6px;margin-top:8px;">';
      html += '<input class="input" id="new-quartier-proche-' + esc(prochesCommune) + '" placeholder="Ajouter un secteur…" style="flex:1;padding:6px 10px;font-size:12px;" />';
      html += '<button class="link-btn" data-action="admin-add-quartier-proche" data-value="' + esc(prochesCommune) + '"><i class="fa-solid fa-plus"></i></button>';
      html += '</div>';
      html += '</div>';
    }
  }

  return html;
}

// ---------- ADMIN : DEMANDES LIVREUR ----------
// ---------- Liste Admin repliable + paginée (20 à la fois) + recherche ----------
// Réutilisée pour toutes les longues listes de l'Admin (Suivi des
// livraisons, Points de retrait...) — repliée par défaut, un bouton
// "Afficher plus" tant qu'il reste des éléments au-delà de 20, et une
// barre de recherche pour retrouver un élément précis sans tout dérouler.
function renderAdminCollapsibleList(sectionKey, titleHtml, items, itemRenderFn, opts) {
  opts = opts || {};
  var expanded = !!state.adminSectionExpanded[sectionKey];
  var shown = state.adminSectionShown[sectionKey] || 20;
  var query = (state.adminSectionSearch[sectionKey] || "").toLowerCase().trim();
  var filtered = (query && opts.searchFn) ? items.filter(function(it) { return opts.searchFn(it, query); }) : items;

  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<button type="button" style="all:unset;cursor:pointer;display:flex;justify-content:space-between;align-items:center;width:100%;" data-action="toggle-admin-collapsible-list" data-value="' + sectionKey + '">';
  html += '<div style="font-weight:800;font-size:14px;">' + titleHtml + ' (' + items.length + ')</div>';
  html += '<i class="fa-solid fa-chevron-' + (expanded ? 'up' : 'down') + '" style="color:var(--text-dim);"></i>';
  html += '</button>';
  if (expanded) {
    if (opts.searchPlaceholder && items.length > 5) {
      html += '<input class="input" style="margin-top:10px;" placeholder="' + esc(opts.searchPlaceholder) + '" value="' + esc(state.adminSectionSearch[sectionKey] || "") + '" data-bind="adminSectionSearch.' + sectionKey + '" />';
    }
    if (filtered.length === 0) {
      html += '<div style="font-size:11.5px;color:var(--text-dim);margin-top:10px;">' + (opts.emptyText || "Aucun élément.") + '</div>';
    } else {
      var toShow = filtered.slice(0, shown);
      html += '<div style="margin-top:10px;">';
      for (var ii = 0; ii < toShow.length; ii++) html += itemRenderFn(toShow[ii]);
      html += '</div>';
      if (filtered.length > shown) {
        html += '<button class="btn-secondary" style="width:100%;margin-top:10px;" data-action="load-more-admin-section" data-value="' + sectionKey + '">Afficher plus (' + (filtered.length - shown) + ' restant(s))</button>';
      }
    }
  }
  html += '</div>';
  return html;
}

function renderAdminLivreurApplications() {
  var apps = state.livreurApplications.filter(inAdminScope).sort(function(a, b) { return b.createdAt - a.createdAt; });
  var pendingApps = apps.filter(function(a) { return a.status === "pending"; });
  var activeLivreurs = state.accounts.filter(function(a) { return a.livreurApplicationStatus === "approved" && inAdminScope(a); });

  var html = '';

  // Tableau de suivi : quelles commandes prêtes sont disponibles, et
  // lesquelles sont déjà prises par un livreur — visible dans les deux
  // groupes, pour garder un œil sur ce qui traîne sans être pris.
  var terminalNonActive = ["Annulée", "Non livrable", "Refusée au retrait", "Livrée", "En boutique"];
  var deliverableOrders = state.orders.filter(function(o) {
    if (terminalNonActive.indexOf(o.status) !== -1) return false;
    return statusProgressIndex(o.status) >= statusProgressIndex("Prête");
  });
  var unassigned = deliverableOrders.filter(function(o) { return !o.livreurId; });
  var assigned = deliverableOrders.filter(function(o) { return o.livreurId; });
  var lateUnassigned = unassigned.filter(function(o) {
    var readyStep = (o.statusHistory || []).find(function(h) { return h.status === "Prête"; });
    return readyStep && (Date.now() - readyStep.at) > 30 * 60 * 1000;
  });

  var lateAlertHtml = '';
  if (lateUnassigned.length > 0) {
    lateAlertHtml += '<div style="background:rgba(239,68,68,0.1);border:1.5px solid var(--danger);border-radius:10px;padding:10px;margin-bottom:16px;">';
    lateAlertHtml += '<div style="font-weight:800;font-size:12.5px;color:var(--danger);"><i class="fa-solid fa-triangle-exclamation"></i> ' + lateUnassigned.length + t("ad_ready_orders_no_livreur") + '</div>';
    for (var lu = 0; lu < lateUnassigned.length; lu++) {
      lateAlertHtml += '<div style="font-size:11.5px;margin-top:4px;">#' + lateUnassigned[lu].id.slice(-5).toUpperCase() + ' — ' + esc(lateUnassigned[lu].buyerName) + '</div>';
    }
    lateAlertHtml += '</div>';
  }

  html += lateAlertHtml;
  html += renderAdminCollapsibleList("deliveryTracking", '<i class="fa-solid fa-truck-fast"></i> ' + t("ad_delivery_tracking").replace(" (", ""), deliverableOrders, function(ord) {
    var rowHtml = '<div class="card-row" data-action="open-admin-order-detail" data-value="' + ord.id + '" data-open-list="1" style="cursor:pointer;">';
    rowHtml += '<div style="flex:1;min-width:0;"><div style="font-weight:700;font-size:12px;">#' + ord.id.slice(-5).toUpperCase() + ' — ' + translateStatus(ord.status) + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + (ord.livreurId ? t("ad_taken_by") + esc(ord.livreurName) : t("ad_available_unclaimed")) + '</div></div>';
    rowHtml += '<span class="status-pill" style="background:' + (ord.livreurId ? 'rgba(46,204,113,0.15);color:var(--success)' : 'rgba(255,159,10,0.15);color:#ff9f0a') + ';">' + (ord.livreurId ? t("ad_taken_pill") : t("ad_available_pill")) + '</span>';
    rowHtml += '</div>';
    return rowHtml;
  }, {
    emptyText: t("ad_no_order_in_delivery"),
    searchPlaceholder: "Rechercher par code ou acheteur...",
    searchFn: function(ord, q) { return ord.id.toLowerCase().indexOf(q) !== -1 || (ord.buyerName || "").toLowerCase().indexOf(q) !== -1; }
  });

  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-inbox"></i> ' + t("ad_pending_requests") + pendingApps.length + ')</div>';
  if (pendingApps.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:16px;">' + t("ad_no_pending_request") + '</div>';
  } else {
    for (var i = 0; i < pendingApps.length; i++) {
      var app = pendingApps[i];
      html += '<div class="glass-card" style="padding:14px;margin-bottom:12px;">';
      html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
      html += '<div style="font-weight:800;font-size:14px;">' + esc(app.accountName) + '</div>';
      html += '<span class="status-pill">' + t("ad_pending_pill") + '</span>';
      html += '</div>';
      html += '<div style="font-size:12.5px;color:var(--text-dim);margin-bottom:10px;"><a href="tel:' + esc(app.accountPhone) + '" style="color:var(--accent)">' + esc(app.accountPhone) + '</a></div>';
      html += '<button class="link-btn" style="font-size:11px;margin-bottom:8px;" data-action="open-admin-account-detail" data-value="' + app.accountId + '">' + t("ad_view_account") + ' <i class="fa-solid fa-arrow-right"></i></button>';
      html += '<div style="display:flex;gap:8px;">';
      html += '<button class="btn-primary" style="flex:1;padding:9px;font-size:12.5px;" data-action="approve-livreur-application" data-value="' + app.id + '"><i class="fa-solid fa-check"></i> ' + t("ad_approve") + '</button>';
      html += '<button class="btn-secondary" style="flex:1;padding:9px;font-size:12.5px;color:var(--danger);border-color:var(--danger);" data-action="reject-livreur-application" data-value="' + app.id + '"><i class="fa-solid fa-xmark"></i> ' + t("ad_refuse") + '</button>';
      html += '</div>';
      html += '<div style="font-size:10px;color:var(--text-dim);margin-top:8px;">' + t("ad_submitted_on") + fmtDateTime(app.createdAt) + '</div>';
      html += '</div>';
    }
  }

  html += '<div class="divider-dashed" style="margin:16px 0;"></div>';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-truck-fast"></i> ' + t("ad_active_livreurs_title") + activeLivreurs.length + ')</div>';
  if (activeLivreurs.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);">' + t("ad_no_active_livreur") + '</div>';
  } else {
    for (var j = 0; j < activeLivreurs.length; j++) {
      var lv = activeLivreurs[j];
      var lvOrders = state.orders.filter(function(o) { return o.livreurId === lv.id; });
      var lvDelivered = lvOrders.filter(function(o) { return o.status === "Livrée"; });
      var lvEarnings = 0;
      for (var k = 0; k < lvDelivered.length; k++) lvEarnings += lvDelivered[k].deliveryFee || 0;
      html += '<div class="card-row" style="cursor:pointer;" data-action="open-admin-livreur-detail" data-value="' + lv.id + '">';
      html += '<div class="emoji-thumb"><i class="fa-solid fa-truck-fast"></i></div>';
      html += '<div style="flex:1;min-width:0;">';
      html += '<div style="font-weight:700;font-size:13px;">' + esc(lv.name) + (lv.banned ? ' 🚫' : '') + (lv.hasRefusalAlert ? ' ⚠️' : '') + '</div>';
      html += '<div style="font-size:11px;color:var(--text-dim);">' + lvDelivered.length + t("ad_deliveries_word") + money(lvEarnings) + t("ad_earned_word") + '</div>';
      html += '</div>';
      html += '<i class="fa-solid fa-chevron-right" style="color:var(--text-dim);"></i>';
      html += '</div>';
    }
  }
  return html;
}

// ---------- ADMIN : MESSAGERIE CENTRALISÉE ----------
// Regroupe la diffusion générale et les canaux Livreurs / Points de Retrait —
// pas les conversations acheteur-vendeur classiques (déjà accessibles via
// le pouvoir étendu depuis chaque fiche de compte).
function renderAdminMessagerie() {
  var scopedAccountsCount = state.accounts.filter(inAdminScope).length;
  var totalUnreadAdmin = 0;
  for (var u = 0; u < state.adminConversations.length; u++) {
    if (inAdminScope(state.adminConversations[u])) totalUnreadAdmin += state.adminConversations[u].unreadForAdmin || 0;
  }

  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:8px;"><i class="fa-solid fa-bullhorn"></i> ' + t("ad_broadcast_title") + (totalUnreadAdmin > 0 ? ' <span style="background:var(--danger);color:white;font-size:10px;padding:1px 8px;border-radius:999px;">' + totalUnreadAdmin + t("ad_reply_count") + '</span>' : '') + '</div>';
  html += '<textarea class="input" rows="3" placeholder="' + t("ad_broadcast_placeholder") + '" data-bind="adminBroadcastDraft">' + esc(state.adminBroadcastDraft || '') + '</textarea>';
  html += '<button class="btn-primary" style="margin-top:10px;" data-action="send-admin-broadcast"><i class="fa-solid fa-paper-plane"></i> ' + t("ad_send_to_all") + scopedAccountsCount + ')</button>';
  html += '</div>';

  function renderChannelSection(title, icon, roleFilter, sectionKey) {
    var accountIds = {};
    for (var a = 0; a < state.accounts.length; a++) {
      var acc = state.accounts[a];
      if (!inAdminScope(acc)) continue;
      var matches;
      if (roleFilter === "livreur") matches = acc.livreurApplicationStatus === "approved";
      else if (roleFilter === "point_vente") matches = acc.relaisApplicationStatus === "approved";
      else matches = acc.livreurApplicationStatus !== "approved" && acc.relaisApplicationStatus !== "approved";
      if (matches) accountIds[acc.id] = acc;
    }
    var convs = state.adminConversations.filter(function(c) { return accountIds[c.accountId]; }).sort(function(x, y) { return y.lastMessageTime - x.lastMessageTime; });
    var msgSearch = (state.adminMessagerieSearch || "").toLowerCase().trim();
    if (msgSearch) convs = convs.filter(function(c) { return (accountIds[c.accountId].name || "").toLowerCase().indexOf(msgSearch) !== -1; });
    var sectionCollapsed = !!state.collapsedAdminSections[sectionKey];
    var sectionHtml = '<div style="display:flex;justify-content:space-between;align-items:center;margin:16px 0 10px;">';
    sectionHtml += '<div style="font-weight:800;font-size:14px;"><i class="fa-solid ' + icon + '"></i> ' + title + ' (' + convs.length + ')</div>';
    sectionHtml += '<button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="' + sectionKey + '"><i class="fa-solid ' + (sectionCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button>';
    sectionHtml += '</div>';
    if (sectionCollapsed) return sectionHtml;
    if (convs.length === 0) {
      sectionHtml += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">' + t("ad_no_conversation") + '</div>';
      return sectionHtml;
    }
    for (var c = 0; c < convs.length; c++) {
      var conv = convs[c];
      var acc2 = accountIds[conv.accountId];
      sectionHtml += '<div class="glass-card" style="padding:12px;margin-bottom:10px;">';
      sectionHtml += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">';
      sectionHtml += '<div style="font-weight:700;font-size:13px;">' + esc(acc2.name) + '</div>';
      if (conv.unreadForAdmin > 0) sectionHtml += '<span style="background:var(--danger);color:white;font-size:10px;padding:1px 8px;border-radius:999px;">' + conv.unreadForAdmin + '</span>';
      sectionHtml += '</div>';
      if (conv.lastMessage) sectionHtml += '<div style="font-size:12px;color:var(--text-dim);margin-bottom:8px;">' + esc(conv.lastMessage) + '</div>';
      sectionHtml += '<div style="display:flex;gap:12px;">';
      sectionHtml += '<button class="link-btn" style="font-size:11.5px;" data-action="open-conv-detail" data-value="' + conv.id + '"><i class="fa-solid fa-comment"></i> ' + t("ad_open_conversation") + '</button>';
      sectionHtml += '<button class="link-btn" style="font-size:11.5px;" data-action="open-account-from-conv" data-value="' + acc2.id + '" data-conv-id="' + conv.id + '"><i class="fa-solid fa-user"></i> ' + t("ad_view_account_msg") + '</button>';
      sectionHtml += '</div></div>';
    }
    return sectionHtml;
  }

  html += '<input class="input" style="margin-bottom:6px;" placeholder="' + t("ad_search_conversation") + '" value="' + esc(state.adminMessagerieSearch || "") + '" data-action-input="admin-messagerie-search" />';
  html += renderChannelSection(t("ad_channel_livreurs"), "fa-truck-fast", "livreur", "msgLivreurs");
  html += renderChannelSection(t("ad_channel_pv"), "fa-shop", "point_vente", "msgPointsVente");
  html += renderChannelSection(t("ad_channel_others"), "fa-user", "autres", "msgAutres");

  return html;
}


function renderAdminRelaisApplications() {
  var editReqs = state.relaisEditRequests.filter(function(r) { return r.status === "pending"; });
  var htmlPrefix = '';
  if (editReqs.length > 0) {
    htmlPrefix += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-pen-to-square"></i> ' + t("ad_edit_requests") + editReqs.length + ')</div>';
    for (var e = 0; e < editReqs.length; e++) {
      var req = editReqs[e];
      var oldAcc = null;
      for (var oa = 0; oa < state.accounts.length; oa++) { if (state.accounts[oa].id === req.accountId) { oldAcc = state.accounts[oa]; break; } }
      htmlPrefix += '<div class="glass-card" style="padding:12px;margin-bottom:12px;">';
      htmlPrefix += '<div style="font-weight:700;font-size:13px;margin-bottom:8px;">' + esc(req.accountName) + '</div>';
      var fields = [
        [t("ad_field_shopname"), "shopName"], [t("ad_field_phone"), "phone"], [t("ad_field_commune"), "commune"],
        [t("ad_field_quartier"), "quartier"], [t("ad_field_precision"), "addressDetail"]
      ];
      for (var f = 0; f < fields.length; f++) {
        var key = fields[f][1];
        var oldVal = oldAcc ? (oldAcc[key] || '—') : '—';
        var newVal = req.changes[key] || '—';
        if (oldVal !== newVal) {
          htmlPrefix += '<div style="font-size:11.5px;margin-bottom:4px;"><span style="color:var(--text-dim);">' + fields[f][0] + '</span> : <span style="text-decoration:line-through;color:var(--text-dim);">' + esc(String(oldVal)) + '</span> → <strong>' + esc(String(newVal)) + '</strong></div>';
        }
      }
      // Le GPS proposé ne vit plus dans req.changes (voir plus bas, révélation dédiée).
      var revealedEditLoc = (state.adminRevealedRelaisEditLoc && state.adminRevealedRelaisEditLoc.editRequestId === req.id) ? state.adminRevealedRelaisEditLoc.location : null;
      if (!revealedEditLoc) {
        htmlPrefix += '<button class="link-btn" style="font-size:11px;margin-bottom:6px;" data-action="open-reveal-relais-edit-location" data-value="' + req.id + '"><i class="fa-solid fa-lock"></i> ' + (state.adminIsOwner ? 'Voir la nouvelle adresse proposée (mot de passe requis)' : 'Voir la nouvelle adresse proposée (confirmation requise)') + '</button>';
      } else {
        htmlPrefix += '<div style="font-size:11.5px;margin-bottom:6px;"><span style="color:var(--text-dim);">Nouvelle adresse proposée</span> : <strong>' + esc(revealedEditLoc.addressDetail || '—') + '</strong>' + (revealedEditLoc.shopLat != null ? ' · <a href="https://www.google.com/maps?q=' + revealedEditLoc.shopLat + ',' + revealedEditLoc.shopLng + '" target="_blank" style="color:var(--accent);">📍 carte</a>' : '') + '</div>';
      }
      htmlPrefix += '<div style="display:flex;gap:8px;margin-top:10px;">';
      htmlPrefix += '<button class="btn-primary" style="flex:1;padding:9px;font-size:12.5px;" data-action="approve-relais-edit" data-value="' + req.id + '"><i class="fa-solid fa-check"></i> ' + t("ad_approve") + '</button>';
      htmlPrefix += '<button class="btn-secondary" style="flex:1;padding:9px;font-size:12.5px;color:var(--danger);border-color:var(--danger);" data-action="reject-relais-edit" data-value="' + req.id + '"><i class="fa-solid fa-xmark"></i> ' + t("ad_refuse") + '</button>';
      htmlPrefix += '</div></div>';
    }
    htmlPrefix += '<div class="divider-dashed" style="margin:16px 0;"></div>';
  }

  var apps = state.relaisApplications.filter(function(a) { return a.status === "pending" && inAdminScope(a); }).sort(function(a, b) { return b.createdAt - a.createdAt; });
  var html = htmlPrefix;
  html += renderAdminCollapsibleList("relaisPending", '<i class="fa-solid fa-inbox"></i> ' + t("ad_pending_requests").replace(" (", ""), apps, function(app) {
    var cardHtml = '<div class="glass-card" style="padding:14px;margin-bottom:12px;">';
    cardHtml += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
    cardHtml += '<div style="font-weight:800;font-size:14px;">' + esc(app.shopName) + '</div>';
    cardHtml += '<span class="status-pill" style="' + (app.status === "pending" ? '' : app.status === "approved" ? 'background:rgba(46,158,79,0.15);color:#2e9e4f;' : 'background:rgba(255,85,102,0.15);color:var(--danger);') + '">' + (app.status === "pending" ? t("ad_pending_pill") : app.status === "approved" ? t("ad_approved_pill") : t("ad_refused_pill")) + '</span>';
    cardHtml += '</div>';
    cardHtml += '<div style="font-size:12.5px;color:var(--text-dim);margin-bottom:4px;"><i class="fa-solid fa-user"></i> ' + esc(app.accountName) + ' · <a href="tel:' + esc(app.accountPhone) + '" style="color:var(--accent)">' + esc(app.accountPhone) + '</a></div>';
    var revealedLoc = (state.adminRevealedRelaisLoc && state.adminRevealedRelaisLoc.applicationId === app.id) ? state.adminRevealedRelaisLoc.location : null;
    cardHtml += '<div style="font-size:12.5px;color:var(--text-dim);margin-bottom:8px;"><i class="fa-solid fa-location-dot"></i> ' + esc(app.quartier) + (app.isAutreQuartier ? t("ad_new_quartier_proposed") : (app.commune ? ', ' + esc(app.commune) : '')) + (revealedLoc && revealedLoc.addressDetail ? ' — ' + esc(revealedLoc.addressDetail) : '') + '</div>';
    if (!revealedLoc) {
      cardHtml += '<button class="link-btn" style="font-size:11.5px;margin-bottom:8px;" data-action="open-reveal-relais-location" data-value="' + app.id + '"><i class="fa-solid fa-lock"></i> ' + (state.adminIsOwner ? 'Voir adresse exacte et GPS (mot de passe requis)' : 'Voir adresse exacte et GPS (confirmation requise)') + '</button><br>';
    } else if (revealedLoc.shopLat != null) {
      cardHtml += '<div style="font-size:11.5px;margin-bottom:8px;"><a href="https://www.google.com/maps?q=' + revealedLoc.shopLat + ',' + revealedLoc.shopLng + '" target="_blank" style="color:var(--accent);font-weight:700;">📍 Voir la position exacte sur la carte</a></div>';
    } else {
      cardHtml += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:8px;">Aucune localisation GPS enregistrée pour cette candidature.</div>';
    }
    if (app.hasVerificationDocs) {
      cardHtml += '<button type="button" class="btn-secondary" style="width:100%;margin-bottom:10px;" data-action="view-relais-docs-secure" data-value="' + app.id + '"><i class="fa-solid fa-image"></i> Voir la photo et la pièce d\'identité</button>';
    }
    if (app.status === "pending") {
      cardHtml += '<div style="display:flex;gap:8px;">';
      cardHtml += '<button class="btn-primary" style="flex:1;padding:9px;font-size:12.5px;" data-action="approve-relais-application" data-value="' + app.id + '"><i class="fa-solid fa-check"></i> ' + t("ad_approve") + '</button>';
      cardHtml += '<button class="btn-secondary" style="flex:1;padding:9px;font-size:12.5px;color:var(--danger);border-color:var(--danger);" data-action="reject-relais-application" data-value="' + app.id + '"><i class="fa-solid fa-xmark"></i> ' + t("ad_refuse") + '</button>';
      cardHtml += '</div>';
    }
    cardHtml += '<div style="font-size:10px;color:var(--text-dim);margin-top:8px;">' + t("ad_submitted_on") + fmtDateTime(app.createdAt) + '</div>';
    cardHtml += '</div>';
    return cardHtml;
  }, {
    emptyText: t("ad_no_new_pv_request"),
    searchPlaceholder: "Rechercher par boutique, nom ou téléphone...",
    searchFn: function(app, q) { return (app.shopName || "").toLowerCase().indexOf(q) !== -1 || (app.accountName || "").toLowerCase().indexOf(q) !== -1 || (app.accountPhone || "").indexOf(q) !== -1; }
  });

  var activeRelais = state.accounts.filter(function(a) { return a.relaisApplicationStatus === "approved"; });
  var rate2 = getRelaisCommissionRate();
  html += renderAdminCollapsibleList("relaisActive", '<i class="fa-solid fa-shop"></i> ' + t("ad_active_pv_title").replace(" (", ""), activeRelais, function(rshop) {
    var rOrders = state.orders.filter(function(o) { return o.deliveryMode === "relais" && o.relaisShopId === rshop.id && o.status === "Livrée"; });
    var rCommission = 0;
    for (var rc = 0; rc < rOrders.length; rc++) rCommission += (rOrders[rc].deliveryFee || 0) * rate2;
    var rowHtml = '<div class="card-row" style="cursor:pointer;" data-action="open-admin-relais-detail" data-value="' + rshop.id + '">';
    rowHtml += '<div class="emoji-thumb"><i class="fa-solid fa-shop"></i></div>';
    rowHtml += '<div style="flex:1;min-width:0;">';
    rowHtml += '<div style="font-weight:700;font-size:13px;">' + esc(rshop.shopName || rshop.name) + (rshop.banned ? ' 🚫' : '') + '</div>';
    rowHtml += '<div style="font-size:11px;color:var(--text-dim);">' + esc(rshop.quartier || '—') + ' · ' + rOrders.length + t("ad_orders_word") + money(rCommission) + t("ad_commission_word") + '</div>';
    rowHtml += '</div>';
    rowHtml += '<i class="fa-solid fa-chevron-right" style="color:var(--text-dim);"></i>';
    rowHtml += '</div>';
    return rowHtml;
  }, {
    emptyText: t("ad_no_active_pv"),
    searchPlaceholder: "Rechercher par boutique ou quartier...",
    searchFn: function(rshop, q) { return (rshop.shopName || rshop.name || "").toLowerCase().indexOf(q) !== -1 || (rshop.quartier || "").toLowerCase().indexOf(q) !== -1; }
  });
  return html;
}

// ---------- ADMIN : LIVREURS (même logique que Points de vente) ----------
// ---------- ADMIN : PORTEFEUILLES (Sounsouni Portefeuille) ----------
// Consultable, modifiable et supprimable pour chaque compte, avec
// recherche — comme convenu, réservé à l'Admin principal.
// ---------- ADMIN : FILATURE ----------
function currentAdminHasFilatureAccess() {
  if (state.adminIsOwner && !state.adminCountryScope) return true; // Groupe 1 global — accès à tous les pays
  if (state.adminCountryScope) {
    var scopedNa = state.nationalAdmins.find(function(a) { return a.country === state.adminCountryScope; });
    return !!(scopedNa && scopedNa.filatureEnabled);
  }
  return false;
}

// ---------- ADMIN > TEST — diagnostic sans avoir besoin d'un ordinateur ----------
// Montre tout ce que l'app a capté toute seule (erreurs JS, promesses
// rejetées, console.error) + quelques boutons pour déclencher des
// vérifications précises à la demande — avec un bouton "Copier" pour
// coller directement le résultat dans la conversation.

// ---------- ADMIN : VERSEMENTS DU JOUR ----------
function loadAdminPayoutList() {
  var di = document.getElementById("admin-payout-date");
  var date = di && di.value ? di.value : new Date().toISOString().slice(0, 10);
  state.payoutList = { date: date, loading: true, items: [] };
  render();
  callWalletOperation({ operation: "admin_payout_list", date: date }).then(function(res) {
    state.payoutList = { date: date, loading: false, items: (res && res.items) || [], error: res && !res.success ? (res.error || "erreur") : null };
    render();
  });
}
function saveAdminPayoutFees() {
  var cfg = {};
  PAYOUT_OPERATORS.forEach(function(o) {
    var pct = document.getElementById("fee-pct-" + o[0]), fixed = document.getElementById("fee-fixed-" + o[0]);
    cfg[o[0]] = { pct: pct ? Number(pct.value) || 0 : 0, fixed: fixed ? Number(fixed.value) || 0 : 0 };
  });
  var doc = { id: "payout_fees", config: cfg, updatedAt: Date.now() };
  if (!state.settings) state.settings = [];
  var idx = state.settings.findIndex(function(x) { return x.id === "payout_fees"; });
  if (idx === -1) state.settings.push(doc); else state.settings[idx] = doc;
  save(); saveDoc("settings", doc);
  showToast("✅ Frais de transfert enregistrés.");
  render();
}
function markAdminPayout(i) {
  var pl = state.payoutList; if (!pl || !pl.items || !pl.items[i]) return;
  var it = pl.items[i];
  var refEl = document.getElementById("payout-ref-" + i);
  var reference = refEl ? String(refEl.value || "").trim() : "";
  if (!reference) { showToast("❌ Indiquez la référence du transfert (numéro de la transaction)."); return; }
  var fee = payoutFeeFor(it.operator || "", it.amount);
  var payload = { operation: "admin_mark_payout", kind: it.kind, key: it.key, operator: it.operator || "", number: it.number || "", reference: reference, fee: fee };
  if (it.kind === "ledger") payload.txnIds = it.txnIds; else payload.orderIds = it.orderIds;
  it.saving = true; render();
  callWalletOperation(payload).then(function(res) {
    if (res && res.success) {
      pl.items.splice(i, 1);
      showToast("✅ Versement enregistré : " + money(res.net) + ". Le bénéficiaire est prévenu.");
    } else {
      it.saving = false;
      showToast("❌ Versement non enregistré : " + ((res && res.error) || "erreur"));
    }
    render();
  });
}
function renderAdminPayoutsCard() {
  var pl = state.payoutList || {};
  var cfg = {};
  (state.settings || []).forEach(function(x) { if (x.id === "payout_fees") cfg = x.config || {}; });
  var today = new Date().toISOString().slice(0, 10);
  var html = '<div style="padding:10px;margin-bottom:12px;border-radius:10px;background:var(--bg-body);">';
  html += '<div style="font-size:12.5px;font-weight:700;margin-bottom:4px;"><i class="fa-solid fa-money-bill-transfer"></i> Versements du jour (vendeurs chaque jour à 17 h)</div>';
  html += '<div style="font-size:10.5px;color:var(--text-dim);margin-bottom:8px;">Vendeurs et parrains : chaque jour à 17 h (frais à leur charge). Points de retrait : le mardi (frais payés par Sounsouni). Faites le transfert, puis appuyez sur « Payé » avec sa référence.</div>';
  html += '<div style="display:flex;gap:6px;margin-bottom:8px;"><input class="input" type="date" id="admin-payout-date" style="flex:1;min-width:0;" value="' + esc(pl.date || today) + '" /><button class="btn-primary" style="flex:0;padding:8px 12px;font-size:12px;" data-action="admin-load-payouts">Afficher</button></div>';
  if (pl.loading) html += '<div style="font-size:12px;">Chargement…</div>';
  else if (pl.error) html += '<div style="font-size:12px;color:var(--danger);">Erreur : ' + esc(pl.error) + '</div>';
  else if (pl.items) {
    if (!pl.items.length && pl.date) html += '<div style="font-size:12px;">✅ Aucun versement dû à cette date.</div>';
    var opName = {}; PAYOUT_OPERATORS.forEach(function(o) { opName[o[0]] = o[1]; });
    pl.items.forEach(function(it, i) {
      var fee = payoutFeeFor(it.operator || "", it.amount);
      var beneficiaryPays = it.feeBy !== "sounsouni";
      var toSend = beneficiaryPays ? it.amount - fee : it.amount;
      html += '<div style="border-top:1px solid var(--border-color);padding:8px 0;">';
      html += '<div style="display:flex;justify-content:space-between;gap:6px;flex-wrap:wrap;"><strong style="font-size:12.5px;">' + esc(it.name) + '</strong><span style="font-size:11px;color:var(--text-dim);">' + (it.kind === "relais" ? "Point de retrait" : "Vendeur / parrain") + ' · ' + it.count + ' élément(s)</span></div>';
      html += '<div style="font-size:12px;">' + (it.operator ? esc(opName[it.operator] || it.operator) : '<span style="color:var(--danger);">opérateur non choisi</span>') + ' · ' + esc(it.number || "?") + '</div>';
      html += '<div style="font-size:12px;">Montant dû ' + money(it.amount) + (fee ? ' · frais ' + money(fee) + (beneficiaryPays ? ' (à sa charge)' : ' (payés par Sounsouni)') : '') + ' → <strong style="color:var(--accent);">à envoyer : ' + money(toSend) + '</strong></div>';
      html += '<div style="display:flex;gap:6px;margin-top:6px;"><input class="input" id="payout-ref-' + i + '" style="flex:1;min-width:0;" placeholder="Référence du transfert" /><button class="btn-primary" style="flex:0;padding:8px 12px;font-size:12px;" data-action="admin-mark-payout" data-value="' + i + '"' + (it.saving ? ' disabled' : '') + '>Payé</button></div>';
      html += '</div>';
    });
  }
  // Frais de transfert par opérateur
  html += '<div style="font-size:12px;font-weight:700;margin:12px 0 4px;">Frais de transfert par opérateur</div>';
  html += '<div style="font-size:10.5px;color:var(--text-dim);margin-bottom:6px;">Frais = pourcentage du montant + montant fixe. Exemple : 1 % + 0 FCFA.</div>';
  var canEditFees = !!state.adminIsOwner;
  if (!canEditFees) {
    PAYOUT_OPERATORS.forEach(function(o) {
      var c = cfg[o[0]] || {};
      html += '<div style="font-size:12px;">' + o[1] + ' : ' + (c.pct || 0) + ' % + ' + money(c.fixed || 0) + '</div>';
    });
    html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:4px;">Seul l\'Admin principal peut modifier ces frais.</div>';
    html += '</div>';
    return html;
  }
  PAYOUT_OPERATORS.forEach(function(o) {
    var c = cfg[o[0]] || {};
    html += '<div style="display:flex;gap:6px;align-items:center;margin-bottom:6px;flex-wrap:wrap;"><span style="font-size:12px;min-width:92px;">' + o[1] + '</span>';
    html += '<input class="input" id="fee-pct-' + o[0] + '" type="number" step="0.1" min="0" style="flex:1;min-width:60px;" placeholder="%" value="' + (c.pct != null ? c.pct : "") + '" />';
    html += '<input class="input" id="fee-fixed-' + o[0] + '" type="number" step="1" min="0" style="flex:1;min-width:60px;" placeholder="FCFA" value="' + (c.fixed != null ? c.fixed : "") + '" /></div>';
  });
  html += '<button class="btn-secondary" style="width:100%;" data-action="admin-save-payout-fees">Enregistrer les frais</button>';
  html += '</div>';
  return html;
}

function renderAdminVersements() {
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:14px;">';
  html += renderAdminPayoutsCard();
  html += '</div>';
  return html;
}
function renderAdminTest() {
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:14px;">';
  html += '<div class="section-title" style="margin-bottom:10px;"><i class="fa-solid fa-bug"></i> Test & diagnostic</div>';
  // Interrupteur global : outils de test visibles par les utilisateurs
  html += '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px;margin-bottom:12px;border-radius:10px;background:' + (diagnosticsEnabled() ? 'rgba(255,159,10,0.12)' : 'var(--bg-body)') + ';">';
  html += '<div style="font-size:12.5px;min-width:0;"><strong>Outils de test visibles par les utilisateurs</strong><br><span style="font-size:10.5px;color:var(--text-dim);">' + (diagnosticsEnabled() ? '⚠️ ACTIVÉS — rapport de démarrage, détails des erreurs, #diag, boutons de test du Profil. Pensez à les désactiver après usage.' : 'Désactivés (normal). À activer seulement pour diagnostiquer un problème chez un utilisateur.') + '</span></div>';
  html += '<div class="toggle-switch ' + (diagnosticsEnabled() ? 'active' : '') + '" data-action="toggle-diagnostics-visible" style="flex-shrink:0;"><div class="toggle-knob"></div></div>';
  html += '</div>';
  // ---- Versements en attente (vendeurs + parrains) ----
  var unsettled = unsettledDeliveredOrders();
  var pc = state.payoutCatchUp;
  html += '<div style="padding:10px;margin-bottom:12px;border-radius:10px;background:var(--bg-body);">';
  html += '<div style="font-size:12.5px;font-weight:700;margin-bottom:4px;"><i class="fa-solid fa-coins"></i> Versements en attente</div>';
  html += '<div style="font-size:10.5px;color:var(--text-dim);margin-bottom:8px;">Commandes livrées dont le versement au vendeur ou au parrain n\'a pas été fait. Aucun risque de double paiement : le serveur ne verse jamais deux fois.</div>';
  if (pc && pc.running) {
    html += '<div style="font-size:12px;">Versements en cours… ' + pc.done + ' / ' + pc.total + '</div>';
  } else {
    if (pc && pc.msg) html += '<div style="font-size:11.5px;margin-bottom:6px;">' + esc(pc.msg) + '</div>';
    if (unsettled.length) {
      html += '<div style="font-size:12px;margin-bottom:6px;"><strong>' + unsettled.length + '</strong> commande(s) concernée(s) :</div>';
      unsettled.slice(0, 8).forEach(function(o) {
        var why = [];
        var paid = o.sellerPayoutSettled || {};
        var sids = Array.isArray(o.sellerIds) && o.sellerIds.length ? o.sellerIds : (o.items || []).map(function(it) { return it.sellerId; }).filter(Boolean);
        if (sids.some(function(id) { return !paid[id]; })) why.push("vendeur");
        if (o.affiliateId && !o.affiliateCommissionCredited) why.push("parrain");
        var lastRes = (state.payoutResults || {})[o.id];
        html += '<div style="font-size:11px;color:var(--text-dim);">#' + o.id.slice(-5).toUpperCase() + ' · ' + fmtDateTime(o.deliveredAt || o.createdAt) + ' · ' + why.join(" + ") + (lastRes ? ' — <em>' + esc(lastRes) + '</em>' : '') + '</div>';
      });
      if (unsettled.length > 8) html += '<div style="font-size:11px;color:var(--text-dim);">… et ' + (unsettled.length - 8) + ' autre(s)</div>';
      html += '<button class="btn-primary" style="width:100%;margin-top:8px;" data-action="admin-payout-catch-up"><i class="fa-solid fa-coins"></i> Verser maintenant</button>';
    } else {
      html += '<div style="font-size:12px;">✅ Aucun versement en attente.</div>';
    }
  }
  html += '</div>';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;margin-bottom:10px;border-bottom:1px solid var(--border-color);">';
  html += '<div style="font-size:12.5px;"><strong>Capture des erreurs</strong><br><span style="font-size:10.5px;color:var(--text-dim);">À désactiver une fois le problème réglé — sinon ça continue à occuper de la place pour rien.</span></div>';
  html += '<div class="toggle-switch ' + (state.debugLoggingEnabled ? 'active' : '') + '" data-action="toggle-debug-logging"><div class="toggle-knob"></div></div>';
  html += '</div>';

  if (state.adminIsOwner) {
    html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;margin-bottom:10px;border-bottom:1px solid var(--border-color);">';
    html += '<div style="font-size:12.5px;"><strong>Diagnostic avancé (tous les comptes)</strong><br><span style="font-size:10.5px;color:var(--text-dim);">Va chercher la vérité directement sur le serveur — pas seulement ce que TON téléphone a en cache. À désactiver une fois le problème réglé.</span></div>';
    html += '<div class="toggle-switch ' + (state.debugToolsEnabled ? 'active' : '') + '" data-action="toggle-debug-tools"><div class="toggle-knob"></div></div>';
    html += '</div>';

    if (state.debugToolsEnabled) {
      html += '<div style="background:var(--bg-body);border-radius:10px;padding:12px;margin-bottom:14px;">';
      html += '<div style="font-size:12px;font-weight:700;margin-bottom:6px;">🔎 Chercher une commande (par son code, ex: 4V9E0)</div>';
      html += '<div style="display:flex;gap:8px;margin-bottom:10px;">';
      html += '<input class="input" id="debug-order-input" placeholder="Code de commande" value="' + esc(state.debugOrderQuery || "") + '" data-bind="debugOrderQuery" data-enter-action="debug-search-order" />';
      html += '<button class="btn-primary" style="flex:0;padding:0 16px;" data-action="debug-search-order"><i class="fa-solid fa-search"></i></button>';
      html += '<button class="btn-secondary" style="flex:0;padding:0 16px;" data-action="debug-search-order-local" title="Vérifier directement dans les données déjà sur ce téléphone, sans passer par le serveur"><i class="fa-solid fa-mobile-screen"></i></button>';
      html += '</div>';
      html += '<div style="font-size:12px;font-weight:700;margin-bottom:6px;">🔎 Chercher un compte (nom, boutique ou téléphone)</div>';
      html += '<div style="display:flex;gap:8px;">';
      html += '<input class="input" id="debug-account-input" placeholder="Nom, boutique ou téléphone" value="' + esc(state.debugAccountQuery || "") + '" data-bind="debugAccountQuery" data-enter-action="debug-search-account" />';
      html += '<button class="btn-primary" style="flex:0;padding:0 16px;" data-action="debug-search-account"><i class="fa-solid fa-search"></i></button>';
      html += '</div>';
      if (state.debugQueryResult) {
        html += '<div style="margin-top:14px;">';
        html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">';
        html += '<strong style="font-size:12px;">Résultat (' + state.debugQueryResult.count + ')</strong>';
        html += '<button class="link-btn" style="font-size:11px;" data-action="debug-copy-result"><i class="fa-solid fa-copy"></i> Copier</button>';
        html += '</div>';
        html += '<pre style="background:#0d0d14;color:#7fdb7f;font-size:10px;padding:10px;border-radius:8px;overflow-x:auto;white-space:pre-wrap;word-break:break-all;max-height:400px;overflow-y:auto;">' + esc(JSON.stringify(state.debugQueryResult.results, null, 2)) + '</pre>';
        html += '</div>';
      }
      html += '</div>';
    }
  }
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:12px;">Cette page capte automatiquement les erreurs de l\'app. Reproduis le problème (ex : passer une commande), reviens ici, puis appuie sur "Copier" et colle le résultat dans la conversation.</div>';
  html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px;">';
  html += '<button class="btn-primary" style="flex:1;" data-action="copy-debug-log"><i class="fa-solid fa-copy"></i> Copier tout</button>';
  html += '<button class="btn-secondary" style="flex:0;" data-action="clear-debug-log"><i class="fa-solid fa-trash"></i> Vider</button>';
  html += '</div>';
  html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;">';
  html += '<button class="btn-secondary" style="flex:1;" data-action="test-my-session"><i class="fa-solid fa-key"></i> Tester ma session</button>';
  html += '<button class="btn-secondary" style="flex:1;" data-action="test-app-state"><i class="fa-solid fa-info-circle"></i> Voir l\'état de l\'app</button>';
  html += '</div>';
  html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;">';
  html += '<button class="btn-primary" style="flex:1;background:#e08a00;" data-action="force-full-resync"><i class="fa-solid fa-rotate"></i> Forcer une resynchronisation complète</button>';
  html += '</div>';

  var logs = state.debugLog || [];
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:8px;">' + logs.length + ' entrée(s)' + (logs.length >= 200 ? ' (limite atteinte, les plus anciennes sont retirées)' : '') + '</div>';
  if (logs.length === 0) {
    html += '<div class="empty-state"><i class="fa-solid fa-check"></i><div class="title">Aucune erreur capturée pour l\'instant</div></div>';
  } else {
    for (var i = 0; i < logs.length; i++) {
      var entry = logs[i];
      var color = entry.type === "error" ? "var(--danger)" : entry.type === "promise" ? "#e08a00" : "var(--text-dim)";
      html += '<div style="border-left:3px solid ' + color + ';padding:8px 10px;margin-bottom:8px;background:var(--bg-body);border-radius:6px;">';
      html += '<div style="font-size:10px;color:var(--text-dim);margin-bottom:2px;">' + fmtDateTime(entry.at) + ' · ' + esc(entry.type) + '</div>';
      html += '<div style="font-size:12px;font-weight:600;word-break:break-word;">' + esc(entry.message) + '</div>';
      if (entry.detail) html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:4px;white-space:pre-wrap;word-break:break-word;">' + esc(entry.detail) + '</div>';
      html += '</div>';
    }
  }
  html += '</div>';
  return html;
}

// Construit le texte complet à copier — tout ce qui est affiché à
// l'écran, dans un format simple à coller tel quel dans la conversation.
function buildDebugLogText() {
  var logs = state.debugLog || [];
  if (logs.length === 0) return "Aucune erreur capturée.";
  var lines = ["=== Journal de diagnostic Sounsouni (" + logs.length + " entrée(s)) ==="];
  for (var i = 0; i < logs.length; i++) {
    var entry = logs[i];
    lines.push("");
    lines.push("[" + fmtDateTime(entry.at) + "] (" + entry.type + ") " + entry.message);
    if (entry.detail) lines.push(entry.detail);
  }
  return lines.join("\n");
}

// Copie robuste sur téléphone : essaie l'API moderne, et si elle n'est
// pas disponible (ancien navigateur, contexte non sécurisé...), reprend
// avec la vieille méthode du textarea invisible + sélection manuelle.
function copyTextToClipboard(text) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(text).then(function() { return true; }).catch(function() { return copyTextToClipboardFallback(text); });
  }
  return Promise.resolve(copyTextToClipboardFallback(text));
}
function copyTextToClipboardFallback(text) {
  try {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    var ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  } catch (e) {
    return false;
  }
}


function renderAdminFilature() {
  var watchlist = getFilatureWatchlist();
  // Un admin national voit seulement les comptes DE SON PAYS, même s'il a
  // techniquement accès à l'onglet — jamais le reste du monde. Seul
  // l'admin global (Groupe 1) voit tout.
  if (state.adminCountryScope) {
    watchlist = watchlist.filter(function(p) {
      var wa = findAccountByPhone(p);
      return wa && wa.country === state.adminCountryScope;
    });
  }
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-user-secret"></i> Comptes surveillés</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:12px;">Aucun suivi détaillé n\'est jamais actif par défaut — uniquement pour les numéros ajoutés ici. Retirer un numéro arrête le suivi immédiatement (l\'historique déjà enregistré reste consultable).</div>';
  html += '<div style="display:flex;gap:8px;">';
  html += '<input class="input" id="filature-add-phone" placeholder="Numéro à surveiller (ex : 70 00 00 00)" data-format="phone" style="flex:1;" />';
  html += '<button class="btn-primary" style="flex:0;padding:0 16px;" data-action="add-filature-watch"><i class="fa-solid fa-plus"></i></button>';
  html += '</div>';
  html += '</div>';

  if (watchlist.length === 0) {
    html += '<div class="empty-state"><i class="fa-solid fa-user-secret"></i><div class="title">Aucun compte surveillé</div></div>';
    return html;
  }

  var filatureSearch = (state.adminFilatureSearch || "").toLowerCase().trim();
  var filteredWatchlist = watchlist;
  if (filatureSearch) {
    filteredWatchlist = watchlist.filter(function(p) {
      var wa2 = findAccountByPhone(p);
      return p.toLowerCase().indexOf(filatureSearch) !== -1 ||
        (wa2 && ((wa2.name || "").toLowerCase().indexOf(filatureSearch) !== -1 || (wa2.shopName || "").toLowerCase().indexOf(filatureSearch) !== -1));
    });
  }
  if (watchlist.length > 5) html += '<input class="input" style="margin-bottom:12px;" placeholder="Rechercher un compte surveillé…" value="' + esc(state.adminFilatureSearch || "") + '" data-action-input="admin-filature-search" />';

  for (var i = 0; i < filteredWatchlist.length; i++) {
    var wPhone = filteredWatchlist[i];
    var wAcc = findAccountByPhone(wPhone);
    var wLog = getFilatureLog(wPhone);
    var isOpenLog = state.adminFilatureOpenPhone === normalizeWalletPhone(wPhone);
    html += '<div class="card-row" style="flex-direction:column;align-items:stretch;margin-bottom:8px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;cursor:pointer;" data-action="toggle-admin-filature-log" data-value="' + esc(wPhone) + '">';
    html += '<div><div style="font-weight:700;font-size:13px;">' + esc(wAcc ? (wAcc.shopName || wAcc.name) : wPhone) + '</div><div style="font-size:11px;color:var(--text-dim);">' + esc(wPhone) + ' · ' + wLog.events.length + ' événement(s)</div></div>';
    html += '<div style="display:flex;align-items:center;gap:10px;"><button class="link-btn" style="color:var(--danger);font-size:11px;" data-action="remove-filature-watch" data-value="' + esc(wPhone) + '"><i class="fa-solid fa-trash"></i></button><i class="fa-solid ' + (isOpenLog ? 'fa-chevron-up' : 'fa-chevron-down') + '" style="color:var(--text-dim);font-size:11px;"></i></div>';
    html += '</div>';
    if (isOpenLog) {
      html += '<div style="margin-top:10px;border-top:1px solid var(--border-color);padding-top:10px;max-height:400px;overflow-y:auto;">';
      var typeLabels = { navigation: "📍 Navigation", produit_consulte: "👁️ Produit consulté", temps_passe: "⏱️ Temps passé", recherche: "🔍 Recherche", clic: "👆 Action", gain: "💰 Gain", depense: "💸 Dépense" };
      var sortedEvents = wLog.events.slice().reverse();
      if (sortedEvents.length === 0) {
        html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucun événement enregistré pour l\'instant.</div>';
      }
      for (var e = 0; e < sortedEvents.length; e++) {
        var ev = sortedEvents[e];
        html += '<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px dashed var(--border-color);font-size:11.5px;">';
        html += '<div><span style="font-weight:700;">' + (typeLabels[ev.type] || ev.type) + '</span> — ' + esc(ev.detail) + (ev.accountName ? ' <span style="color:var(--text-dim);">(' + esc(ev.accountName) + ')</span>' : '') + '</div>';
        html += '<div style="color:var(--text-dim);white-space:nowrap;margin-left:8px;">' + fmtDateTime(ev.at) + '</div>';
        html += '</div>';
      }
      html += '</div>';
    }
    html += '</div>';
  }
  return html;
}

function renderAdminWallets() {
  // Demandes Diaspora en attente — chargées une seule fois par ouverture
  // de l'écran (pas de téléchargement en bloc, juste cette liste précise).
  if (state.adminDiasporaRequests === null && !state._diasporaFetchInFlight) {
    state._diasporaFetchInFlight = true;
    callWalletOperation({ operation: "admin_list_diaspora_requests" }).then(function(res) {
      state._diasporaFetchInFlight = false;
      state.adminDiasporaRequests = res.success ? (res.requests || []) : [];
      render();
    });
  }
  var diasporaHtml = '';
  if (state.adminDiasporaRequests && state.adminDiasporaRequests.length > 0) {
    diasporaHtml += '<div class="section-title" style="font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-earth-africa"></i> Demandes Diaspora en attente (' + state.adminDiasporaRequests.length + ')</div>';
    for (var di = 0; di < state.adminDiasporaRequests.length; di++) {
      var dreq = state.adminDiasporaRequests[di];
      diasporaHtml += '<div class="card-row" style="margin-bottom:8px;">';
      diasporaHtml += '<div style="flex:1;"><div style="font-weight:700;font-size:13px;">' + esc(dreq.accountName) + ' (' + esc(dreq.accountPhone) + ')</div><div style="font-size:11px;color:var(--text-dim);">De : ' + esc(dreq.senderName || "?") + (dreq.message ? ' — "' + esc(dreq.message) + '"' : '') + '</div></div>';
      diasporaHtml += '<div style="font-weight:800;font-size:13px;margin-right:8px;">' + money(dreq.amount) + '</div>';
      diasporaHtml += '<button class="btn-secondary" style="padding:6px 10px;margin-right:6px;" data-action="admin-approve-diaspora" data-value="' + esc(dreq.id) + '"><i class="fa-solid fa-check"></i></button>';
      diasporaHtml += '<button class="link-btn" style="color:var(--danger);" data-action="admin-reject-diaspora" data-value="' + esc(dreq.id) + '"><i class="fa-solid fa-xmark"></i></button>';
      diasporaHtml += '</div>';
    }
  }

  var query = (state.adminWalletSearch || "").toLowerCase().trim();
  var html = diasporaHtml + '<div class="glass-card" style="padding:12px;margin-bottom:14px;">';
  html += '<div style="display:flex;gap:8px;">';
  html += '<div style="position:relative;flex:1;"><i class="fa-solid fa-magnifying-glass" style="position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--text-dim);font-size:13px;"></i>';
  html += '<input class="input" id="admin-wallet-search-input" style="padding-left:34px;" placeholder="Rechercher un compte, un numéro..." value="' + esc(state.adminWalletSearch || "") + '" data-bind="adminWalletSearch" data-enter-action="submit-admin-wallet-search" />';
  html += '</div>';
  html += '<button class="btn-primary" style="flex:0;padding:0 16px;" data-action="submit-admin-wallet-search"><i class="fa-solid fa-magnifying-glass"></i></button>';
  html += '</div></div>';

  // Recherche CIBLÉE côté serveur (voir adminSearchWallets) — jamais un
  // téléchargement de tout le monde comme avant. Les résultats déjà
  // reçus sont mis en cache dans state.adminWalletSearchResults.
  var rows = state.adminWalletSearchResults || [];
  if (!query) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Tapez un nom ou un numéro pour rechercher un portefeuille.</div>';
  } else if (state.adminWalletSearchLoading) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Recherche en cours…</div>';
  } else {
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">' + rows.length + ' résultat(s)</div>';
    if (rows.length === 0) {
      html += '<div class="empty-state"><i class="fa-solid fa-wallet"></i><div class="title">Aucun résultat</div></div>';
    }
  }

  for (var r = 0; r < rows.length; r++) {
    var row = rows[r];
    var isOpen = state.adminWalletOpenId === row.accountId;
    html += '<div class="card-row" style="flex-direction:column;align-items:stretch;margin-bottom:8px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;cursor:pointer;" data-action="toggle-admin-wallet" data-value="' + esc(row.accountId) + '">';
    html += '<div><div style="font-weight:700;font-size:13px;">' + esc(row.name || "") + '</div><div style="font-size:11px;color:var(--text-dim);">' + esc(row.phone || "") + '</div></div>';
    html += '<div style="display:flex;align-items:center;gap:8px;"><div style="font-weight:800;font-size:14px;color:var(--accent);">' + money(row.balance) + '</div><i class="fa-solid ' + (isOpen ? 'fa-chevron-up' : 'fa-chevron-down') + '" style="color:var(--text-dim);font-size:11px;"></i></div>';
    html += '</div>';
    if (isOpen) {
      html += '<div style="margin-top:10px;border-top:1px solid var(--border-color);padding-top:10px;">';
      html += '<div style="display:flex;gap:8px;margin-bottom:10px;">';
      html += '<input class="input" style="flex:1;" type="number" placeholder="Montant" id="admin-wallet-adjust-' + esc(row.accountId) + '" />';
      html += '<button class="btn-secondary" style="flex:0;padding:10px 12px;" data-action="admin-wallet-credit" data-value="' + esc(row.accountId) + '"><i class="fa-solid fa-plus"></i></button>';
      html += '<button class="btn-secondary" style="flex:0;padding:10px 12px;color:var(--danger);" data-action="admin-wallet-debit" data-value="' + esc(row.accountId) + '"><i class="fa-solid fa-minus"></i></button>';
      html += '</div>';
      var detail = state.adminWalletDetail && state.adminWalletDetail.accountId === row.accountId ? state.adminWalletDetail : null;
      if (!detail) {
        html += '<div style="font-size:11.5px;color:var(--text-dim);">Chargement du détail…</div>';
      } else {
        var txns = (detail.wallet.transactions || []).slice().reverse();
        if (txns.length === 0) {
          html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucun mouvement.</div>';
        } else {
          for (var t = 0; t < txns.length; t++) {
            var tx = txns[t];
            html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px dashed var(--border-color);font-size:11.5px;">';
            html += '<div><div style="font-weight:700;">' + esc(walletReasonLabel(tx)) + '</div><div style="color:var(--text-dim);">' + fmtDateTime(tx.createdAt) + (tx.message ? ' — "' + esc(tx.message) + '"' : '') + '</div></div>';
            html += '<div style="display:flex;align-items:center;gap:8px;"><span style="font-weight:800;color:' + (tx.type === "credit" ? 'var(--success)' : 'var(--danger)') + ';">' + (tx.type === "credit" ? '+' : '−') + money(tx.amount) + '</span>';
            html += '<button class="link-btn" style="color:var(--danger);padding:2px;" data-action="admin-wallet-delete-txn" data-value="' + esc(row.accountId) + '" data-txn="' + esc(tx.id) + '"><i class="fa-solid fa-trash"></i></button></div>';
            html += '</div>';
          }
        }
      }
      html += '</div>';
    }
    html += '</div>';
  }

  // ---- Cagnottes — consultables et supprimables ici aussi ----
  html += '<div class="section-title" style="font-size:14px;margin:20px 0 10px;"><i class="fa-solid fa-hand-holding-heart"></i> Cagnottes (' + state.cagnottes.length + ')</div>';
  if (state.cagnottes.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucune cagnotte pour l\'instant.</div>';
  } else {
    var cagnottesSorted = state.cagnottes.filter(inAdminScope).sort(function(a, b) { return b.createdAt - a.createdAt; });
    for (var ci = 0; ci < cagnottesSorted.length; ci++) {
      var cg = cagnottesSorted[ci];
      html += '<div class="card-row" style="margin-bottom:8px;">';
      html += '<div style="flex:1;"><div style="font-weight:700;font-size:13px;">' + esc(cg.title) + (cg.status === "closed" ? ' <span style="font-size:10.5px;color:var(--text-dim);">(clôturée)</span>' : '') + '</div><div style="font-size:11px;color:var(--text-dim);">Par ' + esc(cg.creatorName) + ' · ' + cg.contributions.length + ' cotisation(s)</div></div>';
      html += '<div style="font-weight:800;font-size:13px;margin-right:8px;">' + money(cg.balance) + '</div>';
      html += '<button class="link-btn" style="color:var(--danger);" data-action="admin-delete-cagnotte" data-value="' + esc(cg.id) + '"><i class="fa-solid fa-trash"></i></button>';
      html += '</div>';
    }
  }
  return html;
}

function renderAdminLivreurs() {
  var allLivreurs = state.accounts.filter(function(a) { return a.role === "livreur" || a.livreurApplicationStatus === "approved"; });
  if (allLivreurs.length === 0) {
    return '<div class="empty-state"><i class="fa-solid fa-truck-fast"></i><div class="title">' + t("ad_no_livreur") + '</div></div>';
  }
  var livSearch = (state.adminLivreursSearch || "").toLowerCase().trim();
  var livreurs = allLivreurs;
  if (livSearch) {
    livreurs = allLivreurs.filter(function(a) { return (a.name || "").toLowerCase().indexOf(livSearch) !== -1 || (a.phone || "").indexOf(livSearch) !== -1; });
  }
  var livCollapsed = !!state.collapsedAdminSections.livreursList;
  var html = '';
  var grandTotalEarnings = 0;
  var grandTotalDeliveries = 0;
  // Les totaux globaux portent toujours sur TOUS les livreurs, même
  // repliés ou filtrés par la recherche — seule la liste détaillée
  // ci-dessous change avec ces deux réglages.
  for (var gi = 0; gi < allLivreurs.length; gi++) {
    var gLiv = allLivreurs[gi];
    var gLivOrders = state.orders.filter(function(o) { return o.livreurId === gLiv.id && o.status === "Livrée"; });
    var gLivParcels = state.externalParcels.filter(function(p) { return p.livreurId === gLiv.id && p.status === "Livré"; });
    grandTotalDeliveries += gLivOrders.length + gLivParcels.length;
    for (var gj = 0; gj < gLivOrders.length; gj++) grandTotalEarnings += gLivOrders[gj].deliveryFee || 0;
    for (var gk = 0; gk < gLivParcels.length; gk++) grandTotalEarnings += gLivParcels[gk].deliveryFee || 0;
  }
  if (allLivreurs.length > 5) html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;"><input class="input" placeholder="' + t("ad_search_livreur") + '" value="' + esc(state.adminLivreursSearch || "") + '" data-action-input="admin-livreurs-search" style="flex:1;" /><button class="link-btn" style="flex:0;padding:8px;" data-action="toggle-admin-section" data-value="livreursList"><i class="fa-solid ' + (livCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button></div>';
  for (var i = 0; i < livreurs.length && !livCollapsed; i++) {
    var liv = livreurs[i];
    var livOrders = state.orders.filter(function(o) { return o.livreurId === liv.id && o.status === "Livrée"; });
    var livParcels = state.externalParcels.filter(function(p) { return p.livreurId === liv.id && p.status === "Livré"; });
    var earnings = 0;
    for (var j = 0; j < livOrders.length; j++) earnings += livOrders[j].deliveryFee || 0;
    for (var k = 0; k < livParcels.length; k++) earnings += livParcels[k].deliveryFee || 0;

    html += '<div class="card-row" style="flex-direction:column;align-items:stretch;cursor:pointer;" data-action="open-admin-livreur-detail" data-value="' + liv.id + '">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">';
    html += '<div style="font-weight:800;font-size:14px;"><i class="fa-solid fa-truck-fast"></i> ' + esc(liv.name) + (liv.banned ? ' 🚫' : '') + ' <i class="fa-solid fa-arrow-up-right-from-square" style="font-size:10px;color:var(--text-dim);"></i></div>';
    html += '<span style="font-size:11px;color:var(--text-dim)">' + esc(liv.phone || '') + '</span>';
    html += '</div>';
    html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:3px 0"><span>' + t("ad_deliveries_done") + '</span><span>' + (livOrders.length + livParcels.length) + '</span></div>';
    html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:3px 0;color:var(--accent)"><span>' + t("ad_cumulated_earnings") + '</span><span style="font-weight:800">' + money(earnings) + '</span></div>';
    html += '</div>';
  }
  html = '<div class="stats-row"><div class="stat-card"><div class="stat-value">' + allLivreurs.length + '</div><div class="stat-label">' + t("ad_livreurs_stat") + '</div></div>' +
    '<div class="stat-card"><div class="stat-value">' + grandTotalDeliveries + '</div><div class="stat-label">' + t("ad_deliveries_stat") + '</div></div>' +
    '<div class="stat-card"><div class="stat-value" style="color:var(--accent)">' + money(grandTotalEarnings) + '</div><div class="stat-label">' + t("ad_cumulated_earnings") + '</div></div></div>' + html;
  return html;
}

function renderAdminPointsVente() {
  var allShops = relaisShopsList();
  var html = '';
  if (allShops.length === 0) {
    return '<div class="empty-state"><i class="fa-solid fa-shop-slash"></i><div class="title">' + t("ad_no_pv") + '</div></div>';
  }

  var grandTotalDue = 0;
  for (var gi = 0; gi < allShops.length; gi++) {
    var gShopOrders = state.orders.filter(function(o) { return o.deliveryMode === "relais" && o.relaisShopId === allShops[gi].id && o.status === "Livrée"; });
    for (var gj = 0; gj < gShopOrders.length; gj++) {
      if (!gShopOrders[gj].commissionSettled) grandTotalDue += gShopOrders[gj].commissionAmount || 0;
    }
  }

  var pvSearch = (state.adminPointsVenteSearch || "").toLowerCase().trim();
  var shops = allShops;
  if (pvSearch) {
    shops = allShops.filter(function(s) { return ((s.shopName || s.name || "").toLowerCase().indexOf(pvSearch) !== -1) || (s.phone || "").indexOf(pvSearch) !== -1; });
  }
  var pvCollapsed = !!state.collapsedAdminSections.pointsVenteList;
  if (allShops.length > 5) html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;"><input class="input" placeholder="' + t("ad_search_pv") + '" value="' + esc(state.adminPointsVenteSearch || "") + '" data-action-input="admin-pointsvente-search" style="flex:1;" /><button class="link-btn" style="flex:0;padding:8px;" data-action="toggle-admin-section" data-value="pointsVenteList"><i class="fa-solid ' + (pvCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button></div>';
  for (var i = 0; i < shops.length && !pvCollapsed; i++) {
    var shop = shops[i];
    var shopOrders = state.orders.filter(function(o) { return o.deliveryMode === "relais" && o.relaisShopId === shop.id && o.status === "Livrée"; });
    var encaisse = 0, due = 0, reglee = 0, unsettledCount = 0;
    for (var j = 0; j < shopOrders.length; j++) {
      encaisse += shopOrders[j].total;
      if (shopOrders[j].commissionSettled) reglee += shopOrders[j].commissionAmount || 0;
      else { due += shopOrders[j].commissionAmount || 0; unsettledCount++; }
    }

    html += '<div class="card-row" style="flex-direction:column;align-items:stretch">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">';
    html += '<div style="font-weight:800;font-size:14px;cursor:pointer;" data-action="open-admin-relais-detail" data-value="' + shop.id + '"><i class="fa-solid fa-shop"></i> ' + esc(shop.shopName || shop.name) + ' <i class="fa-solid fa-arrow-up-right-from-square" style="font-size:10px;color:var(--text-dim);"></i></div>';
    html += '<span style="font-size:11px;color:var(--text-dim)">' + esc(shop.phone) + '</span>';
    html += '</div>';
    html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:3px 0"><span>' + t("ad_delivered_orders_stat") + '</span><span>' + shopOrders.length + '</span></div>';
    html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:3px 0"><span>' + t("ad_collected_by_shop") + '</span><span style="font-weight:700">' + money(encaisse) + '</span></div>';
    html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:3px 0;color:var(--accent)"><span>' + t("ad_commission_due") + '</span><span style="font-weight:800">' + money(due) + '</span></div>';
    html += '<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;color:var(--text-dim)"><span>' + t("ad_commission_settled") + '</span><span>' + money(reglee) + '</span></div>';
    if (unsettledCount > 0) {
      html += '<button class="btn-secondary" style="margin-top:10px" data-action="settle-relais-commission" data-value="' + shop.id + '"><i class="fa-solid fa-check-double"></i> ' + t("ad_mark_settled") + unsettledCount + ' ' + t("ad_order_word") + (unsettledCount > 1 ? t("ad_orders_word_plural") : '') + ')</button>';
    } else {
      html += '<div style="font-size:11px;color:var(--success);margin-top:8px"><i class="fa-solid fa-circle-check"></i> ' + t("ad_all_settled") + '</div>';
    }
    html += '</div>';
  }

  html = '<div class="stats-row"><div class="stat-card"><div class="stat-value">' + allShops.length + '</div><div class="stat-label">' + t("ad_pv_stat") + '</div></div>' +
    '<div class="stat-card"><div class="stat-value" style="color:var(--accent)">' + money(grandTotalDue) + '</div><div class="stat-label">' + t("ad_total_commission_due") + '</div></div></div>' + html;

  return html;
}

// ---------- ADMIN : TARIFS LIVRAISON (éditeur) ----------
// ---------- ADMIN : MODÉRATION DES ARTICLES ----------
function renderAdminModeration() {
  var pending = (state.products || []).filter(function(p) { return p.moderationStatus === "pending" && inAdminScope(p); });
  var rejected = (state.products || []).filter(function(p) { return p.moderationStatus === "rejected" && inAdminScope(p); });
  var html = '';
  // ---- Traduction des articles (anglais + hindi) ----
  var trTodo = (state.products || []).filter(function(p) { return productTranslationNeeds(p).length > 0; }).length;
  var trTotal = (state.products || []).length;
  html += '<div class="glass-card" style="padding:14px;margin-bottom:14px;">';
  html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:6px;"><i class="fa-solid fa-language"></i> Traduction des articles</div>';
  html += '<div style="font-size:12px;margin-bottom:10px;">' + (trTotal - trTodo) + ' / ' + trTotal + ' article(s) traduits en anglais et en hindi' + (trTodo ? ' — <strong>' + trTodo + ' à traduire</strong>' : ' ✅') + '</div>';
  var tb = state.trBatch;
  if (tb && tb.running) {
    var pct = tb.total ? Math.round(100 * tb.done / tb.total) : 0;
    html += '<div style="height:8px;border-radius:99px;background:var(--bg-body);overflow:hidden;margin-bottom:6px;"><div style="height:100%;width:' + pct + '%;background:var(--accent);"></div></div>';
    html += '<div style="font-size:11px;color:var(--text-dim);">Traduction en cours… ' + tb.done + ' / ' + tb.total + ' — gardez cette page ouverte.</div>';
  } else {
    if (tb && tb.msg) html += '<div style="font-size:11.5px;margin-bottom:8px;">' + esc(tb.msg) + '</div>';
    if (trTodo) html += '<button class="btn-primary" style="width:100%;" data-action="admin-translate-products"><i class="fa-solid fa-language"></i> Traduire les ' + trTodo + ' article(s) manquant(s)</button>';
  }
  html += '</div>';
  html += renderAdminCollapsibleList("moderationPending", '<i class="fa-solid fa-hourglass-half"></i> En attente de validation', pending, function(p) {
    var card = '<div class="glass-card" style="padding:12px;margin-bottom:10px;">';
    card += '<div style="display:flex;gap:10px;">';
    card += (p.images && p.images[0]) ? '<img loading="lazy" ' + snsThumbSrc(p.images[0]) + ' style="width:64px;height:64px;border-radius:10px;object-fit:cover;flex-shrink:0;" />' : '<div class="emoji-thumb" style="width:64px;height:64px;font-size:24px;">' + (p.emoji || '📦') + '</div>';
    card += '<div style="flex:1;min-width:0;">';
    card += '<div style="font-weight:700;font-size:13px;">' + esc(p.name) + '</div>';
    card += '<div style="font-size:11px;color:var(--text-dim);">' + esc(p.shopName || '') + ' · ' + money(p.price) + '</div>';
    card += '<div style="font-size:11px;color:#c77700;margin-top:4px;"><i class="fa-solid fa-circle-info"></i> ' + esc(p.moderationReason || 'Raison non précisée') + '</div>';
    card += '</div></div>';
    if (Array.isArray(p.reportReasons) && p.reportReasons.length) {
      card += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:8px;">Motifs : ' + p.reportReasons.map(function(r) { return esc(r.reason); }).join(' · ') + '</div>';
    }
    if (p.description) card += '<div style="font-size:11px;margin-top:6px;">' + esc(p.description.slice(0, 160)) + (p.description.length > 160 ? '…' : '') + '</div>';
    card += '<div style="display:flex;gap:8px;margin-top:10px;">';
    card += '<button class="btn-primary" style="flex:1;padding:9px;font-size:12px;" data-action="moderation-approve" data-value="' + p.id + '"><i class="fa-solid fa-check"></i> Approuver</button>';
    card += '<button class="btn-secondary" style="flex:1;padding:9px;font-size:12px;color:var(--danger);border-color:var(--danger);" data-action="moderation-reject" data-value="' + p.id + '"><i class="fa-solid fa-ban"></i> Refuser</button>';
    card += '</div>';
    card += '</div>';
    return card;
  }, {
    emptyText: "Aucun article en attente. 👍",
    searchPlaceholder: "Rechercher par article ou boutique...",
    searchFn: function(p, q) { return (p.name || "").toLowerCase().indexOf(q) !== -1 || (p.shopName || "").toLowerCase().indexOf(q) !== -1; }
  });
  html += renderAdminCollapsibleList("moderationRejected", '<i class="fa-solid fa-ban"></i> Articles refusés', rejected, function(p) {
    var row = '<div class="card-row">';
    row += '<div style="flex:1;min-width:0;"><div style="font-weight:700;font-size:12.5px;">' + esc(p.name) + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + esc(p.shopName || '') + '</div></div>';
    row += '<button class="link-btn" style="font-size:11px;" data-action="moderation-approve" data-value="' + p.id + '">Rétablir</button>';
    row += '<button class="link-btn" style="color:var(--danger);margin-left:8px;" data-action="admin-delete-product" data-value="' + p.id + '"><i class="fa-solid fa-trash"></i></button>';
    row += '</div>';
    return row;
  }, { emptyText: "Aucun article refusé." });
  return html;
}

function renderAdminTarifs() {
  var cfg = getDeliveryFeesConfig();
  var rate = getRelaisCommissionRate();
  var baseCfg = getDeliveryBaseConfig();
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-route"></i> Livraison Express — au kilomètre réel</div>';
  html += '<label class="field-label" style="margin-top:0;">Nom du point de référence</label>';
  html += '<input class="input" id="delivery-base-label" value="' + esc(baseCfg.label) + '" />';
  html += '<label class="field-label">Position du point de référence</label>';
  html += '<button type="button" class="btn-secondary" data-action="capture-delivery-base-gps"><i class="fa-solid fa-location-crosshairs"></i> Localiser depuis ici</button>';
  html += renderGpsPasteField("deliveryBaseDraft.lat", "deliveryBaseDraft.lng");
  html += '<div style="font-size:11px;color:var(--text-dim);margin-top:6px;">📍 Position actuelle : ' + baseCfg.lat.toFixed(5) + ', ' + baseCfg.lng.toFixed(5) + '</div>';
  html += '<div style="display:flex;gap:10px;margin-top:10px;">';
  html += '<div style="flex:1;"><label class="field-label">Tarif / km (FCFA)</label><input class="input" id="delivery-base-perkm" type="number" value="' + baseCfg.perKm + '" /></div>';
  html += '<div style="flex:1;"><label class="field-label">Minimum (FCFA)</label><input class="input" id="delivery-base-min" type="number" value="' + baseCfg.minimum + '" /></div>';
  html += '</div>';
  html += '<button class="btn-primary" style="margin-top:12px;" data-action="save-delivery-base-config">Enregistrer</button>';
  html += '</div>';

  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px">';
  html += '<label class="field-label">Commission Point de Retrait (% de la livraison)</label>';
  html += '<div style="display:flex;gap:8px;align-items:center">';
  html += '<input class="input" id="relais-commission-input" type="number" step="0.5" value="' + (rate * 100) + '" style="max-width:120px" />';
  html += '<span>%</span>';
  html += '<button class="btn-secondary" style="width:auto;padding:0 16px" data-action="save-relais-commission"><i class="fa-solid fa-floppy-disk"></i> Enregistrer</button>';
  html += '</div></div>';

  var cities = Object.keys(cfg);
  for (var i = 0; i < cities.length; i++) {
    var city = cities[i];
    html += '<div class="section-title" style="font-size:15px;margin-top:16px">' + esc(city) + '</div>';
    var zones = Object.keys(cfg[city]);
    for (var j = 0; j < zones.length; j++) {
      var zone = zones[j];
      var z = cfg[city][zone];
      html += '<div class="card-row" style="align-items:center;">';
      html += '<div style="flex:1;font-weight:700;font-size:13px">' + esc(zone) + '</div>';
      html += '<div style="display:flex;flex-direction:column;gap:2px;margin-right:8px;">';
      html += '<label style="font-size:9.5px;color:var(--text-dim);">Express</label>';
      html += '<input class="input" style="width:90px;padding:6px 8px;" type="number" id="fee-express-' + city + '-' + zone + '" value="' + z.express + '" />';
      html += '</div>';
      html += '<div style="display:flex;flex-direction:column;gap:2px;">';
      html += '<label style="font-size:9.5px;color:var(--text-dim);">Relais</label>';
      html += '<input class="input" style="width:90px;padding:6px 8px;" type="number" id="fee-relais-' + city + '-' + zone + '" value="' + z.relais + '" />';
      html += '</div>';
      html += '</div>';
    }
  }
  html += '<button class="btn-primary" style="margin-top:16px" data-action="save-delivery-fees"><i class="fa-solid fa-floppy-disk"></i> Enregistrer tous les tarifs</button>';

  // ---- Livraison inter-villes (envoi par car, hors Bamako) ----
  var icCfg = getIntercityDeliveryConfig();
  html += '<div class="glass-card" style="padding:14px;margin-top:20px;margin-bottom:16px">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:4px;"><i class="fa-solid fa-bus"></i> Livraison inter-villes (envoi par car)</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:12px;">Pour les villes hors Bamako — l\'acheteur récupère son colis à la gare routière. Un prix de base par ville, plus une majoration si la commande contient plusieurs articles (colis plus gros à envoyer). Laisse vide tant que tu n\'as pas le vrai tarif du car pour cette ville — aucun prix n\'est deviné.</div>';
  var icCities = intercityDeliveryCities();
  for (var ici = 0; ici < icCities.length; ici++) {
    var icCity = icCities[ici];
    var icVal = icCfg[icCity] || { basePrice: null, extraItemFee: null };
    html += '<div style="border-top:1px solid var(--border-color);padding-top:10px;margin-top:10px;">';
    html += '<div style="font-weight:700;font-size:13px;margin-bottom:6px;">' + esc(icCity) + '</div>';
    html += '<div style="display:flex;gap:10px;">';
    html += '<div style="flex:1;"><label class="field-label" style="margin-top:0;font-size:10.5px;">Prix de base (FCFA)</label><input class="input" type="number" placeholder="Non configuré" id="intercity-base-' + esc(icCity) + '" value="' + (icVal.basePrice != null ? icVal.basePrice : '') + '" /></div>';
    html += '<div style="flex:1;"><label class="field-label" style="margin-top:0;font-size:10.5px;">Majoration / article suppl. (FCFA)</label><input class="input" type="number" placeholder="0" id="intercity-extra-' + esc(icCity) + '" value="' + (icVal.extraItemFee != null ? icVal.extraItemFee : '') + '" /></div>';
    html += '</div>';
    html += '</div>';
  }
  html += '<button class="btn-primary" style="margin-top:14px" data-action="save-intercity-delivery-fees"><i class="fa-solid fa-floppy-disk"></i> Enregistrer les tarifs inter-villes</button>';
  html += '</div>';

  return html;
}

function renderAdminDashboard(stats) {
  maybeRunLigdiSweep();
  var html = '';
  html += renderVisitStatsCard();
  if (!state.adminCountryScope) {
    var scopedCountries = {};
    for (var sci = 0; sci < state.orders.length; sci++) { scopedCountries[state.orders[sci].country || "Mali"] = true; }
    var scopedCurrencies = {};
    Object.keys(scopedCountries).forEach(function(c) { scopedCurrencies[currencyForCountry(c)] = true; });
    if (Object.keys(scopedCurrencies).length > 1) {
      html += '<div style="background:var(--bg-body);border-radius:12px;padding:10px 14px;margin-bottom:14px;font-size:11px;color:var(--text-dim);"><i class="fa-solid fa-circle-info"></i> ' + t("ad_multi_currency_note") + ' (' + Object.keys(scopedCurrencies).join(", ") + ') ' + t("ad_multi_currency_note_end") + '</div>';
    }
  }
  html += '<div class="admin-stats-grid">';
  html += '<div class="admin-stat-box" style="cursor:pointer;" data-action="open-admin-orders-list" data-value="all"><div class="stat-number">' + money(stats.totalSales, state.adminCountryScope) + '</div><div class="stat-label">' + t("ad_revenue") + '</div></div>';
  html += '<div class="admin-stat-box" style="cursor:pointer;" data-action="open-admin-orders-list" data-value="all"><div class="stat-number">' + stats.totalOrders + '</div><div class="stat-label">' + t("ad_orders") + '</div></div>';
  html += '<div class="admin-stat-box" style="cursor:pointer;" data-action="open-admin-products-list"><div class="stat-number">' + stats.productsCount + '</div><div class="stat-label">' + t("ad_products") + '</div></div>';
  html += '<div class="admin-stat-box" style="cursor:pointer;" data-action="open-admin-products-list"><div class="stat-number">' + stats.totalItemsSold + '</div><div class="stat-label">' + t("ad_items_sold") + '</div></div>';
  html += '<div class="admin-stat-box" style="cursor:pointer;" data-action="open-admin-orders-list" data-value="delivered"><div class="stat-number">' + money(stats.totalRevenue, state.adminCountryScope) + '</div><div class="stat-label">' + t("ad_gems_revenue") + '</div></div>';
  var boostRevenueForDash = state.boosts.filter(function(b) { return b.status === "actif" && inAdminScope(b); }).reduce(function(sum, b) { return sum + (b.price || 0); }, 0);
  html += '<div class="admin-stat-box" style="cursor:pointer;" data-action="set-admin-tab" data-value="pub"><div class="stat-number">' + money(boostRevenueForDash, state.adminCountryScope) + '</div><div class="stat-label">' + t("ad_boost_revenue") + '</div></div>';
  html += '<div class="admin-stat-box" style="cursor:pointer;" data-action="open-admin-orders-list" data-value="all"><div class="stat-number">' + money(stats.avgOrderValue, state.adminCountryScope) + '</div><div class="stat-label">' + t("ad_avg_cart") + '</div></div>';
  html += '<div class="admin-stat-box" style="cursor:pointer;" data-action="set-admin-tab" data-value="reviews"><div class="stat-number">' + stats.totalReviews + '</div><div class="stat-label">' + t("ad_reviews") + '</div></div>';
  html += '<div class="admin-stat-box" style="cursor:pointer;" data-action="set-admin-tab" data-value="reviews"><div class="stat-number">' + stats.avgRating.toFixed(1) + ' ⭐</div><div class="stat-label">' + t("ad_avg_rating") + '</div></div>';
  html += '</div>';
  html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">';
  html += '<select class="input" style="flex:1;min-width:80px;padding:6px 10px;font-size:12px;" data-bind="adminStats.period" data-action-change="admin-period">';
  html += '<option value="jour" ' + (stats.period === "jour" ? 'selected' : '') + '>' + t("ad_by_day") + '</option>';
  html += '<option value="semaine" ' + (stats.period === "semaine" ? 'selected' : '') + '>' + t("ad_by_week") + '</option>';
  html += '<option value="mois" ' + (stats.period === "mois" ? 'selected' : '') + '>' + t("ad_by_month") + '</option>';
  html += '</select>';
  html += '<input class="input" type="date" style="flex:1;min-width:80px;padding:6px 10px;font-size:12px;" data-bind="adminStats.dateFrom" />';
  html += '<input class="input" type="date" style="flex:1;min-width:80px;padding:6px 10px;font-size:12px;" data-bind="adminStats.dateTo" />';
  html += '</div>';
  html += '<div class="chart-container"><canvas id="adminChart"></canvas></div>';
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;margin-bottom:16px;box-shadow:var(--shadow);">';
  html += '<div style="font-weight:700;font-size:13px;margin-bottom:8px;">' + t("ad_top_products") + '</div>';
  if (stats.topProducts.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim)">' + t("ad_no_data") + '</div>';
  } else {
    for (var i = 0; i < stats.topProducts.length; i++) {
      var p = stats.topProducts[i];
      html += '<div style="display:flex;justify-content:space-between;font-size:12px;padding:4px 0;border-bottom:1px solid var(--border-color);cursor:pointer;" data-action="admin-edit-product" data-value="' + p.id + '">';
      html += '<span>' + (i+1) + '. ' + esc(p.name) + '</span>';
      html += '<span style="font-weight:700;">' + p.qty + t("ad_sold_suffix") + '</span>';
      html += '</div>';
    }
  }
  html += '</div>';
  var cfgDash = getCommissionConfig();
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;box-shadow:var(--shadow);margin-bottom:16px;">';
  html += '<div style="font-weight:700;font-size:13px;margin-bottom:8px;">' + t("ad_details") + '</div>';
  html += '<div style="display:flex;justify-content:space-between;font-size:12px;padding:2px 0;"><span>' + t("ad_commission_sounsouni") + (cfgDash.totalCommissionRate * 100).toFixed(0) + '%)</span><span style="font-weight:700;">' + money(stats.totalCommission) + '</span></div>';
  html += '<div style="display:flex;justify-content:space-between;font-size:12px;padding:2px 0;"><span>' + t("ad_delivery_fees") + '</span><span style="font-weight:700;">' + money(stats.deliveryRevenue) + '</span></div>';
  html += '<div style="display:flex;justify-content:space-between;font-size:12px;padding:2px 0;border-top:1px solid var(--border-color);margin-top:4px;padding-top:4px;"><span>' + t("ad_total_revenue_sounsouni") + '</span><span style="font-weight:800;color:var(--accent);">' + money(stats.totalRevenue, state.adminCountryScope) + '</span></div>';
  html += '</div>';

  // ---- Commission 7% : détail avec/sans parrainage, liste dépliable ----
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;box-shadow:var(--shadow);margin-bottom:16px;">';
  html += '<button type="button" style="all:unset;display:flex;justify-content:space-between;align-items:center;width:100%;cursor:pointer;" data-action="toggle-admin-commission-detail">';
  html += '<div style="font-weight:700;font-size:13px;"><i class="fa-solid fa-hand-holding-dollar"></i> ' + t("ad_accumulated_commissions") + (cfgDash.totalCommissionRate * 100).toFixed(0) + '%)</div>';
  html += '<i class="fa-solid ' + (state.adminCommissionDetailOpen ? 'fa-chevron-up' : 'fa-chevron-down') + '"></i>';
  html += '</button>';
  html += '<div style="font-size:20px;font-weight:800;margin-top:8px;">' + money(stats.totalCommission) + '</div>';
  html += '<div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap;">';
  html += '<div style="flex:1;min-width:130px;background:var(--bg-body);border-radius:10px;padding:8px 10px;"><div style="font-size:10.5px;color:var(--text-dim);">' + t("ad_without_referral") + '</div><div style="font-weight:700;font-size:13px;">' + money(stats.totalCommissionWithoutAffiliate) + '</div></div>';
  html += '<div style="flex:1;min-width:130px;background:var(--bg-body);border-radius:10px;padding:8px 10px;"><div style="font-size:10.5px;color:var(--text-dim);">' + t("ad_with_referral") + '</div><div style="font-weight:700;font-size:13px;">' + money(stats.totalCommissionWithAffiliate) + '</div><div style="font-size:10px;color:var(--text-dim);">' + t("ad_of_which_paid") + ' ' + money(stats.totalAffiliatePaid) + ' ' + t("ad_paid_to_referrers") + '</div></div>';
  html += '</div>';
  if (state.adminCommissionDetailOpen) {
    html += '<div style="margin-top:12px;border-top:1px solid var(--border-color);padding-top:10px;max-height:320px;overflow-y:auto;">';
    var ordersWithCommission = state.orders.filter(function(o) { return o.commissionTotal != null; }).slice(0, 100);
    if (ordersWithCommission.length === 0) {
      html += '<div style="font-size:12px;color:var(--text-dim);">' + t("ad_no_commission_orders") + '</div>';
    } else {
      for (var oci = 0; oci < ordersWithCommission.length; oci++) {
        var oc = ordersWithCommission[oci];
        html += '<div style="display:flex;justify-content:space-between;align-items:center;font-size:11.5px;padding:6px 0;border-bottom:1px solid var(--border-color);">';
        html += '<div><span style="font-weight:700;">#' + oc.id.slice(-5).toUpperCase() + '</span> · ' + new Date(oc.createdAt || 0).toLocaleDateString("fr-FR") + (oc.affiliateId ? ' · <span style="color:var(--accent);">' + t("ad_referred") + '</span>' : ' · <span style="color:var(--text-dim);">' + t("ad_no_referral") + '</span>') + '</div>';
        html += '<div style="font-weight:700;">' + money(oc.commissionTotal) + '</div>';
        html += '</div>';
      }
    }
    html += '</div>';
  }
  html += '</div>';

  // ---- Gains de parrainage par compte (déplacé depuis l'onglet Affiliation) ----
  var accountsWithAffiliateDash = state.accounts.filter(function(a) { return a.affiliateCode || (a.affiliateBalance || 0) > 0 || (a.affiliateReferrals || 0) > 0; });
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;box-shadow:var(--shadow);margin-bottom:16px;">';
  html += '<button type="button" style="all:unset;display:flex;justify-content:space-between;align-items:center;width:100%;cursor:pointer;" data-action="toggle-admin-affiliate-accounts">';
  html += '<div style="font-weight:700;font-size:13px;"><i class="fa-solid fa-users"></i> ' + t("ad_referral_earnings_by_account") + accountsWithAffiliateDash.length + ')</div>';
  html += '<i class="fa-solid ' + (state.adminAffiliateAccountsOpen ? 'fa-chevron-up' : 'fa-chevron-down') + '"></i>';
  html += '</button>';
  if (state.adminAffiliateAccountsOpen) {
    html += '<div style="margin-top:12px;">';
    if (accountsWithAffiliateDash.length === 0) {
      html += '<div style="font-size:12px;color:var(--text-dim);">' + t("ad_no_active_referral_code") + '</div>';
    } else {
      for (var ai = 0; ai < accountsWithAffiliateDash.length; ai++) {
        var acc = accountsWithAffiliateDash[ai];
        html += '<div class="card-row" style="margin-bottom:8px;flex-direction:column;align-items:stretch;">';
        html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
        html += '<div><div style="font-weight:700;font-size:13px;">' + esc(acc.shopName || acc.name) + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + esc(acc.phone || '') + ' · ' + t("ad_code_label") + ' ' + esc(acc.affiliateCode || '—') + '</div></div>';
        html += '<div style="text-align:right;"><div style="font-weight:800;color:var(--accent);">' + money(acc.affiliateBalance || 0) + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + (acc.affiliateReferrals || 0) + t("ad_referral_count") + '</div></div>';
        html += '</div></div>';
      }
    }
    html += '</div>';
  }
  html += '</div>';

  // ---- Affiliation (fusionnée depuis son ancien onglet dédié) ----
  var affCfg = getCommissionConfig();
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;box-shadow:var(--shadow);margin-bottom:16px;">';
  html += '<div style="font-weight:700;font-size:13px;margin-bottom:8px;"><i class="fa-solid fa-link"></i> ' + t("ad_affiliation") + '</div>';
  html += '<label class="field-label" style="margin-top:0;font-size:10px;">' + t("ad_total_commission_label") + '</label>';
  html += '<input class="input" type="number" id="total-commission-rate-input" style="margin-bottom:8px;" value="' + (affCfg.totalCommissionRate * 100) + '" min="0" max="100" step="0.5" />';
  html += '<label class="field-label" style="font-size:10px;">' + t("ad_referrer_share_label") + '</label>';
  html += '<input class="input" type="number" id="affiliate-rate-input" style="margin-bottom:10px;" value="' + (affCfg.affiliateCommission * 100) + '" min="0" max="100" step="0.5" />';
  html += '<button class="btn-primary" style="width:100%;" data-action="save-affiliate-rate"><i class="fa-solid fa-save"></i> ' + t("ad_save") + '</button>';
  html += '</div>';

  // ---- Grille des modules — cœur de la navigation du centre de contrôle ----
  var tileList = state.adminIsOwner
    ? ["comptes","vendeurs","versements","disputes","moderation","relaisapplications","livreurapplications","quartiers","messagerie","tarifs","pub","apparence","partenaires","international","security","reviews","claude","test"]
    : ["comptes","vendeurs","versements","disputes","moderation","relaisapplications","livreurapplications","quartiers","messagerie","pub","reviews","partenaires"];
  html += '<div class="section-head" style="display:flex;align-items:baseline;justify-content:space-between;margin:20px 0 12px;"><h2 style="font-size:11px;text-transform:uppercase;letter-spacing:2px;color:var(--mc-dim);font-weight:700;margin:0;">' + t("ad_modules_title") + '</h2></div>';
  html += renderAdminTileGrid(tileList);

  html += '<script>setTimeout(function(){var ctx=document.getElementById("adminChart");if(!ctx)return;if(typeof Chart==="undefined"){if(window.snsLoadLib)window.snsLoadLib("chart").then(function(){try{render()}catch(e){}}).catch(function(){});return;}var chartData=' + JSON.stringify(stats.chartData) + ';var labels=' + JSON.stringify(stats.chartLabels) + ';new Chart(ctx,{type:"line",data:{labels:labels,datasets:[{label:"Ventes (FCFA)",data:chartData,borderColor:getComputedStyle(document.body).getPropertyValue("--accent").trim()||"#ff7a1a",backgroundColor:"rgba(255,122,26,0.1)",fill:true,tension:0.3}]},options:{responsive:true,plugins:{legend:{labels:{color:getComputedStyle(document.body).getPropertyValue("--text-secondary")}}},scales:{y:{beginAtZero:true,ticks:{color:getComputedStyle(document.body).getPropertyValue("--text-dim")}},x:{ticks:{color:getComputedStyle(document.body).getPropertyValue("--text-dim"),maxTicksLimit:10}}}}});},100);<\/script>';
  return html;
}

function renderAdminSellers(stats) {
  var html = '';
  var pendingVerifs = state.verificationRequests.filter(function(r) { return r.status === "pending" && inAdminScope(r); });
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;margin-bottom:16px;box-shadow:var(--shadow);">';
  html += '<div style="font-weight:700;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-shield-check"></i> ' + t("as_verification_requests") + pendingVerifs.length + ')</div>';
  if (pendingVerifs.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim)">' + t("as_no_new_request") + '</div>';
  } else {
    for (var vi = 0; vi < pendingVerifs.length; vi++) {
      var vr = pendingVerifs[vi];
      html += '<div class="card-row" style="margin-bottom:8px;">';
      html += '<div class="emoji-thumb"><i class="fa-solid fa-store"></i></div>';
      html += '<div style="flex:1;min-width:0;">';
      html += '<div style="font-weight:700;font-size:13px;">' + esc(vr.shopName) + '</div>';
      html += '<div style="font-size:11px;color:var(--text-dim);">' + esc(vr.accountName) + ' · ' + esc(vr.accountPhone || '') + '</div>';
      html += '</div>';
      html += '<button class="link-btn" style="color:var(--success);padding:6px;" data-action="approve-verification" data-value="' + vr.id + '"><i class="fa-solid fa-check"></i></button>';
      html += '<button class="link-btn" style="color:var(--danger);padding:6px;" data-action="reject-verification" data-value="' + vr.id + '"><i class="fa-solid fa-xmark"></i></button>';
      html += '</div>';
    }
  }
  html += '</div>';

  var mcfgV = getMarketConfig();
  var sellersSearch = (state.adminSellersSearch || "").toLowerCase().trim();
  var rankCollapsed = !!state.collapsedAdminSections.sellerRanking;
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;margin-bottom:16px;box-shadow:var(--shadow);">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;"><div style="font-weight:700;font-size:14px;">' + t("as_seller_ranking") + '</div><button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="sellerRanking"><i class="fa-solid ' + (rankCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button></div>';
  if (stats.sellerRanking.length > 6) html += '<input class="input" style="margin-bottom:10px;" placeholder="' + t("as_search_seller") + '" value="' + esc(state.adminSellersSearch || "") + '" data-action-input="admin-sellers-search" />';
  if (stats.sellerRanking.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim)">' + t("as_no_active_seller") + '</div>';
  } else if (!rankCollapsed) {
    var rankingToShow = sellersSearch ? stats.sellerRanking.filter(function(s) { return (s.name || "").toLowerCase().indexOf(sellersSearch) !== -1; }) : stats.sellerRanking;
    html += '<table class="seller-rank-table"><tr><th>' + t("as_th_rank") + '</th><th>' + t("as_th_seller") + '</th><th>' + t("as_th_sales") + '</th><th>' + t("as_th_orders") + '</th><th>' + t("as_th_reputation") + '</th></tr>';
    for (var i = 0; i < rankingToShow.length; i++) {
      var s = rankingToShow[i];
      var repHtml = '—';
      if (s.sellerId) {
        var rep = computeSellerReputation(s.sellerId);
        if (rep.totalOrders >= 3) repHtml = rep.stars.toFixed(1) + '/5 · ' + rep.label;
      }
      html += '<tr style="' + (s.sellerId ? 'cursor:pointer;' : '') + '" ' + (s.sellerId ? 'data-action="open-admin-account-detail" data-value="' + s.sellerId + '"' : '') + '><td class="rank-num">' + (stats.sellerRanking.indexOf(s) + 1) + '</td><td>' + esc(s.name) + '</td><td>' + money(s.total) + '</td><td>' + s.orders + '</td><td style="font-size:10.5px;">' + repHtml + '</td></tr>';
    }
    html += '</table>';
  }
  html += '</div>';
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;box-shadow:var(--shadow);">';
  html += '<div style="font-weight:700;font-size:14px;margin-bottom:10px;">' + t("as_summary") + '</div>';
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:12px;">';
  html += '<div><span style="color:var(--text-dim)">' + t("as_active_sellers") + '</span><br><strong>' + stats.sellersCount + '</strong></div>';
  html += '<div><span style="color:var(--text-dim)">' + t("as_shops") + '</span><br><strong>' + state.products.length + '</strong></div>';
  html += '</div></div>';

  // ---- Performance détaillée par vendeur (vues, conversion, boosts) ----
  var sellerIds = [];
  for (var pi = 0; pi < state.products.length; pi++) {
    if (sellerIds.indexOf(state.products[pi].sellerId) === -1) sellerIds.push(state.products[pi].sellerId);
  }
  if (sellerIds.length > 0) {
    var perfCollapsed = !!state.collapsedAdminSections.sellerPerformance;
    html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;margin-top:16px;box-shadow:var(--shadow);overflow-x:auto;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;"><div style="font-weight:700;font-size:14px;">' + t("as_performance_by_seller") + '</div><button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="sellerPerformance"><i class="fa-solid ' + (perfCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button></div>';
    if (!perfCollapsed) {
    html += '<table class="seller-rank-table"><tr><th>' + t("as_th_seller") + '</th><th>' + t("as_th_products") + '</th><th>' + t("as_th_views") + '</th><th>' + t("as_th_sales") + '</th><th>' + t("as_th_conversion") + '</th><th>' + t("as_th_active_boosts") + '</th></tr>';
    var sellerIdsToShow = sellersSearch ? sellerIds.filter(function(sid2) {
      return state.products.some(function(p) { return p.sellerId === sid2 && (p.sellerName || "").toLowerCase().indexOf(sellersSearch) !== -1; });
    }) : sellerIds;
    for (var si = 0; si < sellerIdsToShow.length; si++) {
      var sid = sellerIdsToShow[si];
      var sellerName = "";
      var sellerProductIds = [];
      for (var sp = 0; sp < state.products.length; sp++) {
        if (state.products[sp].sellerId === sid) { sellerName = state.products[sp].sellerName; sellerProductIds.push(state.products[sp].id); }
      }
      var viewCount = 0;
      for (var va = 0; va < state.accounts.length; va++) {
        var vviews = (state.accounts[va].behavior && state.accounts[va].behavior.views) || [];
        for (var vv = 0; vv < vviews.length; vv++) {
          var vid = typeof vviews[vv] === "string" ? vviews[vv] : vviews[vv].productId;
          if (sellerProductIds.indexOf(vid) !== -1) viewCount++;
        }
      }
      var salesCount = 0;
      for (var sc2 = 0; sc2 < sellerProductIds.length; sc2++) salesCount += getProductSalesCount(sellerProductIds[sc2]);
      var conversion = viewCount > 0 ? ((salesCount / viewCount) * 100).toFixed(1) + '%' : '—';
      var activeBoosts = state.boosts.filter(function(b) { return b.sellerId === sid && isBoostActive(b); }).length;
      html += '<tr><td>' + esc(sellerName) + '</td><td>' + sellerProductIds.length + '</td><td>' + viewCount + '</td><td>' + salesCount + '</td><td>' + conversion + '</td><td>' + activeBoosts + '</td></tr>';
    }
    html += '</table>';
    }
    html += '</div>';
  }
  return html;
}

// ---------- ADMIN : COMPTES (liste + détail) ----------
var ROLE_ACCOUNT_LABELS = { acheteur: "Acheteur", vendeur: "Vendeur", point_vente: "Point de Retrait", livreur: "Livreur", agent_sourcing: "Agent Sourcing", admin: "Admin" };

// ---------- ADMIN : LITIGES ----------
function renderAdminDisputes() {
  var disputes = state.disputes.filter(inAdminScope).sort(function(a, b) { return b.createdAt - a.createdAt; });
  if (disputes.length === 0) {
    return '<div class="empty-state"><i class="fa-solid fa-flag"></i><div class="title">' + t("ad_no_dispute") + '</div></div>';
  }
  var disputesSearch = (state.adminDisputesSearch || "").toLowerCase().trim();
  if (disputesSearch) {
    disputes = disputes.filter(function(d) {
      return d.orderId.slice(-5).toLowerCase().indexOf(disputesSearch) !== -1 ||
        (d.buyerName || "").toLowerCase().indexOf(disputesSearch) !== -1 ||
        (DISPUTE_REASONS[d.reason] || d.reason || "").toLowerCase().indexOf(disputesSearch) !== -1 ||
        (d.status || "").toLowerCase().indexOf(disputesSearch) !== -1;
    });
  }
  var disputesCollapsed = !!state.collapsedAdminSections.disputesList;
  var html = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;">';
  html += '<input class="input" placeholder="' + t("ad_search_disputes") + '" value="' + esc(state.adminDisputesSearch || "") + '" data-action-input="admin-disputes-search" style="flex:1;" />';
  html += '<button class="link-btn" style="flex:0;padding:8px;" data-action="toggle-admin-section" data-value="disputesList"><i class="fa-solid ' + (disputesCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button>';
  html += '</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">' + disputes.length + t("ad_disputes_count") + '</div>';
  if (disputesCollapsed) return html;
  for (var i = 0; i < disputes.length; i++) {
    var d = disputes[i];
    var order = null;
    for (var j = 0; j < state.orders.length; j++) { if (state.orders[j].id === d.orderId) { order = state.orders[j]; break; } }
    html += '<div class="card-row" style="flex-direction:column;align-items:stretch;cursor:pointer;" data-action="open-admin-order" data-value="' + d.orderId + '">';
    html += '<div style="display:flex;justify-content:space-between;font-size:12.5px;margin-bottom:6px;">';
    html += '<span style="font-weight:700;">#' + d.orderId.slice(-5).toUpperCase() + '</span>';
    html += '<span class="status-pill" style="' + (d.status === "En litige" ? 'background:rgba(255,85,102,0.15);color:var(--danger);' : '') + '">' + translateStatus(d.status) + '</span>';
    html += '</div>';
    html += '<div style="font-size:12.5px;"><strong>' + esc(DISPUTE_REASONS[d.reason] || d.reason) + '</strong>' + (d.autoGenerated ? ' <span style="font-size:10px;color:var(--text-dim);">' + t("ad_auto_generated") + '</span>' : '') + '</div>';
    if (d.description) {
      html += '<div style="font-size:11.5px;color:var(--text-dim);margin-top:2px;font-style:italic;">"' + esc(d.description) + '"</div>';
    } else {
      html += '<button class="link-btn" style="font-size:11px;margin-top:2px;" data-action="open-reveal-dispute-detail" data-value="' + d.id + '"><i class="fa-solid fa-lock"></i> ' + (state.adminIsOwner ? 'Voir la description (mot de passe requis)' : 'Voir la description (confirmation requise)') + '</button>';
    }
    html += '<div style="font-size:11px;color:var(--text-dim);margin-top:4px;">' + esc(d.buyerName) + ' · ' + fmtDateTime(d.createdAt) + (order ? ' · ' + orderMoney(order.total, order) : '') + '</div>';
    html += '<div class="status-actions" style="margin-top:8px;">';
    for (var s = 0; s < DISPUTE_STATUS_FLOW.length; s++) {
      var st = DISPUTE_STATUS_FLOW[s];
      html += '<button class="' + (d.status === st ? 'active' : '') + '" data-action="set-dispute-status" data-order="' + d.id + '" data-value="' + st + '">' + translateStatus(st) + '</button>';
    }
    html += '</div></div>';
  }
  return html;
}

function renderAdminAccounts() {
  if (state.adminAccountDetailId) return renderAdminAccountDetail(state.adminAccountDetailId);

  var html = '';
  var mode = state.adminAccountsMode === "wallets" ? "wallets" : "accounts";
  html += '<div class="mc-filter-row">';
  html += '<div class="mc-filter-chip' + (mode === "accounts" ? ' active' : '') + '" data-action="set-admin-accounts-mode" data-value="accounts"><i class="fa-solid fa-users"></i> ' + t("ad_accounts_tab") + '</div>';
  html += '<div class="mc-filter-chip' + (mode === "wallets" ? ' active' : '') + '" data-action="set-admin-accounts-mode" data-value="wallets"><i class="fa-solid fa-wallet"></i> ' + t("ad_wallets_tab") + '</div>';
  html += '</div>';

  if (mode === "wallets") return html + renderAdminWallets();

  if (state.adminIsOwner) {
    var empPerms = getEmployeePermissions();
    html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
    html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-user-tie"></i> ' + t("ad_employee_powers") + '</div>';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;">';
    html += '<div style="font-size:12.5px;">' + t("ad_can_approve") + '<br><span style="font-size:10px;color:var(--text-dim);">' + t("ad_can_approve_hint") + '</span></div>';
    html += '<div class="toggle-switch ' + (empPerms.canApprove ? 'active' : '') + '" data-action="toggle-employee-permission" data-value="canApprove"><div class="toggle-knob"></div></div>';
    html += '</div>';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;">';
    html += '<div style="font-size:12.5px;">' + t("ad_can_reply") + '</div>';
    html += '<div class="toggle-switch ' + (empPerms.canReply ? 'active' : '') + '" data-action="toggle-employee-permission" data-value="canReply"><div class="toggle-knob"></div></div>';
    html += '</div>';
    html += '<div style="font-size:10px;color:var(--text-dim);margin-top:8px;">' + t("ad_reserved_note") + '</div>';
    html += '</div>';
  }

  var search = (state.adminAccountSearch || "").toLowerCase().trim();
  var accounts = state.accounts.filter(function(a) {
    if (!inAdminScope(a)) return false;
    if (!search) return true;
    return (a.name || "").toLowerCase().indexOf(search) !== -1 || (a.phone || "").indexOf(search) !== -1 || (a.email || "").toLowerCase().indexOf(search) !== -1;
  });
  accounts.sort(function(a, b) { return (b.createdAt || 0) - (a.createdAt || 0); });

  html += '<div style="display:flex;gap:8px;margin-bottom:14px;">';
  html += '<div class="gems-search" style="flex:1;margin-bottom:0;"><i class="fa-solid fa-magnifying-glass"></i>';
  html += '<input id="admin-account-search-input" placeholder="' + t("ad_search_account") + '" value="' + esc(state.adminAccountSearch || '') + '" data-bind="adminAccountSearch" data-enter-action="submit-admin-account-search" /></div>';
  html += '<button class="btn-primary" style="flex:0;padding:0 16px;" data-action="submit-admin-account-search"><i class="fa-solid fa-magnifying-glass"></i></button>';
  html += '</div>';

  html += renderAdminCollapsibleList("adminAccountsList", '<i class="fa-solid fa-users"></i> ' + t("ad_accounts_tab"), accounts, function(a) {
    var accConv = null;
    for (var ac = 0; ac < state.adminConversations.length; ac++) { if (state.adminConversations[ac].accountId === a.id) { accConv = state.adminConversations[ac]; break; } }
    var rowHtml = '<div class="card-row" style="cursor:pointer;" data-action="open-admin-account-detail" data-value="' + a.id + '">';
    rowHtml += '<div class="emoji-thumb"><i class="fa-solid ' + (ROLE_ICONS[a.role] || 'fa-user') + '"></i></div>';
    rowHtml += '<div style="flex:1;min-width:0;">';
    rowHtml += '<div style="font-weight:700;font-size:13px;">' + esc(a.name) + (a.banned ? ' <span style="color:var(--danger);font-size:10px;">' + t("ad_banned") + '</span>' : '') + '</div>';
    rowHtml += '<div style="font-size:11px;color:var(--text-dim);">' + esc(a.phone) + ' · ' + translateRoleLabel(a.role) + '</div>';
    rowHtml += '</div>';
    if (a.hasRefusalAlert) {
      rowHtml += '<span title="' + t("ad_refusal_alert_title") + '" style="background:rgba(255,166,0,0.15);color:#c77700;font-size:10px;padding:1px 8px;border-radius:999px;margin-right:6px;"><i class="fa-solid fa-triangle-exclamation"></i> ' + a.livreurRefusalCount + '</span>';
    }
    if (accConv && (accConv.unreadForAdmin || 0) > 0) {
      rowHtml += '<span style="background:var(--danger);color:white;font-size:10px;padding:1px 8px;border-radius:999px;margin-right:6px;">' + accConv.unreadForAdmin + '</span>';
    }
    rowHtml += '<i class="fa-solid fa-chevron-right" style="color:var(--text-dim);"></i>';
    rowHtml += '</div>';
    return rowHtml;
  }, { emptyText: t("ad_no_account_found") });

  return html;
}

function adminDetailSectionKey(accountId, section) { return accountId + "::" + section; }

// ---------- FILTRE PAR PÉRIODE — activité d'un compte (livreur, Point de
// Retrait...) — réutilisable partout où on affiche une liste datée,
// disponible à l'identique en Groupe 1 et Groupe 2 (lecture seule pour
// eux, mais le filtre lui-même n'est pas une modification de donnée).
function adminActivityDateActive() {
  return !!(state.adminActivityFrom || state.adminActivityTo);
}

function filterByAdminActivityDate(items, dateField) {
  if (!adminActivityDateActive()) return items;
  var fromTs = state.adminActivityFrom ? new Date(state.adminActivityFrom + "T00:00:00").getTime() : null;
  var toTs = state.adminActivityTo ? new Date(state.adminActivityTo + "T23:59:59").getTime() : null;
  return items.filter(function(it) {
    var ts = it[dateField];
    if (ts == null) return false;
    if (fromTs != null && ts < fromTs) return false;
    if (toTs != null && ts > toTs) return false;
    return true;
  });
}

function renderAdminActivityDateFilter() {
  var html = '<div style="display:flex;gap:8px;align-items:flex-end;margin:14px 0 4px;flex-wrap:wrap;">';
  html += '<div style="flex:1;min-width:120px;"><label class="field-label" style="margin-top:0;font-size:10px;">' + t("ad_date_from") + '</label><input class="input" type="date" value="' + esc(state.adminActivityFrom || '') + '" data-action-input="admin-activity-from" /></div>';
  html += '<div style="flex:1;min-width:120px;"><label class="field-label" style="margin-top:0;font-size:10px;">' + t("ad_date_to") + '</label><input class="input" type="date" value="' + esc(state.adminActivityTo || '') + '" data-action-input="admin-activity-to" /></div>';
  if (adminActivityDateActive()) {
    html += '<button class="link-btn" style="flex:0;padding-bottom:10px;" data-action="reset-admin-activity-date"><i class="fa-solid fa-xmark"></i> ' + t("ad_reset") + '</button>';
  }
  html += '</div>';
  return html;
}

// ---------- VUE FOCALISÉE : activité d'une boutique Point de Retrait
// UNIQUEMENT (pas la fiche générale de la personne — pas ses achats
// éventuels, pas ses messages produit, rien d'autre que son activité en
// tant que Point de Retrait). ----------
function renderAdminRelaisShopDetail(accountId) {
  var a = null;
  for (var i = 0; i < state.accounts.length; i++) { if (state.accounts[i].id === accountId) { a = state.accounts[i]; break; } }
  if (!a) return '<div class="empty-state"><i class="fa-solid fa-shop-slash"></i><div class="title">Boutique introuvable</div></div>';

  var html = '<button class="link-btn" style="margin-bottom:14px;" data-action="close-admin-account-detail"><i class="fa-solid fa-arrow-left"></i> Retour à la liste</button>';

  html += '<div class="glass-card" style="padding:16px;margin-bottom:16px;">';
  html += '<div style="display:flex;align-items:center;gap:12px;">';
  html += '<div class="emoji-thumb" style="width:48px;height:48px;font-size:20px;"><i class="fa-solid fa-shop"></i></div>';
  html += '<div><div style="font-weight:800;font-size:16px;">' + esc(a.shopName || a.name) + '</div><div style="font-size:12px;color:var(--text-dim);">' + esc(a.phone || '—') + (a.commune ? ' · ' + esc(a.commune) : '') + (a.quartier ? ', ' + esc(a.quartier) : '') + '</div></div>';
  html += '</div>';
  html += '<button class="link-btn" style="margin-top:10px;font-size:11px;" data-action="open-admin-account-detail" data-value="' + a.id + '"><i class="fa-solid fa-user"></i> Voir le compte complet de cette personne</button>';
  html += '</div>';

  var relaisOrders = state.orders.filter(function(o) { return o.deliveryMode === "relais" && o.relaisShopId === a.id; });
  html += renderRelaisEarningsSection(relaisOrders);

  html += renderAdminActivityDateFilter();
  var relaisOrdersFiltered = filterByAdminActivityDate(relaisOrders, 'createdAt');
  html += '<div style="font-weight:800;font-size:13.5px;margin:16px 0 8px;"><i class="fa-solid fa-clock-rotate-left"></i> Toutes les commandes (activité)' + (adminActivityDateActive() ? ' — période filtrée' : '') + '</div>';
  if (relaisOrdersFiltered.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucune activité' + (adminActivityDateActive() ? ' sur cette période' : ' pour l\'instant') + '.</div>';
  } else {
    var relaisOrdersSorted = relaisOrdersFiltered.slice().sort(function(x, y) { return y.createdAt - x.createdAt; });
    var relaisShown = adminActivityDateActive() ? relaisOrdersSorted : relaisOrdersSorted.slice(0, 30);
    for (var rs = 0; rs < relaisShown.length; rs++) {
      var ro3 = relaisShown[rs];
      html += '<div class="card-row" style="cursor:pointer;" data-action="open-admin-order" data-value="' + ro3.id + '"><div style="flex:1;"><div style="font-weight:700;font-size:12px;">#' + ro3.id.slice(-5).toUpperCase() + ' — ' + esc(ro3.status) + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + fmtDateTime(ro3.createdAt) + '</div></div><div style="font-weight:700;font-size:12px;">' + orderMoney(ro3.total, ro3) + '</div></div>';
    }
    if (!adminActivityDateActive() && relaisOrdersSorted.length > 30) {
      html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:6px;">+ ' + (relaisOrdersSorted.length - 30) + ' commande(s) plus ancienne(s) — utilisez le filtre par période ci-dessus pour tout voir.</div>';
    }
  }
  return html;
}

// ---------- VUE FOCALISÉE : activité d'un livreur UNIQUEMENT (pas la
// fiche générale de la personne). ----------
function renderAdminLivreurDetail(accountId) {
  var a = null;
  for (var i = 0; i < state.accounts.length; i++) { if (state.accounts[i].id === accountId) { a = state.accounts[i]; break; } }
  if (!a) return '<div class="empty-state"><i class="fa-solid fa-truck-fast"></i><div class="title">Livreur introuvable</div></div>';

  var html = '<button class="link-btn" style="margin-bottom:14px;" data-action="close-admin-account-detail"><i class="fa-solid fa-arrow-left"></i> Retour à la liste</button>';

  html += '<div class="glass-card" style="padding:16px;margin-bottom:16px;">';
  html += '<div style="display:flex;align-items:center;gap:12px;">';
  html += '<div class="emoji-thumb" style="width:48px;height:48px;font-size:20px;"><i class="fa-solid fa-truck-fast"></i></div>';
  html += '<div><div style="font-weight:800;font-size:16px;">' + esc(a.name) + (a.banned ? ' 🚫' : '') + '</div><div style="font-size:12px;color:var(--text-dim);">' + esc(a.phone || '—') + '</div></div>';
  html += '</div>';
  html += '<button class="link-btn" style="margin-top:10px;font-size:11px;" data-action="open-admin-account-detail" data-value="' + a.id + '"><i class="fa-solid fa-user"></i> Voir le compte complet de cette personne</button>';
  html += '</div>';

  var livOrdersAll = state.orders.filter(function(o) { return o.livreurId === a.id && o.status === "Livrée"; });
  var livParcelsAll = state.externalParcels.filter(function(p) { return p.livreurId === a.id && p.status === "Livré"; });
  var livTotalEarnings = livOrdersAll.reduce(function(s, o) { return s + (o.deliveryFee || 0); }, 0) + livParcelsAll.reduce(function(s, p) { return s + (p.deliveryFee || 0); }, 0);

  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:6px;"><i class="fa-solid fa-chart-simple"></i> Résumé</div>';
  html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:4px 0;"><span>Livraisons effectuées (total)</span><span style="font-weight:700;">' + (livOrdersAll.length + livParcelsAll.length) + '</span></div>';
  html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:4px 0;color:var(--accent);"><span>Gains cumulés (total)</span><span style="font-weight:800;">' + money(livTotalEarnings) + '</span></div>';
  html += '</div>';

  html += renderAdminActivityDateFilter();
  var livOrdersFiltered = filterByAdminActivityDate(livOrdersAll, 'createdAt');
  var livParcelsFiltered = filterByAdminActivityDate(livParcelsAll, 'createdAt');
  var livCombined = livOrdersFiltered.map(function(o) { return { type: 'order', id: o.id, at: o.createdAt, amount: o.deliveryFee || 0, label: '#' + o.id.slice(-5).toUpperCase(), country: o.country }; })
    .concat(livParcelsFiltered.map(function(p) { return { type: 'parcel', id: p.id, at: p.createdAt, amount: p.deliveryFee || 0, label: esc(p.trackingNumber || 'Colis externe'), country: null }; }))
    .sort(function(x, y) { return y.at - x.at; });

  html += '<div style="font-weight:800;font-size:13.5px;margin:16px 0 8px;"><i class="fa-solid fa-clock-rotate-left"></i> Détail des livraisons' + (adminActivityDateActive() ? ' — période filtrée' : '') + '</div>';
  if (livCombined.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucune livraison' + (adminActivityDateActive() ? ' sur cette période' : ' pour l\'instant') + '.</div>';
  } else {
    var livShown = adminActivityDateActive() ? livCombined : livCombined.slice(0, 30);
    for (var lc = 0; lc < livShown.length; lc++) {
      var lci = livShown[lc];
      var clickAttr = lci.type === 'order' ? ' style="cursor:pointer;" data-action="open-admin-order" data-value="' + lci.id + '"' : '';
      html += '<div class="card-row"' + clickAttr + '><div style="flex:1;"><div style="font-weight:700;font-size:12px;">' + (lci.type === 'order' ? lci.label : '📦 ' + lci.label) + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + fmtDateTime(lci.at) + '</div></div><div style="font-weight:700;font-size:12px;color:var(--accent);">' + money(lci.amount, lci.country) + '</div></div>';
    }
    if (!adminActivityDateActive() && livCombined.length > 30) {
      html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:6px;">+ ' + (livCombined.length - 30) + ' livraison(s) plus ancienne(s) — utilisez le filtre par période ci-dessus pour tout voir.</div>';
    }
  }
  return html;
}

function renderAdminDetailSection(title, iconClass, accountId, sectionKey, items, renderItemFn, emptyText) {
  var html = '<div style="font-weight:800;font-size:13.5px;margin:18px 0 8px;"><i class="fa-solid ' + iconClass + '"></i> ' + esc(title) + ' (' + items.length + ')</div>';
  if (items.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);">' + emptyText + '</div>';
    return html;
  }
  var expandKey = adminDetailSectionKey(accountId, sectionKey);
  var expanded = !!state.adminDetailExpanded[expandKey];
  var toShow = expanded ? items : items.slice(0, 5);
  for (var i = 0; i < toShow.length; i++) {
    html += renderItemFn(toShow[i]);
  }
  if (items.length > 5) {
    html += '<button class="link-btn" data-action="toggle-admin-detail-section" data-value="' + expandKey + '">' + (expanded ? 'Réduire' : 'Voir plus (' + (items.length - 5) + ')') + '</button>';
  }
  return html;
}

// Historique horodaté d'une commande — chaque étape avec son heure exacte,
// visible par tous les concernés (acheteur, vendeur, livreur, admin), pas
// seulement l'Admin comme avant.
function renderOrderStatusHistory(order) {
  if (!Array.isArray(order.statusHistory) || order.statusHistory.length === 0) return '';
  var html = '<div style="background:var(--bg-body);border-radius:10px;padding:10px;margin:8px 0;">';
  html += '<div style="font-size:11px;font-weight:800;color:var(--text-dim);margin-bottom:6px;"><i class="fa-solid fa-clock-rotate-left"></i> ' + t("order_full_history") + '</div>';
  for (var hi = 0; hi < order.statusHistory.length; hi++) {
    var hstep = order.statusHistory[hi];
    html += '<div style="display:flex;justify-content:space-between;font-size:11.5px;padding:3px 0;' + (hi > 0 ? 'border-top:1px dashed var(--border-color);' : '') + '">';
    html += '<span style="font-weight:700;">' + esc(orderStatusLabel(hstep.status)) + (hstep.note ? ' <span style="font-weight:400;color:var(--text-dim);">— ' + esc(hstep.note) + '</span>' : '') + '</span>';
    html += '<span style="color:var(--text-dim);white-space:nowrap;margin-left:8px;">' + fmtDateTime(hstep.at) + '</span>';
    html += '</div>';
  }
  html += '</div>';
  return html;
}

// Date relative pour la publication d'un article — jamais une date fixe ni
// un nom de jour, juste "il y a X" en unités de plus en plus grandes, pour
// rester court et lisible.
function relativeTimeAgo(ts) {
  if (!ts) return '';
  var diffDays = Math.floor((Date.now() - ts) / (24 * 60 * 60 * 1000));
  if (diffDays <= 0) return t("rt_today");
  if (diffDays === 1) return t("rt_yesterday");
  if (diffDays < 7) return t("rt_days_ago").replace("{n}", diffDays);
  var weeks = Math.floor(diffDays / 7);
  if (weeks < 4) return (weeks > 1 ? t("rt_weeks_ago") : t("rt_week_ago")).replace("{n}", weeks);
  var months = Math.floor(diffDays / 30);
  if (months < 12) return t("rt_month_ago").replace("{n}", months);
  var years = Math.floor(diffDays / 365);
  return (years > 1 ? t("rt_years_ago") : t("rt_year_ago")).replace("{n}", years);
}

// Traduit un nom de couleur pour l'affichage — la valeur interne (stockée
// sur le produit, comparée dans le code) ne change jamais, seul le texte
// montré à l'utilisateur change de langue. Même principe que translateStatus.
function repLabelText(label) {
  var map = { "Nouveau vendeur": "rep_new", "Excellent": "rep_excellent", "Fiable": "rep_reliable", "Correct": "rep_correct", "À surveiller": "rep_watch" };
  return map[label] ? t(map[label]) : label;
}
function translateColorName(name) {
  var key = "color_" + name;
  return t(key) !== key ? t(key) : name;
}

function fmtDateTime(ts) {
  if (!ts) return '—';
  var d = new Date(ts);
  return d.toLocaleDateString('fr-FR') + ' ' + t("at_word") + ' ' + d.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
}

function renderAdminAccountDetail(accountId) {
  var a = null;
  for (var i = 0; i < state.accounts.length; i++) { if (state.accounts[i].id === accountId) { a = state.accounts[i]; break; } }
  if (!a) return '<div class="empty-state"><i class="fa-solid fa-user-slash"></i><div class="title">Compte introuvable</div></div>';

  var html = '<button class="link-btn" style="margin-bottom:14px;" data-action="close-admin-account-detail"><i class="fa-solid fa-arrow-left"></i> Retour à la liste</button>';
  if (state.adminLinkedFromConv) {
    html += '<button class="link-btn" style="margin-bottom:14px;margin-left:14px;" data-action="back-to-linked-message"><i class="fa-solid fa-comment"></i> Retour au message</button>';
  }
  if (currentAdminHasFilatureAccess() && a.phone) {
    html += '<button class="link-btn" style="margin-bottom:14px;margin-left:14px;color:var(--text-dim);font-size:11px;" data-action="open-account-filature" data-value="' + esc(a.phone) + '"><i class="fa-solid fa-user-secret"></i> Filature</button>';
  }

  // ---- Fiche d'identité ----
  html += '<div class="glass-card" style="padding:16px;">';
  html += '<div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">';
  html += '<div class="emoji-thumb" style="width:48px;height:48px;font-size:20px;"><i class="fa-solid ' + (ROLE_ICONS[a.role] || 'fa-user') + '"></i></div>';
  html += '<div><div style="font-weight:800;font-size:16px;">' + esc(a.name) + '</div><div style="font-size:12px;color:var(--text-dim);">' + translateRoleLabel(a.role) + '</div></div>';
  html += '</div>';
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;font-size:12.5px;">';
  html += '<div><span style="color:var(--text-dim);">Téléphone</span><br><strong>' + esc(a.phone || '—') + '</strong></div>';
  html += '<div><span style="color:var(--text-dim);">Email</span><br><strong>' + esc(a.email || '—') + '</strong></div>';
  html += '<div><span style="color:var(--text-dim);">Compte créé le</span><br><strong>' + fmtDateTime(a.createdAt) + '</strong></div>';
  var revealedLogins = (state.adminRevealedLogins && state.adminRevealedLogins.accountId === accountId) ? state.adminRevealedLogins.dates : null;
  html += '<div><span style="color:var(--text-dim);">Dernière connexion</span><br><strong>' + (revealedLogins ? fmtDateTime(revealedLogins.length ? revealedLogins[revealedLogins.length - 1] : null) : '—') + '</strong>' + (!revealedLogins ? ' <button class="link-btn" style="font-size:10.5px;" data-action="open-reveal-login-history" data-value="' + accountId + '"><i class="fa-solid fa-lock"></i> ' + (state.adminIsOwner ? 'Voir' : 'Voir (confirmation)') + '</button>' : '') + '</div>';
  if ((a.unclaimedParcelCount || 0) > 0) {
    var uc = a.unclaimedParcelCount;
    html += '<div style="grid-column:1/-1;margin-top:2px;padding:8px 10px;border-radius:10px;font-size:12px;font-weight:700;background:' + (uc >= 2 ? 'rgba(255,85,102,0.12);color:var(--danger)' : 'rgba(255,193,7,0.12);color:#a15c00') + ';"><i class="fa-solid fa-triangle-exclamation"></i> ' + uc + ' colis jamais récupéré' + (uc > 1 ? 's' : '') + ' au point de retrait' + (uc >= 2 ? ' — comportement répété, à surveiller' : '') + '</div>';
  }
  if (a.role === "vendeur") {
    var typeInfo = SELLER_TYPES[a.sellerType] || SELLER_TYPES.particulier;
    var repDetail = computeSellerReputation(a.id);
    html += '<div><span style="color:var(--text-dim);">Type de vendeur</span><br><strong>' + esc(typeInfo.label) + (a.sellerSector && SECTOR_TYPES[a.sellerSector] ? ' · ' + esc(translateSectorLabel(a.sellerSector)) : '') + '</strong></div>';
    html += '<div><span style="color:var(--text-dim);">Téléphone pro</span><br><strong>' + esc(a.shopPhone || '—') + '</strong></div>';
    html += '<div style="grid-column:1/3;"><span style="color:var(--text-dim);">Adresse</span><br><strong>' + esc(a.shopAddress || '—') + '</strong></div>';
    html += '<div style="grid-column:1/3;"><span style="color:var(--text-dim);">Position GPS de la boutique</span><br><strong>' + (a.shopLat != null && a.shopLng != null ? a.shopLat.toFixed(5) + ', ' + a.shopLng.toFixed(5) + ' · <a href="https://www.google.com/maps?q=' + a.shopLat + ',' + a.shopLng + '" target="_blank" style="color:var(--accent);">📍 Voir sur la carte</a>' : '— (pas encore renseignée)') + '</strong></div>';
    html += '<div style="grid-column:1/3;"><span style="color:var(--text-dim);">Réputation</span><br><strong>' + (repDetail.totalOrders >= 3 ? repDetail.stars.toFixed(1) + '/5 — ' + repDetail.label + ' (' + repDetail.deliveredOrders + '/' + repDetail.totalOrders + ' commandes réussies)' : 'Pas encore assez de commandes') + '</strong></div>';
  }
  if (a.relaisApplicationStatus === "approved") {
    html += '<div style="grid-column:1/3;"><span style="color:var(--text-dim);">Commune / Quartier</span><br><strong>' + esc(a.commune || '—') + ' / ' + esc(a.quartier || '—') + '</strong></div>';
    if (a.addressDetail) html += '<div style="grid-column:1/3;"><span style="color:var(--text-dim);">Précision</span><br><strong>' + esc(a.addressDetail) + '</strong></div>';
    html += '<div style="grid-column:1/3;"><span style="color:var(--text-dim);">Position GPS</span><br><strong>' + (a.shopLat != null ? a.shopLat.toFixed(5) + ', ' + a.shopLng.toFixed(5) : '—') + '</strong></div>';
  }
  html += '</div>';

  // ---- Mode Test à distance — visible uniquement dans SON profil une fois activé ----
  html += '<div class="glass-card" style="padding:14px;margin-top:10px;background:' + (a.testModeEnabled ? 'rgba(46,158,79,0.08)' : 'transparent') + ';">';
  html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:6px;"><i class="fa-solid fa-flask"></i> Mode Test à distance</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:10px;">Une fois activé, un onglet "Test" apparaît dans le profil de cette personne — elle peut voir l\'état complet de son app et te l\'envoyer en un clic, sans que tu aies besoin de deviner ce qu\'elle voit.</div>';
  if (a.testModeEnabled) {
    html += '<div style="font-size:12px;color:var(--success);margin-bottom:8px;"><i class="fa-solid fa-circle-check"></i> Activé — visible dans son profil actuellement.</div>';
    html += '<button class="btn-secondary" style="width:100%;" data-action="toggle-user-test-mode" data-value="' + a.id + '">Désactiver le mode Test</button>';
  } else {
    html += '<button class="btn-primary" style="width:100%;" data-action="toggle-user-test-mode" data-value="' + a.id + '">Activer le mode Test pour ce compte</button>';
  }
  html += '</div>';
  if (state.adminIsOwner && !state.adminCountryScope) {
    var accountSubs = (state.pushSubscriptions || []).filter(function(s) { return s.accountId === a.id; });
    html += '<div class="glass-card" style="padding:14px;margin-top:10px;">';
    html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:8px;"><i class="fa-solid fa-bell"></i> Notifications push</div>';
    if (accountSubs.length === 0) {
      html += '<div style="font-size:12px;color:var(--danger);">❌ Aucun abonnement enregistré — ce compte ne peut pas recevoir de vraie notification pour l\'instant (app fermée). Il doit ouvrir l\'app et activer les notifications dans Profil.</div>';
    } else {
      html += '<div style="font-size:12px;color:var(--accent);margin-bottom:8px;">✅ ' + accountSubs.length + ' appareil(s) abonné(s)</div>';
      for (var asi = 0; asi < accountSubs.length; asi++) {
        html += '<div style="font-size:10.5px;color:var(--text-dim);padding:3px 0;border-top:1px solid var(--border-color);">Abonné le ' + fmtDateTime(accountSubs[asi].createdAt) + '</div>';
        html += '<div style="font-size:9.5px;color:var(--text-faint);word-break:break-all;">Endpoint : ' + esc((accountSubs[asi].endpoint || '').slice(0, 60)) + '… · p256dh : ' + (accountSubs[asi].keys && accountSubs[asi].keys.p256dh ? accountSubs[asi].keys.p256dh.length + ' car.' : '❌ manquant') + ' · auth : ' + (accountSubs[asi].keys && accountSubs[asi].keys.auth ? accountSubs[asi].keys.auth.length + ' car.' : '❌ manquant') + '</div>';
      }
      html += '<button class="btn-secondary" style="width:100%;margin-top:10px;" data-action="send-test-push" data-value="' + a.id + '"><i class="fa-solid fa-paper-plane"></i> Envoyer une notification test</button>';
      html += '<button class="link-btn" style="width:100%;margin-top:8px;font-size:11px;" data-action="send-test-push-empty" data-value="' + a.id + '"><i class="fa-solid fa-vial"></i> Test diagnostic — envoi sans contenu</button>';
    }
    html += '</div>';

    // ---- Diagnostic Firebase natif (app Capacitor) — séparé du Web
    // Push ci-dessus, un compte peut avoir les deux à la fois. ----
    var accountFcm = (state.fcmTokens || []).filter(function(t) { return t.accountId === a.id; });
    html += '<div class="glass-card" style="padding:14px;margin-top:10px;">';
    html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:8px;"><i class="fa-solid fa-fire"></i> Notifications Firebase natif (app Capacitor)</div>';
    if (accountFcm.length === 0) {
      html += '<div style="font-size:12px;color:var(--danger);">❌ Aucun jeton Firebase enregistré — ce compte n\'utilise pas encore l\'app Capacitor, ou ne s\'y est pas encore abonné.</div>';
    } else {
      html += '<div style="font-size:12px;color:var(--accent);margin-bottom:8px;">✅ ' + accountFcm.length + ' appareil(s) abonné(s)</div>';
      for (var afi = 0; afi < accountFcm.length; afi++) {
        html += '<div style="font-size:10.5px;color:var(--text-dim);padding:3px 0;border-top:1px solid var(--border-color);">Abonné le ' + fmtDateTime(accountFcm[afi].createdAt) + ' · jeton : ' + esc((accountFcm[afi].token || '').slice(0, 30)) + '…</div>';
      }
      html += '<button class="btn-secondary" style="width:100%;margin-top:10px;" data-action="send-test-push-fcm" data-value="' + a.id + '"><i class="fa-solid fa-paper-plane"></i> Envoyer une notification test (Firebase)</button>';
    }
    html += '</div>';
  }
  // ---- Diagnostic COMPLET des notifications : un bouton, un rapport ----
  html += '<div class="glass-card" style="padding:14px;margin-top:10px;border:1.5px solid var(--accent);">';
  html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:6px;"><i class="fa-solid fa-stethoscope"></i> Diagnostic complet des notifications</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:10px;">Teste tout en une fois (jetons, abonnements, envois, et réglages du téléphone si lancé depuis l\'application). Lancez-le depuis l\'application installée sur le téléphone concerné, puis copiez le rapport.</div>';
  html += '<button class="btn-primary" style="width:100%;" data-action="run-full-push-diagnostic" data-value="' + a.id + '"><i class="fa-solid fa-play"></i> Lancer le diagnostic complet</button>';
  if (state.pushDiagReport && state.pushDiagReportFor === a.id) {
    html += '<div style="font-family:monospace;font-size:10.5px;white-space:pre-wrap;word-break:break-word;background:var(--bg-body);border-radius:8px;padding:10px;margin-top:10px;">' + esc(state.pushDiagReport) + '</div>';
    html += '<button class="btn-secondary" style="width:100%;margin-top:8px;" data-action="copy-push-diagnostic"><i class="fa-solid fa-copy"></i> Copier le rapport</button>';
  }
  html += '</div>';
  // ---- Sécurité (visible uniquement par l'administration) ----
  html += '<div class="glass-card" style="padding:14px;margin-top:10px;">';
  html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:8px;"><i class="fa-solid fa-shield-halved"></i> Sécurité (réservé à l\'administration)</div>';
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;font-size:12.5px;margin-bottom:12px;">';
  html += '<div><span style="color:var(--text-dim);">Date de naissance</span><br><strong>' + (a.birthDate ? esc(a.birthDate) : 'Protégée côté serveur (credentials)') + '</strong></div>';
  html += '<div><span style="color:var(--text-dim);">Mot de passe</span><br><strong>' + (a.hasPassword ? '🔒 Défini (protégé, jamais affiché)' : '— (pas encore défini)') + '</strong></div>';
  html += '<div style="grid-column:1/3;"><span style="color:var(--text-dim);">Code secret de récupération</span><br><strong>' + (a.hasRecoveryCode ? '🔒 Défini (protégé, jamais affiché)' : '— (pas encore généré)') + '</strong></div>';
  html += '</div>';
  html += '<label class="field-label" style="margin-top:0;">Définir un nouveau mot de passe pour ce compte</label>';
  html += '<div style="display:flex;gap:8px;">';
  html += '<input class="input" type="text" id="admin-new-password-input" placeholder="Nouveau mot de passe" style="flex:1;" />';
  html += '<button class="btn-primary" data-action="admin-set-new-password" data-value="' + a.id + '">Enregistrer</button>';
  html += '</div>';
  html += '</div>';

  // ---- Nommer / retirer le rôle Agent Sourcing — direct, sans mot de
  // passe à créer : la personne se connecte ensuite avec juste son nom
  // et son numéro, comme n'importe quel compte sans mot de passe défini.
  if (state.adminIsOwner) {
    html += '<div class="glass-card" style="padding:14px;margin-top:10px;">';
    html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:8px;"><i class="fa-solid fa-earth-asia"></i> Agent Sourcing</div>';
    if (a.isSourcingAgent) {
      html += '<div style="font-size:12px;color:var(--success);margin-bottom:10px;"><i class="fa-solid fa-circle-check"></i> Ce compte est Agent Sourcing (statut permanent, indépendant du rôle affiché en ce moment).</div>';
      html += '<button class="btn-secondary" style="color:var(--danger);border-color:var(--danger);" data-action="admin-remove-agent-role" data-value="' + a.id + '"><i class="fa-solid fa-xmark"></i> Retirer ce rôle</button>';
    } else {
      html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Fait de ce compte un Agent Sourcing — il pourra vérifier les paiements et suivre les commandes des vendeurs internationaux qui le choisissent à leur inscription.</div>';
      html += '<button class="btn-primary" data-action="admin-make-agent-sourcing" data-value="' + a.id + '"><i class="fa-solid fa-user-check"></i> Nommer Agent Sourcing</button>';
    }
    html += '</div>';
  }
  // ---- Adresses personnelles enregistrées par ce compte (en tant
  // qu'acheteur) — distinctes de l'adresse de la boutique ci-dessus,
  // visibles quel que soit le rôle du compte.
  if (Array.isArray(a.savedAddresses) && a.savedAddresses.length > 0) {
    html += '<div class="glass-card" style="padding:14px;margin-top:10px;">';
    html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:8px;"><i class="fa-solid fa-location-dot"></i> Adresses personnelles enregistrées (' + a.savedAddresses.length + ')</div>';
    for (var sai = 0; sai < a.savedAddresses.length; sai++) {
      var sAddr = a.savedAddresses[sai];
      html += '<div class="card-row" style="margin-bottom:6px;">';
      html += '<div style="flex:1;"><div style="font-weight:700;font-size:12px;">' + esc(sAddr.label || 'Adresse') + '</div>';
      html += '<div style="font-size:11px;color:var(--text-dim);">' + esc(sAddr.quartier || '—') + ' · ' + esc(sAddr.commune || '—') + (sAddr.repere ? ' — ' + esc(sAddr.repere) : '') + '</div>';
      if (sAddr.lat != null && sAddr.lng != null) {
        html += '<div style="font-size:10.5px;color:var(--text-dim);">📍 ' + sAddr.lat.toFixed(5) + ', ' + sAddr.lng.toFixed(5) + ' · <a href="https://www.google.com/maps?q=' + sAddr.lat + ',' + sAddr.lng + '" target="_blank" style="color:var(--accent);">Voir sur la carte</a></div>';
      }
      html += '</div></div>';
    }
    html += '</div>';
  } else {
    html += '<div class="glass-card" style="padding:14px;margin-top:10px;">';
    html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:4px;"><i class="fa-solid fa-location-dot"></i> Adresses personnelles enregistrées</div>';
    html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucune adresse enregistrée par ce compte pour l\'instant.</div>';
    html += '</div>';
  }
  if (a.relaisApplicationStatus === "approved") {
    var relaisOrders = state.orders.filter(function(o) { return o.deliveryMode === "relais" && o.relaisShopId === a.id; });

    html += renderRelaisEarningsSection(relaisOrders);

    html += renderAdminActivityDateFilter();
    var relaisOrdersFiltered = filterByAdminActivityDate(relaisOrders, 'createdAt');
    html += '<div style="font-weight:800;font-size:13.5px;margin:16px 0 8px;"><i class="fa-solid fa-clock-rotate-left"></i> Toutes les commandes (activité)' + (adminActivityDateActive() ? ' — période filtrée' : '') + '</div>';
    if (relaisOrdersFiltered.length === 0) {
      html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucune activité' + (adminActivityDateActive() ? ' sur cette période' : ' pour l\'instant') + '.</div>';
    } else {
      var relaisOrdersSorted = relaisOrdersFiltered.slice().sort(function(x, y) { return y.createdAt - x.createdAt; });
      var relaisShown = adminActivityDateActive() ? relaisOrdersSorted : relaisOrdersSorted.slice(0, 20);
      for (var rs = 0; rs < relaisShown.length; rs++) {
        var ro3 = relaisShown[rs];
        html += '<div class="card-row" style="cursor:pointer;" data-action="open-admin-order" data-value="' + ro3.id + '"><div style="flex:1;"><div style="font-weight:700;font-size:12px;">#' + ro3.id.slice(-5).toUpperCase() + ' — ' + esc(ro3.status) + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + fmtDateTime(ro3.createdAt) + '</div></div><div style="font-weight:700;font-size:12px;">' + orderMoney(ro3.total, ro3) + '</div></div>';
      }
      if (!adminActivityDateActive() && relaisOrdersSorted.length > 20) {
        html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:6px;">+ ' + (relaisOrdersSorted.length - 20) + ' commande(s) plus ancienne(s) — utilisez le filtre par période ci-dessus pour tout voir.</div>';
      }
    }
  }

  // ---- Livraisons effectuées (livreur) — même principe, avec filtre par
  // période, pour que l'admin (Groupe 1 ou Groupe 2) puisse vérifier
  // l'activité réelle d'un livreur sur une plage de dates précise. ----
  if (a.role === "livreur" || a.livreurApplicationStatus === "approved") {
    var livOrdersAll = state.orders.filter(function(o) { return o.livreurId === a.id && o.status === "Livrée"; });
    var livParcelsAll = state.externalParcels.filter(function(p) { return p.livreurId === a.id && p.status === "Livré"; });
    var livTotalEarnings = livOrdersAll.reduce(function(s, o) { return s + (o.deliveryFee || 0); }, 0) + livParcelsAll.reduce(function(s, p) { return s + (p.deliveryFee || 0); }, 0);

    html += '<div class="glass-card" style="padding:14px;margin-top:16px;">';
    html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:6px;"><i class="fa-solid fa-truck-fast"></i> Activité de livraison</div>';
    html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:4px 0;"><span>Livraisons effectuées (total)</span><span style="font-weight:700;">' + (livOrdersAll.length + livParcelsAll.length) + '</span></div>';
    html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:4px 0;color:var(--accent);"><span>Gains cumulés (total)</span><span style="font-weight:800;">' + money(livTotalEarnings) + '</span></div>';
    html += '</div>';

    html += renderAdminActivityDateFilter();
    var livOrdersFiltered = filterByAdminActivityDate(livOrdersAll, 'createdAt');
    var livParcelsFiltered = filterByAdminActivityDate(livParcelsAll, 'createdAt');
    var livCombined = livOrdersFiltered.map(function(o) { return { type: 'order', id: o.id, at: o.createdAt, amount: o.deliveryFee || 0, label: '#' + o.id.slice(-5).toUpperCase(), country: o.country }; })
      .concat(livParcelsFiltered.map(function(p) { return { type: 'parcel', id: p.id, at: p.createdAt, amount: p.deliveryFee || 0, label: esc(p.trackingNumber || 'Colis externe'), country: null }; }))
      .sort(function(x, y) { return y.at - x.at; });

    html += '<div style="font-weight:800;font-size:13.5px;margin:16px 0 8px;"><i class="fa-solid fa-clock-rotate-left"></i> Détail des livraisons' + (adminActivityDateActive() ? ' — période filtrée' : '') + '</div>';
    if (livCombined.length === 0) {
      html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucune livraison' + (adminActivityDateActive() ? ' sur cette période' : ' pour l\'instant') + '.</div>';
    } else {
      var livShown = adminActivityDateActive() ? livCombined : livCombined.slice(0, 20);
      for (var lc = 0; lc < livShown.length; lc++) {
        var lci = livShown[lc];
        var clickAttr = lci.type === 'order' ? ' style="cursor:pointer;" data-action="open-admin-order" data-value="' + lci.id + '"' : '';
        html += '<div class="card-row"' + clickAttr + '><div style="flex:1;"><div style="font-weight:700;font-size:12px;">' + (lci.type === 'order' ? lci.label : '📦 ' + lci.label) + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + fmtDateTime(lci.at) + '</div></div><div style="font-weight:700;font-size:12px;color:var(--accent);">' + money(lci.amount, lci.country) + '</div></div>';
      }
      if (!adminActivityDateActive() && livCombined.length > 20) {
        html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:6px;">+ ' + (livCombined.length - 20) + ' livraison(s) plus ancienne(s) — utilisez le filtre par période ci-dessus pour tout voir.</div>';
      }
    }
  }
  if (a.role === "vendeur") {
    html += '<button class="btn-secondary" style="margin-top:12px;' + (a.verified ? 'border-color:#2e9e4f;color:#2e9e4f;' : '') + '" data-action="toggle-account-verified" data-value="' + a.id + '"><i class="fa-solid fa-shield-check"></i> ' + (a.verified ? 'Boutique vérifiée ✓ (retirer)' : 'Marquer comme boutique vérifiée') + '</button>';
  }
  // ---- Comptes en double sur ce numéro (avant la protection anti-doublon
  // qui bloque désormais toute nouvelle création) — permet de fusionner
  // les vieux comptes fantômes dans le compte principal choisi par l'Admin,
  // sans perdre leurs produits/commandes/messages/avis au passage.
  var samePhoneAll = state.accounts.filter(function(sp) { return sp.phone === a.phone; });
  if (samePhoneAll.length > 1) {
    html += '<div class="glass-card" style="padding:12px;margin-top:10px;background:rgba(255,166,0,0.08);">';
    html += '<div style="font-size:12.5px;font-weight:700;color:#c77700;margin-bottom:6px;"><i class="fa-solid fa-triangle-exclamation"></i> ' + samePhoneAll.length + ' comptes trouvés pour ce même numéro (' + esc(a.phone) + ')</div>';
    html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:10px;">Probablement des doublons créés avant la protection actuelle. Choisissez le compte à garder comme principal — tout le reste (produits, commandes, messages, avis, favoris) sera transféré dedans, puis les autres comptes seront supprimés.</div>';
    for (var spi = 0; spi < samePhoneAll.length; spi++) {
      var spAcc = samePhoneAll[spi];
      var spCounts = getAccountDataCounts(spAcc.id);
      html += '<div class="card-row" style="margin-bottom:6px;">';
      html += '<div style="flex:1;"><div style="font-weight:700;font-size:12.5px;">' + esc(spAcc.shopName || spAcc.name) + (spAcc.id === a.id ? ' <span style="color:var(--accent);">(cette fiche)</span>' : '') + '</div>';
      html += '<div style="font-size:10.5px;color:var(--text-dim);">' + translateRoleLabel(spAcc.role) + ' · Créé le ' + fmtDateTime(spAcc.createdAt) + ' · ' + spCounts.products + ' produit(s), ' + spCounts.orders + ' commande(s), ' + spCounts.conversations + ' conversation(s)</div></div>';
      html += '<button class="btn-secondary" style="flex:0;font-size:11px;padding:6px 10px;" data-action="admin-merge-into-account" data-value="' + spAcc.id + '"><i class="fa-solid fa-code-merge"></i> Garder celui-ci</button>';
      html += '</div>';
    }
    html += '</div>';
  }
  if (a.hasRefusalAlert) {
    html += '<div class="glass-card" style="padding:12px;margin-top:10px;background:rgba(255,166,0,0.08);">';
    html += '<div style="font-size:12.5px;font-weight:700;color:#c77700;margin-bottom:4px;"><i class="fa-solid fa-triangle-exclamation"></i> Signalement : ' + (a.livreurRefusalCount || 0) + ' refus du livreur à la récupération</div>';
    html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:8px;">Le produit récupéré ne correspondait pas à l\'annonce, à plusieurs reprises.</div>';
    html += '<button class="link-btn" style="font-size:11px;" data-action="dismiss-refusal-alert" data-value="' + a.id + '">Marquer comme examiné</button>';
    html += '</div>';
  }
  html += '<button class="btn-secondary" style="margin-top:8px;' + (a.banned ? 'border-color:#2e9e4f;color:#2e9e4f;' : 'color:var(--danger);border-color:var(--danger);') + '" data-action="toggle-account-banned" data-value="' + a.id + '"><i class="fa-solid fa-ban"></i> ' + (a.banned ? 'Compte banni (réactiver)' : 'Bannir ce compte') + '</button>';
  html += '<button class="btn-secondary" style="margin-top:8px;color:var(--danger);border-color:var(--danger);" data-action="admin-delete-account" data-value="' + a.id + '"><i class="fa-solid fa-trash"></i> Supprimer ce compte</button>';
  html += '</div>';

  // ---- Connexions ----
  var logins = ((state.adminRevealedLogins && state.adminRevealedLogins.accountId === accountId) ? state.adminRevealedLogins.dates : []).slice().reverse();
  html += renderAdminDetailSection('Connexions', 'fa-right-to-bracket', accountId, 'logins', logins, function(ts) {
    return '<div class="card-row" style="padding:8px 12px;"><i class="fa-solid fa-right-to-bracket" style="color:var(--text-dim);margin-right:8px;"></i>' + fmtDateTime(ts) + '</div>';
  }, revealedLogins ? 'Aucune connexion enregistrée.' : 'Appuie sur "Voir" ci-dessus pour charger l\'historique.');

  // ---- Commandes passées (acheteur) ----
  var myOrders = state.orders.filter(function(o) { return o.buyerId === accountId; }).sort(function(x, y) { return y.createdAt - x.createdAt; });
  html += renderAdminDetailSection('Commandes passées', 'fa-receipt', accountId, 'orders', myOrders, function(o) {
    return '<div class="card-row" style="cursor:pointer;" data-action="open-admin-order" data-value="' + o.id + '"><div style="flex:1;"><div style="font-weight:700;font-size:12.5px;">#' + o.id.slice(-5).toUpperCase() + '</div><div style="font-size:11px;color:var(--text-dim);">' + fmtDateTime(o.createdAt) + ' · ' + o.status + '</div></div><div style="font-weight:700;font-size:12.5px;">' + (o.total != null ? orderMoney(o.total, o) : '—') + '</div></div>';
  }, 'Aucune commande.');

  // ---- Conversations (messages acheteur ↔ vendeur) — pouvoir admin étendu ----
  var myProductConvs = state.conversations.filter(function(c) { return c.buyerId === accountId || c.sellerId === accountId; }).sort(function(x, y) { return y.lastMessageTime - x.lastMessageTime; });
  html += renderAdminDetailSection('Messages (acheteur ↔ vendeur)', 'fa-comments', accountId, 'productconvs', myProductConvs, function(c) {
    var prod = null;
    for (var cp = 0; cp < state.products.length; cp++) { if (state.products[cp].id === c.productId) { prod = state.products[cp]; break; } }
    var otherRole = c.buyerId === accountId ? 'Vendeur' : 'Acheteur';
    return '<div class="card-row" style="cursor:pointer;" data-action="open-admin-conversation-view" data-value="' + c.id + '"><div style="flex:1;"><div style="font-weight:700;font-size:12.5px;">' + esc(prod ? prod.name : 'Produit supprimé') + '</div><div style="font-size:11px;color:var(--text-dim);">' + otherRole + ' · ' + esc(c.lastMessage || 'Aucun message') + '</div></div><i class="fa-solid fa-chevron-right" style="color:var(--text-dim);"></i></div>';
  }, 'Aucune conversation.');

  // ---- Produits publiés (vendeur) ----
  var myProducts = state.products.filter(function(p) { return p.sellerId === accountId; });
  html += renderAdminDetailSection('Produits publiés', 'fa-box', accountId, 'products', myProducts, function(p) {
    return '<div class="card-row"><div style="flex:1;"><div style="font-weight:700;font-size:12.5px;">' + esc(p.name) + '</div><div style="font-size:11px;color:var(--text-dim);">' + money(p.price) + (p.itemType === "service" ? ' · Service' : '') + '</div></div>' +
      '<button class="link-btn" data-action="admin-edit-product" data-value="' + p.id + '"><i class="fa-solid fa-pen"></i></button>' +
      '<button class="link-btn" style="color:var(--danger);" data-action="admin-delete-product" data-value="' + p.id + '"><i class="fa-solid fa-trash"></i></button></div>';
  }, 'Aucun produit publié.');

  // ---- Réservations ----
  var myBookings = state.bookings.filter(function(b) { return b.buyerId === accountId || b.sellerId === accountId; }).sort(function(x, y) { return y.createdAt - x.createdAt; });
  html += renderAdminDetailSection('Réservations', 'fa-calendar-check', accountId, 'bookings', myBookings, function(b) {
    return '<div class="card-row"><div style="flex:1;"><div style="font-weight:700;font-size:12.5px;">' + esc(b.productName) + '</div><div style="font-size:11px;color:var(--text-dim);">' + fmtDateTime(b.createdAt) + ' · ' + b.status + '</div></div></div>';
  }, 'Aucune réservation.');

  // ---- Avis laissés ----
  var myReviews = state.reviews.filter(function(r) { return r.userId === accountId; }).sort(function(x, y) { return y.createdAt - x.createdAt; });
  html += renderAdminDetailSection('Avis laissés', 'fa-star', accountId, 'reviews', myReviews, function(r) {
    return '<div class="card-row"><div style="flex:1;"><div style="font-weight:700;font-size:12.5px;">' + '⭐'.repeat(r.rating) + '</div><div style="font-size:11px;color:var(--text-dim);">' + fmtDateTime(r.createdAt) + '</div></div></div>';
  }, 'Aucun avis laissé.');

  // ---- Boosts achetés ----
  var myBoosts = state.boosts.filter(function(b) { return b.sellerId === accountId; }).sort(function(x, y) { return y.createdAt - x.createdAt; });
  html += renderAdminDetailSection('Boosts achetés', 'fa-rocket', accountId, 'boosts', myBoosts, function(b) {
    return '<div class="card-row"><div style="flex:1;"><div style="font-weight:700;font-size:12.5px;">' + boostTargetLabel(b) + '</div><div style="font-size:11px;color:var(--text-dim);">' + fmtDateTime(b.createdAt) + ' · ' + b.days + ' j · ' + money(b.price) + '</div></div></div>';
  }, 'Aucun boost acheté.');

  // ---- Produits consultés ----
  var views = ((a.behavior && a.behavior.views) || []).slice().reverse();
  html += renderAdminDetailSection('Produits consultés', 'fa-eye', accountId, 'views', views, function(v) {
    var vid = typeof v === "string" ? v : v.productId;
    var vat = typeof v === "string" ? null : v.viewedAt;
    var prod = null;
    for (var vp = 0; vp < state.products.length; vp++) { if (state.products[vp].id === vid) { prod = state.products[vp]; break; } }
    return '<div class="card-row"><div style="flex:1;"><div style="font-weight:700;font-size:12.5px;">' + esc(prod ? prod.name : 'Produit supprimé') + '</div><div style="font-size:11px;color:var(--text-dim);">' + fmtDateTime(vat) + '</div></div></div>';
  }, 'Aucun produit consulté.');

  // ---- Messagerie avec ce compte ----
  var accConvDetail = null;
  for (var acd = 0; acd < state.adminConversations.length; acd++) { if (state.adminConversations[acd].accountId === accountId) { accConvDetail = state.adminConversations[acd]; break; } }
  var msgs = accConvDetail ? accConvDetail.messages : [];
  html += '<div style="font-weight:800;font-size:13.5px;margin:18px 0 8px;"><i class="fa-solid fa-comments"></i> Messagerie (' + msgs.length + ')</div>';
  if (msgs.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:8px;">Aucun message échangé avec ce compte.</div>';
  } else {
    html += '<div style="max-height:220px;overflow-y:auto;background:var(--bg-body);border-radius:12px;padding:10px;margin-bottom:8px;">';
    var toShowMsgs = msgs.slice(-10);
    for (var mi = 0; mi < toShowMsgs.length; mi++) {
      var m2 = toShowMsgs[mi];
      var fromAdmin = m2.senderRole === "admin";
      html += '<div style="margin-bottom:8px;text-align:' + (fromAdmin ? 'right' : 'left') + ';">';
      html += '<div style="display:inline-block;max-width:80%;padding:6px 10px;border-radius:10px;font-size:12px;background:' + (fromAdmin ? 'var(--accent)' : 'var(--bg-card)') + ';color:' + (fromAdmin ? '#fff' : 'var(--text-primary)') + ';">' + esc(m2.message) + '</div>';
      html += '<div style="font-size:9.5px;color:var(--text-dim);margin-top:2px;">' + fmtDateTime(m2.createdAt) + '</div>';
      html += '</div>';
    }
    html += '</div>';
  }
  html += '<div style="display:flex;gap:8px;">';
  html += '<input class="input" id="admin-reply-input" placeholder="Écrire à ' + esc(a.name) + '…" />';
  html += '<button class="btn-primary" style="flex:0;width:auto;padding:0 16px;" data-action="send-admin-reply" data-value="' + accountId + '"><i class="fa-solid fa-paper-plane"></i></button>';
  html += '</div>';

  // ---- Adresses enregistrées ----
  html += '<div class="glass-card" style="padding:16px;margin-top:14px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-location-dot"></i> Adresses enregistrées</div>';
  var revealedAddr = (state.adminRevealedAddresses && state.adminRevealedAddresses.accountId === accountId) ? state.adminRevealedAddresses.addresses : null;
  if (!revealedAddr) {
    html += '<button class="link-btn" data-action="open-reveal-account-addresses" data-value="' + accountId + '"><i class="fa-solid fa-lock"></i> ' + (state.adminIsOwner ? 'Voir les adresses (mot de passe requis)' : 'Voir les adresses (confirmation requise)') + '</button>';
  } else if (revealedAddr.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim);">Aucune adresse enregistrée.</div>';
  } else {
    for (var addrI = 0; addrI < revealedAddr.length; addrI++) {
      var addrItem = revealedAddr[addrI];
      html += '<div class="card-row" style="margin-bottom:6px;">';
      html += '<div style="flex:1;"><div style="font-weight:700;font-size:12.5px;">' + esc(addrItem.label) + '</div><div style="font-size:11px;color:var(--text-dim);">' + esc(addrItem.commune) + ', ' + esc(addrItem.quartier) + (addrItem.repere ? ' — ' + esc(addrItem.repere) : '') + '</div></div>';
      if (state.adminIsOwner) {
        html += '<button class="link-btn" style="padding:4px;" data-action="admin-edit-address" data-value="' + accountId + '" data-addr="' + addrItem.id + '"><i class="fa-solid fa-pen"></i></button>';
        html += '<button class="link-btn" style="padding:4px;color:var(--danger);" data-action="admin-delete-address" data-value="' + accountId + '" data-addr="' + addrItem.id + '"><i class="fa-solid fa-trash"></i></button>';
      }
      html += '</div>';
    }
  }
  html += '</div>';

  // ---- Conversations acheteur-vendeur de ce compte ----
  html += '<div class="glass-card" style="padding:16px;margin-top:14px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-comments"></i> Conversations</div>';
  var accConvs = state.conversations.filter(function(c) { return c.buyerId === accountId || c.sellerId === accountId; });
  if (accConvs.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim);">Aucune conversation.</div>';
  } else {
    for (var cvI = 0; cvI < accConvs.length; cvI++) {
      var cv = accConvs[cvI];
      var revealedMsgs = (state.adminRevealedMessages && state.adminRevealedMessages.conversationId === cv.id) ? state.adminRevealedMessages.messages : null;
      html += '<div style="border-bottom:1px solid var(--border-color);padding:8px 0;">';
      html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:4px;">Conversation #' + cv.id.slice(-5).toUpperCase() + ' · ' + fmtDateTime(cv.lastMessageTime || cv.createdAt) + '</div>';
      if (!revealedMsgs) {
        html += '<button class="link-btn" data-action="open-reveal-conversation-messages" data-value="' + cv.id + '"><i class="fa-solid fa-lock"></i> ' + (state.adminIsOwner ? 'Voir les messages (mot de passe requis)' : 'Voir les messages (confirmation requise)') + '</button>';
      } else if (revealedMsgs.length === 0) {
        html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucun message.</div>';
      } else {
        for (var mI = 0; mI < revealedMsgs.length; mI++) {
          var rm = revealedMsgs[mI];
          html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;padding:4px 0;">';
          html += '<div style="font-size:12px;flex:1;"><strong>' + esc(rm.senderName || "") + '</strong> — ' + (rm.isVoice ? '🎤 Message vocal' : esc(rm.message)) + (rm.editedByAdmin ? ' <span style="font-size:9.5px;color:var(--text-dim);">(modifié par Admin)</span>' : '') + '<div style="font-size:9.5px;color:var(--text-dim);">' + fmtDateTime(rm.createdAt) + '</div></div>';
          if (state.adminIsOwner) {
            html += '<div style="display:flex;gap:4px;flex-shrink:0;">';
            if (!rm.isVoice) html += '<button class="link-btn" style="padding:4px;" data-action="admin-edit-message" data-value="' + cv.id + '" data-msg="' + rm.id + '"><i class="fa-solid fa-pen"></i></button>';
            html += '<button class="link-btn" style="padding:4px;color:var(--danger);" data-action="admin-delete-message" data-value="' + cv.id + '" data-msg="' + rm.id + '"><i class="fa-solid fa-trash"></i></button>';
            html += '</div>';
          }
          html += '</div>';
        }
      }
      html += '</div>';
    }
  }
  html += '</div>';

  return html;
}


// ---------- ACCÈS CLAUDE (clé technique de l'assistant, fonction claude-admin) ----------
// Interrupteur + journal de tout ce que Claude a fait. Les deux sont des
// réglages protégés (settings/claude_access et settings/claude_log) : seul
// l'admin (ou le serveur) peut les modifier.
function getSettingDoc(id) {
  for (var i = 0; i < (state.settings || []).length; i++) { if (state.settings[i] && state.settings[i].id === id) return state.settings[i]; }
  return null;
}
var CLAUDE_OP_LABELS = {
  article_publie: "Article publié", article_modifie: "Article modifié", article_retire: "Article retiré",
  pub_vip_creee: "Pub VIP créée", pub_vip_modifiee: "Pub VIP modifiée", pub_vip_supprimee: "Pub VIP supprimée",
  reglage_modifie: "Réglage modifié", boutique_creee: "Boutique créée", boutique_mise_a_jour: "Boutique mise à jour", lien_test_ligdicash: "Lien de test LigdiCash"
};
function renderAdminClaude() {
  var acc = getSettingDoc("claude_access") || {};
  var on = acc.enabled === true;
  var logDoc = getSettingDoc("claude_log") || {};
  var entries = Array.isArray(logDoc.entries) ? logDoc.entries : [];
  var official = (state.products || []).filter(function(p) { return p.sellerId === "sounsouni-officiel"; }).length;
  var html = '<div class="seasonal-effects-panel" style="margin-bottom:12px;">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;">';
  html += '<div style="font-weight:700;font-size:14px;"><i class="fa-solid fa-robot"></i> Accès de Claude</div>';
  html += '<div class="flex-row"><span style="font-size:12px;color:var(--text-dim);">' + (on ? 'Activé' : 'Coupé') + '</span>';
  html += '<div class="toggle-switch ' + (on ? 'active' : '') + '" data-action="toggle-claude-access"><div class="toggle-knob"></div></div></div></div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-top:6px;line-height:1.5;">Coupé = Claude ne peut plus rien lire ni rien faire, immédiatement.' + (acc.changedAt ? ' Dernier changement : ' + esc(new Date(acc.changedAt).toLocaleString("fr-FR")) + (acc.changedBy ? ' (' + esc(acc.changedBy) + ')' : '') + '.' : '') + '</div>';
  html += '</div>';
  html += '<div class="seasonal-effects-panel" style="margin-bottom:12px;font-size:12px;line-height:1.6;">';
  html += '<div style="font-weight:700;font-size:13px;margin-bottom:6px;">Ce que Claude peut faire</div>';
  html += '<div>✅ Voir l\'état de Sounsouni (commandes, paiements, articles, litiges) <b>sans</b> les données personnelles (téléphones, adresses, noms des clients).</div>';
  html += '<div>✅ Publier, modifier ou retirer les articles de la boutique <b>Sounsouni Officiel</b> (' + official + ' article' + (official > 1 ? 's' : '') + ' aujourd\'hui).</div>';
  html += '<div>✅ Gérer les pubs VIP et quelques réglages d\'affichage du marché.</div>';
  html += '<div style="margin-top:6px;">⛔ Jamais : toucher aux articles des autres vendeurs, aux comptes, aux mots de passe, à l\'argent ou à cet interrupteur.</div>';
  html += '</div>';
  html += '<div class="seasonal-effects-panel">';
  html += '<div style="font-weight:700;font-size:13px;margin-bottom:8px;">Journal (' + entries.length + ')</div>';
  if (!entries.length) html += '<div style="font-size:12px;color:var(--text-dim);">Aucune action pour le moment.</div>';
  for (var i = 0; i < entries.length && i < 60; i++) {
    var e = entries[i] || {};
    html += '<div style="display:flex;gap:8px;padding:7px 0;border-top:1px solid var(--border-color);font-size:12px;">';
    html += '<div style="flex:0 0 auto;color:var(--text-dim);min-width:92px;">' + esc(new Date(e.at || 0).toLocaleString("fr-FR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" })) + '</div>';
    html += '<div style="min-width:0;"><b>' + esc(CLAUDE_OP_LABELS[e.op] || e.op || "") + '</b>' + (e.summary ? ' — ' + esc(e.summary) : '') + '</div></div>';
  }
  html += '</div>';
  return html;
}
function toggleClaudeAccess() {
  var cur = getSettingDoc("claude_access") || {};
  var turnOn = cur.enabled !== true;
  if (!turnOn && !confirm("Couper l'accès de Claude ? Il ne pourra plus rien lire ni rien faire tant que vous ne le rallumez pas.")) return;
  var doc = { id: "claude_access", enabled: turnOn, changedAt: Date.now(), changedBy: state.profile ? (state.profile.name || "admin") : "admin" };
  var idx = -1;
  for (var i = 0; i < state.settings.length; i++) { if (state.settings[i] && state.settings[i].id === "claude_access") { idx = i; break; } }
  if (idx === -1) state.settings.push(doc); else state.settings[idx] = doc;
  save();
  saveDoc("settings", doc);
  showToast(turnOn ? "Accès de Claude activé" : "Accès de Claude coupé");
  render();
}

function renderAdminEffects() {
  var e = state.seasonalEffects;
  var fxOn = isMarketFxEnabled();
  var html = '<div class="seasonal-effects-panel" style="margin-bottom:12px;">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
  html += '<div style="font-weight:700;font-size:14px;"><i class="fa-solid fa-wand-magic-sparkles"></i> Effets animés du marché</div>';
  html += '<div class="flex-row"><span style="font-size:12px;color:var(--text-dim);">' + (fxOn ? 'Activé' : 'Désactivé') + '</span>';
  html += '<div class="toggle-switch ' + (fxOn ? 'active' : '') + '" data-action="toggle-market-fx"><div class="toggle-knob"></div></div></div>';
  html += '</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-top:4px;">Reflets, pulsations, balayages et changement automatique des articles « À la une ». Pour tout le monde. Coupé = application plus légère sur les petits téléphones.</div>';
  html += '</div>';
  html += '<div class="seasonal-effects-panel">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
  html += '<div style="font-weight:700;font-size:14px;"><i class="fa-solid fa-sparkles"></i> Effets saisonniers</div>';
  html += '<div class="flex-row"><span style="font-size:12px;color:var(--text-dim);">Activé</span>';
  html += '<div class="toggle-switch ' + (e.enabled ? 'active' : '') + '" data-action="toggle-seasonal"><div class="toggle-knob"></div></div></div>';
  html += '</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-top:4px;">Ajoute des animations sur toute la plateforme.</div>';
  html += '<div class="effect-options">';
  var effects = ['none', 'snow', 'hearts', 'fireworks', 'mali'];
  var labels = ['Aucun', '❄️ Neige', '❤️ Cœurs', '🎆 Feux', '🇲🇱 Mali'];
  for (var i = 0; i < effects.length; i++) {
    html += '<button class="' + (e.effect === effects[i] ? 'active' : '') + '" data-action="set-seasonal-effect" data-value="' + effects[i] + '">' + labels[i] + '</button>';
  }
  html += '</div></div>';
  html += '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;box-shadow:var(--shadow);">';
  html += '<div style="font-weight:700;font-size:13px;margin-bottom:8px;">Calendrier des fêtes</div>';
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:11px;">';
  for (var j = 0; j < HOLIDAYS.length; j++) {
    var h = HOLIDAYS[j];
    html += '<div style="background:var(--bg-body);padding:6px 10px;border-radius:8px;display:flex;align-items:center;gap:6px;">';
    html += '<span>' + h.emoji + '</span>';
    html += '<span style="font-weight:600;">' + h.name + '</span>';
    html += '<span style="color:var(--text-dim);font-size:10px;">' + h.day + '/' + h.month + '</span>';
    html += '</div>';
  }
  html += '</div>';
  html += '<div style="font-size:10px;color:var(--text-dim);margin-top:8px;">Les effets sont recommandés selon les fêtes proches.</div>';
  html += '</div>';
  return html;
}

// ---------- ADMIN : INTÉGRATION PLATEFORME EXTERNE (Groupe 1 uniquement) ----------
// Fenêtre de détail d'un colis externe — historique complet horodaté,
// et lien cliquable vers le compte du Point de Retrait concerné (comme pour
// les commandes normales, pour maximiser les informations accessibles).
function renderAdminParcelDetailModal() {
  var p = null;
  for (var i = 0; i < state.externalParcels.length; i++) {
    if (state.externalParcels[i].id === state.adminParcelDetailId) { p = state.externalParcels[i]; break; }
  }
  if (!p) return '';
  var html = '<div class="modal-overlay" id="parcel-detail-overlay" data-action="close-admin-parcel-detail"><div class="modal-sheet">';
  html += '<button class="modal-close" data-action="close-admin-parcel-detail"><i class="fa-solid fa-xmark"></i></button>';
  html += '<div class="section-title" style="margin-bottom:10px;">' + esc(p.trackingNumber) + '</div>';
  html += '<div style="display:flex;justify-content:space-between;margin-bottom:10px;"><span style="font-size:12px;color:var(--text-dim);">' + esc(p.platform) + '</span><span class="status-pill">' + translateStatus(p.status) + '</span></div>';
  html += '<div class="glass-card" style="padding:12px;margin-bottom:12px;">';
  html += '<div style="font-size:11px;font-weight:800;color:var(--text-dim);margin-bottom:6px;">Destinataire</div>';
  html += '<div style="font-size:13px;font-weight:700;">' + esc(p.recipientName) + '</div>';
  html += '<div style="font-size:12px;color:var(--text-dim);">' + esc(p.recipientPhone) + '</div>';
  if (p.description) html += '<div style="font-size:11.5px;color:var(--text-dim);margin-top:6px;">' + esc(p.description) + '</div>';
  html += '</div>';
  html += '<button class="link-btn" style="font-size:11.5px;margin-bottom:12px;" data-action="open-admin-account-detail" data-value="' + p.relaisShopId + '"><i class="fa-solid fa-shop"></i> ' + esc(p.relaisShopName) + ' — voir le compte</button>';
  html += '<div style="background:var(--bg-body);border-radius:10px;padding:10px;">';
  html += '<div style="font-size:11px;font-weight:800;color:var(--text-dim);margin-bottom:6px;"><i class="fa-solid fa-clock-rotate-left"></i> ' + t("order_full_history") + '</div>';
  for (var h = 0; h < p.statusHistory.length; h++) {
    var step = p.statusHistory[h];
    html += '<div style="display:flex;justify-content:space-between;font-size:11.5px;padding:3px 0;' + (h > 0 ? 'border-top:1px dashed var(--border-color);' : '') + '">';
    html += '<span style="font-weight:700;">' + esc(step.status) + '</span><span style="color:var(--text-dim);white-space:nowrap;margin-left:8px;">' + fmtDateTime(step.at) + '</span>';
    html += '</div>';
  }
  html += '</div></div></div>';
  return html;
}

// ---------- ADMIN : COLIS EXTERNES (création, modification, suppression) ----------
// Groupe 1 : pouvoir complet. Groupe 2 : peut créer, mais toute
// modification/suppression passe par une demande soumise au Groupe 1.
// ---------- ADMIN : SÉCURITÉ (identifiants des deux groupes) ----------
function renderAdminSecurity() {
  var ownerCreds = getAdminCredentials("owner");
  var html = '';

  // ---- Pièges à robots : alertes (Admin principal uniquement) ----
  if (state.adminIsOwner) {
    var alerts = state.securityAlerts || [];
    var dayAgo = Date.now() - 24 * 3600 * 1000;
    var last24 = alerts.filter(function(a) { return (a.at || 0) > dayAgo; }).length;
    html += '<div class="glass-card" style="padding:14px;margin-bottom:14px;">';
    html += '<div style="font-weight:800;font-size:13.5px;margin-bottom:4px;"><i class="fa-solid fa-spider"></i> Pièges à robots</div>';
    html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:10px;">Champs et collections pièges dans la base, champs invisibles et chronomètre dans les formulaires. Chaque tentative est bloquée puis listée ici.</div>';
    html += '<div style="font-size:12.5px;margin-bottom:8px;">' + (alerts.length ? '<strong>' + last24 + '</strong> alerte(s) ces dernières 24 h · ' + alerts.length + ' au total (200 dernières)' : '✅ Aucune tentative détectée.') + '</div>';
    alerts.slice(0, 30).forEach(function(a) {
      var icon = a.type === "formulaire" ? "fa-keyboard" : (a.type === "limite" ? "fa-gauge-high" : (a.type === "collection_piege" ? "fa-box-open" : "fa-user-secret"));
      html += '<div style="border-left:3px solid var(--danger);padding:6px 10px;margin-bottom:6px;background:var(--bg-body);border-radius:6px;">';
      html += '<div style="font-size:11px;color:var(--text-dim);"><i class="fa-solid ' + icon + '"></i> ' + fmtDateTime(a.at) + (a.ip && a.ip !== '?' ? ' · IP ' + esc(a.ip) : '') + '</div>';
      html += '<div style="font-size:12px;">' + esc(a.detail || a.type || '') + '</div>';
      html += '</div>';
    });
    html += '</div>';
  }

  if (state.adminIsOwner && !state.adminCountryScope) {
    var xrCfg = getExchangeRateConfig();
    html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
    html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-money-bill-transfer"></i> Taux de change (Roupie indienne → FCFA)</div>';
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:12px;">Utilisé pour convertir automatiquement les prix des vendeurs internationaux. En mode automatique, le taux se met à jour tout seul une fois par jour — rien à faire.</div>';
    html += '<div style="display:flex;gap:8px;margin-bottom:12px;">';
    html += '<button class="btn-secondary' + (xrCfg.mode === "auto" ? " active" : "") + '" style="flex:1;' + (xrCfg.mode === "auto" ? "border-color:var(--accent);color:var(--accent);" : "") + '" data-action="set-exchange-rate-mode" data-value="auto">Automatique</button>';
    html += '<button class="btn-secondary' + (xrCfg.mode === "manual" ? " active" : "") + '" style="flex:1;' + (xrCfg.mode === "manual" ? "border-color:var(--accent);color:var(--accent);" : "") + '" data-action="set-exchange-rate-mode" data-value="manual">Manuel</button>';
    html += '</div>';
    if (xrCfg.mode === "auto") {
      html += '<div style="font-size:12px;color:var(--text-secondary);">Taux actuel : <b>1 ₹ = ' + (xrCfg.autoRate || EXCHANGE_RATE_FALLBACK_INR_TO_XOF).toFixed(2) + ' FCFA</b>';
      html += xrCfg.autoRateFetchedAt ? ' <span style="color:var(--text-dim);">(mis à jour ' + relativeTimeAgo(xrCfg.autoRateFetchedAt) + ')</span>' : ' <span style="color:var(--text-dim);">(pas encore récupéré — valeur de secours utilisée)</span>';
      html += '</div>';
    } else {
      html += '<label class="field-label" style="margin-top:0;">1 Roupie indienne (₹) = combien de FCFA ?</label>';
      html += '<input class="input" type="number" step="0.01" id="manual-exchange-rate-input" value="' + xrCfg.manualRate + '" data-action-input="manual-exchange-rate" />';
    }
    html += '</div>';
  }

  // ---- Diagnostic de taille — toujours visible, pour voir exactement ce
  // qui prend de la place, indépendamment des autres outils ci-dessous. ----
  var sizeDiag = computeStateSizeBreakdown();
  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-chart-simple"></i> Diagnostic de taille</div>';
  html += '<div class="mono" style="font-size:20px;font-weight:700;color:var(--accent);margin-bottom:8px;">' + (sizeDiag.total > 1024 ? (sizeDiag.total / 1024).toFixed(2) + ' Mo' : sizeDiag.total + ' Ko') + '</div>';
  html += '<div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">Les plus gros postes</div>';
  for (var sdi = 0; sdi < Math.min(sizeDiag.breakdown.length, 15); sdi++) {
    var sd = sizeDiag.breakdown[sdi];
    html += '<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;border-bottom:1px solid var(--border-color);"><span>' + esc(sd.key) + (sd.count != null ? ' (' + sd.count + ')' : '') + '</span><span style="font-weight:700;">' + (sd.sizeKB > 1024 ? (sd.sizeKB / 1024).toFixed(2) + ' Mo' : sd.sizeKB + ' Ko') + '</span></div>';
  }
  html += '</div>';

  // ---- Ce que le navigateur rapporte lui-même (rempli après coup, car
  // l'information est asynchrone — voir renderPendingStorageReport). ----
  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;" id="browser-storage-report" data-storage-report-pending="1">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-hard-drive"></i> Ce que le navigateur voit réellement</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);">Chargement…</div>';
  html += '</div>';

  // ---- Nettoyage des vieilles photos enregistrées en base64 (avant
  // Supabase Storage) — cause la plus fréquente de "stockage plein" sur
  // le téléphone. ----
  var embeddedPhotos = scanForEmbeddedPhotos();
  if (embeddedPhotos.length > 0) {
    var totalKB = embeddedPhotos.reduce(function(s, e) { return s + e.sizeKB; }, 0);
    html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;border:1.5px solid var(--danger);">';
    html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-broom"></i> Vieilles photos à nettoyer (' + embeddedPhotos.length + ')</div>';
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Enregistrées directement dans les données avant la mise en place de Supabase Storage — environ ' + (totalKB > 1024 ? (totalKB / 1024).toFixed(1) + ' Mo' : totalKB + ' Ko') + ' à libérer. Les retirer efface la photo concernée (la personne peut en renvoyer une, stockée correctement cette fois).</div>';
    for (var epi = 0; epi < Math.min(embeddedPhotos.length, 10); epi++) {
      var ep = embeddedPhotos[epi];
      html += '<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;"><span>' + esc(ep.label) + ' — ' + esc(ep.field) + '</span><span style="color:var(--text-dim);">' + ep.sizeKB + ' Ko</span></div>';
    }
    if (embeddedPhotos.length > 10) html += '<div style="font-size:11px;color:var(--text-dim);margin-top:4px;">+ ' + (embeddedPhotos.length - 10) + ' autre(s)</div>';
    html += '<button class="btn-primary" style="width:100%;margin-top:10px;background:var(--danger);" data-action="clean-embedded-photos"><i class="fa-solid fa-trash"></i> Tout nettoyer</button>';
    html += '</div>';
  }

  // ---- Demandes de récupération de mot de passe ("code perdu") ----
  var recoveryReqs = (state.passwordRecoveryRequests || []).filter(function(r) { return r.status === "pending"; });
  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;' + (recoveryReqs.length > 0 ? 'border:1.5px solid var(--accent);' : '') + '">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-key"></i> Demandes de récupération de mot de passe (' + recoveryReqs.length + ')</div>';
  if (recoveryReqs.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim);">Aucune demande en attente.</div>';
  } else {
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Vérifiez l\'identité de la personne (appel téléphonique recommandé) avant de définir un nouveau mot de passe sur son compte.</div>';
    for (var rq = 0; rq < recoveryReqs.length; rq++) {
      var req = recoveryReqs[rq];
      html += '<div style="background:var(--bg-body);border-radius:10px;padding:10px;margin-bottom:8px;">';
      html += '<div style="font-size:12.5px;font-weight:700;">' + esc(req.name) + '</div>';
      html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:4px;">' + esc(req.phone || '—') + ' · ' + esc(req.email || '—') + ' · né(e) le ' + esc(req.birthDate || '—') + '</div>';
      html += '<div style="font-size:10.5px;color:var(--text-dim);margin-bottom:8px;">Demandé le ' + fmtDateTime(req.createdAt) + '</div>';
      html += '<div style="display:flex;gap:8px;">';
      html += '<button class="link-btn" style="font-size:11.5px;" data-action="open-admin-account-detail" data-value="' + req.accountId + '"><i class="fa-solid fa-user"></i> Voir le compte</button>';
      html += '<button class="link-btn" style="font-size:11.5px;color:var(--danger);" data-action="dismiss-recovery-request" data-value="' + req.id + '"><i class="fa-solid fa-xmark"></i> Ignorer</button>';
      html += '</div>';
      html += '</div>';
    }
  }
  html += '</div>';

  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-crown"></i> Identifiants — Groupe 1 (Accès complet)</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:12px;">Le mot de passe est protégé — il ne s\'affiche jamais ici. Laisse le champ vide pour ne rien changer, ou tape un nouveau mot de passe pour le remplacer.</div>';
  html += '<label class="field-label" style="margin-top:0;">Nom d\'utilisateur</label>';
  html += '<input class="input" id="owner-cred-user" value="' + esc(ownerCreds.username) + '" data-action-input="owner-cred-username" />';
  html += '<label class="field-label">Nouveau mot de passe (laisser vide pour garder l\'actuel)</label>';
  html += '<div style="position:relative;"><input class="input" type="password" id="owner-cred-pass" value="" style="padding-right:44px;" placeholder="🔒 Protégé — tapez pour remplacer" data-action-input="owner-cred-password" /><button type="button" class="pw-eye-btn" data-action="toggle-pw-visibility" style="position:absolute;right:6px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--text-dim);padding:8px;"><i class="fa-solid fa-eye"></i></button></div>';
  html += '</div>';

  html += '<div class="glass-card" style="padding:14px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-user-tie"></i> Groupe 2 (Accès limité) — par numéro, sans mot de passe</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:12px;">Ajoute directement le numéro d\'un compte Sounsouni existant : dès qu\'il se connecte avec ce numéro, il peut basculer vers cet espace sans rien saisir. Retire le numéro pour couper l\'accès.</div>';
  html += '<div style="display:flex;gap:8px;margin-bottom:10px;">';
  html += '<input class="input" id="g2-global-phone" placeholder="Numéro (ex : 70 00 00 00)" data-format="phone" style="flex:1;" />';
  html += '<button class="btn-primary" style="flex:0;padding:0 16px;" data-action="add-group2-global"><i class="fa-solid fa-plus"></i></button>';
  html += '</div>';
  var g2List = state.group2GlobalWhitelist || [];
  if (g2List.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucun numéro autorisé pour l\'instant.</div>';
  } else {
    for (var g2i = 0; g2i < g2List.length; g2i++) {
      var g2w = g2List[g2i];
      var g2Acc = findAccountByPhone(g2w.phone);
      html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-top:1px solid var(--border-color);">';
      html += '<div><div style="font-weight:700;font-size:12.5px;">' + esc(g2Acc ? g2Acc.name : (g2w.name || "Compte")) + '</div><div style="font-size:11px;color:var(--text-dim);">' + esc(g2w.phone) + '</div></div>';
      html += '<button class="link-btn" style="color:var(--danger);" data-action="remove-group2-global" data-value="' + esc(g2w.id) + '"><i class="fa-solid fa-trash"></i></button>';
      html += '</div>';
    }
  }
  html += '</div>';

  html += '<div class="glass-card" style="padding:14px;margin-top:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-magnifying-glass-dollar"></i> Agent Sourcing — par numéro, sans mot de passe</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:12px;">Section séparée du Groupe 2 : un numéro ajouté ici bascule directement vers l\'espace Agent Sourcing (jamais vers l\'Admin) via le même bouton "Administration".</div>';
  html += '<div style="display:flex;gap:8px;margin-bottom:10px;">';
  html += '<input class="input" id="sourcing-agent-phone" placeholder="Numéro (ex : 70 00 00 00)" data-format="phone" style="flex:1;" />';
  html += '<button class="btn-primary" style="flex:0;padding:0 16px;" data-action="add-sourcing-agent-whitelist"><i class="fa-solid fa-plus"></i></button>';
  html += '</div>';
  var saList = state.sourcingAgentWhitelist || [];
  if (saList.length === 0) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);">Aucun numéro autorisé pour l\'instant.</div>';
  } else {
    for (var sai = 0; sai < saList.length; sai++) {
      var saw = saList[sai];
      var saAcc = findAccountByPhone(saw.phone);
      html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-top:1px solid var(--border-color);">';
      html += '<div><div style="font-weight:700;font-size:12.5px;">' + esc(saAcc ? saAcc.name : (saw.name || "Compte")) + '</div><div style="font-size:11px;color:var(--text-dim);">' + esc(saw.phone) + '</div></div>';
      html += '<button class="link-btn" style="color:var(--danger);" data-action="remove-sourcing-agent-whitelist" data-value="' + esc(saw.id) + '"><i class="fa-solid fa-trash"></i></button>';
      html += '</div>';
    }
  }
  html += '</div>';

  // ---- Admins nationaux (expansion internationale) — réservé au Groupe 1
  // global uniquement, jamais visible par un admin national lui-même. ----
  if (state.adminIsOwner && !state.adminCountryScope) {
    var naSearch = (state.adminNationalSearch || "").toLowerCase().trim();
    var naListFiltered = state.nationalAdmins;
    if (naSearch) naListFiltered = naListFiltered.filter(function(na) { return na.country.toLowerCase().indexOf(naSearch) !== -1; });
    var naCollapsed = !!state.collapsedAdminSections.nationalAdminsList;
    html += '<div class="glass-card" style="padding:14px;margin-top:16px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">';
    html += '<div style="font-weight:800;font-size:14px;"><i class="fa-solid fa-earth-africa"></i> Admins nationaux (' + state.nationalAdmins.length + ')</div>';
    html += '<button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="nationalAdminsList"><i class="fa-solid ' + (naCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button>';
    html += '</div>';
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:10px;">Un admin par pays étendu, avec le même pouvoir que toi mais limité à ce pays — et ses propres employés, à pouvoir limité comme les tiens.</div>';
    if (state.nationalAdmins.length > 5) html += '<input class="input" style="margin-bottom:12px;" placeholder="Rechercher un pays…" value="' + esc(state.adminNationalSearch || "") + '" data-action-input="admin-national-search" />';
    if (!naCollapsed) {
    for (var nai = 0; nai < naListFiltered.length; nai++) {
      var na = naListFiltered[nai];
      html += '<div style="background:var(--bg-body);border-radius:12px;padding:12px;margin-bottom:10px;">';
      html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;"><div style="font-weight:800;font-size:13px;">' + esc(na.country) + '</div><button class="link-btn" style="color:var(--danger);font-size:11px;" data-action="remove-national-admin" data-value="' + na.id + '"><i class="fa-solid fa-trash"></i></button></div>';
      html += '<label class="field-label" style="margin-top:0;font-size:10px;">Identifiants admin national (pouvoir complet, ce pays)</label>';
      html += '<input class="input" style="margin-bottom:6px;" value="' + esc(na.ownerUsername) + '" data-action-input="national-owner-username" data-config="' + na.id + '" placeholder="Nom d\'utilisateur" />';
      html += '<div style="position:relative;"><input class="input" type="password" value="" style="padding-right:44px;" placeholder="🔒 Protégé — tapez pour remplacer" data-action-input="national-owner-password" data-config="' + na.id + '" /><button type="button" class="pw-eye-btn" data-action="toggle-pw-visibility" style="position:absolute;right:6px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--text-dim);padding:8px;"><i class="fa-solid fa-eye"></i></button></div>';
      html += '<label class="field-label" style="font-size:10px;">Groupe 2 de ce pays — par numéro, sans mot de passe</label>';
      html += '<div style="display:flex;gap:8px;margin-bottom:8px;">';
      html += '<input class="input" id="g2-national-phone-' + na.id + '" placeholder="Numéro (ex : 70 00 00 00)" data-format="phone" style="flex:1;" />';
      html += '<button class="btn-primary" style="flex:0;padding:0 14px;" data-action="add-group2-national" data-value="' + na.id + '"><i class="fa-solid fa-plus"></i></button>';
      html += '</div>';
      var naG2List = na.employeeWhitelist || [];
      if (naG2List.length === 0) {
        html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:8px;">Aucun numéro autorisé pour l\'instant.</div>';
      } else {
        for (var nag2i = 0; nag2i < naG2List.length; nag2i++) {
          var nag2w = naG2List[nag2i];
          var nag2Acc = findAccountByPhone(nag2w.phone);
          html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-top:1px solid var(--border-color);">';
          html += '<div><div style="font-weight:700;font-size:11.5px;">' + esc(nag2Acc ? nag2Acc.name : (nag2w.name || "Compte")) + '</div><div style="font-size:10px;color:var(--text-dim);">' + esc(nag2w.phone) + '</div></div>';
          html += '<button class="link-btn" style="color:var(--danger);" data-action="remove-group2-national" data-value="' + esc(nag2w.id) + '" data-config="' + na.id + '"><i class="fa-solid fa-trash"></i></button>';
          html += '</div>';
        }
      }
      html += '<label class="field-label" style="font-size:10px;"><i class="fa-solid fa-lock"></i> Statut (visible uniquement par toi)</label>';
      html += '<button class="vendor-hub-card" style="padding:10px;" data-action="toggle-national-partner" data-value="' + na.id + '"><i class="fa-solid ' + (na.isPartner ? 'fa-toggle-on' : 'fa-toggle-off') + '" style="color:' + (na.isPartner ? 'var(--accent)' : 'var(--text-dim)') + ';"></i><div><div class="vh-title" style="font-size:12px;">' + (na.isPartner ? 'Partenaire (touche une commission)' : 'Administrateur embauché (pas de commission)') + '</div></div></button>';
      if (na.isPartner) {
        html += '<label class="field-label" style="font-size:10px;">Sa part de commission (%)</label>';
        html += '<input class="input" type="number" value="' + (na.commissionRate != null ? na.commissionRate : '') + '" data-action-input="national-commission-rate" data-config="' + na.id + '" placeholder="Ex : 15" />';
      }
      html += '</div>';
    }
    }
    html += '<button class="btn-secondary" data-action="add-national-admin"><i class="fa-solid fa-plus"></i> Ajouter un admin national</button>';
    html += '</div>';
  }

  return html;
}

// ---------- ADMIN : INTERNATIONAL (vue globale + par pays) ----------
function renderAdminInternational() {
  if (!state.adminIsOwner || state.adminCountryScope) return '<div class="empty-state"><i class="fa-solid fa-lock"></i><div class="title">Réservé au Groupe 1 global</div></div>';

  var selected = state.adminInternationalCountry || null;
  var intlCities = getInternationalCities();
  var countriesWithCities = [];
  for (var cwc0 = 0; cwc0 < intlCities.length; cwc0++) {
    if (countriesWithCities.indexOf(intlCities[cwc0].country) === -1) countriesWithCities.push(intlCities[cwc0].country);
  }
  var allCountries = ["Mali"].concat(countriesWithCities);
  var html = '';

  if (!selected) {
    // ---- Vue d'ensemble : tous les pays ----
    var totalVilles = intlCities.length;
    var totalQuartiers = intlCities.reduce(function(sum, c) { return sum + (c.quartiers || []).length; }, 0);
    html += '<div class="kpi-grid" style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:20px;">';
    html += '<div class="kpi" style="--kpi-color:var(--mc-cyan);background:var(--mc-panel);border:1px solid var(--mc-line);border-radius:10px;padding:14px;"><div style="font-size:9.5px;text-transform:uppercase;color:var(--mc-dim);letter-spacing:1px;">Pays configurés</div><div class="mono" style="font-size:22px;font-weight:700;">' + allCountries.length + '</div></div>';
    html += '<div class="kpi" style="--kpi-color:var(--mc-green);background:var(--mc-panel);border:1px solid var(--mc-line);border-radius:10px;padding:14px;"><div style="font-size:9.5px;text-transform:uppercase;color:var(--mc-dim);letter-spacing:1px;">Villes / Quartiers</div><div class="mono" style="font-size:22px;font-weight:700;">' + totalVilles + ' / ' + totalQuartiers + '</div></div>';
    html += '</div>';

    html += '<div style="font-size:11px;text-transform:uppercase;letter-spacing:2px;color:var(--mc-dim);font-weight:700;margin-bottom:10px;">Pays — touchez pour ouvrir</div>';
    html += '<div class="mc-tiles">';
    for (var aci = 0; aci < allCountries.length; aci++) {
      var acCountry = allCountries[aci];
      var acCities = intlCities.filter(function(c) { return c.country === acCountry; });
      var acFlag = "";
      for (var accc = 0; accc < COUNTRY_CODES.length; accc++) { if (COUNTRY_CODES[accc].country === acCountry) { acFlag = COUNTRY_CODES[accc].label.split(" ")[0]; break; } }
      var acNA = state.nationalAdmins.find(function(n) { return n.country === acCountry; });
      html += '<button class="mc-tile" data-action="open-admin-international-country" data-value="' + esc(acCountry) + '">';
      html += '<div class="mc-tile-icon" style="font-size:16px;">' + acFlag + '</div>';
      html += '<div class="mc-tile-name">' + esc(acCountry) + '</div>';
      html += '<div style="font-size:10px;color:var(--mc-dim);">' + acCities.length + ' ville(s)' + (acCountry !== "Mali" ? (acNA ? ' · admin actif' : ' · pas d\'admin') : '') + '</div>';
      html += '</button>';
    }
    html += '</div>';

    // ---- Tarifs de transport international (vendeurs internationaux) ----
    // En roupies (INR), comme les prix des vendeurs indiens — convertis en
    // FCFA au paiement avec le taux du jour. Le transport facturé = le plus
    // élevé entre le poids réel et le poids volumétrique (volume × 167),
    // multiplié par le tarif au kilo, avec un minimum par envoi.
    var isCfg = getInternationalShippingConfig();
    var tbl = isCfg.airTable || defaultInternationalShippingConfig().airTable;
    // Exemple chiffré : un colis de 5 kg, pour vérifier les réglages d'un coup d'œil.
    var ex = (function() { var row = tbl.find(function(r) { return r[0] >= 5; }) || tbl[tbl.length - 1]; var base = row[1]; var gst = Math.round(base * (Number(isCfg.gstPct) || 0) / 100); var mg = Math.round((base + gst) * (Number(isCfg.marginPct) || 0) / 100); var r = getInrToXofRate(); return { base: base, gst: gst, mg: mg, xof: Math.round((base + gst + mg) * r) }; })();
    var num = function(id, label, val, step) { return '<div style="flex:1 1 120px;min-width:0;"><label class="field-label" style="margin-top:6px;font-size:10.5px;">' + label + '</label><input class="input" type="number" min="0" step="' + (step || 1) + '" id="' + id + '" value="' + esc(String(val)) + '" style="width:100%;min-width:0;" /></div>'; };
    html += '<div class="glass-card" style="padding:14px;margin-top:20px;">';
    html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-plane"></i> Transport depuis l\'Inde (avion)</div>';
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:8px;line-height:1.5;">Calcul colis par colis, livré à l\'aéroport de Bamako. Poids facturé = le plus élevé entre le poids réel et le poids de place (L × l × H ÷ 5 000), minimum 0,5 kg. Tableau du partenaire : 0,5 kg = ' + tbl[0][1].toLocaleString("fr-FR") + ' ₹ … ' + tbl[tbl.length - 1][0] + ' kg = ' + tbl[tbl.length - 1][1].toLocaleString("fr-FR") + ' ₹, puis un prix au kilo jusqu\'au poids maximum d\'un colis. Au-delà, la commande est partagée en plusieurs colis égaux, chacun calculé avec le tableau. Le bateau se fait sur devis.</div>';
    html += '<div style="display:flex;flex-wrap:wrap;gap:8px;">';
    html += num("intl-air-perkg", "Prix / kg de 21 à 44 kg (₹)", isCfg.airPerKgAbove20);
    html += num("intl-air-max", "Poids maximum d'un colis (kg)", isCfg.airMaxKg);
    html += num("intl-air-gst", "Taxe indienne GST (%)", isCfg.gstPct, 0.5);
    html += num("intl-air-margin", "Frais Sounsouni (%)", isCfg.marginPct, 0.5);
    var dutyNow = isCfg.customsDutyPct != null ? isCfg.customsDutyPct : (isCfg.customsPct || 0);
    html += num("intl-air-duty", "Droits de douane (%)", dutyNow, 0.5);
    html += num("intl-air-vat", "TVA Mali (%)", isCfg.vatPct != null ? isCfg.vatPct : 0, 0.5);
    html += '</div>';
    html += '<label class="field-label" style="font-size:10.5px;">Délai affiché au client</label><input class="input" id="intl-air-delay" value="' + esc(isCfg.delayText || "6 à 12 jours") + '" />';
    html += '<div style="font-size:11px;color:var(--text-dim);margin-top:6px;">Douane + TVA = <strong>' + ((Number(dutyNow) || 0) + (Number(isCfg.vatPct) || 0)) + ' %</strong> de la valeur des articles (sans le transport), ajoutés au prix du client.</div>';
    // Tableau du partenaire modifiable (quand ses prix changent)
    html += '<button class="link-btn" style="margin-top:10px;font-size:12px;" data-action="toggle-air-table-editor"><i class="fa-solid ' + (state.showAirTableEditor ? 'fa-chevron-up' : 'fa-table') + '"></i> ' + (state.showAirTableEditor ? 'Fermer le tableau' : 'Modifier le tableau des prix du partenaire (0,5 à 20 kg)') + '</button>';
    if (state.showAirTableEditor) {
      html += '<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 10px;margin-top:8px;">';
      tbl.forEach(function(r, i) { html += '<div style="display:flex;align-items:center;gap:6px;min-width:0;"><span style="font-size:11.5px;width:44px;flex-shrink:0;">' + String(r[0]).replace(".", ",") + ' kg</span><input class="input" type="number" min="0" id="air-row-' + i + '" value="' + r[1] + '" style="flex:1;min-width:0;padding:6px 8px;font-size:12.5px;" /></div>'; });
      html += '</div>';
      html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:6px;">Prix en roupies, sans la taxe indienne. Appuie sur « Enregistrer » en bas pour garder les changements.</div>';
    }
    html += '<div style="font-size:11px;background:var(--bg-body);border-radius:10px;padding:8px 10px;margin-top:10px;line-height:1.5;"><strong>Exemple, colis de 5 kg :</strong> ' + ex.base.toLocaleString("fr-FR") + ' ₹ + taxe ' + ex.gst.toLocaleString("fr-FR") + ' ₹ + frais Sounsouni ' + ex.mg.toLocaleString("fr-FR") + ' ₹ = <strong>' + ex.xof.toLocaleString("fr-FR") + ' FCFA</strong> (sans les articles ni la douane)</div>';
    // Bateau : un seul prix tout compris au m³ (FCFA), modifiable.
    html += '<div style="font-weight:800;font-size:14px;margin:16px 0 6px;"><i class="fa-solid fa-ship"></i> Transport par bateau</div>';
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:6px;line-height:1.5;">Prix tout compris par m³ : bateau Inde → Dakar avec taxes indiennes, ports, camion Dakar → Bamako, transit et formalités. Vos frais Sounsouni (' + (isCfg.marginPct || 0) + ' %) et la douane + TVA s\'ajoutent comme pour l\'avion. 1 m³ ≈ 16 cartons moyens (50 × 40 × 30 cm).</div>';
    html += '<div style="display:flex;flex-wrap:wrap;gap:8px;">';
    html += num("intl-sea-price", "Prix par m³ (FCFA)", isCfg.seaPricePerM3Xof, 1000);
    html += num("intl-sea-min", "Minimum facturé (m³)", isCfg.seaMinM3, 0.05);
    html += num("intl-sea-kgm3", "Poids pour 1 m³ (kg)", isCfg.seaKgPerM3, 50);
    html += '</div>';
    html += '<div style="font-weight:800;font-size:14px;margin:16px 0 6px;"><i class="fa-solid fa-house"></i> Livraison à domicile à Bamako</div>';
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:6px;line-height:1.5;">Tarif normal de livraison du quartier du client, + un supplément pour les gros colis (et toujours pour le bateau). Compris dans la ligne « Livraison jusqu\'à chez vous ».</div>';
    html += '<div style="display:flex;flex-wrap:wrap;gap:8px;">';
    html += num("intl-home-heavykg", "Gros colis à partir de (kg)", isCfg.homeHeavyKg != null ? isCfg.homeHeavyKg : 30, 1);
    html += num("intl-home-extra", "Supplément gros colis (FCFA)", isCfg.homeHeavyExtraXof != null ? isCfg.homeHeavyExtraXof : 5000, 500);
    html += '</div>';
    html += '<label class="field-label" style="font-size:10.5px;">Délai bateau affiché au client</label><input class="input" id="intl-sea-delay" value="' + esc(isCfg.seaDelayText || "6 à 10 semaines") + '" />';
    html += '<div style="font-size:11px;color:var(--text-dim);margin:6px 0 4px;">Exemple, minimum facturé : ' + Number(Math.round((Number(isCfg.seaMinM3) || 0) * (Number(isCfg.seaPricePerM3Xof) || 0) * (1 + (Number(isCfg.marginPct) || 0) / 100))).toLocaleString("fr-FR") + ' FCFA de livraison (frais Sounsouni compris), hors douane.</div>';
    html += '<button class="btn-primary" style="margin-top:14px;" data-action="save-international-shipping-rates"><i class="fa-solid fa-floppy-disk"></i> Enregistrer les tarifs de transport</button>';
    html += '</div>';

    // ---- Service de géocodage (global, pas spécifique à un pays) ----
    var geoCfg = getGeocodingConfig();
    html += '<div class="glass-card" style="padding:14px;margin-top:20px;">';
    html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-map-location-dot"></i> Service de géocodage</div>';
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:14px;">Utilisé pour suggérer automatiquement les quartiers d\'une nouvelle ville. Sans service choisi ici, OpenStreetMap (gratuit) est utilisé par défaut.</div>';
    html += '<label class="field-label" style="margin-top:0;">Service</label>';
    html += '<select class="input" style="margin-bottom:10px;" data-action-input="geocoding-provider">';
    html += '<option value="none"' + (geoCfg.provider === "none" || !geoCfg.provider ? ' selected' : '') + '>Aucun — OpenStreetMap gratuit</option>';
    html += '<option value="mapbox"' + (geoCfg.provider === "mapbox" ? ' selected' : '') + '>Mapbox</option>';
    html += '</select>';
    if (geoCfg.provider === "mapbox") {
      html += '<label class="field-label">Jeton d\'accès (public, commence par pk.)</label>';
      html += '<input class="input" id="geocoding-token-input" value="' + esc(geoCfg.token || '') + '" data-action-input="geocoding-token" placeholder="pk.eyJ1Ijoi..." />';
    }
    html += '</div>';

    html += '<button class="btn-secondary" style="margin-top:16px;width:100%;" data-action="open-admin-add-international-city"><i class="fa-solid fa-plus"></i> Ajouter une nouvelle ville</button>';
    return html;
  }

  // ---- Vue détaillée d'UN pays ----
  var selFlag = "";
  for (var sfi = 0; sfi < COUNTRY_CODES.length; sfi++) { if (COUNTRY_CODES[sfi].country === selected) { selFlag = COUNTRY_CODES[sfi].label.split(" ")[0]; break; } }
  html += '<button class="mc-back" style="margin-bottom:14px;" data-action="close-admin-international-country"><i class="fa-solid fa-arrow-left"></i> Retour aux pays</button>';
  html += '<div class="mc-module-title"><span style="font-size:18px;">' + selFlag + '</span><h2>' + esc(selected) + '</h2></div>';

  // ---- Mini centre de contrôle de ce pays — mêmes indicateurs que
  // l'accueil général, mais filtrés uniquement sur ce pays. ----
  var cOrders = state.orders.filter(function(o) { return (o.country || "Mali") === selected; });
  var cSalesToday = cOrders.filter(function(o) { var d = new Date(o.createdAt); var now = new Date(); return d.toDateString() === now.toDateString(); }).reduce(function(sum, o) { return sum + (o.total || 0); }, 0);
  var cLivreurs = state.accounts.filter(function(a) { return a.livreurApplicationStatus === "approved" && (a.country || "Mali") === selected; }).length;
  var cVendeurs = state.accounts.filter(function(a) { return a.role === "vendeur" && (a.country || "Mali") === selected; }).length;
  var cDisputes = state.disputes.filter(function(d) { return (d.country || "Mali") === selected && d.status === "En litige"; }).length;
  html += '<div class="kpi-grid" style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:16px;">';
  html += '<div style="background:var(--mc-panel);border:1px solid var(--mc-line);border-radius:10px;padding:12px;"><div style="font-size:9px;text-transform:uppercase;color:var(--mc-dim);letter-spacing:1px;">Ventes du jour</div><div class="mono" style="font-size:18px;font-weight:700;">' + money(cSalesToday, selected) + '</div></div>';
  html += '<div style="background:var(--mc-panel);border:1px solid var(--mc-line);border-radius:10px;padding:12px;"><div style="font-size:9px;text-transform:uppercase;color:var(--mc-dim);letter-spacing:1px;">Livreurs actifs</div><div class="mono" style="font-size:18px;font-weight:700;">' + cLivreurs + '</div></div>';
  html += '<div style="background:var(--mc-panel);border:1px solid var(--mc-line);border-radius:10px;padding:12px;"><div style="font-size:9px;text-transform:uppercase;color:var(--mc-dim);letter-spacing:1px;">Litiges actifs</div><div class="mono" style="font-size:18px;font-weight:700;">' + cDisputes + '</div></div>';
  html += '<div style="background:var(--mc-panel);border:1px solid var(--mc-line);border-radius:10px;padding:12px;"><div style="font-size:9px;text-transform:uppercase;color:var(--mc-dim);letter-spacing:1px;">Vendeurs actifs</div><div class="mono" style="font-size:18px;font-weight:700;">' + cVendeurs + '</div></div>';
  html += '</div>';

  if (selected !== "Mali") {
    var selNA = state.nationalAdmins.find(function(n) { return n.country === selected; });
    html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
    html += '<div style="font-weight:800;font-size:13px;margin-bottom:8px;"><i class="fa-solid fa-user-shield"></i> Admin national</div>';
    if (selNA) {
      html += '<div class="data-row" style="display:flex;justify-content:space-between;padding:6px 0;"><span style="color:var(--mc-dim);">Statut</span><span class="status-tag" style="background:var(--mc-green-dim);color:var(--mc-green);padding:3px 9px;border-radius:99px;font-size:10.5px;font-weight:700;">Actif</span></div>';
      html += '<div class="data-row" style="display:flex;justify-content:space-between;padding:6px 0;"><span style="color:var(--mc-dim);">Partenaire</span><span class="mono">' + (selNA.isPartner ? 'Oui — ' + (selNA.commissionRate || 0) + '%' : 'Non — admin embauché') + '</span></div>';
      html += '<div class="data-row" style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-top:1px solid var(--mc-line);margin-top:4px;"><span style="color:var(--mc-dim);"><i class="fa-solid fa-user-secret"></i> Filature (dans son pays)</span><button class="link-btn" style="font-size:11px;font-weight:700;color:' + (selNA.filatureEnabled ? 'var(--mc-green)' : 'var(--mc-dim)') + ';" data-action="toggle-national-admin-filature" data-value="' + esc(selNA.id) + '">' + (selNA.filatureEnabled ? 'Activée — désactiver' : 'Désactivée — activer') + '</button></div>';
      html += '<button class="link-btn" style="margin-top:8px;" data-action="set-admin-tab" data-value="security"><i class="fa-solid fa-arrow-right"></i> Gérer ses identifiants (Sécurité)</button>';
    } else {
      html += '<div style="font-size:12px;color:var(--mc-dim);margin-bottom:8px;">Aucun admin national pour ce pays.</div>';
      html += '<button class="link-btn" data-action="set-admin-tab" data-value="security"><i class="fa-solid fa-arrow-right"></i> En créer un (Sécurité)</button>';
    }
    html += '</div>';
  }

  // ---- Villes de ce pays ----
  var selCities = intlCities.filter(function(c) { return c.country === selected; });
  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-city"></i> Villes</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:14px;">Quartiers proposés automatiquement via le service de géocodage réglé sur la vue d\'ensemble, à corriger avant d\'enregistrer.</div>';
  if (selected === "Mali") {
    html += '<div style="font-size:12px;color:var(--text-dim);">Bamako et les villes historiques du Mali restent gérées dans l\'onglet Quartiers.</div>';
  } else {
    for (var ici = 0; ici < selCities.length; ici++) {
      var ic = selCities[ici];
      html += '<div style="background:var(--bg-body);border-radius:12px;padding:12px;margin-bottom:10px;">';
      html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><div style="font-weight:800;font-size:13px;">' + esc(ic.city) + '</div><div style="display:flex;gap:12px;"><button class="link-btn" style="font-size:11px;" data-action="retry-international-city-quartiers" data-value="' + ic.id + '"><i class="fa-solid fa-arrows-rotate"></i></button><button class="link-btn" style="color:var(--danger);font-size:11px;" data-action="remove-international-city" data-value="' + ic.id + '"><i class="fa-solid fa-trash"></i></button></div></div>';
      html += '<label class="field-label" style="margin-top:0;font-size:10px;">Quartiers (un par ligne)</label>';
      html += '<textarea class="input" rows="4" data-action-input="intl-city-quartiers" data-config="' + ic.id + '">' + esc((ic.quartiers || []).join("\n")) + '</textarea>';
      html += '</div>';
    }
    html += '<label class="field-label" style="margin-top:0;">Nouvelle ville pour ' + esc(selected) + '</label>';
    html += '<input class="input" style="margin-bottom:6px;" id="new-intl-city-name" placeholder="Ex : Abidjan" />';
    html += '<input type="hidden" id="new-intl-city-country" value="' + esc(selected) + '" />';
    html += '<button class="btn-secondary" data-action="add-international-city"><i class="fa-solid fa-magnifying-glass-location"></i> Ajouter et suggérer les quartiers</button>';
  }
  html += '</div>';

  // ---- Paiement mobile money de ce pays ----
  var pCfg = getPaymentConfig(selected);
  var pSlug = countrySecretSlug(selected);
  html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-money-bill-transfer"></i> Paiement mobile money</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:14px;"><strong>Les clés se règlent dans Supabase</strong> (jamais ici) — les noms exacts s\'affichent selon ton choix.</div>';
  html += '<label class="field-label" style="margin-top:0;">Mode</label>';
  html += '<select class="input" style="margin-bottom:8px;" data-action-input="payment-mode" data-config="' + esc(selected) + '">';
  html += '<option value="none"' + (pCfg.mode === "none" ? ' selected' : '') + '>Aucun — paiement à la livraison seulement</option>';
  html += '<option value="aggregator"' + (pCfg.mode === "aggregator" ? ' selected' : '') + '>Agrégateur</option>';
  html += '<option value="individual"' + (pCfg.mode === "individual" ? ' selected' : '') + '>Chaque opérateur séparément</option>';
  html += '</select>';
  if (pCfg.mode === "aggregator") {
    html += '<label class="field-label">Agrégateur</label>';
    html += '<select class="input" style="margin-bottom:10px;" data-action-input="payment-aggregator" data-config="' + esc(selected) + '">';
    html += '<option value="cinetpay"' + (pCfg.aggregator === "cinetpay" ? ' selected' : '') + '>CinetPay</option>';
    html += '<option value="paydunya"' + (pCfg.aggregator === "paydunya" ? ' selected' : '') + '>PayDunya</option>';
    html += '<option value="flutterwave"' + (pCfg.aggregator === "flutterwave" ? ' selected' : '') + '>Flutterwave</option>';
    html += '<option value="ligdicash"' + (pCfg.aggregator === "ligdicash" ? ' selected' : '') + '>LigdiCash (Orange Money, Moov Money)</option>';
    html += '</select>';
    var secretNames = {
      cinetpay: ['CINETPAY_APIKEY_' + pSlug, 'CINETPAY_SITEID_' + pSlug],
      paydunya: ['PAYDUNYA_MASTERKEY_' + pSlug, 'PAYDUNYA_PRIVATEKEY_' + pSlug, 'PAYDUNYA_TOKEN_' + pSlug],
      flutterwave: ['FLUTTERWAVE_SECRETKEY_' + pSlug],
      ligdicash: ['LIGDICASH_API_KEY', 'LIGDICASH_AUTH_TOKEN']
    };
    var namesForAgg = secretNames[pCfg.aggregator] || secretNames.cinetpay;
    html += '<div style="font-size:10.5px;color:var(--text-dim);background:var(--bg-card);border-radius:8px;padding:8px;">Secrets Supabase à créer :<br>' + namesForAgg.map(function(n) { return '<code>' + n + '</code>'; }).join('<br>') + '</div>';
  } else if (pCfg.mode === "individual") {
    html += '<div style="font-size:10.5px;color:var(--text-dim);background:var(--bg-card);border-radius:8px;padding:8px;"><i class="fa-solid fa-triangle-exclamation"></i> Pas encore branché — chaque opérateur a sa propre API et un agrément séparé. Utilise un agrégateur en attendant.</div>';
  }
  html += '</div>';

  // ---- Tarifs de livraison de ce pays ----
  if (selected !== "Mali") {
    var dCfg = getInternationalDeliveryConfig(selected);
    html += '<div class="glass-card" style="padding:14px;">';
    html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-route"></i> Tarifs de livraison</div>';
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:14px;">Distance réelle boutique-acheteur, comme au Mali.</div>';
    html += '<label class="field-label" style="margin-top:0;">Tarif par km (' + currencySymbol(dCfg.currency) + ')</label>';
    html += '<input class="input" style="margin-bottom:6px;" type="number" value="' + dCfg.perKm + '" data-action-input="intl-delivery-perkm" data-config="' + esc(selected) + '" />';
    html += '<label class="field-label">Minimum</label>';
    html += '<input class="input" style="margin-bottom:6px;" type="number" value="' + dCfg.minimum + '" data-action-input="intl-delivery-minimum" data-config="' + esc(selected) + '" />';
    html += '<label class="field-label">Arrondi à</label>';
    html += '<input class="input" type="number" value="' + dCfg.roundTo + '" data-action-input="intl-delivery-roundto" data-config="' + esc(selected) + '" />';
    html += '</div>';
  }

  return html;
}

function renderAdminExternalParcelsTab() {
  var isOwner = state.adminIsOwner;
  var html = '';

  if (isOwner) {
    var pendingReqs = state.externalParcelChangeRequests.filter(function(r) { return r.status === "pending"; });
    if (pendingReqs.length > 0) {
      html += '<div class="glass-card" style="padding:14px;margin-bottom:16px;border:1.5px solid var(--accent);">';
      html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-clock"></i> Demandes en attente (' + pendingReqs.length + ')</div>';
      for (var r = 0; r < pendingReqs.length; r++) {
        var req = pendingReqs[r];
        var reqParcel = state.externalParcels.find(function(p) { return p.id === req.parcelId; });
        html += '<div style="background:var(--bg-body);border-radius:10px;padding:10px;margin-bottom:8px;">';
        html += '<div style="font-size:12px;font-weight:700;">' + (req.type === "delete" ? "Suppression" : "Modification") + ' — ' + (reqParcel ? esc(reqParcel.trackingNumber) : "colis introuvable") + '</div>';
        html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:8px;">Demandé par ' + esc(req.requestedByName) + ' · ' + fmtDateTime(req.createdAt) + '</div>';
        html += '<div style="display:flex;gap:8px;">';
        html += '<button class="btn-primary" style="flex:1;padding:6px;font-size:12px;" data-action="approve-parcel-change-request" data-value="' + req.id + '">Approuver</button>';
        html += '<button class="btn-secondary" style="flex:1;padding:6px;font-size:12px;" data-action="reject-parcel-change-request" data-value="' + req.id + '">Rejeter</button>';
        html += '</div></div>';
      }
      html += '</div>';
    }
  }

  html += renderExternalParcelFormSection();

  html += '<div class="glass-card" style="padding:14px;">';
  var parcelsCollapsed = !!state.collapsedAdminSections.parcelsList;
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><div style="font-weight:800;font-size:14px;"><i class="fa-solid fa-list"></i> Tous les colis (' + state.externalParcels.length + ')</div><button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="parcelsList"><i class="fa-solid ' + (parcelsCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button></div>';
  if (state.externalParcels.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim);">Aucun colis externe enregistré pour l\'instant.</div>';
  } else if (!parcelsCollapsed) {
    if (state.externalParcels.length > 8) html += '<input class="input" style="margin-bottom:10px;" placeholder="Rechercher (n° suivi, destinataire, plateforme)…" value="' + esc(state.adminParcelsSearch || "") + '" data-action-input="admin-parcels-search" />';
    var parcelsSearch = (state.adminParcelsSearch || "").toLowerCase().trim();
    var parcelsToShow = state.externalParcels;
    if (parcelsSearch) {
      parcelsToShow = state.externalParcels.filter(function(p) {
        return (p.trackingNumber || "").toLowerCase().indexOf(parcelsSearch) !== -1 ||
          (p.recipientName || "").toLowerCase().indexOf(parcelsSearch) !== -1 ||
          (p.platform || "").toLowerCase().indexOf(parcelsSearch) !== -1;
      });
    }
    for (var i = 0; i < parcelsToShow.length && i < 40; i++) {
      var p = parcelsToShow[i];
      html += '<div style="background:var(--bg-body);border-radius:10px;padding:10px;margin-bottom:8px;">';
      html += '<div style="display:flex;justify-content:space-between;"><span style="font-weight:700;font-size:12.5px;">' + esc(p.trackingNumber) + ' — ' + esc(p.platform) + '</span><span class="status-pill">' + translateStatus(p.status) + '</span></div>';
      html += '<div style="font-size:11px;color:var(--text-dim);margin-top:2px;">' + esc(p.recipientName) + ' · ' + esc(p.relaisShopName) + '</div>';
      html += '<div style="display:flex;gap:8px;margin-top:8px;">';
      html += '<button class="link-btn" style="font-size:11px;" data-action="set-admin-parcel-detail" data-value="' + p.id + '"><i class="fa-solid fa-eye"></i> Détail</button>';
      html += '<button class="link-btn" style="font-size:11px;" data-action="' + (isOwner ? "admin-edit-external-parcel" : "request-edit-external-parcel") + '" data-value="' + p.id + '"><i class="fa-solid fa-pen"></i> ' + (isOwner ? "Modifier" : "Demander une modification") + '</button>';
      html += '<button class="link-btn" style="font-size:11px;color:var(--danger);" data-action="' + (isOwner ? "admin-delete-external-parcel" : "request-delete-external-parcel") + '" data-value="' + p.id + '"><i class="fa-solid fa-trash"></i> ' + (isOwner ? "Supprimer" : "Demander la suppression") + '</button>';
      html += '</div></div>';
    }
  }
  html += '</div>';
  return html;
}

function renderExternalParcelFormSection() {
  var approvedRelais = state.accounts.filter(function(a) { return a.relaisApplicationStatus === "approved"; });
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  if (!state.adminExternalParcelForm) {
    html += '<button class="btn-primary" style="width:100%;" data-action="open-admin-parcel-form"><i class="fa-solid fa-plus"></i> ' + (state.adminExternalParcelEditId ? "Continuer la modification" : "Créer un colis externe") + '</button>';
    html += '</div>';
    return html;
  }
  var d = state.externalParcelDraft || { trackingNumber: "", platform: "Alibaba", recipientName: "", recipientPhone: "", description: "", relaisShopId: "" };
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:10px;">' + (state.adminExternalParcelEditId ? "Modifier le colis" : "Nouveau colis externe") + '</div>';
  html += '<label class="field-label" style="margin-top:0;">Numéro de suivi</label>';
  html += '<div style="display:flex;gap:8px;">';
  html += '<input class="input" id="admin-parcel-tracking-input" value="' + esc(d.trackingNumber) + '" placeholder="Ex : LP123456789CN" data-bind="externalParcelDraft.trackingNumber" style="flex:1;" />';
  html += '<button class="btn-secondary" style="flex:0;padding:8px 12px;" data-action="open-scanner" data-target="admin-parcel-tracking-input"><i class="fa-solid fa-qrcode"></i></button>';
  html += '</div>';
  html += '<label class="field-label">Plateforme d\'origine</label>';
  html += '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
  ["Alibaba", "Amazon", "Autre"].forEach(function(pf) {
    html += '<button class="chip ' + (d.platform === pf ? 'active' : '') + '" data-action="set-parcel-platform" data-value="' + pf + '">' + pf + '</button>';
  });
  html += '</div>';
  html += '<label class="field-label">Point de Retrait de destination</label>';
  html += '<select class="input" data-bind="externalParcelDraft.relaisShopId">';
  html += '<option value="">Choisir…</option>';
  approvedRelais.forEach(function(r) {
    html += '<option value="' + r.id + '" ' + (d.relaisShopId === r.id ? 'selected' : '') + '>' + esc(r.shopName || r.name) + '</option>';
  });
  html += '</select>';
  if (approvedRelais.length === 0) html += '<div style="font-size:10.5px;color:var(--danger);margin-top:4px;">Aucun Point de Retrait approuvé pour l\'instant.</div>';
  html += '<label class="field-label">Nom du destinataire</label>';
  html += '<input class="input" value="' + esc(d.recipientName) + '" placeholder="Ex : Aïcha Coulibaly" data-bind="externalParcelDraft.recipientName" />';
  html += '<label class="field-label">Téléphone du destinataire</label>';
  html += '<input class="input" value="' + esc(d.recipientPhone) + '" placeholder="Ex : 70000000" data-bind="externalParcelDraft.recipientPhone" />';
  html += '<label class="field-label">Description (optionnel)</label>';
  html += '<input class="input" value="' + esc(d.description || '') + '" placeholder="Ex : Vêtements" data-bind="externalParcelDraft.description" />';
  html += '<button class="btn-primary" style="margin-top:14px;" data-action="submit-admin-external-parcel">' + (state.adminExternalParcelEditId ? "Enregistrer les modifications" : "Créer le colis") + '</button>';
  html += '<button class="link-btn" style="margin-top:8px;width:100%;text-align:center;" data-action="cancel-admin-parcel-form">' + t("cancel_generic") + '</button>';
  html += '</div>';
  return html;
}

function renderAdminExternalIntegration() {
  var html = '';
  html += renderWebhookPartnersSection();
  html += renderDashboardPartnersSection();
  html += renderApiPartnersSection();
  html += renderPlatformCommissionsSection();

  html += '<div class="glass-card" style="padding:14px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:8px;"><i class="fa-solid fa-box-open"></i> Colis externes enregistrés (' + state.externalParcels.length + ')</div>';
  if (state.externalParcels.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim);">Aucun colis externe enregistré pour l\'instant.</div>';
  } else {
    for (var i = 0; i < state.externalParcels.length && i < 30; i++) {
      var p = state.externalParcels[i];
      html += '<div class="card-row" style="cursor:pointer;" data-action="open-external-parcel-admin-detail" data-value="' + p.id + '">';
      html += '<div style="flex:1;min-width:0;"><div style="font-weight:700;font-size:12px;">' + esc(p.trackingNumber) + ' — ' + esc(p.platform) + '</div><div style="font-size:10.5px;color:var(--text-dim);">' + esc(p.recipientName) + ' · ' + esc(p.relaisShopName) + '</div></div>';
      html += '<span class="status-pill">' + translateStatus(p.status) + '</span>';
      html += '</div>';
    }
  }
  html += '</div>';
  return html;
}

function renderWebhookPartnersSection() {
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-plug"></i> Webhooks partenaires (' + state.webhookPartners.length + ')</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:12px;">Chaque partenaire a sa propre adresse — seuls ses colis à lui déclenchent un envoi vers son adresse, jamais mélangés avec un autre.</div>';
  for (var i = 0; i < state.webhookPartners.length; i++) {
    var w = state.webhookPartners[i];
    html += '<div style="background:var(--bg-body);border-radius:10px;padding:10px;margin-bottom:8px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">';
    html += '<div style="font-weight:800;font-size:12.5px;">' + esc(w.platform) + '</div>';
    html += '<div style="display:flex;gap:8px;align-items:center;"><div class="toggle-switch ' + (w.enabled ? 'active' : '') + '" data-action="toggle-webhook-partner" data-value="' + w.id + '"><div class="toggle-knob"></div></div><button class="link-btn" style="color:var(--danger);padding:2px;" data-action="remove-webhook-partner" data-value="' + w.id + '"><i class="fa-solid fa-trash"></i></button></div>';
    html += '</div>';
    html += '<input class="input" id="webhook-url-' + w.id + '" placeholder="https://partenaire.exemple.com/webhook" value="' + esc(w.url) + '" data-action-input="webhook-partner-url" data-config="' + w.id + '" style="margin-bottom:6px;" />';
    html += '<div style="position:relative;"><input class="input" id="webhook-token-' + w.id + '" type="password" style="padding-right:44px;" placeholder="🔒 Protégé — tapez pour remplacer (optionnel)" value="" data-action-input="webhook-partner-token" data-config="' + w.id + '" /><button type="button" class="pw-eye-btn" data-action="reveal-partner-secret" data-value="' + w.id + '" data-secret-type="authToken" style="position:absolute;right:6px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--text-dim);padding:8px;" title="Voir le jeton"><i class="fa-solid fa-eye"></i></button></div>';
    html += '<button class="btn-secondary" style="margin-top:8px;width:100%;font-size:12px;padding:6px;" data-action="test-webhook-partner" data-value="' + w.id + '"><i class="fa-solid fa-vial"></i> Envoyer un test</button>';
    if (w.lastTestResult) html += '<div style="font-size:10.5px;margin-top:6px;color:' + (w.lastTestResult === "success" ? "#2e9e4f" : "var(--danger)") + ';">' + (w.lastTestResult === "success" ? "✅ Test envoyé." : "❌ Échec.") + '</div>';
    html += '</div>';
  }
  html += '<button class="btn-primary" style="width:100%;" data-action="add-webhook-partner"><i class="fa-solid fa-plus"></i> Ajouter un partenaire webhook</button>';
  html += '</div>';
  return html;
}

function renderDashboardPartnersSection() {
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-table-columns"></i> Tableaux de bord partagés (' + state.dashboardPartners.length + ')</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:12px;">Chaque partenaire a ses propres identifiants et ne voit jamais que ses propres colis — rien ne se mélange entre partenaires.</div>';
  for (var i = 0; i < state.dashboardPartners.length; i++) {
    var d = state.dashboardPartners[i];
    html += '<div style="background:var(--bg-body);border-radius:10px;padding:10px;margin-bottom:8px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">';
    html += '<div style="font-weight:800;font-size:12.5px;">' + esc(d.platform) + '</div>';
    html += '<div style="display:flex;gap:8px;align-items:center;"><div class="toggle-switch ' + (d.enabled ? 'active' : '') + '" data-action="toggle-dashboard-partner" data-value="' + d.id + '"><div class="toggle-knob"></div></div><button class="link-btn" style="color:var(--danger);padding:2px;" data-action="remove-dashboard-partner" data-value="' + d.id + '"><i class="fa-solid fa-trash"></i></button></div>';
    html += '</div>';
    html += '<input class="input" id="dash-user-' + d.id + '" placeholder="Nom d\'utilisateur" value="' + esc(d.username) + '" data-action-input="dashboard-partner-username" data-config="' + d.id + '" style="margin-bottom:6px;" />';
    html += '<div style="position:relative;"><input class="input" id="dash-pass-' + d.id + '" type="password" style="padding-right:44px;" placeholder="🔒 Protégé — tapez pour remplacer" value="" data-action-input="dashboard-partner-password" data-config="' + d.id + '" /><button type="button" class="pw-eye-btn" data-action="toggle-pw-visibility" style="position:absolute;right:6px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--text-dim);padding:8px;"><i class="fa-solid fa-eye"></i></button></div>';
    if (d.enabled && d.username) {
      html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:8px;background:var(--bg-card);padding:6px;border-radius:6px;word-break:break-all;">Lien : ' + PUBLIC_SITE_URL + '/#partner-dashboard</div>';
    }
    html += '</div>';
  }
  html += '<button class="btn-primary" style="width:100%;" data-action="add-dashboard-partner"><i class="fa-solid fa-plus"></i> Ajouter un partenaire</button>';
  html += '</div>';
  return html;
}

function renderApiPartnersSection() {
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-code"></i> API à interroger (' + state.apiPartners.length + ')</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:12px;">Chaque partenaire a sa propre clé — impossible pour l\'un de consulter les colis d\'un autre, même avec un numéro de suivi deviné.</div>';
  for (var i = 0; i < state.apiPartners.length; i++) {
    var a = state.apiPartners[i];
    html += '<div style="background:var(--bg-body);border-radius:10px;padding:10px;margin-bottom:8px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">';
    html += '<div style="font-weight:800;font-size:12.5px;">' + esc(a.platform) + '</div>';
    html += '<div style="display:flex;gap:8px;align-items:center;"><div class="toggle-switch ' + (a.enabled ? 'active' : '') + '" data-action="toggle-api-partner" data-value="' + a.id + '"><div class="toggle-knob"></div></div><button class="link-btn" style="color:var(--danger);padding:2px;" data-action="remove-api-partner" data-value="' + a.id + '"><i class="fa-solid fa-trash"></i></button></div>';
    html += '</div>';
    html += '<div style="display:flex;gap:8px;">';
    html += '<input class="input" id="api-key-' + a.id + '" placeholder="🔒 Protégé — tapez pour remplacer" value="" data-action-input="api-partner-key" data-config="' + a.id + '" style="flex:1;" />';
    html += '<button class="btn-secondary" style="flex:0;padding:8px 12px;" data-action="reveal-partner-secret" data-value="' + a.id + '" data-secret-type="apiKey" title="Voir la clé"><i class="fa-solid fa-eye"></i></button>';
    html += '<button class="btn-secondary" style="flex:0;padding:8px 12px;" data-action="regenerate-api-partner-key" data-value="' + a.id + '"><i class="fa-solid fa-arrows-rotate"></i></button>';
    html += '</div>';
    if (a.enabled && a.hasApiKey) {
      html += '<div style="font-size:10.5px;color:var(--text-dim);margin-top:8px;background:var(--bg-card);padding:6px;border-radius:6px;">Appuyez sur 👁 pour voir le lien complet avec la clé, à donner au partenaire.</div>';
    }
    html += '</div>';
  }
  html += '<button class="btn-primary" style="width:100%;" data-action="add-api-partner"><i class="fa-solid fa-plus"></i> Ajouter un partenaire</button>';
  html += '</div>';
  return html;
}

function renderPlatformCommissionsSection() {
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:16px;">';
  html += '<div style="font-weight:800;font-size:14px;margin-bottom:6px;"><i class="fa-solid fa-sack-dollar"></i> Commission Point de Retrait (' + state.platformCommissions.length + ')</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:12px;">Un montant fixe par colis reçu, réglable pour chaque plateforme séparément — rien n\'est versé tant que ce n\'est pas activé, prêt pour le jour où un accord réel sera signé.</div>';
  for (var i = 0; i < state.platformCommissions.length; i++) {
    var c = state.platformCommissions[i];
    html += '<div style="background:var(--bg-body);border-radius:10px;padding:10px;margin-bottom:8px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">';
    html += '<div style="font-weight:800;font-size:12.5px;">' + esc(c.platform) + '</div>';
    html += '<div style="display:flex;gap:8px;align-items:center;"><div class="toggle-switch ' + (c.enabled ? 'active' : '') + '" data-action="toggle-platform-commission" data-value="' + c.id + '"><div class="toggle-knob"></div></div><button class="link-btn" style="color:var(--danger);padding:2px;" data-action="remove-platform-commission" data-value="' + c.id + '"><i class="fa-solid fa-trash"></i></button></div>';
    html += '</div>';
    html += '<label class="field-label" style="margin-top:0;">Montant par colis (FCFA)</label>';
    html += '<input class="input" id="commission-amount-' + c.id + '" type="number" placeholder="Ex : 300" value="' + (c.amount || '') + '" data-action-input="platform-commission-amount" data-config="' + c.id + '" />';
    if (c.enabled && c.amount > 0) {
      html += '<div style="font-size:10.5px;color:#2e9e4f;margin-top:6px;">✅ Actif — le Point de Retrait voit ' + money(c.amount) + ' sur chaque colis ' + esc(c.platform) + '.</div>';
    }
    html += '</div>';
  }
  html += '<button class="btn-primary" style="width:100%;" data-action="add-platform-commission"><i class="fa-solid fa-plus"></i> Ajouter une plateforme</button>';
  html += '</div>';
  return html;
}

function renderAdminAffiliation() {
  var stats = computeAdminStats();
  var cfgAdmin = getCommissionConfig();
  var totalRate = cfgAdmin.totalCommissionRate;
  var affRate = cfgAdmin.affiliateCommission;
  var platformKeep = Math.max(0, totalRate - affRate);
  var html = '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;box-shadow:var(--shadow);margin-bottom:16px;">';
  html += '<div style="font-weight:700;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-hand-holding-dollar"></i> Paramètres de commission & parrainage</div>';
  html += '<label class="field-label" style="margin-top:0;">Commission totale (%) — prélevée sur chaque vente</label>';
  html += '<input class="input" type="number" id="total-commission-rate-input" value="' + (totalRate * 100) + '" min="0" max="100" step="0.5" />';
  html += '<label class="field-label">Part du parrain (%) — sur les ventes parrainées uniquement</label>';
  html += '<input class="input" type="number" id="affiliate-rate-input" value="' + (affRate * 100) + '" min="0" max="100" step="0.5" />';
  html += '<button class="btn-primary" style="margin-top:10px;" data-action="save-affiliate-rate"><i class="fa-solid fa-save"></i> Enregistrer</button>';
  html += '<div class="divider-dashed" style="margin:16px 0;"></div>';
  html += '<label class="field-label" style="margin-top:0;">Comment la commission s\'applique</label>';
  html += '<div style="display:flex;gap:10px;align-items:flex-start;background:var(--bg-body);border-radius:10px;padding:10px 12px;">';
  html += '<div class="toggle-switch ' + (cfgAdmin.commissionMode === "add" ? 'active' : '') + '" data-action="toggle-commission-mode"><div class="toggle-knob"></div></div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);">' + (cfgAdmin.commissionMode === "add"
    ? '<strong style="color:var(--text-primary);">Ajoutée au prix affiché.</strong> Le vendeur saisit le montant qu\'il veut recevoir net — la commission s\'ajoute par-dessus pour l\'acheteur, et le vendeur reçoit l\'intégralité de son prix demandé.'
    : '<strong style="color:var(--text-primary);">Retirée du prix affiché (par défaut).</strong> Le vendeur fixe un prix, l\'acheteur le paie tel quel, le vendeur reçoit (prix − commission).') + '</div>';
  html += '</div>';
  html += '<div style="margin-top:6px;font-size:10.5px;color:var(--text-dim);"><i class="fa-solid fa-triangle-exclamation"></i> Ne change rien aux commandes déjà passées — seulement les nouvelles publications et ventes à venir.</div>';
  html += '<div style="margin-top:12px;font-size:11.5px;color:var(--text-dim);background:var(--bg-body);padding:10px 12px;border-radius:10px;">';
  html += '<div>Sans parrainage : vous gardez <strong>' + (totalRate * 100).toFixed(1) + '%</strong></div>';
  html += '<div>Avec parrainage : le parrain reçoit <strong>' + (affRate * 100).toFixed(1) + '%</strong>, vous gardez <strong>' + (platformKeep * 100).toFixed(1) + '%</strong></div>';
  html += '</div>';
  html += '<div style="margin-top:12px;font-size:12px;color:var(--text-dim);">';
  html += '<div>💰 Total commissions de parrainage versées : <strong>' + money(stats.affiliateTotal || 0) + '</strong></div>';
  html += '<div>👥 Nombre total de parrainages : <strong>' + stats.affiliateReferrals + '</strong></div>';
  html += '</div>';
  html += '<div style="margin-top:10px;font-size:11px;color:var(--text-dim);"><i class="fa-solid fa-circle-info"></i> Le détail des gains par compte et des commissions accumulées se trouve maintenant dans le Tableau de bord.</div>';
  html += '</div>';
  return html;
}

function renderAdminReviews() {
  var allReviews = state.reviews;
  if (allReviews.length === 0) {
    return '<div class="empty-state"><i class="fa-solid fa-star"></i><div class="title">Aucun avis</div></div>';
  }
  var reviewsSearch = (state.adminReviewsSearch || "").toLowerCase().trim();
  var filteredReviews = allReviews;
  if (reviewsSearch) {
    filteredReviews = allReviews.filter(function(r) {
      var prod = state.products.find(function(p) { return p.id === r.productId; });
      return (r.userName || "").toLowerCase().indexOf(reviewsSearch) !== -1 ||
        (r.comment || "").toLowerCase().indexOf(reviewsSearch) !== -1 ||
        (prod && prod.name.toLowerCase().indexOf(reviewsSearch) !== -1);
    });
  }
  var reviewsCollapsed = !!state.collapsedAdminSections.reviewsList;
  var html = '<div style="background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius);padding:14px;box-shadow:var(--shadow);">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">';
  html += '<div style="font-weight:700;font-size:14px;">Tous les avis (' + filteredReviews.length + ')</div>';
  html += '<button class="link-btn" style="padding:6px;" data-action="toggle-admin-section" data-value="reviewsList"><i class="fa-solid ' + (reviewsCollapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button>';
  html += '</div>';
  html += '<input class="input" style="margin-bottom:12px;" placeholder="Rechercher (client, produit, texte de l\'avis)…" value="' + esc(state.adminReviewsSearch || "") + '" data-action-input="admin-reviews-search" />';
  if (!reviewsCollapsed) {
    var toShow = filteredReviews.slice(0, 20);
    for (var i = 0; i < toShow.length; i++) {
    var r = toShow[i];
    var product = null;
    for (var j = 0; j < state.products.length; j++) {
      if (state.products[j].id === r.productId) { product = state.products[j]; break; }
    }
    html += '<div class="review-item">';
    html += '<div class="review-header"><div><span class="reviewer-name">' + esc(r.userName) + '</span>';
    if (r.verified) html += '<span class="review-verified">✓ Avis vérifié</span>';
    html += '</div><span class="review-date">' + new Date(r.createdAt).toLocaleDateString('fr-FR') + '</span></div>';
    html += '<div class="review-stars">' + '⭐'.repeat(r.rating) + '☆'.repeat(5-r.rating) + '</div>';
    if (product) html += '<div style="font-size:11px;color:var(--text-dim);cursor:pointer;" data-action="admin-edit-product" data-value="' + product.id + '">Produit : <span style="text-decoration:underline;">' + esc(product.name) + '</span></div>';
    html += '<div class="review-text">' + esc(r.comment) + '</div>';
    html += '<button class="link-btn" style="color:var(--danger);font-size:11px;margin-top:6px;" data-action="admin-delete-review" data-value="' + r.id + '"><i class="fa-solid fa-trash"></i> Supprimer cet avis</button>';
    html += '</div>';
    }
  }
  html += '</div>';
  return html;
}

// ---------- RENDER PRODUCT MODAL ----------
// Affiche à l'acheteur les caractéristiques propres au secteur/catégorie
// du produit (temps de préparation pour un plat, matériau pour un bijou…)
// — champs capturés à la publication mais jamais montrés jusqu'ici.
var SECTOR_FIELD_LABELS = {
  tempsPreparation: "Temps de préparation", ingredients: "Ingrédients / Allergènes", disponibleAujourdhui: "Disponible aujourd'hui",
  provenance: "Provenance", dureeFormation: "Durée de la formation", niveauRequis: "Niveau requis",
  diplomeDelivre: "Diplôme délivré", modeFormation: "Mode", prochaineRentree: "Prochaine rentrée",
  dureeActe: "Durée de l'acte", surRendezVous: "Sur rendez-vous", dureeSoin: "Durée du soin",
  serviceADomicile: "Service à domicile", typeServiceAuto: "Type de service", delaiIntervention: "Délai d'intervention",
  garantie: "Garantie", capacite: "Capacité", petitDejeuner: "Petit-déjeuner inclus",
  materiau: "Matériau", poidsBijou: "Poids", contenance: "Contenance", typePeauUsage: "Type de peau / Usage",
  ingredientsCosmetique: "Ingrédients principaux", datePeremption: "Date de péremption",
  marqueElectro: "Marque", modeleElectro: "Modèle", etatElectro: "État", garantieElectro: "Garantie",
  specsElectro: "Spécifications", puissanceElectro: "Puissance / Capacité",
  quantitePoidsAgri: "Quantité / Poids disponible", uniteVenteAgri: "Unité de vente",
  saisonRecolte: "Saison de récolte", fraicheurAgri: "Fraîcheur", etatFraicheur: "Frais ou Sec",
  marqueAuto: "Marque / Modèle", modeleAuto: "Modèle", anneeAuto: "Année", etatAuto: "État", kilometrageAuto: "Kilométrage",
  matiereMode: "Matière", occasionMode: "Occasion", etatMode: "État", genreEnfant: "Genre", ageRecommande: "Âge recommandé",
  typeChaussure: "Type", matiereChaussure: "Matière", etatChaussure: "État",
  typeSolaire: "Type", puissanceSolaire: "Puissance", autonomieSolaire: "Autonomie", garantieSolaire: "Garantie",
  matiereMaison: "Matière", dimensionsMaison: "Dimensions", styleMaison: "Style",
  matiereCuisine: "Matière", nbPiecesCuisine: "Nombre de pièces",
  origineAlim: "Provenance", ingredientsAlim: "Ingrédients / Composition",
  typeBoisson: "Type", contientAlcool: "Contient de l'alcool",
  typeOutil: "Type d'outil", alimentationOutil: "Alimentation", etatOutil: "État", garantieOutil: "Garantie",
  typeActiviteSport: "Activité concernée", etatSport: "État",
  matiereArtisanat: "Matière", origineArtisanat: "Origine / Région", faitMainArtisanat: "Fait main",
  typeProduitSante: "Type de produit", usagePosologieSante: "Usage / Posologie",
  typeBureautique: "Type", etatBureautique: "État",
  typePrestationDeco: "Type de prestation", delaiPreparationDeco: "Délai de préparation",
  typeEvenement: "Type d'événement", capaciteEvenement: "Capacité (invités)",
  digitalAuthor: "Auteur / Créateur", digitalLanguage: "Langue", digitalLength: "Taille / Durée", digitalFormat: "Format",
  digitalLevel: "Niveau", digitalPlatform: "Plateforme", digitalVersion: "Version", digitalLicense: "Licence"
};
function getSectorFieldLabel(f) {
  var key = "sfield_" + f;
  return t(key) !== key ? t(key) : (SECTOR_FIELD_LABELS[f] || f);
}

function renderProductSectorDetails(p) {
  // Ne garde que les champs qui appartiennent VRAIMENT au type de vendeur /
  // secteur / catégorie de CET article — même pour les articles publiés
  // avant ce correctif, dont les anciennes données traînent encore avec des
  // champs hors sujet (ex: "Fait main" sur un champignon).
  var relevantFields = getRelevantSectorFields(p.sellerType, p.sellerSector, p.category);
  var present = relevantFields.filter(function(f) { return p[f] !== undefined && p[f] !== null && p[f] !== "" && SECTOR_FIELD_LABELS[f]; });
  if (present.length === 0) return '';
  var html = '<div class="glass-card" style="padding:12px;margin-top:10px;">';
  html += '<div style="font-weight:800;font-size:12.5px;margin-bottom:8px;">' + t("pd_characteristics") + '</div>';
  for (var i = 0; i < present.length; i++) {
    var f = present[i];
    html += '<div style="display:flex;justify-content:space-between;font-size:12px;padding:4px 0;border-bottom:1px solid var(--border-color);"><span style="color:var(--text-dim);">' + getSectorFieldLabel(f) + '</span><span style="font-weight:600;text-align:right;">' + esc(String(productDisplayField(p, f))) + '</span></div>';
  }
  html += '</div>';
  return html;
}

// Limite la part d'articles sponsorisés dans une liste — les non
// sponsorisés remplissent en priorité. Si peu de non-sponsorisés
// existent, la liste finale est plus courte plutôt que de combler avec
// des sponsorisés au-delà du ratio autorisé — mieux vaut une section
// plus courte et honnête qu'une section pleine mais artificiellement
// gonflée de publicité.
function capBoostedShare(candidates, limit, maxRatio) {
  var nonBoosted = [], boosted = [];
  for (var i = 0; i < candidates.length; i++) {
    if (isProductBoosted(candidates[i])) boosted.push(candidates[i]); else nonBoosted.push(candidates[i]);
  }
  // On réserve d'abord une vraie place aux non-sponsorisés (75% de la
  // limite par défaut), puis on complète avec des sponsorisés dans la
  // part restante — ainsi, les sponsors gardent une vraie visibilité
  // garantie quand il y a assez de contenu, sans jamais dominer la
  // section quand le contenu organique vient à manquer.
  var targetNonBoosted = Math.ceil(limit * (1 - maxRatio));
  var keptNonBoosted = nonBoosted.slice(0, targetNonBoosted);
  // S'il n'y a AUCUN article non sponsorisé pour ce contexte, le calcul
  // de ratio tombe à zéro par construction (0 × n'importe quoi = 0) —
  // ce qui masquait complètement les sponsorisés au lieu de les
  // montrer, alors qu'il n'y a justement rien d'autre à montrer à leur
  // place. Mieux vaut afficher les sponsorisés que rien du tout.
  var maxBoostedAllowed = keptNonBoosted.length > 0
    ? Math.floor(keptNonBoosted.length * maxRatio / (1 - maxRatio))
    : Math.min(limit, boosted.length);
  var remainingSlots = limit - keptNonBoosted.length;
  var boostedToAdd = Math.min(maxBoostedAllowed, boosted.length, remainingSlots);
  // Rotation dans le temps (toutes les 5 minutes, même principe que la
  // "découverte" du marché) — sans ça, s'il y a plus de sponsors actifs
  // que de places disponibles, c'était TOUJOURS les mêmes premiers
  // rencontrés dans le tableau qui passaient, et les autres (comme
  // "Drap d'examen" dans le cas rapporté) ne s'affichaient jamais nulle
  // part dans cette section, même actifs et bien chargés.
  var rotationSlot = boosted.length > 0 ? Math.floor(Date.now() / (5 * 60 * 1000)) % boosted.length : 0;
  var rotatedBoosted = boosted.slice(rotationSlot).concat(boosted.slice(0, rotationSlot));
  var result = keptNonBoosted.concat(rotatedBoosted.slice(0, boostedToAdd));
  // S'il reste de la place que les sponsorisés n'ont pas pu combler
  // (pas assez de sponsors actifs), on la remplit avec d'autres
  // non-sponsorisés plutôt que de raccourcir la liste sans raison.
  if (result.length < limit && nonBoosted.length > keptNonBoosted.length) {
    var extra = nonBoosted.slice(keptNonBoosted.length, keptNonBoosted.length + (limit - result.length));
    result = result.concat(extra);
  }
  return result;
}

function renderProductModal() {
  var p = null;
  for (var i = 0; i < state.products.length; i++) {
    if (state.products[i].id === state.detailProductId) {
      p = state.products[i];
      break;
    }
  }
  if (!p) return '';
  var isFreshOpen = modalWasOpenFor !== state.detailProductId;
  modalWasOpenFor = state.detailProductId;
  var waMsg = encodeURIComponent('Bonjour, je suis intéressé(e) par "' + p.name + '" (' + money(p.price) + ') vu sur Sounsouni.');
  var waLink = 'https://wa.me/' + p.sellerPhone.replace(/\D/g, '') + '?text=' + waMsg;
  var hasImages = p.images && p.images.length > 0;
  var mainImage = hasImages ? p.images[Math.min(state.activeImageIndex, p.images.length - 1)] : null;
  var avgRating = getProductAverageRating(p.id);
  var reviews = getProductReviews(p.id);
  var tieredPrice = getTieredPrice(p, state.selectedQty, state.selectedColor || null);
  var tieredTotal = getTieredTotal(p, state.selectedQty);
  
  var html = '<div class="modal-overlay ' + (isFreshOpen ? '' : 'no-anim') + '" id="modal-overlay" data-action="close-product">';
  html += '<div class="modal-sheet ' + (isFreshOpen ? '' : 'no-anim') + '">';
  html += '<button class="modal-close" data-action="close-product"><i class="fa-solid fa-xmark"></i></button>';
  html += '<button class="modal-close" style="right:56px" data-action="share-product" data-value="' + p.id + '"><i class="fa-solid fa-share-nodes"></i></button>';
  html += '<div class="pd-layout"><div class="pd-media">';
  html += '<div class="modal-image swipeable-carousel" data-action="open-lightbox" data-value="' + p.id + '" data-index="' + state.activeImageIndex + '">';
  if (hasImages && p.images.length > 1) {
    html += '<div class="carousel-track" style="transform:translateX(-' + (state.activeImageIndex * 100) + '%);">';
    for (var pmi = 0; pmi < p.images.length; pmi++) {
      html += '<div style="position:relative;width:100%;height:100%;flex-shrink:0;overflow:hidden;">';
      html += '<img loading="lazy" class="product-image-backdrop" src="' + p.images[pmi] + '" alt="" aria-hidden="true" />';
      html += '<img loading="lazy" src="' + p.images[pmi] + '" alt="' + esc(p.name) + '" />';
      html += '</div>';
    }
    html += '</div>';
    html += '<div class="carousel-dots">';
    for (var pmdi = 0; pmdi < p.images.length; pmdi++) {
      html += '<span class="' + (pmdi === state.activeImageIndex ? 'active' : '') + '"></span>';
    }
    html += '</div>';
  } else if (mainImage) {
    html += '<img loading="lazy" class="product-image-backdrop" src="' + mainImage + '" alt="" aria-hidden="true" />';
    html += '<img loading="lazy" src="' + mainImage + '" alt="' + esc(p.name) + '" />';
  } else {
    html += p.emoji;
  }
  if (hasImages) {
    html += '<span class="click-hint">👆 Cliquez pour agrandir</span>';
  }
  html += '</div>';
  if (hasImages && p.images.length > 1) {
    html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 0;">';
    for (var k = 0; k < p.images.length; k++) {
      var img = p.images[k];
      html += '<div style="width:50px;height:50px;border-radius:8px;overflow:hidden;border:1.5px solid ' + (k === state.activeImageIndex ? 'var(--accent)' : 'var(--border-color)') + ';cursor:pointer;flex-shrink:0;" data-action="set-active-image" data-value="' + k + '">';
      html += '<img loading="lazy" ' + snsThumbSrc(img) + ' alt="" style="width:100%;height:100%;object-fit:cover;" />';
      html += '</div>';
    }
    html += '</div>';
  }
  if (p.video) {
    html += '<div style="margin-top:12px;"><div class="field-label" style="margin:10px 0 6px;"><i class="fa-solid fa-video"></i> Vidéo</div><video id="product-detail-video" data-src="' + esc(p.video) + '" src="' + p.video + '" preload="none"' + ((p.images && p.images[0]) ? ' poster="' + snsThumb(p.images[0]) + '"' : '') + ' controls playsinline style="width:100%;border-radius:14px;"></video></div>';
  }
  html += '</div><div class="pd-buybox">';
  html += '<div class="product-shop" style="margin:14px 0 4px;"><i class="fa-solid fa-store"></i> ' + esc(p.shopName) + (p.shopName !== p.sellerName ? ' — ' + esc(p.sellerName) : '') + '</div>';
  html += '<div style="font-size:11px;color:var(--text-dim);margin-bottom:8px;"><i class="fa-solid fa-clock"></i> ' + t("pd_published_prefix") + ' ' + (relativeTimeAgo(p.createdAt) === "Aujourd\'hui" ? t("pd_published_today") : relativeTimeAgo(p.createdAt).toLowerCase()) + '</div>';
  html += '<button class="link-btn" style="font-size:11.5px;margin-bottom:8px;" data-action="view-seller-shop" data-value="' + p.sellerId + '"><i class="fa-solid fa-shop"></i> ' + t("pd_view_shop") + '</button>';
  var sellerRep = computeSellerReputation(p.sellerId);
  if (sellerRep.totalOrders >= 3) {
    html += '<div class="reputation-badge"><i class="fa-solid fa-shield-heart"></i> ' + repLabelText(sellerRep.label) + ' — ' + sellerRep.stars.toFixed(1) + '/5</div>';
  }
  html += '<div style="font-size:21px;font-weight:800;margin-bottom:4px;">' + esc(productDisplayName(p)) + '</div>';
  if (p.sku) {
    html += '<div style="font-size:11px;color:var(--text-dim);font-family:monospace;margin-bottom:8px;">Réf. ' + esc(p.sku) + '</div>';
  }
  html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">';
  if (avgRating > 0) {
    html += '<span style="color:#f5a623;font-weight:700;">⭐ ' + avgRating.toFixed(1) + '</span><span style="color:var(--text-dim);font-size:12px;">(' + reviews.length + ' avis)</span>';
  } else {
    html += '<span style="display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:700;color:var(--text-dim);background:var(--bg-body);border:1px solid var(--border-color);padding:4px 10px;border-radius:999px;"><i class="fa-regular fa-star"></i> ' + t("pd_no_reviews_yet") + '</span>';
  }
  html += '</div>';
  var pdSellerAcc = state.accounts.find(function(a) { return a.id === p.sellerId; });
  var pdVerified = !!(pdSellerAcc && pdSellerAcc.verified);
  var pdMcfg = getMarketConfig();
  var pdIsNew = pdMcfg.showNewTag && (p.createdAt || 0) >= (Date.now() - newArrivalsDurationMs(pdMcfg));
  if (pdVerified || pdIsNew) {
    html += '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;">';
    if (pdVerified) {
      html += '<span style="display:inline-flex;align-items:center;gap:5px;font-size:11.5px;font-weight:700;color:#2e9e4f;background:rgba(46,158,79,0.1);padding:4px 10px;border-radius:999px;"><i class="fa-solid fa-circle-check"></i> ' + t("pd_verified_account") + '</span>';
    }
    if (pdIsNew) {
      html += '<span class="na-tag na-tag-new" style="font-size:10.5px;padding:3px 9px;">' + t("new_badge") + '</span>';
    }
    html += '</div>';
  }
  var pdLikes = Array.isArray(p.likedBy) ? p.likedBy.length : 0;
  var pdDislikes = Array.isArray(p.dislikedBy) ? p.dislikedBy.length : 0;
  var pdMyLike = state.profile && Array.isArray(p.likedBy) && p.likedBy.indexOf(state.profile.id) !== -1;
  var pdMyDislike = state.profile && Array.isArray(p.dislikedBy) && p.dislikedBy.indexOf(state.profile.id) !== -1;
  html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap;">';
  html += '<button type="button" class="btn-secondary" style="padding:7px 12px;font-size:12px;flex:1;min-width:0;white-space:nowrap;' + (pdMyLike ? 'border-color:#2e9e4f;color:#2e9e4f;' : '') + '" data-action="vote-like-product" data-value="' + p.id + '"><i class="fa-solid fa-thumbs-up"></i> ' + t("pd_like") + (pdLikes > 0 ? ' (' + pdLikes + ')' : '') + '</button>';
  html += '<button type="button" class="btn-secondary" style="padding:7px 12px;font-size:12px;flex:1;min-width:0;white-space:nowrap;' + (pdMyDislike ? 'border-color:var(--danger);color:var(--danger);' : '') + '" data-action="vote-dislike-product" data-value="' + p.id + '"><i class="fa-solid fa-thumbs-down"></i> ' + t("pd_dislike") + (pdDislikes > 0 ? ' (' + pdDislikes + ')' : '') + '</button>';
  html += '</div>';
  html += '<p style="color:var(--text-secondary);font-size:14px;line-height:1.5;margin-top:10px;">' + esc(productDisplayDescription(p)) + '</p>';
  html += renderProductSectorDetails(p);
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin:16px 0;">';
  html += '<span style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;">';
  html += '<span style="font-size:22px;font-weight:800;color:var(--accent);">' + money(tieredPrice, p.country, state.profile ? state.profile.country : null) + '</span>';
  if (p.oldPrice && p.oldPrice > tieredPrice) {
    html += '<span class="price-old" style="font-size:13px;">' + money(p.oldPrice, p.country, state.profile ? state.profile.country : null) + '</span>';
  }
  var disc = discountPercent(p);
  if (disc) {
    html += '<span class="discount-corner" style="position:static;background:var(--danger);color:white;font-size:11px;font-weight:800;padding:3px 8px;border-radius:8px;">-' + disc + '%</span>';
  }
  html += '</span>';
  if (p.stock <= 0) {
    html += '<span class="stock-badge out">' + t("stock_out") + '</span>';
  } else if (p.stock <= 5) {
    html += '<span class="stock-badge low">' + t("stock_low") + ' ' + p.stock + '</span>';
  } else {
    html += '<span class="stock-badge ok">' + t("stock_ok") + '</span>';
  }
  html += '</div>';
  if (p.tieredPricing && p.tieredPricing.length > 0) {
    html += '<div class="tiered-pricing"><div style="font-weight:600;font-size:12px;color:var(--text-dim);margin-bottom:4px;">📊 ' + t("publish_tiered_pricing") + '</div>';
    for (var t2 = 0; t2 < p.tieredPricing.length; t2++) {
      var tier = p.tieredPricing[t2];
      html += '<div class="tier-row"><span class="tier-range">' + tier.minQty + '+ unités</span><span class="tier-price">' + money(tier.price, p.country, state.profile ? state.profile.country : null) + ' / unité</span></div>';
    }
    html += '<div style="font-size:11px;color:var(--text-dim);margin-top:4px;">Prix actuel: ' + money(tieredPrice, p.country, state.profile ? state.profile.country : null) + ' × ' + state.selectedQty + ' = ' + money(tieredTotal, p.country, state.profile ? state.profile.country : null) + '</div></div>';
  }
  if (p.colors && p.colors.length > 0) {
    html += '<label class="field-label">' + t("pd_color") + '</label><div class="option-pills">';
    for (var c = 0; c < p.colors.length; c++) {
      var col = p.colors[c];
      var hex = colorHex(col);
      html += '<button class="option-pill color-pill ' + (state.selectedColor === col ? 'active' : '') + '" data-action="select-color" data-value="' + esc(col) + '">';
      if (hex) html += '<span class="color-dot" style="background:' + hex + '"></span>';
      html += esc(translateColorName(col));
      if (hasColorPrices(p)) html += ' <span style="font-size:10.5px;opacity:0.75;">· ' + money(colorBasePrice(p, col), p.country, state.profile ? state.profile.country : null) + '</span>';
      html += '</button>';
    }
    html += '</div>';
  }
  if (p.sizes && p.sizes.length > 0) {
    html += '<label class="field-label">' + t("pd_size") + '</label><div class="option-pills">';
    for (var s = 0; s < p.sizes.length; s++) {
      var sz = p.sizes[s];
      html += '<button class="option-pill ' + (state.selectedSize === sz ? 'active' : '') + '" data-action="select-size" data-value="' + esc(sz) + '">' + esc(sz) + '</button>';
    }
    html += '</div>';
    if (p.fitNote) {
      html += '<div style="font-size:11.5px;color:var(--text-dim);margin-top:6px;"><i class="fa-solid fa-ruler"></i> ' + esc(p.fitNote) + '</div>';
    }
  }
  if (p.itemType === "service") {
    html += '<div class="glass-card" style="padding:12px;margin:10px 0;">';
    html += '<div style="font-size:11.5px;color:var(--text-dim);"><i class="fa-solid fa-circle-info"></i> ' + t("pd_service_info") + '</div>';
    html += '</div>';
    html += '<label class="field-label">' + t("pd_note_for_seller") + '</label>';
    html += '<textarea class="input" id="booking-note-input" rows="2" placeholder="' + t("pd_note_placeholder") + '"></textarea>';
    html += '<button class="btn-primary" style="margin-top:10px;" data-action="reserve-service" data-value="' + p.id + '" ' + (p.stock <= 0 ? 'disabled' : '') + '><i class="fa-solid fa-calendar-check"></i> ' + t("pd_reserve") + '</button>';
  } else if (isDigitalProduct(p)) {
    var dpaid = digitalPaidOrderFor(p.id);
    html += '<div class="glass-card" style="padding:12px;margin:10px 0;font-size:12px;line-height:1.5;"><i class="fa-solid fa-cloud-arrow-down" style="color:var(--success);"></i> ' + t(p.digitalKind === "link" ? "dig_pd_info_link" : "dig_pd_info_file") + '</div>';
    if (dpaid) html += '<button class="btn-primary" style="margin-top:6px;" data-action="digital-open" data-order="' + dpaid.id + '" data-value="' + p.id + '"><i class="fa-solid ' + (p.digitalKind === "link" ? 'fa-circle-play' : 'fa-download') + '"></i> ' + t(p.digitalKind === "link" ? "dig_open_link" : "dig_download") + '</button>';
    else html += '<button class="btn-primary" style="margin-top:6px;" data-action="buy-digital" data-value="' + p.id + '"><i class="fa-solid fa-bolt"></i> ' + t("dig_buy_btn") + ' — ' + money(getTieredPrice(p, 1), p.country, state.profile ? state.profile.country : null) + '</button>';
  } else {
    html += '<label class="field-label">' + t("pd_quantity") + '</label>';
    html += '<div class="qty-control" style="width:fit-content;">';
    html += '<button data-action="modal-qty" data-delta="-1"><i class="fa-solid fa-minus"></i></button>';
    html += '<span style="font-weight:700;font-size:14px;min-width:22px;text-align:center;">' + state.selectedQty + '</span>';
    html += '<button data-action="modal-qty" data-delta="1"><i class="fa-solid fa-plus"></i></button>';
    html += '</div>';
    html += '<div class="delivery-estimate"><i class="fa-solid fa-truck-fast"></i><span>' + t("pd_delivery_estimate") + '</span></div>';
    html += '<div style="display:flex;gap:8px;">';
    html += '<button class="btn-primary" style="flex:1;" data-action="add-cart" data-value="' + p.id + '" ' + (p.stock <= 0 ? 'disabled' : '') + '><i class="fa-solid fa-plus"></i> ' + t("pd_add_to_cart") + '</button>';
    html += '<button class="btn-view-cart" data-action="view-cart-from-product">' + renderCartIcon(20) + (cartCount() > 0 ? '<span class="btn-view-cart-badge">' + cartCount() + '</span>' : '') + '</button>';
    html += '</div>';
    html += '<button class="btn-secondary" style="margin-top:10px;" data-action="buy-now" data-value="' + p.id + '" ' + (p.stock <= 0 ? 'disabled' : '') + '><i class="fa-solid fa-bolt"></i> ' + t("pd_buy_now") + '</button>';
  }
  html += '<button class="link-btn" style="margin-top:8px;width:100%;text-align:center;" data-action="chat-seller" data-value="' + p.id + '"><i class="fa-solid fa-comment"></i> ' + t("pd_contact_seller") + '</button>';
  html += '<button class="btn-whatsapp" data-action="whatsapp-coming-soon"><i class="fa-brands fa-whatsapp"></i> ' + t("pd_whatsapp") + '</button>';
  html += '</div></div>';
  
  // Avis
  html += '<div style="margin-top:20px;border-top:1px solid var(--border-color);padding-top:16px;">';
  html += '<div style="font-weight:700;font-size:14px;margin-bottom:10px;">' + t("pd_customer_reviews") + '</div>';
  if (reviews.length === 0) {
    html += '<div style="font-size:12px;color:var(--text-dim);">' + t("pd_no_reviews_for_product") + '</div>';
  } else {
    for (var rv = 0; rv < Math.min(5, reviews.length); rv++) {
      var rev = reviews[rv];
      html += '<div class="review-item"><div class="review-header"><span class="reviewer-name">' + esc(rev.userName) + '</span><span class="review-date">' + new Date(rev.createdAt).toLocaleDateString('fr-FR') + '</span></div>';
      html += '<div class="review-stars">' + '⭐'.repeat(rev.rating) + '☆'.repeat(5-rev.rating) + '</div>';
      html += '<div class="review-text">' + esc(rev.comment) + '</div>';
      if (rev.verified) html += '<span class="review-verified">✓ Achat vérifié</span>';
      html += '</div>';
    }
    if (reviews.length > 5) {
      html += '<button class="link-btn" style="font-size:12px;">Voir tous les avis (' + reviews.length + ')</button>';
    }
  }
  html += '<button class="btn-secondary" style="margin-top:10px;font-size:13px;padding:10px;" data-action="write-review" data-value="' + p.id + '"><i class="fa-regular fa-star"></i> Donner mon avis</button>';
  html += '</div>';

  // Produits recommandés (même catégorie que l'article consulté)
  ensureCategoryProductsLoaded(p.category);
  var relatedCandidates = [];
  for (var rp = 0; rp < state.products.length; rp++) {
    var rprod = state.products[rp];
    if (rprod.id !== p.id && rprod.category === p.category) relatedCandidates.push(rprod);
  }
  // Les vieux articles non sponsorisés d'une catégorie peuvent avoir été
  // écartés du lot chargé (voir le nouveau système de chargement par
  // lots), alors que les sponsorisés, eux, sont toujours garantis
  // présents — sans cette limite, une catégorie où beaucoup de vendeurs
  // boostent pouvait se retrouver avec une section "que du sponsorisé",
  // ce qui n'est ni honnête ni agréable à voir.
  // 9 au maximum (3 lignes de 3) : section courte, peu de données.
  var related = capBoostedShare(relatedCandidates, PD_RELATED_MAX, 0.25);
  if (related.length > 0) {
    html += '<div style="margin-top:20px;border-top:1px solid var(--border-color);padding-top:16px;">';
    html += '<div style="font-weight:700;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-star"></i> Vous pourriez aussi aimer</div>';
    html += '<div class="new-arrivals-scroll">';
    for (var re = 0; re < related.length; re++) html += productCard(related[re]);
    html += '</div></div>';
  }

  // Produits du marché : 2 colonnes comme le marché principal, affichés
  // par lots de 9. Le lot suivant n'arrive que quand le client atteint le
  // bas de la liste (voir setupPdMarketScroll) — avant, TOUS les articles
  // s'affichaient d'un coup, avec toutes leurs photos.
  var relatedIds = {};
  for (var ri = 0; ri < related.length; ri++) relatedIds[related[ri].id] = true;
  var marketCandidates = [];
  for (var ms = 0; ms < state.products.length; ms++) {
    var mprod = state.products[ms];
    if (mprod.id !== p.id && !relatedIds[mprod.id]) marketCandidates.push(mprod);
  }
  var marketSample = capBoostedShare(marketCandidates, PD_MARKET_MAX, 0.25);
  if (!window._pdMarket || window._pdMarket.pid !== p.id) window._pdMarket = { pid: p.id, shown: PD_MARKET_PAGE };
  window._pdMarket.list = marketSample;
  if (marketSample.length > 0) {
    var pdShown = Math.min(window._pdMarket.shown, marketSample.length);
    html += '<div style="margin-top:20px;border-top:1px solid var(--border-color);padding-top:16px;">';
    html += '<div style="font-weight:700;font-size:14px;margin-bottom:10px;"><i class="fa-solid fa-shop"></i> Produits du marché</div>';
    html += '<div class="product-grid" id="pd-market-grid">';
    for (var mp = 0; mp < pdShown; mp++) html += productCard(marketSample[mp]);
    html += '</div>';
    if (pdShown < marketSample.length) html += '<div id="pd-market-sentinel" style="height:1px;"></div>';
    html += '</div>';
  }

  // ---- Signalement d'un article (pas pour son propre vendeur) ----
  var isOwnProduct = state.profile && p.sellerId === state.profile.id;
  if (isOwnProduct && (p.moderationStatus === "pending" || p.moderationStatus === "rejected")) {
    html += '<div class="glass-card" style="margin-top:18px;padding:12px;background:rgba(255,159,10,0.12);border:1.5px solid #ff9f0a;font-size:12px;">';
    html += p.moderationStatus === "pending"
      ? '<i class="fa-solid fa-hourglass-half"></i> <strong>En attente de validation</strong> — cet article est temporairement masqué au public, le temps que l\'équipe Sounsouni le vérifie.'
      : '<i class="fa-solid fa-ban"></i> <strong>Article refusé</strong> — il n\'est pas visible par le public. Contactez l\'administration pour plus d\'informations.';
    html += '</div>';
  }
  if (state.profile && !isOwnProduct) {
    var alreadyReported = Array.isArray(p.reportedBy) && p.reportedBy.indexOf(state.profile.id) !== -1;
    html += '<div style="text-align:center;margin-top:18px;">';
    html += alreadyReported
      ? '<span style="font-size:11.5px;color:var(--text-dim);"><i class="fa-solid fa-flag"></i> Vous avez déjà signalé cet article — merci.</span>'
      : '<button class="link-btn" style="font-size:11.5px;color:var(--text-dim);" data-action="open-report-product" data-value="' + p.id + '"><i class="fa-regular fa-flag"></i> Signaler cet article</button>';
    html += '</div>';
  }
  
  html += '</div></div>';
  return html;
}

// ---------- RENDER LIGHTBOX ----------
function renderLightbox() {
  // Deux usages différents partagent cette même visionneuse : les photos
  // d'un article en vente (state.detailProductId + p.images), et les
  // photos génériques ouvertes ailleurs dans l'app comme les pièces
  // d'identité (state.lightboxImages) — ce deuxième cas n'était jusqu'ici
  // jamais lu ici, ce qui faisait échouer silencieusement tout ce qui
  // l'utilisait.
  var images = null;
  var altLabel = "";
  if (state.lightboxImages && state.lightboxImages.length > 0) {
    images = state.lightboxImages;
  } else {
    var p = null;
    for (var i = 0; i < state.products.length; i++) {
      if (state.products[i].id === state.detailProductId) {
        p = state.products[i];
        break;
      }
    }
    if (!p || !p.images || p.images.length === 0) return '';
    images = p.images;
    altLabel = p.name;
  }
  var idx = state.lightboxIndex;
  var html = '<div class="lightbox-overlay" data-action="close-lightbox">';
  html += '<div class="lightbox-content">';
  html += '<button class="lightbox-close" data-action="close-lightbox"><i class="fa-solid fa-xmark"></i></button>';
  html += '<button class="lightbox-close" style="right:56px;padding:6px;min-width:28px;min-height:28px;" data-action="download-lightbox-image" data-value="' + esc(images[idx]) + '" title="Télécharger cette photo"><i class="fa-solid fa-download"></i></button>';
  html += '<img loading="lazy" src="' + images[idx] + '" alt="' + esc(altLabel) + '" />';
  if (images.length > 1) {
    html += '<button class="lightbox-nav prev" data-action="lightbox-prev"><i class="fa-solid fa-chevron-left"></i></button>';
    html += '<button class="lightbox-nav next" data-action="lightbox-next"><i class="fa-solid fa-chevron-right"></i></button>';
    html += '<div class="lightbox-counter">' + (idx+1) + ' / ' + images.length + '</div>';
  }
  html += '</div></div>';
  return html;
}

// ---------- RENDER CHAT ----------
function renderChatToggle() {
  if (!state.profile) return '';
  var myConvs = getConversationsForUser();
  var unreadChat = 0;
  for (var i = 0; i < myConvs.length; i++) {
    unreadChat += unreadForMe(myConvs[i]);
  }
  for (var ai = 0; ai < state.adminConversations.length; ai++) {
    if (state.adminConversations[ai].accountId === state.profile.id) {
      unreadChat += state.adminConversations[ai].unreadForUser || 0;
      break;
    }
  }
  // Discret : ne s'affiche que s'il y a un vrai nouveau message non lu, et
  // seulement si l'utilisateur ne l'a pas déjà refermé pour ce lot de
  // messages précis (redevient visible si de nouveaux messages arrivent).
  var dismissedAt = state.chatToggleDismissedCount || 0;
  if (unreadChat === 0 || (unreadChat <= dismissedAt && !state.chatOpen)) {
    if (!state.chatOpen) return '';
  }
  var html = '<div class="chat-toggle-wrap">';
  html += '<button class="chat-toggle-btn" data-action="toggle-chat"><i class="fa-solid fa-comment"></i>';
  if (unreadChat > 0) {
    html += '<span class="chat-badge">' + unreadChat + '</span>';
  }
  html += '</button>';
  if (!state.chatOpen && unreadChat > 0) {
    html += '<button class="chat-toggle-dismiss" data-action="dismiss-chat-toggle"><i class="fa-solid fa-xmark"></i></button>';
  }
  html += '</div>';
  return html;
}

// Composeur de message — texte classique + bouton micro pour un message
// vocal (enregistrement réel, envoyé comme pièce jointe audio).
function renderChatComposer() {
  var html = '<div class="chat-input-area">';
  if (state.voiceRecording) {
    html += '<div style="flex:1;display:flex;align-items:center;gap:8px;color:var(--danger);font-weight:700;font-size:12.5px;"><i class="fa-solid fa-circle" style="font-size:9px;animation:pulseAttention 1s infinite;"></i> ' + t("chat_recording") + ' <span id="voiceRecTimer">0:00</span></div>';
    html += '<button data-action="cancel-voice-recording" style="background:var(--bg-body);color:var(--text-dim);"><i class="fa-solid fa-trash"></i></button>';
    html += '<button data-action="stop-voice-recording" style="background:var(--danger);"><i class="fa-solid fa-stop"></i></button>';
  } else {
    html += '<input id="chatInput" placeholder="' + t("chat_write_message") + '" />';
    // Le message vocal n'est disponible que pour une conversation entre
    // utilisateurs (acheteur/vendeur) — pas pour la messagerie Admin.
    if (state.currentConversationId) {
      html += '<button data-action="start-voice-recording" style="background:var(--bg-body);color:var(--text-primary);border:1.5px solid var(--border-color);"><i class="fa-solid fa-microphone"></i></button>';
    }
    html += '<button data-action="send-chat"><i class="fa-solid fa-paper-plane"></i></button>';
  }
  html += '</div>';
  return html;
}

function renderChatWidget() {
  var convs = getConversationsForUser();
  var myAdminConv = null;
  for (var ai = 0; ai < state.adminConversations.length; ai++) {
    if (state.adminConversations[ai].accountId === state.profile.id) { myAdminConv = state.adminConversations[ai]; break; }
  }

  var currentConv = null;
  if (state.currentConversationId) {
    for (var i = 0; i < state.conversations.length; i++) {
      if (state.conversations[i].id === state.currentConversationId) {
        currentConv = state.conversations[i];
        break;
      }
    }
  }
  var viewingAdmin = !!state.currentAdminConvId;
  var messages = currentConv ? getConversationMessages(currentConv.id) : (viewingAdmin && myAdminConv ? myAdminConv.messages : []);
  
  var html = '<div class="chat-widget open">';
  if (currentConv || viewingAdmin) {
    var headerAccLabel = '';
    if (currentConv) {
      var headerLinkedIds = getLinkedAccountIds();
      var headerConvAccountId = headerLinkedIds.indexOf(currentConv.sellerId) !== -1 ? currentConv.sellerId : currentConv.buyerId;
      var headerConvAcc = null;
      for (var hca = 0; hca < state.accounts.length; hca++) { if (state.accounts[hca].id === headerConvAccountId) { headerConvAcc = state.accounts[hca]; break; } }
      if (headerConvAcc) headerAccLabel = ' — ' + esc(headerConvAcc.shopName || headerConvAcc.name);
    }
    html += '<div class="chat-header"><button class="link-btn" style="color:white;padding:0;" data-action="back-to-chat-list"><i class="fa-solid fa-arrow-left"></i> ' + t("chat_back") + '</button><span>💬 ' + (currentConv ? t("chat_conversation") + headerAccLabel : t("chat_administration")) + '</span><button class="chat-close" data-action="toggle-chat">✕</button></div>';
  } else {
    html += '<div class="chat-header" data-action="toggle-chat"><span>💬 ' + t("chat_messages") + '</span><button class="chat-close" data-action="toggle-chat">✕</button></div>';
  }
  html += '<div class="chat-body">';
  if (!currentConv && !viewingAdmin) {
    html += '<div style="padding:12px;overflow-y:auto;flex:1;">';
    html += '<div style="padding:10px;border-bottom:1px solid var(--border-color);cursor:pointer;background:rgba(255,122,26,0.06);border-radius:10px;margin-bottom:6px;" data-action="open-admin-chat">';
    html += '<div style="font-weight:700;font-size:13px;"><i class="fa-solid fa-shield-halved" style="color:var(--accent);"></i> ' + t("chat_administration") + '</div>';
    html += '<div style="font-size:12px;color:var(--text-dim);">' + (myAdminConv ? esc(myAdminConv.lastMessage || '') : t("chat_contact_admin")) + '</div>';
    if (myAdminConv && (myAdminConv.unreadForUser || 0) > 0) {
      html += '<span style="background:var(--danger);color:white;font-size:10px;padding:1px 8px;border-radius:999px;">' + myAdminConv.unreadForUser + '</span>';
    }
    html += '</div>';
    if (convs.length === 0) {
      html += '<div style="text-align:center;color:var(--text-dim);padding:30px 0;font-size:12.5px;">' + t("chat_no_other_conv") + '</div>';
    } else {
      var myLinkedIdsForList = getLinkedAccountIds();
      for (var j = 0; j < convs.length; j++) {
        var c = convs[j];
        var product = null;
        for (var p = 0; p < state.products.length; p++) {
          if (state.products[p].id === c.productId) { product = state.products[p]; break; }
        }
        // Indique clairement QUEL compte lié est concerné par cette
        // conversation — indispensable dès qu'on a plusieurs comptes sous
        // le même numéro, sinon impossible de savoir qui a reçu quoi.
        var myConvAccountId = myLinkedIdsForList.indexOf(c.sellerId) !== -1 ? c.sellerId : c.buyerId;
        var myConvAcc = null;
        for (var mca = 0; mca < state.accounts.length; mca++) { if (state.accounts[mca].id === myConvAccountId) { myConvAcc = state.accounts[mca]; break; } }
        // On affiche la personne qui écrit (l'autre partie), pas son propre
        // compte — "Vous-même" si les deux côtés sont à soi (compte lié).
        var otherPartyId = myConvAccountId === c.sellerId ? c.buyerId : c.sellerId;
        var otherPartyIsMine = myLinkedIdsForList.indexOf(otherPartyId) !== -1;
        var otherPartyAcc = null;
        for (var opa = 0; opa < state.accounts.length; opa++) { if (state.accounts[opa].id === otherPartyId) { otherPartyAcc = state.accounts[opa]; break; } }
        var myConvAccLabel = otherPartyIsMine ? "Vous-même" : (otherPartyAcc ? (otherPartyId === c.sellerId ? (otherPartyAcc.shopName || otherPartyAcc.name) : otherPartyAcc.name) : '');
        html += '<div style="padding:10px;border-bottom:1px solid var(--border-color);cursor:pointer;" data-action="open-chat" data-value="' + c.id + '">';
        html += '<div style="display:flex;justify-content:space-between;align-items:baseline;gap:8px;"><div style="font-weight:700;font-size:13px;">' + (product ? esc(product.name) : t("chat_product_default")) + '</div>' + (myConvAccLabel ? '<div style="font-size:10px;color:var(--accent);font-weight:700;white-space:nowrap;">' + esc(myConvAccLabel) + '</div>' : '') + '</div>';
        var convLastMsg = c.lastMessage;
        if (!convLastMsg && Array.isArray(c.messages) && c.messages.length) { var lm = c.messages[c.messages.length - 1]; convLastMsg = lm ? (lm.audioUrl || lm.type === "audio" ? "🎤 Message vocal" : (lm.message || lm.text || "")) : ""; }
        html += '<div style="font-size:12px;color:var(--text-dim);">' + esc(convLastMsg || t("chat_new_conversation")) + '</div>';
        if (unreadForMe(c) > 0) {
          html += '<span style="background:var(--danger);color:white;font-size:10px;padding:1px 8px;border-radius:999px;">' + unreadForMe(c) + '</span>';
        }
        html += '</div>';
      }
    }
    html += '</div>';
  } else {
    html += '<div class="messages-container" id="chatMessages">';
    for (var m = 0; m < messages.length; m++) {
      var msg = messages[m];
      var isSent = viewingAdmin ? (msg.senderRole !== "admin") : (getLinkedAccountIds().indexOf(msg.senderId) !== -1);
      html += '<div class="message ' + (isSent ? 'sent' : 'received') + '">';
      if (!isSent) {
        html += '<div style="font-weight:600;font-size:11px;">' + (viewingAdmin ? t("chat_administration") : esc(msg.senderName)) + '</div>';
      }
      if (msg.type === "audio" && msg.audioUrl) {
        html += '<audio controls src="' + esc(msg.audioUrl) + '" style="max-width:210px;height:36px;"></audio>';
        if (msg.hasPhoneNumber) {
          html += '<div class="blocked-phone">' + t("chat_voice_warning") + '</div>';
        }
      } else {
        html += esc(msg.message);
        if (msg.hasPhoneNumber) {
          html += '<div class="blocked-phone">' + t("chat_number_hidden") + '</div>';
        }
      }
      html += '<span class="time">' + new Date(msg.createdAt).toLocaleTimeString('fr-FR', {hour:'2-digit',minute:'2-digit'}) + '</span>';
      html += '</div>';
    }
    html += '</div>';
    html += renderChatComposer();
  }
  html += '</div></div>';
  return html;
}

// ---------- RENDER ADMIN ORDER MODAL ----------
// ---------- Reconfirmation par mot de passe avant de révéler des
// informations sensibles (GPS exact, téléphone) sur une commande ----------
// Même si le panneau Admin est déjà déverrouillé, voir ces détails
// précis redemande le mot de passe — au cas où l'appareil serait resté
// ouvert sans surveillance. Redemande TOUJOURS un vrai aller-retour
// serveur (jamais juste "je me souviens que c'était bon tout à
// l'heure"), donc ça marche même avec l'ancien mot de passe par défaut
// jamais encore personnalisé.
function renderRevealPasswordModal() {
  var isGroup2 = !state.adminIsOwner;
  var html = '<div class="modal-overlay" id="reveal-password-overlay" data-action="close-reveal-password">';
  html += '<div class="modal-sheet">';
  html += '<button class="modal-close" data-action="close-reveal-password"><i class="fa-solid fa-xmark"></i></button>';
  html += '<div class="section-title" style="margin-bottom:10px;"><i class="fa-solid fa-lock"></i> Confirmation requise</div>';
  if (isGroup2) {
    html += '<div style="font-size:12px;color:var(--text-dim);margin-bottom:14px;">Retape ton propre numéro de téléphone (celui de ton compte) pour voir ces informations.</div>';
    html += '<input class="input" type="tel" id="reveal-password-input" placeholder="Ton numéro de téléphone" value="' + esc(state.revealPasswordValue || "") + '" data-bind="revealPasswordValue" data-enter-action="submit-reveal-password" />';
  } else {
    html += '<div style="font-size:12px;color:var(--text-dim);margin-bottom:14px;">Retape le mot de passe Admin pour voir ces informations complètes.</div>';
    html += '<input class="input" type="password" id="reveal-password-input" placeholder="Mot de passe Admin" value="' + esc(state.revealPasswordValue || "") + '" data-bind="revealPasswordValue" data-enter-action="submit-reveal-password" />';
  }
  if (state.revealPasswordError) html += '<div style="color:var(--danger);font-size:11.5px;margin-top:6px;">' + esc(state.revealPasswordError) + '</div>';
  html += '<button class="btn-primary" style="margin-top:14px;width:100%;" data-action="submit-reveal-password"><i class="fa-solid fa-eye"></i> Confirmer et voir</button>';
  html += '</div></div>';
  return html;
}

function renderAdminOrderModal() {
  var o = null;
  for (var i = 0; i < state.orders.length; i++) {
    if (state.orders[i].id === state.adminOrderDetailId) {
      o = state.orders[i];
      break;
    }
  }
  if (!o) return '';
  var paymentLabels = { paiement_livraison: "Paiement à la livraison", orange_money: "Orange Money", moov_money: "Moov Money", portefeuille: "Portefeuille Sounsouni" };
  
  var html = '<div class="modal-overlay" id="admin-order-overlay" data-action="close-admin-order">';
  html += '<div class="modal-sheet">';
  html += '<button class="modal-close" data-action="close-admin-order"><i class="fa-solid fa-xmark"></i></button>';
  html += '<div class="section-title" style="margin-bottom:4px;">Commande #' + o.id.slice(-5).toUpperCase() + '</div>';
  html += '<div style="font-size:11.5px;color:var(--text-dim);margin-bottom:16px;">' + new Date(o.createdAt).toLocaleString("fr-FR") + '</div>';
  
  // Stepper
  var flowForOrder = o.isInternational ? INTERNATIONAL_STATUS_FLOW : (o.deliveryMode === "relais" ? RELAIS_STATUS_FLOW : STATUS_FLOW);
  html += '<div class="status-stepper" style="display:flex;align-items:flex-start;">';
  for (var s = 0; s < flowForOrder.length; s++) {
    var sname = flowForOrder[s];
    var isDone = s <= statusProgressIndex(o.status);
    html += '<div class="stepper-step" style="display:flex;flex-direction:column;align-items:center;gap:4px;flex-shrink:0;width:44px;">';
    html += '<div class="stepper-dot" style="width:24px;height:24px;border-radius:50%;background:' + (isDone ? 'rgba(46,204,113,0.15)' : 'var(--bg-body)') + ';border:1.5px solid ' + (isDone ? 'var(--success)' : 'var(--border-color)') + ';color:' + (isDone ? 'var(--success)' : 'var(--text-dim)') + ';display:flex;align-items:center;justify-content:center;font-size:10px;"><i class="fa-solid ' + STATUS_ICONS[sname] + '"></i></div>';
    html += '<div class="stepper-label" style="font-size:8.5px;font-weight:700;color:' + (isDone ? 'var(--text-primary)' : 'var(--text-dim)') + ';text-align:center;line-height:1.2;">' + translateStatus(sname) + '</div>';
    html += '</div>';
    if (s < flowForOrder.length - 1) {
      html += '<div class="stepper-line" style="flex:1;height:2px;background:' + (isDone ? 'var(--success)' : 'var(--border-color)') + ';margin-top:11px;min-width:8px;"></div>';
    }
  }
  html += '</div>';
  
  html += '<div style="font-weight:800;font-size:13.5px;margin:20px 0 8px;"><i class="fa-solid fa-box-open"></i> Articles</div>';
  if (!o.items) {
    html += '<button class="link-btn" data-action="open-reveal-order-details" data-value="' + o.id + '"><i class="fa-solid fa-lock"></i> ' + (state.adminIsOwner ? 'Voir les articles et montants (mot de passe requis)' : 'Voir les articles et montants (confirmation requise)') + '</button>';
    html += '</div></div>';
    return html;
  }
  for (var it = 0; it < o.items.length; it++) {
    var item = o.items[it];
    html += '<div style="display:flex;justify-content:space-between;font-size:13px;padding:6px 0;border-bottom:1px solid var(--border-color);">';
    html += '<div><div>' + item.qty + '× ' + esc(item.name) + itemVariant(item) + '</div>';
    html += '<div style="font-size:11px;color:var(--text-dim);"><i class="fa-solid fa-store"></i> ' + esc(item.sellerName) + '</div></div>';
    html += '<div style="font-weight:700;">' + (o.isInternational && o.exchangeRate ? money(Math.round(item.price * item.qty * o.exchangeRate)) : money(item.price * item.qty)) + '</div>';
    html += '</div>';
  }
  html += '<div style="display:flex;justify-content:space-between;font-size:13px;color:var(--text-secondary);margin-top:10px;"><span>Sous-total</span><span>' + orderMoney(o.subtotal, o) + '</span></div>';
  html += '<div style="display:flex;justify-content:space-between;font-size:13px;color:var(--text-secondary);margin-top:4px;"><span>Livraison</span><span>' + orderMoney(o.deliveryFee, o) + '</span></div>';
  html += '<div style="display:flex;justify-content:space-between;font-weight:800;font-size:15px;border-top:1px solid var(--border-color);margin-top:8px;padding-top:8px;"><span>Total</span><span style="color:var(--accent)">' + orderMoney(o.total, o) + '</span></div>';
  if (o.otp) {
    html += '<div style="margin-top:10px;padding:10px;background:var(--bg-body);border-radius:10px;font-size:12px;text-align:center;">🔑 Code OTP: <strong style="font-size:20px;letter-spacing:4px;">' + o.otp + '</strong></div>';
  }
  html += '<div style="font-weight:800;font-size:13.5px;margin:20px 0 8px;"><i class="fa-solid fa-phone"></i> Contacts</div>';
  var sellerMap = {};
  for (var si = 0; si < o.items.length; si++) {
    var it2 = o.items[si];
    sellerMap[it2.sellerId] = it2;
  }
  var sellerKeys = Object.keys(sellerMap);
  for (var sk = 0; sk < sellerKeys.length; sk++) {
    var seller = sellerMap[sellerKeys[sk]];
    html += '<a class="contact-row" href="tel:' + (seller.sellerPhone || '').replace(/\s/g, '') + '" style="display:flex;align-items:center;gap:12px;padding:10px 0;text-decoration:none;border-bottom:1px solid var(--border-color);">';
    html += '<div class="emoji-thumb"><i class="fa-solid fa-store"></i></div>';
    html += '<div style="flex:1;"><div style="font-weight:700;font-size:13px;">' + esc(seller.sellerName) + '</div><div style="font-size:11.5px;color:var(--text-dim);">Vendeur</div></div>';
    html += '<div style="font-weight:700;font-size:13px;color:var(--accent);">' + esc(seller.sellerPhone || "—") + '</div>';
    html += '</a>';
  }
  if (o.livreurPhone) {
    html += '<a class="contact-row" href="tel:' + o.livreurPhone.replace(/\s/g, '') + '" style="display:flex;align-items:center;gap:12px;padding:10px 0;text-decoration:none;border-bottom:1px solid var(--border-color);">';
    html += '<div class="emoji-thumb"><i class="fa-solid fa-truck-fast"></i></div>';
    html += '<div style="flex:1;"><div style="font-weight:700;font-size:13px;">' + esc(o.livreurName) + '</div><div style="font-size:11.5px;color:var(--text-dim);">Livreur</div></div>';
    html += '<div style="font-weight:700;font-size:13px;color:var(--accent);">' + esc(o.livreurPhone) + '</div>';
    html += '</a>';
  } else {
    html += '<div style="font-size:12.5px;color:var(--text-dim);margin-top:6px;">Pas encore pris en charge.</div>';
  }
  html += '<div style="font-weight:800;font-size:13.5px;margin:20px 0 8px;"><i class="fa-solid fa-truck"></i> Livraison</div>';
  if (o.isInternational) {
    html += '<div style="font-size:13px;color:var(--text-secondary);line-height:1.6;">' + esc(o.country || "") + " — " + esc(o.shippingMode || "") + (o.deliveryPoint ? " — " + esc(o.deliveryPoint) : "") + '</div>';
    if (o.commune || o.repere) {
      html += '<div style="font-size:13px;color:var(--text-secondary);line-height:1.6;"><i class="fa-solid fa-house"></i> Bamako, ' + esc(o.commune || o.zone || "") + (o.quartier ? ', ' + esc(o.quartier) : '') + (o.repere ? '<br/><i class="fa-solid fa-location-dot"></i> ' + esc(o.repere) : '') + '</div>';
      if (!o.repere) html += '<button class="link-btn" style="margin-top:6px;font-size:12px;" data-action="open-reveal-order-contact" data-value="' + o.id + '"><i class="fa-solid fa-lock"></i> Voir l\'adresse exacte</button>';
    }
    if (o.seaTransportXof != null) {
      var rowS = function(l, v) { return '<div style="display:flex;justify-content:space-between;gap:8px;font-size:12.5px;color:var(--text-secondary);margin-top:3px;"><span style="min-width:0;">' + l + '</span><span style="flex-shrink:0;">' + v + '</span></div>'; };
      html += '<div style="background:var(--bg-body);border-radius:10px;padding:8px 10px;margin-top:6px;">';
      html += '<div style="font-size:11px;font-weight:700;color:var(--text-dim);">Détail interne (non montré au client)</div>';
      html += rowS('Volume facturé', String(o.billableM3).replace('.', ',') + ' m³');
      if (o.billableWeightKg) html += rowS('Poids réel déclaré', String(o.billableWeightKg).replace('.', ',') + ' kg');
      html += rowS('Bateau + ports + camion (tout compris)', money(o.seaTransportXof));
      html += rowS('Frais Sounsouni', money(o.sounsouniFeeXof || 0));
      if (o.customsXof != null) html += rowS('Douane + TVA Mali', money(o.customsXof));
      if (o.homeDeliveryXof != null) html += rowS('Livraison à domicile (Bamako)', money(o.homeDeliveryXof));
      html += '</div>';
    }
    if (o.airTransportInr != null) {
      var rateO = Number(o.exchangeRate) || 0;
      var rowO = function(l, v) { return '<div style="display:flex;justify-content:space-between;gap:8px;font-size:12.5px;color:var(--text-secondary);margin-top:3px;"><span style="min-width:0;">' + l + '</span><span style="flex-shrink:0;">' + v + '</span></div>'; };
      var pk = Array.isArray(o.parcelsKg) && o.parcelsKg.length ? o.parcelsKg : (o.billableWeightKg ? [o.billableWeightKg] : []);
      html += '<div style="background:var(--bg-body);border-radius:10px;padding:8px 10px;margin-top:6px;">';
      html += '<div style="font-size:11px;font-weight:700;color:var(--text-dim);">Détail interne (non montré au client)</div>';
      if (o.billableWeightKg) html += rowO('Poids facturé', String(o.billableWeightKg).replace('.', ',') + ' kg');
      if (pk.length) html += rowO('Colis à préparer', pk.length + ' : ' + pk.map(function(k) { return String(k).replace('.', ',') + ' kg'; }).join(' + '));
      html += rowO('Transport + taxe indienne', Number(o.airTransportInr).toLocaleString('fr-FR') + ' ₹' + (rateO ? ' (' + money(Math.round(o.airTransportInr * rateO)) + ')' : ''));
      if (o.sounsouniFeeInr != null) html += rowO('Frais Sounsouni', Number(o.sounsouniFeeInr).toLocaleString('fr-FR') + ' ₹' + (rateO ? ' (' + money(Math.round(o.sounsouniFeeInr * rateO)) + ')' : ''));
      if (o.customsXof != null) html += rowO('Douane + TVA Mali', money(o.customsXof));
      if (o.homeDeliveryXof != null) html += rowO('Livraison à domicile (Bamako)', money(o.homeDeliveryXof));
      if (rateO) html += rowO('Taux utilisé', '1 ₹ = ' + rateO.toFixed(2) + ' FCFA');
      html += '</div>';
    }
  } else if (o.repere) {
    html += '<div style="font-size:13px;color:var(--text-secondary);line-height:1.6;">' + o.city + ', ' + esc(o.zone) + '<br/><i class="fa-solid fa-location-dot"></i> ' + esc(o.repere) + '</div>';
  } else {
    html += '<div style="font-size:13px;color:var(--text-secondary);line-height:1.6;">' + o.city + ', ' + esc(o.zone) + '</div>';
    html += '<button class="link-btn" style="margin-top:6px;font-size:12px;" data-action="open-reveal-order-contact" data-value="' + o.id + '"><i class="fa-solid fa-lock"></i> ' + (state.adminIsOwner ? 'Voir l\'adresse exacte (mot de passe requis)' : 'Voir l\'adresse exacte (confirmation requise)') + '</button>';
  }
  html += '<div style="font-weight:800;font-size:13.5px;margin:20px 0 8px;"><i class="fa-solid fa-credit-card"></i> Paiement</div>';
  html += '<div style="font-size:13px;color:var(--text-secondary);">' + (paymentLabels[o.payment] || o.payment) + '</div>';
  html += '</div></div>';
  return html;
}

