  html += '<button type="button" data-action="toggle-admin-pass-visible" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--text-dim);"><i class="fa-solid ' + (state.adminGatePassVisible ? 'fa-eye-slash' : 'fa-eye') + '"></i></button>';
