      state.checkoutForm.expressCommune = "";
      state.checkoutForm.expressQuartier = "";
      state.checkoutForm.repere = "";
      state.checkoutForm.contactPhone = null;
      state.checkoutForm.buyerLat = null;
      state.checkoutForm.buyerLng = null;
      state.checkoutForm.buyerGpsAccuracy = null;
      state.checkoutForm.expressSaveAsked = false;
      render();
