        '</body></html>';
      var guideBlob = new Blob([guideHtml], { type: "text/html;charset=utf-8" });
      var guideUrl = URL.createObjectURL(guideBlob);
      var guideLink = document.createElement("a");
      guideLink.href = guideUrl;
      guideLink.download = "Guide-utilisation-Sounsouni.html";
      document.body.appendChild(guideLink);
      guideLink.click();
      document.body.removeChild(guideLink);
      setTimeout(function() { URL.revokeObjectURL(guideUrl); }, 2000);
      showToast(t("toast_guide_downloaded"));
      break;
