      if (!state.settings) state.settings = [];
      var di = -1;
      for (var dsi = 0; dsi < state.settings.length; dsi++) { if (state.settings[dsi].id === "diagnostics_config") { di = dsi; break; } }
      if (di === -1) state.settings.push(diagDoc); else state.settings[di] = diagDoc;
      save();
      saveDoc("settings", diagDoc);
