      var perKgA = readRate("intl-air-perkg"), maxA = readRate("intl-air-max"), gstA = readRate("intl-air-gst"), mgA = readRate("intl-air-margin"), dutyA = readRate("intl-air-duty"), vatA = readRate("intl-air-vat");
