    '<path d="M8 10 C8 6.5 9.5 4 12 4 C14.5 4 16 6.5 16 10" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" fill="none"/>' +
    '<path d="M5.5 10 H18.5 L17.2 19 C17.05 19.9 16.3 20.5 15.4 20.5 H8.6 C7.7 20.5 6.95 19.9 6.8 19 Z" fill="currentColor" fill-opacity="0.18" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/>' +
    '<path d="M8.5 13.5 H15.5 M8.9 16.5 H15.1" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" opacity="0.6"/>' +
    '</svg>';
