function renderGLogoSvg(size, animated) {
  var navy = 'M 194.37 245.16 A 105 105 0 1 1 245.16 105.63 L 206.19 123.80 A 62 62 0 1 0 176.20 206.19 Z';
  var green = 'M 245.16 105.63 A 105 105 0 0 1 254.60 159.15 L 211.76 155.40 A 62 62 0 0 0 206.19 123.80 Z';
  var boxLeft = 'M 172 190 L 172 236 L 214 258 L 214 212 Z';
  var boxRight = 'M 214 212 L 214 258 L 256 236 L 256 190 Z';
  var boxTop = 'M 172 190 L 214 168 L 256 190 L 214 212 Z';
  var bolt = 'M 158 30 L 96 175 L 132 175 L 108 270 L 210 148 L 162 148 Z';

  if (animated) {
    function shape(d, color, delay) {
      return '<path class="splash-stroke" d="' + d + '" style="stroke:' + color + ';animation-delay:' + delay + 's"></path>' +
             '<path class="splash-fill" d="' + d + '" style="fill:' + color + ';animation-delay:' + (delay + 0.55) + 's"></path>';
    }
    return '<svg viewBox="0 0 300 300" width="' + size + '" height="' + size + '" class="splash-logo">' +
      shape(navy, '#12233f', 0) + shape(green, '#2e9e4f', 0.25) +
      shape(boxLeft, '#e8720c', 0.5) + shape(boxRight, '#f28c1a', 0.55) +
      shape(boxTop, '#ffb84d', 0.6) + shape(bolt, '#f2b705', 0.35) +
      '</svg>';
  }
  return '<svg viewBox="0 0 300 300" width="' + size + '" height="' + size + '" class="g-logo-static">' +
    '<path d="' + navy + '" fill="#12233f"/>' +
    '<path d="' + green + '" fill="#2e9e4f"/>' +
    '<path d="' + boxLeft + '" fill="#e8720c"/>' +
    '<path d="' + boxRight + '" fill="#f28c1a"/>' +
    '<path d="' + boxTop + '" fill="#ffb84d"/>' +
    '<path d="' + bolt + '" fill="#f2b705"/>' +
    '</svg>';
}

function renderSplashScreen() {
  // Animation signature : quelques écailles s'assemblent en convergeant
  // vers le centre avant que le logo n'apparaisse — chacune part d'un
  // bord différent, avec un léger décalage de temps.
  var scaleDirs = [
    { x: -140, y: -160 }, { x: 140, y: -160 }, { x: -160, y: 0 },
    { x: 160, y: 0 }, { x: -140, y: 160 }, { x: 140, y: 160 },
    { x: 0, y: -180 }, { x: 0, y: 180 }
  ];
  var scalesHtml = '';
  for (var i = 0; i < scaleDirs.length; i++) {
    var d = scaleDirs[i];
    scalesHtml += '<div class="splash-scale" style="--sx:' + d.x + 'px;--sy:' + d.y + 'px;animation-delay:' + (i * 0.2) + 's;"></div>';
  }
  return '<div class="splash-screen"><div class="splash-scales-wrap">' + scalesHtml + '<img loading="lazy" src="' + SOUNSOUNI_SPLASH_IMG + '" class="splash-sounsouni-logo" alt="Sounsouni" /></div></div>';
}

