function finishProductsBoot() {
  if (window.__bootMark) window.__bootMark("traitement des articles");
  // Premier lancement de ce projet Supabase (table vide) : on y dépose
  // le catalogue de démo, une seule fois. Déplacé ici (plutôt que dans
  // la synchronisation générale) car c'est seulement à cet endroit
  // qu'on sait vraiment si le catalogue est vide ou pas.
  if (state.products.length === 0 && !localStorage.getItem("gems_seeded_v1")) {
    localStorage.setItem("gems_seeded_v1", "1");
    SEED_PRODUCTS.forEach(function(p) { saveDoc("products", p); });
  }
  // Nettoyage ponctuel des articles de démonstration — même logique
  // qu'avant, juste déplacée ici pour la même raison.
  if (!localStorage.getItem("gems_seed_cleanup_v1")) {
    localStorage.setItem("gems_seed_cleanup_v1", "1");
    var seedProductsStillPresent = state.products.filter(function(p) { return p.sellerId === "seed"; });
    if (seedProductsStillPresent.length > 0) {
      seedProductsStillPresent.forEach(function(p) { deleteRemoteDoc("products", p.id); });
      state.products = state.products.filter(function(p) { return p.sellerId !== "seed"; });
    }
  }
  save();
  _productsSyncReady = true;
  maybeSignalBootReady();
  // Vérification globale des articles trop vieux (particuliers
  // uniquement) — déclenchée par N'IMPORTE QUI ouvrant l'app, pas
  // seulement le vendeur concerné (voir la note détaillée plus haut).
  // Ne dépend que des produits déjà chargés, donc peut se faire ici.
  maybeRunGlobalStaleProductCheck();
}

// Va chercher, un par un, tout produit connu comme boosté ou déjà
// acheté par cette personne, mais absent du lot déjà chargé — ces deux
// listes (boosts, commandes) restent, elles, entièrement synchronisées
// comme avant, donc on sait déjà QUELS identifiants chercher.
// ---------- Actualisation obligatoire des articles (vendeurs particuliers) ----------
// Ne concerne QUE les particuliers (sellerType === "particulier") — les
// entreprises (restaurants, hôtels...) proposent un service permanent au
// jour le jour, pas un stock d'articles ponctuels, donc ça n'a pas de
// sens de les forcer à "actualiser" quoi que ce soit.
//
// Déclenché par N'IMPORTE QUI ouvrant l'app (comme checkStalePickupOrders
// pour les colis non récupérés) — pas seulement le vendeur concerné.
// Important avec notre chargement par lots : on interroge Supabase
// DIRECTEMENT pour la liste des articles anciens, plutôt que de se fier à
// ce qui est déjà chargé localement (qui peut être incomplet) — ainsi,
// même si le vendeur concerné ne se reconnecte jamais, le premier autre
// visiteur qui ouvre l'app quelque part déclenche quand même la
// vérification pour lui.
var STALE_WARNING_START_DAYS = 60;
var STALE_DELETE_DAYS = 90;
var STALE_WARNING_INTERVAL_DAYS = 4; // un rappel tous les 3-5 jours environ
var STALE_CHECK_KEY = "gems_last_stale_check_v1";
var STALE_CHECK_INTERVAL_MS = 12 * 60 * 60 * 1000; // au plus deux fois par jour et par appareil, peu importe le nombre de visiteurs

// ---------- COMPTEUR DE VISITEURS (anonyme) ----------
// 1 appareil = 1 visiteur par jour. Un numéro tiré au hasard est gardé sur
// l'appareil (aucun nom, aucun numéro de téléphone). On note seulement :
// connecté ou non, et d'où vient la visite (Google, Facebook, WhatsApp,
// lien d'article partagé, parrainage, direct). Le comptage est fait par le
// serveur (secure-write) : personne ne peut gonfler les chiffres.
function visitSource() {
  try {
    var qs = location.search || "";
    if (/[?&]product=/.test(qs)) return "lien_article";
    if (/[?&]ref=/.test(qs)) return "parrainage";
    var r = String(document.referrer || "").toLowerCase();
    if (!r || r.indexOf(location.host) !== -1) return "direct";
    if (r.indexOf("google.") !== -1) return "google";
    if (r.indexOf("facebook.") !== -1 || r.indexOf("fb.") !== -1 || r.indexOf("instagram.") !== -1) return "facebook";
    if (r.indexOf("whatsapp") !== -1 || r.indexOf("wa.me") !== -1) return "whatsapp";
    if (r.indexOf("tiktok") !== -1) return "tiktok";
    return "autre_site";
  } catch (e) { return "direct"; }
}
var _visitSourceAtArrival = visitSource();
function trackVisit() {
  if (!FIREBASE_ENABLED || navigator.webdriver) return;
  var day = new Date().toISOString().slice(0, 10), member = !!state.profile;
  var vid = null, done = null;
  try {
    vid = localStorage.getItem("sns_visitor_id");
    if (!vid) { vid = (Math.random().toString(36).slice(2) + Date.now().toString(36) + Math.random().toString(36).slice(2)).replace(/[^a-z0-9]/g, "").slice(0, 24); localStorage.setItem("sns_visitor_id", vid); }
    done = localStorage.getItem("sns_visit_day");
  } catch (e) { return; }
  // Déjà compté aujourd'hui (et déjà compté comme inscrit s'il l'est) : rien à faire.
  if (done === day + "|1" || (done === day + "|0" && !member)) return;
  fetch(supabaseConfig.url + "/functions/v1/secure-write", { method: "POST", headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey }, body: JSON.stringify({ operation: "track_visit", vid: vid, member: member, src: _visitSourceAtArrival }) })
    .then(readServerJson)
    .then(function(res) { if (res && res.success) { try { localStorage.setItem("sns_visit_day", day + "|" + (member ? 1 : 0)); } catch (e) {} } })
    .catch(function() {});
}

// Carte « Visiteurs du site » (Admin > Tableau de bord)
function loadVisitStats(force) {
  if (!FIREBASE_ENABLED) return;
  if (!force && window._visitStatsAt && Date.now() - window._visitStatsAt < 5 * 60 * 1000) return;
  window._visitStatsAt = Date.now();
  var since = new Date(Date.now() - 29 * 864e5).toISOString().slice(0, 10);
  sb.from("app_data").select("data").eq("collection", "visitStats").gte("id", since).then(function(res) {
    if (res.error || !res.data) return;
    state.visitStats = res.data.map(function(r) { return r.data; }).filter(Boolean);
    renderOrDefer();
  });
}
function renderVisitStatsCard() {
  loadVisitStats(false);
  var rows = state.visitStats || [];
  var today = new Date().toISOString().slice(0, 10);
  function sum(days) {
    var since = new Date(Date.now() - (days - 1) * 864e5).toISOString().slice(0, 10);
    var r = { v: 0, g: 0, m: 0, src: {} };
    rows.forEach(function(d) { if (!d || d.id < since) return; r.v += d.visitors || 0; r.g += d.guests || 0; r.m += d.members || 0; Object.keys(d.sources || {}).forEach(function(k) { r.src[k] = (r.src[k] || 0) + d.sources[k]; }); });
    var t0 = Date.now() - days * 864e5;
    r.acc = (state.accounts || []).filter(function(a) { var c = typeof a.createdAt === "number" ? a.createdAt : Date.parse(a.createdAt || ""); return c && c >= t0; }).length;
    return r;
  }
  var d1 = sum(1), d7 = sum(7), d30 = sum(30);
  var labels = { google: "Google", facebook: "Facebook / Instagram", whatsapp: "WhatsApp", tiktok: "TikTok", lien_article: "Lien d'article partagé", parrainage: "Lien de parrainage", autre_site: "Autre site", direct: "Direct / application" };
  var html = '<div class="glass-card" style="padding:14px;margin-bottom:14px;">';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;"><div style="font-weight:800;font-size:13.5px;"><i class="fa-solid fa-users"></i> Visiteurs du site</div><button class="link-btn" style="font-size:11.5px;" data-action="refresh-visit-stats"><i class="fa-solid fa-rotate"></i></button></div>';
  html += '<div style="font-size:10.5px;color:var(--text-dim);margin:2px 0 10px;">1 visiteur = 1 téléphone ou ordinateur par jour (anonyme).</div>';
  html += '<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;text-align:center;">';
  [["Aujourd'hui", d1], ["7 jours", d7], ["30 jours", d30]].forEach(function(c) {
    html += '<div style="background:var(--bg-body);border-radius:10px;padding:8px 4px;min-width:0;"><div style="font-size:10.5px;color:var(--text-dim);">' + c[0] + '</div><div style="font-weight:800;font-size:17px;">' + c[1].v + '</div><div style="font-size:10px;color:var(--text-dim);line-height:1.3;">' + c[1].g + ' non connectés<br>' + c[1].acc + ' inscriptions</div></div>';
  });
  html += '</div>';
  if (d30.g > 0) html += '<div style="font-size:11.5px;margin-top:8px;">Sur 30 jours : <strong>' + Math.round(100 * d30.acc / Math.max(1, d30.g)) + ' %</strong> des visiteurs non connectés ont créé un compte.</div>';
  var srcKeys = Object.keys(d30.src).sort(function(a, b) { return d30.src[b] - d30.src[a]; });
  if (srcKeys.length) {
    html += '<div style="font-size:11px;font-weight:700;color:var(--text-dim);margin-top:10px;">D\'où viennent-ils ? (30 jours)</div>';
    srcKeys.forEach(function(k) { var pc = Math.round(100 * d30.src[k] / Math.max(1, d30.v)); html += '<div style="display:flex;justify-content:space-between;gap:8px;font-size:11.5px;padding:2px 0;"><span>' + (labels[k] || k) + '</span><span style="font-weight:700;">' + d30.src[k] + ' (' + pc + ' %)</span></div>'; });
  } else if (!rows.length) {
    html += '<div style="font-size:11.5px;color:var(--text-dim);margin-top:8px;">Pas encore de visite comptée — les chiffres apparaissent dès les premières visites après la mise à jour.</div>';
  }
  html += '</div>';
  return html;
}

function maybeRunGlobalStaleProductCheck() {
  // Le travail est fait par le serveur (secure-write) : lui seul a le droit
  // de supprimer l'article d'un autre vendeur et d'enregistrer le rappel.
  // Ce téléphone ne fait que le lui demander (au plus deux fois par jour).
  var last = null;
  try { last = localStorage.getItem(STALE_CHECK_KEY); } catch (e) {}
  if (last && (Date.now() - parseInt(last, 10)) < STALE_CHECK_INTERVAL_MS) return;
  try { localStorage.setItem(STALE_CHECK_KEY, String(Date.now())); } catch (e) {}
  if (!FIREBASE_ENABLED) return;
  fetch(supabaseConfig.url + "/functions/v1/secure-write", { method: "POST", headers: { "Content-Type": "application/json", "Authorization": "Bearer " + supabaseConfig.anonKey }, body: JSON.stringify({ operation: "stale_products_sweep" }) })
    .then(readServerJson)
    .then(function(res) { if (res && res.deleted) pushDebugLog("info", "Articles anciens", "supprimés : " + res.deleted + " · rappels : " + (res.warned || 0)); })
    .catch(function() {});
}

function ensureRelevantOldProductsLoaded() {
  var neededIds = {};
  var now = Date.now();
  for (var bi = 0; bi < state.boosts.length; bi++) {
    var b = state.boosts[bi];
    if (isBoostActive(b) && b.targetType === "product") neededIds[b.targetId] = true;
  }
  if (state.profile) {
    for (var oi = 0; oi < state.orders.length; oi++) {
      var o = state.orders[oi];
      if (o.buyerId !== state.profile.id) continue;
      for (var ii = 0; ii < o.items.length; ii++) neededIds[o.items[ii].productId] = true;
    }
  }
  var existingIds = {};
  for (var pi = 0; pi < state.products.length; pi++) existingIds[state.products[pi].id] = true;
  var missingIds = Object.keys(neededIds).filter(function(id) { return !existingIds[id]; });
  // Un vendeur doit toujours voir la totalité de SES PROPRES articles dans
  // "Mes produits", peu importe leur âge — sans ça, "Mes produits"
  // paraîtrait incomplet, et la vérification d'actualisation/suppression
  // automatique plus bas ne pourrait jamais voir ses vieux articles.
  if (state.profile && (state.profile.role === "vendeur" || state.profile.shopName)) {
    ensureAllSellerOwnProductsLoaded(missingIds);
  } else if (missingIds.length > 0) {
    fetchMissingProductIds(missingIds);
  }
}

function fetchMissingProductIds(missingIds) {
  if (missingIds.length === 0) return;
  sb.from("app_data").select("*").eq("collection", "products").in("id", missingIds)
    .then(function(res) {
      if (res.error || !res.data) { console.error("Échec du chargement des produits boostés/déjà achetés :", res.error); return; }
      res.data.forEach(function(row) { state.products.push(row.data); });
      save();
      if (_splashFinished) render();
    });
}

// Charge TOUS les articles du vendeur connecté (même très vieux) —
// nécessaire pour que "Mes produits" reste complet, et pour que la
// vérification d'actualisation/suppression automatique (voir plus bas)
// puisse voir l'intégralité de son catalogue, pas seulement le lot
// récent déjà chargé pour tout le monde.
function ensureAllSellerOwnProductsLoaded(alsoMissingIds) {
  sb.from("app_data").select("*").eq("collection", "products").eq("data->>sellerId", state.profile.id)
    .then(function(res) {
      if (res.error || !res.data) {
        console.error("Échec du chargement du catalogue complet du vendeur :", res.error);
        fetchMissingProductIds(alsoMissingIds);
        return;
      }
      var existingIds = {};
      for (var pi = 0; pi < state.products.length; pi++) existingIds[state.products[pi].id] = true;
      res.data.forEach(function(row) { if (!existingIds[row.data.id]) { state.products.push(row.data); existingIds[row.data.id] = true; } });
      var stillMissing = alsoMissingIds.filter(function(id) { return !existingIds[id]; });
      save();
      if (_splashFinished) render();
      fetchMissingProductIds(stillMissing);
    });
}

// Appelée quand l'affichage du marché approche de la fin de ce qui est
// déjà chargé localement (défilement infini) — va chercher le lot
// suivant côté serveur, au lieu de supposer à tort que tout est déjà là.
function loadMoreProductsIfNeeded() {
  if (_productsFullyLoaded || window._loadingMoreProducts) return;
  window._loadingMoreProducts = true;
  sb.from("app_data").select("*").eq("collection", "products")
    .order("updated_at", { ascending: false })
    .range(state.products.length, state.products.length + PRODUCTS_BATCH_SIZE - 1)
    .then(function(res) {
      window._loadingMoreProducts = false;
      if (res.error || !res.data) { console.error("Échec du chargement de produits supplémentaires :", res.error); return; }
      var existingIds = {};
      for (var epi = 0; epi < state.products.length; epi++) existingIds[state.products[epi].id] = true;
      res.data.forEach(function(row) { if (!existingIds[row.data.id]) state.products.push(row.data); });
      if (res.data.length < PRODUCTS_BATCH_SIZE) _productsFullyLoaded = true;
      save();
      render();
    });
}

// Recherche : sans ça, chercher un article ne trouverait que parmi ce
// qui est déjà chargé localement, jamais tout le catalogue. Interroge
// directement Supabase, puis fusionne les résultats avec ce qui est
// déjà en mémoire (jamais de doublon, jamais de perte).
var _lastServerSearchTerm = null;
function searchProductsOnServer(term) {
  var trimmed = (term || "").trim();
  if (!trimmed || trimmed === _lastServerSearchTerm || _productsFullyLoaded) return;
  _lastServerSearchTerm = trimmed;
  sb.from("app_data").select("*").eq("collection", "products")
    .ilike("data->>name", "%" + trimmed + "%")
    .limit(100)
    .then(function(res) {
      if (res.error || !res.data) { console.error("Échec de la recherche côté serveur :", res.error); return; }
      var existingIds = {};
      for (var spi = 0; spi < state.products.length; spi++) existingIds[state.products[spi].id] = true;
      var addedAny = false;
      res.data.forEach(function(row) {
        if (!existingIds[row.data.id]) { state.products.push(row.data); addedAny = true; }
      });
      if (addedAny) { save(); render(); }
    });
}

function trySplashFinish() {
  if (_splashFinished) return;
  if (_splashMinTimeDone && _splashAppDataReady) {
    _splashFinished = true;
    // Chaque étape ci-dessous est isolée : si l'une plante, on l'enregistre
    // et on continue — l'écran DOIT s'afficher quoi qu'il arrive. Avant, une
    // seule erreur ici laissait le logo de chargement à l'écran pour toujours.
    var bootStep = function(name, fn) {
      if (window.__bootMark) window.__bootMark("étape : " + name);
      try { fn(); } catch (err) {
        window._bootStepErrors = window._bootStepErrors || [];
        window._bootStepErrors.push(name + " : " + (err && err.message ? err.message : String(err)));
        console.error("Étape de démarrage en erreur (" + name + ") :", err);
        try { pushDebugLog("error", "Étape de démarrage en erreur : " + name, err && err.stack ? String(err.stack).slice(0, 500) : String(err)); } catch (e2) {}
      }
    };
    // Pour les comptes déjà existants (créés avant que le son/la
    // notification n'existent) — pas seulement à l'inscription — sinon
    // ceux-là ne verraient jamais la demande d'autorisation.
    bootStep("notifications", function() {
      if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.PushNotifications) {
        // App Capacitor — Firebase natif, prioritaire sur le Web Push.
        // silent=true : c'est un appel automatique de fond, pas une action
        // demandée par l'utilisateur — aucun toast ne doit apparaître ici.
        subscribeToFcmIfCapacitor(true);
      } else if (state.profile && "Notification" in window && Notification.permission === "default") {
        Notification.requestPermission().then(function(permission) {
          if (permission === "granted") subscribeToPush();
        });
      } else if (state.profile && "Notification" in window && Notification.permission === "granted") {
        // Déjà autorisé (ex: mise à jour de l'app) — on s'assure que
        // l'abonnement push existe bien aussi, pas seulement la permission.
        subscribeToPush();
      }
    });
    bootStep("taux de change", refreshExchangeRatesIfStale);
    bootStep("villes internationales", seedDefaultInternationalCities);
    bootStep("colis en point de retrait", checkStalePickupOrders);
    bootStep("retour de paiement", checkPaymentReturn);
    bootStep("retour LigdiCash", checkLigdicashReturn);
    bootStep("affichage", render);
    bootStep("compteur de visiteurs", function() { setTimeout(trackVisit, 3000); });
    bootStep("nettoyage du journal", function() { (state.debugLog || []).forEach(function(l) { l.message = maskSecrets(l.message); l.detail = maskSecrets(l.detail); }); });
    bootStep("clé de session", function() { setTimeout(function() { ensureFreshSession(); }, 4000); setInterval(function() { ensureFreshSession(); }, 30 * 60 * 1000); });
  }
}

// Taper "#diag" (ou le retirer) à la fin de l'adresse affiche la page de
// diagnostic sans recharger la page — donc sans perdre la connexion.
window.addEventListener("hashchange", function() {
  if (typeof _splashFinished !== "undefined" && _splashFinished) render();
});

// Filet de sécurité : si, pour une raison imprévue, le logo de chargement
// est toujours affiché 15 secondes après le démarrage, on force l'affichage.
setTimeout(function() {
  if (!_splashFinished || document.getElementById("su-splash") || document.querySelector(".splash-screen")) {
    if (!_splashFinished) { _splashMinTimeDone = true; _splashAppDataReady = true; bootDone = true; trySplashFinish(); }
    else { try { render(); } catch (e) { console.error("Affichage forcé en erreur :", e); } }
  }
}, 15000);

setTimeout(function() { _splashMinTimeDone = true; trySplashFinish(); }, 5500);

function bootAppWithLocalData() {
  if (window.__bootMark) window.__bootMark("démarrage des données");
  if (!FIREBASE_ENABLED) {
    // Mode local (test) : state est déjà prêt (chargé depuis localStorage ou
    // valeurs par défaut avec le catalogue de démo).
    _splashAppDataReady = true;
    trySplashFinish();
  } else {
    bootDone = false;
    var LAST_SYNC_KEY = "gems_last_sync_v2";
    var lastSyncAt = localStorage.getItem(LAST_SYNC_KEY);
    // Il faut les DEUX pour vraiment sauter la synchro complète — un
    // "ou" laissait passer un cache incomplet (ex: comptes présents mais
    // produits vides, vu sur le diagnostic), qui se contentait alors
    // d'une synchro incrémentale ne redemandant que les changements
    // récents, sans jamais combler ce qui manquait depuis le début.
    var hasCachedData = state.products.length > 0 && state.accounts.length > 0;

    // Avec des données déjà en cache local (visite précédente), l'app
    // démarre IMMÉDIATEMENT dessus — pas besoin d'attendre le réseau pour
    // afficher quelque chose. La synchronisation se fait ensuite en fond,
    // et ne retélécharge que ce qui a changé depuis la dernière visite,
    // au lieu de tout retélécharger à chaque lancement.
    if (hasCachedData && lastSyncAt) {
      _splashAppDataReady = true;
      trySplashFinish();
      bootDone = true;
    }

    // Filet de sécurité : si Supabase ne répond jamais (règles de sécurité
    // mal configurées qui bloquent silencieusement, table pas encore créée),
    // l'app démarre quand même après quelques secondes avec ce qui est déjà
    // en mémoire/localStorage, plutôt que de rester bloquée sur l'écran de
    // chargement.
    setTimeout(function() {
      if (!bootDone) {
        bootDone = true;
        _splashAppDataReady = true;
        console.warn("Chargement Supabase : délai dépassé, démarrage avec les données disponibles.");
        trySplashFinish();
      }
    }, 8000);

    // Synchronisation en fond : incrémentale (seulement les lignes modifiées
    // depuis la dernière visite) si on a déjà un cache datant de moins de
    // 24h, sinon un chargement complet — pour se remettre à niveau si
    // l'appareil est resté longtemps sans se connecter (ex: suppressions
    // manquées pendant l'absence).
    var ONE_DAY_MS = 24 * 60 * 60 * 1000;
    // IMPORTANT : si le cache local est vide (state.products/accounts
    // vides — ex : premier chargement d'IndexedDB, migration pas encore
    // terminée), on force un chargement COMPLET même si "lastSyncAt" est
    // récent — sinon l'app ne redemande que les changements récents à
    // Supabase alors qu'elle n'a rien en mémoire pour les compléter, et le
    // marché reste vide.
    var needsFullSync = !lastSyncAt || !hasCachedData || (Date.now() - new Date(lastSyncAt).getTime()) > ONE_DAY_MS;
    // "products" est désormais chargé à part, par lots (voir
    // syncProductsInitialBatch) — de très loin la plus grosse collection
    // à grande échelle, elle ne doit plus jamais être téléchargée en bloc
    // avec tout le reste pour chaque visiteur.

    var PAGE_SIZE = 900;
    function fetchAllSyncPages(offset, accumulated) {
      var pageQuery = sb.from("app_data").select("*").not("collection", "in", "(products,orders,notifications,conversations,visitIds,visitStats)").range(offset, offset + PAGE_SIZE - 1);
      if (!needsFullSync) pageQuery = pageQuery.gt("updated_at", lastSyncAt);
      return pageQuery.then(function(res) {
        if (res.error) return res;
        var combined = accumulated.concat(res.data || []);
        // Tant qu'une page revient pleine, il peut encore en rester —
        // on continue. Sans cette boucle, une seule requête pouvait être
        // silencieusement tronquée par la limite par défaut de Supabase
        // dès que le total (commandes + comptes + tout le reste
        // confondus) dépassait cette limite — et selon l'ordre renvoyé
        // par la base, ce sont parfois les comptes qui manquaient à
        // l'arrivée, pas les autres collections.
        if (res.data && res.data.length === PAGE_SIZE) {
          return fetchAllSyncPages(offset + PAGE_SIZE, combined);
        }
        return { error: null, data: combined };
      });
    }

    fetchAllSyncPages(0, []).then(function(res) {
      if (res.error) {
        console.error("Erreur de connexion Supabase :", res.error);
        if (!hasCachedData) showToast(t("toast_supabase_unreachable"));
      } else {
        if (needsFullSync) {
          // Chargement complet : on repart d'une table vide par collection,
          // comme avant — remet aussi à niveau les suppressions manquées.
          var byCollection = {};
          SHARED_KEYS.forEach(function(name) { byCollection[name] = []; });
          var publicProfileRows = [];
          res.data.forEach(function(row) {
            if (row.collection === "publicProfiles") { publicProfileRows.push(row.data); return; }
            if (byCollection[row.collection]) byCollection[row.collection].push(row.data);
          });
          // Comptes : liste complète si la base la donne encore (avant la mise
          // en place), sinon versions publiques + ses propres comptes complets.
          var accountsFromPublic = byCollection.accounts.length === 0 && publicProfileRows.length > 0;
          // Les articles ne font PAS partie de cette requête (chargés à part,
          // par lots — voir syncProductsInitialBatch). Remplacer
          // state.products par la liste vide reçue ici effaçait les articles
          // déjà arrivés : marché vide pour tout nouveau visiteur, et
          // "je ne vois que mes propres articles" après plus de 24 h.
          SHARED_KEYS.forEach(function(name) { if (name === "products" || PERSONAL_KEYS.indexOf(name) !== -1 || PRIVATE_KEYS.indexOf(name) !== -1 || (name === "accounts" && accountsFromPublic)) return; state[name] = byCollection[name]; });
          if (accountsFromPublic) applyPublicProfiles(publicProfileRows, true);
        } else {
          // Incrémental : on met seulement à jour/ajoute les lignes reçues,
          // le reste du cache local reste tel quel.
          res.data.forEach(function(row) {
            if (row.collection === "publicProfiles") { applyPublicProfiles([row.data], false); return; }
            if (SHARED_KEYS.indexOf(row.collection) === -1) return;
            var list = state[row.collection];
            var idx = list.findIndex(function(item) { return item.id === row.data.id; });
            if (idx === -1) list.push(row.data); else list[idx] = row.data;
          });
        }
        localStorage.setItem(LAST_SYNC_KEY, computeNextSyncWatermark(res.data, lastSyncAt));
        syncPersonalCollections();
        refreshProfileFromAccounts();
        // Sécurité : le contenu (items/subtotal/total) arrive séparément
        // désormais (voir fetchMyOrderDetails) — en attendant qu'il
        // arrive, on s'assure qu'aucune commande n'a ces champs
        // complètement absents, pour qu'un .length/.map/money() exécuté
        // entre-temps ne fasse jamais planter l'écran ni afficher "NaN"
        // (juste "0" un court instant).
        for (var oi = 0; oi < state.orders.length; oi++) {
          if (!Array.isArray(state.orders[oi].items)) state.orders[oi].items = [];
          if (typeof state.orders[oi].subtotal !== "number") state.orders[oi].subtotal = 0;
          if (typeof state.orders[oi].total !== "number") state.orders[oi].total = 0;
        }
        save();
        pushDebugLog("info", "Synchronisation générale terminée", "lignes reçues au total=" + res.data.length + " · comptes en mémoire après=" + state.accounts.length + " · pages=" + Math.ceil(res.data.length / PAGE_SIZE));
        if (state.profile) { fetchMyOrderContacts(); fetchMyOrderDetails(); }
      }
      _generalSyncReady = true;
      maybeSignalBootReady();
    });

    // Chargement des produits, à part et par lots — voir la note plus
    // haut sur pourquoi cette collection ne fait plus partie de la
    // synchronisation générale. Lancé en parallèle de la requête
    // ci-dessus (pas l'un après l'autre), pour ne pas ralentir le
    // démarrage.
    syncProductsInitialBatch();

    // Écoute en temps réel : chaque changement (venant de cet appareil ou
    // d'un autre) met à jour le bon tableau et redessine l'écran.
    sb.channel("app_data_changes")
      .on("postgres_changes", { event: "*", schema: "public", table: "app_data" }, function(payload) {
        var row = payload.new && Object.keys(payload.new).length ? payload.new : payload.old;
        if (row && row.collection === "publicProfiles") {
          if (payload.eventType === "DELETE") { state.accounts = (state.accounts || []).filter(function(a) { return a.id !== row.id || keepsPrivateFields(a.id); }); }
          else if (row.data) { applyPublicProfiles([row.data], false); refreshProfileFromAccounts(); }
          save(); renderOrDefer(); return;
        }
        if (!row || !byCollectionExists(row.collection)) return;
        // Commandes, notifications et conversations : seulement celles qui
        // concernent ce téléphone (sauf Admin / agent de sourcing).
        if (PERSONAL_KEYS.indexOf(row.collection) !== -1 && payload.eventType !== "DELETE" && !isPersonalRowForMe(row.collection, row.data)) return;
        if (row.collection === "orders" && row.data) normalizeOrderDoc(row.data);
        var list = state[row.collection] || [];
        var changed = true;
        var previousItem = null;
        var isNewInsert = false;
        if (payload.eventType === "DELETE") {
          var beforeLen = list.length;
          list = list.filter(function(item) { return item.id !== row.id; });
          changed = list.length !== beforeLen;
        } else {
          var idx = list.findIndex(function(item) { return item.id === row.data.id; });
          if (idx === -1) {
            isNewInsert = true;
            // Une nouvelle commande reçue en direct va en tête de liste
            // (la plus récente en premier), pas en bas.
            if (row.collection === "orders") list.unshift(row.data); else list.push(row.data);
          } else {
            previousItem = list[idx];
            // Écho de notre propre écriture (l'appareil reçoit en retour ce
            // qu'il vient d'envoyer) : si rien n'a réellement changé, on
            // évite un second redessin complet de l'écran, source du
            // "clic fantôme" — l'écran qui disparaît puis réapparaît.
            if (JSON.stringify(list[idx]) === JSON.stringify(row.data)) {
              changed = false;
            } else {
              list[idx] = row.data;
            }
          }
        }
        state[row.collection] = list;
        if (row.collection === "accounts") refreshProfileFromAccounts();
        // Une commande qui vient d'arriver (ou de changer) par le temps
        // réel n'a que ses métadonnées (statut, qui est concerné...) —
        // son contenu (articles, montants) vit à part désormais (voir
        // order-write/order-contact). On va le chercher tout de suite
        // si cette commande nous concerne, sans attendre le prochain
        // cycle de synchronisation complet.
        if (row.collection === "orders" && changed && state.profile) {
          var newOrder = row.data;
          var newOrderHadNoItems = !Array.isArray(newOrder.items);
          if (newOrderHadNoItems) newOrder.items = [];
          var concernsMe = newOrder.buyerId === state.profile.id
            || (Array.isArray(newOrder.sellerIds) && newOrder.sellerIds.indexOf(state.profile.id) !== -1)
            || newOrder.livreurId === state.profile.id
            || newOrder.relaisShopId === state.profile.id;
          if (concernsMe && newOrderHadNoItems) fetchMyOrderDetails([newOrder.id]);
        }
        // Son + notification système — uniquement pour du contenu qui nous
        // concerne VRAIMENT (jamais nos propres actions), et jamais pendant
        // le chargement initial (tout l'historique arriverait d'un coup).
        if (changed && _splashFinished && state.profile) {
          notifyIfRelevant(row.collection, row.data, previousItem, isNewInsert);
        }
        // Un nouvel article, une modification de prix ou de stock ARRIVE
        // en permanence de la part de N'IMPORTE QUEL vendeur, à tout
        // moment — redessiner le marché en entier à chaque fois le
        // réordonnait sous les doigts de la personne en train de le
        // parcourir, donnant l'impression que l'écran "tirait" tout seul
        // pendant le défilement. La donnée est déjà à jour ci-dessus ;
        // l'affichage, lui, se rafraîchira au prochain rendu naturel
        // (un like, un filtre, la suite du défilement...) plutôt que
        // de perturber celui en cours.
        var isDisruptiveMarketUpdate = row.collection === "products" && state.view === "market";
        if (changed && _splashFinished && !isDisruptiveMarketUpdate) renderOrDefer(); // mise à jour en temps réel après le démarrage — repoussée si on tape dans une fenêtre
      })
      .subscribe();

    function byCollectionExists(name) { return SHARED_KEYS.indexOf(name) !== -1; }
  }
}

// Charge l'état local (IndexedDB, avec repli localStorage pour la
// transition) — ASYNCHRONE, donc tout ce qui dépend de "state" déjà
// rempli doit attendre que cette étape se termine avant de continuer.
// Filet de sécurité : si IndexedDB ne répond jamais (bloqué par le
// navigateur en navigation privée, ou par ce mode d'ouverture de fichier
// sur certains appareils), l'app démarre quand même après un court délai
// plutôt que de rester bloquée indéfiniment sur l'écran de démarrage.
var _localLoadSettled = false;
setTimeout(function() {
  if (_localLoadSettled) return;
  _localLoadSettled = true;
  console.warn("Chargement du stockage local : délai dépassé, démarrage avec les valeurs par défaut.");
  bootAppWithLocalData();
}, 2500);

loadStateAsync().then(function(loaded) {
  if (_localLoadSettled) return; // le filet de sécurité a déjà démarré l'app, ne pas redémarrer par-dessus
  _localLoadSettled = true;
  if (loaded) state = loaded;
  bootAppWithLocalData();
}).catch(function(e) {
  if (_localLoadSettled) return;
  _localLoadSettled = true;
  console.error("Chargement de l'état local impossible :", e);
  bootAppWithLocalData(); // on démarre quand même, avec les valeurs par défaut
});

// ---------- Petit rappel périodique pour télécharger l'app (web uniquement) ----------
// Jamais dans l'app installée elle-même (vérifié à chaque déclenchement,
// pas seulement au démarrage, au cas où Capacitor mettrait un peu de
// temps à s'annoncer). Utilise sessionStorage (pas localStorage) : le
// compteur repart donc naturellement à zéro à chaque fois que la
// personne revient sur le site après avoir été absente un moment —
// pas besoin de "se reconnecter" avec un mot de passe pour ça.
var DOWNLOAD_NUDGE_FIRST_DELAY_MS = 10 * 1000; // le tout premier, rapide : 10 secondes après l'ouverture
var DOWNLOAD_NUDGE_INTERVAL_MS = 7 * 60 * 1000; // les suivants, plus espacés : environ toutes les 7 minutes
var DOWNLOAD_NUDGE_MAX_SHOWS = 3;
function triggerDownloadNudgeIfAllowed() {
  var isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  if (isNative) return;
  var shownCount = parseInt(sessionStorage.getItem("sounsouni_dl_nudge_count") || "0", 10);
  if (shownCount >= DOWNLOAD_NUDGE_MAX_SHOWS) return;
  if (state.showDownloadNudge) return; // déjà affiché, ne pas empiler
  if (isGuestBrowsingMode()) return; // page visiteur : proposition séparée, après le 1er ajout au panier
  sessionStorage.setItem("sounsouni_dl_nudge_count", String(shownCount + 1));
  state.showDownloadNudge = true;
  render();
}
function scheduleDownloadNudge() {
  setTimeout(triggerDownloadNudgeIfAllowed, DOWNLOAD_NUDGE_FIRST_DELAY_MS);
  setInterval(triggerDownloadNudgeIfAllowed, DOWNLOAD_NUDGE_INTERVAL_MS);
}
scheduleDownloadNudge();

// Décide si un changement reçu du serveur mérite un bip + une notification
// système sur CET appareil — c'est-à-dire : ça concerne le compte
// actuellement connecté ici, et ce n'est pas nous-mêmes qui venons de le
// provoquer.
function notifyIfRelevant(collection, data, previousItem, isNewInsert) {
  var me = state.profile.id;
  // Comptes liés (même numéro) : un message reçu par sa boutique doit
  // alerter même si l'app est ouverte sur son compte acheteur, et inversement.
  var myLinked = (typeof getLinkedAccountIds === "function" ? getLinkedAccountIds() : [me]);
  var isMine = function(id) { return !!id && (id === me || myLinked.indexOf(id) !== -1); };
  if (collection === "notifications") {
    if (isNewInsert && isMine(data.userId)) {
      playNotificationSound();
      showSystemNotification(data.message);
    }
    return;
  }
  if (collection === "conversations") {
    if (!previousItem) return; // une conversation qu'on découvre à l'instant n'est pas "un nouveau message"
    // Conversation avec soi-même (les deux côtés sont à soi) : jamais de son,
    // c'est forcément un message qu'on vient d'envoyer.
    if (isMine(data.sellerId) && isMine(data.buyerId)) return;
    if (isMine(data.sellerId) && (data.unreadForSeller || 0) > (previousItem.unreadForSeller || 0)) {
      playNotificationSound();
      showSystemNotification("💬 " + (data.lastMessage || "Nouveau message"));
    } else if (isMine(data.buyerId) && (data.unreadForBuyer || 0) > (previousItem.unreadForBuyer || 0)) {
      playNotificationSound();
      showSystemNotification("💬 " + (data.lastMessage || "Nouveau message"));
    }
    return;
  }
  if (collection === "adminConversations") {
    if (!previousItem) return;
    if (data.accountId === me && (data.unreadForUser || 0) > (previousItem.unreadForUser || 0)) {
      playNotificationSound();
      showSystemNotification("📢 " + (data.lastMessage || "Message de l'administration"));
    } else if (state.adminUnlocked && (data.unreadForAdmin || 0) > (previousItem.unreadForAdmin || 0)) {
      playNotificationSound();
      showSystemNotification("💬 " + (data.lastMessage || "Nouveau message"));
    }
  }
}
